const e="https://www.churchofjesuschrist.org/study/scriptures",n=JSON.parse('[{"id":"doctrine-and-covenants","title":"Lehre und Bündnisse","englishTitle":"Doctrine and Covenants","volume":"Doctrine and Covenants","volumeId":"dc-testament","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Horcht auf, o ihr Volk meiner Kirche, spricht die Stimme dessen, der in der Höhe wohnt und dessen Augen auf allen Menschen sind; ja, wahrlich, ich sage: Horcht auf, ihr Völker von fern her, und die ihr auf den Inseln des Meeres seid, hört miteinander zu."},{"verse":2,"text":"Denn wahrlich, die Stimme des Herrn ergeht an alle Menschen, und es gibt keinen, der entrinnt; und es gibt kein Auge, das nicht sehen wird, auch kein Ohr, das nicht hören wird, auch kein Herz, das nicht durchdrungen werden wird."},{"verse":3,"text":"Und die Widersetzlichen werden von viel Leid durchbohrt werden, denn ihre Übeltaten werden von den Hausdächern geredet, und ihre geheimen Taten werden offenbart werden."},{"verse":4,"text":"Und die Stimme der Warnung wird an alles Volk ergehen, durch den Mund meiner Jünger, die ich in diesen letzten Tagen erwählt habe."},{"verse":5,"text":"Und sie werden ausgehen, und keiner wird sie aufhalten, denn ich, der Herr, habe ihnen geboten."},{"verse":6,"text":"Siehe, dies ist meine Vollmacht und die Vollmacht an meine Diener und mein Geleitwort für das Buch meiner Gebote, die ich ihnen gegeben habe, dass sie diese für euch, o Bewohner der Erde, veröffentlichen sollen."},{"verse":7,"text":"Darum fürchtet euch und zittert, o ihr Völker, denn was ich, der Herr, in ihnen verfügt habe, wird sich erfüllen."},{"verse":8,"text":"Und wahrlich, ich sage euch: Denen, die ausgehen und den Bewohnern der Erde diese Nachricht bringen, denen ist die Macht gegeben, die Ungläubigen und Widersetzlichen sowohl auf Erden als auch im Himmel zu siegeln,"},{"verse":9,"text":"ja, wahrlich, sie für den Tag zu versiegeln, da der Grimm Gottes ohne Maß über die Schlechten ausgegossen werden wird –"},{"verse":10,"text":"für den Tag, da der Herr kommen wird, um jedem Menschen gemäß seinem Werk zu vergelten und jedem Menschen mit dem Maß zuzumessen, womit dieser seinem Mitmenschen zugemessen hat."},{"verse":11,"text":"Darum ergeht die Stimme des Herrn an die Enden der Erde, damit alle, die hören wollen, hören mögen:"},{"verse":12,"text":"Macht euch bereit, macht euch bereit für das, was kommen wird, denn der Herr ist nahe,"},{"verse":13,"text":"und der Zorn des Herrn ist entflammt, und sein Schwert im Himmel ist eingetaucht, und es wird auf die Bewohner der Erde fallen."},{"verse":14,"text":"Und der Arm des Herrn wird sich offenbaren; und der Tag kommt, da diejenigen, die nicht auf die Stimme des Herrn hören wollen, auch nicht auf die Stimme seiner Diener, auch nicht den Worten der Propheten und Apostel Beachtung schenken wollen, aus dem Volk ausgeschlossen werden sollen;"},{"verse":15,"text":"denn sie sind von meinen Verordnungen abgewichen und haben meinen immerwährenden Bund gebrochen;"},{"verse":16,"text":"sie suchen nicht den Herrn, um seine Rechtschaffenheit aufzurichten, sondern jedermann wandelt auf seinem eigenen Weg und nach dem Abbild seines eigenen Gottes, dessen Abbild dem der Welt gleicht und dessen Wesen das eines Götzen ist, der alt wird und in Babylon zugrunde gehen wird, ja, Babylon, der Großen, die fallen wird."},{"verse":17,"text":"Darum habe ich, der Herr, der das Unheil kennt, das über die Bewohner der Erde kommen soll, meinen Diener Joseph Smith Jr. aufgerufen und aus dem Himmel zu ihm gesprochen und ihm Gebote gegeben,"},{"verse":18,"text":"und auch anderen Gebote gegeben, dass sie dies der Welt verkündigen; und dies alles, damit sich erfülle, was die Propheten geschrieben haben –"},{"verse":19,"text":"das Schwache der Welt wird hervorkommen und die Mächtigen und Starken niederbrechen, damit der Mensch nicht seinem Mitmenschen rate, auch nicht auf den Arm des Fleisches vertraue –"},{"verse":20,"text":"sondern damit jedermann im Namen Gottes, des Herrn, ja, des Erretters der Welt, sprechen könne;"},{"verse":21,"text":"damit auch der Glaube auf Erden zunehme;"},{"verse":22,"text":"damit mein immerwährender Bund aufgerichtet werde;"},{"verse":23,"text":"damit die Fülle meines Evangeliums durch die Schwachen und die Einfachen bis an die Enden der Welt und vor Königen und Herrschern verkündigt werde."},{"verse":24,"text":"Siehe, ich bin Gott und habe es gesagt; diese Gebote sind von mir und sind meinen Dienern in ihrer Schwachheit, nach der Weise ihrer Sprache gegeben worden, damit sie Verständnis erlangen können,"},{"verse":25,"text":"und, insoweit sie geirrt haben, es kundgetan werden könne,"},{"verse":26,"text":"und, insoweit sie nach Weisheit getrachtet haben, sie unterwiesen werden können,"},{"verse":27,"text":"und, insoweit sie gesündigt haben, sie gezüchtigt werden können, damit sie umkehren können,"},{"verse":28,"text":"und, insoweit sie demütig waren, sie stark gemacht und aus der Höhe gesegnet werden und von Zeit zu Zeit Erkenntnis empfangen können"},{"verse":29,"text":"und damit, nachdem er die Aufzeichnungen der Nephiten empfangen hat, ja, nämlich mein Diener Joseph Smith Jr., er die Macht habe, mittels der Gnade Gottes, durch die Macht Gottes, das Buch Mormon zu übersetzen,"},{"verse":30,"text":"und auch, damit diejenigen, denen diese Gebote gegeben worden sind, die Macht haben mögen, für diese Kirche die Grundlage zu legen und sie aus dem Dunkel und aus der Finsternis hervorzubringen, die einzige wahre und lebendige Kirche auf der ganzen Erde, an der ich, der Herr, Wohlgefallen habe, wobei ich zur Kirche insgesamt spreche und nicht zu dem Einzelnen –"},{"verse":31,"text":"denn ich, der Herr, kann nicht mit dem geringsten Maß von Billigung auf Sünde blicken;"},{"verse":32,"text":"doch wer umkehrt und die Gebote des Herrn tut, dem wird vergeben werden,"},{"verse":33,"text":"und wer nicht umkehrt, von dem wird selbst das Licht genommen werden, das er empfangen hat; denn mein Geist wird sich nicht immer mit dem Menschen abmühen, spricht der Herr der Heerscharen."},{"verse":34,"text":"Und weiter, wahrlich, ich sage euch, o Bewohner der Erde: Ich, der Herr, bin willens, dies alles allem Fleische kundzutun,"},{"verse":35,"text":"denn ich sehe nicht auf die Person und will, dass alle Menschen wissen, dass der Tag schnell kommt; die Stunde ist noch nicht, aber steht nahe bevor, da der Frieden von der Erde genommen werden wird und der Teufel Macht über sein eigenes Herrschaftsgebiet haben wird."},{"verse":36,"text":"Und ebenso wird der Herr über seine Heiligen Macht haben und wird in ihrer Mitte regieren und wird zum Gericht herniederkommen auf Idumäa oder die Welt."},{"verse":37,"text":"Forscht in diesen Geboten, denn sie sind wahr und treu, und die Prophezeiungen und Verheißungen, die darin sind, werden sich alle erfüllen."},{"verse":38,"text":"Was ich, der Herr, gesagt habe, das habe ich gesagt, und ich entschuldige mich nicht; und mögen auch die Himmel und die Erde vergehen, mein Wort wird nicht vergehen, sondern wird sich gänzlich erfüllen, sei es durch meine eigene Stimme oder durch die Stimme meiner Diener, das ist dasselbe."},{"verse":39,"text":"Denn siehe, ja siehe, der Herr ist Gott, und der Geist gibt Zeugnis, und das Zeugnis ist wahr, und die Wahrheit verbleibt für immer und immer. Amen."}]},{"chapter":2,"verses":[{"verse":1,"text":"Siehe, ich werde euch das Priestertum durch die Hand des Propheten Elija offenbaren, ehe der große und schreckliche Tag des Herrn kommt."},{"verse":2,"text":"Und er wird die Verheißungen, die den Vätern gemacht worden sind, den Kindern ins Herz pflanzen, und das Herz der Kinder wird sich ihren Vätern zuwenden."},{"verse":3,"text":"Wenn es nicht so wäre, würde die ganze Erde bei seinem Kommen völlig verwüstet werden."}]},{"chapter":3,"verses":[{"verse":1,"text":"Die Werke und die Pläne und die Absichten Gottes lassen sich nicht vereiteln, auch lassen sie sich nicht zunichtemachen."},{"verse":2,"text":"Denn Gott wandelt nicht auf krummen Pfaden, auch wendet er sich weder zur rechten Hand noch zur linken, auch weicht er nicht von dem ab, was er gesprochen hat; darum sind seine Pfade gerade, und seine Bahn ist eine ewige Runde."},{"verse":3,"text":"Denkt daran, denkt daran, dass es nicht das Werk Gottes ist, das vereitelt wird, sondern das Werk der Menschen;"},{"verse":4,"text":"denn ein Mensch mag zwar viele Offenbarungen haben und die Macht haben, viele mächtige Werke zu tun, aber wenn er mit seiner eigenen Stärke prahlt und die Ratschläge Gottes für nichts achtet und dem Gebot seines eigenen Willens und seiner fleischlichen Gelüste folgt, muss er fallen und die Vergeltung eines gerechten Gottes über sich bringen."},{"verse":5,"text":"Siehe, dir ist dies alles anvertraut worden, doch wie streng waren deine Gebote; und denke auch an die Verheißungen, die dir gemacht worden sind, sofern du sie nicht übertreten würdest."},{"verse":6,"text":"Und siehe, wie oft hast du die Gebote und die Gesetze Gottes übertreten und hast dich weiterhin von Menschen überreden lassen."},{"verse":7,"text":"Denn siehe, du hättest die Menschen nicht mehr fürchten sollen als Gott. Wenn auch die Menschen die Ratschläge Gottes für nichts achten und seine Worte geringschätzen,"},{"verse":8,"text":"so hättest du doch treu sein sollen; dann hätte er seinen Arm ausgestreckt und dich gegen all die feurigen Pfeile des Widersachers gestärkt; und er hätte dir in allen Zeiten der Beunruhigung beigestanden."},{"verse":9,"text":"Siehe, du bist Joseph, und du wurdest erwählt, das Werk des Herrn zu verrichten, aber der Übertretung wegen, wenn du nicht achtgibst, wirst du fallen."},{"verse":10,"text":"Doch denke daran, Gott ist barmherzig; darum kehre um von dem, was du getan hast, was gegen das Gebot ist, das ich dir gegeben habe, dann bist du noch immer erwählt und bist wieder zum Werk berufen;"},{"verse":11,"text":"tust du es aber nicht, so wirst du dir selbst überlassen werden und so werden wie andere Menschen und keine Gabe mehr haben."},{"verse":12,"text":"Und als du das weitergabst, zu dessen Übersetzung Gott dir Einsicht und Macht gegeben hatte, hast du das, was heilig ist, in die Hände eines schlechten Mannes weitergegeben,"},{"verse":13,"text":"der die Ratschläge Gottes für nichts achtete und die heiligsten, vor Gott gegebenen Versprechen brach und sich auf sein eigenes Urteil verließ und mit seiner eigenen Weisheit prahlte."},{"verse":14,"text":"Und aus diesem Grund hast du deine Vorrechte für eine Zeit lang verloren –"},{"verse":15,"text":"denn du hast zugelassen, dass der Rat dessen, der dich leitet, von Anfang an mit Füßen getreten wurde."},{"verse":16,"text":"Doch mein Werk wird vorangehen, denn wie das Wissen um einen Erretter an die Welt gelangt ist, nämlich durch das Zeugnis der Juden, so wird das Wissen um einen Erretter auch an mein Volk gelangen –"},{"verse":17,"text":"und an die Nephiten und die Jakobiten und die Josephiten und die Zoramiten, nämlich durch das Zeugnis ihrer Väter –,"},{"verse":18,"text":"und dieses Zeugnis wird den Lamaniten und den Lemueliten und den Ischmaeliten zur Kenntnis kommen, die in Unglauben verfallen sind wegen des Übeltuns ihrer Väter, welchen es der Herr zugelassen hat, dass sie ihre Brüder, die Nephiten, wegen deren Übeltaten und deren Gräuel vernichteten."},{"verse":19,"text":"Und zu genau diesem Zweck sind die Platten bewahrt worden, auf denen diese Aufzeichnungen enthalten sind – dass die Verheißungen des Herrn, die er seinem Volk gegeben hat, in Erfüllung gehen"},{"verse":20,"text":"und dass die Lamaniten Kenntnis erhalten von ihren Vätern und dass sie von den Verheißungen des Herrn wissen und dass sie das Evangelium glauben und sich auf die Verdienste Jesu Christi verlassen und durch den Glauben an seinen Namen verherrlicht werden und dass sie, indem sie umkehren, errettet werden mögen. Amen."}]},{"chapter":4,"verses":[{"verse":1,"text":"Nun siehe, ein wunderbares Werk ist im Begriff, unter den Menschenkindern hervorzukommen."},{"verse":2,"text":"Nun also, o ihr, die ihr euch aufmacht, Gott zu dienen: Seht zu, dass ihr ihm mit eurem ganzen Herzen, aller Macht, ganzem Sinn und aller Kraft dient, damit ihr am letzten Tag schuldlos vor Gott stehen mögt."},{"verse":3,"text":"Darum, wenn ihr den Wunsch habt, Gott zu dienen, seid ihr zu dem Werk berufen;"},{"verse":4,"text":"denn siehe, das Feld ist schon weiß, zur Ernte bereit; und siehe, wer seine Sichel mit aller Macht einschlägt, der legt einen Vorrat an, sodass er nicht zugrunde geht, sondern seiner Seele die Errettung bringt;"},{"verse":5,"text":"und Glaube, Hoffnung, Nächstenliebe und Liebe, das Auge nur auf die Herrlichkeit Gottes gerichtet, befähigen ihn für das Werk."},{"verse":6,"text":"Denkt immer an Glauben, Tugend, Erkenntnis, Mäßigung, Geduld, brüderliches Wohlwollen, Gottesfurcht, Nächstenliebe, Demut, Eifer."},{"verse":7,"text":"Bittet, und ihr werdet empfangen; klopfet an, und es wird euch aufgetan werden. Amen."}]},{"chapter":5,"verses":[{"verse":1,"text":"Siehe, ich sage dir: Da mein Diener Martin Harris von meiner Hand ein Zeugnis begehrt hat, dass du, mein Diener Joseph Smith Jr., die Platten hast, von denen du bezeugt und Zeugnis abgelegt hast, du habest von mir empfangen,"},{"verse":2,"text":"und nun siehe, dies sollst du ihm sagen: Er, der zu dir geredet hat, der hat dir gesagt: Ich, der Herr, bin Gott und habe diese Dinge dir, meinem Diener Joseph Smith Jr., gegeben und habe dir geboten, als Zeuge dieser Dinge dazustehen;"},{"verse":3,"text":"und ich habe dich einen Bund mit mir eingehen lassen, dass du sie nicht herzeigen sollst außer den Personen, die ich dir geboten habe; und du hast keine Macht über sie, außer ich gewähre es dir."},{"verse":4,"text":"Und du hast die Gabe, die Platten zu übersetzen, und das ist die erste Gabe, die ich dir verliehen habe; und ich habe dir geboten, auf keine andere Gabe Anspruch zu erheben, bis meine Absicht hierin erreicht ist; denn ich werde dir keine andere Gabe gewähren, bis dieses abgeschlossen ist."},{"verse":5,"text":"Wahrlich, ich sage dir: Weh wird über die Bewohner der Erde kommen, wenn sie nicht auf meine Worte hören,"},{"verse":6,"text":"denn hernach wirst du ordiniert werden und hingehen und den Menschenkindern meine Worte überbringen."},{"verse":7,"text":"Siehe, wenn sie meinen Worten nicht glauben, würden sie dir nicht glauben, mein Diener Joseph, wenn es möglich wäre, dass du ihnen alle diese Dinge zeigtest, die ich dir überantwortet habe."},{"verse":8,"text":"O diese ungläubige und halsstarrige Generation – mein Zorn ist gegen sie entflammt."},{"verse":9,"text":"Siehe, wahrlich, ich sage dir: Ich habe diese Dinge, die ich dir, mein Diener Joseph, anvertraut habe, aus meiner weisen Absicht zurückbehalten, und diese wird künftigen Generationen kundgetan werden;"},{"verse":10,"text":"aber diese Generation wird mein Wort durch dich bekommen,"},{"verse":11,"text":"und außer deinem Zeugnis noch das Zeugnis von drei meiner Diener, die ich berufen und ordinieren werde und denen ich diese Dinge zeigen werde, und sie werden mit meinen Worten, die durch dich gegeben werden, ausgehen."},{"verse":12,"text":"Ja, sie werden mit Bestimmtheit wissen, dass diese Dinge wahr sind, denn vom Himmel werde ich es ihnen verkünden."},{"verse":13,"text":"Ich werde ihnen Macht geben, damit sie diese Dinge so sehen und erblicken können, wie sie sind;"},{"verse":14,"text":"und keinem anderen werde ich diese Macht geben, ebendasselbe Zeugnis in dieser Generation zu empfangen, nämlich am Anfang der Entstehung meiner Kirche und ihres Hervorkommens aus der Wildnis – klar wie der Mond und schön wie die Sonne und schrecklich wie ein Heer mit Bannern."},{"verse":15,"text":"Und das Zeugnis von drei Zeugen für mein Wort werde ich hinaussenden."},{"verse":16,"text":"Und siehe, wer auch immer an meine Worte glaubt, den werde ich mit der Kundgebung meines Geistes besuchen; und sie werden aus mir geboren werden, nämlich aus Wasser und aus dem Geist –"},{"verse":17,"text":"und ihr müsst noch eine kleine Weile warten, denn ihr seid noch nicht ordiniert –,"},{"verse":18,"text":"und ihr Zeugnis wird auch hinausgehen, um diese Generation schuldig zu sprechen, wenn sie ihr Herz gegen sie verhärten;"},{"verse":19,"text":"denn eine verheerende Geißel wird unter den Bewohnern der Erde umgehen und wird auch weiterhin von Zeit zu Zeit ausgegossen werden, wenn sie nicht umkehren, bis die Erde leer ist und ihre Bewohner durch den Glanz meines Kommens hinweggerafft und völlig vernichtet sind."},{"verse":20,"text":"Siehe, ich sage dir dies alles, so wie ich auch dem Volk von der Zerstörung Jerusalems gesagt habe; und mein Wort wird sich diesmal ebenso bewahrheiten, wie es sich bisher bewahrheitet hat."},{"verse":21,"text":"Und nun gebiete ich dir, mein Diener Joseph, umzukehren und noch untadeliger vor mir zu wandeln und menschlichen Überredungen nicht mehr nachzugeben;"},{"verse":22,"text":"und du sollst fest sein im Halten der Gebote, womit ich dir geboten habe; und wenn du das tust, siehe, dann gewähre ich dir ewiges Leben, selbst wenn du getötet werden solltest."},{"verse":23,"text":"Und nun spreche ich wieder zu dir, mein Diener Joseph, in Bezug auf den Mann, der das Zeugnis begehrt –"},{"verse":24,"text":"siehe, ich sage ihm: Er erhöht sich selbst und demütigt sich nicht genügend vor mir; aber wenn er sich vor mir niederbeugt und sich in mächtigem Gebet und Glauben demütigt, in der Aufrichtigkeit seines Herzens, dann werde ich ihm den Anblick der Dinge gewähren, die er zu sehen begehrt."},{"verse":25,"text":"Und dann soll er zu den Menschen dieser Generation sagen: Siehe, ich habe alles gesehen, was Joseph Smith Jr. vom Herrn gezeigt bekommen hat, und ich weiß mit Bestimmtheit, dass es wahr ist, denn ich habe es gesehen, denn es ist mir durch die Macht Gottes und nicht der Menschen gezeigt worden."},{"verse":26,"text":"Und ich, der Herr, gebiete ihm, meinem Diener Martin Harris, zu ihnen darüber nicht mehr zu sagen als nur das: Ich habe sie gesehen, und sie sind mir durch die Macht Gottes gezeigt worden; und das sind die Worte, die er sagen soll."},{"verse":27,"text":"Aber wenn er dies leugnet, so bricht er den Bund, mit dem er sich zuvor bei mir gebunden hat, und siehe, er ist schuldig gesprochen."},{"verse":28,"text":"Und nun, wenn er sich nicht demütigt und mir das eingesteht, was er getan hat und was falsch war, und mir gelobt, dass er meine Gebote halten und Glauben an mich ausüben wird, siehe, ich sage ihm: Er wird diesen Anblick nicht haben, denn ich werde ihm keinen Blick auf die Dinge gewähren, von denen ich gesprochen habe."},{"verse":29,"text":"Und wenn dies der Fall ist, gebiete ich dir, mein Diener Joseph, ihm zu sagen, dass er nichts mehr tun soll, auch mich in dieser Sache nicht mehr behelligen soll."},{"verse":30,"text":"Und wenn dies der Fall ist, siehe, so sage ich dir, Joseph: Wenn du noch ein paar Seiten übersetzt haben wirst, sollst du eine Zeit lang einhalten, ja, bis ich es dir wieder gebiete; dann magst du wieder übersetzen."},{"verse":31,"text":"Und wenn du das nicht tust, siehe, dann wirst du keine Gabe mehr haben, und ich werde dir das, was ich dir anvertraut habe, wegnehmen."},{"verse":32,"text":"Und nun, weil ich vorhersehe, wie man auf der Lauer liegt, um dich zu vernichten, ja, so sehe ich vorher, wenn mein Diener Martin Harris sich nicht demütigt und ein Zeugnis von meiner Hand empfängt, dann wird er in Übertretung fallen;"},{"verse":33,"text":"und es gibt viele, die auf der Lauer liegen, um dich vom Erdboden hinweg zu vernichten; und aus dem Grund, damit deine Tage verlängert seien, habe ich dir diese Gebote gegeben."},{"verse":34,"text":"Ja, aus dem Grund habe ich gesagt: Halte ein und bleibe stehen, bis ich dir gebiete, und ich werde Mittel und Wege bereiten, wodurch du das vollbringen kannst, was ich dir geboten habe."},{"verse":35,"text":"Und wenn du treu bist im Halten meiner Gebote, wirst du am letzten Tag emporgehoben werden. Amen."}]},{"chapter":6,"verses":[{"verse":1,"text":"Ein großes und wunderbares Werk ist im Begriff, für die Menschenkinder hervorzukommen."},{"verse":2,"text":"Siehe, ich bin Gott; schenkt meinem Wort Beachtung, das lebendig und machtvoll ist, schärfer als ein zweischneidiges Schwert, sodass es sowohl Gelenke als auch Mark zerteilt; darum schenkt meinen Worten Beachtung."},{"verse":3,"text":"Siehe, das Feld ist schon weiß, zur Ernte bereit; darum, wer zu ernten wünscht, der soll seine Sichel mit aller Macht einschlagen und ernten, solange es noch Tag ist, damit er im Reich Gottes immerwährende Errettung für seine Seele aufhäufe wie einen Schatz."},{"verse":4,"text":"Ja, wer auch immer seine Sichel einschlägt und erntet, der ist von Gott berufen."},{"verse":5,"text":"Darum, wenn ihr mich bittet, werdet ihr empfangen; wenn ihr anklopft, wird euch aufgetan werden."},{"verse":6,"text":"Da ihr nun gebeten habt, siehe, so sage ich euch: Haltet meine Gebote, und trachtet danach, die Sache Zions hervorzubringen und zu festigen;"},{"verse":7,"text":"trachtet nicht nach Reichtum, sondern nach Weisheit, und siehe, die Geheimnisse Gottes werden sich euch entfalten, und dann werdet ihr reich gemacht werden. Siehe, wer ewiges Leben hat, ist reich."},{"verse":8,"text":"Wahrlich, wahrlich, ich sage dir: Wie du es von mir wünschst, so wird es mit dir sein; und wenn du es wünschst, wirst du das Mittel sein, in dieser Generation viel Gutes zu tun."},{"verse":9,"text":"Sprich nichts als nur Umkehr zu dieser Generation; halte meine Gebote, und sei behilflich, mein Werk gemäß meinen Geboten hervorzubringen, dann wirst du gesegnet sein."},{"verse":10,"text":"Siehe, du hast eine Gabe, und gesegnet bist du wegen deiner Gabe. Bedenke, sie ist heilig und kommt von oben –"},{"verse":11,"text":"und wenn du fragst, so wirst du Geheimnisse kennenlernen, die groß und wunderbar sind; darum sollst du deine Gabe ausüben, damit du Geheimnisse herausfindest, damit du viele zur Erkenntnis der Wahrheit führen, ja, sie vom Irrtum ihrer Wege überzeugen kannst."},{"verse":12,"text":"Tue deine Gabe niemandem kund außer denjenigen, die deines Glaubens sind. Gehe mit Heiligem nicht leichtfertig um."},{"verse":13,"text":"Wenn du Gutes tust, ja, und treu bis ans Ende ausharrst, so wirst du im Reich Gottes errettet werden, was die größte aller Gaben Gottes ist; denn es gibt keine größere Gabe als die Gabe der Errettung."},{"verse":14,"text":"Wahrlich, wahrlich, ich sage dir: Gesegnet bist du um deswillen, was du getan hast; denn du hast mich gefragt, und siehe, sooft du gefragt hast, hast du von meinem Geist Belehrung empfangen. Wäre es nicht so gewesen, so wärst du nicht an den Ort gekommen, wo du jetzt bist."},{"verse":15,"text":"Siehe, du weißt, dass du mich gefragt hast und ich deinen Verstand erleuchtet habe; und nun sage ich dir dies alles, damit du weißt, dass du durch den Geist der Wahrheit erleuchtet worden bist;"},{"verse":16,"text":"ja, ich sage es dir, damit du weißt, dass es niemanden gibt außer Gott, der deine Gedanken und die Absichten deines Herzens kennt."},{"verse":17,"text":"Ich sage dir dies alles als Zeugnis für dich – dass die Worte, oder das Werk, das du niedergeschrieben hast, wahr sind."},{"verse":18,"text":"Darum sei eifrig; stehe meinem Diener Joseph getreulich bei, in welch schwierigen Umständen er auch immer um des Wortes willen sein mag."},{"verse":19,"text":"Ermahne ihn bei seinen Fehlern, und nimm auch Ermahnung von ihm an. Sei geduldig; sei ernsthaft; sei maßvoll; habe Geduld, Glauben, Hoffnung und Nächstenliebe."},{"verse":20,"text":"Siehe, du bist Oliver, und ich habe wegen deiner Wünsche zu dir gesprochen; darum hüte diese Worte in deinem Herzen wie einen Schatz. Sei treu und eifrig im Halten der Gebote Gottes, und ich werde dich mit den Armen meiner Liebe umschließen."},{"verse":21,"text":"Siehe, ich bin Jesus Christus, der Sohn Gottes. Ich bin es, der ich zu den Meinen gekommen bin, und die Meinen haben mich nicht empfangen. Ich bin das Licht, das in der Finsternis leuchtet, und die Finsternis erfasst es nicht."},{"verse":22,"text":"Wahrlich, wahrlich, ich sage dir: Wenn du ein weiteres Zeugnis begehrst, dann denke in deinem Sinn an die Nacht, da du im Herzen zu mir geschrien hast und wissen wolltest, ob dieses hier wahr sei."},{"verse":23,"text":"Habe ich deinem Sinn nicht Frieden in dieser Angelegenheit zugesprochen? Welch größeres Zeugnis kannst du haben als von Gott?"},{"verse":24,"text":"Und nun siehe, du hast ein Zeugnis empfangen; denn wenn ich dir etwas gesagt habe, was kein Mensch weiß, hast du dann nicht ein Zeugnis empfangen?"},{"verse":25,"text":"Und siehe, ich gewähre dir eine Gabe, wenn du es von mir wünschst, nämlich zu übersetzen, ja, wie mein Diener Joseph."},{"verse":26,"text":"Wahrlich, wahrlich, ich sage dir: Es gibt Aufzeichnungen, die viel von meinem Evangelium enthalten, die wegen der Schlechtigkeit der Menschen zurückgehalten worden sind;"},{"verse":27,"text":"und nun gebiete ich dir, wenn du gute Wünsche hast – den Wunsch, Schätze für dich anzusammeln im Himmel –, dann sollst du mithelfen, mit deiner Gabe diejenigen Teile meiner Schriften ans Licht zu bringen, die wegen des Übeltuns verborgen worden sind."},{"verse":28,"text":"Und nun siehe, ich gebe dir und auch meinem Diener Joseph die Schlüssel dieser Gabe, die diesen geistlichen Dienst ans Licht bringen soll; und durch den Mund zweier oder dreier Zeugen soll jegliches Wort bestätigt werden."},{"verse":29,"text":"Wahrlich, wahrlich, ich sage euch: Wenn sie meine Worte und diesen Teil meines Evangeliums und geistlichen Dienstes verwerfen, seid ihr gesegnet, denn sie können euch nicht mehr antun als mir."},{"verse":30,"text":"Und selbst wenn sie euch antun, ja, was sie mir angetan haben, seid ihr gesegnet, denn ihr werdet mit mir in Herrlichkeit wohnen."},{"verse":31,"text":"Doch wenn sie meine Worte nicht verwerfen, die durch das Zeugnis, das gegeben werden wird, bestätigt werden, sind sie gesegnet, und dann werdet ihr Freude an der Frucht eurer Arbeit haben."},{"verse":32,"text":"Wahrlich, wahrlich, ich sage euch, wie ich meinen Jüngern gesagt habe: Wo zwei oder drei in meinem Namen versammelt sind, irgendeine Sache betreffend, siehe, da werde ich mitten unter ihnen sein – und so bin ich mitten unter euch."},{"verse":33,"text":"Fürchtet euch nicht, Gutes zu tun, meine Söhne, denn was auch immer ihr sät, das werdet ihr auch ernten; darum, wenn ihr Gutes sät, werdet ihr als euren Lohn auch Gutes ernten."},{"verse":34,"text":"Darum fürchtet euch nicht, kleine Herde; tut Gutes; lasst Erde und Hölle sich gegen euch verbinden, denn wenn ihr auf meinem Felsen gebaut seid, können sie euch nicht überwältigen."},{"verse":35,"text":"Siehe, ich verurteile euch nicht; geht eurer Wege und sündigt nicht mehr; verrichtet mit Ernsthaftigkeit das Werk, das ich euch geboten habe."},{"verse":36,"text":"Blickt in jedem Gedanken auf mich; zweifelt nicht, fürchtet euch nicht."},{"verse":37,"text":"Seht die Wunden, die meine Seite durchbohrten, und auch die Nägelmale in meinen Händen und Füßen; seid treu, haltet meine Gebote, dann werdet ihr das Himmelreich ererben. Amen."}]},{"chapter":7,"verses":[{"verse":1,"text":"Und der Herr sprach zu mir: Mein geliebter Johannes, was wünschst du dir? Denn wenn du dir erbittest, was du willst, so wird es dir gewährt werden."},{"verse":2,"text":"Und ich sprach zu ihm: Herr, gib mir Macht über den Tod, damit ich leben und Seelen zu dir bringen kann."},{"verse":3,"text":"Und der Herr sprach zu mir: Wahrlich, wahrlich, ich sage dir, weil du dir das wünschst, wirst du verweilen, bis ich in meiner Herrlichkeit komme, und wirst vor Nationen, Geschlechtern, Sprachen und Völkern prophezeien."},{"verse":4,"text":"Und aus diesem Grund sprach der Herr zu Petrus: Wenn ich will, dass er verweile, bis ich komme, was geht das dich an? Denn er hat sich von mir gewünscht, Seelen zu mir bringen zu können, aber du hast dir gewünscht, schnell zu mir in mein Reich kommen zu können."},{"verse":5,"text":"Ich sage dir, Petrus, dies war ein guter Wunsch; aber mein Geliebter hat sich gewünscht, mehr zu tun, ja, ein noch größeres Werk unter den Menschen, als was er zuvor getan hat."},{"verse":6,"text":"Ja, er hat ein größeres Werk auf sich genommen; darum werde ich ihn wie flammendes Feuer und zu einem dienenden Engel werden lassen; er wird denen dienen, die auf Erden wohnen und Erben der Errettung sein werden."},{"verse":7,"text":"Und ich werde machen, dass du ihm und deinem Bruder Jakobus dienst; und euch drei werde ich diese Macht und die Schlüssel dieses geistlichen Dienstes geben, bis ich komme."},{"verse":8,"text":"Wahrlich, ich sage euch, ihr werdet beide gemäß euren Wünschen haben, denn ihr beide erfreut euch dessen, was ihr euch gewünscht habt."}]},{"chapter":8,"verses":[{"verse":1,"text":"Oliver Cowdery, wahrlich, wahrlich, ich sage dir: So gewisslich der Herr lebt, der dein Gott und dein Erlöser ist, ebenso gewiss wirst du Kenntnis empfangen von allem, was auch immer du im Glauben erbittest, mit ehrlichem Herzen und im Vertrauen darauf, dass du Kenntnis empfangen wirst über die Gravierungen der alten Aufzeichnungen, die aus früherer Zeit stammen und diejenigen Teile meiner heiligen Schrift enthalten, von denen durch die Kundgebung meines Geistes gesprochen worden ist."},{"verse":2,"text":"Ja, siehe, ich werde es dir in deinem Verstand und in deinem Herzen durch den Heiligen Geist sagen, der über dich kommen wird und der in deinem Herzen wohnen wird."},{"verse":3,"text":"Nun siehe, dies ist der Geist der Offenbarung; siehe, dies ist der Geist, durch den Mose die Kinder Israel auf trockenem Grund durch das Rote Meer führte."},{"verse":4,"text":"Darum ist dies deine Gabe; mache davon Gebrauch, dann bist du gesegnet, denn sie wird dich aus den Händen deiner Feinde befreien, die, wenn es nicht so wäre, dich töten und deine Seele zur Vernichtung führen würden."},{"verse":5,"text":"O denke an diese Worte und halte meine Gebote. Denke daran, dies ist deine Gabe."},{"verse":6,"text":"Nun ist dies nicht all deine Gabe, denn du hast noch eine Gabe, nämlich die Gabe Aarons; siehe, sie hat dir vieles mitgeteilt;"},{"verse":7,"text":"siehe, es gibt außer der Macht Gottes keine andere Macht, die dir diese Gabe Aarons zukommen lassen könnte."},{"verse":8,"text":"Darum zweifle nicht, denn es ist die Gabe Gottes; und du wirst sie in deinen Händen halten und wunderbare Werke verrichten; und keine Macht wird imstande sein, sie dir aus deinen Händen wegzunehmen, denn es ist das Werk Gottes."},{"verse":9,"text":"Und darum: Was auch immer du mich bittest, dir auf diese Weise mitzuteilen, das werde ich dir gewähren, und du wirst Kenntnis davon haben."},{"verse":10,"text":"Denke daran: Ohne Glauben kannst du nichts tun; darum bitte im Glauben. Gehe nicht leichtfertig mit all diesem um; bitte nicht um das, was du nicht solltest."},{"verse":11,"text":"Bitte, dass du die Geheimnisse Gottes erfahren mögest und dass du übersetzen und Kenntnis aus all jenen alten Aufzeichnungen empfangen mögest, die verborgen worden sind, die heilig sind; und gemäß deinem Glauben wird dir geschehen."},{"verse":12,"text":"Siehe, ich bin es, der dies gesprochen hat; und ich bin derselbe, der von Anfang an zu dir gesprochen hat. Amen."}]},{"chapter":9,"verses":[{"verse":1,"text":"Siehe, ich sage dir, mein Sohn: Weil du nicht übersetzt hast, wie es dem entsprochen hätte, was du von mir begehrt hast, sondern wieder angefangen hast, für meinen Diener Joseph Smith Jr. zu schreiben, so möchte ich, dass du damit fortfährst, bis du diesen Bericht zu Ende gebracht hast, den ich ihm anvertraut habe."},{"verse":2,"text":"Und dann, siehe, weitere Aufzeichnungen habe ich, bei denen ich dir die Macht geben werde, an der Übersetzung mitzuhelfen."},{"verse":3,"text":"Sei geduldig, mein Sohn, denn es ist nach meiner Weisheit, und es ist nicht ratsam, dass du zur gegenwärtigen Zeit übersetzen sollst."},{"verse":4,"text":"Siehe, die Arbeit, zu der du berufen bist, besteht darin, für meinen Diener Joseph zu schreiben."},{"verse":5,"text":"Und siehe, es ist, weil du nicht weitergemacht hast, wie du begonnen hast, als du anfingst zu übersetzen, dass ich dir dieses Recht weggenommen habe."},{"verse":6,"text":"Murre nicht, mein Sohn, denn es ist nach meiner Weisheit, dass ich mit dir auf diese Weise umgegangen bin."},{"verse":7,"text":"Siehe, du hast es nicht verstanden; du hast gemeint, ich würde es dir geben, obschon du dir keine Gedanken gemacht hast, außer mich zu bitten."},{"verse":8,"text":"Aber siehe, ich sage dir: Du musst es mit deinem Verstand durcharbeiten; dann musst du mich fragen, ob es recht ist, und wenn es recht ist, werde ich machen, dass dein Herz in dir brennt; darum wirst du fühlen, dass es recht ist."},{"verse":9,"text":"Wenn es aber nicht recht ist, wirst du keine solchen Gefühle haben, sondern du wirst eine Gedankenstarre haben, die dich das vergessen lassen wird, was falsch ist; darum kannst du das, was heilig ist, nicht schreiben, außer es werde dir von mir gegeben."},{"verse":10,"text":"Nun, wenn du das erkannt hättest, so hättest du übersetzen können; doch ist es nicht ratsam, dass du jetzt übersetzt."},{"verse":11,"text":"Siehe, es war ratsam, als du anfingst; aber du hast Furcht gehabt, und die Zeit ist vorbei, und jetzt ist es nicht ratsam;"},{"verse":12,"text":"denn siehst du nicht, dass ich meinem Diener Joseph genügend Kraft gegeben habe, wodurch das ausgeglichen wird? Und keinen von euch beiden habe ich schuldig gesprochen."},{"verse":13,"text":"Tue das, was ich dir geboten habe, und es wird dir wohl ergehen. Sei treu und gib keiner Versuchung nach."},{"verse":14,"text":"Steh fest in dem Werk, wozu ich dich berufen habe, und nicht ein Haar deines Hauptes wird verlorengehen, und du wirst am letzten Tag emporgehoben werden. Amen."}]},{"chapter":10,"verses":[{"verse":1,"text":"Nun siehe, ich sage dir: Weil du jene Schriften, für deren Übersetzung mit Hilfe des Urim und Tummim dir Macht gegeben wurde, in die Hände eines schlechten Mannes weitergegeben hast, sind sie dir verlorengegangen."},{"verse":2,"text":"Und zur gleichen Zeit hast du auch deine Gabe verloren, und dein Verstand hat sich verfinstert."},{"verse":3,"text":"Doch ist sie dir jetzt wiederhergestellt worden; darum sieh zu, dass du treu bist und weitermachst, um die restliche Übersetzungsarbeit zu Ende zu bringen, wie du angefangen hast."},{"verse":4,"text":"Laufe nicht schneller und verrichte nicht mehr Arbeit, als du Kraft hast und Mittel vorgesehen sind, die dir das Übersetzen ermöglichen; doch sei eifrig bis ans Ende."},{"verse":5,"text":"Bete immer, damit du als Sieger hervorgehst, ja, damit du den Satan besiegst und damit du den Händen der Diener des Satans entrinnst, die sein Werk unterstützen."},{"verse":6,"text":"Siehe, sie haben danach getrachtet, dich zu vernichten; ja, sogar der Mann, dem du vertraut hast, hat danach getrachtet, dich zu vernichten."},{"verse":7,"text":"Und aus diesem Grund habe ich gesagt, er sei ein schlechter Mann, denn er hat danach getrachtet, das wegzunehmen, was dir anvertraut worden ist, und er hat auch danach getrachtet, deine Gabe zu vernichten."},{"verse":8,"text":"Und weil du die Schriften in seine Hände gegeben hast, siehe, haben schlechte Menschen sie dir weggenommen."},{"verse":9,"text":"Darum hast du sie, ja, das, was heilig ist, der Schlechtigkeit übergeben."},{"verse":10,"text":"Und siehe, der Satan hat es ihnen ins Herz gegeben, die Worte zu ändern, die du hast schreiben lassen, oder die du übersetzt hast, und die aus deinen Händen verlorengegangen sind."},{"verse":11,"text":"Und siehe, ich sage dir: Weil sie die Worte geändert haben, lauten diese jetzt widersprechend zu dem, was du übersetzt hast und hast schreiben lassen;"},{"verse":12,"text":"und auf diese Weise hat der Teufel danach getrachtet, einen schlauen Plan zurechtzulegen, damit er dieses Werk zerstöre;"},{"verse":13,"text":"denn er hat es ihnen ins Herz gegeben, dies zu tun, damit sie mit ihrem Lügen sagen können, sie hätten dich in den Worten gefangen, die du angeblich übersetzt hast."},{"verse":14,"text":"Wahrlich, ich sage dir: Ich werde nicht zulassen, dass der Satan seine böse Absicht in dieser Sache vollbringt."},{"verse":15,"text":"Denn siehe, er hat es ihnen ins Herz gegeben, dich dahin zu bringen, dass du den Herrn, deinen Gott, versuchst, indem du bittest, es abermals übersetzen zu dürfen."},{"verse":16,"text":"Und dann, siehe, sagen und denken sie in ihrem Herzen: Wir werden sehen, ob Gott ihm die Macht gegeben hat zu übersetzen; wenn ja, wird er ihm die Macht auch noch einmal geben;"},{"verse":17,"text":"und wenn Gott ihm die Macht noch einmal gibt oder wenn er noch einmal übersetzt oder, mit anderen Worten, wenn er die gleichen Worte hervorbringt, siehe, so haben wir die gleichen bei uns, und wir haben sie geändert;"},{"verse":18,"text":"darum werden sie nicht übereinstimmen, und wir werden sagen, er habe in seinen Worten gelogen und er habe keine Gabe und er habe keine Macht;"},{"verse":19,"text":"darum werden wir ihn vernichten, ebenso das Werk; und wir wollen dies tun, damit wir am Ende nicht beschämt werden und damit wir Ansehen der Welt erlangen."},{"verse":20,"text":"Wahrlich, wahrlich, ich sage dir: Der Satan hat großen Einfluss auf ihr Herz; er stachelt sie zum Übeltun auf gegen das, was gut ist;"},{"verse":21,"text":"und ihr Herz ist verdorben und voller Schlechtigkeit und Gräuel; und sie lieben die Finsternis mehr als das Licht, weil ihre Taten böse sind; darum wollen sie mich nicht bitten."},{"verse":22,"text":"Der Satan stachelt sie auf, damit er ihre Seele zur Vernichtung führen könne."},{"verse":23,"text":"Und so hat er einen schlauen Plan zurechtgelegt und gedenkt, das Werk Gottes zu zerstören; aber ich werde dies von ihrer Hand fordern, und es wird sich am Tag des Gerichts zu ihrer Schande und Schuldigsprechung wenden."},{"verse":24,"text":"Ja, er stachelt ihnen das Herz zum Zorn gegen dieses Werk auf."},{"verse":25,"text":"Ja, er spricht zu ihnen: Täuscht und legt euch auf die Lauer, um zu fangen, damit ihr zerstören könnt; siehe, das ist nichts Arges. Und so schmeichelt er ihnen und sagt ihnen, es sei keine Sünde, wenn sie lügen, um jemanden in einer Lüge zu fangen, damit sie ihn vernichten können."},{"verse":26,"text":"Und so schmeichelt er ihnen und führt sie dahin, bis er ihre Seele zur Hölle hinabzerrt; und so lässt er sie sich in ihrer eigenen Schlinge fangen."},{"verse":27,"text":"Und so geht er auf der Erde auf und ab, hin und her, und trachtet danach, die Menschenseelen zu vernichten."},{"verse":28,"text":"Wahrlich, wahrlich, ich sage dir: Weh sei dem, der lügt, um zu täuschen, weil er meint, ein anderer lüge, um zu täuschen; denn so jemand ist von der Gerechtigkeit Gottes nicht ausgenommen."},{"verse":29,"text":"Nun siehe, sie haben diese Worte geändert, weil der Satan zu ihnen sagt: Er hat euch getäuscht – und so verleitet er sie schmeichlerisch, dass sie übeltun und dich dazu bringen, dass du den Herrn, deinen Gott, versuchst."},{"verse":30,"text":"Siehe, ich sage dir: Du sollst die Worte, die aus deinen Händen verlorengegangen sind, nicht noch einmal übersetzen;"},{"verse":31,"text":"denn siehe, sie sollen ihre bösen Absichten nicht verwirklichen, indem sie gegen jene Worte lügen. Denn siehe, wenn du dieselben Worte hervorbringst, werden sie sagen, du habest gelogen und du habest vorgegeben zu übersetzen, aber du habest dir selbst widersprochen."},{"verse":32,"text":"Und siehe, sie werden dies veröffentlichen, und der Satan wird den Menschen das Herz verhärten, um sie zum Zorn gegen dich aufzustacheln, sodass sie meine Worte nicht glauben werden."},{"verse":33,"text":"So gedenkt der Satan, dein Zeugnis in dieser Generation zu überwältigen, damit das Werk in dieser Generation nicht hervorkommen kann."},{"verse":34,"text":"Aber siehe, hier ist Weisheit, und weil ich dir Weisheit erzeige und dir diesbezüglich Gebote gebe, was du tun sollst, so zeige es nicht der Welt, bis du das Werk der Übersetzung vollbracht hast."},{"verse":35,"text":"Wundere dich nicht, dass ich dir gesagt habe: Hier ist Weisheit, zeige es nicht der Welt – denn ich habe gesagt, zeige es nicht der Welt, damit du bewahrt bleibest."},{"verse":36,"text":"Siehe, ich sage nicht, dass du es nicht den Rechtschaffenen zeigen sollst;"},{"verse":37,"text":"aber da du nicht immer beurteilen kannst, wer rechtschaffen ist, oder da du die Schlechten von den Rechtschaffenen nicht immer unterscheiden kannst, darum sage ich dir: Sei still, bis ich es für richtig halte, der Welt alles über diese Angelegenheit kundzutun."},{"verse":38,"text":"Und nun, wahrlich, ich sage dir: Ein Bericht von dem allen, was du geschrieben hast und was aus deinen Händen verlorengegangen ist, ist auf den Platten Nephis eingraviert;"},{"verse":39,"text":"ja, und du erinnerst dich, es heißt in jenen Schriften, dass ein ausführlicherer Bericht von diesem allen auf den Platten Nephis gegeben sei."},{"verse":40,"text":"Und nun, weil der Bericht, der auf den Platten Nephis eingraviert ist, ausführlicher über das ist, was ich nach meiner Weisheit den Menschen mit diesem Bericht zur Kenntnis bringen wollte –"},{"verse":41,"text":"darum sollst du die Gravierungen, die auf den Platten Nephis sind, übersetzen, bis du hinab zur Regierung König Benjamins kommst, oder bis du zu dem kommst, was du übersetzt hast, was du behalten hast;"},{"verse":42,"text":"und siehe, du sollst es als den Bericht Nephis veröffentlichen; und so werde ich diejenigen beschämen, die meine Worte geändert haben."},{"verse":43,"text":"Ich werde nicht zulassen, dass sie mein Werk zerstören; ja, ich werde ihnen zeigen, dass meine Weisheit größer ist als die Schlauheit des Teufels."},{"verse":44,"text":"Siehe, sie haben nur einen Teil oder einen Auszug aus dem Bericht Nephis erlangt."},{"verse":45,"text":"Siehe, vieles ist auf den Platten Nephis eingraviert, was größere Einsichten in mein Evangelium gewährt; darum ist es nach meiner Weisheit, dass du diesen ersten Teil der Gravierungen Nephis übersetzt und in diesem Werk herausbringst."},{"verse":46,"text":"Und siehe, all das Übrige dieses Werkes enthält alle jene Teile meines Evangeliums, von denen meine heiligen Propheten, ja, und auch meine Jünger, in ihren Gebeten gewünscht haben, sie mögen an dieses Volk gelangen."},{"verse":47,"text":"Und ich sprach zu ihnen, dass es ihnen gemäß ihrem Glauben in ihren Gebeten gewährt werden würde;"},{"verse":48,"text":"ja, und dies war ihr Glaube – dass mein Evangelium, das ich ihnen gegeben hatte, damit sie in ihren Tagen predigten, zu ihren Brüdern, den Lamaniten, gelangen möge, ebenso allen, die infolge ihrer Abspaltungen Lamaniten geworden waren."},{"verse":49,"text":"Nun ist dies nicht alles – ihr Glaube in ihren Gebeten war, dass dieses Evangelium auch kundgetan werden sollte, wenn es möglich wäre, dass andere Nationen dieses Land besäßen;"},{"verse":50,"text":"und so haben sie in ihren Gebeten einen Segen auf diesem Land hinterlassen, dass, wer auch immer in diesem Land an dieses Evangelium glaubt, ewiges Leben haben könne;"},{"verse":51,"text":"ja, dass es frei sei für alle, von welcher Nation, welchem Geschlecht, welcher Sprache oder welchem Volk sie auch immer seien."},{"verse":52,"text":"Und nun, siehe, gemäß ihrem Glauben in ihren Gebeten werde ich diesen Teil meines Evangeliums meinem Volk zur Kenntnis bringen. Siehe, ich bringe es nicht, um das zu zerstören, was sie empfangen haben, sondern um es aufzubauen."},{"verse":53,"text":"Und aus diesem Grund habe ich gesagt: Wenn diese Generation ihr Herz nicht verhärtet, werde ich meine Kirche unter ihnen aufrichten."},{"verse":54,"text":"Nun sage ich das nicht, um meine Kirche zu zerstören, sondern ich sage es, um meine Kirche aufzubauen;"},{"verse":55,"text":"darum, wer auch immer meiner Kirche angehört, braucht sich nicht zu fürchten, denn so jemand wird das Himmelreich ererben."},{"verse":56,"text":"Aber es sind diejenigen, die mich nicht fürchten, auch meine Gebote nicht halten, sondern für sich selbst Kirchen errichten, um Gewinn zu erlangen, ja, und alle jene, die Schlechtes tun und das Reich des Teufels aufbauen – ja, wahrlich, wahrlich, ich sage dir: Sie sind es, die ich aufschrecken werde und bis ins Innerste zittern und beben machen werde."},{"verse":57,"text":"Siehe, ich bin Jesus Christus, der Sohn Gottes. Ich bin zu den Meinen gekommen, und die Meinen haben mich nicht empfangen."},{"verse":58,"text":"Ich bin das Licht, das in der Finsternis leuchtet, und die Finsternis erfasst es nicht."},{"verse":59,"text":"Ich bin es, der zu meinen Jüngern gesprochen hat: Andere Schafe habe ich, die nicht von dieser Herde sind – und viele gab es, die mich nicht verstanden haben."},{"verse":60,"text":"Und ich werde diesem Volk zeigen, dass ich andere Schafe hatte und dass sie ein Zweig vom Haus Jakob waren;"},{"verse":61,"text":"und ich werde ihre wunderbaren Werke ans Licht bringen, die sie in meinem Namen getan haben;"},{"verse":62,"text":"ja, und ich werde auch mein Evangelium ans Licht bringen, das ihnen kundgetan wurde, und siehe, sie werden das, was du empfangen hast, nicht leugnen, sondern sie werden es aufbauen und werden die wahren Punkte meiner Lehre ans Licht bringen, ja, nämlich die einzige Lehre, die in mir ist."},{"verse":63,"text":"Und dies tue ich, um mein Evangelium aufzurichten, damit es nicht so viel Streit gibt; ja, der Satan stachelt den Menschen das Herz zum Streit über die Punkte meiner Lehre auf, und darin irren sie, denn sie verdrehen die Schriften und verstehen sie nicht."},{"verse":64,"text":"Darum werde ich ihnen dieses große Geheimnis entfalten;"},{"verse":65,"text":"denn siehe, ich will sie sammeln, wie eine Henne ihre Küken unter ihre Flügel sammelt, wenn sie ihr Herz nicht verhärten;"},{"verse":66,"text":"ja, wenn sie kommen wollen, so mögen sie es und dürfen uneingeschränkt von den Wassern des Lebens nehmen."},{"verse":67,"text":"Siehe, dies ist meine Lehre: Wer auch immer umkehrt und zu mir kommt, der ist meine Kirche."},{"verse":68,"text":"Wer auch immer mehr oder weniger als dies verkündet, der ist nicht von mir, sondern ist gegen mich; darum ist er nicht von meiner Kirche."},{"verse":69,"text":"Und nun siehe, wer auch immer von meiner Kirche ist und in meiner Kirche bis ans Ende ausharrt, den werde ich auf meinen Felsen gründen, und die Pforten der Hölle werden ihn nicht überwältigen."},{"verse":70,"text":"Und nun, denke an die Worte dessen, der das Leben und Licht der Welt ist, dein Erlöser, dein Herr und dein Gott. Amen."}]},{"chapter":11,"verses":[{"verse":1,"text":"Ein großes und wunderbares Werk ist im Begriff, unter den Menschenkindern hervorzukommen."},{"verse":2,"text":"Siehe, ich bin Gott; schenke meinem Wort Beachtung, das lebendig und machtvoll ist, schärfer als ein zweischneidiges Schwert, sodass es sowohl Gelenke als auch Mark zerteilt; darum schenke meinem Wort Beachtung."},{"verse":3,"text":"Siehe, das Feld ist schon weiß, zur Ernte bereit; darum, wer zu ernten wünscht, der soll seine Sichel mit aller Macht einschlagen und ernten, solange es noch Tag ist, damit er im Reich Gottes immerwährende Errettung für seine Seele aufhäufe wie einen Schatz."},{"verse":4,"text":"Ja, wer auch immer seine Sichel einschlägt und erntet, der ist von Gott berufen."},{"verse":5,"text":"Darum, wenn du mich bittest, wirst du empfangen; wenn du anklopfst, wird dir aufgetan werden."},{"verse":6,"text":"Da du nun gebeten hast, siehe, so sage ich dir: Halte meine Gebote, und trachte danach, die Sache Zions hervorzubringen und zu festigen."},{"verse":7,"text":"Trachte nicht nach Reichtum, sondern nach Weisheit, und siehe, die Geheimnisse Gottes werden sich dir entfalten, und dann wirst du reich gemacht werden. Siehe, wer ewiges Leben hat, ist reich."},{"verse":8,"text":"Wahrlich, wahrlich, ich sage dir: So, wie du es von mir begehrst, so wird es dir geschehen; und wenn du es wünschst, wirst du das Mittel sein, in dieser Generation viel Gutes zu tun."},{"verse":9,"text":"Sprich nichts als nur Umkehr zu dieser Generation. Halte meine Gebote, und sei behilflich, mein Werk gemäß meinen Geboten hervorzubringen, dann wirst du gesegnet sein."},{"verse":10,"text":"Siehe, du hast eine Gabe, oder du wirst eine Gabe haben, wenn du es von mir im Glauben wünschst, mit ehrlichem Herzen, und an die Macht Jesu Christi glaubst, oder an meine Macht, die zu dir spricht;"},{"verse":11,"text":"denn siehe, ich bin es, der spricht; siehe, ich bin das Licht, das in der Finsternis leuchtet, und durch meine Macht gebe ich dir diese Worte."},{"verse":12,"text":"Und nun, wahrlich, wahrlich, ich sage dir: Setze dein Vertrauen in jenen Geist, der dazu führt, Gutes zu tun – ja, gerecht zu handeln, demütig zu wandeln, rechtschaffen zu richten; und dies ist mein Geist."},{"verse":13,"text":"Wahrlich, wahrlich, ich sage dir: Ich werde dir von meinem Geist geben, der dir den Verstand erleuchten wird und der dir die Seele mit Freude erfüllen wird;"},{"verse":14,"text":"und dann wirst du wissen, oder infolgedessen wirst du alles wissen, was auch immer du von mir begehrst und was die Rechtschaffenheit betrifft, sofern du im Glauben an mich darauf vertraust, dass du empfangen wirst."},{"verse":15,"text":"Siehe, ich gebiete dir, nicht etwa zu meinen, du seiest berufen zu predigen, ehe du berufen bist."},{"verse":16,"text":"Warte noch ein wenig, bis du mein Wort haben wirst, meinen Fels, meine Kirche und mein Evangelium, damit du meine Lehre mit Gewissheit kennst."},{"verse":17,"text":"Und dann, siehe, wird dir gemäß deinen Wünschen, ja, nämlich gemäß deinem Glauben geschehen."},{"verse":18,"text":"Halte meine Gebote; sei still; wende dich an meinen Geist;"},{"verse":19,"text":"ja, halte mit deinem ganzen Herzen an mir fest, damit du mithelfen kannst, das ans Licht zu bringen, wovon die Rede war – ja, die Übersetzung meines Werks; sei geduldig, bis du es vollbringen wirst."},{"verse":20,"text":"Siehe, dies ist dein Werk: meine Gebote zu halten, ja, mit all deiner Macht, ganzem Sinn und aller Kraft."},{"verse":21,"text":"Trachte nicht danach, mein Wort zu verkünden, sondern trachte zuerst danach, mein Wort zu erlangen, und dann wird deine Zunge gelöst werden; dann, wenn du es wünschst, wirst du meinen Geist und mein Wort haben, ja, die Macht Gottes, um Menschen zu überzeugen."},{"verse":22,"text":"Aber nun sei still; erforsche mein Wort, das unter die Menschenkinder hinausgegangen ist, und erforsche auch mein Wort, das unter den Menschenkindern hervorkommen wird, oder das, was jetzt in der Übersetzung ist, ja, bis du alles erlangt hast, was ich den Menschenkindern in dieser Generation gewähren werde, und dann wird dem alles hinzugefügt werden."},{"verse":23,"text":"Siehe, du bist Hyrum, mein Sohn; trachte nach dem Reich Gottes, dann wird alles hinzugefügt werden, gemäß dem, was gerecht ist."},{"verse":24,"text":"Baue auf meinem Felsen, der mein Evangelium ist;"},{"verse":25,"text":"leugne nicht den Geist der Offenbarung, auch nicht den Geist der Prophezeiung, denn weh dem, der dieses leugnet;"},{"verse":26,"text":"darum häufe in deinem Herzen auf wie einen Schatz, bis zu der Zeit, da du meiner Weisheit nach ausgehen sollst."},{"verse":27,"text":"Siehe, ich spreche zu allen, die gute Wünsche haben und ihre Sichel eingeschlagen haben, um zu ernten."},{"verse":28,"text":"Siehe, ich bin Jesus Christus, der Sohn Gottes. Ich bin das Leben und das Licht der Welt."},{"verse":29,"text":"Ich bin es, der ich zu den Meinen gekommen bin, und die Meinen haben mich nicht empfangen;"},{"verse":30,"text":"aber wahrlich, wahrlich, ich sage euch: Allen, die mich empfangen, denen werde ich die Macht geben, Söhne Gottes zu werden, ja, denen, die an meinen Namen glauben. Amen."}]},{"chapter":12,"verses":[{"verse":1,"text":"Ein großes und wunderbares Werk ist im Begriff, unter den Menschenkindern hervorzukommen."},{"verse":2,"text":"Siehe, ich bin Gott; schenke meinem Wort Beachtung, das lebendig und machtvoll ist, schärfer als ein zweischneidiges Schwert, sodass es sowohl Gelenke als auch Mark zerteilt; darum schenke meinem Wort Beachtung."},{"verse":3,"text":"Siehe, das Feld ist schon weiß, zur Ernte bereit; darum, wer zu ernten wünscht, der soll seine Sichel mit aller Macht einschlagen und ernten, solange es noch Tag ist, damit er im Reich Gottes immerwährende Errettung für seine Seele aufhäufe wie einen Schatz."},{"verse":4,"text":"Ja, wer auch immer seine Sichel einschlägt und erntet, der ist von Gott berufen."},{"verse":5,"text":"Darum, wenn du mich bittest, wirst du empfangen; wenn du anklopfst, wird dir aufgetan werden."},{"verse":6,"text":"Da du nun gebeten hast, siehe, so sage ich dir: Halte meine Gebote, und trachte danach, die Sache Zions hervorzubringen und zu festigen."},{"verse":7,"text":"Siehe, ich spreche zu dir und auch zu all jenen, die den Wunsch haben, dieses Werk hervorzubringen und zu festigen;"},{"verse":8,"text":"und niemand kann bei diesem Werk helfen, wenn er nicht demütig und voller Liebe ist und Glauben, Hoffnung und Nächstenliebe hat und in allem, was auch immer seiner Obhut anvertraut wird, maßvoll ist."},{"verse":9,"text":"Siehe, ich bin das Licht und das Leben der Welt, der ich diese Worte spreche, darum schenke ihnen Beachtung mit aller Kraft, und dann bist du berufen. Amen."}]},{"chapter":13,"verses":[{"verse":1,"text":"Euch, meinen Mitbrüdern im Dienst, übertrage ich im Namen des Messias das Priestertum Aarons, das die Schlüssel des Dienstes von Engeln und die des Evangeliums der Umkehr und die der Taufe durch Untertauchen zur Sündenvergebung innehat; und es wird nie mehr von der Erde genommen werden, bis die Söhne Levi dem Herrn wieder in Rechtschaffenheit ein Opfer darbringen."}]},{"chapter":14,"verses":[{"verse":1,"text":"Ein großes und wunderbares Werk ist im Begriff, für die Menschenkinder hervorzukommen."},{"verse":2,"text":"Siehe, ich bin Gott; schenke meinem Wort Beachtung, das lebendig und machtvoll ist, schärfer als ein zweischneidiges Schwert, sodass es sowohl Gelenke als auch Mark zerteilt; darum schenke meinem Wort Beachtung."},{"verse":3,"text":"Siehe, das Feld ist schon weiß, zur Ernte bereit; darum, wer zu ernten wünscht, der soll seine Sichel mit aller Macht einschlagen und ernten, solange es noch Tag ist, damit er im Reich Gottes immerwährende Errettung für seine Seele aufhäufe wie einen Schatz."},{"verse":4,"text":"Ja, wer auch immer seine Sichel einschlägt und erntet, der ist von Gott berufen."},{"verse":5,"text":"Darum, wenn du mich bittest, wirst du empfangen; wenn du anklopfst, wird dir aufgetan werden."},{"verse":6,"text":"Trachte danach, mein Zion hervorzubringen und zu festigen. Halte in allem meine Gebote."},{"verse":7,"text":"Und wenn du meine Gebote hältst und bis ans Ende ausharrst, wirst du ewiges Leben haben, und diese Gabe ist die größte aller Gaben Gottes."},{"verse":8,"text":"Und es wird sich begeben: Wenn du den Vater in meinem Namen bittest und voll Glauben vertraust, wirst du den Heiligen Geist empfangen, der zu reden eingibt, damit du dastehen kannst als Zeuge dessen, was du hören und auch sehen wirst, und auch, damit du dieser Generation Umkehr verkünden kannst."},{"verse":9,"text":"Siehe, ich bin Jesus Christus, der Sohn des lebendigen Gottes, der die Himmel und die Erde erschaffen hat, ein Licht, das nicht in der Finsternis verborgen werden kann;"},{"verse":10,"text":"darum muss ich die Fülle meines Evangeliums von den Anderen her zum Haus Israel hervorbringen."},{"verse":11,"text":"Und siehe, du bist David, und du bist berufen mitzuhelfen; und wenn du das tust und treu bist, wirst du sowohl geistig als auch zeitlich gesegnet sein, und groß wird dein Lohn sein. Amen."}]},{"chapter":15,"verses":[{"verse":1,"text":"Horche auf, mein Diener John, und höre auf die Worte Jesu Christi, deines Herrn und deines Erlösers."},{"verse":2,"text":"Denn siehe, ich spreche zu dir mit Deutlichkeit und mit Macht, denn mein Arm ist über der ganzen Erde."},{"verse":3,"text":"Und ich will dir das sagen, was außer mir und dir allein kein Mensch weiß –"},{"verse":4,"text":"denn viele Male hast du von mir zu wissen begehrt, was für dich von größtem Wert sein würde."},{"verse":5,"text":"Siehe, gesegnet bist du dafür und dass du meine Worte geredet hast, die ich dir gemäß meinen Geboten gegeben habe."},{"verse":6,"text":"Und nun siehe, ich sage dir: Was für dich von größtem Wert sein wird, das ist, diesem Volk Umkehr zu verkünden, damit du Seelen zu mir bringst, damit du mit ihnen im Reich meines Vaters ruhen mögest. Amen."}]},{"chapter":16,"verses":[{"verse":1,"text":"Horche auf, mein Diener Peter, und höre auf die Worte Jesu Christi, deines Herrn und deines Erlösers."},{"verse":2,"text":"Denn siehe, ich spreche zu dir mit Deutlichkeit und mit Macht, denn mein Arm ist über der ganzen Erde."},{"verse":3,"text":"Und ich will dir das sagen, was außer mir und dir allein kein Mensch weiß –"},{"verse":4,"text":"denn viele Male hast du von mir zu wissen begehrt, was für dich von größtem Wert sein würde."},{"verse":5,"text":"Siehe, gesegnet bist du dafür und dass du meine Worte geredet hast, die ich dir gemäß meinen Geboten gegeben habe."},{"verse":6,"text":"Und nun siehe, ich sage dir: Was für dich von größtem Wert sein wird, das ist, diesem Volk Umkehr zu verkünden, damit du Seelen zu mir bringst, damit du mit ihnen im Reich meines Vaters ruhen mögest. Amen."}]},{"chapter":17,"verses":[{"verse":1,"text":"Siehe, ich sage euch: Ihr müsst euch auf mein Wort verlassen, denn wenn ihr das mit voller Herzensabsicht tut, werdet ihr die Platten erblicken, ebenso den Brustschild, das Schwert Labans, die Urim und Tummim, die Jareds Bruder auf dem Berg gegeben wurden, als er von Angesicht zu Angesicht mit dem Herrn sprach, sowie die wundertätigen Richtungsweiser, die Lehi in der Wildnis gegeben wurden, im Grenzgebiet des Roten Meeres."},{"verse":2,"text":"Und es ist durch euren Glauben, dass ihr sie erblicken werdet, durch jenen Glauben nämlich, den die Propheten vor alters hatten."},{"verse":3,"text":"Und nachdem ihr Glauben erlangt habt und sie mit eigenen Augen gesehen habt, sollt ihr dafür Zeugnis geben, durch die Macht Gottes;"},{"verse":4,"text":"und dies sollt ihr tun, damit mein Diener Joseph Smith Jr. nicht vernichtet werde, damit ich meine rechtschaffenen Absichten für die Menschenkinder in diesem Werk verwirklichen kann."},{"verse":5,"text":"Und ihr sollt bezeugen, dass ihr sie gesehen habt, ebenso wie mein Diener Joseph Smith Jr. sie gesehen hat; denn es ist durch meine Macht, dass er sie gesehen hat, und es ist, weil er Glauben hatte."},{"verse":6,"text":"Und er hat das Buch übersetzt, nämlich jenen Teil, den ich ihm geboten habe, und so wahr euer Herr und euer Gott lebt, ist es wahr."},{"verse":7,"text":"Nun also habt ihr die gleiche Macht empfangen und den gleichen Glauben und die gleiche Gabe wie auch er;"},{"verse":8,"text":"und wenn ihr diese meine letzten Gebote tut, die ich euch gegeben habe, so werden die Pforten der Hölle euch nicht überwältigen; denn meine Gnade ist ausreichend für euch, und ihr werdet am letzten Tag emporgehoben werden."},{"verse":9,"text":"Und ich, Jesus Christus, euer Herr und euer Gott, habe es zu euch gesprochen, damit ich meine rechtschaffenen Absichten für die Menschenkinder verwirklichen kann. Amen."}]},{"chapter":18,"verses":[{"verse":1,"text":"Nun siehe, um dessentwillen, was du, mein Diener Oliver Cowdery, von mir zu wissen wünschst, gebe ich dir diese Worte:"},{"verse":2,"text":"Siehe, ich habe dir durch meinen Geist in vielen Fällen kundgetan, dass das, was du geschrieben hast, wahr ist; darum weißt du, dass es wahr ist."},{"verse":3,"text":"Und da du nun weißt, dass es wahr ist, siehe, so gebe ich dir das Gebot, dich auf das zu verlassen, was geschrieben ist;"},{"verse":4,"text":"denn darin ist alles niedergeschrieben, was die Grundlage meiner Kirche, meines Evangeliums und meines Felsens betrifft."},{"verse":5,"text":"Darum, wenn du meine Kirche auf der Grundlage meines Evangeliums und meines Felsens errichtest, werden die Pforten der Hölle dich nicht überwältigen."},{"verse":6,"text":"Siehe, die Welt wird reif im Übeltun; und es muss notwendigerweise sein, dass die Menschenkinder zur Umkehr aufgestachelt werden, die Anderen ebenso wie auch das Haus Israel."},{"verse":7,"text":"Da du nun durch die Hände meines Dieners Joseph Smith Jr. gemäß dem, was ich ihm geboten habe, getauft worden bist, hat er das vollbracht, was ich ihm geboten habe."},{"verse":8,"text":"Und nun, wundere dich nicht, dass ich ihn zu meinem eigenen Zweck berufen habe, einem Zweck, den ich kenne; wenn er darum im Halten meiner Gebote eifrig ist, so wird er zu ewigem Leben gesegnet sein; und sein Name ist Joseph."},{"verse":9,"text":"Und nun, Oliver Cowdery, spreche ich zu dir und auch zu David Whitmer in der Form eines Gebotes; denn siehe, ich gebiete allen Menschen überall, umzukehren, und ich spreche zu euch so wie zu meinem Apostel Paulus; denn ihr seid berufen, selbst mit derselben Berufung, mit der er berufen war."},{"verse":10,"text":"Denkt daran, die Seelen haben großen Wert in den Augen Gottes;"},{"verse":11,"text":"denn siehe, der Herr, euer Erlöser, erlitt den Tod im Fleische; darum hat er die Schmerzen aller Menschen gelitten, damit alle Menschen umkehren und zu ihm kommen können."},{"verse":12,"text":"Und er ist von den Toten wieder auferstanden, damit er alle Menschen zu sich führe, unter der Bedingung, dass sie umkehrten."},{"verse":13,"text":"Und wie groß ist seine Freude über die Seele, die umkehrt!"},{"verse":14,"text":"Darum seid ihr berufen, dieses Volk zur Umkehr zu rufen."},{"verse":15,"text":"Und wenn es so ist, dass ihr alle eure Tage arbeitet, um dieses Volk zur Umkehr zu rufen, und auch nur eine einzige Seele zu mir führt, wie groß wird eure Freude mit ihr im Reich meines Vaters sein!"},{"verse":16,"text":"Und nun, wenn eure Freude schon groß sein wird mit einer Seele, die ihr zu mir ins Reich meines Vaters geführt habt, wie groß wird eure Freude sein, wenn ihr viele Seelen zu mir führt!"},{"verse":17,"text":"Siehe, ihr habt mein Evangelium vor euch und meinen Felsen und meine Errettung."},{"verse":18,"text":"Bittet den Vater voll Glauben in meinem Namen, darauf vertrauend, dass ihr empfangen werdet, dann werdet ihr den Heiligen Geist haben, der alles kundtut, was für die Menschenkinder ratsam ist."},{"verse":19,"text":"Und wenn ihr nicht Glauben, Hoffnung und Nächstenliebe habt, könnt ihr nichts tun."},{"verse":20,"text":"Streitet gegen keine Kirche, außer es sei die Kirche des Teufels."},{"verse":21,"text":"Nehmt den Namen Christi auf euch, und redet die Wahrheit mit Ernsthaftigkeit."},{"verse":22,"text":"Und alle, die umkehren und sich in meinem Namen, nämlich Jesus Christus, taufen lassen und bis ans Ende ausharren, die werden errettet werden."},{"verse":23,"text":"Siehe, Jesus Christus ist der Name, der vom Vater gegeben ist, und es ist kein anderer Name gegeben, wodurch der Mensch errettet werden kann;"},{"verse":24,"text":"darum müssen alle Menschen den Namen auf sich nehmen, der vom Vater gegeben ist, denn mit diesem Namen werden sie am letzten Tag gerufen werden;"},{"verse":25,"text":"wenn sie darum den Namen nicht kennen, mit dem sie gerufen werden, können sie im Reich meines Vaters keinen Platz haben."},{"verse":26,"text":"Und nun siehe, es gibt noch andere, die berufen sind, mein Evangelium zu verkünden, den Anderen ebenso wie den Juden;"},{"verse":27,"text":"ja, nämlich zwölf; und die Zwölf sollen meine Jünger sein, und sie sollen meinen Namen auf sich nehmen; und die Zwölf sind diejenigen, die wünschen werden, meinen Namen mit voller Herzensabsicht auf sich zu nehmen."},{"verse":28,"text":"Und wenn sie meinen Namen mit voller Herzensabsicht auf sich zu nehmen wünschen, sind sie berufen, in alle Welt hinzugehen und mein Evangelium jedem Geschöpf zu predigen."},{"verse":29,"text":"Und sie sind es, die von mir ordiniert sind, in meinem Namen zu taufen, nämlich gemäß dem, was geschrieben steht;"},{"verse":30,"text":"und ihr habt das, was geschrieben steht, vor euch; darum müsst ihr es ausführen gemäß den Worten, die geschrieben stehen."},{"verse":31,"text":"Und nun spreche ich zu euch, den Zwölf: Siehe, meine Gnade ist ausreichend für euch; ihr müsst untadelig vor mir wandeln und nicht sündigen."},{"verse":32,"text":"Und siehe, ihr seid diejenigen, die von mir ordiniert sind, um Priester und Lehrer zu ordinieren, um mein Evangelium zu verkünden gemäß der Macht des Heiligen Geistes, die in euch ist, und gemäß den Berufungen und Gaben, die Gott den Menschen gibt;"},{"verse":33,"text":"und ich, Jesus Christus, euer Herr und euer Gott, habe es gesprochen."},{"verse":34,"text":"Diese Worte sind nicht von den Menschen, auch nicht von einem Menschen, sondern von mir; darum sollt ihr bezeugen, dass sie von mir sind und nicht von einem Menschen;"},{"verse":35,"text":"denn es ist meine Stimme, die sie zu euch redet; denn sie werden euch durch meinen Geist gegeben, und durch meine Macht könnt ihr sie einander vorlesen, und außer durch meine Macht könntet ihr sie nicht haben;"},{"verse":36,"text":"darum könnt ihr bezeugen, dass ihr meine Stimme vernommen habt und meine Worte kennt."},{"verse":37,"text":"Und nun siehe, ich gebe es dir, Oliver Cowdery, und auch David Whitmer, die Zwölf auszusuchen, die die Wünsche haben werden, wovon ich gesprochen habe,"},{"verse":38,"text":"und an ihren Wünschen und ihren Werken werdet ihr sie erkennen."},{"verse":39,"text":"Und wenn ihr sie gefunden habt, sollt ihr ihnen dieses hier zeigen."},{"verse":40,"text":"Und ihr sollt niederfallen und den Vater in meinem Namen anbeten."},{"verse":41,"text":"Und ihr müsst der Welt predigen, nämlich: Ihr müsst umkehren und euch taufen lassen, im Namen Jesu Christi;"},{"verse":42,"text":"denn alle Menschen müssen umkehren und sich taufen lassen, und nicht nur die Männer, sondern auch die Frauen und diejenigen Kinder, die die Jahre der Verantwortlichkeit erreicht haben."},{"verse":43,"text":"Und nun, nachdem ihr dies empfangen habt, müsst ihr in allem meine Gebote halten,"},{"verse":44,"text":"und durch eure Hände werde ich unter den Menschenkindern ein wunderbares Werk bewirken, sodass viele sich ihrer Sünden bewusst werden, damit sie zur Umkehr kommen mögen und damit sie ins Reich meines Vaters kommen mögen."},{"verse":45,"text":"Darum stehen die Segnungen, die ich euch gebe, über allem."},{"verse":46,"text":"Und wenn ihr, nachdem ihr dies empfangen habt, meine Gebote nicht haltet, könnt ihr nicht im Reich meines Vaters errettet werden."},{"verse":47,"text":"Siehe, ich, Jesus Christus, euer Herr und euer Gott und euer Erlöser, habe es durch die Macht meines Geistes gesprochen. Amen."}]},{"chapter":19,"verses":[{"verse":1,"text":"Ich bin Alpha und Omega, Christus, der Herr; ja, ich bin es selbst, der Anfang und das Ende, der Erlöser der Welt."},{"verse":2,"text":"Ich habe den Willen dessen vollbracht und vollendet, dessen ich bin, nämlich des Vaters, in Bezug auf mich – und ich habe dies getan, damit ich mir alles untertan mache –"},{"verse":3,"text":"ich habe alle Macht inne, ja, auch für die Vernichtung des Satans und seiner Werke am Ende der Welt und den letzten großen Tag des Gerichts, das ich über ihre Bewohner kommen lassen werde, wenn ich jeden Menschen gemäß seinen Werken und den Taten, die er getan hat, richten werde."},{"verse":4,"text":"Und gewiss muss jeder Mensch umkehren oder leiden, denn ich, Gott, bin endlos."},{"verse":5,"text":"Darum widerrufe ich nicht die Richtersprüche, die ich kommen lassen werde, sondern Weh wird kommen, Weinen, Wehklagen und Zähneknirschen, nämlich über diejenigen, die zu meiner linken Hand gefunden werden."},{"verse":6,"text":"Doch steht nicht geschrieben, dass diese Qual kein Ende haben wird, sondern es steht geschrieben endlose Qual."},{"verse":7,"text":"Weiter steht geschrieben ewige Verdammnis; darum ist diese Schriftstelle deutlicher als andere, damit sie ganz und gar um der Herrlichkeit meines Namens willen auf das Herz der Menschenkinder einwirken kann."},{"verse":8,"text":"Darum werde ich euch dieses Geheimnis erklären, denn es ist gut, wenn ihr es wisst, ebenso wie meine Apostel."},{"verse":9,"text":"Ich spreche zu euch, die ihr in dieser Sache erwählt seid, wie zu einem, damit ihr in meine Ruhe eingehen könnt."},{"verse":10,"text":"Denn siehe, das Geheimnis des Göttlichen, wie groß ist es doch! Denn siehe, ich bin endlos, und die Strafe, die aus meiner Hand kommt, ist endlose Strafe, denn Endlos ist mein Name. Darum:"},{"verse":11,"text":"Ewige Strafe ist Gottes Strafe."},{"verse":12,"text":"Endlose Strafe ist Gottes Strafe."},{"verse":13,"text":"Darum gebiete ich dir, umzukehren und die Gebote zu halten, die du in meinem Namen durch die Hand meines Dieners Joseph Smith Jr. empfangen hast;"},{"verse":14,"text":"und durch meine Allmacht hast du sie empfangen;"},{"verse":15,"text":"darum gebiete ich dir umzukehren – kehre um, sonst schlage ich dich mit der Rute meines Mundes und mit meinem Grimm und mit meinem Zorn, und deine Leiden werden schmerzlich – wie schmerzlich, das weißt du nicht, wie außerordentlich, das weißt du nicht, ja, wie schwer zu ertragen, das weißt du nicht."},{"verse":16,"text":"Denn siehe, ich, Gott, habe das für alle gelitten, damit sie nicht leiden müssen, sofern sie umkehren;"},{"verse":17,"text":"aber falls sie nicht umkehren, müssen sie leiden so wie ich,"},{"verse":18,"text":"und dieses Leiden ließ mich, selbst Gott, den Größten von allen, der Schmerzen wegen zittern und aus jeder Pore bluten und an Leib und Geist leiden – und ich wollte den bitteren Kelch nicht trinken und zurückschrecken –"},{"verse":19,"text":"doch Ehre sei dem Vater, und ich trank davon und vollendete meine Vorbereitungen für die Menschenkinder."},{"verse":20,"text":"Darum gebiete ich dir abermals, umzukehren, sonst demütige ich dich mit meiner Allmacht; und dass du deine Sünden bekennst, sonst erleidest du diese Strafen, wovon ich gesprochen habe, wovon du im kleinsten, ja, selbst im geringsten Maße gekostet hast zu der Zeit, da ich meinen Geist zurückzog."},{"verse":21,"text":"Und ich gebiete dir, nichts anderes als nur Umkehr zu predigen und dies der Welt nicht zu zeigen, bis es nach meiner Weisheit ist."},{"verse":22,"text":"Denn sie können noch kein Fleisch vertragen, sondern Milch müssen sie bekommen; darum dürfen sie hiervon nichts wissen, sonst gehen sie zugrunde."},{"verse":23,"text":"Lerne von mir und höre auf meine Worte; wandle in der Sanftmut meines Geistes, dann wirst du Frieden haben in mir."},{"verse":24,"text":"Ich bin Jesus Christus; ich bin nach dem Willen des Vaters gekommen, und ich tue seinen Willen."},{"verse":25,"text":"Und weiter gebiete ich dir: Du sollst nicht begehren deines Nächsten Frau noch deinem Nächsten nach dem Leben trachten."},{"verse":26,"text":"Und weiter gebiete ich dir: Du sollst nicht deinen eigenen Besitz begehren, sondern davon freigebig für den Druck des Buches Mormon geben, welches die Wahrheit und das Wort Gottes enthält –"},{"verse":27,"text":"welches mein Wort an die Anderen ist, damit es bald an die Juden gelange, von denen die Lamaniten ein Überrest sind, damit sie das Evangelium glauben und nicht nach einem Messias ausschauen, der kommen soll, der doch schon gekommen ist."},{"verse":28,"text":"Und weiter gebiete ich dir: Du sollst sowohl laut als auch in deinem Herzen beten, ja, sowohl vor der Welt als auch im Verborgenen, sowohl in der Öffentlichkeit als auch, wenn du allein bist."},{"verse":29,"text":"Und du sollst frohe Nachricht verkünden, ja, verkündige sie auf den Bergen und an jedem hohen Ort und unter jedem Volk, das zu besuchen dir erlaubt sein wird."},{"verse":30,"text":"Und du sollst es in aller Demut tun, im Vertrauen auf mich, und die Schmäher nicht wiederschmähen."},{"verse":31,"text":"Und von Lehrsätzen sollst du nicht sprechen, sondern du sollst Umkehr verkünden und Glauben an den Erretter und Sündenvergebung durch die Taufe und durch Feuer, ja, nämlich den Heiligen Geist."},{"verse":32,"text":"Siehe, dies ist ein großes Gebot und das letzte, das ich dir in dieser Sache gebe; denn dies soll dir für deinen täglichen Wandel genügen, ja, bis ans Ende deines Lebens."},{"verse":33,"text":"Und Elend wirst du empfangen, wenn du diese Ratschläge missachtest, ja, sogar deine eigene Vernichtung und die deines Eigentums."},{"verse":34,"text":"Gib einen Teil deines Eigentums hin, ja, nämlich einen Teil deines Landes, außer was dem Unterhalt deiner Familie dient."},{"verse":35,"text":"Bezahle die Schulden, die du beim Drucker eingegangen bist. Befreie dich aus der Knechtschaft."},{"verse":36,"text":"Verlasse dein Haus und Heim, außer wenn du den Wunsch hast, deine Familie zu sehen,"},{"verse":37,"text":"und rede freimütig zu allen, ja, predige, ermahne, verkünde die Wahrheit, nämlich mit lauter Stimme, mit dem Ton der Freude, und rufe: Hosanna, hosanna, gesegnet sei der Name Gottes, des Herrn!"},{"verse":38,"text":"Bete immer, dann werde ich meinen Geist über dich ausgießen, und groß wird deine Segnung sein – ja, selbst größer, als wenn du Schätze der Erde erhieltest und Verweslichkeit im gleichen Ausmaß."},{"verse":39,"text":"Siehe, kannst du dies lesen, ohne dich zu freuen und dein Herz vor Freude zu erheben?"},{"verse":40,"text":"Oder kannst du noch länger als blinder Führer umherlaufen?"},{"verse":41,"text":"Oder kannst du demütig und sanftmütig sein und dich vor mir weise verhalten? Ja, komm zu mir, deinem Erretter. Amen."}]},{"chapter":20,"verses":[{"verse":1,"text":"Die Entstehung der Kirche Christi in diesen letzten Tagen, nämlich eintausendachthundertdreißig Jahre nachdem unser Herr und Erretter Jesus Christus im Fleische gekommen ist; in Übereinstimmung mit den Gesetzen unseres Landes ordnungsgemäß gegründet und aufgerichtet, dem Willen und den Geboten Gottes gemäß, im vierten Monat und am sechsten Tag des Monats, der April genannt wird –"},{"verse":2,"text":"und diese Gebote ergingen an Joseph Smith Jr., der von Gott berufen und zu einem Apostel Jesu Christi ordiniert wurde, dass er der erste Älteste dieser Kirche sei,"},{"verse":3,"text":"sowie an Oliver Cowdery, der ebenfalls von Gott berufen wurde, ein Apostel Jesu Christi, dass er der zweite Älteste dieser Kirche sei, und unter seiner Hand ordiniert wurde;"},{"verse":4,"text":"und dies gemäß der Gnade unseres Herrn und Erretters Jesus Christus, und ihm sei alle Herrlichkeit, jetzt und auch immerdar. Amen."},{"verse":5,"text":"Nachdem es diesem ersten Ältesten wahrhaft kundgetan worden war, dass er Vergebung seiner Sünden empfangen hatte, verstrickte er sich wiederum in die Nichtigkeiten der Welt;"},{"verse":6,"text":"aber nachdem er umgekehrt war und sich durch Glauben aufrichtig gedemütigt hatte, nahm Gott sich seiner durch einen heiligen Engel an, dessen Antlitz wie ein Blitz leuchtete und dessen Gewand rein und weiß war, weißer als alles andere,"},{"verse":7,"text":"und gab ihm Gebote, die ihn inspirierten,"},{"verse":8,"text":"und gab ihm Macht aus der Höhe, durch die Mittel, die zuvor bereitgestellt worden waren, um das Buch Mormon zu übersetzen,"},{"verse":9,"text":"und dieses enthält den Bericht eines gefallenen Volkes und die Fülle des Evangeliums Jesu Christi für die Anderen und auch für die Juden;"},{"verse":10,"text":"es ist durch Inspiration gegeben worden und wird anderen durch den Dienst von Engeln bestätigt und wird der Welt von diesen verkündet –"},{"verse":11,"text":"und dies beweist der Welt, dass die heiligen Schriften wahr sind und dass Gott Menschen inspiriert und sie zu seinem heiligen Werk beruft, in diesem Zeitalter und dieser Generation ebenso wie in den Generationen vor alters,"},{"verse":12,"text":"und zeigt damit, dass er derselbe Gott ist, gestern, heute und immerdar. Amen."},{"verse":13,"text":"Da nun die Welt so große Zeugnisse hat, wird sie danach gerichtet werden, ja, alle, die später noch Kenntnis von diesem Werk erlangen."},{"verse":14,"text":"Und diejenigen, die es im Glauben annehmen und Rechtschaffenheit bewirken, werden eine Krone des ewigen Lebens empfangen,"},{"verse":15,"text":"aber diejenigen, die ihr Herz in Unglauben verhärten und es verwerfen, denen wird sich das zu ihrer eigenen Schuldigsprechung wenden;"},{"verse":16,"text":"denn Gott, der Herr, hat es gesagt, und wir, die Ältesten der Kirche, haben vernommen und geben Zeugnis für die Worte der herrlichen Majestät in der Höhe, und ihr sei Herrlichkeit für immer und immer. Amen."},{"verse":17,"text":"Durch dies alles wissen wir, dass es einen Gott im Himmel gibt, der unbegrenzt und ewig ist, vom Immerwährenden zum Immerwährenden derselbe unveränderliche Gott, der Gestalter des Himmels und der Erde und all dessen, was darinnen ist,"},{"verse":18,"text":"und dass er den Menschen erschaffen hat, männlich und weiblich, als sein eigenes Abbild, und ihm selbst ähnlich hat er sie erschaffen,"},{"verse":19,"text":"und gab ihnen Gebote, dass sie ihn, den einzigen lebendigen und wahren Gott, lieben und ihm dienen sollen und dass er das einzige Wesen sein solle, das sie anbeten sollten."},{"verse":20,"text":"Aber durch die Übertretung dieser heiligen Gesetze wurde der Mensch sinnlich und teuflisch und wurde zum gefallenen Menschen."},{"verse":21,"text":"Darum gab der allmächtige Gott seinen einziggezeugten Sohn, wie es in jenen Schriften geschrieben steht, die von ihm gegeben worden sind."},{"verse":22,"text":"Er litt Versuchungen, schenkte ihnen aber keine Beachtung."},{"verse":23,"text":"Er wurde gekreuzigt, starb und auferstand am dritten Tag"},{"verse":24,"text":"und fuhr in den Himmel auf, sich hinzusetzen zur rechten Hand des Vaters, um gemäß dem Willen des Vaters mit Allmacht zu herrschen,"},{"verse":25,"text":"damit alle, die glauben und sich in seinem heiligen Namen taufen lassen und im Glauben bis ans Ende ausharren, errettet werden können –"},{"verse":26,"text":"nicht nur diejenigen, die glaubten, nachdem er in der Mitte der Zeit im Fleische gekommen war, sondern alle jene von Anfang an, nämlich alle, die waren, bevor er kam, die den Worten der heiligen Propheten glaubten, welche redeten, wie sie durch die Gabe des Heiligen Geistes inspiriert wurden, die in allem wahrhaft für ihn Zeugnis ablegten, sollen ewiges Leben haben;"},{"verse":27,"text":"ebenso diejenigen, die danach kämen, die an die Gaben und Berufungen Gottes durch den Heiligen Geist glauben würden, welcher Zeugnis gibt für den Vater und den Sohn;"},{"verse":28,"text":"und der Vater, der Sohn und der Heilige Geist sind ein Gott, unbegrenzt und ewig, ohne Ende. Amen."},{"verse":29,"text":"Und wir wissen, dass alle Menschen umkehren und an den Namen Jesu Christi glauben und den Vater in seinem Namen anbeten und im Glauben an seinen Namen bis ans Ende ausharren müssen, sonst können sie nicht im Reich Gottes errettet werden."},{"verse":30,"text":"Und wir wissen, dass Rechtfertigung durch die Gnade unseres Herrn und Erretters Jesus Christus gerecht und wahr ist,"},{"verse":31,"text":"und wir wissen auch, dass Heiligung durch die Gnade unseres Herrn und Erretters Jesus Christus gerecht und wahr ist, für alle diejenigen, die Gott lieben und ihm mit all ihrer Macht, ganzem Sinn und aller Kraft dienen."},{"verse":32,"text":"Aber es ist möglich, dass der Mensch aus der Gnade fallen und den lebendigen Gott verlassen kann,"},{"verse":33,"text":"darum soll die Kirche achtgeben und immer beten, damit sie nicht in Versuchung fallen,"},{"verse":34,"text":"ja, und selbst diejenigen, die geheiligt sind, sollen auch achtgeben."},{"verse":35,"text":"Und wir wissen, dass dies alles wahr ist und im Einklang mit den Offenbarungen des Johannes, weder hinzufügend noch wegnehmend von der Prophezeiung seines Buches, den heiligen Schriften oder den Offenbarungen Gottes, die später noch durch die Gabe und Macht des Heiligen Geistes, die Stimme Gottes oder den Dienst von Engeln ergehen werden."},{"verse":36,"text":"Und Gott, der Herr, hat es gesagt; und Ehre, Macht und Herrlichkeit komme seinem heiligen Namen zu, jetzt und auch immerdar. Amen."},{"verse":37,"text":"Und weiter, als Gebot für die Kirche über die Art und Weise der Taufe: Alle diejenigen, die sich vor Gott demütigen und getauft zu werden wünschen und mit reuigem Herzen und zerknirschtem Geist vortreten und vor der Kirche bezeugen, dass sie wahrhaftig von all ihren Sünden umgekehrt sind und willens sind, den Namen Jesu Christi auf sich zu nehmen, mit der Entschlossenheit, ihm bis ans Ende zu dienen, und durch ihre Werke wahrhaft kundtun, dass sie vom Geist Christi zur Vergebung ihrer Sünden empfangen haben, sollen durch die Taufe in seine Kirche aufgenommen werden."},{"verse":38,"text":"Die Pflichten der Ältesten, Priester, Lehrer, Diakone und Mitglieder der Kirche Christi: Ein Apostel ist ein Ältester, und es ist seine Berufung, zu taufen"},{"verse":39,"text":"und andere zum Ältesten, Priester, Lehrer oder Diakon zu ordinieren"},{"verse":40,"text":"und Brot und Wein – die Symbole des Fleisches und Blutes Christi – zu segnen"},{"verse":41,"text":"und diejenigen, die durch die Taufe in die Kirche kommen, durch Händeauflegen zu konfirmieren, zur Taufe mit Feuer und dem Heiligen Geist, gemäß den Schriften,"},{"verse":42,"text":"und zu lehren, zu erläutern, zu ermahnen, zu taufen und über die Kirche zu wachen"},{"verse":43,"text":"und die Mitglieder der Kirche durch Händeauflegen zu konfirmieren und den Heiligen Geist zu spenden"},{"verse":44,"text":"und in allen Versammlungen die Führung zu übernehmen."},{"verse":45,"text":"Die Ältesten sollen die Versammlungen leiten, wie sie vom Heiligen Geist geführt werden, gemäß den Geboten und Offenbarungen Gottes."},{"verse":46,"text":"Die Pflicht des Priesters ist es, zu predigen, zu lehren, zu erläutern, zu ermahnen und zu taufen und das Abendmahl zu segnen"},{"verse":47,"text":"und alle Mitglieder zu Hause zu besuchen und sie zu ermahnen, dass sie sowohl laut als auch im Verborgenen beten und allen Pflichten in der Familie nachkommen."},{"verse":48,"text":"Und er kann auch andere zum Priester, Lehrer oder Diakon ordinieren."},{"verse":49,"text":"Und er soll in den Versammlungen die Führung übernehmen, wenn kein Ältester anwesend ist;"},{"verse":50,"text":"aber wenn ein Ältester anwesend ist, soll er nur predigen, lehren, erläutern, ermahnen und taufen"},{"verse":51,"text":"und alle Mitglieder zu Hause besuchen, um sie zu ermahnen, dass sie sowohl laut als auch im Verborgenen beten und allen Pflichten in der Familie nachkommen."},{"verse":52,"text":"In allen diesen Pflichten soll der Priester dem Ältesten behilflich sein, wenn es die Umstände erfordern."},{"verse":53,"text":"Die Pflicht des Lehrers ist es, immer über die Mitglieder der Kirche zu wachen und bei ihnen zu sein und sie zu stärken"},{"verse":54,"text":"und zu sehen, dass es in der Kirche kein Übeltun gibt, auch keine Härte gegeneinander, weder Lügen noch Verleumden noch übles Gerede,"},{"verse":55,"text":"und zu sehen, dass sich die Gemeinde oft versammelt, und auch zu sehen, dass alle Mitglieder ihre Pflicht erfüllen."},{"verse":56,"text":"Und er soll in Abwesenheit eines Ältesten oder Priesters in den Versammlungen die Führung übernehmen,"},{"verse":57,"text":"und ihm sollen immer, in allen seinen Pflichten in der Kirche, die Diakone behilflich sein, wenn es die Umstände erfordern."},{"verse":58,"text":"Aber weder Lehrer noch Diakone haben die Vollmacht, zu taufen, das Abendmahl zu segnen oder die Hände aufzulegen;"},{"verse":59,"text":"sie sollen aber warnen, erläutern, ermahnen und lehren und alle einladen, zu Christus zu kommen."},{"verse":60,"text":"Jeder Älteste, Priester, Lehrer oder Diakon soll gemäß den Gaben und Berufungen, die Gott ihm gibt, ordiniert werden, und er soll durch die Macht des Heiligen Geistes ordiniert werden, die in demjenigen ist, der ihn ordiniert."},{"verse":61,"text":"Die verschiedenen Ältesten, die diese Kirche Christi bilden, sollen sich alle drei Monate einmal zu einer Konferenz versammeln oder aber von Zeit zu Zeit, wie die besagten Konferenzen es anordnen oder bestimmen;"},{"verse":62,"text":"und die besagten Konferenzen sollen sich mit allen Angelegenheiten der Kirche befassen, die zu der Zeit erledigt werden müssen."},{"verse":63,"text":"Die Ältesten sollen ihren Berechtigungsschein von anderen Ältesten, nach Abstimmung in der Gemeinde, der sie angehören, oder von den Konferenzen empfangen."},{"verse":64,"text":"Jeder Priester, Lehrer oder Diakon, der von einem Priester ordiniert wird, kann von diesem zu der Zeit eine Bestätigung entgegennehmen, und wenn diese Bestätigung einem Ältesten vorgelegt wird, gibt sie ihm ein Recht auf einen Berechtigungsschein, der ihn bevollmächtigt, die Pflichten seiner Berufung zu erfüllen, oder er kann ihn von einer Konferenz empfangen."},{"verse":65,"text":"Niemand soll zu irgendeinem Amt in dieser Kirche ordiniert werden, wo es einen ordnungsgemäß organisierten Zweig derselben gibt, ohne die Abstimmung in jener Gemeinde;"},{"verse":66,"text":"aber die präsidierenden Ältesten, reisenden Bischöfe, Hohen Räte, Hohen Priester und Ältesten haben das Recht, dort zu ordinieren, wo es keinen Zweig der Kirche gibt, sodass man zur Abstimmung aufrufen könnte."},{"verse":67,"text":"Jeder Präsident des Hohen Priestertums (oder präsidierende Älteste), Bischof, Hoher Rat und Hoher Priester soll nach Weisung eines Hoherates oder einer Generalkonferenz ordiniert werden."},{"verse":68,"text":"Die Pflicht der Mitglieder, nachdem sie durch die Taufe aufgenommen worden sind: Die Ältesten oder Priester sollen genügend Zeit haben, ihnen alles, was die Kirche Christi betrifft, so zu erläutern, dass sie davon Verständnis erlangen, ehe sie vom Abendmahl nehmen und durch das Händeauflegen der Ältesten konfirmiert werden, damit alles in Ordnung geschehe."},{"verse":69,"text":"Und die Mitglieder sollen vor der Kirche und auch vor den Ältesten durch gottesfürchtigen Wandel und Umgang kundtun, dass sie dessen würdig sind, damit es Werke und Glauben gebe in Übereinstimmung mit den heiligen Schriften – indem sie in Heiligkeit vor dem Herrn wandeln."},{"verse":70,"text":"Jedes Mitglied der Kirche Christi, das Kinder hat, soll sie vor die Gemeinde zu den Ältesten bringen, und diese sollen ihnen im Namen Jesu Christi die Hände auflegen und sie in seinem Namen segnen."},{"verse":71,"text":"Niemand kann in die Kirche Christi aufgenommen werden, wenn er nicht die Jahre der Verantwortlichkeit vor Gott erreicht hat und zur Umkehr fähig ist."},{"verse":72,"text":"Die Taufe ist an allen, die umkehren, auf die folgende Weise zu vollziehen:"},{"verse":73,"text":"Derjenige, der von Gott berufen ist und von Jesus Christus Vollmacht hat zu taufen, soll mit demjenigen oder derjenigen, der oder die zur Taufe erschienen ist, in das Wasser hinabsteigen und, indem er ihn oder sie beim Namen nennt, sprechen: Beauftragt von Jesus Christus, taufe ich dich im Namen des Vaters und des Sohnes und des Heiligen Geistes. Amen."},{"verse":74,"text":"Dann soll er ihn oder sie im Wasser untertauchen und wieder aus dem Wasser hervorkommen."},{"verse":75,"text":"Es ist ratsam, dass die Gemeinde sich oft versammelt, um zum Gedächtnis des Herrn Jesus Brot und Wein zu sich zu nehmen;"},{"verse":76,"text":"und der Älteste oder Priester soll es segnen; und auf die folgende Art und Weise soll er es segnen: Er soll mit der Gemeinde niederknien und den Vater in feierlichem Gebet anrufen, nämlich:"},{"verse":77,"text":"O Gott, ewiger Vater, wir bitten dich im Namen deines Sohnes, Jesus Christus, segne und heilige dieses Brot für die Seele all derer, die davon nehmen, damit sie zum Gedächtnis des Leibes deines Sohnes essen und dir, o Gott, ewiger Vater, bezeugen, dass sie willens sind, den Namen deines Sohnes auf sich zu nehmen und immer an ihn zu denken und seine Gebote, die er ihnen gegeben hat, zu halten, damit sein Geist immer mit ihnen sei. Amen."},{"verse":78,"text":"Die Art und Weise, den Wein zu segnen: Er soll auch den Kelch nehmen und sprechen:"},{"verse":79,"text":"O Gott, ewiger Vater, wir bitten dich im Namen deines Sohnes, Jesus Christus, segne und heilige diesen Wein für die Seele all derer, die davon trinken, damit sie es zum Gedächtnis des Blutes deines Sohnes tun, das für sie vergossen wurde, damit sie dir, o Gott, ewiger Vater, bezeugen, dass sie immer an ihn denken, damit sein Geist mit ihnen sei. Amen."},{"verse":80,"text":"Mit jedem Mitglied der Kirche Christi, das eine Übertretung begeht oder bei einer Verfehlung angetroffen wird, soll man verfahren, wie die Schriften es anordnen."},{"verse":81,"text":"Es soll die Pflicht der verschiedenen Gemeinden, die die Kirche Christi bilden, sein, einen oder mehrere von ihren Lehrern zur Teilnahme an den verschiedenen Konferenzen zu entsenden, die von den Ältesten der Kirche abgehalten werden,"},{"verse":82,"text":"mit einer Liste der Namen der verschiedenen Mitglieder, die sich seit der letzten Konferenz mit der Kirche vereinigt haben, oder durch die Hand eines Priesters zu übersenden, sodass von einem der Ältesten, den die anderen Ältesten von Zeit zu Zeit bestimmen, ein richtiges Verzeichnis aller Namen der gesamten Kirche in einem Buch geführt werden kann,"},{"verse":83,"text":"und auch, wenn jemand aus der Kirche ausgestoßen worden ist, damit sein Name aus dem allgemeinen Namensverzeichnis der Kirche gelöscht werde."},{"verse":84,"text":"Alle Mitglieder, die von der Gemeinde, wo sie wohnen, wegziehen, können, wenn sie zu einer Gemeinde gehen, wo sie unbekannt sind, einen Brief mitnehmen, worin bestätigt wird, dass sie ordnungsgemäß Mitglieder und in gutem Stand sind; diese Bestätigung kann von jedem Ältesten oder Priester unterschrieben werden, wenn das Mitglied, das den Brief erhalten soll, mit dem Ältesten oder Priester persönlich bekannt ist, oder sie kann von den Lehrern oder Diakonen der Kirche unterschrieben werden."}]},{"chapter":21,"verses":[{"verse":1,"text":"Siehe, ein Bericht soll unter euch geführt werden, und darin sollst du ein Seher genannt werden, ein Übersetzer, ein Prophet, ein Apostel Jesu Christi, ein Ältester der Kirche durch den Willen Gottes des Vaters und die Gnade eures Herrn Jesus Christus,"},{"verse":2,"text":"denn du wirst vom Heiligen Geist inspiriert, ihre Grundlage zu legen und sie zu dem höchst heiligen Glauben aufzubauen."},{"verse":3,"text":"Und diese Kirche wurde im Jahr eures Herrn achtzehnhundertdreißig, im vierten Monat und am sechsten Tag des Monats, der April heißt, gegründet und aufgerichtet."},{"verse":4,"text":"Darum sollst du, nämlich die Kirche, all seinen Worten und Geboten Beachtung schenken, die er dir geben wird, wie er sie empfängt, in aller Heiligkeit vor mir wandelnd;"},{"verse":5,"text":"denn sein Wort sollt ihr empfangen, als sei es aus meinem eigenen Mund, voller Geduld und Glauben."},{"verse":6,"text":"Denn wenn ihr dies alles tut, werden die Pforten der Hölle euch nicht überwältigen; ja, und Gott, der Herr, wird die Mächte der Finsternis vor euch zerstreuen und die Himmel zu eurem Guten und um der Herrlichkeit seines Namens willen erbeben lassen."},{"verse":7,"text":"Denn so spricht Gott, der Herr: Ihn habe ich inspiriert, die Sache Zions mit großer Macht zum Guten zu bewegen, und seinen Eifer kenne ich, und seine Gebete habe ich vernommen."},{"verse":8,"text":"Ja, sein Weinen um Zion habe ich gesehen, und ich werde machen, dass er nicht länger darum trauert; denn seine Tage des Freuens sind gekommen, indem ihm seine Sünden vergeben sind und es offenkundig wird, dass mein Segen auf seinen Werken ruht."},{"verse":9,"text":"Denn siehe, ich werde alle diejenigen, die in meinem Weingarten arbeiten, mit einem mächtigen Segen segnen, und sie werden an seine Worte glauben, die ihm durch mich vom Tröster gegeben werden, und dieser tut kund, dass Jesus von sündigen Menschen für die Sünden der Welt gekreuzigt worden ist, ja, damit dem zerknirschten Herzen die Sünden vergeben werden."},{"verse":10,"text":"Darum erscheint es mir angebracht, dass er von dir, Oliver Cowdery, mein Apostel, ordiniert werde;"},{"verse":11,"text":"und dies ist für dich eine Verordnung, dass du unter seiner Hand ein Ältester bist, und er ist für dich der erste, auf dass du für diese Kirche Christi, die meinen Namen trägt, ein Ältester seist –"},{"verse":12,"text":"und der erste Prediger dieser Kirche für die Kirche und vor der Welt, ja, vor den Anderen; ja, und so spricht Gott, der Herr: Sieh, sieh! auch für die Juden. Amen."}]},{"chapter":22,"verses":[{"verse":1,"text":"Siehe, ich sage euch: Ich habe alle alten Bündnisse in dieser Hinsicht vergehen lassen; und dies ist ein neuer und ein immerwährender Bund, nämlich jener, der von Anfang an war."},{"verse":2,"text":"Darum, wenn jemand auch hundertmal getauft worden sein sollte, so nützt es ihm nichts, denn ihr könnt weder durch das Gesetz des Mose noch durch eure toten Werke durch die enge Pforte eintreten."},{"verse":3,"text":"Denn wegen eurer toten Werke habe ich diesen letzten Bund und diese Kirche für mich aufrichten lassen, ja, wie in alten Tagen."},{"verse":4,"text":"Darum tretet durch die Pforte ein, wie ich geboten habe, und trachtet nicht, eurem Gott Rat zu erteilen. Amen."}]},{"chapter":23,"verses":[{"verse":1,"text":"Siehe, ich spreche einige Worte zu dir, Oliver. Siehe, du bist gesegnet und bist unter keinem Schuldspruch. Aber hüte dich vor Stolz, damit du nicht in Versuchung gerätst."},{"verse":2,"text":"Tue deine Berufung für die Kirche und auch vor der Welt kund, dann wird dein Herz aufgetan werden, um fortan und für immer die Wahrheit zu predigen. Amen."},{"verse":3,"text":"Siehe, ich spreche einige Worte zu dir, Hyrum; denn auch du bist unter keinem Schuldspruch, und dein Herz ist aufgetan und deine Zunge gelöst; und deine Berufung ist das Ermahnen und dass du beständig die Kirche stärkst. Darum ist die Kirche für immer deine Pflicht, und dies wegen deiner Familie. Amen."},{"verse":4,"text":"Siehe, ich spreche einige Worte zu dir, Samuel; denn auch du bist unter keinem Schuldspruch, und deine Berufung ist das Ermahnen und dass du die Kirche stärkst; und du bist jetzt noch nicht berufen, vor der Welt zu predigen. Amen."},{"verse":5,"text":"Siehe, ich spreche einige Worte zu dir, Joseph; denn auch du bist unter keinem Schuldspruch, und deine Berufung ist ebenfalls das Ermahnen und dass du die Kirche stärkst; und das ist deine Pflicht fortan und für immer. Amen."},{"verse":6,"text":"Siehe, ich tue dir, Joseph Knight, mit diesen Worten kund, dass du dein Kreuz auf dich nehmen musst, was bedeutet, du musst laut beten, sowohl vor der Welt als auch im Verborgenen und in deiner Familie und bei deinen Freunden und an allen Orten."},{"verse":7,"text":"Und siehe, es ist deine Pflicht, dich mit der wahren Kirche zu vereinigen und dein Reden beständig dem Ermahnen zu widmen, damit du den Lohn des Arbeiters empfangen kannst. Amen."}]},{"chapter":24,"verses":[{"verse":1,"text":"Siehe, du wurdest berufen und erwählt, das Buch Mormon zu schreiben und meinen geistlichen Dienst zu tun; und ich habe dich aus deinen Bedrängnissen emporgehoben und habe dir Rat gegeben, sodass du von all deinen Feinden befreit worden bist, und du bist aus der Macht des Satans und aus Finsternis befreit worden!"},{"verse":2,"text":"Doch gibt es für dich in deinen Übertretungen keine Entschuldigung; doch gehe deines Weges und sündige nicht mehr."},{"verse":3,"text":"Mache dein Amt groß; und wenn du deine Felder eingesät und sie gesichert hast, begib dich schnell zu den Gemeinden in Colesville, Fayette und Manchester, und sie sollen für dich sorgen; und ich will sie sowohl geistig als auch zeitlich segnen;"},{"verse":4,"text":"wenn sie dich aber nicht empfangen, schicke ich auf sie einen Fluch statt eines Segens."},{"verse":5,"text":"Und du sollst auch weiterhin Gott in meinem Namen anrufen und das niederschreiben, was dir vom Tröster gegeben wird, und der Kirche alle Schriften erläutern."},{"verse":6,"text":"Und es wird dir im selben Augenblick eingegeben werden, was du reden und schreiben sollst, und sie sollen es vernehmen, sonst schicke ich ihnen einen Fluch statt eines Segens."},{"verse":7,"text":"Denn du sollst dein ganzes Dienen Zion widmen, und darin wirst du Kraft haben."},{"verse":8,"text":"Sei geduldig in Bedrängnissen, denn du wirst viele haben; aber ertrage sie, denn sieh, ich bin mit dir, ja, bis ans Ende deiner Tage."},{"verse":9,"text":"Und in zeitlichen Arbeiten wirst du keine Kraft haben, denn das ist nicht deine Berufung. Widme dich deiner Berufung, und dann wirst du haben, womit du dein Amt groß machen und alle Schriften erläutern kannst, und fahre fort, die Hände aufzulegen und die Gemeinden zu konfirmieren."},{"verse":10,"text":"Und dein Bruder Oliver soll fortfahren, meinen Namen vor der Welt und auch vor der Kirche zu bezeugen. Und er soll nicht meinen, er könne in meiner Sache genug sagen; und sieh, ich bin mit ihm bis ans Ende."},{"verse":11,"text":"In mir soll er Herrlichkeit haben und nicht aus sich selbst, ob in Schwäche oder in Stärke, ob geknechtet oder frei;"},{"verse":12,"text":"und zu allen Zeiten und an allen Orten soll er den Mund auftun und mein Evangelium wie mit der Stimme einer Posaune verkünden, ja, Tag und Nacht. Und ich will ihm Kraft geben, wie sie unter Menschen unbekannt ist."},{"verse":13,"text":"Verlangt keine Wundertaten, außer ich gebiete es euch, außer wenn ihr Teufel austreibt, Kranke heilt sowie gegen giftige Schlangen und gegen tödliche Gifte;"},{"verse":14,"text":"und dies alles sollt ihr nicht tun, außer wenn diejenigen, die den Wunsch danach haben, es von euch verlangen, damit sich die Schriften erfüllen; denn ihr sollt so handeln, wie es geschrieben steht."},{"verse":15,"text":"Und wo auch immer ihr eintretet, und man empfängt euch nicht in meinem Namen, da sollt ihr einen Fluch statt eines Segens hinterlassen, indem ihr zum Zeugnis gegen sie den Staub von euren Füßen schüttelt und eure Füße am Wegesrand säubert."},{"verse":16,"text":"Und es wird sich begeben: Wer auch immer mit Gewalt Hand an euch legt, dem gebietet in meinem Namen, er solle geschlagen werden; und siehe, ich werde ihn gemäß euren Worten zu der von mir selbst bestimmten Zeit schlagen."},{"verse":17,"text":"Und wer auch immer dich vor dem Gesetz verklagt, der wird von dem Gesetz verflucht werden."},{"verse":18,"text":"Und du sollst weder Beutel noch Tasche mitnehmen, auch keinen Stab und keine zwei Röcke, denn die Kirche wird dir zur selben Stunde geben, was du an Nahrung und an Kleidung und an Schuhen und an Geld und an Tasche brauchst."},{"verse":19,"text":"Denn du bist berufen, meinen Weingarten mit mächtigem Beschneiden zu beschneiden, ja, nämlich zum letzten Mal; ja, und das sind auch alle diejenigen, die du ordiniert hast, und sie sollen gemäß diesem Muster handeln. Amen."}]},{"chapter":25,"verses":[{"verse":1,"text":"Höre auf die Stimme des Herrn, deines Gottes, während ich zu dir, meine Tochter Emma Smith, spreche; denn wahrlich, ich sage dir: Alle jene, die mein Evangelium annehmen, sind Söhne und Töchter in meinem Reich."},{"verse":2,"text":"Eine Offenbarung gebe ich dir in Bezug auf meinen Willen; und wenn du treu bist und auf den Pfaden der Tugend vor mir wandelst, werde ich dein Leben bewahren, und du wirst ein Erbteil in Zion empfangen."},{"verse":3,"text":"Siehe, deine Sünden sind dir vergeben, und du bist eine auserwählte Frau, die ich berufen habe."},{"verse":4,"text":"Murre nicht wegen dem, was du nicht gesehen hast, denn es ist dir und auch der Welt vorenthalten, und das ist nach meiner Weisheit, für eine künftige Zeit."},{"verse":5,"text":"Und das Amt deiner Berufung besteht darin, dass du meinem Diener Joseph Smith Jr., deinem Mann, ein Trost in seinen Bedrängnissen sein sollst, mit lindernden Worten, im Geist der Sanftmut."},{"verse":6,"text":"Und du sollst mit ihm gehen zu der Zeit, da er geht, und sollst ihm eine Schreiberin sein, wenn kein Schreiber für ihn da ist, damit ich meinen Diener Oliver Cowdery senden kann, wohin auch immer ich will."},{"verse":7,"text":"Und du sollst unter seiner Hand ordiniert werden, Schriften zu erläutern und die Kirche zu ermahnen, gemäß dem, wie es dir durch meinen Geist eingegeben werden wird."},{"verse":8,"text":"Denn er wird dir seine Hände auflegen, und du wirst den Heiligen Geist empfangen, und deine Zeit soll darauf verwendet werden, zu schreiben und viel zu lernen."},{"verse":9,"text":"Und du brauchst dich nicht zu fürchten, denn dein Mann wird in der Kirche für dich sorgen; denn für sie ist seine Berufung, damit ihnen alles, was auch immer ich will, gemäß ihrem Glauben offenbart werden kann."},{"verse":10,"text":"Und wahrlich, ich sage dir: Du sollst die Dinge dieser Welt ablegen und nach den Dingen einer besseren trachten."},{"verse":11,"text":"Und es wird dir auch gegeben werden, eine Auswahl von heiligen Liedern zu treffen, wie es dir eingegeben werden wird, und es gefällt mir, dass sie in meiner Kirche vorhanden seien."},{"verse":12,"text":"Denn meine Seele erfreut sich am Lied des Herzens; ja, das Lied der Rechtschaffenen ist ein Gebet für mich, und es wird mit einer Segnung auf ihr Haupt beantwortet werden."},{"verse":13,"text":"Darum hebe dein Herz empor und freue dich, und halte an den Bündnissen fest, die du gemacht hast."},{"verse":14,"text":"Verbleibe im Geist der Sanftmut, und hüte dich vor Stolz. Lass deine Seele sich an deinem Mann erfreuen und an der Herrlichkeit, die auf ihn kommen wird."},{"verse":15,"text":"Halte beständig meine Gebote, und eine Krone der Rechtschaffenheit wirst du empfangen. Und wenn du das nicht tust, kannst du, wo ich bin, nicht hinkommen."},{"verse":16,"text":"Und wahrlich, wahrlich, ich sage dir: Dies ist meine Stimme an alle. Amen."}]},{"chapter":26,"verses":[{"verse":1,"text":"Siehe, ich sage euch: Widmet eure Zeit dem Studium der Schriften und dem Predigen und dem Konfirmieren der Gemeinde in Colesville und dem Verrichten eurer Arbeiten auf dem Land, wie es erforderlich ist, bis ihr dann nach dem Westen geht, um die nächste Konferenz abzuhalten; und dann wird es kundgetan werden, was ihr tun sollt."},{"verse":2,"text":"Und alles soll in der Kirche mit allgemeiner Zustimmung getan werden, durch viel Beten und Glauben, denn alles sollt ihr durch Glauben empfangen. Amen."}]},{"chapter":27,"verses":[{"verse":1,"text":"Hört auf die Stimme Jesu Christi, eures Herrn, eures Gottes und eures Erlösers, dessen Wort lebendig und machtvoll ist."},{"verse":2,"text":"Denn siehe, ich sage euch: Es kommt nicht darauf an, was ihr esst oder was ihr trinkt, wenn ihr vom Abendmahl nehmt, sofern ihr es so tut, dass euer Auge nur auf meine Herrlichkeit gerichtet ist, und ihr – vor dem Vater – meines Leibes gedenkt, der für euch niedergelegt wurde, sowie meines Blutes, das für die Vergebung eurer Sünden vergossen wurde."},{"verse":3,"text":"Darum gebe ich euch das Gebot, dass ihr von euren Feinden weder Wein noch starkes Getränk kaufen sollt;"},{"verse":4,"text":"darum sollt ihr von solchem nicht nehmen, außer er sei von euch neu bereitet, ja, in diesem meines Vaters Reich, das auf Erden aufgerichtet werden soll."},{"verse":5,"text":"Siehe, dies ist nach meiner Weisheit; darum wundert euch nicht, denn die Stunde kommt, da ich von der Frucht des Weinstocks mit euch auf Erden trinken werde, und mit Moroni, den ich dir gesandt habe, um das Buch Mormon zu offenbaren, das die Fülle meines immerwährenden Evangeliums enthält, und dem ich die Schlüssel des Berichts vom Holz Efraims übertragen habe;"},{"verse":6,"text":"und auch mit Elias, dem ich die Schlüssel übertragen habe, die Wiederherstellung all dessen zustande zu bringen, was durch den Mund aller heiligen Propheten von Anbeginn der Welt an in Bezug auf die letzten Tage gesprochen worden ist;"},{"verse":7,"text":"und auch Johannes, dem Sohn des Zacharias, welchen Zacharias er (Elias) besuchte und dem er die Verheißung gab, er werde einen Sohn bekommen, und dessen Name solle Johannes sein, und er werde vom Geist des Elias erfüllt sein;"},{"verse":8,"text":"diesen Johannes habe ich zu euch, meine Diener Joseph Smith Jr. und Oliver Cowdery, gesandt, dass er euch zum ersten Priestertum ordiniere, das ihr empfangen habt, damit ihr berufen und ordiniert seiet so wie Aaron;"},{"verse":9,"text":"und auch Elija, dem ich die Schlüssel der Macht übertragen habe, das Herz der Väter den Kindern zuzuwenden und das Herz der Kinder den Vätern, damit nicht die ganze Erde mit einem Fluch geschlagen werde;"},{"verse":10,"text":"und auch mit Josef und Jakob und Isaak und Abraham, euren Vätern, durch die die Verheißungen fortbestehen;"},{"verse":11,"text":"und auch mit Michael oder Adam, dem Vater aller, dem Fürsten aller, dem Alten der Tage;"},{"verse":12,"text":"und auch mit Petrus und Jakobus und Johannes, die ich zu euch gesandt habe, durch die ich euch ordiniert und euch bestätigt habe, Apostel und besondere Zeugen meines Namens zu sein und die Schlüssel eures geistlichen Dienstes und all dessen innezuhaben, was ich auch ihnen offenbarte,"},{"verse":13,"text":"und euch habe ich die Schlüssel meines Reiches und eine Evangeliumszeit für die letzte Zeit übertragen und für die Fülle der Zeiten, in der ich alles in eins zusammenbringen werde, sowohl, was im Himmel ist, als auch, was auf Erden ist;"},{"verse":14,"text":"und auch mit all denen, die mir mein Vater aus der Welt gegeben hat."},{"verse":15,"text":"Darum hebt euer Herz empor und freut euch, und gürtet euch die Lenden, und legt meine ganze Waffenrüstung an, damit ihr dem bösen Tag widerstehen könnt und, nachdem ihr alles getan habt, damit ihr imstande seid zu bestehen."},{"verse":16,"text":"Darum steht, eure Lenden umgürtet mit Wahrheit, angetan mit dem Brustschild der Rechtschaffenheit und eure Füße beschuht mit der Vorbereitung des Evangeliums des Friedens, das euch zu überbringen ich meine Engel gesandt habe;"},{"verse":17,"text":"und ergreift den Schild des Glaubens, mit dem ihr fähig seid, alle feurigen Pfeile der Schlechten auszulöschen,"},{"verse":18,"text":"und nehmt den Helm der Errettung und das Schwert meines Geistes, den ich über euch ausgießen werde, und mein Wort, das ich euch offenbare; seid euch, jede Sache betreffend, einig, was auch immer ihr von mir erbittet, und seid treu, bis ich komme; dann werdet ihr entrückt werden, damit, wo ich bin, auch ihr sein werdet. Amen."}]},{"chapter":28,"verses":[{"verse":1,"text":"Siehe, ich sage dir, Oliver: Dir wird es gegeben sein, von der Kirche in allem gehört zu werden, was auch immer du sie in Bezug auf die Offenbarungen und Gebote, die ich gegeben habe, durch den Tröster lehren wirst."},{"verse":2,"text":"Aber siehe, wahrlich, wahrlich, ich sage dir: Niemand wird bestimmt werden, Gebote und Offenbarungen in dieser Kirche zu empfangen, ausgenommen mein Diener Joseph Smith Jr., denn er empfängt sie gleichwie Mose."},{"verse":3,"text":"Und du sollst das, was ich ihm gebe, befolgen, ja, gleichwie Aaron, und der Kirche getreulich die Gebote und die Offenbarungen mit Macht und Vollmacht verkünden."},{"verse":4,"text":"Und wann immer du durch den Tröster veranlasst wirst, zur Kirche zu sprechen oder sie zu lehren, oder immer aufgrund eines Gebots, magst du solches tun."},{"verse":5,"text":"Aber du sollst nicht nach Art eines Gebotes schreiben, sondern mit Hilfe von Weisheit;"},{"verse":6,"text":"und du sollst nicht ihm gebieten, der dir als Haupt gesetzt ist und als Haupt über die Kirche;"},{"verse":7,"text":"denn ich habe ihm die Schlüssel der Geheimnisse und der Offenbarungen, die versiegelt sind, gegeben, bis ich ihnen einen anderen an seiner Stelle bestimmen werde."},{"verse":8,"text":"Und nun siehe, ich sage dir: Du sollst zu den Lamaniten gehen und ihnen mein Evangelium predigen; und insoweit sie deine Belehrungen annehmen, sollst du unter ihnen meine Kirche aufrichten lassen; und du sollst Offenbarungen haben, aber schreibe sie nicht nach Art eines Gebotes nieder."},{"verse":9,"text":"Und nun siehe, ich sage dir: Es ist nicht offenbart, und kein Mensch weiß, wo die Stadt Zion erbaut werden wird, sondern es wird später noch gegeben werden. Siehe, ich sage dir: Es wird an der Grenze bei den Lamaniten sein."},{"verse":10,"text":"Du sollst diesen Ort erst nach der Konferenz verlassen, und mein Diener Joseph soll durch die Stimme der Konferenz bestimmt werden, darüber zu präsidieren, und was er dir sagt, das sollst du reden."},{"verse":11,"text":"Und weiter sollst du dir deinen Bruder Hiram Page nehmen, zwischen ihm und dir allein, und ihm sagen, dass all jenes, was er von jenem Stein geschrieben hat, nicht von mir ist und dass der Satan ihn täuscht;"},{"verse":12,"text":"denn siehe, dies alles ist nicht ihm bestimmt, auch wird niemandem in dieser Kirche irgendetwas im Gegensatz zu den Bündnissen der Kirche bestimmt werden."},{"verse":13,"text":"Denn alles muss in Ordnung geschehen und durch allgemeine Zustimmung in der Kirche, durch das Gebet des Glaubens."},{"verse":14,"text":"Und du sollst behilflich sein, dies alles gemäß den Bündnissen der Kirche zu bereinigen, ehe du deine Reise zu den Lamaniten antrittst."},{"verse":15,"text":"Und es wird dir von der Zeit an, da du aufbrichst, bis zu der Zeit, da du zurückkehrst, eingegeben werden, was du tun sollst."},{"verse":16,"text":"Und du musst allezeit deinen Mund auftun und mein Evangelium mit dem Ton der Freude verkünden. Amen."}]},{"chapter":29,"verses":[{"verse":1,"text":"Hört auf die Stimme Jesu Christi, eures Erlösers, des Großen Ich Bin, dessen Arm der Barmherzigkeit für eure Sünden gesühnt hat,"},{"verse":2,"text":"der sein Volk sammeln wird, so wie eine Henne ihre Küken unter ihre Flügel sammelt, ja, alle, die auf meine Stimme hören und sich vor mir demütigen und mich in mächtigem Gebet anrufen."},{"verse":3,"text":"Siehe, wahrlich, wahrlich, ich sage euch: Zu dieser Zeit sind euch eure Sünden vergeben, darum empfangt ihr dieses hier; aber denkt daran, dass ihr nicht mehr sündigt, damit nicht Gefahren über euch kommen."},{"verse":4,"text":"Wahrlich, ich sage euch: Ihr seid aus der Welt erwählt, um mein Evangelium mit dem Ton der Freude zu verkünden wie mit der Stimme einer Posaune."},{"verse":5,"text":"Hebt euer Herz empor und seid froh, denn ich bin mitten unter euch und bin euer Fürsprecher beim Vater; und es ist sein guter Wille, euch das Reich zu geben."},{"verse":6,"text":"Und, wie es geschrieben steht: Was auch immer ihr im Glauben erbittet, einig im Gebet gemäß meinem Gebot, das werdet ihr empfangen."},{"verse":7,"text":"Und ihr seid berufen, die Sammlung meiner Auserwählten zuwege zu bringen; denn meine Auserwählten vernehmen meine Stimme und verhärten nicht ihr Herz;"},{"verse":8,"text":"darum ist der Beschluss vom Vater hinausgegangen, dass sie an einem Ort in diesem Land gesammelt werden sollen, um in allem ihr Herz vorzubereiten und für den Tag bereit zu sein, da Drangsal und Verwüstung über die Schlechten gesandt werden."},{"verse":9,"text":"Denn die Stunde ist nahe, und der Tag steht bald bevor, da die Erde reif ist, und alle Stolzen und jene, die Schlechtes tun, werden wie Stoppeln sein, und ich werde sie verbrennen, spricht der Herr der Heerscharen, sodass es keine Schlechtigkeit auf Erden geben wird;"},{"verse":10,"text":"denn die Stunde ist nahe, und das, was von meinen Aposteln gesprochen worden ist, muss sich erfüllen; denn wie sie gesprochen haben, so wird es sich begeben;"},{"verse":11,"text":"denn ich werde mich vom Himmel her mit Macht und großer Herrlichkeit mit all seinen Scharen offenbaren und in Rechtschaffenheit eintausend Jahre bei den Menschen auf Erden wohnen, und die Schlechten werden nicht bestehen."},{"verse":12,"text":"Und weiter, wahrlich, wahrlich, ich sage euch, und es ist als fester Beschluss hinausgegangen, durch den Willen des Vaters, dass meine Apostel, die Zwölf, die in meinem geistlichen Wirken zu Jerusalem bei mir waren, zu meiner rechten Hand stehen werden am Tag meines Kommens in einer Feuersäule, angetan mit dem Gewand der Rechtschaffenheit, mit einer Krone auf ihrem Haupt, in Herrlichkeit gleichwie ich bin, um das ganze Haus Israel zu richten, nämlich alle, die mich geliebt und meine Gebote gehalten haben, und sonst niemand."},{"verse":13,"text":"Denn eine Posaune wird ertönen, lang und auch laut, ja, wie auf dem Berg Sinai, und die ganze Erde wird beben, und sie werden hervorkommen – ja, nämlich die Toten, die in mir gestorben sind, auf dass sie eine Krone der Rechtschaffenheit empfangen und bekleidet werden, gleichwie ich bin, auf dass sie bei mir seien, damit wir eins sein können."},{"verse":14,"text":"Aber siehe, ich sage euch: Ehe dieser große Tag kommt, wird sich die Sonne verfinstern, und der Mond wird sich in Blut verwandeln, und die Sterne werden vom Himmel fallen, und es wird noch größere Zeichen geben, oben im Himmel und unten auf der Erde;"},{"verse":15,"text":"und es wird Weinen und Wehklagen unter den Scharen der Menschen geben;"},{"verse":16,"text":"und es wird ein großer Hagelsturm gesandt werden, die Ernten der Erde zu vernichten."},{"verse":17,"text":"Und es wird sich begeben: Wegen der Schlechtigkeit der Welt werde ich Vergeltung üben an den Schlechten, denn sie wollen nicht umkehren; denn der Becher meines Unwillens ist voll; denn siehe, mein Blut wird sie nicht säubern, wenn sie nicht auf mich hören."},{"verse":18,"text":"Darum werde ich, Gott, der Herr, Fliegen auf den Erdboden aussenden, die werden dessen Bewohner befallen und werden ihr Fleisch fressen und werden Maden über sie kommen lassen;"},{"verse":19,"text":"und ihrer Zunge wird Einhalt geboten werden, sodass sie nicht gegen mich reden werden; und ihr Fleisch wird ihnen von den Knochen fallen und ihre Augen aus den Höhlen;"},{"verse":20,"text":"und es wird sich begeben: Die wilden Tiere des Waldes und die Vögel der Luft werden sie auffressen."},{"verse":21,"text":"Und die große und gräuelreiche Kirche, welche die Hure der ganzen Erde ist, wird durch verzehrendes Feuer niedergeworfen werden, gemäß dem, was durch den Mund des Propheten Ezechiel gesprochen worden ist, der von dem allen gesprochen hat, was sich noch nicht begeben hat, aber gewiss muss, so wahr ich lebe, denn Gräuel dürfen nicht regieren."},{"verse":22,"text":"Und weiter, wahrlich, wahrlich, ich sage euch: Wenn die tausend Jahre zu Ende sind und die Menschen wieder anfangen, ihren Gott zu leugnen, dann werde ich die Erde nur eine kurze Zeit lang verschonen,"},{"verse":23,"text":"und das Ende wird kommen, und der Himmel und die Erde werden verzehrt werden und vergehen, und es wird einen neuen Himmel und eine neue Erde geben."},{"verse":24,"text":"Denn alles Alte wird vergehen, und alles wird neu werden, ja, der Himmel und die Erde und deren ganze Fülle, sowohl Mensch wie Tier, die Vögel der Luft und die Fische des Meeres;"},{"verse":25,"text":"und nicht ein Haar noch Stäubchen wird verlorengehen, denn es ist das Werk meiner Hand."},{"verse":26,"text":"Aber siehe, wahrlich, ich sage euch: Ehe die Erde vergeht, wird Michael, mein Erzengel, seine Posaune ertönen lassen, und dann werden alle Toten erwachen, denn ihre Gräber werden sich öffnen, und sie werden hervorkommen – ja, selbst alle."},{"verse":27,"text":"Und die Rechtschaffenen werden zu meiner rechten Hand zu ewigem Leben gesammelt werden; und der Schlechten zu meiner linken Hand werde ich mich schämen, sie vor dem Vater als mein Eigen anzuerkennen,"},{"verse":28,"text":"darum werde ich zu ihnen sagen: Hinweg von mir, ihr Verfluchten, in das immerwährende Feuer, das für den Teufel und seine Engel bereitet ist."},{"verse":29,"text":"Und nun siehe, ich sage euch: Niemals, zu keiner Zeit, habe ich mit meinem eigenen Mund verkündet, dass sie wiederkehren sollen, denn wo ich bin, können sie nicht hinkommen, denn sie haben keine Macht."},{"verse":30,"text":"Aber denkt daran, dass nicht alle meine Richtersprüche den Menschen gegeben werden; und wie die Worte aus meinem Mund hervorgegangen sind, ja, so werden sie sich erfüllen, dass die Ersten die Letzten sein werden und dass die Letzten die Ersten sein werden in allem, was auch immer ich durch das Wort meiner Macht, nämlich die Macht meines Geistes, erschaffen habe."},{"verse":31,"text":"Denn durch die Macht meines Geistes habe ich es erschaffen; ja, alles, Geistiges und auch Zeitliches –"},{"verse":32,"text":"erst Geistiges, dann Zeitliches, und das ist der Anfang meines Werkes; und wiederum erst Zeitliches und dann Geistiges, und das ist das Letzte meines Werkes –,"},{"verse":33,"text":"ich rede so zu euch, damit ihr es natürlich verstehen könnt; für mich selbst aber haben meine Werke weder Ende noch Anfang; euch aber ist es gegeben, damit ihr es verstehen könnt, denn ihr habt mich darum gefragt und seid einig."},{"verse":34,"text":"Darum, wahrlich, ich sage euch: Für mich ist alles geistig, und zu keiner Zeit habe ich euch ein Gesetz gegeben, das zeitlich ist, weder irgendeinem Menschen noch den Menschenkindern, auch nicht Adam, eurem Vater, den ich erschaffen habe."},{"verse":35,"text":"Siehe, ich habe ihm gewährt, für sich selbst zu handeln, und ich habe ihm Gebot gegeben, aber zeitliches Gebot habe ich ihm keines gegeben, denn meine Gebote sind geistig; sie sind nicht natürlich noch zeitlich, weder fleischlich noch sinnlich."},{"verse":36,"text":"Und es begab sich: Adam, vom Teufel versucht – denn siehe, der Teufel war eher als Adam, denn er lehnte sich gegen mich auf und sprach: Gib mir deine Ehre, und das ist meine Macht; und auch den dritten Teil der Scharen des Himmels wendete er wegen ihrer Entscheidungsfreiheit von mir ab;"},{"verse":37,"text":"und sie wurden hinabgeworfen, und so entstanden der Teufel und seine Engel;"},{"verse":38,"text":"und siehe, es gibt einen Ort für sie, bereitet von Anfang an, und dieser Ort ist die Hölle."},{"verse":39,"text":"Und es muss notwendigerweise so sein, dass der Teufel die Menschenkinder versucht, sonst könnten sie nicht für sich selbst handeln; denn wenn sie nie das Bittere hätten, könnten sie das Süße nicht kennen –"},{"verse":40,"text":"darum begab es sich: Der Teufel versuchte Adam, und dieser aß von der verbotenen Frucht und übertrat das Gebot, wodurch er dem Willen des Teufels untertan wurde, weil er der Versuchung nachgab."},{"verse":41,"text":"Darum ließ ich, Gott, der Herr, ihn aus dem Garten von Eden, aus meiner Gegenwart, wegen seiner Übertretung ausstoßen, und dadurch wurde er geistig tot, und das ist der erste Tod, nämlich derselbe Tod, der der letzte Tod ist, der geistig ist, der über die Schlechten ausgesprochen werden wird, wenn ich sagen werde: Hinweg, ihr Verfluchten."},{"verse":42,"text":"Aber siehe, ich sage euch: Ich, Gott, der Herr, gewährte Adam und seinen Nachkommen, nicht eher zu sterben, was den zeitlichen Tod betrifft, als bis ich, Gott, der Herr, Engel aussenden würde, die ihnen Umkehr und Erlösung durch Glauben an den Namen meines einziggezeugten Sohnes verkünden sollten."},{"verse":43,"text":"Und so bestimmte ich, Gott, der Herr, dem Menschen die Tage seiner Bewährung – dass er durch seinen natürlichen Tod in Unsterblichkeit zu ewigem Leben erhoben werden könne, ja alle, die glauben wollen;"},{"verse":44,"text":"und die nicht glauben, zu ewiger Verdammnis; denn sie können von ihrem geistigen Fall nicht erlöst werden, weil sie nicht umkehren;"},{"verse":45,"text":"denn sie lieben die Finsternis mehr als das Licht, und ihre Taten sind böse, und sie empfangen ihren Lohn von demjenigen, dem zu gehorchen ihnen gefällt."},{"verse":46,"text":"Aber siehe, ich sage euch: Kleine Kinder sind von der Grundlegung der Welt an durch meinen Einziggezeugten erlöst;"},{"verse":47,"text":"darum können sie nicht sündigen, denn dem Satan ist nicht die Macht gegeben, kleine Kinder zu versuchen, ehe sie anfangen, vor mir verantwortlich zu werden;"},{"verse":48,"text":"denn es wird ihnen gegeben, ja, wie ich es will, gemäß meinem eigenen Wohlgefallen, damit Großes von der Hand ihrer Väter gefordert werden kann."},{"verse":49,"text":"Und weiter, ich sage euch: Wem, der Erkenntnis hat, habe ich nicht geboten umzukehren?"},{"verse":50,"text":"Und dem, der kein Verständnis hat, es bleibt mir überlassen, gemäß dem zu tun, was geschrieben steht. Und nun verkünde ich euch zu dieser Zeit nichts mehr. Amen."}]},{"chapter":30,"verses":[{"verse":1,"text":"Siehe, ich sage dir, David: Du hast die Menschen gefürchtet und hast dich nicht, was Kraft betrifft, auf mich verlassen, wie du hättest sollen."},{"verse":2,"text":"Sondern dein Sinn war mehr auf die Dinge der Erde gerichtet als auf das, was von mir, deinem Schöpfer, ist, und auf den geistlichen Dienst, zu dem du berufen worden bist; und du hast meinem Geist und denen, die über dich gesetzt sind, keine Beachtung geschenkt, sondern bist von denen dazu bewogen worden, denen ich nicht geboten habe."},{"verse":3,"text":"Darum ist es an dir, für dich selbst von meiner Hand zu erfragen und über das nachzudenken, was du empfangen hast."},{"verse":4,"text":"Und dein Heim soll im Haus deines Vaters sein, bis ich dir weitere Gebote gebe. Und du sollst dich dem geistlichen Dienst widmen, in der Kirche und vor der Welt und in den Gebieten ringsum. Amen."},{"verse":5,"text":"Siehe, ich sage dir, Peter: Du sollst mit deinem Bruder Oliver die Reise antreten; denn die Zeit ist gekommen, da es mir ratsam ist, dass du deinen Mund auftust, um mein Evangelium zu verkünden; darum fürchte dich nicht, sondern schenke den Worten und Ratschlägen deines Bruders, die er dir geben wird, Beachtung."},{"verse":6,"text":"Und sei du bedrängt in all seinen Bedrängnissen, und hebe immerzu dein Herz zu mir empor, in Gebet und Glauben, damit er und du befreit werdet, denn ich habe ihm die Macht gegeben, meine Kirche unter den Lamaniten zu errichten;"},{"verse":7,"text":"und niemanden habe ich dazu bestimmt, Ratgeber über ihn in der Kirche zu sein in Bezug auf Angelegenheiten der Kirche, außer seinen Bruder Joseph Smith Jr."},{"verse":8,"text":"Darum schenke all diesem Beachtung, und sei eifrig im Halten meiner Gebote, dann wirst du zu ewigem Leben gesegnet werden. Amen."},{"verse":9,"text":"Siehe, ich sage dir, mein Diener John: Du sollst von dieser Zeit an beginnen, mein Evangelium wie mit der Stimme einer Posaune zu verkündigen."},{"verse":10,"text":"Und deine Arbeit soll bei deinem Bruder Philip Burroughs und in jenem Gebiet ringsum geschehen, ja, wo immer du gehört werden kannst, bis ich dir gebiete, von da fortzugehen."},{"verse":11,"text":"Und deine gesamte Arbeit soll von nun an in Zion sein, mit deiner ganzen Seele; ja, du sollst jederzeit deinen Mund auftun in meiner Sache und nicht fürchten, was Menschen tun können, denn ich bin mit dir. Amen."}]},{"chapter":31,"verses":[{"verse":1,"text":"Thomas, mein Sohn, gesegnet bist du, weil du an mein Werk glaubst."},{"verse":2,"text":"Siehe, deiner Familie wegen hast du viele Bedrängnisse gehabt, doch ich werde dich und deine Familie, ja, deine Kleinen, segnen; und der Tag kommt, da sie glauben und die Wahrheit erkennen und mit dir in meiner Kirche eins sein werden."},{"verse":3,"text":"Hebe dein Herz empor und freue dich, denn die Stunde deiner Mission ist gekommen; und deine Zunge wird gelöst werden, und du sollst dieser Generation frohe Nachricht von großer Freude verkünden."},{"verse":4,"text":"Du sollst das alles verkünden, was meinem Diener Joseph Smith Jr. offenbart worden ist. Du sollst anfangen, von dieser Zeit an zu predigen, ja, zu ernten auf dem Feld, das schon weiß ist, zum Verbrennen bereit."},{"verse":5,"text":"Darum schlage mit deiner ganzen Seele deine Sichel ein, und deine Sünden sind dir vergeben, und du wirst mit Garben auf deinem Rücken beladen werden, denn der Arbeiter ist seines Lohnes wert. Darum wird deine Familie leben."},{"verse":6,"text":"Siehe, wahrlich, ich sage dir: Geh nur für eine kurze Zeit von ihnen fort und verkünde mein Wort, und ich werde einen Ort für sie bereiten."},{"verse":7,"text":"Ja, ich werde den Menschen das Herz öffnen, und sie werden dich empfangen. Und ich werde durch deine Hand eine Gemeinde aufrichten,"},{"verse":8,"text":"und du sollst sie stärken und sie für die Zeit bereitmachen, da sie gesammelt werden sollen."},{"verse":9,"text":"Sei geduldig in Bedrängnissen, schmähe nicht diejenigen, die schmähen. Regiere dein Haus mit Sanftmut, und sei standhaft."},{"verse":10,"text":"Siehe, ich sage dir: Du wirst für die Kirche ein Arzt sein, aber nicht für die Welt, denn sie werden dich nicht empfangen."},{"verse":11,"text":"Geh deines Weges, wohin auch immer ich will, und es wird dir vom Tröster eingegeben werden, was du tun sollst und wohin du gehen sollst."},{"verse":12,"text":"Bete immer, damit du nicht in Versuchung gerätst und deines Lohnes verlustig gehst."},{"verse":13,"text":"Sei treu bis ans Ende, und sieh, ich bin mit dir. Diese Worte sind nicht von einem Menschen, auch nicht von den Menschen, sondern von mir, nämlich Jesus Christus, deinem Erlöser, durch den Willen des Vaters. Amen."}]},{"chapter":32,"verses":[{"verse":1,"text":"Und nun zu meinem Diener Parley P. Pratt. Siehe, ich sage ihm: So wahr ich lebe, will ich, dass er mein Evangelium verkünden und von mir lernen und sanftmütig und von Herzen demütig sein soll."},{"verse":2,"text":"Und das, was ich ihm bestimmt habe, ist, dass er mit meinen Dienern Oliver Cowdery und Peter Whitmer Jr. in die Wildnis unter die Lamaniten gehen soll."},{"verse":3,"text":"Und Ziba Peterson soll auch mit ihnen gehen; und ich selbst werde mit ihnen gehen und mitten unter ihnen sein; und ich bin ihr Fürsprecher beim Vater, und nichts wird sie überwältigen."},{"verse":4,"text":"Und sie sollen dem Beachtung schenken, was geschrieben steht, und nicht auf andere Offenbarung Anspruch erheben; und sie sollen immer beten, dass ich dasselbe ihrem Verständnis entfalten kann."},{"verse":5,"text":"Und sie sollen diesen Worten Beachtung schenken und nicht leichtfertig damit umgehen, dann werde ich sie segnen. Amen."}]},{"chapter":33,"verses":[{"verse":1,"text":"Siehe, ich sage euch, meine Diener Ezra und Northrop: Öffnet eure Ohren und hört auf die Stimme des Herrn, eures Gottes, dessen Wort lebendig und machtvoll ist, schärfer als ein zweischneidiges Schwert, sodass es Gelenke und Mark, Seele und Geist scheidet und die Gedanken und Absichten des Herzens zu erkennen weiß."},{"verse":2,"text":"Denn wahrlich, wahrlich, ich sage euch: Ihr seid berufen, eure Stimme zu erheben wie mit dem Ton einer Posaune, um mein Evangelium einer verdrehten und frevelhaften Generation zu verkünden."},{"verse":3,"text":"Denn siehe, das Feld ist schon weiß, zur Ernte bereit; und es ist die elfte Stunde und das letzte Mal, dass ich Arbeiter in meinen Weingarten berufe."},{"verse":4,"text":"Und mein Weingarten ist bis ins Kleinste verdorben; und es gibt niemanden, der Gutes tut, außer einigen wenigen; und sie irren sich in vielen Fällen aufgrund von Priesterlist, denn alle haben einen verdorbenen Sinn."},{"verse":5,"text":"Und wahrlich, wahrlich, ich sage euch: Diese Kirche habe ich aufgerichtet und aus der Wildnis hervorgerufen."},{"verse":6,"text":"Und ebenso werde ich meine Auserwählten von den vier Enden der Erde sammeln, ja, alle, die an mich glauben und auf meine Stimme hören."},{"verse":7,"text":"Ja, wahrlich, wahrlich, ich sage euch: Das Feld ist schon weiß, zur Ernte bereit; darum schlagt eure Sicheln ein und erntet mit all eurer Macht, ganzem Sinn und aller Kraft."},{"verse":8,"text":"Tut euren Mund auf, und er wird gefüllt werden, und ihr sollt werden gleichwie Nephi vor alters, der von Jerusalem in die Wildnis zog."},{"verse":9,"text":"Ja, tut euren Mund auf und haltet nicht zurück, und ihr werdet mit Garben auf eurem Rücken beladen werden, denn seht, ich bin mit euch."},{"verse":10,"text":"Ja, tut euren Mund auf, und er wird gefüllt werden, und sprecht: Kehrt um, kehrt um, und bereitet den Weg des Herrn, und macht seine Pfade gerade, denn das Himmelreich ist nahe;"},{"verse":11,"text":"ja, kehrt um und lasst euch taufen, ein jeglicher von euch, zur Vergebung eurer Sünden; ja, lasst euch taufen, nämlich mit Wasser, und dann kommt die Taufe mit Feuer und mit dem Heiligen Geist."},{"verse":12,"text":"Siehe, wahrlich, wahrlich, ich sage euch: Das ist mein Evangelium; und denkt daran, dass sie Glauben an mich haben müssen, sonst können sie keineswegs errettet werden;"},{"verse":13,"text":"und auf diesem Felsen werde ich meine Kirche bauen; ja, auf diesem Felsen seid ihr gebaut, und wenn ihr verbleibt, werden die Pforten der Hölle euch nicht überwältigen."},{"verse":14,"text":"Und ihr sollt euch der Satzungen und Bündnisse der Kirche erinnern und sie befolgen."},{"verse":15,"text":"Und wer Glauben hat, den sollt ihr in meiner Kirche durch das Auflegen der Hände konfirmieren, und ich werde solchen die Gabe des Heiligen Geistes zuteilwerden lassen."},{"verse":16,"text":"Und das Buch Mormon und die heiligen Schriften sind von mir zu eurer Belehrung gegeben; und die Macht meines Geistes belebt alles."},{"verse":17,"text":"Darum seid treu, betet immer und habt eure Lampen bereitet und brennend und Öl bei euch, damit ihr bereit seid, wenn der Bräutigam kommt –"},{"verse":18,"text":"denn siehe, wahrlich, wahrlich, ich sage euch: Ich komme schnell. So ist es. Amen."}]},{"chapter":34,"verses":[{"verse":1,"text":"Mein Sohn Orson, horche auf und vernimm und sieh, was ich, Gott, der Herr, dir sagen werde, ja, Jesus Christus, dein Erlöser;"},{"verse":2,"text":"das Licht und das Leben der Welt, ein Licht, das in der Finsternis leuchtet, und die Finsternis erfasst es nicht;"},{"verse":3,"text":"der die Welt so sehr geliebt hat, dass er sein eigenes Leben hingegeben hat, damit alle, die da glauben, Söhne Gottes werden können. Darum bist du mein Sohn;"},{"verse":4,"text":"und gesegnet bist du, weil du geglaubt hast;"},{"verse":5,"text":"und noch mehr gesegnet bist du, weil du von mir berufen bist, mein Evangelium zu predigen –"},{"verse":6,"text":"deine Stimme zu erheben wie mit dem Ton einer Posaune, lang und auch laut, und eine verdrehte und frevelhafte Generation zur Umkehr zu rufen, um dem Herrn den Weg für sein zweites Kommen zu bereiten."},{"verse":7,"text":"Denn siehe, wahrlich, wahrlich, ich sage dir: Die Zeit steht bald bevor, da ich in einer Wolke kommen werde mit Macht und großer Herrlichkeit."},{"verse":8,"text":"Und es wird ein großer Tag sein zu der Zeit meines Kommens, denn alle Nationen werden zittern."},{"verse":9,"text":"Aber ehe jener große Tag kommt, wird die Sonne sich verfinstern und der Mond sich in Blut verwandeln; und die Sterne werden sich weigern zu leuchten, und einige werden fallen, und große Zerschlagungen erwarten die Schlechten."},{"verse":10,"text":"Darum erhebe deine Stimme und halte nicht zurück, denn Gott, der Herr, hat gesprochen; darum prophezeie, und es wird durch die Macht des Heiligen Geistes gegeben werden."},{"verse":11,"text":"Und wenn du treu bist, siehe, so bin ich mit dir, bis ich komme –"},{"verse":12,"text":"und wahrlich, wahrlich, ich sage dir: Ich komme schnell. Ich bin dein Herr und dein Erlöser. So ist es. Amen."}]},{"chapter":35,"verses":[{"verse":1,"text":"Hört auf die Stimme des Herrn, eures Gottes, nämlich Alpha und Omega, der Anfang und das Ende, dessen Bahn eine ewige Runde ist, derselbe heute wie gestern und immerdar."},{"verse":2,"text":"Ich bin Jesus Christus, der Sohn Gottes, der für die Sünden der Welt gekreuzigt worden ist, ja, all derer, die an meinen Namen glauben, damit sie Söhne Gottes werden können, ja, eins in mir, wie ich eins bin im Vater, wie der Vater eins ist in mir, damit wir eins seien."},{"verse":3,"text":"Siehe, wahrlich, wahrlich, ich sage meinem Diener Sidney: Ich habe dich und deine Werke angesehen. Ich habe deine Gebete vernommen und dich für ein größeres Werk vorbereitet."},{"verse":4,"text":"Du bist gesegnet, denn du sollst Großes tun. Siehe, du warst ausgesandt, nämlich wie Johannes, um den Weg vor mir zu bereiten und vor Elija, der kommen soll, und du hast es nicht gewusst."},{"verse":5,"text":"Du hast mit Wasser getauft, zur Umkehr, aber sie haben den Heiligen Geist nicht empfangen;"},{"verse":6,"text":"nun aber gebe ich dir das Gebot, dass du mit Wasser taufen sollst, und sie sollen den Heiligen Geist durch das Händeauflegen empfangen so wie bei den Aposteln vor alters."},{"verse":7,"text":"Und es wird sich begeben: Es wird ein großes Werk in dem Land geben, nämlich unter den Anderen, denn ihre Torheit und ihre Gräuel werden vor den Augen allen Volkes kundgetan werden."},{"verse":8,"text":"Denn ich bin Gott, und mein Arm hat sich nicht verkürzt; und ich werde Wundertaten, Zeichen und Wunder all denen zeigen, die an meinen Namen glauben."},{"verse":9,"text":"Und die es in meinem Namen voller Glauben bitten, die werden Teufel austreiben; sie werden die Kranken heilen; sie werden bewirken, dass die Blinden ihr Augenlicht empfangen und die Tauben hören und die Stummen reden und die Lahmen gehen."},{"verse":10,"text":"Und die Zeit kommt schnell, da Großes den Menschenkindern gezeigt werden wird;"},{"verse":11,"text":"aber ohne Glauben wird nichts gezeigt werden außer Verwüstungen über Babylon, nämlich jenes, das alle Nationen dazu gebracht hat, vom Wein des Zornes seiner Unzucht zu trinken."},{"verse":12,"text":"Und es gibt niemanden, der Gutes tut, außer diejenigen, die bereit sind, die Fülle meines Evangeliums zu empfangen, die ich an diese Generation ausgesandt habe."},{"verse":13,"text":"Darum rufe ich das Schwache der Welt auf, jene, die ungelehrt und verachtet sind, dass sie die Nationen mit der Macht meines Geistes dreschen;"},{"verse":14,"text":"und ihr Arm wird mein Arm sein, und ich werde ihr Schild und ihr Schutz sein; und ich werde ihnen die Lenden gürten, und sie werden mannhaft für mich kämpfen; und ihre Feinde werden unter ihren Füßen sein; und ich werde das Schwert niederfallen lassen um ihretwillen, und mit dem Feuer meines Unwillens werde ich sie bewahren."},{"verse":15,"text":"Und den Armen und den Sanftmütigen wird das Evangelium gepredigt werden, und sie werden nach der Zeit meines Kommens ausschauen, denn sie steht nahe bevor –"},{"verse":16,"text":"und sie werden das Gleichnis vom Feigenbaum erfahren, denn eben jetzt ist der Sommer schon nahe."},{"verse":17,"text":"Und ich habe die Fülle meines Evangeliums durch die Hand meines Dieners Joseph ausgesandt; und in Schwachheit habe ich ihn gesegnet;"},{"verse":18,"text":"und ich habe ihm die Schlüssel zu den Geheimnissen dessen gegeben, was versiegelt worden ist, nämlich das, was von der Grundlegung der Welt an gewesen ist, und das, was von jetzt an bis zur Zeit meines Kommens geschehen wird, sofern er in mir verbleibt; und wenn nicht, einen anderen werde ich an seine Stelle setzen."},{"verse":19,"text":"Darum wache über ihn, dass sein Glaube nicht versage, und es wird durch den Tröster gegeben werden, den Heiligen Geist, der alles weiß."},{"verse":20,"text":"Und ein Gebot gebe ich dir – dass du für ihn schreiben sollst; und die Schriften werden so gegeben werden, wie sie in meinem eigenen Herzen sind, zur Errettung meiner eigenen Auserwählten;"},{"verse":21,"text":"denn sie werden meine Stimme vernehmen und werden mich sehen und werden nicht eingeschlafen sein und werden den Tag meines Kommens aushalten, denn sie werden rein gemacht werden, ja, wie ich rein bin."},{"verse":22,"text":"Und jetzt sage ich dir: Bleibe bei ihm, und er soll mit dir reisen; verlass ihn nicht, dann wird sich dies gewiss erfüllen."},{"verse":23,"text":"Und insoweit ihr nicht schreibt, siehe, wird es ihm gegeben sein zu prophezeien; und du sollst mein Evangelium predigen und dich auf die heiligen Propheten berufen, um seine Worte zu beweisen, wie sie ihm gegeben werden."},{"verse":24,"text":"Haltet alle Gebote und Bündnisse, durch die ihr gebunden seid; und ich werde die Himmel zu eurem Guten erbeben lassen, und der Satan wird zittern, und Zion wird sich auf den Hügeln freuen und erblühen;"},{"verse":25,"text":"und Israel wird zu der von mir selbst bestimmten Zeit errettet werden; und durch die Schlüssel, die ich gegeben habe, wird es geleitet und keineswegs mehr zuschanden werden."},{"verse":26,"text":"Hebt euer Herz empor und seid froh, eure Erlösung naht sich."},{"verse":27,"text":"Fürchtet euch nicht, kleine Herde, das Reich ist euer, bis ich komme. Siehe, ich komme schnell. So ist es. Amen."}]},{"chapter":36,"verses":[{"verse":1,"text":"So spricht Gott, der Herr, der Mächtige Israels: Siehe, ich sage dir, mein Diener Edward: Du bist gesegnet, und deine Sünden sind dir vergeben, und du bist berufen, mein Evangelium wie mit der Stimme einer Posaune zu predigen;"},{"verse":2,"text":"und ich werde dir meine Hand auflegen durch die Hand meines Dieners Sidney Rigdon, und du wirst meinen Geist empfangen, den Heiligen Geist, nämlich den Tröster, der dich das Friedfertige des Reiches lehren wird;"},{"verse":3,"text":"und du sollst es mit lauter Stimme verkünden, nämlich: Hosanna, gesegnet sei der Name des allerhöchsten Gottes."},{"verse":4,"text":"Und nun, diese Berufung und dieses Gebot gebe ich dir hinsichtlich aller Menschen –"},{"verse":5,"text":"dass alle, die zu meinen Dienern Sidney Rigdon und Joseph Smith Jr. kommen und diese Berufung und dieses Gebot annehmen, ordiniert und ausgesandt werden sollen, unter den Nationen das immerwährende Evangelium zu predigen –"},{"verse":6,"text":"und zur Umkehr zu rufen, nämlich: Errettet euch aus dieser verkehrten Generation, und kommt heraus aus dem Feuer, und hasst sogar das Gewand, das befleckt ist vom Fleische."},{"verse":7,"text":"Und dieses Gebot soll den Ältesten meiner Kirche gegeben werden, damit jeder Mann, der es mit Lauterkeit des Herzens annimmt, ordiniert und ausgesandt werden kann, so wie ich es gesagt habe."},{"verse":8,"text":"Ich bin Jesus Christus, der Sohn Gottes; darum gürtet euch die Lenden, und ich werde plötzlich zu meinem Tempel kommen. So ist es. Amen."}]},{"chapter":37,"verses":[{"verse":1,"text":"Siehe, ich sage euch: Es ist mir nicht ratsam, dass ihr noch weiter übersetzt, ehe ihr nach Ohio geht, und dies wegen des Feindes und um euretwillen."},{"verse":2,"text":"Und weiter, ich sage euch: Ihr sollt nicht gehen, ehe ihr mein Evangelium in jenen Teilen gepredigt habt und die Kirche, wo auch immer sie zu finden ist, gestärkt habt, und besonders in Colesville; denn siehe, sie beten mit viel Glauben zu mir."},{"verse":3,"text":"Und weiter, ein Gebot gebe ich der Kirche, dass es mir ratsam ist, dass sie sich in Ohio sammeln in Vorbereitung auf die Zeit, da mein Diener Oliver Cowdery zu ihnen zurückkehren wird."},{"verse":4,"text":"Siehe, hier ist Weisheit, und lasst jedermann selbst entscheiden, bis ich komme. So ist es. Amen."}]},{"chapter":38,"verses":[{"verse":1,"text":"So spricht der Herr, euer Gott, nämlich Jesus Christus, der Große Ich Bin, Alpha und Omega, der Anfang und das Ende, er, der auf den weiten Raum der Ewigkeit und all die seraphischen Scharen des Himmels blickte, ehe die Welt gemacht wurde;"},{"verse":2,"text":"er, der alles weiß, denn alles ist vor meinen Augen gegenwärtig;"},{"verse":3,"text":"ich bin es, der sprach, und die Welt wurde gemacht, und alles ist durch mich geworden."},{"verse":4,"text":"Ich bin es, der ich das Zion Henochs in meinen eigenen Schoß aufgenommen habe; und, wahrlich, ich sage, ja, selbst alle, die an meinen Namen geglaubt haben, denn ich bin Christus, und in meinem eigenen Namen, kraft des Blutes, das ich vergossen habe, habe ich mich beim Vater für sie eingesetzt."},{"verse":5,"text":"Aber siehe, die Schlechten, die noch übrig sind, habe ich in den Ketten der Finsternis gehalten bis zum Gericht des großen Tages, das am Ende der Erde kommen wird;"},{"verse":6,"text":"und ebenso werde ich die Schlechten halten lassen, die meine Stimme nicht vernehmen wollen, sondern ihr Herz verhärten; und Weh, Weh, Weh ist ihr Schicksal."},{"verse":7,"text":"Aber siehe, wahrlich, wahrlich, ich sage euch: Meine Augen ruhen auf euch. Ich bin mitten unter euch, und ihr könnt mich nicht sehen;"},{"verse":8,"text":"aber der Tag kommt bald, da ihr mich sehen und wissen werdet, dass ich bin; denn der Schleier der Finsternis wird bald zerrissen werden, und wer nicht rein gemacht worden ist, wird den Tag nicht aushalten."},{"verse":9,"text":"Darum gürtet euch die Lenden und seid bereit. Siehe, das Reich ist euer, und der Feind wird nicht überwinden."},{"verse":10,"text":"Wahrlich, ich sage euch: Ihr seid rein, aber nicht alle; und es gibt sonst niemanden, an dem ich Wohlgefallen habe;"},{"verse":11,"text":"denn alles Fleisch ist verdorben vor mir; und die Mächte der Finsternis haben auf Erden überhandgenommen, unter den Menschenkindern, in Gegenwart aller Scharen des Himmels –"},{"verse":12,"text":"was die Ursache ist, dass Stille herrscht und die ganze Ewigkeit leidet und die Engel auf den großen Befehl warten, die Erde abzuernten, das Unkraut einzusammeln, um es zu verbrennen; und siehe, der Feind hat sich zusammengeschlossen."},{"verse":13,"text":"Und nun zeige ich euch ein Geheimnis, etwas, was in geheimen Gemächern ist, um im Laufe der Zeit sogar eure Vernichtung zustande zu bringen, und ihr habt es nicht gewusst;"},{"verse":14,"text":"aber nun sage ich es euch, und ihr seid gesegnet, nicht wegen eures Übeltuns, auch nicht wegen eures ungläubigen Herzens; denn wahrlich, einige von euch sind vor mir schuldig, aber ich werde eurer Schwachheit barmherzig sein."},{"verse":15,"text":"Darum seid von nun an stark; fürchtet euch nicht, denn das Reich ist euer."},{"verse":16,"text":"Und zu eurer Errettung gebe ich euch ein Gebot, denn ich habe eure Gebete vernommen, und die Armen haben vor mir geklagt, und die Reichen habe ich erschaffen, und alles Fleisch ist mein, und ich sehe nicht auf die Person."},{"verse":17,"text":"Und ich habe die Erde reich gemacht, und siehe, sie ist mein Fußschemel, darum werde ich wieder auf ihr stehen."},{"verse":18,"text":"Und ich biete euch größere Reichtümer, und es beliebt mir, sie euch zu geben, ja, ein Land der Verheißung, ein Land, in dem Milch und Honig fließen, auf dem kein Fluch ruhen wird, wenn der Herr kommt;"},{"verse":19,"text":"und ich will es euch als das Land eures Erbteils geben, wenn ihr mit eurem ganzen Herzen danach trachtet."},{"verse":20,"text":"Und dies wird mein Bund mit euch sein: Ihr sollt es als das Land eures Erbteils haben und als das Erbteil eurer Kinder immerdar, solange die Erde besteht, und ihr werdet es in der Ewigkeit weiter besitzen, und es soll nicht mehr vergehen."},{"verse":21,"text":"Aber wahrlich, ich sage euch: Mit der Zeit werdet ihr keinen König noch Herrscher haben, denn ich werde euer König sein und über euch wachen."},{"verse":22,"text":"Darum vernehmt meine Stimme und folgt mir nach, und ihr werdet ein freies Volk sein, und ihr werdet, wenn ich komme, keine anderen Gesetze haben als meine Gesetze, denn ich bin euer Gesetzgeber, und was könnte meine Hand zurückhalten?"},{"verse":23,"text":"Aber wahrlich, ich sage euch: Belehrt einander gemäß dem Amt, wozu ich euch bestimmt habe,"},{"verse":24,"text":"und lasst jedermann seinen Bruder achten wie sich selbst und Tugend und Heiligkeit vor mir üben."},{"verse":25,"text":"Und abermals sage ich euch: Lasst jedermann seinen Bruder achten wie sich selbst."},{"verse":26,"text":"Denn welcher Mann unter euch, der zwölf Söhne hat und sie nicht unterschiedlich ansieht, und sie dienen ihm voller Gehorsam, und er sagt zu dem einen: Kleide dich in ein Festgewand und setze dich hierher, und zu dem anderen: Kleide dich in Lumpen und setze dich dorthin – blickt dann auf seine Söhne und sagt: Ich bin gerecht?"},{"verse":27,"text":"Siehe, dies habe ich euch als Gleichnis gegeben, und es ist so, wie ich bin. Ich sage euch: Seid eins; und wenn ihr nicht eins seid, dann seid ihr nicht mein."},{"verse":28,"text":"Und weiter, ich sage euch: Der Feind in den geheimen Gemächern trachtet euch nach dem Leben."},{"verse":29,"text":"Ihr hört von Kriegen in fernen Ländern, und ihr sagt, es werde bald große Kriege in fernen Ländern geben; aber ihr kennt nicht die Herzen der Menschen in eurem eigenen Land."},{"verse":30,"text":"Ich sage euch das, weil ihr gebetet habt; darum häuft euch im Herzen Weisheit auf wie einen Schatz, damit nicht die Schlechtigkeit der Menschen euch dies durch ihre Schlechtigkeit offenbare, auf eine Weise, die euch in den Ohren gellt mit einer Stimme, die lauter ist als das, was die Erde erzittern lassen wird; aber wenn ihr bereit seid, werdet ihr euch nicht fürchten."},{"verse":31,"text":"Und damit ihr der Macht des Feindes entrinnen mögt und euch als ein rechtschaffenes Volk ohne Makel und schuldlos zu mir her sammelt –"},{"verse":32,"text":"aus diesem Grund also habe ich euch das Gebot gegeben, an den Ohio zu gehen; und dort werde ich euch mein Gesetz geben; und dort werdet ihr mit Macht aus der Höhe ausgerüstet werden;"},{"verse":33,"text":"und von dort soll, wer auch immer ich will, hingehen unter alle Nationen, und es wird ihnen gesagt werden, was sie tun sollen; denn ich habe ein großes Werk bereitliegen, denn Israel wird errettet werden, und ich werde sie führen, wohin auch immer ich will, und keine Macht wird meine Hand zurückhalten."},{"verse":34,"text":"Und nun gebe ich der Kirche in diesen Teilen das Gebot, dass einige Männer unter ihnen bestimmt werden sollen, und sie sollen durch die Stimme der Kirche bestimmt werden;"},{"verse":35,"text":"und sie sollen nach den Armen und Bedürftigen sehen und ihnen Hilfe zuteilwerden lassen, sodass sie nicht leiden, und sie nach dem Ort senden, den ich ihnen geboten habe;"},{"verse":36,"text":"und dies soll ihre Arbeit sein, die Angelegenheiten des Eigentums dieser Kirche zu regeln."},{"verse":37,"text":"Und diejenigen, die eine Farm haben, die nicht verkauft werden kann, sollen sie zurücklassen oder verpachten, wie es ihnen gut scheint."},{"verse":38,"text":"Seht zu, dass alles bewahrt wird; und wenn Männer mit Macht aus der Höhe ausgerüstet sind und ausgesandt werden, dann soll dies alles in den Schoß der Kirche eingebracht werden."},{"verse":39,"text":"Und wenn ihr nach den Reichtümern trachtet, die euch der Vater zu geben gewillt ist, werdet ihr das reichste aller Völker sein, denn ihr werdet die Reichtümer der Ewigkeit haben; und es muss notwendigerweise so sein, dass die Reichtümer der Erde mein sind, dass ich sie gebe; aber hütet euch vor dem Stolz, damit ihr nicht werdet wie die Nephiten vor alters."},{"verse":40,"text":"Und weiter, ich sage euch: Ich gebe euch das Gebot, dass ein jeder Mann, ob Ältester, Priester, Lehrer oder auch Mitglied, mit aller Macht darangehe, durch seiner Hände Arbeit all das vorzubereiten und auszuführen, was ich geboten habe."},{"verse":41,"text":"Und lasst euer Predigen die warnende Stimme sein, jedermann für seinen Nächsten, voll Milde und voll Sanftmut."},{"verse":42,"text":"Und geht fort von denen, die schlecht sind. Errettet euch. Seid rein, die ihr die Gefäße des Herrn tragt. So ist es. Amen."}]},{"chapter":39,"verses":[{"verse":1,"text":"Horche auf und höre auf die Stimme dessen, der von aller Ewigkeit bis in alle Ewigkeit ist, der Große Ich Bin, nämlich Jesus Christus –"},{"verse":2,"text":"das Licht und das Leben der Welt; ein Licht, das in der Finsternis leuchtet, und die Finsternis erfasst es nicht;"},{"verse":3,"text":"ich bin es, der ich in der Mitte der Zeit zu den Meinen gekommen bin, und die Meinen haben mich nicht empfangen;"},{"verse":4,"text":"aber allen, die mich empfangen haben, gab ich die Macht, meine Söhne zu werden; und ebenso will ich allen, die mich noch empfangen, die Macht geben, meine Söhne zu werden."},{"verse":5,"text":"Und wahrlich, wahrlich, ich sage euch: Wer mein Evangelium empfängt, der empfängt mich, und wer mein Evangelium nicht empfängt, der empfängt mich nicht."},{"verse":6,"text":"Und dies ist mein Evangelium: Umkehr und Taufe im Wasser, und dann kommt die Taufe mit Feuer und dem Heiligen Geist, nämlich dem Tröster, der alles kundtut und das Friedfertige des Reiches lehrt."},{"verse":7,"text":"Und nun, siehe, ich sage dir, mein Diener James: Ich habe deine Werke angesehen, und ich kenne dich."},{"verse":8,"text":"Und wahrlich, ich sage dir: Dein Herz ist jetzt, zu dieser Zeit, vor mir recht, und siehe, ich habe dir große Segnungen auf dein Haupt zuteilwerden lassen;"},{"verse":9,"text":"doch hast du große Betrübnis erfahren, denn du hast mich viele Male wegen des Stolzes und wegen der Sorgen der Welt verworfen."},{"verse":10,"text":"Aber siehe, die Tage deiner Befreiung sind gekommen, wenn du auf meine Stimme hören willst, die zu dir sagt: Erhebe dich und lass dich taufen, und wasche deine Sünden weg, und rufe dabei meinen Namen an, dann wirst du meinen Geist empfangen und eine Segnung, so groß, wie du nie eine erfahren hast."},{"verse":11,"text":"Und wenn du dies tust, so habe ich dich für ein größeres Werk vorbereitet. Du sollst die Fülle meines Evangeliums predigen, die ich in diesen letzten Tagen ausgesandt habe, den Bund, den ich ausgesandt habe, um mein Volk, das vom Haus Israel ist, zurückzugewinnen."},{"verse":12,"text":"Und es wird sich begeben: Macht wird auf dir ruhen; du wirst großen Glauben haben, und ich werde mit dir sein und vor deinem Angesicht hergehen."},{"verse":13,"text":"Du bist berufen, in meinem Weingarten zu arbeiten und meine Kirche aufzubauen und Zion hervorzubringen, damit es sich auf den Hügeln freue und erblühe."},{"verse":14,"text":"Siehe, wahrlich, wahrlich, ich sage dir: Du bist nicht berufen, in die östlichen Länder zu gehen, sondern du bist berufen, nach Ohio zu gehen."},{"verse":15,"text":"Und da mein Volk sich in Ohio versammelt, habe ich eine Segnung bereitliegen, wie man sie unter den Menschenkindern noch nicht erfahren hat, und sie wird ihnen auf ihr Haupt ausgegossen werden. Und von dort aus sollen Männer zu allen Nationen hingehen."},{"verse":16,"text":"Siehe, wahrlich, wahrlich, ich sage euch: Das Volk in Ohio ruft mich mit viel Glauben an und denkt, ich würde meine Hand beim Richten der Nationen zurückhalten, aber ich kann mein Wort nicht verleugnen."},{"verse":17,"text":"Darum macht euch mit aller Kraft daran, und beruft treue Arbeiter in meinen Weingarten, dass er zum letzten Mal beschnitten werde."},{"verse":18,"text":"Und insofern sie umkehren und die Fülle meines Evangeliums empfangen und geheiligt werden, werde ich meine Hand beim Richten zurückhalten."},{"verse":19,"text":"Darum geht hin, ruft mit lauter Stimme, nämlich: Das Himmelreich ist nahe. Ruft: Hosanna!, gesegnet sei der Name des allerhöchsten Gottes."},{"verse":20,"text":"Geht hin und tauft mit Wasser, und bereitet vor meinem Angesicht den Weg für die Zeit meines Kommens;"},{"verse":21,"text":"denn die Zeit ist nahe; den Tag oder die Stunde weiß kein Mensch; aber sie wird gewiss kommen."},{"verse":22,"text":"Und wer dies alles empfängt, der empfängt mich; und sie werden in der Zeit und in der Ewigkeit zu mir gesammelt werden."},{"verse":23,"text":"Und weiter, es wird sich begeben: Allen, die ihr mit Wasser tauft, sollt ihr eure Hände auflegen, und sie sollen die Gabe des Heiligen Geistes empfangen und sollen nach den Zeichen meines Kommens ausschauen und werden mich erkennen."},{"verse":24,"text":"Siehe, ich komme schnell. So ist es. Amen."}]},{"chapter":40,"verses":[{"verse":1,"text":"Siehe, wahrlich, ich sage euch: Das Herz meines Dieners James Covel war vor mir recht, denn er machte mit mir den Bund, dass er meinem Wort gehorchen werde."},{"verse":2,"text":"Und er empfing das Wort mit Freuden, aber sogleich versuchte ihn der Satan, und die Furcht vor Verfolgung und die Sorgen der Welt ließen ihn das Wort verwerfen."},{"verse":3,"text":"Darum hat er meinen Bund gebrochen, und es bleibt mir überlassen, mit ihm zu verfahren, wie es mir gut scheint. Amen."}]},{"chapter":41,"verses":[{"verse":1,"text":"Horcht auf und vernehmt, o ihr mein Volk, spricht der Herr und euer Gott, ihr, die ich voll Freude mit der größten aller Segnungen segne, euch, die ihr auf mich hört; und euch, die ihr nicht auf mich hört, werde ich verfluchen, die ihr euch zu meinem Namen bekannt habt, mit dem schwersten aller Flüche."},{"verse":2,"text":"Horcht auf, o ihr Ältesten meiner Kirche, die ich berufen habe; siehe, ich gebe euch das Gebot, euch zu versammeln, damit ihr euch über mein Wort einig seid;"},{"verse":3,"text":"und durch das Gebet eures Glaubens werdet ihr mein Gesetz empfangen, damit ihr wisst, wie ihr meine Kirche führen sollt und alles vor mir richtig habt."},{"verse":4,"text":"Und ich werde euer Herrscher sein, wenn ich komme; und siehe, ich komme schnell, und ihr sollt darauf sehen, dass mein Gesetz eingehalten wird."},{"verse":5,"text":"Wer mein Gesetz empfängt und es tut, der ist mein Jünger; und wer sagt, er empfange es, und tut es nicht, der ist nicht mein Jünger und soll aus eurer Mitte ausgestoßen werden;"},{"verse":6,"text":"denn es ist nicht recht, wenn das, was den Kindern des Reiches gehört, denen gegeben wird, die nicht würdig sind, oder den Hunden, oder dass die Perlen vor die Schweine geworfen werden."},{"verse":7,"text":"Und weiter: Es ist recht, dass meinem Diener Joseph Smith Jr. ein Haus gebaut werde, worin er wohnen und übersetzen kann."},{"verse":8,"text":"Und weiter: Es ist recht, dass mein Diener Sidney Rigdon so lebe, wie es ihm gut scheint, sofern er meine Gebote hält."},{"verse":9,"text":"Und weiter: Ich habe meinen Diener Edward Partridge berufen; und ich gebe das Gebot, er soll durch die Stimme der Kirche bestimmt und zum Bischof für die Kirche ordiniert werden, sein Handelsgeschäft aufgeben und seine gesamte Zeit auf die Arbeit der Kirche verwenden,"},{"verse":10,"text":"um alles so zu versehen, wie es ihm in meinen Gesetzen bestimmt wird an dem Tag, da ich sie geben werde."},{"verse":11,"text":"Und dies, weil sein Herz rein vor mir ist, denn er ist so wie Natanaël vor alters, in dem keine Falschheit ist."},{"verse":12,"text":"Diese Worte sind euch gegeben, und sie sind rein vor mir; darum nehmt euch in Acht, wie ihr damit umgeht, denn am Tag des Gerichts wird eure Seele sich dafür verantworten müssen. So ist es. Amen."}]},{"chapter":42,"verses":[{"verse":1,"text":"Horcht auf, o ihr Ältesten meiner Kirche, die ihr euch versammelt habt in meinem Namen, nämlich Jesu Christi, des Sohnes des lebendigen Gottes, des Erretters der Welt, da ihr an meinen Namen glaubt und meine Gebote haltet."},{"verse":2,"text":"Abermals sage ich euch: Horcht auf und vernehmt und beachtet das Gesetz, das ich euch geben werde."},{"verse":3,"text":"Denn wahrlich, ich sage: Da ihr euch versammelt habt gemäß dem Gebot, womit ich euch geboten habe, und euch einig seid, was diese eine Sache betrifft, und den Vater in meinem Namen gebeten habt, werdet ihr ebenso empfangen."},{"verse":4,"text":"Siehe, wahrlich, ich sage euch: Ich gebe euch dies erste Gebot, dass ihr in meinem Namen ausgehen sollt, ein jeder von euch, ausgenommen meine Diener Joseph Smith Jr. und Sidney Rigdon."},{"verse":5,"text":"Und ich gebe ihnen das Gebot, dass sie eine kurze Zeit lang ausgehen sollen, und es wird durch die Macht des Geistes gegeben werden, wann sie zurückkehren sollen."},{"verse":6,"text":"Und ihr sollt in der Macht meines Geistes ausgehen und mein Evangelium predigen, zu zweit, in meinem Namen, und eure Stimme erheben wie mit dem Ton einer Posaune und mein Wort wie Engel Gottes verkündigen."},{"verse":7,"text":"Und ihr sollt hingehen und mit Wasser taufen und sagen: Kehrt um, kehrt um, denn das Himmelreich ist nahe."},{"verse":8,"text":"Und von diesem Ort aus sollt ihr in die Gebiete im Westen hingehen; und insoweit ihr die findet, die euch empfangen, sollt ihr in jedem Gebiet meine Kirche aufrichten –"},{"verse":9,"text":"bis die Zeit kommt, da es euch aus der Höhe offenbart werden wird, wann das Neue Jerusalem als Stadt bereitet werden soll, damit ihr in eins zusammengeführt seiet, damit ihr mein Volk seiet, und ich werde euer Gott sein."},{"verse":10,"text":"Und weiter, ich sage euch: Mein Diener Edward Partridge soll in dem Amt stehen, zu dem ich ihn bestimmt habe. Und es wird sich begeben: Wenn er übertritt, wird ein anderer an seiner statt bestimmt werden. So ist es. Amen."},{"verse":11,"text":"Weiter, ich sage euch: Keinem soll es gegeben sein hinzugehen, um mein Evangelium zu predigen oder meine Kirche aufzurichten, außer er sei von jemandem ordiniert worden, der Vollmacht hat, und es ist der Kirche bekannt, dass er Vollmacht hat und von den Häuptern der Kirche ordnungsgemäß ordiniert worden ist."},{"verse":12,"text":"Und weiter: Die Ältesten, Priester und Lehrer dieser Kirche sollen die Grundsätze meines Evangeliums lehren, die in der Bibel und im Buch Mormon stehen, worin die Fülle des Evangeliums enthalten ist."},{"verse":13,"text":"Und sie sollen darauf bedacht sein, die Bündnisse und Satzungen der Kirche zu befolgen, und diese sollen ihre Lehren sein, wie sie vom Geist geleitet werden."},{"verse":14,"text":"Und der Geist wird euch durch das Gebet des Glaubens gegeben; und wenn ihr den Geist nicht empfangt, sollt ihr nicht lehren."},{"verse":15,"text":"Und all dies zu tun, sollt ihr bedacht sein, wie ich es hinsichtlich eures Lehrens geboten habe, bis die Fülle meiner Schriften gegeben werden wird."},{"verse":16,"text":"Und wenn ihr durch den Tröster eure Stimme erhebt, werdet ihr reden und prophezeien, wie es mir gut scheint;"},{"verse":17,"text":"denn siehe, der Tröster weiß alles und gibt Zeugnis für den Vater und den Sohn."},{"verse":18,"text":"Und nun, siehe, ich spreche zur Kirche: Du sollst nicht töten; und wer tötet, wird weder in dieser Welt noch in der künftigen Welt Vergebung haben."},{"verse":19,"text":"Und weiter, ich sage, du sollst nicht töten; wer aber tötet, soll sterben."},{"verse":20,"text":"Du sollst nicht stehlen; und wer stiehlt und nicht umkehren will, soll ausgestoßen werden."},{"verse":21,"text":"Du sollst nicht lügen; wer lügt und nicht umkehren will, soll ausgestoßen werden."},{"verse":22,"text":"Du sollst deine Frau mit deinem ganzen Herzen lieben und sollst an ihr festhalten und an niemandem und nichts sonst."},{"verse":23,"text":"Und wer eine Frau ansieht, dass es ihn nach ihr gelüstet, der wird den Glauben verleugnen und wird den Geist nicht haben; und wenn er nicht umkehrt, soll er ausgestoßen werden."},{"verse":24,"text":"Du sollst nicht Ehebruch begehen; und wer Ehebruch begeht und nicht umkehrt, soll ausgestoßen werden."},{"verse":25,"text":"Aber dem, der Ehebruch begangen hat und mit seinem ganzen Herzen umkehrt und davon lässt und es nicht mehr tut, sollst du vergeben;"},{"verse":26,"text":"tut er es aber wieder, so soll ihm nicht vergeben werden, sondern er soll ausgestoßen werden."},{"verse":27,"text":"Du sollst von deinem Nächsten nichts Böses reden noch ihm irgendeinen Schaden tun."},{"verse":28,"text":"Du weißt, dass meine Gesetze hierüber in meinen Schriften gegeben sind; wer sündigt und nicht umkehrt, soll ausgestoßen werden."},{"verse":29,"text":"Wenn du mich liebst, sollst du mir dienen und alle meine Gebote halten."},{"verse":30,"text":"Und siehe, du wirst der Armen gedenken und von deinem Eigentum das, was du mit ihnen teilen kannst, ihrer Unterstützung weihen, mit einem Bündnis und einem Vertrag, der nicht gebrochen werden kann."},{"verse":31,"text":"Und wenn ihr von eurer Habe mit den Armen teilt, so tut ihr es mir; und es soll vor den Bischof meiner Kirche und seine Ratgeber gelegt werden, zwei von den Ältesten oder Hohen Priestern, wie er sie zu diesem Zweck bestimmen mag oder schon bestimmt und eingesetzt hat."},{"verse":32,"text":"Und es wird sich begeben: Nachdem es dem Bischof meiner Kirche vorgelegt worden ist und nachdem er diese Zeugnisse über die Weihung des Eigentums meiner Kirche empfangen hat, dass es der Kirche nicht mehr genommen werden kann, in Übereinstimmung mit meinen Geboten, dann wird jedermann als Treuhänder über seinem Eigentum oder dem, was er durch Weihung empfangen hat – so viel, wie für ihn und seine Familie ausreichend ist –, vor mir rechenschaftspflichtig sein."},{"verse":33,"text":"Und weiter, wenn in den Händen der Kirche oder eines ihrer Zugehörigen mehr Eigentum verbleibt, als für deren Unterhalt nach dieser ersten Weihung nötig ist – also ein Rest, der dem Bischof zu weihen ist –, so soll es aufbewahrt werden, um von Zeit zu Zeit denen zuteilzuwerden, die nicht haben, damit jedermann, der bedürftig ist, hinreichend versorgt werde und gemäß seinen Bedürfnissen empfange."},{"verse":34,"text":"Darum soll der Rest in meinem Vorratshaus aufbewahrt werden, damit den Armen und den Bedürftigen zuteilwerden kann, wie es von dem Hoherat der Kirche und dem Bischof und seinem Rat bestimmt wird,"},{"verse":35,"text":"auch zum Zwecke des Landerwerbs zum allgemeinen Wohl der Kirche und um Gotteshäuser zu bauen und um das Neue Jerusalem zu errichten, das später noch offenbart werden wird –"},{"verse":36,"text":"damit mein Bundesvolk in eins zusammengeführt sei an dem Tag, da ich zu meinem Tempel kommen werde. Und dies tue ich zur Errettung meines Volkes."},{"verse":37,"text":"Und es wird sich begeben: Wer sündigt und nicht umkehrt, soll aus der Kirche ausgestoßen werden und soll das nicht wieder empfangen, was er den Armen und den Bedürftigen meiner Kirche oder, mit anderen Worten, mir geweiht hat –"},{"verse":38,"text":"denn wenn ihr es dem Geringsten von diesen tut, so tut ihr es mir."},{"verse":39,"text":"Denn es wird sich begeben: Das, was ich durch den Mund meiner Propheten gesprochen habe, wird sich erfüllen; denn ich werde von den Reichtümern derjenigen unter den Anderen, die mein Evangelium annehmen, den Armen meines Volkes, die vom Haus Israel sind, weihen."},{"verse":40,"text":"Und weiter, du sollst nicht stolz sein in deinem Herzen; lass alle deine Gewänder einfach sein und ihre Schönheit die Schönheit der Arbeit deiner eigenen Hände;"},{"verse":41,"text":"und lass alles in Reinlichkeit vor mir geschehen."},{"verse":42,"text":"Du sollst nicht müßig sein, denn wer müßig ist, soll weder das Brot des Arbeiters essen noch dessen Gewand tragen."},{"verse":43,"text":"Und wer auch immer unter euch krank ist und nicht den Glauben hat, geheilt zu werden, aber gläubig ist, soll voller Zartgefühl mit Kräutern und leichter Kost ernährt werden, und das nicht durch die Hand eines Feindes."},{"verse":44,"text":"Und die Ältesten der Kirche, zwei oder mehr, sollen gerufen werden und sollen für ihn beten und ihm in meinem Namen die Hände auflegen; und wenn er stirbt, so stirbt er in mir, und wenn er lebt, so lebt er in mir."},{"verse":45,"text":"Ihr sollt liebevoll miteinander leben, sodass ihr über den Verlust derer, die sterben, weinen werdet, besonders aber über diejenigen, die nicht die Hoffnung auf eine herrliche Auferstehung haben."},{"verse":46,"text":"Und es wird sich begeben: Wer in mir stirbt, wird den Tod nicht schmecken, denn er wird ihm süß sein;"},{"verse":47,"text":"und wer nicht in mir stirbt, weh ihm, denn sein Tod ist bitter."},{"verse":48,"text":"Und weiter, es wird sich begeben: Wer den Glauben an mich hat, geheilt zu werden, und nicht für den Tod bestimmt ist, wird geheilt werden."},{"verse":49,"text":"Wer den Glauben hat zu sehen, wird sehen."},{"verse":50,"text":"Wer den Glauben hat zu hören, wird hören."},{"verse":51,"text":"Der Lahme, der den Glauben hat zu springen, wird springen."},{"verse":52,"text":"Und diejenigen, die nicht den Glauben haben, dies zu tun, die aber an mich glauben, haben die Macht, meine Söhne zu werden; und insoweit sie meine Gesetze nicht brechen, sollst du ihre Schwächen ertragen."},{"verse":53,"text":"Du sollst am Platz deiner Treuhandschaft stehen."},{"verse":54,"text":"Du sollst nicht deines Bruders Gewand nehmen; du sollst das bezahlen, was du von deinem Bruder empfängst."},{"verse":55,"text":"Und wenn du mehr erlangst, als das, was für deinen Unterhalt wäre, sollst du es in mein Vorratshaus geben, damit alles so geschehe, wie ich es gesagt habe."},{"verse":56,"text":"Du sollst bitten, und meine Schriften werden gegeben werden, wie ich es bestimmt habe, und sie sollen in Sicherheit aufbewahrt werden;"},{"verse":57,"text":"und es ist ratsam, dass du über sie Stillschweigen bewahrst und sie nicht lehrst, bis ihr sie vollständig empfangen habt."},{"verse":58,"text":"Und ich gebe euch das Gebot, dass ihr sie dann alle Menschen lehren sollt; denn sie sollen allen Nationen, Geschlechtern, Sprachen und Völkern gelehrt werden."},{"verse":59,"text":"Du sollst all das, was du empfangen hast, was dir in meinen Schriften als Gesetz gegeben worden ist, als mein Gesetz zur Führung meiner Kirche nehmen;"},{"verse":60,"text":"und wer gemäß dem allen handelt, wird errettet werden, und wer nicht so handelt, wird verdammt werden, wenn er so weitermacht."},{"verse":61,"text":"Wenn du bittest, wirst du Offenbarung um Offenbarung, Erkenntnis um Erkenntnis empfangen, damit du die Geheimnisse und das Friedfertige erkennen mögest – das, was Freude bringt, das, was ewiges Leben bringt."},{"verse":62,"text":"Du sollst bitten, dann wird euch zu der von mir selbst bestimmten Zeit offenbart werden, wo das Neue Jerusalem erbaut werden soll."},{"verse":63,"text":"Und siehe, es wird sich begeben: Meine Diener sollen nach dem Osten und nach dem Westen, nach dem Norden und nach dem Süden ausgesandt werden."},{"verse":64,"text":"Und schon jetzt lasst den, der nach dem Osten geht, diejenigen, die bekehrt werden, belehren, dass sie nach dem Westen fliehen, und dies im Hinblick auf das, was auf Erden kommen wird, und auf geheime Verbindungen."},{"verse":65,"text":"Siehe, du sollst dies alles befolgen, und groß wird dein Lohn sein; denn euch ist es gegeben, die Geheimnisse des Reiches zu kennen, aber der Welt ist es nicht gegeben, sie zu kennen."},{"verse":66,"text":"Ihr sollt die Gesetze befolgen, die ihr empfangen habt, und treu sein."},{"verse":67,"text":"Und ihr werdet später noch kirchliche Bündnisse empfangen, die genügen werden, euch hier und auch im Neuen Jerusalem fest aufzurichten."},{"verse":68,"text":"Darum, wem es an Weisheit fehlt, der soll mich bitten, und ich werde ihm gern geben und ihm keine Vorwürfe machen."},{"verse":69,"text":"Hebt euer Herz empor und freut euch, denn euch ist das Reich oder, mit anderen Worten, sind die Schlüssel der Kirche gegeben. So ist es. Amen."},{"verse":70,"text":"Die Priester und Lehrer sollen ihre Treuhandschaft haben, ebenso wie die Mitglieder."},{"verse":71,"text":"Und die Ältesten oder Hohen Priester, die bestimmt sind, dem Bischof in allem als Ratgeber behilflich zu sein, sollen Unterhalt für ihre Familie aus dem Eigentum bekommen, das dem Bischof zum Wohl der Armen und für andere Zwecke, wie zuvor erwähnt, geweiht worden ist,"},{"verse":72,"text":"oder sie sollen für alle ihre Dienste eine gerechte Vergütung empfangen, entweder eine Treuhandschaft oder auf andere Weise, wie es von den Ratgebern und dem Bischof für das Beste gehalten oder beschlossen wird."},{"verse":73,"text":"Und der Bischof soll auch seinen Unterhalt oder eine gerechte Vergütung für alle seine Dienste in der Kirche empfangen."},{"verse":74,"text":"Siehe, wahrlich, ich sage euch: Wenn sich jemand unter euch von seinem Ehepartner wegen dessen Unzucht losgesagt hat oder, mit anderen Worten, wenn jemand in aller Herzensdemut vor euch bezeugt, dass dies der Fall ist, so sollt ihr ihn nicht aus eurer Mitte ausstoßen;"},{"verse":75,"text":"findet ihr aber heraus, dass jemand seinen Ehepartner um des Ehebruchs willen verlassen hat und er selbst der Missetäter ist und sein Ehepartner noch am Leben ist, so soll er aus eurer Mitte ausgestoßen werden."},{"verse":76,"text":"Und weiter, ich sage euch: Ihr sollt aufmerksam und vorsichtig sein und allenthalben nachforschen, damit ihr so jemanden nicht bei euch aufnehmt, sofern er verheiratet ist;"},{"verse":77,"text":"und wenn er nicht verheiratet ist, soll er von all seinen Sünden umkehren, sonst sollt ihr ihn nicht aufnehmen."},{"verse":78,"text":"Und weiter: Jeder, der dieser Kirche Christi angehört, soll darauf bedacht sein, alle Gebote und Bündnisse der Kirche zu halten."},{"verse":79,"text":"Und es wird sich begeben: Wenn jemand von euch tötet, so soll er gemäß den Gesetzen des Landes überantwortet und behandelt werden; denn bedenkt, er hat keine Vergebung; und es soll gemäß den Gesetzen des Landes bewiesen werden."},{"verse":80,"text":"Und wenn jemand, Mann oder Frau, Ehebruch begeht, so soll vor zwei oder mehr Ältesten der Kirche gegen ihn oder sie vorgegangen werden, und jedes Wort gegen ihn oder sie soll von zwei Zeugen aus der Kirche, nicht aber vom Feind, bestätigt werden; aber wenn es mehr als zwei Zeugen gibt, ist es besser."},{"verse":81,"text":"Aber er oder sie soll durch den Mund zweier Zeugen schuldig gesprochen werden; und die Ältesten sollen den Fall der Gemeinde vorlegen, und die Gemeinde soll die Hand gegen ihn oder sie emporheben, damit gemäß dem Gesetz Gottes mit ihnen verfahren werden kann."},{"verse":82,"text":"Und wenn es sein kann, ist es notwendig, dass auch der Bischof anwesend ist."},{"verse":83,"text":"Und so sollt ihr in allen Fällen verfahren, die vor euch kommen."},{"verse":84,"text":"Und wenn ein Mann oder eine Frau einen Raub verübt, so soll er oder sie dem Gesetz des Landes überantwortet werden."},{"verse":85,"text":"Und wenn er oder sie stiehlt, soll er oder sie dem Gesetz des Landes überantwortet werden."},{"verse":86,"text":"Und wenn er oder sie lügt, soll er oder sie dem Gesetz des Landes überantwortet werden."},{"verse":87,"text":"Und wenn er oder sie irgendeine Art Übeltun begeht, soll er oder sie dem Gesetz überantwortet werden, nämlich dem Gottes."},{"verse":88,"text":"Und wenn dir dein Bruder oder deine Schwester Unrecht tut, sollst du ihn oder sie nehmen, zwischen ihm oder ihr und dir allein; und wenn er oder sie bekennt, sollst du versöhnt sein."},{"verse":89,"text":"Und wenn er oder sie nicht bekennt, sollst du ihn oder sie der Gemeinde überantworten, nicht den Mitgliedern, sondern den Ältesten. Und es soll in einer Sitzung geschehen, und das nicht vor der Welt."},{"verse":90,"text":"Und wenn dein Bruder oder deine Schwester vielen Unrecht tut, so soll er oder sie vor vielen gezüchtigt werden."},{"verse":91,"text":"Und wenn jemand öffentlich Unrecht tut, soll er oder sie öffentlich zurechtgewiesen werden, damit er oder sie sich schäme. Und wenn er oder sie nicht bekennt, soll er oder sie dem Gesetz Gottes überantwortet werden."},{"verse":92,"text":"Wenn jemand im Verborgenen Unrecht tut, soll er oder sie im Verborgenen zurechtgewiesen werden, damit er oder sie Gelegenheit habe, im Verborgenen demjenigen oder derjenigen, dem oder der er oder sie Unrecht getan hat, und Gott zu bekennen, damit die Gemeinde nicht vorwurfsvoll über ihn oder sie rede."},{"verse":93,"text":"Und so sollt ihr euch in allen Angelegenheiten verhalten."}]},{"chapter":43,"verses":[{"verse":1,"text":"O horcht auf, ihr Ältesten meiner Kirche, und schenkt den Worten Gehör, die ich zu euch sprechen werde."},{"verse":2,"text":"Denn siehe, wahrlich, wahrlich, ich sage euch: Ihr habt ein Gebot als Gesetz für meine Kirche empfangen, durch ihn, den ich für euch bestimmt habe, dass er von meiner Hand Gebote und Offenbarungen empfange."},{"verse":3,"text":"Und dies sollt ihr ganz sicher wissen: Es ist kein anderer für euch bestimmt, Gebote und Offenbarungen zu empfangen, bis er hinweggenommen werden wird, sofern er in mir verbleibt."},{"verse":4,"text":"Aber wahrlich, wahrlich, ich sage euch: Kein anderer wird für diese Gabe bestimmt werden außer durch ihn; denn wenn sie von ihm genommen wird, soll er keine Macht haben, außer einen anderen an seiner statt zu bestimmen."},{"verse":5,"text":"Und dies soll euch ein Gesetz sein, dass ihr nicht die Lehren irgendjemandes, der vor euch hintritt, als Offenbarungen oder Gebote annehmt;"},{"verse":6,"text":"und dies gebe ich euch, damit ihr euch nicht täuschen lasst, damit ihr wisst, dass sie nicht von mir sind."},{"verse":7,"text":"Denn wahrlich, ich sage euch: Wer von mir ordiniert ist, wird durch die Pforte hereinkommen und ordiniert werden, wie ich es euch zuvor gesagt habe, um jene Offenbarungen zu lehren, die ihr durch ihn, den ich bestimmt habe, empfangen habt und empfangen werdet."},{"verse":8,"text":"Und nun siehe, ich gebe euch das Gebot: Wenn ihr versammelt seid, so unterweist und erbaut einander, damit ihr wisst, wie ihr handeln und meine Kirche leiten sollt, wie ihr nach den Punkten meines Gesetzes und meiner Gebote, die ich gegeben habe, handeln sollt."},{"verse":9,"text":"Und so werdet ihr im Gesetz meiner Kirche unterwiesen und durch das, was ihr empfangen habt, geheiligt werden, und ihr sollt euch bindend verpflichten, in aller Heiligkeit vor mir zu handeln –"},{"verse":10,"text":"damit, insoweit ihr dies tut, Herrlichkeit dem Reich hinzugefügt werde, das ihr empfangen habt. Insoweit ihr es nicht tut, wird selbst das weggenommen werden, was ihr empfangen habt."},{"verse":11,"text":"Merzt das Übeltun aus, das unter euch vorhanden ist; heiligt euch vor mir;"},{"verse":12,"text":"und wenn ihr die Herrlichkeiten des Reiches haben wollt, dann bestimmt meinen Diener Joseph Smith Jr. und haltet ihn vor mir aufrecht durch das Gebet des Glaubens."},{"verse":13,"text":"Und weiter, ich sage euch: Wenn ihr die Geheimnisse des Reiches haben wollt, dann versorgt ihn mit Speise und Kleidung und allem, was er braucht, um das Werk zu vollbringen, das ich ihm geboten habe;"},{"verse":14,"text":"und wenn ihr es nicht tut, so wird er denen verbleiben, die ihn empfangen haben, damit ich mir ein Volk bewahre, das rein ist vor mir."},{"verse":15,"text":"Weiter, ich sage: Horcht auf, ihr Ältesten meiner Kirche, die ich bestimmt habe: Ihr seid nicht ausgesandt, um euch belehren zu lassen, sondern um die Menschenkinder das zu lehren, was ich euch in die Hand gegeben habe, durch die Macht meines Geistes;"},{"verse":16,"text":"und ihr sollt euch aus der Höhe belehren lassen. Heiligt euch, dann werdet ihr mit Macht ausgerüstet werden, damit ihr geben könnt, so wie ich es gesagt habe."},{"verse":17,"text":"Horcht auf, denn siehe, der große Tag des Herrn steht nahe bevor."},{"verse":18,"text":"Denn der Tag kommt, da der Herr seine Stimme aus dem Himmel erschallen lassen wird; die Himmel werden erbeben, und die Erde wird erzittern, und die Posaune Gottes wird ertönen, lang und auch laut, und wird zu den schlafenden Nationen sprechen: Ihr Heiligen, erhebt euch und lebt; ihr Sünder, bleibt und schlaft, bis ich abermals rufe."},{"verse":19,"text":"Darum gürtet euch die Lenden, damit ihr nicht bei den Schlechten gefunden werdet."},{"verse":20,"text":"Erhebt eure Stimme und haltet nicht zurück. Ruft die Nationen zur Umkehr, ob alt oder jung, ob geknechtet oder frei, und sprecht: Macht euch bereit für den großen Tag des Herrn;"},{"verse":21,"text":"denn wenn schon ich, der ich ein Mensch bin, meine Stimme erhebe und euch zur Umkehr rufe, und ihr hasst mich, was werdet ihr erst sagen, wenn der Tag kommt, da die Donner ihre Stimme von den Enden der Erde erschallen lassen und allen Lebenden in die Ohren rufen, nämlich: Kehrt um, und macht euch bereit für den großen Tag des Herrn?"},{"verse":22,"text":"Ja, und weiter – was, wenn Blitze von Osten nach Westen zucken und für alle Lebenden ihre Stimme erschallen lassen, sodass es allen, die es hören, in den Ohren klingt, nämlich diese Worte: Kehrt um, denn der große Tag des Herrn ist gekommen?"},{"verse":23,"text":"Und weiter, der Herr wird seine Stimme aus dem Himmel erschallen lassen, nämlich: Horcht auf, o ihr Nationen der Erde, und vernehmt die Worte jenes Gottes, der euch erschaffen hat."},{"verse":24,"text":"O ihr Nationen der Erde, wie oft hätte ich euch sammeln mögen wie eine Henne ihre Küken unter ihre Flügel sammelt, aber ihr habt nicht gewollt!"},{"verse":25,"text":"Wie oft habe ich euch durch den Mund meiner Diener zugerufen und durch den Dienst von Engeln und mit meiner eigenen Stimme und mit der Stimme von Donnern und mit der Stimme von Blitzen und mit der Stimme von Unwettern und mit der Stimme von Erdbeben und großen Hagelstürmen und mit der Stimme von Hungersnöten und Seuchen jeder Art und mit dem lauten Ton einer Posaune und mit der Stimme des Gerichts und mit der Stimme der Barmherzigkeit den ganzen Tag lang und mit der Stimme der Herrlichkeit und der Ehre und der Reichtümer des ewigen Lebens und hätte euch erretten wollen mit einer immerwährenden Errettung, aber ihr habt nicht gewollt!"},{"verse":26,"text":"Siehe, der Tag ist gekommen, da der Zornbecher meines Unwillens voll ist."},{"verse":27,"text":"Siehe, wahrlich, ich sage euch: Dies sind die Worte des Herrn, eures Gottes."},{"verse":28,"text":"Darum arbeitet, arbeitet in meinem Weingarten zum letzten Mal – zum letzten Mal ruft den Bewohnern der Erde zu."},{"verse":29,"text":"Denn in der von mir selbst bestimmten Zeit werde ich zum Gericht auf die Erde kommen, und mein Volk wird erlöst werden und wird mit mir auf Erden regieren."},{"verse":30,"text":"Denn das große Millennium, wovon ich durch den Mund meiner Diener gesprochen habe, wird kommen."},{"verse":31,"text":"Denn der Satan wird gebunden werden, und wenn er wieder losgelassen wird, wird er nur noch eine kurze Zeit lang regieren, und dann kommt das Ende der Erde."},{"verse":32,"text":"Und wer in Rechtschaffenheit lebt, wird in einem Augenblick verwandelt werden, und die Erde wird wie durch Feuer vergehen."},{"verse":33,"text":"Und die Schlechten werden fortgehen in ein unauslöschliches Feuer, und ihr Ende kennt kein Mensch auf Erden und wird es auch nie kennen, bis sie zum Gericht vor mich kommen."},{"verse":34,"text":"Hört auf diese Worte. Siehe, ich bin Jesus Christus, der Erretter der Welt. Häuft dies alles in eurem Herzen auf wie einen Schatz, und lasst das Feierliche der Ewigkeit in eurem Sinn verweilen."},{"verse":35,"text":"Seid ernsthaft. Haltet alle meine Gebote. So ist es. Amen."}]},{"chapter":44,"verses":[{"verse":1,"text":"Siehe, so spricht der Herr zu euch, meine Diener: Es ist mir ratsam, dass die Ältesten meiner Kirche zusammengerufen werden, aus dem Osten und aus dem Westen und aus dem Norden und aus dem Süden, durch Briefe oder auf andere Weise."},{"verse":2,"text":"Und es wird sich begeben: Insoweit sie getreu sind und Glauben an mich ausüben, werde ich an dem Tag, da sie sich versammeln, meinen Geist über sie ausgießen."},{"verse":3,"text":"Und es wird sich begeben: Sie sollen in die Gebiete ringsum hinausgehen und dem Volk Umkehr predigen."},{"verse":4,"text":"Und viele werden bekehrt werden, sodass ihr die Macht erlangen werdet, euch gemäß den Gesetzen der Menschen zu organisieren,"},{"verse":5,"text":"damit eure Feinde keine Macht über euch haben, damit ihr in allem bewahrt bleibt, damit ihr imstande seid, meine Gesetze zu befolgen, damit jede Fessel, womit der Feind mein Volk zu vernichten sucht, zerrissen wird."},{"verse":6,"text":"Siehe, ich sage euch: Ihr müsst die Armen und die Bedürftigen besuchen und ihnen Hilfe zuteilwerden lassen, damit sie erhalten bleiben, bis alles gemäß meinem Gesetz geschehen kann, das ihr empfangen habt. Amen."}]},{"chapter":45,"verses":[{"verse":1,"text":"Horcht auf, o ihr Volk meiner Kirche, denen das Reich gegeben worden ist; horcht auf und schenkt Gehör dem, der die Grundlage der Erde gelegt hat, der die Himmel und alle ihre Scharen gemacht hat und durch den alles gemacht worden ist, was lebt und sich regt und ein Dasein hat."},{"verse":2,"text":"Und weiter, ich sage: Hört auf meine Stimme, damit euch nicht der Tod ereile; zu einer Stunde, da ihr es nicht denkt, wird der Sommer vorbei sein und die Ernte zu Ende, und eure Seele ist nicht errettet."},{"verse":3,"text":"Hört auf ihn, der der Fürsprecher beim Vater ist, der sich vor ihm für eure Sache einsetzt –"},{"verse":4,"text":"nämlich: Vater, sieh die Leiden und den Tod dessen, der keine Sünde getan hat, an dem du Wohlgefallen gehabt hast; sieh das Blut deines Sohnes, das vergossen wurde, das Blut dessen, den du hingegeben hast, damit du selbst verherrlicht werdest;"},{"verse":5,"text":"darum, Vater, verschone diese meine Brüder, die an meinen Namen glauben, auf dass sie zu mir kommen können und immerwährendes Leben haben."},{"verse":6,"text":"Horcht auf, o ihr Volk meiner Kirche, und ihr Ältesten, hört allesamt zu und vernehmt meine Stimme, solange es noch „heute“ heißt, und verhärtet nicht euer Herz;"},{"verse":7,"text":"denn wahrlich, ich sage euch: Ich bin Alpha und Omega, der Anfang und das Ende, das Licht und das Leben der Welt – ein Licht, das in der Finsternis leuchtet, und die Finsternis erfasst es nicht."},{"verse":8,"text":"Ich bin zu den Meinen gekommen, und die Meinen haben mich nicht empfangen; aber allen, die mich empfingen, gab ich die Macht, viele Wundertaten zu tun und Söhne Gottes zu werden; ja, und denen, die an meinen Namen glaubten, gab ich die Macht, ewiges Leben zu erlangen."},{"verse":9,"text":"Und so habe ich auch meinen immerwährenden Bund in die Welt gesandt, dass er der Welt ein Licht sei und dass er meinem Volk ein Banner sei und damit die Anderen ihn suchen und dass er vor meinem Angesicht ein Bote sei, den Weg vor mir zu bereiten."},{"verse":10,"text":"Darum kommt zu ihm, und dem, der kommt, werde ich meine Gründe darlegen wie den Männern in alten Tagen, und ich werde euch meine starken Gründe zeigen."},{"verse":11,"text":"Darum horcht allesamt auf, und lasst mich euch auch meine Weisheit zeigen – die Weisheit dessen, von dem ihr sagt, er sei der Gott Henochs und seiner Brüder,"},{"verse":12,"text":"die von der Erde abgesondert und zu mir aufgenommen worden sind – eine Stadt, aufgehoben, bis der Tag der Rechtschaffenheit kommt – ein Tag, nach dem alle heiligen Männer getrachtet haben, und sie haben ihn nicht erlangt infolge von Schlechtigkeit und Gräueln"},{"verse":13,"text":"und haben bekannt, dass sie Fremde und Pilger auf der Erde seien,"},{"verse":14,"text":"aber haben die Verheißung erhalten, dass sie ihn finden und ihn in ihrem Fleische sehen würden."},{"verse":15,"text":"Darum horcht auf, und ich werde euch die Gründe darlegen, und ich werde zu euch sprechen und prophezeien wie zu den Männern in alten Tagen."},{"verse":16,"text":"Und ich werde es klar zeigen, wie ich es meinen Jüngern gezeigt habe, als ich im Fleische vor ihnen stand und zu ihnen redete, nämlich: Da ihr mich gefragt habt in Bezug auf die Zeichen meines Kommens an dem Tag, da ich in meiner Herrlichkeit kommen werde in den Wolken des Himmels, um die Verheißungen zu erfüllen, die ich euren Vätern gemacht habe,"},{"verse":17,"text":"und da ihr die lange Abwesenheit eures Geistes von eurem Leib als Gefangenschaft anseht, so werde ich euch zeigen, wie der Tag der Erlösung kommen wird und auch die Wiederherstellung des zerstreuten Israel."},{"verse":18,"text":"Und nun seht ihr diesen Tempel, der in Jerusalem ist, den ihr das Haus Gottes nennt; und eure Feinde sagen, dieses Haus werde nie fallen."},{"verse":19,"text":"Aber wahrlich, ich sage euch: Verwüstung wird über diese Generation kommen wie ein Dieb in der Nacht, und dieses Volk wird zerschlagen und unter alle Nationen zerstreut werden."},{"verse":20,"text":"Und dieser Tempel, den ihr jetzt seht, wird niedergerissen werden, dass auch nicht ein Stein auf dem anderen bleibt."},{"verse":21,"text":"Und es wird sich begeben: Diese Generation von Juden wird nicht vergehen, bis eine jede Verwüstung, die ich euch in Bezug auf sie gesagt habe, geschehen wird."},{"verse":22,"text":"Ihr sprecht, ihr wüsstet, dass das Ende der Welt kommt; ihr sprecht auch, ihr wüsstet, dass die Himmel und die Erde vergehen werden;"},{"verse":23,"text":"und in diesem sprecht ihr recht, denn so ist es; aber all dies, was ich euch gesagt habe, wird nicht vergehen, bis alles erfüllt ist."},{"verse":24,"text":"Und dies habe ich euch in Bezug auf Jerusalem gesagt; und wenn jener Tag kommt, wird ein Überrest unter alle Nationen zerstreut werden;"},{"verse":25,"text":"aber sie werden wieder gesammelt werden; doch werden sie verbleiben, bis die Zeiten der Anderen sich erfüllt haben."},{"verse":26,"text":"Und an jenem Tag wird man von Kriegen und Kriegsgerüchten hören, und die ganze Erde wird in Aufruhr sein, und den Menschen wird das Herz aussetzen, und sie werden sagen, Christus verzögere sein Kommen bis zum Ende der Erde."},{"verse":27,"text":"Und die Liebe der Menschen wird erkalten, und das Übeltun wird überhandnehmen."},{"verse":28,"text":"Und wenn die Zeiten der Anderen herbeigekommen sind, wird ein Licht hervorbrechen unter denen, die in Finsternis sitzen, und das wird die Fülle meines Evangeliums sein;"},{"verse":29,"text":"aber sie empfangen es nicht; denn sie nehmen das Licht nicht wahr, und sie wenden ihr Herz von mir ab wegen der Weisungen von Menschen."},{"verse":30,"text":"Und in jener Generation werden sich die Zeiten der Anderen erfüllen."},{"verse":31,"text":"Und es werden Menschen in jener Generation dastehen, die nicht vergehen werden, bis sie eine überflutende Geißel sehen; denn eine verheerende Krankheit wird das Land bedecken."},{"verse":32,"text":"Aber meine Jünger werden an heiligen Stätten stehen und werden nicht wanken; aber unter den Schlechten werden Menschen ihre Stimme erheben und Gott fluchen und sterben."},{"verse":33,"text":"Und es wird auch Erdbeben geben an verschiedenen Orten und viele Verwüstungen; doch werden die Menschen ihr Herz gegen mich verhärten, und sie werden das Schwert ergreifen, einer gegen den anderen, und sie werden einander umbringen."},{"verse":34,"text":"Und nun, als ich, der Herr, diese Worte zu meinen Jüngern gesagt hatte, waren sie beunruhigt."},{"verse":35,"text":"Und ich sagte zu ihnen: Beunruhigt euch nicht; denn wenn dies alles geschehen wird, könnt ihr wissen, dass die Verheißungen, die euch gemacht worden sind, in Erfüllung gehen werden."},{"verse":36,"text":"Und wenn das Licht allmählich hervorbricht, wird es mit ihnen sein wie in dem Gleichnis, das ich euch darlegen werde:"},{"verse":37,"text":"Ihr schaut und seht die Feigenbäume, und ihr seht sie mit euren Augen, und ihr sagt, wenn sie anfangen zu treiben und ihre Blätter noch zart sind, der Sommer sei jetzt nahe;"},{"verse":38,"text":"so wird es auch an jenem Tag sein, da sie dies alles sehen, dann werden sie wissen, dass die Stunde nahe ist."},{"verse":39,"text":"Und es wird sich begeben: Wer mich fürchtet, wird Ausschau halten nach dem großen Tag des Herrn, der kommen soll, nämlich nach den Zeichen vom Kommen des Menschensohnes."},{"verse":40,"text":"Und sie werden Zeichen und Wunder sehen, denn diese werden oben in den Himmeln und unten auf der Erde gezeigt werden."},{"verse":41,"text":"Und sie werden Blut und Feuer und Rauchschwaden sehen."},{"verse":42,"text":"Und ehe der Tag des Herrn kommt, wird die Sonne sich verfinstern, und der Mond wird sich in Blut verwandeln, und die Sterne werden vom Himmel fallen."},{"verse":43,"text":"Und der Überrest wird an diesen Ort gesammelt werden;"},{"verse":44,"text":"und dann werden sie nach mir ausschauen, und siehe, ich werde kommen; und sie werden mich sehen in den Wolken des Himmels, angetan mit Macht und großer Herrlichkeit, mit allen heiligen Engeln; und wer mich nicht erwartet, wird ausgestoßen werden."},{"verse":45,"text":"Aber ehe der Arm des Herrn niederfällt, wird ein Engel seine Posaune ertönen lassen, und die Heiligen, die geschlafen haben, werden hervorkommen, um mir in der Wolke zu begegnen."},{"verse":46,"text":"Darum, wenn ihr in Frieden geschlafen habt, seid ihr gesegnet; denn wie ihr mich jetzt seht und wisst, dass ich bin, so werdet ihr auch zu mir kommen, und eure Seele wird leben, und eure Erlösung wird vollendet werden; und die Heiligen werden von den vier Enden der Erde hervorkommen."},{"verse":47,"text":"Dann wird der Arm des Herrn auf die Nationen niederfallen."},{"verse":48,"text":"Und dann wird der Herr seinen Fuß auf diesen Berg setzen, und dieser wird sich entzweispalten, und die Erde wird zittern und hin und her wanken, und auch die Himmel werden erbeben."},{"verse":49,"text":"Und der Herr wird seine Stimme erschallen lassen, und alle Enden der Erde werden sie vernehmen; und die Nationen der Erde werden wehklagen, und jene, die gelacht haben, werden ihre Torheit einsehen."},{"verse":50,"text":"Und Unheil wird den Spötter bedecken, und der Verächter wird verzehrt werden, und wer auf Übeltun gelauert hat, wird umgehauen und ins Feuer geworfen werden."},{"verse":51,"text":"Und dann werden die Juden mich anschauen und sprechen: Was sind das für Wunden an deinen Händen und an deinen Füßen?"},{"verse":52,"text":"Dann werden sie wissen, dass ich der Herr bin; denn ich werde zu ihnen sprechen: Diese Wunden sind die Wunden, mit denen ich im Haus meiner Freunde verwundet worden bin. Ich bin es, der emporgehoben wurde. Ich bin Jesus, der gekreuzigt wurde. Ich bin der Sohn Gottes."},{"verse":53,"text":"Und dann werden sie weinen wegen ihrer Übeltaten, dann werden sie wehklagen, weil sie ihren König verfolgt haben."},{"verse":54,"text":"Und dann werden die heidnischen Nationen erlöst werden, und diejenigen, die kein Gesetz gekannt haben, werden an der ersten Auferstehung Anteil haben; und es wird erträglich für sie sein."},{"verse":55,"text":"Und der Satan wird gebunden werden, sodass er keinen Platz im Herzen der Menschenkinder haben wird."},{"verse":56,"text":"Und an jenem Tag, da ich in meiner Herrlichkeit kommen werde, wird das Gleichnis, das ich von den zehn Jungfrauen erzählt habe, in Erfüllung gehen."},{"verse":57,"text":"Denn diejenigen, die weise sind und die Wahrheit empfangen haben und sich den Heiligen Geist als ihren Führer genommen haben und sich nicht haben täuschen lassen – wahrlich, ich sage euch: Sie werden nicht umgehauen und ins Feuer geworfen werden, sondern werden den Tag aushalten."},{"verse":58,"text":"Und die Erde wird ihnen als Erbteil übergeben werden; und sie werden sich mehren und stark werden, und ihre Kinder werden ohne Sünde zur Errettung aufwachsen."},{"verse":59,"text":"Denn der Herr wird mitten unter ihnen sein, und seine Herrlichkeit wird auf ihnen sein, und er wird ihr König und ihr Gesetzgeber sein."},{"verse":60,"text":"Und nun siehe, ich sage dir: Es ist euch nicht gewährt, noch Weiteres über dieses Kapitel zu wissen, bis das Neue Testament übersetzt ist; und darin wird dies alles kundgetan werden;"},{"verse":61,"text":"darum gewähre ich dir, es jetzt zu übersetzen, damit ihr euch für das Kommende bereitmachen könnt."},{"verse":62,"text":"Denn wahrlich, ich sage euch: Großes erwartet euch;"},{"verse":63,"text":"ihr hört von Kriegen in fremden Ländern; aber siehe, ich sage euch: Sie sind nahe, ja, vor eurer Tür, und in nicht vielen Jahren von nun an werdet ihr von Kriegen in euren eigenen Ländern hören."},{"verse":64,"text":"Darum habe ich, der Herr, gesagt: Sammelt euch aus den östlichen Ländern, versammelt euch, ihr Ältesten meiner Kirche; geht hin in die westlichen Länder, ruft die Bewohner zur Umkehr, und insoweit sie umkehren, richtet mir Gemeinden auf."},{"verse":65,"text":"Und eines Herzens und eines Sinnes sollt ihr eure Reichtümer zusammentragen, um ein Erbteil kaufen zu können, das euch später noch bestimmt werden wird."},{"verse":66,"text":"Und es wird das Neue Jerusalem genannt werden, ein Land des Friedens, eine Stadt der Zuflucht, ein Ort der Sicherheit für die Heiligen des allerhöchsten Gottes;"},{"verse":67,"text":"und die Herrlichkeit des Herrn wird dort sein, und der Schrecken des Herrn wird auch dort sein, so sehr, dass die Schlechten nicht hinkommen werden; und man wird es Zion nennen."},{"verse":68,"text":"Und unter den Schlechten wird es sich begeben: Ein jeder, der nicht gegen seinen Nächsten zum Schwert greifen will, muss um der Sicherheit willen notwendigerweise nach Zion fliehen."},{"verse":69,"text":"Und dorthin werden gesammelt aus jeder Nation unter dem Himmel; und es wird dies das einzige Volk sein, das sich nicht miteinander im Krieg befindet."},{"verse":70,"text":"Und unter den Schlechten wird man sprechen: Lasst uns nicht zum Kampf gegen Zion hinaufziehen, denn die Einwohner Zions sind schrecklich, darum können wir nicht bestehen."},{"verse":71,"text":"Und es wird sich begeben: Die Rechtschaffenen werden aus allen Nationen gesammelt werden und werden nach Zion kommen – singen werden sie Gesänge immerwährender Freude."},{"verse":72,"text":"Und nun sage ich euch: Lasst dies alles nicht in die Welt hinausgehen, bis es mir ratsam ist, damit ihr dieses Werk vor den Augen des Volkes und vor den Augen eurer Feinde vollbringen könnt, damit sie nichts von euren Werken erfahren, bis ihr das, was ich euch geboten habe, vollbracht habt,"},{"verse":73,"text":"damit, wenn sie es erfahren, sie über dies alles nachdenken."},{"verse":74,"text":"Denn wenn der Herr erscheint, wird er für sie schrecklich sein, dass Furcht sie ergreife, und sie werden ferne stehen und zittern."},{"verse":75,"text":"Und alle Nationen werden sich ängstigen wegen des Schreckens des Herrn und der Gewalt seiner Macht. So ist es. Amen."}]},{"chapter":46,"verses":[{"verse":1,"text":"Horcht auf, o ihr Volk meiner Kirche; denn wahrlich, ich sage euch: Dies alles ist euch zu eurem Nutzen und zu eurer Belehrung gesagt worden."},{"verse":2,"text":"Aber ungeachtet all dessen, was geschrieben steht, ist es den Ältesten meiner Kirche von Anfang an immer gegeben gewesen, und wird immer so sein, dass sie alle Versammlungen so leiten, wie sie vom Heiligen Geist angewiesen und geführt werden."},{"verse":3,"text":"Doch ist es euch geboten, niemals jemanden aus euren öffentlichen Versammlungen, die vor der Welt gehalten werden, auszustoßen."},{"verse":4,"text":"Auch ist es euch geboten, keinen, der der Kirche angehört, aus euren Abendmahlsversammlungen auszustoßen; wenn aber jemand übertreten hat, so lasst ihn nicht davon nehmen, bis er Sühne leistet."},{"verse":5,"text":"Und weiter, ich sage euch: Ihr sollt keinen aus euren Abendmahlsversammlungen ausstoßen, der ernstlich nach dem Gottesreich trachtet – ich sage dies in Bezug auf diejenigen, die nicht von der Kirche sind."},{"verse":6,"text":"Und weiter sage ich euch in Bezug auf eure Konfirmierungsversammlungen, wenn es da welche gibt, die nicht von der Kirche sind, die ernstlich nach dem Gottesreich trachten, sollt ihr sie nicht ausstoßen."},{"verse":7,"text":"Aber euch ist es geboten, in allem Gott zu bitten, der gern gibt; und das, was der Geist euch bezeugt, von dem möchte ich, dass ihr es tut, mit aller Herzensheiligkeit, untadelig vor mir wandelnd, das Ziel eurer Errettung bedenkend, indem ihr alles mit Gebet und Danksagung tut, damit ihr nicht durch böse Geister oder Lehren von Teufeln oder die Gebote von Menschen verführt werdet, denn einige sind von Menschen und andere von Teufeln."},{"verse":8,"text":"Darum hütet euch, dass ihr euch nicht täuschen lasst; und damit ihr nicht getäuscht werdet, sollt ihr ernstlich nach den besten Gaben trachten und immer bedenken, wozu sie gegeben sind;"},{"verse":9,"text":"denn wahrlich, ich sage euch: Sie sind zum Nutzen derer gegeben, die mich lieben und alle meine Gebote halten, und dessen, der dies zu tun trachtet; damit allen genutzt sei, die suchen oder die mich bitten – die bitten, und nicht um ein Zeichen, damit sie es dann in ihren Begierden verzehren."},{"verse":10,"text":"Und weiter, wahrlich, ich sage euch: Ich möchte, dass ihr immer daran denkt und immer in eurem Sinn behaltet, was jene Gaben sind, die der Kirche gegeben sind."},{"verse":11,"text":"Denn allen ist nicht jede Gabe gegeben; denn es gibt viele Gaben, und jedem Menschen ist durch den Geist Gottes eine Gabe gegeben."},{"verse":12,"text":"Einigen ist die eine gegeben, und einigen ist eine andere gegeben, damit allen dadurch genutzt sei."},{"verse":13,"text":"Einigen ist es durch den Heiligen Geist gegeben zu wissen, dass Jesus Christus der Sohn Gottes ist und dass er für die Sünden der Welt gekreuzigt worden ist."},{"verse":14,"text":"Anderen ist es gegeben, dass sie ihren Worten glauben, damit auch sie ewiges Leben haben können, wenn sie weiterhin treu bleiben."},{"verse":15,"text":"Und weiter, einigen ist es durch den Heiligen Geist gegeben, die Verschiedenheiten der Dienste zu erkennen, wie es dem einen Herrn wohlgefällig ist, so wie der Herr es will, der seine große Barmherzigkeit den Umständen der Menschenkinder anpasst."},{"verse":16,"text":"Und weiter, es ist einigen durch den Heiligen Geist gegeben, die Verschiedenheiten der Handlungen zu erkennen, ob sie von Gott sind, damit die Kundgebungen des Geistes einem jeden Menschen gegeben werden können, um ihm damit zu nutzen."},{"verse":17,"text":"Und weiter, wahrlich, ich sage euch: Einigen ist durch den Geist Gottes das Wort der Weisheit gegeben."},{"verse":18,"text":"Einem anderen ist das Wort der Erkenntnis gegeben, damit alle belehrt werden können, dass sie weise seien und Erkenntnis haben."},{"verse":19,"text":"Und weiter, einigen ist es gegeben, dass sie den Glauben haben, geheilt zu werden;"},{"verse":20,"text":"und anderen ist es gegeben, dass sie den Glauben haben zu heilen."},{"verse":21,"text":"Und weiter, einigen ist es gegeben, Wundertaten zu verrichten;"},{"verse":22,"text":"und anderen ist es gegeben, dass sie prophezeien;"},{"verse":23,"text":"und anderen die Unterscheidung von Geistern."},{"verse":24,"text":"Und weiter, es ist einigen gegeben, dass sie in Zungen reden;"},{"verse":25,"text":"und einem anderen ist es gegeben, die Zungenrede auszulegen."},{"verse":26,"text":"Und alle diese Gaben kommen von Gott, zum Nutzen der Kinder Gottes."},{"verse":27,"text":"Und dem Bischof der Kirche und denen, die Gott bestimmt und ordiniert, dass sie über die Kirche wachen und dass sie Älteste für die Kirche seien, denen wird es gegeben sein, alle diese Gaben zu unterscheiden, damit nicht jemand unter euch etwas vorgebe und doch nicht von Gott sei."},{"verse":28,"text":"Und es wird sich begeben: Wer im Geiste bittet, wird im Geiste empfangen,"},{"verse":29,"text":"damit es einigen gegeben sei, alle jene Gaben zu haben, damit es ein Haupt gebe, damit einem jeden Mitglied dadurch genutzt sei."},{"verse":30,"text":"Wer im Geiste bittet, der bittet gemäß dem Willen Gottes; darum geschieht es so, wie er bittet."},{"verse":31,"text":"Und weiter, ich sage euch: Alles muss im Namen Christi getan werden, was auch immer ihr im Geiste tut;"},{"verse":32,"text":"und ihr müsst im Geiste Gott danken für jeglichen Segen, mit dem ihr gesegnet seid."},{"verse":33,"text":"Und ihr müsst beständig Tugend und Heiligkeit vor mir üben. So ist es. Amen."}]},{"chapter":47,"verses":[{"verse":1,"text":"Siehe, es ist mir ratsam, dass mein Diener John eine ordnungsgemäße Geschichte schreibe und führe und dir, mein Diener Joseph, behilflich sei, alles niederzuschreiben, was dir gegeben wird, bis er zu weiteren Aufgaben berufen wird."},{"verse":2,"text":"Weiter, wahrlich, ich sage dir: Er kann auch in Versammlungen seine Stimme erheben, wann immer es ratsam ist."},{"verse":3,"text":"Und weiter, ich sage dir: Es soll ihm bestimmt werden, die Aufzeichnungen und die Geschichte der Kirche fortlaufend zu führen; denn Oliver Cowdery habe ich zu einem anderen Amt bestimmt."},{"verse":4,"text":"Darum soll es ihm, insoweit er glaubenstreu ist, durch den Tröster gegeben werden, dies alles niederzuschreiben. So ist es. Amen."}]},{"chapter":48,"verses":[{"verse":1,"text":"Es ist notwendig, dass ihr zur gegenwärtigen Zeit an eurem Wohnort bleibt, wie es euren Umständen angemessen ist."},{"verse":2,"text":"Und soweit ihr Land habt, sollt ihr es mit den östlichen Brüdern teilen;"},{"verse":3,"text":"und soweit ihr kein Land habt, sollen sie zur gegenwärtigen Zeit in jenen Gebieten ringsum ankaufen, wie es ihnen gut scheint, denn es ist notwendigerweise erforderlich, dass sie einen Ort haben, wo sie zur gegenwärtigen Zeit wohnen können."},{"verse":4,"text":"Es ist notwendigerweise erforderlich, dass ihr alles Geld spart, was ihr könnt, und dass ihr alles, was ihr könnt, in Rechtschaffenheit erlangt, damit ihr mit der Zeit imstande seid, Land für ein Erbteil zu kaufen, nämlich die Stadt."},{"verse":5,"text":"Der Ort wird jetzt noch nicht offenbart; doch nach der Ankunft eurer Brüder aus dem Osten sollen einige Männer bestimmt werden, und ihnen wird es gegeben sein, den Ort zu wissen, ja, ihnen wird er offenbart werden."},{"verse":6,"text":"Und sie sollen bestimmt werden, die Ländereien zu kaufen und damit zu beginnen, die Grundlage für die Stadt zu legen; und dann sollt ihr anfangen, euch mit euren Familien zu sammeln, ein jeder gemäß seiner Familie, gemäß seinen Umständen und wie es ihm von der Präsidentschaft und dem Bischof der Kirche bestimmt wird, gemäß den Gesetzen und Geboten, die ihr empfangen habt und die ihr später noch empfangen werdet. So ist es. Amen."}]},{"chapter":49,"verses":[{"verse":1,"text":"Hört auf mein Wort, meine Diener Sidney und Parley und Leman; denn siehe, wahrlich, ich sage euch: Ich gebe euch das Gebot, hinzugehen und mein Evangelium, das ihr empfangen habt, so, wie ihr es empfangen habt, den Shakern zu predigen."},{"verse":2,"text":"Siehe, ich sage euch: Sie haben den Wunsch, teilweise die Wahrheit zu wissen, aber nicht gänzlich, denn sie sind nicht recht vor mir und müssen notwendigerweise umkehren."},{"verse":3,"text":"Darum sende ich euch, meine Diener Sidney und Parley, dass ihr ihnen das Evangelium predigt."},{"verse":4,"text":"Und mein Diener Leman soll zu dieser Arbeit ordiniert werden, damit er ihnen die Gründe darlegen kann, nicht gemäß dem, was er von ihnen empfangen hat, sondern gemäß dem, was er von euch, meinen Dienern, gelehrt wird; und wenn er das tut, werde ich ihn segnen, sonst aber wird er nicht gedeihen."},{"verse":5,"text":"So spricht der Herr; denn ich bin Gott und habe meinen einziggezeugten Sohn in die Welt gesandt, dass er die Welt erlöse, und habe angeordnet, dass, wer ihn empfängt, errettet werden wird, wer ihn aber nicht empfängt, verdammt werden wird –"},{"verse":6,"text":"und sie haben mit des Menschen Sohn das getan, was sie wollten; und er hat seine Macht zur rechten Hand seiner Herrlichkeit eingenommen und regiert nun in den Himmeln und wird regieren, bis er auf die Erde herabkommt, um sich alle Feinde unter seine Füße zu tun, und diese Zeit steht nahe bevor."},{"verse":7,"text":"Ich, Gott, der Herr, habe es gesagt; aber die Stunde und den Tag weiß kein Mensch, auch nicht die Engel im Himmel, und sie werden es auch nicht wissen, bis er kommt."},{"verse":8,"text":"Darum will ich, dass alle Menschen umkehren, denn alle sind unter der Sünde außer denen, die ich mir bewahrt habe, heilige Männer, von denen ihr nicht wisst."},{"verse":9,"text":"Darum sage ich euch: Ich habe euch meinen immerwährenden Bund gesandt, nämlich jenen, der von Anfang an war."},{"verse":10,"text":"Und das, was ich verheißen habe, habe ich auch so erfüllt, und die Nationen der Erde werden sich davor beugen; und wenn nicht von sich aus, werden sie erniedrigt werden, denn das, was jetzt von sich aus erhöht ist, wird mit Macht erniedrigt werden."},{"verse":11,"text":"Darum gebe ich euch das Gebot, unter diese Leute zu gehen und zu ihnen zu sprechen, wie bei meinem Apostel vor alters, dessen Name Petrus war:"},{"verse":12,"text":"Glaubt an den Namen des Herrn Jesus, der auf Erden gewesen ist und kommen wird, der Anfang und das Ende;"},{"verse":13,"text":"kehrt um, und lasst euch taufen im Namen Jesu Christi, gemäß dem heiligen Gebot, zur Sündenvergebung;"},{"verse":14,"text":"und wer dies tut, wird die Gabe des Heiligen Geistes durch das Händeauflegen der Ältesten der Kirche empfangen."},{"verse":15,"text":"Und weiter, wahrlich, ich sage euch: Wer verbietet zu heiraten, ist nicht von Gott verordnet, denn die Ehe ist dem Menschen von Gott verordnet."},{"verse":16,"text":"Darum ist es rechtens, dass er eine Frau habe, und die beiden werden ein Fleisch sein, und dies alles, damit die Erde den Zweck ihrer Erschaffung erfülle"},{"verse":17,"text":"und damit sie sich mit dem Maß an Menschen fülle, gemäß seiner Erschaffung, ehe die Welt gemacht wurde."},{"verse":18,"text":"Und wer verbietet, Fleisch zu meiden, dass der Mensch dasselbe nicht essen soll, ist nicht von Gott verordnet;"},{"verse":19,"text":"denn siehe, die Tiere des Feldes und die Vögel der Luft und das, was von der Erde kommt, ist dem Menschen zum Gebrauch verordnet, zur Nahrung und zur Kleidung und dass er reichlich habe."},{"verse":20,"text":"Aber es ist nicht gegeben, dass der eine Mensch über den anderen hinaus Besitz haben soll, darum liegt die Welt in Sünde."},{"verse":21,"text":"Und weh sei dem Menschen, der Blut vergießt oder der Fleisch verschwendet und es nicht nötig hat."},{"verse":22,"text":"Und weiter, wahrlich, ich sage euch: Des Menschen Sohn kommt nicht in Gestalt einer Frau, auch nicht in der eines Mannes, der auf Erden wandert."},{"verse":23,"text":"Darum lasst euch nicht täuschen, sondern bleibt standhaft; schaut danach aus, dass die Himmel erbeben werden und die Erde zittern und hin und her wanken wird wie ein Betrunkener und dass die Täler erhöht werden und dass die Berge erniedrigt werden und dass die zerklüfteten Orte sich ebnen werden – und all dies, wenn der Engel seine Posaune ertönen lassen wird."},{"verse":24,"text":"Aber ehe der große Tag des Herrn kommt, wird Jakob in der Wildnis erblühen, und die Lamaniten werden blühen wie die Rose."},{"verse":25,"text":"Zion wird auf den Hügeln erblühen und sich auf den Bergen freuen und wird sich an dem Ort sammeln, den ich bestimmt habe."},{"verse":26,"text":"Siehe, ich sage euch: Geht hin, wie ich euch geboten habe; kehrt von all euren Sünden um; bittet, und ihr werdet empfangen; klopfet an, und es wird euch aufgetan werden."},{"verse":27,"text":"Siehe, ich werde vor euch hergehen und werde eure Nachhut sein; und ich werde mitten unter euch sein, und ihr werdet nicht zuschanden werden."},{"verse":28,"text":"Siehe, ich bin Jesus Christus, und ich komme schnell. So ist es. Amen."}]},{"chapter":50,"verses":[{"verse":1,"text":"Horcht auf, o ihr Ältesten meiner Kirche, und schenkt der Stimme des lebendigen Gottes Gehör, und gebt auf die Worte der Weisheit acht, die euch gegeben werden gemäß dem, was ihr erbeten habt und worin ihr euch einig seid, dass es die Kirche betrifft und die Geister, die auf Erden umgehen."},{"verse":2,"text":"Siehe, wahrlich, ich sage euch: Es gibt viele Geister, die falsche Geister sind, die auf der Erde umhergehen und die Welt täuschen."},{"verse":3,"text":"Und auch der Satan hat danach getrachtet, euch zu täuschen, damit er euch zu Fall bringe."},{"verse":4,"text":"Siehe, ich, der Herr, habe auf euch geschaut und habe Gräuel in der Kirche gesehen, die sich zu meinem Namen bekennt."},{"verse":5,"text":"Aber gesegnet sind diejenigen, die glaubenstreu sind und ausharren, sei es im Leben oder im Tod, denn sie werden ewiges Leben ererben."},{"verse":6,"text":"Aber weh denen, die täuschen und heucheln; denn, so spricht der Herr, ich werde sie vor Gericht bringen."},{"verse":7,"text":"Siehe, wahrlich, ich sage euch: Es gibt Heuchler unter euch, die einige getäuscht haben, was dem Widersacher Macht gegeben hat; aber siehe, solche werden wiedergewonnen werden;"},{"verse":8,"text":"aber die Heuchler werden entlarvt und werden ausgeschlossen werden, entweder im Leben oder im Tod, ja, wie ich es will; und weh denen, die aus meiner Kirche ausgeschlossen werden, denn dieselben sind von der Welt überwunden."},{"verse":9,"text":"Darum soll sich ein jeder hüten, dass er nicht das tue, was nicht in Wahrheit und Rechtschaffenheit vor mir ist."},{"verse":10,"text":"Und nun kommt, spricht der Herr durch den Geist zu den Ältesten seiner Kirche, und lasst uns einander die Gründe darlegen, damit ihr versteht;"},{"verse":11,"text":"lasst uns die Gründe darlegen, wie ein Mensch dem anderen von Angesicht zu Angesicht seine Gründe darlegt."},{"verse":12,"text":"Nun, wenn ein Mensch seine Gründe darlegt, so wird er von den Menschen verstanden, denn er legt seine Gründe dar wie ein Mensch; und so werde auch ich, der Herr, euch meine Gründe darlegen, damit ihr versteht."},{"verse":13,"text":"Darum stelle ich, der Herr, euch diese Frage: Wozu seid ihr ordiniert worden?"},{"verse":14,"text":"Dass ihr mein Evangelium durch den Geist predigt, nämlich den Tröster, der ausgesandt wurde, um die Wahrheit zu lehren."},{"verse":15,"text":"Und dann habt ihr Geister empfangen, die ihr nicht verstehen konntet, und habt sie als von Gott kommend empfangen; und darin seid ihr gerechtfertigt?"},{"verse":16,"text":"Siehe, ihr sollt euch diese Frage selbst beantworten; doch werde ich barmherzig zu euch sein; wer unter euch schwach ist, wird hernach stark gemacht werden."},{"verse":17,"text":"Wahrlich, ich sage euch: Wer von mir ordiniert und ausgesandt ist, das Wort der Wahrheit durch den Tröster zu predigen, im Geist der Wahrheit, predigt er es durch den Geist der Wahrheit oder auf eine andere Weise?"},{"verse":18,"text":"Und wenn es auf eine andere Weise geschieht, ist es nicht von Gott."},{"verse":19,"text":"Und weiter: Wer das Wort der Wahrheit empfängt, empfängt er es durch den Geist der Wahrheit oder auf eine andere Weise?"},{"verse":20,"text":"Wenn es auf eine andere Weise geschieht, ist es nicht von Gott."},{"verse":21,"text":"Wie kommt es also, dass ihr nicht verstehen und erkennen könnt, dass der, der das Wort durch den Geist der Wahrheit empfängt, es so empfängt, wie es durch den Geist der Wahrheit gepredigt wird?"},{"verse":22,"text":"Darum verstehen der, der predigt, und der, der empfängt, einander, und beide werden erbaut und freuen sich miteinander."},{"verse":23,"text":"Und was nicht erbaut, das ist nicht von Gott, sondern ist Finsternis."},{"verse":24,"text":"Was von Gott ist, das ist Licht; und wer Licht empfängt und in Gott verbleibt, empfängt mehr Licht; und jenes Licht wird heller und heller bis zum vollkommenen Tag."},{"verse":25,"text":"Und weiter, wahrlich, ich sage euch, und ich sage es, damit ihr die Wahrheit erkennt, damit ihr Finsternis aus eurer Mitte vertreiben könnt:"},{"verse":26,"text":"Wer von Gott ordiniert und ausgesandt ist, der ist auch bestimmt, der Größte zu sein, auch wenn er der Geringste ist und aller Diener."},{"verse":27,"text":"Darum besitzt er alles, denn alles ist ihm untertan, sowohl im Himmel als auch auf Erden, das Leben und das Licht, der Geist und die Macht, ausgesandt vom Willen des Vaters durch Jesus Christus, seinen Sohn."},{"verse":28,"text":"Aber niemand besitzt alles, außer er sei rein gemacht und von aller Sünde gesäubert."},{"verse":29,"text":"Und wenn ihr rein gemacht und von aller Sünde gesäubert seid, mögt ihr im Namen Jesu erbitten, was auch immer ihr wollt, und es wird geschehen."},{"verse":30,"text":"Aber wisset dies, es wird euch gegeben werden, was ihr erbitten werdet; und da ihr als Haupt bestimmt seid, werden euch die Geister untertan sein."},{"verse":31,"text":"Darum wird es sich begeben: Wenn ihr einen Geist sich kundtun seht, den ihr nicht verstehen könnt, und ihr jenen Geist nicht empfangt, so sollt ihr den Vater im Namen Jesu bitten; und wenn er euch jenen Geist nicht gibt, so könnt ihr wissen, dass er nicht von Gott ist."},{"verse":32,"text":"Und es wird euch Macht über jenen Geist gegeben werden; und ihr sollt gegen jenen Geist mit lauter Stimme verkündigen, dass er nicht von Gott ist –"},{"verse":33,"text":"nicht mit schmähender Anklage, damit ihr nicht überwunden werdet, auch nicht mit Prahlen oder Frohlocken, damit ihr nicht davon ergriffen werdet."},{"verse":34,"text":"Wer von Gott empfängt, soll es als von Gott achten; und er soll sich freuen, dass er von Gott für würdig erachtet wird zu empfangen."},{"verse":35,"text":"Und indem ihr achtgebt und das tut, was ihr empfangen habt und was ihr später noch empfangen werdet – und das Reich ist euch vom Vater gegeben und die Macht, alles zu überwinden, was nicht von ihm verordnet ist –"},{"verse":36,"text":"und siehe, wahrlich, ich sage euch: Gesegnet seid ihr, die ihr jetzt diese meine Worte aus dem Mund meines Dieners vernehmt, denn eure Sünden sind euch vergeben."},{"verse":37,"text":"Lasst meinen Diener Joseph Wakefield, an dem ich Wohlgefallen habe, und meinen Diener Parley P. Pratt unter die Gemeinden ausgehen und sie mit dem Wort der Ermahnung stärken;"},{"verse":38,"text":"ebenso meinen Diener John Corrill, oder alle meine Diener, die zu diesem Amt ordiniert werden, und lasst sie im Weingarten arbeiten; und lasst niemanden sie hindern, das zu tun, was ich ihnen bestimmt habe –"},{"verse":39,"text":"darum ist in dieser Sache mein Diener Edward Partridge nicht gerechtfertigt; doch soll er umkehren, dann wird ihm vergeben werden."},{"verse":40,"text":"Siehe, ihr seid kleine Kinder, und ihr könnt jetzt noch nicht alles ertragen; ihr müsst in der Gnade und in der Erkenntnis der Wahrheit wachsen."},{"verse":41,"text":"Fürchtet euch nicht, kleine Kinder, denn ihr seid mein, und ich habe die Welt überwunden, und ihr seid von denen, die mein Vater mir gegeben hat;"},{"verse":42,"text":"und keiner von denen, die mein Vater mir gegeben hat, wird verlorengehen."},{"verse":43,"text":"Und der Vater und ich sind eins. Ich bin im Vater und der Vater in mir; und insoweit ihr mich empfangen habt, seid ihr in mir und ich in euch."},{"verse":44,"text":"Darum bin ich mitten unter euch, und ich bin der gute Hirte und der Stein Israels. Wer auf diesem Felsen baut, wird nie fallen."},{"verse":45,"text":"Und der Tag kommt, da ihr meine Stimme vernehmen und mich sehen und wissen werdet, dass ich bin."},{"verse":46,"text":"Seid darum wachsam, damit ihr bereit seiet. So ist es. Amen."}]},{"chapter":51,"verses":[{"verse":1,"text":"Hört auf mich, spricht der Herr, euer Gott, dann werde ich zu meinem Diener Edward Partridge sprechen und ihm Weisungen geben; denn es muss notwendigerweise sein, dass er Weisungen empfange, wie dieses Volk zu organisieren ist."},{"verse":2,"text":"Denn es muss notwendigerweise sein, dass es gemäß meinen Gesetzen organisiert werde, denn andernfalls wird es ausgestoßen werden."},{"verse":3,"text":"Darum sollen mein Diener Edward Partridge und diejenigen, die er erwählt hat, an denen ich Wohlgefallen habe, diesem Volk seine Anteile bestimmen, einem jeden gleich, gemäß seiner Familie, gemäß seinen Umständen und seinen Bedürfnissen und seinem Bedarf."},{"verse":4,"text":"Und mein Diener Edward Partridge soll, wenn er jemandem seinen Anteil bestimmt, ihm ein Schriftstück geben, das ihm seinen Anteil sichert, dass er diesen behalte, nämlich dieses Recht und dieses Erbteil in der Kirche, bis er übertritt und von der Stimme der Gemeinde gemäß den Gesetzen und Bündnissen der Kirche nicht für würdig erachtet wird, der Kirche anzugehören."},{"verse":5,"text":"Und wenn er übertritt und nicht für würdig erachtet wird, der Kirche anzugehören, soll er nicht die Macht haben, den Anteil zu beanspruchen, den er dem Bischof für die Armen und Bedürftigen meiner Kirche geweiht hat; darum soll er das, was er gegeben hat, nicht behalten, sondern soll nur auf den Anteil Anspruch haben, der ihm vertraglich übertragen worden ist."},{"verse":6,"text":"Und so soll alles gemäß den Gesetzen des Landes sichergestellt werden."},{"verse":7,"text":"Und das, was diesem Volk gehört, soll für dieses Volk bestimmt werden."},{"verse":8,"text":"Und das Geld, das für dieses Volk übriggeblieben ist – ein Beauftragter soll für dieses Volk bestimmt werden, der das Geld nimmt, um für Nahrung und Kleidung zu sorgen, gemäß den Bedürfnissen dieses Volkes."},{"verse":9,"text":"Und jedermann soll ehrlich handeln und in diesem Volk gleich sein und gleich empfangen, damit ihr eins seiet, so wie ich es euch geboten habe."},{"verse":10,"text":"Und das, was diesem Volk gehört, soll nicht genommen und denen von einer anderen Gemeinde gegeben werden."},{"verse":11,"text":"Darum, wenn eine andere Gemeinde Geld von dieser Gemeinde empfangen möchte, soll sie es dieser Gemeinde wieder zurückzahlen, gemäß ihrer Vereinbarung;"},{"verse":12,"text":"und dies soll durch den Bischof geschehen oder den Beauftragten, der von der Stimme der Gemeinde bestimmt werden soll."},{"verse":13,"text":"Und weiter: Der Bischof soll für diese Gemeinde ein Vorratshaus bestimmen; und alles, sei es Geld oder Nahrung, was mehr ist, als vom Volk für seine Erfordernisse benötigt wird, soll in den Händen des Bischofs verwahrt werden."},{"verse":14,"text":"Und er soll auch für sich selbst, für seine eigenen Bedürfnisse und für die Bedürfnisse seiner Familie, zurückbehalten, da er sich der Erledigung dieser Geschäfte widmet."},{"verse":15,"text":"Und so gewähre ich diesem Volk das Recht, sich gemäß meinen Gesetzen zu organisieren."},{"verse":16,"text":"Und ich weihe ihm dieses Land für eine kurze Zeit, bis ich, der Herr, andere Vorsorge für es treffe und ihm gebieten werde, von hier fortzugehen;"},{"verse":17,"text":"und die Stunde und der Tag sind ihm nicht gegeben, darum soll es auf diesem Land arbeiten, als sei es für Jahre, und dies wird sich ihm zu seinem Nutzen wenden."},{"verse":18,"text":"Siehe, dies soll meinem Diener Edward Partridge an anderen Orten, in allen Gemeinden, ein Beispiel sein."},{"verse":19,"text":"Und wer als treuer, als gerechter und als weiser Treuhänder befunden wird, der wird in die Freude seines Herrn eingehen und wird ewiges Leben ererben."},{"verse":20,"text":"Wahrlich, ich sage euch: Ich bin Jesus Christus, der schnell kommt, zu einer Stunde, da ihr es nicht denkt. So ist es. Amen."}]},{"chapter":52,"verses":[{"verse":1,"text":"Siehe, so spricht der Herr zu den Ältesten, die er in diesen letzten Tagen berufen und erwählt hat, durch die Stimme seines Geistes –"},{"verse":2,"text":"nämlich: Ich, der Herr, werde euch kundtun, was ihr nach meinem Willen von jetzt an bis zur nächsten Konferenz tun sollt, die in Missouri stattfinden soll, in dem Land, das ich meinem Volk, das ein Überrest von Jakob ist, und denjenigen, die Erben gemäß dem Bunde sind, weihen werde."},{"verse":3,"text":"Darum, wahrlich, ich sage euch: Lasst meine Diener Joseph Smith Jr. und Sidney Rigdon ihre Reise antreten, sobald die Vorbereitungen für ihre Abreise von daheim getroffen werden können, und in das Land Missouri reisen."},{"verse":4,"text":"Und insoweit sie mir treu sind, wird ihnen kundgetan werden, was sie tun sollen,"},{"verse":5,"text":"und es wird ihnen, insoweit sie treu sind, auch das Land eures Erbteils kundgetan werden."},{"verse":6,"text":"Und insoweit sie nicht treu sind, werden sie ausgestoßen werden, ja, wie ich es will, wie es mir gut scheint."},{"verse":7,"text":"Und weiter, wahrlich, ich sage euch: Lasst meinen Diener Lyman Wight und meinen Diener John Corrill schnell ihre Reise antreten,"},{"verse":8,"text":"und auch mein Diener John Murdock und mein Diener Hyrum Smith sollen nach dem gleichen Ort ihre Reise antreten, auf dem Weg über Detroit."},{"verse":9,"text":"Und von dort sollen sie weiterreisen und unterwegs das Wort predigen und nichts anderes sagen als das, was die Propheten und Apostel geschrieben haben, und das, was sie vom Tröster durch das Gebet des Glaubens gelehrt werden."},{"verse":10,"text":"Lasst sie zu zweit gehen, und so sollen sie unterwegs in jeder Zusammenkunft predigen und taufen im Wasser und durch Händeauflegen am Rande des Wassers."},{"verse":11,"text":"Denn so spricht der Herr: Ich werde mein Werk in Rechtschaffenheit abkürzen, denn die Tage kommen, da ich Rechtsprechung zum Sieg führen werde."},{"verse":12,"text":"Und mein Diener Lyman Wight soll sich hüten, denn der Satan möchte ihn aussondern wie Spreu."},{"verse":13,"text":"Und siehe, wer treu ist, wird zum Herrscher über vieles gemacht werden."},{"verse":14,"text":"Und weiter: Ich werde euch in allem ein Muster geben, damit ihr nicht getäuscht werdet, denn der Satan geht im Land umher, und er geht aus, die Nationen zu täuschen –"},{"verse":15,"text":"darum: Wer da betet, wessen Geist zerknirscht ist, der wird von mir angenommen, wenn er meine Verordnungen beachtet."},{"verse":16,"text":"Wer da redet, wessen Geist zerknirscht ist, wessen Sprache sanft ist und erbaut, der ist von Gott, wenn er meine Verordnungen beachtet."},{"verse":17,"text":"Und weiter: Wer unter meiner Macht erzittert, wird stark gemacht werden und wird Früchte des Lobes und der Weisheit hervorbringen, gemäß den Offenbarungen und Wahrheiten, die ich euch gegeben habe."},{"verse":18,"text":"Und weiter: Wer überwunden wird und keine Früchte hervorbringt, nämlich gemäß diesem Muster, ist nicht von mir."},{"verse":19,"text":"Darum sollt ihr nach diesem Muster in allen Fällen unter den ganzen Himmeln die Geister erkennen."},{"verse":20,"text":"Und die Tage sind gekommen; gemäß dem Glauben der Menschen wird ihnen geschehen."},{"verse":21,"text":"Siehe, dieses Gebot ist allen Ältesten gegeben, die ich erwählt habe."},{"verse":22,"text":"Und weiter, wahrlich, ich sage euch: Lasst auch meinen Diener Thomas B. Marsh und meinen Diener Ezra Thayre ihre Reise antreten und unterwegs nach ebendemselben Land das Wort predigen."},{"verse":23,"text":"Und weiter, lasst meinen Diener Isaac Morley und meinen Diener Ezra Booth ihre Reise antreten und ebenfalls unterwegs nach ebendemselben Land das Wort predigen."},{"verse":24,"text":"Und weiter, lasst meine Diener Edward Partridge und Martin Harris mit meinen Dienern Sidney Rigdon und Joseph Smith Jr. ihre Reise antreten."},{"verse":25,"text":"Lasst auch meine Diener David Whitmer und Harvey Whitlock ihre Reise antreten und unterwegs nach ebendemselben Land predigen."},{"verse":26,"text":"Und lasst meine Diener Parley P. Pratt und Orson Pratt ihre Reise antreten und unterwegs nach ebendemselben Land predigen."},{"verse":27,"text":"Und lasst auch meine Diener Solomon Hancock und Simeon Carter ihre Reise nach ebendemselben Land antreten und unterwegs predigen."},{"verse":28,"text":"Lasst auch meine Diener Edson Fuller und Jacob Scott ihre Reise antreten."},{"verse":29,"text":"Lasst meine Diener Levi W. Hancock und Zebedee Coltrin auch ihre Reise antreten."},{"verse":30,"text":"Lasst meine Diener Reynolds Cahoon und Samuel H. Smith auch ihre Reise antreten."},{"verse":31,"text":"Lasst meine Diener Wheeler Baldwin und William Carter auch ihre Reise antreten."},{"verse":32,"text":"Und lasst meine Diener Newel Knight und Selah J. Griffin beide ordiniert werden und auch ihre Reise antreten."},{"verse":33,"text":"Ja, wahrlich, ich sage: Lasst alle diese ihre Reise nach dem einen Ort antreten, auf ihren verschiedenen Wegen, und der eine soll nicht auf der Grundlage eines anderen bauen, auch nicht in der Spur eines anderen reisen."},{"verse":34,"text":"Wer treu ist, der wird erhalten bleiben und mit viel Frucht gesegnet sein."},{"verse":35,"text":"Und weiter, ich sage euch: Lasst meine Diener Joseph Wakefield und Solomon Humphrey ihre Reise in die östlichen Länder antreten;"},{"verse":36,"text":"sie sollen mit ihrer Familie arbeiten und nichts anderes verkünden als die Propheten und Apostel, das, was sie gesehen und gehört haben und mit völliger Gewissheit glauben, damit sich die Prophezeiungen erfüllen."},{"verse":37,"text":"Infolge von Übertretung soll das, was Heman Basset verliehen worden ist, von ihm genommen und auf das Haupt von Simonds Ryder übertragen werden."},{"verse":38,"text":"Und weiter, wahrlich, ich sage euch: Jared Carter soll zum Priester ordiniert werden, und auch George James soll zum Priester ordiniert werden."},{"verse":39,"text":"Lasst die übrigen Ältesten über die Gemeinden wachen und das Wort in den Gebieten rings um sie her verkünden; und sie sollen mit ihren eigenen Händen arbeiten, damit weder Götzendienst noch Schlechtigkeit ausgeübt werde."},{"verse":40,"text":"Und gedenkt in allem der Armen und der Bedürftigen, der Kranken und der Bedrängten, denn wer das nicht tut, der ist nicht mein Jünger."},{"verse":41,"text":"Und weiter: Meine Diener Joseph Smith Jr. und Sidney Rigdon und Edward Partridge sollen ein Empfehlungsschreiben von der Kirche mitnehmen. Und auch für meinen Diener Oliver Cowdery soll eines erlangt werden."},{"verse":42,"text":"Und so, wie ich schon gesagt habe: Wenn ihr treu seid, werdet ihr euch zusammenfinden, um euch im Land Missouri zu freuen, das das Land eures Erbteils ist, das jetzt das Land eurer Feinde ist."},{"verse":43,"text":"Aber siehe, ich, der Herr, werde die Stadt zu ihrer Zeit beschleunigen und werde die Getreuen mit Freude und mit Jubel krönen."},{"verse":44,"text":"Siehe, ich bin Jesus Christus, der Sohn Gottes, und ich werde sie am letzten Tag emporheben. So ist es. Amen."}]},{"chapter":53,"verses":[{"verse":1,"text":"Siehe, ich sage dir, mein Diener Sidney Gilbert: Ich habe deine Gebete vernommen; und du hast mich angerufen, damit es dir vom Herrn, von deinem Gott, kundgetan werde, was deine Berufung und Erwählung in der Kirche sein soll, die ich, der Herr, in diesen letzten Tagen aufgerichtet habe."},{"verse":2,"text":"Siehe, ich, der Herr, der ich für die Sünden der Welt gekreuzigt worden bin, gebe dir das Gebot, dass du von der Welt lassen sollst."},{"verse":3,"text":"Nimm auf dich meine Ordinierung, nämlich jene eines Ältesten, um gemäß meinem Wort Glauben und Umkehr und Sündenvergebung zu predigen und den Empfang des Heiligen Geistes durch das Händeauflegen;"},{"verse":4,"text":"und auch, ein Beauftragter für diese Kirche zu sein, an dem Platz, der vom Bischof bestimmt werden wird, gemäß den Geboten, die später noch gegeben werden."},{"verse":5,"text":"Und weiter, wahrlich, ich sage dir: Du sollst mit meinen Dienern Joseph Smith Jr. und Sidney Rigdon deine Reise antreten."},{"verse":6,"text":"Siehe, dies sind die ersten Verordnungen, die du empfangen sollst; und die übrigen werden zu einer zukünftigen Zeit kundgetan werden, gemäß deiner Arbeit in meinem Weingarten."},{"verse":7,"text":"Und weiter: Ich möchte, dass ihr dies lernt: Nur der wird errettet, der bis ans Ende ausharrt. So ist es. Amen."}]},{"chapter":54,"verses":[{"verse":1,"text":"Siehe, so spricht der Herr, ja, Alpha und Omega, der Anfang und das Ende, nämlich er, der für die Sünden der Welt gekreuzigt wurde:"},{"verse":2,"text":"Siehe, wahrlich, wahrlich, ich sage dir, mein Diener Newel Knight: Du sollst fest stehen in dem Amt, zu dem ich dich bestimmt habe."},{"verse":3,"text":"Und wenn deine Brüder ihren Feinden entrinnen möchten, so sollen sie von all ihren Sünden umkehren und vor mir wahrhaft demütig werden und zerknirscht sein."},{"verse":4,"text":"Und da der Bund, den sie mir gemacht haben, gebrochen worden ist, so ist er auch nichtig geworden und ohne Wirkung."},{"verse":5,"text":"Und weh dem, durch den dieses Ärgernis kommt, denn es wäre für ihn besser gewesen, er wäre in der Tiefe des Meeres ertränkt worden."},{"verse":6,"text":"Aber gesegnet sind, die den Bund gehalten und das Gebot beachtet haben, denn sie werden Barmherzigkeit erlangen."},{"verse":7,"text":"Darum geht nun daran und flieht aus dem Land, damit nicht eure Feinde über euch kommen; und tretet eure Reise an und bestimmt, wen ihr wollt, zu eurem Führer und dass er die Gelder für euch bezahle."},{"verse":8,"text":"Und so sollt ihr eure Reise in die Gebiete im Westen antreten, in das Land Missouri, bis an die Grenzen der Lamaniten."},{"verse":9,"text":"Und wenn ihr mit eurer Reise fertig seid, siehe, ich sage euch: Sucht euch euren Lebensunterhalt wie andere Menschen, bis ich euch einen Ort bereite."},{"verse":10,"text":"Und weiter: Seid geduldig in Drangsal, bis ich komme; und siehe, ich komme schnell, und mein Lohn kommt mit mir, und die früh nach mir gesucht haben, werden Ruhe finden für ihre Seele. So ist es. Amen."}]},{"chapter":55,"verses":[{"verse":1,"text":"Siehe, so spricht der Herr zu dir, mein Diener William, ja, nämlich der Herr der ganzen Erde: Du bist berufen und erwählt; und nachdem du mit Wasser getauft sein wirst, wenn du dies so tust, dass dein Auge nur auf meine Herrlichkeit gerichtet ist, wirst du Vergebung deiner Sünden erlangen und den Empfang des Heiligen Geistes durch das Händeauflegen;"},{"verse":2,"text":"und dann wirst du durch die Hand meines Dieners Joseph Smith Jr. ordiniert werden, um ein Ältester für diese Kirche zu sein, um Umkehr und Sündenvergebung mittels der Taufe im Namen Jesu Christi, des Sohnes des lebendigen Gottes, zu predigen."},{"verse":3,"text":"Und wem auch immer du die Hände auflegst, wenn er zerknirscht vor mir ist, wirst du die Macht haben, den Heiligen Geist zu spenden."},{"verse":4,"text":"Und weiter, du wirst ordiniert werden, meinem Diener Oliver Cowdery bei der Arbeit für das Drucken und für die Auswahl und das Schreiben von Büchern für die Schulen in dieser Kirche behilflich zu sein, damit auch die kleinen Kinder Unterweisung vor mir erhalten, wie es mir wohlgefällig ist."},{"verse":5,"text":"Und weiter, wahrlich, ich sage dir: Aus diesem Grund sollst du deine Reise mit meinen Dienern Joseph Smith Jr. und Sidney Rigdon antreten, damit du in das Land deines Erbteils gepflanzt werdest, um diese Arbeit zu tun."},{"verse":6,"text":"Und weiter: Auch mein Diener Joseph Coe soll mit ihnen seine Reise antreten. Das Übrige wird später noch kundgetan werden, ja, wie ich es will. Amen."}]},{"chapter":56,"verses":[{"verse":1,"text":"Horcht auf, o ihr Volk, die ihr euch zu meinem Namen bekennt, spricht der Herr, euer Gott; denn siehe, mein Zorn ist gegen die Widersetzlichen entflammt, und sie werden meinen Arm und meinen Unwillen am Tag der Heimsuchung und des Grimms über die Nationen kennenlernen."},{"verse":2,"text":"Und wer nicht sein Kreuz auf sich nehmen und mir nachfolgen und meine Gebote halten will, der wird nicht errettet werden."},{"verse":3,"text":"Siehe, ich, der Herr, gebiete; und wer nicht gehorchen will, der wird zu der von mir selbst bestimmten Zeit ausgestoßen werden, nachdem ich geboten habe und das Gebot gebrochen worden ist."},{"verse":4,"text":"Darum gebiete und widerrufe ich, der Herr, wie es mir gut scheint; und dies alles soll auf dem Haupt der Widersetzlichen verantwortet werden, spricht der Herr."},{"verse":5,"text":"Darum widerrufe ich das Gebot, das meinen Dienern Thomas B. Marsh und Ezra Thayre gegeben worden ist, und gebe meinem Diener Thomas das neue Gebot, schnell seine Reise in das Land Missouri anzutreten, und mein Diener Selah J. Griffin soll auch mit ihm gehen."},{"verse":6,"text":"Denn siehe, ich widerrufe das Gebot, das meinen Dienern Selah J. Griffin und Newel Knight gegeben worden ist, infolge der Halsstarrigkeit meines Volkes, das in Thompson ist, und seiner vielen Widersetzlichkeit."},{"verse":7,"text":"Darum soll mein Diener Newel Knight bei ihm bleiben; und alle, die gehen wollen, die vor mir zerknirscht sind, mögen gehen und sich von ihm in das Land führen lassen, das ich bestimmt habe."},{"verse":8,"text":"Und weiter, wahrlich, ich sage euch: Mein Diener Ezra Thayre muss von seinem Stolz und von seiner Selbstsucht umkehren und das frühere Gebot beachten, das ich ihm in Bezug auf den Ort, an dem er wohnt, gegeben habe."},{"verse":9,"text":"Und wenn er dies tut, da auf dem Land keine Teilungen vorgenommen werden sollen, so ist er noch immer bestimmt, in das Land Missouri zu gehen;"},{"verse":10,"text":"sonst aber soll er das Geld empfangen, das er gezahlt hat, und soll den Ort verlassen und soll aus meiner Kirche ausgeschlossen werden, spricht Gott, der Herr der Heerscharen;"},{"verse":11,"text":"und mögen auch der Himmel und die Erde vergehen, diese Worte werden nicht vergehen, sondern werden sich erfüllen."},{"verse":12,"text":"Und wenn mein Diener Joseph Smith Jr. notwendigerweise das Geld zahlen muss, siehe, so will ich, der Herr, es ihm im Land Missouri zurückzahlen, damit diejenigen, von denen er empfängt, gemäß dem, was sie tun, wieder belohnt werden können;"},{"verse":13,"text":"denn gemäß dem, was sie tun, werden sie empfangen, nämlich Ländereien als ihr Erbteil."},{"verse":14,"text":"Siehe, so spricht der Herr zu meinem Volk: Es gibt viel, was ihr tun müsst und wovon ihr umkehren müsst, denn siehe, eure Sünden sind vor mich heraufgekommen und sind nicht verziehen, weil ihr danach trachtet, auf eure eigene Weise Rat zu halten."},{"verse":15,"text":"Und im Herzen seid ihr nicht zufrieden. Und ihr gehorcht nicht der Wahrheit, sondern habt Gefallen am Unrecht."},{"verse":16,"text":"Weh euch Reichen, die ihr eure Habe nicht den Armen geben wollt, denn euer Reichtum wird euch die Seele zerfressen; und dies wird eure Klage sein am Tag der Heimsuchung und des Gerichts und des Unwillens: Die Ernte ist vorbei, der Sommer ist zu Ende, und meine Seele ist nicht errettet!"},{"verse":17,"text":"Weh euch Armen, deren Herz nicht reuig ist, deren Geist nicht zerknirscht ist und deren Bauch unersättlich ist und deren Hände sich nicht abhalten lassen, die Güter anderer Menschen zu ergreifen, deren Augen voller Habgier sind und die ihr nicht mit euren eigenen Händen arbeiten wollt!"},{"verse":18,"text":"Aber gesegnet sind die Armen, die im Herzen rein sind, deren Herz reuig ist und deren Geist zerknirscht ist, denn sie werden das Reich Gottes sehen, wie es mit Macht und großer Herrlichkeit kommt, um sie zu befreien; denn der fette Ertrag der Erde wird ihnen gehören."},{"verse":19,"text":"Denn siehe, der Herr wird kommen, und seine Vergeltung wird mit ihm sein; und er wird einen jeden belohnen, und die Armen werden sich freuen;"},{"verse":20,"text":"und ihre Generationen werden die Erde ererben, von Generation zu Generation, für immer und immer. Und nun komme ich damit zu Ende, zu euch zu reden. So ist es. Amen."}]},{"chapter":57,"verses":[{"verse":1,"text":"Horcht auf, o ihr Ältesten meiner Kirche, spricht der Herr, euer Gott, die ihr euch gemäß meinen Geboten in diesem Land versammelt habt, nämlich im Land Missouri, nämlich in dem Land, das ich für die Sammlung der Heiligen bestimmt und geweiht habe."},{"verse":2,"text":"Darum ist dies das Land der Verheißung und der Ort für die Stadt Zion."},{"verse":3,"text":"Und so spricht der Herr, euer Gott: Wenn ihr Weisheit empfangen wollt, hier ist Weisheit. Siehe, der Ort, der jetzt Independence genannt wird, ist das Zentrum; und ein Platz für den Tempel ist westlich davon, auf einem Grundstück nicht weit vom Gerichtsgebäude."},{"verse":4,"text":"Darum ist es Weisheit, dass die Heiligen das Land kaufen, ebenso das ganze Gebiet westlich davon, ja, bis an die Linie, die unmittelbar zwischen den Juden und den Anderen verläuft,"},{"verse":5,"text":"ebenso alles Gebiet, was an die Prärie grenzt, soweit meine Jünger imstande sind, Land zu kaufen. Siehe, dies ist Weisheit, damit sie es als immerwährendes Erbteil erlangen können."},{"verse":6,"text":"Und lasst meinen Diener Sidney Gilbert in dem Amt stehen, zu dem ich ihn bestimmt habe, um Gelder in Empfang zu nehmen, um als Beauftragter für die Kirche zu handeln, um in allen Gebieten ringsum Land zu kaufen, soweit dies in Rechtschaffenheit geschehen kann und wie Weisheit es gebieten wird."},{"verse":7,"text":"Und lasst meinen Diener Edward Partridge in dem Amt stehen, zu dem ich ihn bestimmt habe, und den Heiligen ihr Erbteil zuteilen, so wie ich es geboten habe; ebenso diejenigen, die er bestimmt hat, dass sie ihm behilflich seien."},{"verse":8,"text":"Und weiter, wahrlich, ich sage euch: Lasst meinen Diener Sidney Gilbert sich an diesem Ort ansiedeln und einen Laden einrichten, damit er Waren ohne Betrug verkaufen kann, damit er Geld erlangen kann, um zum Nutzen der Heiligen Land kaufen zu können, und damit er erlangen kann, was auch immer die Jünger brauchen mögen, um sich auf ihrem Erbteil anzusiedeln."},{"verse":9,"text":"Und lasst meinen Diener Sidney Gilbert auch einen Berechtigungsschein erlangen – siehe, hier ist Weisheit, und wer da liest, der möge verstehen –, damit er auch Waren an das Volk senden kann durch wen er will, von den Gehilfen, die in seinem Dienst stehen,"},{"verse":10,"text":"und so für meine Heiligen sorgen kann, damit mein Evangelium denen gepredigt werden kann, die in der Finsternis und im Bereich und Schatten des Todes sitzen."},{"verse":11,"text":"Und weiter, wahrlich, ich sage euch: Lasst meinen Diener William W. Phelps sich an diesem Ort ansiedeln und sich als Drucker für die Kirche einrichten."},{"verse":12,"text":"Und siehe, wenn die Welt seine Schriften empfängt – siehe, hier ist Weisheit –, so soll er alles, was er in Rechtschaffenheit erlangen kann, zum Nutzen der Heiligen erlangen."},{"verse":13,"text":"Und mein Diener Oliver Cowdery soll ihm behilflich sein, so wie ich geboten habe, an welchem Platz auch immer ich für ihn bestimmen werde, um abzuschreiben und zu korrigieren und auszuwählen, damit alles vor mir recht sei, wie es der Geist durch ihn beweisen wird."},{"verse":14,"text":"Und so lasst diejenigen, von denen ich geredet habe, sich so schnell wie möglich mit ihrer Familie im Land Zion ansiedeln, um alles so zu tun, wie ich es gesagt habe."},{"verse":15,"text":"Und nun, was die Sammlung betrifft: Lasst den Bischof und den Beauftragten Vorbereitungen treffen für jene Familien, denen geboten worden ist, in dieses Land zu kommen, so schnell wie möglich, und sie auf ihrem Erbteil ansiedeln."},{"verse":16,"text":"Und den übrigen der Ältesten und auch der Mitglieder werden später noch weitere Weisungen gegeben werden. So ist es. Amen."}]},{"chapter":58,"verses":[{"verse":1,"text":"Horcht auf, o ihr Ältesten meiner Kirche, und schenkt meinem Wort Gehör, und erfahrt von mir, was mein Wille ist in Bezug auf euch und auch in Bezug auf dieses Land, in das ich euch gesandt habe."},{"verse":2,"text":"Denn wahrlich, ich sage euch: Gesegnet ist, wer meine Gebote hält, sei es im Leben oder im Tod; und wer in Drangsal treu ist, dessen Lohn im Himmelreich wird umso größer sein."},{"verse":3,"text":"Mit euren natürlichen Augen könnt ihr zur gegenwärtigen Zeit die Absicht eures Gottes in Bezug auf das, was später noch geschehen wird, nicht sehen, auch nicht die Herrlichkeit, die nach viel Drangsal folgen wird."},{"verse":4,"text":"Denn nach viel Drangsal kommen die Segnungen. Darum kommt der Tag, da ihr mit viel Herrlichkeit gekrönt werdet; die Stunde ist noch nicht, aber steht nahe bevor."},{"verse":5,"text":"Denkt an dieses, was ich euch im Voraus sage, damit ihr es euch zu Herzen nehmt und das empfangt, was folgen wird."},{"verse":6,"text":"Siehe, wahrlich, ich sage euch: Aus diesem Grund habe ich euch gesandt – dass ihr gehorsam seiet und dass euer Herz bereit sei, für das, was kommen wird, Zeugnis abzulegen;"},{"verse":7,"text":"und auch, dass euch die Ehre zuteilwerde, die Grundlage zu legen und für das Land, worauf das Zion Gottes stehen wird, Zeugnis abzulegen;"},{"verse":8,"text":"und auch, dass ein Festmahl von fetten Speisen für die Armen bereitet werde, ja, ein Festmahl von fetten Speisen und von Wein, der vom Bodensatz geläutert ist, damit die Erde wisse, dass der Mund der Propheten nicht fehlgeht;"},{"verse":9,"text":"ja, ein Abendmahl im Haus des Herrn, wohlbereitet, zu dem alle Nationen eingeladen sein werden."},{"verse":10,"text":"Zuerst die Reichen und die Gelehrten, die Weisen und die Edlen;"},{"verse":11,"text":"und danach kommt der Tag meiner Macht; dann werden die Armen, die Lahmen und die Blinden und die Tauben zur Hochzeit des Lammes hereinkommen und am Abendmahl des Herrn teilnehmen, bereitet für den großen Tag, der kommen wird."},{"verse":12,"text":"Siehe, ich, der Herr, habe es gesprochen:"},{"verse":13,"text":"Und damit das Zeugnis aus Zion, ja, aus dem Mund der Stadt des Erbes Gottes hervorgehe –"},{"verse":14,"text":"ja, aus diesem Grund habe ich euch hierher gesandt und habe meinen Diener Edward Partridge ausgewählt und habe ihm seinen Auftrag in diesem Land bestimmt."},{"verse":15,"text":"Aber wenn er von seinen Sünden nicht umkehrt, nämlich von Unglauben und Verblendung des Herzens, dann soll er sich in Acht nehmen, dass er nicht falle."},{"verse":16,"text":"Siehe, sein Auftrag ist ihm gegeben worden, und er wird nicht abermals gegeben werden."},{"verse":17,"text":"Und wer auch immer in diesem Auftrag steht, der ist dazu bestimmt, Richter in Israel zu sein, so wie es in alten Tagen war, dass er die Ländereien des Erbes Gottes dessen Kindern zuteile"},{"verse":18,"text":"und dass er dessen Volk richte nach dem Zeugnis der Gerechten und mit dem Beistand seiner Ratgeber, gemäß den Gesetzen des Reiches, die durch die Propheten Gottes gegeben werden."},{"verse":19,"text":"Denn wahrlich, ich sage euch: Mein Gesetz soll in diesem Land eingehalten werden."},{"verse":20,"text":"Keiner soll denken, er sei Herrscher, sondern lasst Gott gemäß dem Ratschluss seines eigenen Willens über denjenigen herrschen, der richtet oder, mit anderen Worten, den, der Rat gibt oder auf dem Richterstuhl sitzt."},{"verse":21,"text":"Keiner soll die Gesetze des Landes brechen, denn wer die Gesetze Gottes einhält, der braucht die Gesetze des Landes nicht zu brechen."},{"verse":22,"text":"Darum seid den bestehenden Mächten untertan, bis derjenige regiert, dessen Recht es ist zu regieren, und sich alle Feinde untertan macht unter seine Füße."},{"verse":23,"text":"Siehe, die Gesetze, die ihr von meiner Hand empfangen habt, sind die Gesetze der Kirche, und in diesem Licht sollt ihr sie darlegen. Siehe, hier ist Weisheit."},{"verse":24,"text":"Und nun, wie ich im Hinblick auf meinen Diener Edward Partridge gesagt habe – dieses Land ist das Land seines Wohnsitzes und derjenigen, die er zu seinen Ratgebern bestimmt hat, und auch das Land des Wohnsitzes für denjenigen, den ich bestimmt habe, mein Vorratshaus zu verwalten;"},{"verse":25,"text":"darum sollen sie ihre Familien in dieses Land bringen, wie sie sich untereinander und mit mir beraten werden."},{"verse":26,"text":"Denn siehe, es ist nicht recht, dass ich in allem gebieten muss; denn wer in allem genötigt werden muss, der ist ein träger und nicht ein weiser Diener, darum empfängt er keinen Lohn."},{"verse":27,"text":"Wahrlich, ich sage: Die Menschen sollen sich voll Eifer einer guten Sache widmen und vieles aus ihrem eigenen, freien Willen tun und viel Rechtschaffenheit zustande bringen;"},{"verse":28,"text":"denn die Macht ist in ihnen, wodurch sie für sich selbst handeln können. Und insoweit die Menschen Gutes tun, werden sie keineswegs ihres Lohnes verlustig gehen."},{"verse":29,"text":"Wer aber gar nichts tut, bis es ihm geboten wird, und ein Gebot mit zweifelndem Herzen empfängt und es auf träge Weise hält, der ist verdammt."},{"verse":30,"text":"Wer bin ich, der ich den Menschen gemacht habe, spricht der Herr, dass ich den als schuldlos ansehen werde, der meine Gebote nicht beachtet?"},{"verse":31,"text":"Wer bin ich, spricht der Herr, dass ich verheißen habe und nicht erfüllt habe?"},{"verse":32,"text":"Ich gebiete, und die Menschen gehorchen nicht; ich widerrufe, und sie empfangen die Segnung nicht."},{"verse":33,"text":"Dann sprechen sie in ihrem Herzen: Dies ist nicht das Werk des Herrn, denn seine Verheißungen gehen nicht in Erfüllung. Aber weh solchen, denn ihr Lohn lauert unten und nicht von oben."},{"verse":34,"text":"Und nun gebe ich euch weitere Weisungen in Bezug auf dieses Land."},{"verse":35,"text":"Es ist nach meiner Weisheit, dass mein Diener Martin Harris der Kirche ein Vorbild sein soll, indem er seine Gelder vor den Bischof der Kirche legt."},{"verse":36,"text":"Und dies ist auch ein Gesetz für einen jeden, der in dieses Land kommt, um ein Erbteil zu empfangen; und er soll mit seinen Geldern so tun, wie das Gesetz es anordnet."},{"verse":37,"text":"Und es ist auch Weisheit, dass in Independence Land gekauft werde für den Platz des Vorratshauses und ebenso für das Haus der Druckerei."},{"verse":38,"text":"Und weitere Weisungen in Bezug auf meinen Diener Martin Harris werden ihm vom Geist gegeben werden, damit er sein Erbteil empfange, wie es ihm gut scheint;"},{"verse":39,"text":"und er soll von seinen Sünden umkehren, denn er trachtet nach dem Lob der Welt."},{"verse":40,"text":"Und auch mein Diener William W. Phelps soll in dem Amt stehen, das ich ihm bestimmt habe, und sein Erbteil in dem Land empfangen;"},{"verse":41,"text":"und auch er hat es nötig umzukehren, denn ich, der Herr, habe kein Wohlgefallen an ihm, denn er trachtet danach, sich hervorzutun, und er ist vor mir nicht sanftmütig genug."},{"verse":42,"text":"Siehe, wer von seinen Sünden umgekehrt ist, dem ist vergeben, und ich, der Herr, denke nicht mehr an sie."},{"verse":43,"text":"Ob jemand von seinen Sünden umkehrt, könnt ihr daran erkennen: Siehe, er wird sie bekennen und von ihnen lassen."},{"verse":44,"text":"Und nun, wahrlich, was die übrigen Ältesten meiner Kirche betrifft, sage ich: Die Zeit ist noch nicht gekommen, viele Jahre lang, dass sie ihr Erbteil in diesem Land empfangen, außer sie wünschen es durch das Gebet des Glaubens, und dann nur, wie es ihnen vom Herrn bestimmt wird."},{"verse":45,"text":"Denn siehe, sie werden das Volk von den Enden der Erde zusammentreiben."},{"verse":46,"text":"Darum sammelt euch; und die nicht bestimmt sind, in diesem Land zu bleiben, sollen in den Gegenden ringsum das Evangelium predigen; und danach sollen sie nach Hause zurückkehren."},{"verse":47,"text":"Sie sollen unterwegs predigen und an allen Orten für die Wahrheit Zeugnis geben und die Reichen, die Hohen und die Niedrigen und die Armen zur Umkehr rufen."},{"verse":48,"text":"Und sie sollen Gemeinden aufrichten, insoweit die Bewohner der Erde umkehren."},{"verse":49,"text":"Und lasst durch die Stimme der Kirche einen Beauftragten für die Gemeinde in Ohio bestimmen, dass er Gelder in Empfang nehme, um in Zion Ländereien zu kaufen."},{"verse":50,"text":"Und meinem Diener Sidney Rigdon gebe ich das Gebot, vom Land Zion eine Beschreibung zu verfassen, ebenso eine Erklärung des Willens Gottes, wie ihm dieser durch den Geist kundgetan werden wird;"},{"verse":51,"text":"dazu auch einen Brief samt einer Zeichnungsliste, die allen Gemeinden vorgelegt werden sollen, um Gelder zu erlangen, die in die Hände des Bischofs übergeben werden sollen, in seine oder die des Beauftragten, wie es ihm gut scheint oder wie er die Weisung dazu erteilt, um Ländereien als Erbteil für die Kinder Gottes zu kaufen."},{"verse":52,"text":"Denn siehe, wahrlich, ich sage euch: Der Herr will, dass die Jünger und die Menschenkinder ihr Herz öffnen sollen, ja, um dieses ganze Gebiet im Land zu kaufen, sobald es die Zeit erlaubt."},{"verse":53,"text":"Siehe, hier ist Weisheit. Lasst sie das tun, denn sonst werden sie, außer durch Blutvergießen, kein Erbteil empfangen."},{"verse":54,"text":"Und weiter, soweit Land erworben wird, sollen Werkleute aller Art in dieses Land gesandt werden, um für die Heiligen Gottes zu arbeiten."},{"verse":55,"text":"Lasst dies alles in Ordnung geschehen; und der Bischof oder der Beauftragte der Kirche soll von Zeit zu Zeit die Nutzungsrechte der Ländereien bekanntgeben."},{"verse":56,"text":"Und das Werk der Sammlung soll nicht in Hast vor sich gehen, auch nicht als Flucht; sondern es soll so geschehen, wie die Ältesten der Kirche auf den Konferenzen beraten werden, gemäß der Kenntnis, die sie von Zeit zu Zeit empfangen."},{"verse":57,"text":"Und mein Diener Sidney Rigdon soll dieses Land sowie den Platz für den Tempel dem Herrn weihen und widmen."},{"verse":58,"text":"Und eine Konferenzversammlung soll einberufen werden; und danach sollen meine Diener Sidney Rigdon und Joseph Smith Jr. zurückkehren, und auch Oliver Cowdery mit ihnen, um den übrigen Teil der Arbeit auszuführen, die ich ihnen in ihrem eigenen Land bestimmt habe, und die Übrigen, wie es von den Konferenzen bestimmt werden wird."},{"verse":59,"text":"Und lasst keinen aus diesem Land zurückkehren, wenn er nicht unterwegs Zeugnis gibt für das, was er weiß und mit völliger Gewissheit glaubt."},{"verse":60,"text":"Das, was Ziba Peterson verliehen worden ist, soll ihm genommen werden, und er soll in der Kirche als ein Mitglied dastehen und mit seinen eigenen Händen arbeiten, mit den Brüdern, bis er für alle seine Sünden genügend gezüchtigt ist; denn er bekennt sie nicht, und er gedenkt, sie zu verbergen."},{"verse":61,"text":"Lasst die übrigen Ältesten dieser Kirche, die in dieses Land kommen und von denen einige überaus gesegnet sind, ja, über die Maßen, ebenfalls eine Konferenz in diesem Land halten."},{"verse":62,"text":"Und mein Diener Edward Partridge soll die Konferenz, die sie halten werden, leiten."},{"verse":63,"text":"Und auch sie sollen zurückkehren, unterwegs das Evangelium predigen und für das, was ihnen offenbart wird, Zeugnis geben."},{"verse":64,"text":"Denn wahrlich, der Ruf muss von diesem Ort hinausgehen in alle Welt und bis in die entlegensten Teile der Erde – das Evangelium muss jedem Geschöpf gepredigt werden, mit Zeichen, die denen folgen, die da glauben."},{"verse":65,"text":"Und siehe, des Menschen Sohn kommt. Amen."}]},{"chapter":59,"verses":[{"verse":1,"text":"Siehe, gesegnet, spricht der Herr, sind diejenigen, die gemäß meinen Geboten in dieses Land heraufgekommen sind, das Auge nur auf meine Herrlichkeit gerichtet."},{"verse":2,"text":"Denn diejenigen, die leben, werden die Erde ererben, und diejenigen, die sterben, werden von all ihrer Arbeit ausruhen, und ihre Werke werden ihnen nachfolgen; und sie werden in den Wohnungen meines Vaters, die ich für sie bereitet habe, eine Krone empfangen."},{"verse":3,"text":"Ja, gesegnet sind die, deren Füße auf dem Land Zion stehen und die mein Evangelium beachtet haben, denn sie werden als ihren Lohn die guten Dinge der Erde empfangen, und sie wird mit aller Stärke hervorbringen."},{"verse":4,"text":"Und sie werden auch mit Segnungen von oben gekrönt werden, ja, und mit nicht wenigen Geboten und mit Offenbarungen zu ihrer Zeit – diejenigen, die treu und eifrig vor mir sind."},{"verse":5,"text":"Darum gebe ich ihnen ein Gebot, nämlich so: Du sollst den Herrn, deinen Gott, lieben mit deinem ganzen Herzen, mit all deiner Macht, ganzem Sinn und aller Kraft; und im Namen Jesu Christi sollst du ihm dienen."},{"verse":6,"text":"Du sollst deinen Nächsten lieben wie dich selbst. Du sollst nicht stehlen, auch nicht Ehebruch begehen, nicht töten noch irgendetwas Derartiges tun."},{"verse":7,"text":"Du sollst dem Herrn, deinem Gott, in allem danken."},{"verse":8,"text":"Du sollst dem Herrn, deinem Gott, in Rechtschaffenheit ein Opfer darbringen, nämlich das eines reuigen Herzens und eines zerknirschten Geistes."},{"verse":9,"text":"Und damit du dich selbst noch mehr von der Welt unbefleckt halten mögest, sollst du an meinem heiligen Tag ins Haus des Betens gehen und deine heiligen Handlungen darbringen;"},{"verse":10,"text":"denn wahrlich, dies ist der Tag, der dir bestimmt ist, von deiner Arbeit zu ruhen und dem Allerhöchsten deine Ergebenheit zu erweisen;"},{"verse":11,"text":"doch sollen deine Gelübde an allen Tagen und zu allen Zeiten in Rechtschaffenheit dargebracht werden;"},{"verse":12,"text":"aber denke daran: An diesem, dem Tag des Herrn, sollst du dem Allerhöchsten deine Opfergaben und deine heiligen Handlungen darbringen und deinen Brüdern sowie vor dem Herrn deine Sünden bekennen."},{"verse":13,"text":"Und an diesem Tag sollst du nichts anderes tun, nur mit Lauterkeit des Herzens deine Speise bereiten, damit dein Fasten vollkommen sei oder, mit anderen Worten, damit deine Freude voll sei."},{"verse":14,"text":"Wahrlich, dies ist Fasten und Beten oder, mit anderen Worten, Sichfreuen und Beten."},{"verse":15,"text":"Und insoweit ihr dies alles mit Danksagung tut, mit fröhlichem Herzen und Angesicht, nicht mit viel Gelächter, denn das ist Sünde, sondern mit frohem Herzen und fröhlichem Angesicht –"},{"verse":16,"text":"wahrlich, ich sage: Insoweit ihr dies tut, so gehört euch die Fülle der Erde, die Tiere des Feldes und die Vögel der Luft und das, was auf die Bäume klettert und auf der Erde läuft,"},{"verse":17,"text":"ja, und das Kraut und alles Gute, was von der Erde kommt, sei es zur Nahrung oder zur Kleidung oder für Häuser oder für Scheunen oder für Obstgärten oder für Gärten oder für Weingärten;"},{"verse":18,"text":"ja, alles, was zu seiner Zeit von der Erde kommt, ist dem Menschen zum Nutzen und Gebrauch gemacht, dass es sowohl das Auge erfreue als auch das Herz beglücke,"},{"verse":19,"text":"ja, zur Nahrung und zur Kleidung, zum Schmecken und zum Riechen, zur Stärkung des Leibes und zur Belebung der Seele."},{"verse":20,"text":"Und es gefällt Gott, dass er dies alles dem Menschen gegeben hat; denn zu diesem Zweck ist es gemacht worden, dass es gebraucht werde, mit Urteilsvermögen, nicht im Übermaß, auch nicht durch Androhung von Gewalt."},{"verse":21,"text":"Und in nichts beleidigt der Mensch Gott, oder gegen niemanden entflammt sein Grimm, ausgenommen diejenigen, die seine Hand nicht in allem anerkennen und seine Gebote nicht beachten."},{"verse":22,"text":"Siehe, dies ist gemäß dem Gesetz und den Propheten; darum behelligt mich in dieser Sache nicht mehr."},{"verse":23,"text":"Sondern lernt, dass derjenige, der die Werke der Rechtschaffenheit tut, seinen Lohn empfangen wird, nämlich Frieden in dieser Welt und ewiges Leben in der künftigen Welt."},{"verse":24,"text":"Ich, der Herr, habe es gesagt, und der Geist gibt Zeugnis. Amen."}]},{"chapter":60,"verses":[{"verse":1,"text":"Siehe, so spricht der Herr zu den Ältesten seiner Kirche, die schnell in das Land zurückkehren sollen, von wo sie gekommen sind: Siehe, es gefällt mir, dass ihr hierhergekommen seid;"},{"verse":2,"text":"aber an einigen habe ich kein Wohlgefallen, denn sie wollen ihren Mund nicht auftun, sondern aus Menschenfurcht verbergen sie das Talent, das ich ihnen gegeben habe. Weh solchen, denn mein Zorn ist gegen sie entflammt."},{"verse":3,"text":"Und es wird sich begeben: Wenn sie mir nicht mehr Glaubenstreue erzeigen, wird ihnen selbst das weggenommen werden, was sie haben."},{"verse":4,"text":"Denn ich, der Herr, herrsche in den Himmeln oben und über die Heere der Erde; und an dem Tag, da ich meine Juwelen herrichte, werden alle Menschen wissen, was es ist, das die Macht Gottes bezeugt."},{"verse":5,"text":"Aber wahrlich, ich will zu euch über eure Reise in das Land sprechen, von wo ihr gekommen seid. Lasst da ein Wasserfahrzeug bauen oder kauft eines, wie es euch gut scheint, es macht mir nichts aus, und tretet schnell eure Reise zu dem Ort an, der St. Louis genannt wird."},{"verse":6,"text":"Und von dort sollen meine Diener Sidney Rigdon, Joseph Smith Jr. und Oliver Cowdery ihre Reise nach Cincinnati antreten;"},{"verse":7,"text":"und an dem Ort sollen sie ihre Stimme erheben und mein Wort mit lauter Stimme verkünden, ohne Grimm oder Zweifel, und heilige Hände über sie erheben. Denn ich bin imstande, euch heilig zu machen, und eure Sünden sind euch vergeben."},{"verse":8,"text":"Und lasst die Übrigen von St. Louis aus ihre Reise antreten, zu zweit, und in den Zusammenkünften der Schlechten ohne Hast das Wort predigen, bis sie zu den Gemeinden zurückkehren, von wo sie gekommen sind."},{"verse":9,"text":"Und dies alles zum Nutzen der Gemeinden; mit dieser Absicht habe ich sie gesandt."},{"verse":10,"text":"Und mein Diener Edward Partridge soll von dem Geld, das ich ihm gegeben habe, einen Teil meinen Ältesten geben, denen geboten worden ist zurückzukehren;"},{"verse":11,"text":"und wer dazu imstande ist, der soll es über den Beauftragten zurückzahlen, und wer es nicht ist, von dem wird es nicht verlangt."},{"verse":12,"text":"Und nun rede ich von den Übrigen, die noch in dieses Land kommen werden."},{"verse":13,"text":"Siehe, sie sind ausgesandt worden, um in den Zusammenkünften der Schlechten mein Evangelium zu predigen; darum gebe ich ihnen ein Gebot, und zwar: Du sollst deine Zeit nicht müßig vertun, auch sollst du dein Talent nicht vergraben, auf dass es nicht bekannt werde."},{"verse":14,"text":"Und wenn du in das Land Zion heraufgekommen bist und mein Wort verkündigt hast, sollst du schnell zurückkehren und in den Zusammenkünften der Schlechten mein Wort verkündigen, nicht in Hast, auch nicht im Grimm noch mit Streit."},{"verse":15,"text":"Und schüttle den Staub von deinen Füßen gegen diejenigen, die dich nicht empfangen, nicht in ihrer Gegenwart, damit du sie nicht zum Zorn reizt, sondern im Verborgenen; und wasche deine Füße zum Zeugnis gegen sie am Tag des Gerichts."},{"verse":16,"text":"Siehe, dies ist genügend für euch und der Wille dessen, der euch gesandt hat."},{"verse":17,"text":"Und durch den Mund meines Dieners Joseph Smith Jr. soll kundgetan werden, was Sidney Rigdon und Oliver Cowdery betrifft. Das Übrige später. So ist es. Amen."}]},{"chapter":61,"verses":[{"verse":1,"text":"Seht und hört auf die Stimme dessen, der alle Macht hat, der vom Immerwährenden zum Immerwährenden ist, nämlich Alpha und Omega, der Anfang und das Ende."},{"verse":2,"text":"Siehe, wahrlich, so spricht der Herr zu euch, o ihr Ältesten meiner Kirche, die ihr an dieser Stelle versammelt seid, ihr, deren Sünden euch nun vergeben sind, denn ich, der Herr, vergebe Sünden und bin barmherzig zu denen, die ihre Sünden mit demütigem Herzen bekennen;"},{"verse":3,"text":"aber wahrlich, ich sage euch: Es ist nicht nötig, dass diese ganze Abteilung meiner Ältesten sich schnell auf den Wassern fortbewegt, während die Bewohner zu beiden Seiten in Unglauben zugrunde gehen."},{"verse":4,"text":"Doch habe ich es zugelassen, damit ihr Zeugnis geben könnt; siehe, es gibt viele Gefahren auf den Wassern, und besonders von nun an;"},{"verse":5,"text":"denn ich, der Herr, habe in meinem Zorn viele Zerstörungen auf den Wassern beschlossen, ja, und besonders auf diesen Wassern."},{"verse":6,"text":"Doch ist alles Fleisch in meiner Hand, und wer unter euch treu ist, der wird nicht durch die Wasser zugrunde gehen."},{"verse":7,"text":"Darum ist es ratsam, dass mein Diener Sidney Gilbert und mein Diener William W. Phelps eilends ihren Auftrag und ihre Mission antreten."},{"verse":8,"text":"Doch wollte ich nicht zulassen, dass ihr auseinandergeht, ehe ihr für alle eure Sünden gezüchtigt seid, auf dass ihr eins seiet, auf dass ihr nicht in Schlechtigkeit zugrunde gehet;"},{"verse":9,"text":"aber jetzt, wahrlich, ich sage: Mir erscheint es angebracht, dass ihr auseinandergeht. Darum sollen meine Diener Sidney Gilbert und William W. Phelps ihre frühere Abteilung sammeln, und sie sollen eilends ihre Reise antreten, um ihre Mission zu erfüllen, und durch Glauben werden sie überwinden;"},{"verse":10,"text":"und insoweit sie treu sind, werden sie bewahrt werden, und ich, der Herr, werde mit ihnen sein."},{"verse":11,"text":"Und die Übrigen sollen mitnehmen, was sie an Kleidung brauchen."},{"verse":12,"text":"Lasst meinen Diener Sidney Gilbert das mitnehmen, was nicht gebraucht wird, wie ihr euch darauf einigt."},{"verse":13,"text":"Und nun, siehe, zu eurem Nutzen habe ich euch in Bezug auf dies alles ein Gebot gegeben; und ich, der Herr, werde euch meine Gründe darlegen wie den Männern in alten Tagen."},{"verse":14,"text":"Siehe, ich, der Herr, habe am Anfang die Wasser gesegnet; aber in den letzten Tagen habe ich durch den Mund meines Dieners Johannes die Wasser verflucht."},{"verse":15,"text":"Darum werden die Tage kommen, da kein Fleisch auf den Wassern sicher sein wird."},{"verse":16,"text":"Und in künftigen Tagen wird man sagen, dass niemand imstande ist, auf den Wassern in das Land Zion hinaufzugehen, als nur jemand, der im Herzen aufrichtig ist."},{"verse":17,"text":"Und wie ich, der Herr, am Anfang das Land verflucht habe, so habe ich es in den letzten Tagen, zu seiner Zeit, meinen Heiligen zum Gebrauch gesegnet, damit sie an dessen fettem Ertrag teilhaben mögen."},{"verse":18,"text":"Und nun gebe ich euch das Gebot, dass ich das, was ich zu einem sage, zu allen sage, dass ihr eure Brüder in Bezug auf diese Wasser vorwarnt, damit sie nicht auf ihnen anreisen und ihr Glaube versage und sie in Schlingen gefangen werden;"},{"verse":19,"text":"ich, der Herr, habe beschlossen, und der Zerstörer fährt auf der Wasserfläche einher, und ich widerrufe den Beschluss nicht."},{"verse":20,"text":"Ich, der Herr, war gestern zornig auf euch, aber heute ist mein Zorn abgewendet."},{"verse":21,"text":"Darum sollen diejenigen, von denen ich gesagt habe, dass sie eilends ihre Reise antreten sollen – abermals sage ich euch: Sie sollen eilends ihre Reise antreten."},{"verse":22,"text":"Und es macht mir nichts aus, wenn es so ist, dass sie nach einer kleinen Weile ihre Mission erfüllen, ob sie zu Wasser oder zu Lande reisen; das soll sein, wie es ihnen hernach gemäß ihrem eigenen Urteil kundgetan werden wird."},{"verse":23,"text":"Und nun, was meine Diener Sidney Rigdon, Joseph Smith Jr. und Oliver Cowdery betrifft: Sie sollen, wenn sie ihre Heimreise antreten, sich nicht wieder auf die Wasser begeben, es sei denn auf den Kanal; oder, mit anderen Worten, sie sollen nicht auf den Wassern reisen, außer auf dem Kanal."},{"verse":24,"text":"Siehe, ich, der Herr, habe einen Weg für das Reisen meiner Heiligen bestimmt, und siehe, dies ist der Weg: Nachdem sie den Kanal verlassen, sollen sie zu Lande reisen, da es ihnen geboten ist, zu reisen und in das Land Zion hinaufzugehen;"},{"verse":25,"text":"und sie sollen es den Kindern Israel gleichtun und unterwegs ihre Zelte aufschlagen."},{"verse":26,"text":"Und siehe, dieses Gebot sollt ihr allen euren Brüdern geben."},{"verse":27,"text":"Doch wem die Macht gegeben ist, den Wassern zu gebieten, dem ist es durch den Geist gegeben, alle seine Wege zu wissen;"},{"verse":28,"text":"darum soll er tun, wie der Geist des lebendigen Gottes ihm gebietet, sei es auf dem Land oder auf den Wassern, wie es mir überlassen bleibt, von nun an zu tun."},{"verse":29,"text":"Und euch ist die Richtung für die Heiligen gegeben oder der Weg, auf dem die Heiligen des Lagers des Herrn reisen sollen."},{"verse":30,"text":"Und weiter, wahrlich, ich sage euch: Meine Diener Sidney Rigdon, Joseph Smith Jr. und Oliver Cowdery sollen in den Zusammenkünften der Schlechten ihren Mund nicht auftun, bis sie in Cincinnati ankommen;"},{"verse":31,"text":"und an dem Ort sollen sie gegen jenes Volk die Stimme zu Gott erheben, ja, zu ihm, dessen Zorn gegen ihre Schlechtigkeit entflammt ist, ein Volk, das beinah reif ist für die Vernichtung."},{"verse":32,"text":"Und von dort sollen sie zu den Zusammenkünften ihrer Brüder reisen, denn schon jetzt ist ihre Arbeit unter denen noch reichlicher vonnöten als in den Zusammenkünften der Schlechten."},{"verse":33,"text":"Und nun, was die Übrigen betrifft: Lasst sie reisen und in den Zusammenkünften der Schlechten das Wort verkünden, soweit es gegeben wird;"},{"verse":34,"text":"und wenn sie das tun, werden sie ihre Kleider rein machen, und sie werden makellos vor mir sein."},{"verse":35,"text":"Und sie sollen zusammen reisen oder zu zweit, wie es ihnen gut scheint; nur mein Diener Reynolds Cahoon und mein Diener Samuel H. Smith, an denen ich Wohlgefallen habe, sollen nicht getrennt werden, bis sie nach Hause zurückgekehrt sind, und dies aus meiner weisen Absicht."},{"verse":36,"text":"Und nun, wahrlich, ich sage euch, und was ich zu einem sage, das sage ich zu allen: Seid guten Mutes, kleine Kinder, denn ich bin mitten unter euch, und ich habe euch nicht verlassen;"},{"verse":37,"text":"und da ihr euch vor mir gedemütigt habt, sind die Segnungen des Gottesreiches euer."},{"verse":38,"text":"Gürtet euch die Lenden und seid wachsam und seid ernsthaft; schaut aus nach dem Kommen des Menschensohnes, denn er kommt zu einer Stunde, da ihr es nicht denkt."},{"verse":39,"text":"Betet immer, dass ihr nicht in Versuchung geratet, dass ihr den Tag seines Kommens aushalten könnt, sei es im Leben oder im Tod. So ist es. Amen."}]},{"chapter":62,"verses":[{"verse":1,"text":"Seht und horcht auf, o ihr Ältesten meiner Kirche, spricht der Herr, euer Gott, nämlich Jesus Christus, euer Fürsprecher, der die Schwäche des Menschen kennt und denen beizustehen weiß, die versucht werden."},{"verse":2,"text":"Und wahrlich, meine Augen ruhen auf denen, die noch nicht ins Land Zion hinaufgegangen sind; darum ist eure Mission noch nicht erfüllt."},{"verse":3,"text":"Doch seid ihr gesegnet, denn das Zeugnis, das ihr gegeben habt, ist im Himmel aufgezeichnet, sodass die Engel es betrachten können; und sie freuen sich über euch, und eure Sünden sind euch vergeben."},{"verse":4,"text":"Und nun setzt eure Reise fort. Sammelt euch im Land Zion, und haltet eine Versammlung und freut euch miteinander; und bringt dem Allerhöchsten eine heilige Handlung dar."},{"verse":5,"text":"Und dann mögt ihr zurückkehren, um Zeugnis zu geben, ja, nämlich alle zusammen oder zu zweit, wie es euch gut scheint, mir macht es nichts aus; seid nur treu, und verkündet den Bewohnern der Erde, oder in den Zusammenkünften der Schlechten, frohe Nachricht."},{"verse":6,"text":"Siehe, ich, der Herr, habe euch zusammengeführt, damit sich die Verheißung erfülle, dass die Treuen unter euch bewahrt werden und sich miteinander im Land Missouri freuen sollen. Ich, der Herr, verheiße den Treuen und kann nicht lügen."},{"verse":7,"text":"Ich, der Herr, bin willens: Wenn jemand von euch den Wunsch hat, auf einem Pferd oder auf einem Maultier zu reiten oder in einem Wagen zu fahren, so soll er diese Segnung empfangen, wenn er sie aus der Hand des Herrn mit dankerfülltem Herzen für alles empfängt."},{"verse":8,"text":"Dies verbleibt bei euch, damit ihr mit Urteilsvermögen und gemäß den Weisungen des Geistes handeln könnt."},{"verse":9,"text":"Siehe, das Reich ist euer. Und siehe, ja, siehe, ich bin allezeit mit den Treuen. So ist es. Amen."}]},{"chapter":63,"verses":[{"verse":1,"text":"Horcht auf, o ihr Volk, und öffnet euer Herz und schenkt von fernher Gehör; und hört zu, ihr, die ihr euch das Volk des Herrn nennt, und vernehmt das Wort des Herrn und seinen Willen in Bezug auf euch."},{"verse":2,"text":"Ja, wahrlich, ich sage: Vernehmt das Wort dessen, dessen Zorn gegen die Schlechten und Widersetzlichen entflammt ist,"},{"verse":3,"text":"dessen Wille es ist, diejenigen hinwegzunehmen, die er hinwegnehmen will, und der diejenigen am Leben erhält, die er erhalten will,"},{"verse":4,"text":"der nach seinem eigenen Willen und Wohlgefallen aufbaut und zerstört, wenn es ihm gefällt, und imstande ist, die Seele in die Hölle hinabzuwerfen."},{"verse":5,"text":"Siehe, ich, der Herr, lasse meine Stimme erschallen, und ihr soll gehorcht werden."},{"verse":6,"text":"Darum, wahrlich, ich sage: Die Schlechten sollen sich in Acht nehmen, und die Widersetzlichen sollen sich fürchten und zittern; und die Ungläubigen sollen die Lippen schließen, denn der Tag des Grimms wird über sie kommen wie ein Wirbelsturm, und alles Fleisch wird wissen, dass ich Gott bin."},{"verse":7,"text":"Und wer nach Zeichen trachtet, wird Zeichen sehen, aber nicht zur Errettung."},{"verse":8,"text":"Wahrlich, ich sage euch: Es gibt unter euch welche, die nach Zeichen trachten, und solche hat es schon von Anfang an gegeben;"},{"verse":9,"text":"aber siehe, der Glaube kommt nicht durch Zeichen, sondern Zeichen folgen denen, die da glauben."},{"verse":10,"text":"Ja, Zeichen kommen durch den Glauben, nicht durch den Willen der Menschen, auch nicht nach ihrem Belieben, sondern durch den Willen Gottes."},{"verse":11,"text":"Ja, Zeichen kommen durch den Glauben, der zu mächtigen Werken führt, denn ohne Glauben kann kein Mensch Gott gefallen; und wem Gott zürnt, an dem hat er kein Wohlgefallen; darum zeigt er so jemandem keine Zeichen, außer im Grimm, um ihn schuldig zu sprechen."},{"verse":12,"text":"Darum habe ich, der Herr, kein Gefallen an denen von euch, die nach Zeichen und Wundern trachten für ihren Glauben und nicht zum Nutzen der Menschen, zu meiner Herrlichkeit."},{"verse":13,"text":"Doch ich gebe Gebote, und viele haben sich von meinen Geboten abgewendet und haben sie nicht gehalten."},{"verse":14,"text":"Es waren unter euch Ehebrecher und Ehebrecherinnen; einige davon haben sich von euch abgewendet, andere aber sind bei euch geblieben, die später noch offenbart werden."},{"verse":15,"text":"Solche sollen sich in Acht nehmen und schnell umkehren, damit nicht Strafgericht über sie komme wie eine Schlinge und ihre Torheit kundgetan werde und ihre Werke ihnen in den Augen des Volkes nachfolgen."},{"verse":16,"text":"Und wahrlich, ich sage euch, wie ich schon zuvor gesagt habe: Wer eine Frau ansieht, dass es ihn nach ihr gelüstet, oder wenn jemand in seinem Herzen Ehebruch begeht, so wird er den Geist nicht haben, sondern wird den Glauben verleugnen und wird sich fürchten."},{"verse":17,"text":"Darum habe ich, der Herr, gesagt: Die Fürchtenden und die Ungläubigen und alle Lügner und wer auch immer Lüge liebt und tut und die Unzüchtigen und die Zauberer werden ihr Teil haben in dem See, der mit Feuer und Schwefel brennt, was der zweite Tod ist."},{"verse":18,"text":"Wahrlich, ich sage: Sie werden an der ersten Auferstehung nicht Anteil haben."},{"verse":19,"text":"Und nun siehe, ich, der Herr, sage euch: Ihr seid nicht gerechtfertigt, denn dies alles kommt unter euch vor."},{"verse":20,"text":"Doch wer im Glauben ausharrt und meinen Willen tut, der wird überwinden und wird ein Erbteil auf der Erde empfangen, wenn der Tag der Verklärung kommt;"},{"verse":21,"text":"wenn die Erde verklärt werden wird, nämlich gemäß dem Muster, das meinen Aposteln auf dem Berg gezeigt worden ist, von welchem Bericht ihr die Fülle noch nicht empfangen habt."},{"verse":22,"text":"Und nun, wahrlich, ich sage euch: Da ich gesagt habe, ich würde euch meinen Willen kundtun, siehe, so werde ich ihn euch kundtun, nicht in Form eines Gebotes, denn es gibt viele, die nicht darauf bedacht sind, meine Gebote zu halten."},{"verse":23,"text":"Aber wer meine Gebote hält, dem werde ich die Geheimnisse meines Reiches geben, und diese werden in ihm eine Quelle lebendigen Wassers sein, das zu immerwährendem Leben emporquillt."},{"verse":24,"text":"Und nun siehe, dies ist der Wille des Herrn, eures Gottes, in Bezug auf seine Heiligen: Sie sollen sich im Land Zion sammeln, nicht in Hast, damit nicht Verwirrung entstehe, wodurch es zu Seuchen kommt."},{"verse":25,"text":"Siehe, das Land Zion: Ich, der Herr, halte es in meinen eigenen Händen;"},{"verse":26,"text":"und doch gebe ich, der Herr, dem Kaiser, was des Kaisers ist."},{"verse":27,"text":"Darum will ich, der Herr, dass ihr das Land kauft, damit ihr den Vorteil der Welt habt, damit ihr in der Welt einen Anspruch habt, damit sie nicht zum Zorn aufgestachelt werde."},{"verse":28,"text":"Denn der Satan gibt es ihnen ins Herz, dass sie zornig auf euch sind und Blut vergießen wollen."},{"verse":29,"text":"Darum wird das Land Zion nicht anders erworben werden als nur durch Ankauf oder durch Blut; andernfalls gibt es kein Erbteil für euch."},{"verse":30,"text":"Und wenn durch Ankauf, siehe, seid ihr gesegnet;"},{"verse":31,"text":"und wenn durch Blut, da es euch verboten ist, Blut zu vergießen, sieh, so sind eure Feinde über euch, und ihr werdet von Stadt zu Stadt und von Synagoge zu Synagoge gegeißelt werden, und nur wenige werden bestehen, um ein Erbteil zu empfangen."},{"verse":32,"text":"Ich, der Herr, bin zornig über die Schlechten, ich halte meinen Geist von den Bewohnern der Erde fern."},{"verse":33,"text":"Ich habe in meinem Grimm geschworen und Kriege auf der Erde beschlossen, und die Schlechten werden die Schlechten töten, und Furcht wird über jeden Menschen kommen;"},{"verse":34,"text":"und auch die Heiligen werden nur mit Mühe entrinnen; doch ich, der Herr, bin mit ihnen und werde im Himmel, aus der Gegenwart meines Vaters, herabkommen und die Schlechten mit unauslöschlichem Feuer verzehren."},{"verse":35,"text":"Und siehe, dies ist noch nicht, aber bald."},{"verse":36,"text":"Darum, in Anbetracht dessen, dass ich, der Herr, dies alles über die Erde beschlossen habe, will ich, dass meine Heiligen sich im Land Zion sammeln"},{"verse":37,"text":"und dass ein jeder Mann Rechtschaffenheit in seine Hände nehme und Glaubenstreue um seine Lenden und für die Bewohner der Erde warnend die Stimme erhebe und durch Wort und auch durch Flucht verkünde, dass Verwüstung über die Schlechten kommen wird."},{"verse":38,"text":"Darum sollen meine Jünger in Kirtland, die auf dieser Farm leben, ihre zeitlichen Angelegenheiten ordnen."},{"verse":39,"text":"Lasst meinen Diener Titus Billings, dem die Sorge dafür obliegt, das Land veräußern, damit er im kommenden Frühjahr bereit sei, seine Reise hinauf zum Land Zion anzutreten, mit denen, die darauf wohnen, ausgenommen diejenigen, die ich mir bewahre, die nicht gehen sollen, bis ich es ihnen gebiete."},{"verse":40,"text":"Und lasst alles Geld, was erübrigt werden kann, und es kommt mir nicht darauf an, ob es wenig ist oder viel, zum Land Zion hinaufsenden, an diejenigen, die ich bestimmt habe zu empfangen."},{"verse":41,"text":"Siehe, ich, der Herr, werde meinem Diener Joseph Smith Jr. Macht geben, dass er fähig ist, mittels des Geistes zu erkennen, wer in das Land Zion hinaufgehen soll und wer von meinen Jüngern verweilen soll."},{"verse":42,"text":"Mein Diener Newel K. Whitney soll seinen Laden oder, mit anderen Worten, den Laden noch eine kurze Zeit lang behalten."},{"verse":43,"text":"Doch soll er alles Geld, was er geben kann, geben, damit es zum Land Zion hinaufgesandt werde."},{"verse":44,"text":"Siehe, dies alles liegt in seinen eigenen Händen, und er soll so handeln, wie es weise ist."},{"verse":45,"text":"Wahrlich, ich sage: Er soll für die Jünger, die verweilen werden, zum Beauftragten ordiniert werden, und er soll zu dieser Macht ordiniert werden"},{"verse":46,"text":"und nun eilends die Gemeinden besuchen und ihnen dies alles mit meinem Diener Oliver Cowdery erläutern. Siehe, dies ist mein Wille, dass Gelder beschafft werden, ja, wie ich es angewiesen habe."},{"verse":47,"text":"Wer glaubenstreu ist und ausharrt, wird die Welt überwinden."},{"verse":48,"text":"Wer Schätze in das Land Zion hinaufsendet, wird ein Erbteil in dieser Welt empfangen, und seine Werke werden ihm nachfolgen, und auch einen Lohn in der künftigen Welt."},{"verse":49,"text":"Ja, und gesegnet sind die Toten, die von nun an im Herrn sterben; denn wenn der Herr kommt und das Alte vergeht und alles neu wird, werden sie von den Toten auferstehen und werden hernach nicht mehr sterben und werden ein Erbteil vor dem Herrn in der heiligen Stadt empfangen."},{"verse":50,"text":"Und wer am Leben ist, wenn der Herr kommt, und den Glauben gehalten hat, der ist gesegnet; doch ist es ihm bestimmt, im Alter eines Menschen zu sterben."},{"verse":51,"text":"Darum werden die Kinder aufwachsen, bis sie alt werden; alte Menschen werden sterben; aber sie werden nicht im Staub schlafen, sondern sie werden in einem Augenblick verwandelt werden."},{"verse":52,"text":"Aus diesem Grund also haben die Apostel der Welt die Auferstehung der Toten gepredigt."},{"verse":53,"text":"Dies alles ist es, wonach ihr ausschauen müsst; und um nach der Weise des Herrn zu reden: Es steht jetzt nahe bevor, ja, in der kommenden Zeit, nämlich an dem Tag, da des Menschen Sohn kommt."},{"verse":54,"text":"Und bis zu jener Stunde wird es törichte Jungfrauen unter den klugen geben; und zu jener Stunde kommt eine völlige Trennung der Rechtschaffenen und der Schlechten; und an jenem Tag werde ich meine Engel aussenden, dass sie die Schlechten ausreißen und sie in unauslöschliches Feuer werfen."},{"verse":55,"text":"Und nun siehe, wahrlich, ich sage euch: Ich, der Herr, habe kein Gefallen an meinem Diener Sidney Rigdon; er hat sich in seinem Herzen erhöht und nicht Rat angenommen, sondern den Geist betrübt;"},{"verse":56,"text":"darum ist sein Schreiben für den Herrn nicht annehmbar, und er soll ein anderes machen; und wenn der Herr es nicht annimmt, siehe, dann steht er nicht länger in dem Amt, wozu ich ihn bestimmt habe."},{"verse":57,"text":"Und weiter, wahrlich, ich sage euch: Wer voll Sanftmut im Herzen den Wunsch hat, die Sünder zu warnen, damit sie umkehren, der soll zu dieser Macht ordiniert werden."},{"verse":58,"text":"Denn dies ist ein Tag des Warnens und nicht ein Tag vieler Worte. Denn ich, der Herr, werde mich in den letzten Tagen nicht verspotten lassen."},{"verse":59,"text":"Siehe, ich bin von oben, und meine Macht liegt unterhalb. Ich bin über allem und in allem und durch alles und erforsche alles, und der Tag kommt, da mir alles untertan sein wird."},{"verse":60,"text":"Siehe, ich bin Alpha und Omega, nämlich Jesus Christus."},{"verse":61,"text":"Darum sollen alle Menschen sich in Acht nehmen, wie sie meinen Namen auf ihre Lippen nehmen –"},{"verse":62,"text":"denn siehe, wahrlich, ich sage: Viele sind es, die unter diesem Schuldspruch stehen, die den Namen des Herrn gebrauchen und ihn missbrauchen, da sie keine Vollmacht haben."},{"verse":63,"text":"Darum soll die Kirche von ihren Sünden umkehren, und ich, der Herr, werde sie als mein Eigen anerkennen; andernfalls werden sie ausgestoßen werden."},{"verse":64,"text":"Denkt daran: Das, was von oben kommt, ist heilig und muss mit Sorgfalt und unter dem Drängen des Geistes gesprochen werden; und darin gibt es keinen Schuldspruch, und den Geist empfangt ihr durch das Gebet; darum, ohne dies bleibt Schuldspruch."},{"verse":65,"text":"Meine Diener Joseph Smith Jr. und Sidney Rigdon sollen sich ein Zuhause suchen, wie sie mittels des Gebets vom Geist belehrt werden."},{"verse":66,"text":"Dies alles bleibt nun, um mit Geduld überwunden zu werden, damit so jemand ein überaus größeres und ewiges Maß an Herrlichkeit empfangen kann, andernfalls einen größeren Schuldspruch. Amen."}]},{"chapter":64,"verses":[{"verse":1,"text":"Siehe, so spricht der Herr, euer Gott, zu euch, o ihr Ältesten meiner Kirche: Horcht auf und vernehmt, und empfangt meinen Willen in Bezug auf euch."},{"verse":2,"text":"Denn wahrlich, ich sage euch: Ich will, dass ihr die Welt überwindet; darum will ich mit euch Mitleid haben."},{"verse":3,"text":"Es gibt welche unter euch, die gesündigt haben; aber wahrlich, ich sage: Dieses eine Mal, um meiner eigenen Herrlichkeit willen und um der Errettung der Seelen willen, habe ich euch eure Sünden vergeben."},{"verse":4,"text":"Ich will barmherzig zu euch sein, denn ich habe euch das Reich gegeben."},{"verse":5,"text":"Und die Schlüssel der Geheimnisse des Reiches werden meinem Diener Joseph Smith Jr. durch die Mittel, die ich bestimmt habe, nicht genommen werden, solange er lebt, wenn er meine Verordnungen beachtet."},{"verse":6,"text":"Es gibt welche, die ohne Grund einen Anlass gegen ihn gesucht haben;"},{"verse":7,"text":"dennoch, er hat gesündigt; aber wahrlich, ich sage euch: Ich, der Herr, vergebe denen die Sünden, die ihre Sünden vor mir bekennen und um Vergebung bitten, sofern sie nicht zum Tode gesündigt haben."},{"verse":8,"text":"Meine Jünger in alten Tagen haben Anlass gegeneinander gesucht und einander in ihrem Herzen nicht vergeben; und wegen dieses Übels sind sie bedrängt und schwer gezüchtigt worden."},{"verse":9,"text":"Darum sage ich euch: Ihr sollt einander vergeben; denn wer seinem Bruder dessen Verfehlungen nicht vergibt, der steht schuldig vor dem Herrn; denn auf ihm verbleibt die größere Sünde."},{"verse":10,"text":"Ich, der Herr, vergebe, wem ich vergeben will, aber von euch wird verlangt, dass ihr allen Menschen vergebt."},{"verse":11,"text":"Und ihr solltet in eurem Herzen sprechen: Lass Gott richten zwischen mir und dir und dir vergelten gemäß deinen Taten."},{"verse":12,"text":"Und wer von seinen Sünden nicht umkehrt und sie nicht bekennt, den sollt ihr vor die Kirche bringen und mit ihm verfahren, wie die Schrift es euch sagt, sei es durch Gebot oder durch Offenbarung."},{"verse":13,"text":"Und das sollt ihr tun, damit Gott verherrlicht werde – nicht, weil ihr nicht vergebt, indem ihr kein Mitleid habt, sondern damit ihr in den Augen des Gesetzes gerechtfertigt seiet, damit ihr den nicht beleidigt, der euer Gesetzgeber ist –,"},{"verse":14,"text":"wahrlich, ich sage: Aus diesem Grund sollt ihr das alles tun."},{"verse":15,"text":"Siehe, ich, der Herr, bin zornig gewesen über Ezra Booth, der mein Diener war, und auch über meinen Diener Isaac Morley, denn sie haben weder das Gesetz noch das Gebot gehalten;"},{"verse":16,"text":"sie haben in ihrem Herzen nach Bösem getrachtet, und ich, der Herr, habe meinen Geist zurückgehalten. Sie haben das, worin nichts Böses war, als böse verurteilt; dennoch habe ich meinem Diener Isaac Morley vergeben."},{"verse":17,"text":"Und auch mein Diener Edward Partridge, siehe, er hat gesündigt, und der Satan trachtet danach, seine Seele zu vernichten; aber wenn ihnen dies alles kundgetan wird und sie von dem, was böse ist, umkehren, wird ihnen vergeben werden."},{"verse":18,"text":"Und nun, wahrlich, ich sage: Es ist mir ratsam, dass mein Diener Sidney Gilbert nach ein paar Wochen wieder zu seinem Geschäft und zu seiner Agentur im Land Zion zurückkehre;"},{"verse":19,"text":"und was er gesehen und vernommen hat, möge meinen Jüngern kundgetan werden, damit sie nicht zugrunde gehen. Und aus diesem Grund habe ich dies alles gesagt."},{"verse":20,"text":"Und weiter, ich sage euch: Damit mein Diener Isaac Morley nicht über das hinaus versucht werde, was er ertragen kann, und zu eurem Schaden falsch berate, habe ich geboten, dass seine Farm verkauft werde."},{"verse":21,"text":"Ich will nicht, dass mein Diener Frederick G. Williams seine Farm verkaufe, denn ich, der Herr, will, dass es im Land Kirtland einen starken Stützpunkt gebe, über den Zeitraum von fünf Jahren hinweg, während dessen ich die Schlechten nicht zu Fall bringen werde, damit ich dadurch einige errette."},{"verse":22,"text":"Und nach jenem Tag werde ich, der Herr, keinen schuldig halten, der mit offenem Herzen in das Land Zion hinaufgeht; denn ich, der Herr, fordere von den Menschenkindern das Herz."},{"verse":23,"text":"Siehe, jetzt, bis des Menschen Sohn kommt, sagt man „heute“; und wahrlich, es ist ein Tag des Opferns und ein Tag, dass mein Volk gezehntet werde; denn wer gezehntet ist, wird bei seinem Kommen nicht verbrannt werden."},{"verse":24,"text":"Denn nach dem „Heute“ kommt das Brennen – dies ist nach der Weise des Herrn geredet –, denn wahrlich, ich sage: Morgen werden alle Stolzen und jene, die Schlechtes tun, wie Stoppeln sein; und ich werde sie verbrennen, denn ich bin der Herr der Heerscharen; und ich werde keinen schonen, der in Babylon verbleibt."},{"verse":25,"text":"Darum, wenn ihr mir glaubt, werdet ihr arbeiten, solange es noch „heute“ heißt."},{"verse":26,"text":"Und es ist nicht recht, dass meine Diener Newel K. Whitney und Sidney Gilbert ihren Laden und ihre Besitztümer hier verkaufen; denn das ist erst dann weise, wenn die übrigen der Kirche, die an diesem Ort verbleiben, zum Land Zion hinaufgehen werden."},{"verse":27,"text":"Siehe, in meinen Gesetzen heißt es, oder ist es verboten, bei deinen Feinden Schulden zu machen;"},{"verse":28,"text":"aber siehe, es heißt zu keiner Zeit, dass der Herr nicht nehmen kann, wenn es ihm gefällt, und bezahlen kann, wie es ihm gut scheint."},{"verse":29,"text":"Da ihr also Beauftragte seid, handelt ihr im Auftrag des Herrn; und alles, was ihr gemäß dem Willen des Herrn tut, ist des Herrn Angelegenheit."},{"verse":30,"text":"Und er hat euch gesetzt, damit ihr in diesen letzten Tagen für seine Heiligen sorgt, damit sie im Land Zion ein Erbteil erlangen."},{"verse":31,"text":"Und siehe, ich, der Herr, verkünde euch, und meine Worte sind sicher und werden nicht fehlgehen, dass sie es erlangen werden."},{"verse":32,"text":"Aber alles muss zu seiner Zeit geschehen."},{"verse":33,"text":"Darum werdet nicht müde, Gutes zu tun, denn ihr legt die Grundlage für ein großes Werk. Und aus etwas Kleinem geht das Große hervor."},{"verse":34,"text":"Siehe, der Herr fordert das Herz und einen willigen Sinn; und die Willigen und Gehorsamen werden in diesen letzten Tagen das Gute aus dem Land Zion essen."},{"verse":35,"text":"Und die Widersetzlichen werden aus dem Land Zion ausgeschlossen werden und werden weggeschickt werden und werden das Land nicht ererben."},{"verse":36,"text":"Denn wahrlich, ich sage: Die Widersetzlichen sind nicht vom Blut Efraims, darum werden sie ausgerissen werden."},{"verse":37,"text":"Siehe, ich, der Herr, habe meine Kirche in diesen letzten Tagen gleichsam zu einem Richter gemacht, der auf einem Hügel sitzt, oder an einem hohen Ort, um die Nationen zu richten."},{"verse":38,"text":"Denn es wird sich begeben: Die Einwohner Zions werden in allem, was Zion betrifft, Richter sein."},{"verse":39,"text":"Und Lügner und Heuchler werden durch sie festgestellt werden, und diejenigen, die keine Apostel und Propheten sind, werden erkannt werden."},{"verse":40,"text":"Und auch der Bischof, der ein Richter ist, und seine Ratgeber sollen, wenn sie in ihrer Treuhandschaft nicht treu sind, schuldig gesprochen werden, und andere werden an ihre Stelle gesetzt werden."},{"verse":41,"text":"Denn siehe, ich sage euch: Zion wird erblühen, und die Herrlichkeit des Herrn wird darauf ruhen;"},{"verse":42,"text":"und Zion wird ein Panier für die Völker sein, und aus jeder Nation unter dem Himmel werden welche zu ihm kommen."},{"verse":43,"text":"Und der Tag wird kommen, da die Nationen der Erde vor ihm zittern werden, und vor seinen Schrecklichen werden sie sich fürchten. Der Herr hat es gesprochen. Amen."}]},{"chapter":65,"verses":[{"verse":1,"text":"Horcht auf und seht, eine Stimme wie von einem, der aus der Höhe niedergesandt ist, der mächtig und kraftvoll ist, der bis an die Enden der Erde schreitet, ja, dessen Stimme an die Menschen ergeht: Bereitet den Weg des Herrn, macht seine Pfade gerade."},{"verse":2,"text":"Die Schlüssel des Reiches Gottes sind dem Menschen auf Erden überantwortet, und von da an wird das Evangelium bis an die Enden der Erde hinrollen; gleichwie der Stein, der sich ohne das Zutun von Händen vom Berg löst, dahinrollen wird, bis er die ganze Erde erfüllt hat."},{"verse":3,"text":"Ja, eine Stimme, die ruft: Bereitet den Weg des Herrn, bereitet das Abendmahl des Lammes, macht euch für den Bräutigam bereit."},{"verse":4,"text":"Betet zum Herrn, ruft seinen heiligen Namen an, tut seine wunderbaren Werke unter den Völkern kund."},{"verse":5,"text":"Ruft den Herrn an, damit sein Reich auf der Erde vorwärtsschreite, damit ihre Bewohner es empfangen mögen und bereit seien für die kommenden Tage, in denen des Menschen Sohn im Himmel herabkommen wird, angetan mit dem hellen Glanz seiner Herrlichkeit, um dem Reich Gottes zu begegnen, das auf Erden errichtet ist."},{"verse":6,"text":"Darum möge das Reich Gottes vorwärtsschreiten, damit das Himmelreich kommen kann, damit du, o Gott, im Himmel wie auch auf Erden verherrlicht werdest, damit deine Feinde bezwungen werden mögen; denn dein ist die Ehre, Macht und Herrlichkeit für immer und immer. Amen."}]},{"chapter":66,"verses":[{"verse":1,"text":"Siehe, so spricht der Herr zu meinem Diener William E. McLellin: Gesegnet bist du, insoweit du dich von deinen Übeltaten abgewendet hast und meine Wahrheiten empfangen hast, spricht der Herr, dein Erlöser, der Erretter der Welt, ja, all derer, die an meinen Namen glauben."},{"verse":2,"text":"Wahrlich, ich sage dir: Gesegnet bist du, da du meinen immerwährenden Bund angenommen hast, ja, die Fülle meines Evangeliums, ausgesandt unter die Menschenkinder, damit sie Leben haben und zu Teilhabern der Herrlichkeiten werden können, die in den letzten Tagen offenbart werden sollen, wie es die Propheten und Apostel in alten Tagen geschrieben haben."},{"verse":3,"text":"Wahrlich, ich sage dir, mein Diener William: Du bist rein, aber nicht ganz; darum kehre um von dem, was in meinen Augen nicht angenehm ist, spricht der Herr, denn der Herr wird es dir zeigen."},{"verse":4,"text":"Und nun, wahrlich, ich, der Herr, werde dir zeigen, was ich in Bezug auf dich will oder was mein Wille in Bezug auf dich ist."},{"verse":5,"text":"Siehe, wahrlich, ich sage dir: Es ist mein Wille, dass du mein Evangelium von Land zu Land und von Stadt zu Stadt verkündigst, ja, in jenen Gebieten ringsum, wo es noch nicht verkündigt worden ist."},{"verse":6,"text":"Verweile nicht viele Tage an diesem Ort; gehe noch nicht in das Land Zion hinauf; aber insoweit du etwas senden kannst, sende es; ansonsten denke nicht an dein Eigentum."},{"verse":7,"text":"Gehe in die östlichen Länder, gib Zeugnis an allen Orten, vor allen Menschen, und in ihren Synagogen, und lege den Menschen die Gründe dar."},{"verse":8,"text":"Lass meinen Diener Samuel H. Smith mit dir gehen, und verlass ihn nicht, und gib ihm deine Anweisungen; und wer treu ist, wird an jedem Ort stark gemacht werden; und ich, der Herr, werde mit dir gehen."},{"verse":9,"text":"Lege den Kranken deine Hände auf, und sie werden gesund werden. Kehre nicht zurück, bis ich, der Herr, dich sende. Sei geduldig in Bedrängnis. Bitte, und du wirst empfangen; klopfe an, und es wird dir aufgetan werden."},{"verse":10,"text":"Trachte danach, dass dich nichts belaste. Lass ab von allem Unrecht. Begehe nicht Ehebruch – eine Versuchung, die dich beunruhigt hat."},{"verse":11,"text":"Halte diese Worte, denn sie sind wahr und treu; und du sollst dein Amt groß machen und viele Menschen nach Zion treiben, mit Liedern immerwährender Freude auf ihrem Haupt."},{"verse":12,"text":"Fahre in all diesem fort, ja, bis ans Ende, dann wirst du eine Krone ewigen Lebens haben zur rechten Hand meines Vaters, der voller Gnade und Wahrheit ist."},{"verse":13,"text":"Wahrlich, so spricht der Herr, dein Gott, dein Erlöser, ja, Jesus Christus. Amen."}]},{"chapter":67,"verses":[{"verse":1,"text":"Seht und horcht auf, o ihr Ältesten meiner Kirche, die ihr euch versammelt habt, deren Gebete ich vernommen habe und deren Herz ich kenne und deren Wünsche vor mich heraufgekommen sind."},{"verse":2,"text":"Siehe, ja siehe, meine Augen ruhen auf euch, und die Himmel und die Erde sind in meinen Händen, und die Reichtümer der Ewigkeit sind mein, dass ich sie gebe."},{"verse":3,"text":"Ihr wart bestrebt zu glauben, ihr würdet die Segnung empfangen, die euch dargeboten wurde; aber siehe, wahrlich, ich sage euch: Ihr hattet Furcht in eurem Herzen, und wahrlich, das ist der Grund, warum ihr nicht empfangen habt."},{"verse":4,"text":"Und nun gebe ich, der Herr, euch Zeugnis, dass diese Gebote, die euch vorliegen, wahr sind."},{"verse":5,"text":"Eure Augen haben auf meinem Diener Joseph Smith Jr. geruht, und seine Sprache kennt ihr, und seine Unvollkommenheiten kennt ihr; und ihr habt in eurem Herzen nach Wissen getrachtet, um euch über seine Sprache hinaus ausdrücken zu können; das wisst ihr auch."},{"verse":6,"text":"Nun, sucht euch aus dem Buch der Gebote auch nur das Geringste aus, was darin ist, und bestimmt denjenigen, der der Klügste unter euch ist;"},{"verse":7,"text":"oder, wenn es unter euch irgendeinen gibt, der eines dem gleich machen kann, dann dürft ihr zu Recht sagen, ihr wisst nicht, dass sie wahr sind;"},{"verse":8,"text":"aber wenn ihr keines dem gleich machen könnt, dann steht ihr unter Schuldigsprechung, wenn ihr nicht Zeugnis gebt, dass sie wahr sind."},{"verse":9,"text":"Denn ihr wisst, dass es kein Unrecht in ihnen gibt, und das, was rechtschaffen ist, kommt von oben herab, vom Vater der Lichter."},{"verse":10,"text":"Und weiter, wahrlich, ich sage euch: Es ist euer Vorzug, und eine Verheißung gebe ich euch, die ihr zu diesem geistlichen Dienst ordiniert worden seid: Insoweit ihr eure Eifersucht und Furcht ablegt und euch vor mir demütigt, denn ihr seid nicht demütig genug, wird der Schleier zerrissen werden, und ihr werdet mich sehen und wissen, dass ich bin – nicht mit dem fleischlichen oder natürlichen Sinn, sondern mit dem geistigen."},{"verse":11,"text":"Denn kein Mensch hat je im Fleische Gott gesehen, außer er war durch den Geist Gottes belebt."},{"verse":12,"text":"So kann auch kein natürlicher Mensch die Gegenwart Gottes aushalten, auch nicht gemäß dem fleischlichen Sinn."},{"verse":13,"text":"Ihr seid jetzt nicht imstande, die Gegenwart Gottes auszuhalten, auch nicht den Dienst von Engeln; darum fahrt fort in Geduld, bis ihr vollkommen geworden seid."},{"verse":14,"text":"Lasst euren Sinn sich nicht zurückwenden; und wenn ihr würdig seid, dann werdet ihr zu der von mir selbst bestimmten Zeit das sehen und wissen, was euch durch die Hände meines Dieners Joseph Smith Jr. übertragen worden ist. Amen."}]},{"chapter":68,"verses":[{"verse":1,"text":"Mein Diener Orson Hyde wurde mit seiner Ordinierung berufen, das immerwährende Evangelium durch den Geist des lebendigen Gottes zu verkündigen, von Volk zu Volk und von Land zu Land, in den Zusammenkünften der Schlechten, in ihren Synagogen, und ihnen die Gründe darzulegen und alle Schriften zu erläutern."},{"verse":2,"text":"Und siehe, ja siehe, dies ist ein Beispiel für alle, die zu diesem Priestertum ordiniert worden sind, denen es als Mission bestimmt worden ist hinauszugehen –"},{"verse":3,"text":"und dies ist für sie das Beispiel: Sie sollen reden, wie sie vom Heiligen Geist dazu bewogen werden."},{"verse":4,"text":"Und was auch immer sie reden werden, wenn der Heilige Geist sie berührt, wird heilige Schrift sein, wird der Wille des Herrn sein, wird der Sinn des Herrn sein, wird das Wort des Herrn sein, wird die Stimme des Herrn sein und die Macht Gottes zur Errettung."},{"verse":5,"text":"Siehe, dies ist die Verheißung des Herrn an euch, o ihr meine Diener."},{"verse":6,"text":"Darum seid guten Mutes und fürchtet euch nicht, denn ich, der Herr, bin mit euch und werde euch beistehen; und ihr sollt für mich, ja, Jesus Christus, Zeugnis geben, dass ich der Sohn des lebendigen Gottes bin, dass ich war, dass ich bin und dass ich kommen werde."},{"verse":7,"text":"Dies ist das Wort des Herrn an dich, mein Diener Orson Hyde, und auch an meinen Diener Luke Johnson und an meinen Diener Lyman Johnson und an meinen Diener William E. McLellin und an alle treuen Ältesten meiner Kirche:"},{"verse":8,"text":"Geht hin in alle Welt, predigt das Evangelium jedem Geschöpf, handelt in der Vollmacht, die ich euch gegeben habe, und tauft im Namen des Vaters und des Sohnes und des Heiligen Geistes."},{"verse":9,"text":"Und wer da glaubt und sich taufen lässt, der wird errettet werden, und wer nicht glaubt, der wird verdammt werden."},{"verse":10,"text":"Und wer da glaubt, der wird mit Zeichen, die ihm folgen, gesegnet werden, ja, wie es geschrieben steht."},{"verse":11,"text":"Und euch wird es gegeben sein, die Zeichen der Zeiten und die Zeichen vom Kommen des Menschensohnes zu erkennen;"},{"verse":12,"text":"und für alle, für die der Vater Zeugnis gibt, wird euch die Macht gegeben werden, sie für das ewige Leben zu versiegeln. Amen."},{"verse":13,"text":"Und nun, was die Punkte betrifft, die zu den Bündnissen und Geboten hinzukommen, so sind es folgende:"},{"verse":14,"text":"Es gibt später noch, zu der vom Herrn bestimmten Zeit, weitere Bischöfe, die für die Kirche eingesetzt werden sollen, um zu dienen, so wie der erste;"},{"verse":15,"text":"darum sollen sie Hohe Priester sein, die würdig sind, und sie sollen von der Ersten Präsidentschaft des Melchisedekischen Priestertums bestimmt werden, außer es sind buchstäbliche Abkömmlinge Aarons."},{"verse":16,"text":"Und wenn es buchstäbliche Abkömmlinge Aarons sind, so haben sie ein gesetzliches Recht auf das Bischofsamt, sofern sie die Erstgeborenen unter den Söhnen Aarons sind;"},{"verse":17,"text":"denn der Erstgeborene hat das Recht der Präsidentschaft über dieses Priestertum inne, ebenso die Schlüssel oder die Vollmacht desselben."},{"verse":18,"text":"Niemand hat ein gesetzliches Recht auf dieses Amt, die Schlüssel dieses Priestertums innezuhaben, außer er sei ein buchstäblicher Abkömmling und der Erstgeborene Aarons."},{"verse":19,"text":"Aber da ein Hoher Priester des Melchisedekischen Priestertums die Vollmacht hat, in allen geringeren Ämtern zu amtieren, darf er im Amt des Bischofs amtieren, wenn kein buchstäblicher Abkömmling Aarons gefunden werden kann; Voraussetzung ist, dass er berufen und unter den Händen der Ersten Präsidentschaft des Melchisedekischen Priestertums zu dieser Macht eingesetzt und ordiniert wird."},{"verse":20,"text":"Und auch ein buchstäblicher Abkömmling Aarons muss von dieser Präsidentschaft als solcher bestimmt und für würdig befunden und gesalbt und unter den Händen dieser Präsidentschaft ordiniert werden, andernfalls sind sie nicht gesetzlich bevollmächtigt, in ihrem Priestertum zu amtieren."},{"verse":21,"text":"Aber kraft ihres festgelegten Rechts auf das Priestertum, das vom Vater auf den Sohn übergeht, können sie ihre Salbung jederzeit verlangen, sofern sie ihre Abstammung darlegen können oder sie mittels Offenbarung vom Herrn unter den Händen der oben genannten Präsidentschaft nachweisen."},{"verse":22,"text":"Und weiter: Gegen keinen Bischof oder Hohen Priester, der für diesen geistlichen Dienst eingesetzt worden ist, soll wegen eines Verbrechens vorgegangen oder dieser schuldig gesprochen werden, es sei denn vor der Ersten Präsidentschaft der Kirche;"},{"verse":23,"text":"und insoweit er vor dieser Präsidentschaft für schuldig befunden wird, aufgrund von unanfechtbarem Zeugnis, soll er schuldig gesprochen werden;"},{"verse":24,"text":"und wenn er umkehrt, soll ihm vergeben werden, gemäß den Bündnissen und Geboten der Kirche."},{"verse":25,"text":"Und weiter: Wenn Eltern in Zion oder einem seiner organisierten Pfähle Kinder haben und sie nicht lehren, die Lehre von der Umkehr, vom Glauben an Christus, den Sohn des lebendigen Gottes, und von der Taufe und der Gabe des Heiligen Geistes durch Händeauflegen zu verstehen, wenn sie acht Jahre alt sind, so sei die Sünde auf dem Haupt der Eltern."},{"verse":26,"text":"Denn dies soll für die Einwohner Zions und in einem jeden seiner organisierten Pfähle ein Gesetz sein."},{"verse":27,"text":"Und ihre Kinder sollen, wenn sie acht Jahre alt sind, zur Vergebung ihrer Sünden getauft werden und das Auflegen der Hände empfangen."},{"verse":28,"text":"Und sie sollen ihre Kinder auch lehren, zu beten und untadelig vor dem Herrn zu wandeln."},{"verse":29,"text":"Und die Einwohner Zions sollen auch den Sabbattag beachten, dass sie ihn heilighalten."},{"verse":30,"text":"Und die Einwohner Zions sollen auch voller Glaubenstreue an ihre Arbeit denken, in dem Maße, wie es ihnen bestimmt ist zu arbeiten; denn der Müßiggänger wird vor dem Herrn in Erinnerung gebracht werden."},{"verse":31,"text":"Nun habe ich, der Herr, an den Einwohnern Zions kein Wohlgefallen, denn es gibt Müßiggänger unter ihnen; und ihre Kinder wachsen auch in Schlechtigkeit auf; sie trachten auch nicht ernsthaft nach den Reichtümern der Ewigkeit, sondern ihre Augen sind voller Habgier."},{"verse":32,"text":"Dies alles soll nicht sein und muss aus ihrer Mitte hinweggetan werden; darum soll mein Diener Oliver Cowdery diese Worte zum Land Zion tragen."},{"verse":33,"text":"Und ein Gebot gebe ich ihnen: Wer nicht zur rechten Zeit auf seine Gebete vor dem Herrn bedacht ist, soll vor dem Richter meines Volkes in Erinnerung gebracht werden."},{"verse":34,"text":"Diese Worte sind wahr und treu; darum übertretet sie nicht, und nehmt auch nichts davon weg."},{"verse":35,"text":"Siehe, ich bin Alpha und Omega, und ich komme schnell. Amen."}]},{"chapter":69,"verses":[{"verse":1,"text":"Hört auf mich, spricht der Herr, euer Gott, meines Dieners Oliver Cowdery wegen. Es ist nicht nach meiner Weisheit, dass ihm die Gebote und die Gelder, die er in das Land Zion bringen soll, anvertraut werden, wenn nicht jemand mit ihm geht, der wahr und treu ist."},{"verse":2,"text":"Darum will ich, der Herr, dass mein Diener John Whitmer mit meinem Diener Oliver Cowdery gehe;"},{"verse":3,"text":"und auch, dass er weiterhin schreibe und alles zu einer Geschichte zusammenfasse, was wichtig ist, was er in Bezug auf meine Kirche beobachtet und weiß;"},{"verse":4,"text":"und auch, dass er von meinem Diener Oliver Cowdery und anderen Rat und Beistand empfange."},{"verse":5,"text":"Und auch meine Diener, die überall auf der Erde sind, sollen die Berichte über ihre Treuhandschaft zum Land Zion hinsenden;"},{"verse":6,"text":"denn das Land Zion soll der Sitz und der Ort sein, wo man dies alles empfängt und erledigt."},{"verse":7,"text":"Doch soll mein Diener John Whitmer viele Male von Ort zu Ort reisen und von Gemeinde zu Gemeinde, damit er sich dadurch leichter Kenntnis verschaffe;"},{"verse":8,"text":"er soll predigen und erläutern, schreiben, abschreiben, auswählen und alles erlangen, was zum Nutzen der Kirche und der heranwachsenden Generationen sein wird, die im Land Zion aufwachsen werden, um es von Generation zu Generation zu besitzen, für immer und immer. Amen."}]},{"chapter":70,"verses":[{"verse":1,"text":"Seht und horcht auf, o ihr Einwohner Zions und all ihr Volk meiner Kirche, die ihr ferne seid, und vernehmt das Wort des Herrn, das ich meinem Diener Joseph Smith Jr. und auch meinem Diener Martin Harris und auch meinem Diener Oliver Cowdery und auch meinem Diener John Whitmer und auch meinem Diener Sidney Rigdon und auch meinem Diener William W. Phelps gebe, in der Form eines Gebotes an sie."},{"verse":2,"text":"Denn ich gebe ihnen ein Gebot; darum horcht auf und vernehmt, denn so spricht der Herr zu ihnen:"},{"verse":3,"text":"Ich, der Herr, habe sie bestimmt und sie zu Treuhändern der Offenbarungen und Gebote ordiniert, die ich ihnen gegeben habe und die ich ihnen später noch geben werde;"},{"verse":4,"text":"und Rechenschaft über diese Treuhandschaft werde ich von ihnen am Tag des Gerichts fordern."},{"verse":5,"text":"Darum habe ich ihnen bestimmt, und dies ist ihre Aufgabe in der Kirche Gottes, diese zu verwalten und alles, was damit zusammenhängt, ja, die Erträge davon."},{"verse":6,"text":"Darum gebe ich ihnen das Gebot, diese weder der Kirche noch der Welt zu geben;"},{"verse":7,"text":"doch insoweit sie mehr empfangen, als für ihre Bedürfnisse und ihre Erfordernisse benötigt wird, soll es meinem Vorratshaus übergeben werden;"},{"verse":8,"text":"und die Erträge sollen den Einwohnern Zions und ihren Generationen geweiht werden, insoweit sie gemäß den Gesetzen des Reiches Erben werden."},{"verse":9,"text":"Siehe, dies verlangt der Herr von einem jeden in seiner Treuhandschaft, ja, wie ich, der Herr, einem jeden bestimmt habe oder später noch bestimmen werde."},{"verse":10,"text":"Und siehe, niemand, der der Kirche des lebendigen Gottes angehört, ist von diesem Gesetz ausgenommen,"},{"verse":11,"text":"ja, weder der Bischof noch der Beauftragte, der das Vorratshaus des Herrn führt, noch derjenige, der zu einer Treuhandschaft in zeitlichen Belangen bestimmt ist."},{"verse":12,"text":"Wer bestimmt ist, in geistlichen Belangen zu wirken, der ist seines Lohnes wert, ja, wie diejenigen, die bestimmt sind, in einer Treuhandschaft in zeitlichen Belangen zu wirken,"},{"verse":13,"text":"ja, sogar noch reichlicher, und dieses reichliche Maß wird ihnen durch die Kundgebungen des Geistes vervielfacht."},{"verse":14,"text":"Doch in euren zeitlichen Belangen sollt ihr gleich sein, und dies nicht widerstrebend, sonst wird das reichliche Maß der Kundgebungen des Geistes vorenthalten werden."},{"verse":15,"text":"Dieses Gebot nun gebe ich meinen Dienern zu ihrem Nutzen, solange sie verbleiben, als Kundgebung meiner Segnungen auf ihr Haupt und als Lohn für ihren Eifer und zu ihrer Sicherheit,"},{"verse":16,"text":"für Nahrung und für Kleidung, für ein Erbteil, für Häuser und für Land, in was für eine Lage auch immer ich, der Herr, sie bringen werde und wohin auch immer ich, der Herr, sie senden werde."},{"verse":17,"text":"Denn sie sind über vielem treu gewesen und haben wohlgetan, insoweit sie nicht gesündigt haben."},{"verse":18,"text":"Siehe, ich, der Herr, bin barmherzig und werde sie segnen, und sie werden in die Freude all dessen eingehen. So ist es. Amen."}]},{"chapter":71,"verses":[{"verse":1,"text":"Siehe, so spricht der Herr zu euch, meine Diener Joseph Smith Jr. und Sidney Rigdon: Die Zeit ist wahrhaft gekommen, da es mir notwendig und ratsam ist, dass ihr euren Mund auftut und mein Evangelium verkündigt, das, was zum Reich gehört, und dessen Geheimnisse aus den Schriften erläutert, gemäß dem Maß an Geist und Macht, das euch gegeben werden wird, so wie ich es will."},{"verse":2,"text":"Wahrlich, ich sage euch: Verkündigt der Welt in den Gebieten ringsum und auch in der Kirche, eine Zeit lang, ja, so lange, bis es euch kundgetan werden wird."},{"verse":3,"text":"Wahrlich, dies ist für eine Zeit lang eine Mission, die ich euch gebe."},{"verse":4,"text":"Darum arbeitet in meinem Weingarten. Ruft den Bewohnern der Erde zu und gebt Zeugnis, und bereitet den Weg für die Gebote und Offenbarungen, die noch kommen werden."},{"verse":5,"text":"Nun siehe, dies ist Weisheit: Wer da liest, der möge verstehen und auch empfangen;"},{"verse":6,"text":"denn dem, der empfängt, wird reichlicher gegeben werden, nämlich Macht."},{"verse":7,"text":"Darum macht eure Feinde zuschanden; ruft sie auf, euch sowohl öffentlich als auch allein gegenüberzutreten; und insoweit ihr treu seid, wird ihre Schande kundgetan werden."},{"verse":8,"text":"Darum lasst sie ihre starken Gründe gegen den Herrn vorbringen."},{"verse":9,"text":"Wahrlich, so spricht der Herr zu euch: Keiner Waffe, die gegen euch geformt ist, wird etwas gelingen;"},{"verse":10,"text":"und wenn jemand seine Stimme gegen euch erhebt, so wird er zu der von mir selbst bestimmten Zeit zuschanden werden."},{"verse":11,"text":"Darum haltet meine Gebote; sie sind wahr und treu. So ist es. Amen."}]},{"chapter":72,"verses":[{"verse":1,"text":"Horcht auf und hört auf die Stimme des Herrn, o ihr, die ihr euch versammelt habt, die ihr die Hohen Priester meiner Kirche seid, ihr, denen das Reich und die Macht gegeben worden sind."},{"verse":2,"text":"Denn wahrlich, so spricht der Herr: Es ist mir ratsam, dass für euch ein Bischof bestimmt werde oder von euch, für die Kirche in diesem Teil des Weingartens des Herrn."},{"verse":3,"text":"Und wahrlich, darin habt ihr weise gehandelt, denn der Herr verlangt von der Hand jedes Treuhänders, dass er Rechenschaft über seine Treuhandschaft ablege, sowohl in der Zeit als auch in der Ewigkeit."},{"verse":4,"text":"Denn wer in der Zeit treu und weise ist, der wird als würdig erachtet, die Wohnungen zu ererben, die mein Vater für ihn bereitet hat."},{"verse":5,"text":"Wahrlich, ich sage euch: Die Ältesten der Kirche in diesem Teil meines Weingartens sollen dem Bischof, den ich für diesen Teil meines Weingartens bestimmen werde, Rechenschaft über ihre Treuhandschaft ablegen."},{"verse":6,"text":"Darüber soll ein Bericht geführt werden, und dieser ist dem Bischof in Zion zu übergeben."},{"verse":7,"text":"Und die Pflicht des Bischofs soll durch die Gebote, die gegeben worden sind, sowie durch die Stimme der Konferenz kundgetan werden."},{"verse":8,"text":"Und nun, wahrlich, ich sage euch: Mein Diener Newel K. Whitney ist der Mann, der bestimmt und zu dieser Macht ordiniert werden soll. Dies ist der Wille des Herrn, eures Gottes, eures Erlösers. So ist es. Amen."},{"verse":9,"text":"Das Wort des Herrn, zusätzlich zu dem Gesetz, das gegeben worden ist, wodurch die Pflicht des Bischofs kundgetan wird, der für die Kirche in diesem Teil des Weingartens ordiniert worden ist, nämlich:"},{"verse":10,"text":"Das Vorratshaus des Herrn zu verwalten; die Gelder der Kirche in diesem Teil des Weingartens zu empfangen;"},{"verse":11,"text":"sich von den Ältesten Rechenschaft geben zu lassen, wie zuvor geboten worden ist, und sich ihrer Bedürfnisse anzunehmen, die für das, was sie empfangen, bezahlen sollen, soweit sie etwas haben, womit sie bezahlen können;"},{"verse":12,"text":"damit dies auch dem Nutzen der Kirche, den Armen und Bedürftigen, geweiht werden möge."},{"verse":13,"text":"Und für den, der nichts hat, womit er bezahlen kann, soll ein Bericht angefertigt und dem Bischof in Zion übergeben werden, der die Schuld aus dem bezahlen soll, was der Herr ihm in die Hände legt."},{"verse":14,"text":"Und die Arbeit der Glaubenstreuen, die in geistlichen Belangen tätig sind, die für die Kirche und für die Welt im Evangelium und dem, was zum Reich gehört, wirken, soll dem Bischof in Zion für die Schuld Genüge leisten;"},{"verse":15,"text":"somit kommt es von der Kirche, denn gemäß dem Gesetz muss jeder, der nach Zion heraufkommt, alles vor den Bischof in Zion legen."},{"verse":16,"text":"Und nun, wahrlich, ich sage euch: Da jeder Älteste in diesem Teil des Weingartens dem Bischof in diesem Teil des Weingartens Rechenschaft über seine Treuhandschaft geben muss,"},{"verse":17,"text":"soll eine Bescheinigung vom Richter oder Bischof in diesem Teil des Weingartens an den Bischof in Zion einen jeden als annehmbar erweisen und in allem genügen für ein Erbteil und um als ein weiser Treuhänder und als ein treuer Arbeiter empfangen zu werden;"},{"verse":18,"text":"andernfalls soll er vom Bischof von Zion nicht angenommen werden."},{"verse":19,"text":"Und nun, wahrlich, ich sage euch: Jeder Älteste, der dem Bischof der Kirche in diesem Teil des Weingartens Rechenschaft geben wird, soll von der Gemeinde oder den Gemeinden, wo er arbeitet, empfohlen werden, damit er sich und seine Berichte als völlig in Ordnung befunden erweisen kann."},{"verse":20,"text":"Und weiter: Meine Diener, die als Treuhänder der literarischen Belange meiner Kirche bestimmt worden sind, sollen in allem einen Anspruch auf den Beistand des Bischofs oder der Bischöfe haben,"},{"verse":21,"text":"damit die Offenbarungen veröffentlicht werden und an die Enden der Erde hinausgehen können; damit sie auch Gelder erlangen können, die der Kirche in allem nutzen sollen;"},{"verse":22,"text":"damit auch sie sich als völlig in Ordnung befunden erweisen und als weise Treuhänder erachtet werden können."},{"verse":23,"text":"Und nun, siehe, dies soll ein Beispiel sein für alle weit verteilten Zweige meiner Kirche, in welchem Land sie auch immer errichtet werden mögen. Und nun komme ich mit meinen Worten zu Ende. Amen."},{"verse":24,"text":"Noch einige zusätzliche Worte zu den Gesetzen des Reiches, die Mitglieder der Kirche betreffend – diejenigen, die vom Heiligen Geist bestimmt sind, nach Zion hinaufzugehen, und diejenigen, die den Vorzug genießen, nach Zion hinaufgehen zu können:"},{"verse":25,"text":"Sie sollen dem Bischof eine Bescheinigung von drei Ältesten der Kirche oder eine Bescheinigung vom Bischof bringen;"},{"verse":26,"text":"andernfalls soll derjenige, der in das Land Zion hinaufgeht, nicht als ein weiser Treuhänder erachtet werden. Dies ist ebenfalls ein Beispiel. Amen."}]},{"chapter":73,"verses":[{"verse":1,"text":"Denn wahrlich, so spricht der Herr: Es ist mir ratsam, dass sie bis zur Konferenz fortfahren, das Evangelium zu predigen und die Gemeinden in den Gebieten ringsum zu ermahnen;"},{"verse":2,"text":"und dann, siehe, wird ihnen durch die Stimme der Konferenz ihre jeweilige Mission kundgetan werden."},{"verse":3,"text":"Nun, wahrlich, ich sage euch, meine Diener Joseph Smith Jr. und Sidney Rigdon, spricht der Herr, es ist ratsam, wieder zu übersetzen;"},{"verse":4,"text":"und insoweit es möglich ist, bis zur Konferenz in den Gebieten ringsum zu predigen; und danach ist es ratsam, mit der Übersetzungsarbeit fortzufahren, bis sie beendet ist."},{"verse":5,"text":"Und lasst dies für die Ältesten ein Muster sein, bis Weiteres kundgetan wird, ja, wie es geschrieben steht."},{"verse":6,"text":"Nun gebe ich euch zu dieser Zeit nichts mehr. Gürtet euch die Lenden und seid ernsthaft. So ist es. Amen."}]},{"chapter":74,"verses":[{"verse":1,"text":"Denn der ungläubige Mann ist geheiligt durch die Frau, und die ungläubige Frau ist geheiligt durch den Mann. Sonst wären eure Kinder unrein; nun aber sind sie heilig."},{"verse":2,"text":"Nun, in den Tagen der Apostel galt unter allen Juden, die nicht an das Evangelium Jesu Christi glaubten, das Gesetz der Beschneidung."},{"verse":3,"text":"Und es begab sich: Es erhob sich unter dem Volk ein großer Streit über das Gesetz der Beschneidung, denn der ungläubige Mann hatte den Wunsch, seine Kinder mögen beschnitten und dem Gesetz des Mose unterstellt werden, aber dieses Gesetz war schon erfüllt."},{"verse":4,"text":"Und es begab sich: Die Kinder, die unter dem Gesetz des Mose erzogen wurden, schenkten den Überlieferungen ihrer Väter Beachtung und glaubten nicht an das Evangelium Christi; dadurch wurden sie unheilig."},{"verse":5,"text":"Aus diesem Grund also schrieb der Apostel an die Gemeinde und gab ihr das Gebot, nicht vom Herrn, sondern von sich aus, dass der Gläubige sich nicht mit einem Ungläubigen vereinigen sollte, außer das Gesetz des Mose würde unter ihnen abgeschafft,"},{"verse":6,"text":"damit ihre Kinder ohne Beschneidung blieben und damit die Überlieferung abgeschafft würde, die da sagt, kleine Kinder seien unheilig; denn das galt unter den Juden;"},{"verse":7,"text":"aber kleine Kinder sind heilig, heilig gemacht durch das Sühnopfer Jesu Christi; und dies ist es, was die Schriften besagen."}]},{"chapter":75,"verses":[{"verse":1,"text":"Wahrlich, wahrlich, ich sage euch, ich, ja, der ich durch die Stimme meines Geistes spreche, ja, Alpha und Omega, euer Herr und euer Gott:"},{"verse":2,"text":"Horcht auf, o ihr, die ihr euren Namen genannt habt, dass ihr hingehen und mein Evangelium verkündigen und meinen Weingarten beschneiden wollt."},{"verse":3,"text":"Siehe, ich sage euch: Es ist mein Wille, dass ihr hingeht und nicht zaudert, auch nicht müßig seid, sondern mit all eurer Macht arbeitet"},{"verse":4,"text":"und eure Stimme erhebt wie mit dem Ton einer Posaune und die Wahrheit gemäß den Offenbarungen und Geboten verkündigt, die ich euch gegeben habe."},{"verse":5,"text":"Und so, wenn ihr treu seid, werdet ihr mit vielen Garben beladen sein und mit Ehre und Herrlichkeit und Unsterblichkeit und ewigem Leben gekrönt werden."},{"verse":6,"text":"Darum, wahrlich, sage ich zu meinem Diener William E. McLellin: Ich widerrufe den Auftrag, den ich ihm gegeben habe, in die östlichen Länder zu gehen;"},{"verse":7,"text":"und ich gebe ihm einen neuen Auftrag und ein neues Gebot, womit ich, der Herr, ihn züchtige, weil er in seinem Herzen gemurrt hat;"},{"verse":8,"text":"und er hat gesündigt; doch ich vergebe ihm und sage weiter zu ihm: Gehe in die Länder im Süden."},{"verse":9,"text":"Und mein Diener Luke Johnson soll mit ihm gehen, und sie sollen das verkündigen, was ich ihnen geboten habe –"},{"verse":10,"text":"und den Namen des Herrn anrufen um den Tröster, der sie alles lehren wird, was für sie ratsam ist,"},{"verse":11,"text":"und immer beten, dass sie nicht ermatten; und insoweit sie dies tun, werde ich mit ihnen sein, ja, bis ans Ende."},{"verse":12,"text":"Siehe, dies ist der Wille des Herrn, eures Gottes, in Bezug auf euch. So ist es. Amen."},{"verse":13,"text":"Und weiter, wahrlich, so spricht der Herr: Mein Diener Orson Hyde und mein Diener Samuel H. Smith sollen ihre Reise in die östlichen Länder antreten und das verkündigen, was ich ihnen geboten habe; und insoweit sie treu sind, siehe, werde ich mit ihnen sein, ja, bis ans Ende."},{"verse":14,"text":"Und weiter, wahrlich, sage ich zu meinem Diener Lyman Johnson und zu meinem Diener Orson Pratt, sie sollen ebenfalls ihre Reise in die östlichen Länder antreten; und siehe, ja siehe, ich bin auch mit ihnen, ja, bis ans Ende."},{"verse":15,"text":"Und weiter, ich sage zu meinem Diener Asa Dodds und zu meinem Diener Calves Wilson, sie sollen ebenfalls ihre Reise antreten in die westlichen Länder und mein Evangelium verkündigen, so wie ich ihnen geboten habe."},{"verse":16,"text":"Und wer treu ist, der wird alles überwinden und wird am letzten Tag emporgehoben werden."},{"verse":17,"text":"Und weiter, ich sage zu meinem Diener Major N. Ashley und meinem Diener Burr Riggs, sie sollen ebenfalls ihre Reise antreten in das Land im Süden."},{"verse":18,"text":"Ja, sie sollen alle ihre Reise antreten, wie ich ihnen geboten habe, und von Haus zu Haus gehen und von Dorf zu Dorf und von Stadt zu Stadt."},{"verse":19,"text":"Und wo auch immer ihr ein Haus betretet, und man empfängt euch, da hinterlasst euren Segen auf jenem Haus."},{"verse":20,"text":"Und wo auch immer ihr ein Haus betretet, und man empfängt euch nicht, da sollt ihr euch schnell von jenem Haus entfernen und den Staub von euren Füßen schütteln zum Zeugnis gegen sie."},{"verse":21,"text":"Und ihr werdet von Freude und Frohsinn erfüllt sein und sollt dies wissen: Am Tag des Gerichts werdet ihr Richter sein über jenes Haus und sie schuldig sprechen;"},{"verse":22,"text":"und es wird erträglicher für die Heiden sein am Tag des Gerichts als für jenes Haus; darum gürtet euch die Lenden und seid treu, dann werdet ihr alles überwinden und am letzten Tag emporgehoben werden. So ist es. Amen."},{"verse":23,"text":"Und weiter, so spricht der Herr zu euch, o ihr Ältesten meiner Kirche, die ihr euren Namen genannt habt, damit ihr seinen Willen in Bezug auf euch wissen möget:"},{"verse":24,"text":"Siehe, ich sage euch: Es ist die Pflicht der Kirche, bei der Unterstützung der Familie derjenigen behilflich zu sein und auch die Familie derjenigen zu unterstützen, die berufen werden und notwendigerweise in die Welt hinausgesandt werden müssen, um der Welt das Evangelium zu verkündigen."},{"verse":25,"text":"Darum gebe ich, der Herr, euch dieses Gebot: Besorgt Unterkunft für eure Familien, insoweit eure Brüder gewillt sind, ihr Herz zu öffnen."},{"verse":26,"text":"Und alle diejenigen, die Unterkunft für ihre Familie und Unterstützung der Kirche für sie besorgen können, sollen nicht versäumen, in die Welt hinauszugehen, sei es in den Osten oder in den Westen oder in den Norden oder in den Süden."},{"verse":27,"text":"Sie sollen bitten, und sie werden empfangen, anklopfen, und es wird ihnen aufgetan werden, und es wird aus der Höhe kundgetan werden, nämlich durch den Tröster, wohin sie gehen sollen."},{"verse":28,"text":"Und weiter, wahrlich, ich sage euch: Ein jeder, der verpflichtet ist, selbst für seine Familie zu sorgen, soll für sie sorgen, und er wird keineswegs seiner Krone verlustig gehen; und er soll in der Kirche arbeiten."},{"verse":29,"text":"Ein jeder soll in allem eifrig sein. Und der Müßiggänger soll keinen Platz in der Kirche haben, außer er kehre um und bessere seine Wege."},{"verse":30,"text":"Darum sollen mein Diener Simeon Carter und mein Diener Emer Harris im geistlichen Dienst vereint sein,"},{"verse":31,"text":"ebenso mein Diener Ezra Thayre und mein Diener Thomas B. Marsh,"},{"verse":32,"text":"ebenso mein Diener Hyrum Smith und mein Diener Reynolds Cahoon,"},{"verse":33,"text":"ebenso mein Diener Daniel Stanton und mein Diener Seymour Brunson,"},{"verse":34,"text":"ebenso mein Diener Sylvester Smith und mein Diener Gideon Carter,"},{"verse":35,"text":"ebenso mein Diener Ruggles Eames und mein Diener Stephen Burnett,"},{"verse":36,"text":"ebenso mein Diener Micah B. Welton und ebenso mein Diener Eden Smith. So ist es. Amen."}]},{"chapter":76,"verses":[{"verse":1,"text":"Vernehmt, o ihr Himmel, und schenke Gehör, o Erde, und freut euch, ihr, deren Bewohner, denn der Herr ist Gott, und außer ihm gibt es keinen Erretter."},{"verse":2,"text":"Groß ist seine Weisheit, wunderbar sind seine Wege, und das Ausmaß seiner Werke vermag niemand zu ergründen."},{"verse":3,"text":"Seine Vorhaben gehen nicht fehl, auch gibt es keinen, der seine Hand zurückhalten kann."},{"verse":4,"text":"Von Ewigkeit zu Ewigkeit ist er derselbe, und seine Jahre hören niemals auf."},{"verse":5,"text":"Denn so spricht der Herr: Ich, der Herr, bin barmherzig und gnädig zu denen, die mich fürchten, und es freut mich, die zu ehren, die mir in Rechtschaffenheit und in Wahrheit bis ans Ende dienen."},{"verse":6,"text":"Groß wird ihr Lohn sein und ewig wird ihre Herrlichkeit sein."},{"verse":7,"text":"Und ihnen werde ich alle Geheimnisse offenbaren, ja, alle verborgenen Geheimnisse meines Reiches seit den alten Tagen, und für künftige Zeitalter werde ich ihnen das Wohlgefallen meines Willens kundtun, in Bezug auf alles, was mein Reich betrifft."},{"verse":8,"text":"Ja, selbst die Wunder der Ewigkeit werden sie wissen, und Zukünftiges werde ich ihnen zeigen, selbst das vieler Generationen."},{"verse":9,"text":"Und ihre Weisheit wird groß sein und ihr Verständnis bis zum Himmel reichen; und vor ihnen wird die Weisheit der Weisen zugrunde gehen und das Verständnis der Klugen wird zunichtewerden."},{"verse":10,"text":"Denn durch meinen Geist werde ich sie erleuchten, und durch meine Macht werde ich ihnen die Geheimnisse meines Willens kundtun – ja, selbst das, was das Auge nicht gesehen und das Ohr nicht gehört hat und was dem Menschen noch nicht ins Herz gedrungen ist."},{"verse":11,"text":"Wir, Joseph Smith Jr. und Sidney Rigdon, befanden uns am sechzehnten Tag des Februars im Jahre unseres Herrn eintausendachthundertzweiunddreißig im Geist –"},{"verse":12,"text":"durch die Macht des Geistes waren uns die Augen aufgegangen, und unser Verständnis wurde erleuchtet, sodass wir das, was von Gott ist, sehen und verstehen konnten –"},{"verse":13,"text":"selbst das, was von Anfang an war, ehe die Welt war, das, was vom Vater durch seinen einziggezeugten Sohn verordnet wurde, der am Herzen des Vaters war, ja, von Anfang an;"},{"verse":14,"text":"für ihn geben wir Zeugnis; und das Zeugnis, das wir geben, ist die Fülle des Evangeliums Jesu Christi, der der Sohn ist, den wir gesehen und mit dem wir in der himmlischen Vision geredet haben."},{"verse":15,"text":"Denn als wir mit der Übersetzungsarbeit beschäftigt waren, die der Herr uns bestimmt hatte, kamen wir zu dem neunundzwanzigsten Vers im fünften Kapitel des Johannes, der uns folgendermaßen gegeben wurde –"},{"verse":16,"text":"worin von der Auferstehung der Toten die Rede ist, derjenigen nämlich, die die Stimme des Menschensohnes vernehmen werden:"},{"verse":17,"text":"„und hervorkommen werden: die da Gutes getan haben, in der Auferstehung der Gerechten, und die da Böses getan haben, in der Auferstehung der Ungerechten“."},{"verse":18,"text":"Dies nun setzte uns in Verwunderung, denn es war uns vom Geist eingegeben worden."},{"verse":19,"text":"Und während wir darüber nachdachten, berührte der Herr die Augen unseres Verständnisses, und sie gingen uns auf, und die Herrlichkeit des Herrn leuchtete ringsum."},{"verse":20,"text":"Und wir erblickten die Herrlichkeit des Sohnes zur rechten Hand des Vaters und empfingen von seiner Fülle;"},{"verse":21,"text":"und sahen die heiligen Engel und diejenigen, die geheiligt sind, vor seinem Thron, wie sie Gott und das Lamm anbeten und ihn anbeten für immer und immer."},{"verse":22,"text":"Und nun, nach den vielen Zeugnissen, die für ihn gegeben worden sind, ist dies, als letztes von allen, das Zeugnis, das wir für ihn geben: Er lebt!"},{"verse":23,"text":"Denn wir haben ihn gesehen, ja, zur rechten Hand Gottes; und wir haben die Stimme Zeugnis geben hören, dass er der Einziggezeugte des Vaters ist –"},{"verse":24,"text":"dass von ihm und durch ihn und aus ihm die Welten erschaffen werden und wurden, und deren Bewohner sind für Gott gezeugte Söhne und Töchter."},{"verse":25,"text":"Und dies haben wir auch gesehen und geben Zeugnis, dass ein Engel Gottes, der in der Gegenwart Gottes Vollmacht hatte, der sich auflehnte gegen den einziggezeugten Sohn, den der Vater liebte und der am Herzen des Vaters war, aus der Gegenwart Gottes und des Sohnes hinabgeworfen wurde"},{"verse":26,"text":"und Verderben genannt wurde, denn die Himmel weinten über ihn – er war Luzifer, ein Sohn des Morgens."},{"verse":27,"text":"Und wir schauten, und siehe, er ist gefallen! ist gefallen, selbst ein Sohn des Morgens!"},{"verse":28,"text":"Und während wir noch im Geist waren, gebot uns der Herr, die Vision niederzuschreiben; denn wir erblickten den Satan, jene alte Schlange, nämlich den Teufel, der sich gegen Gott auflehnte und danach trachtete, das Reich unseres Gottes und seines Christus an sich zu nehmen –"},{"verse":29,"text":"darum führt er Krieg mit den Heiligen Gottes und schließt sie ringsum ein."},{"verse":30,"text":"Und wir sahen eine Vision von den Leiden derer, mit denen er Krieg geführt und die er überwunden hatte, denn so erging die Stimme des Herrn an uns:"},{"verse":31,"text":"So spricht der Herr in Bezug auf alle diejenigen, die meine Macht kennen und ihrer teilhaftig gemacht worden sind und zugelassen haben, dass sie durch die Macht des Teufels überwunden werden und die Wahrheit leugnen und meiner Macht trotzen –"},{"verse":32,"text":"sie sind diejenigen, die Söhne des Verderbens sind, von denen ich sage, es wäre besser für sie gewesen, nie geboren worden zu sein;"},{"verse":33,"text":"denn sie sind Gefäße des Grimms, dazu verdammt, in Ewigkeit mit dem Teufel und seinen Engeln den Grimm Gottes zu erleiden,"},{"verse":34,"text":"von denen ich gesagt habe, dass es keine Vergebung gibt, weder in dieser Welt noch in der künftigen Welt –"},{"verse":35,"text":"denn sie haben den Heiligen Geist geleugnet, nachdem sie ihn empfangen haben, und haben den einziggezeugten Sohn des Vaters geleugnet und haben ihn für sich selbst gekreuzigt und ihn zum offenen Gespött gemacht."},{"verse":36,"text":"Das sind diejenigen, die mit dem Teufel und seinen Engeln hinweggehen werden in den See von Feuer und Schwefel –"},{"verse":37,"text":"und die Einzigen, über die der zweite Tod irgendwelche Macht haben wird,"},{"verse":38,"text":"ja, wahrlich, die Einzigen, die zu der vom Herrn bestimmten Zeit, nachdem sie seinen Grimm erlitten haben, nicht erlöst werden."},{"verse":39,"text":"Denn alle Übrigen werden durch die Auferstehung der Toten hervorgebracht werden, durch den Triumph und die Herrlichkeit des Lammes, das getötet wurde, das am Herzen des Vaters war, ehe die Welten gemacht wurden."},{"verse":40,"text":"Und dies ist das Evangelium, die frohe Nachricht, wofür uns die Stimme aus den Himmeln Zeugnis gab:"},{"verse":41,"text":"Dass er in die Welt gekommen ist, nämlich Jesus, um für die Welt gekreuzigt zu werden und um die Sünden der Welt zu tragen und um die Welt zu heiligen und um sie von allem Unrecht zu säubern;"},{"verse":42,"text":"dass durch ihn alle errettet werden können, die der Vater in seine Macht gegeben hat und durch ihn gemacht hat,"},{"verse":43,"text":"der den Vater verherrlicht und alle Werke seiner Hände errettet, außer jene Söhne des Verderbens, die den Sohn leugnen, nachdem der Vater ihn offenbart hat."},{"verse":44,"text":"Darum errettet er alle außer sie – sie werden hinweggehen zu immerwährender Strafe, und das ist endlose Strafe, und das ist ewige Strafe, um mit dem Teufel und seinen Engeln in Ewigkeit zu regieren, wo ihr Wurm nicht stirbt und das Feuer nicht erlischt, und das ist ihre Qual –"},{"verse":45,"text":"und das Ende davon und den Ort davon und ihre Qual kennt kein Mensch,"},{"verse":46,"text":"und weder ist es den Menschen offenbart worden noch wird es ihnen jetzt oder später offenbart werden, außer denen, die daran teilhaben werden;"},{"verse":47,"text":"doch zeige ich, der Herr, es vielen in einer Vision, die ich aber dann sogleich wieder schließe;"},{"verse":48,"text":"darum werden das Ende, die Weite, die Höhe, die Tiefe und das Elend davon von ihnen nicht verstanden, auch von keinem Menschen außer denjenigen, denen dieser Schuldspruch verordnet wird."},{"verse":49,"text":"Und wir vernahmen die Stimme, nämlich: Schreibt die Vision nieder, denn siehe, dies ist das Ende der Vision von den Leiden der Gottlosen."},{"verse":50,"text":"Und wiederum geben wir Zeugnis – denn wir haben gesehen und vernommen, und dies ist das Zeugnis des Evangeliums Christi in Bezug auf diejenigen, die in der Auferstehung der Gerechten hervorkommen werden –"},{"verse":51,"text":"sie sind diejenigen, die das Zeugnis von Jesus empfangen haben und an seinen Namen geglaubt haben und nach der Art seiner Grablegung getauft worden sind, indem sie in seinem Namen im Wasser begraben wurden, und dies gemäß dem Gebot, das er gegeben hat –"},{"verse":52,"text":"damit sie durch das Halten der Gebote von all ihren Sünden gewaschen und gesäubert werden und den Heiligen Geist empfangen durch das Händeauflegen eines, der zu dieser Macht ordiniert und gesiegelt ist;"},{"verse":53,"text":"und die durch Glauben überwinden und vom Heiligen Geist der Verheißung gesiegelt sind, den der Vater über alle jene ausgießt, die gerecht und treu sind."},{"verse":54,"text":"Sie sind diejenigen, die die Kirche des Erstgeborenen sind."},{"verse":55,"text":"Sie sind diejenigen, denen der Vater alles in die Hände gegeben hat –"},{"verse":56,"text":"sie sind diejenigen, die Priester und Könige sind, die von seiner Fülle empfangen haben und von seiner Herrlichkeit"},{"verse":57,"text":"und Priester des Allerhöchsten nach der Ordnung Melchisedeks sind, welche nach der Ordnung Henochs war, welche nach der Ordnung des einziggezeugten Sohnes war."},{"verse":58,"text":"Darum, wie es geschrieben steht, sind sie Götter, nämlich die Söhne Gottes –"},{"verse":59,"text":"darum gehört ihnen alles, sei es Leben oder Tod, Gegenwärtiges oder Zukünftiges – alles gehört ihnen, und sie gehören Christus, und Christus gehört Gott."},{"verse":60,"text":"Und sie werden alles überwinden."},{"verse":61,"text":"Darum soll kein Mensch sich des Menschen rühmen, sondern er soll sich Gottes rühmen, der sich alle Feinde untertan machen wird unter seine Füße."},{"verse":62,"text":"Diese werden für immer und immer in der Gegenwart Gottes und seines Christus wohnen."},{"verse":63,"text":"Das sind diejenigen, die er mitbringen wird, wenn er in den Wolken des Himmels kommt, um auf Erden über sein Volk zu regieren."},{"verse":64,"text":"Das sind diejenigen, die an der ersten Auferstehung Anteil haben werden."},{"verse":65,"text":"Das sind diejenigen, die in der Auferstehung der Gerechten hervorkommen werden."},{"verse":66,"text":"Das sind diejenigen, die zum Berg Zion und zur Stadt des lebendigen Gottes gekommen sind, zur himmlischen Stätte, der heiligsten von allen."},{"verse":67,"text":"Das sind diejenigen, die zu einer unzählbaren Schar von Engeln gekommen sind, zur allgemeinen Versammlung und Kirche Henochs und des Erstgeborenen."},{"verse":68,"text":"Das sind diejenigen, deren Namen im Himmel aufgeschrieben sind, wo Gott und Christus die Richter aller sind."},{"verse":69,"text":"Das sind diejenigen, die gerechte Menschen sind, vollkommen gemacht durch Jesus, den Mittler des neuen Bundes, der mit dem Vergießen seines eigenen Blutes dieses vollkommene Sühnopfer bewirkt hat."},{"verse":70,"text":"Das sind diejenigen, deren Körper celestial ist, deren Herrlichkeit die der Sonne ist, selbst die Herrlichkeit Gottes, des höchsten von allen, von welcher Herrlichkeit geschrieben steht, die Sonne am Firmament sei dafür kennzeichnend."},{"verse":71,"text":"Und weiter sahen wir die terrestriale Welt, und siehe, ja siehe, das sind diejenigen, die zu den Terrestrialen gehören, deren Herrlichkeit sich von der der Kirche des Erstgeborenen, die die Fülle des Vaters empfangen haben, so unterscheidet, wie sich die des Mondes von der Sonne am Firmament unterscheidet."},{"verse":72,"text":"Siehe, das sind diejenigen, die ohne Gesetz gestorben sind,"},{"verse":73,"text":"und auch diejenigen, die die im Gefängnis gehaltenen Menschengeister sind, die der Sohn besucht hat und denen er das Evangelium gepredigt hat, damit sie den Menschen gemäß nach dem Fleisch gerichtet werden können,"},{"verse":74,"text":"die das Zeugnis von Jesus im Fleische nicht empfangen haben, es aber nachher empfangen haben."},{"verse":75,"text":"Das sind diejenigen, die ehrenhafte Menschen auf Erden sind, die durch die Hinterlist von Menschen verblendet worden sind."},{"verse":76,"text":"Das sind diejenigen, die von seiner Herrlichkeit empfangen, aber nicht von seiner Fülle."},{"verse":77,"text":"Das sind diejenigen, die von der Gegenwart des Sohnes empfangen, aber nicht von der Fülle des Vaters."},{"verse":78,"text":"Darum sind sie terrestriale Körper und nicht celestiale Körper und unterscheiden sich an Herrlichkeit, wie sich der Mond von der Sonne unterscheidet."},{"verse":79,"text":"Das sind diejenigen, die im Zeugnis von Jesus nicht tapfer sind; darum erlangen sie nicht die Krone über das Reich unseres Gottes."},{"verse":80,"text":"Und nun ist dies das Ende der Vision, die wir von den Terrestrialen schauten und die der Herr uns niederzuschreiben gebot, während wir noch im Geist waren."},{"verse":81,"text":"Und weiter sahen wir die Herrlichkeit der Telestialen, welche Herrlichkeit die der Geringeren ist, so wie sich die Herrlichkeit der Sterne von der Herrlichkeit des Mondes am Firmament unterscheidet."},{"verse":82,"text":"Das sind diejenigen, die das Evangelium von Christus nicht empfangen haben, auch nicht das Zeugnis von Jesus."},{"verse":83,"text":"Das sind diejenigen, die den Heiligen Geist nicht leugnen."},{"verse":84,"text":"Das sind diejenigen, die in die Hölle hinabgeworfen werden."},{"verse":85,"text":"Das sind diejenigen, die erst mit der letzten Auferstehung aus der Gewalt des Teufels erlöst werden, dann, wenn der Herr, nämlich Christus, das Lamm, sein Werk beendet haben wird."},{"verse":86,"text":"Das sind diejenigen, die nicht von seiner Fülle in der ewigen Welt empfangen, sondern vom Heiligen Geist durch den Dienst der Terrestrialen,"},{"verse":87,"text":"und die Terrestrialen durch den Dienst der Celestialen."},{"verse":88,"text":"Und auch die Telestialen empfangen davon durch den Dienst von Engeln, die bestimmt sind, ihnen zu dienen, oder die dazu bestimmt sind, dienende Geister für sie zu sein; denn sie werden Erben der Errettung sein."},{"verse":89,"text":"Und so sahen wir, in der himmlischen Vision, die Herrlichkeit der Telestialen, die alles Verständnis übersteigt;"},{"verse":90,"text":"und kein Mensch kennt sie, außer wem Gott es offenbart hat."},{"verse":91,"text":"Und so sahen wir die Herrlichkeit der Terrestrialen, die die Herrlichkeit der Telestialen in allem übertrifft, nämlich an Herrlichkeit und an Macht und an Kraft und an Herrschaft."},{"verse":92,"text":"Und so sahen wir die Herrlichkeit der Celestialen, die alles übertrifft – wo Gott, selbst der Vater, auf seinem Thron für immer und immer regiert,"},{"verse":93,"text":"vor dessen Thron sich alles in demütiger Ehrfurcht neigt und ihm Ehre erweist für immer und immer."},{"verse":94,"text":"Diejenigen, die in seiner Gegenwart wohnen, sind die Kirche des Erstgeborenen; und sie sehen, wie sie gesehen werden, und erkennen, wie sie erkannt werden, denn sie haben von seiner Fülle und von seiner Gnade empfangen;"},{"verse":95,"text":"und er macht sie gleich an Macht und an Kraft und an Herrschaft."},{"verse":96,"text":"Und die Herrlichkeit der Celestialen ist eine eigene, so wie die Herrlichkeit der Sonne eine eigene ist."},{"verse":97,"text":"Und die Herrlichkeit der Terrestrialen ist eine eigene, so wie die Herrlichkeit des Mondes eine eigene ist."},{"verse":98,"text":"Und die Herrlichkeit der Telestialen ist eine eigene, so wie die Herrlichkeit der Sterne eine eigene ist; denn wie ein Stern sich vom anderen Stern an Herrlichkeit unterscheidet, so unterscheidet sich auch der eine vom anderen in der telestialen Welt an Herrlichkeit;"},{"verse":99,"text":"denn das sind diejenigen, die des Paulus und des Apollos und des Kephas sind."},{"verse":100,"text":"Das sind diejenigen, die sagen, sie seien einige des einen und einige des anderen – einige des Christus und einige des Johannes und einige des Mose und einige des Elias und einige des Esaias und einige des Jesaja und einige des Henoch,"},{"verse":101,"text":"aber haben das Evangelium nicht empfangen, auch nicht das Zeugnis von Jesus, auch nicht die Propheten, auch nicht den immerwährenden Bund."},{"verse":102,"text":"Schließlich sind das alle diejenigen, die sich nicht mit den Heiligen sammeln wollen, um zur Kirche des Erstgeborenen entrückt und in der Wolke empfangen zu werden."},{"verse":103,"text":"Das sind diejenigen, die Lügner sind und Zauberer und Ehebrecher und Unzüchtige und wer auch immer Lüge liebt und tut."},{"verse":104,"text":"Das sind diejenigen, die den Grimm Gottes auf Erden erleiden."},{"verse":105,"text":"Das sind diejenigen, die die Rache ewigen Feuers erleiden."},{"verse":106,"text":"Das sind diejenigen, die in die Hölle hinabgeworfen werden und den Grimm des allmächtigen Gottes erleiden bis hin zu der Fülle der Zeiten, wenn Christus sich alle Feinde unter seine Füße untertan gemacht haben wird und sein Werk vollendet haben wird;"},{"verse":107,"text":"wenn er das Reich übergeben und es dem Vater makellos darreichen und sagen wird: Ich habe überwunden und habe die Weinkelter allein getreten, ja, die Weinkelter des heftigen Grimms des allmächtigen Gottes."},{"verse":108,"text":"Dann wird er mit der Krone seiner Herrlichkeit gekrönt werden, dass er auf dem Thron seiner Macht sitze und regiere für immer und immer."},{"verse":109,"text":"Aber siehe, ja siehe, wir sahen die Herrlichkeit und die Bewohner der telestialen Welt, dass sie so unzählbar waren wie die Sterne am Firmament des Himmels oder wie der Sand am Ufer des Meeres,"},{"verse":110,"text":"und vernahmen die Stimme des Herrn, nämlich: Diese alle werden das Knie beugen und jede Zunge wird bekennen vor ihm, der für immer und immer auf dem Thron sitzt;"},{"verse":111,"text":"denn sie werden gemäß ihren Werken gerichtet werden, und jeder Mensch wird gemäß seinen eigenen Werken seine eigene Herrschaft empfangen in den Wohnungen, die bereitet worden sind;"},{"verse":112,"text":"und sie werden Diener des Allerhöchsten sein, aber dort, wo Gott und Christus wohnen, können sie, Welten ohne Ende, nicht hinkommen."},{"verse":113,"text":"Dies ist das Ende der Vision, die wir schauten und von der uns geboten wurde, sie niederzuschreiben, während wir noch im Geist waren."},{"verse":114,"text":"Aber groß und wunderbar sind die Werke des Herrn und die Geheimnisse seines Reiches, die er uns gezeigt hat, die an Herrlichkeit und an Kraft und an Herrschaft alles Verständnis übersteigen;"},{"verse":115,"text":"von ihnen hat er uns geboten, sie nicht niederzuschreiben, während wir noch im Geist waren; und es ist nicht recht, dass der Mensch sie ausspricht,"},{"verse":116,"text":"auch ist der Mensch nicht fähig, sie kundzutun, denn sie lassen sich nur mit der Macht des Heiligen Geistes sehen und verstehen, den Gott denjenigen zuteilwerden lässt, die ihn lieben und sich vor ihm rein machen,"},{"verse":117,"text":"denen er diesen Vorzug gewährt, dass sie selbst sehen und wissen dürfen;"},{"verse":118,"text":"damit sie, noch im Fleische, durch die Macht und Kundgebung des Geistes imstande seien, seine Gegenwart in der Welt der Herrlichkeit zu ertragen."},{"verse":119,"text":"Und Gott und dem Lamm seien Herrlichkeit und Ehre und Herrschaft für immer und immer. Amen."}]},{"chapter":77,"verses":[{"verse":1,"text":"Frage: Was ist das gläserne Meer, von dem Johannes im 4. Kapitel, Vers 6 der Offenbarung spricht?Antwort: Das ist die Erde in ihrem geheiligten, unsterblichen und ewigen Zustand."},{"verse":2,"text":"Fr.: Was sollen wir unter den vier Lebewesen verstehen, von denen im selben Vers gesprochen wird?Antw.: Das ist ein bildhafter Ausdruck, den der Offenbarer Johannes verwendet hat, um den Himmel, das Paradies Gottes, das Glück des Menschen und der Tiere und des kriechenden Getiers und der Vögel der Luft zu beschreiben; das, was geistig ist, gleicht dem, was zeitlich ist; und das, was zeitlich ist, gleicht dem, was geistig ist; der Geist des Menschen gleicht seiner körperlichen Gestalt und ebenso der Geist der Tiere und eines jeden anderen Geschöpfs, das Gott geschaffen hat."},{"verse":3,"text":"Fr.: Sind die vier Lebewesen nur bestimmte Tiere, oder stellen sie Klassen oder Ordnungen dar?Antw.: Es sind nur vier bestimmte Tiere, die Johannes gezeigt wurden, und sie stellen die Herrlichkeit der Klassen von Wesen in ihrer bestimmten Ordnung oder Schöpfungssphäre dar, im Genuss ihres ewigen Glücks."},{"verse":4,"text":"Fr.: Was sollen wir unter den Augen und Flügeln verstehen, die die Lebewesen hatten?Antw.: Ihre Augen stellen Licht und Erkenntnis dar, das heißt, dass sie voll Erkenntnis sind; und ihre Flügel stellen die Macht dar, sich zu bewegen, zu handeln usw."},{"verse":5,"text":"Fr.: Was sollen wir unter den vierundzwanzig Ältesten verstehen, von denen Johannes spricht?Antw.: Darunter ist zu verstehen, dass diese Ältesten, die Johannes sah, Älteste sind, die im Werk des geistlichen Dienstes treu waren und gestorben sind; sie gehörten zu den sieben Gemeinden und waren dann im Paradies Gottes."},{"verse":6,"text":"Fr.: Was sollen wir unter dem Buch verstehen, das Johannes sah und das auf der Rückseite mit sieben Siegeln versiegelt war?Antw.: Darunter ist zu verstehen, dass es den Willen, die Geheimnisse und die Werke Gottes enthält, die er offenbart hat – das Verborgene seines Haushaltens in Bezug auf diese Erde während der siebentausend Jahre ihres Bestehens oder ihres zeitlichen Daseins."},{"verse":7,"text":"Fr.: Was sollen wir unter den sieben Siegeln verstehen, womit es versiegelt war?Antw.: Darunter ist zu verstehen, dass das erste Siegel das einschließt, was zu den ersten tausend Jahren gehört, und das zweite gleichermaßen das, was zu den zweiten tausend Jahren gehört, und so weiter bis zum siebenten."},{"verse":8,"text":"Fr.: Was sollen wir unter den vier Engeln verstehen, von denen im 7. Kapitel der Offenbarung, Vers 1 gesprochen wird?Antw.: Darunter ist zu verstehen, dass es vier Engel sind, die von Gott ausgesandt sind und denen Macht über die vier Teile der Erde gegeben ist, um Leben zu erretten und zu zerstören; das sind diejenigen, die das immerwährende Evangelium jeder Nation, jedem Geschlecht, jeder Sprache und jedem Volk zu überbringen haben; und sie haben die Macht, die Himmel zu verschließen, zum Leben zu versiegeln oder in die Bereiche der Finsternis hinabzuwerfen."},{"verse":9,"text":"Fr.: Was sollen wir unter dem Engel verstehen, der gemäß Offenbarung, 7. Kapitel, Vers 2 vom Osten her emporsteigt?Antw.: Darunter ist zu verstehen, dass der vom Osten her emporsteigende Engel jener ist, dem das Siegel des lebendigen Gottes über die zwölf Stämme Israels gegeben ist; darum ruft er den vier Engeln, die das immerwährende Evangelium haben, zu, nämlich: Schadet nicht der Erde noch dem Meer noch den Bäumen, bis wir die Diener unseres Gottes an ihrer Stirn versiegelt haben. Und wenn ihr dies annehmen wollt: Dies ist Elias, der kommen sollte, um die Stämme Israels zu sammeln und alles wiederherzustellen."},{"verse":10,"text":"Fr.: Wann wird das, wovon in diesem Kapitel gesprochen wird, vollbracht werden?Antw.: Es wird im sechsten Jahrtausend, oder mit dem Öffnen des sechsten Siegels, vollbracht werden."},{"verse":11,"text":"Fr.: Was sollen wir unter dem Versiegeln der einhundertvierundvierzigtausend aus allen Stämmen Israels verstehen – zwölftausend aus jedem Stamm?Antw.: Darunter ist zu verstehen, dass diejenigen, die versiegelt werden, Hohe Priester sind, ordiniert zur heiligen Ordnung Gottes, um das immerwährende Evangelium zu verwalten; denn es sind diejenigen, die aus jeder Nation, jedem Geschlecht, jeder Sprache und jedem Volk ordiniert werden, durch die Engel, denen Macht über die Nationen der Erde gegeben ist, um alle, die kommen wollen, in die Kirche des Erstgeborenen zu bringen."},{"verse":12,"text":"Fr.: Was sollen wir unter dem Ertönen der Posaunen verstehen, das im 8. Kapitel der Offenbarung erwähnt wird?Antw.: Darunter ist zu verstehen: Wie Gott die Welt in sechs Tagen gemacht hat und er am siebenten Tag sein Werk vollendet und diesen geheiligt hat und auch den Menschen aus dem Staub der Erde gestaltet hat, so wird Gott, der Herr, auch am Anfang des siebenten Jahrtausends die Erde heiligen und die Errettung des Menschen vollenden und über alles Gericht halten und wird alles erlösen, ausgenommen das, was er nicht in seine Macht gegeben hat, wenn er alles gesiegelt haben wird, nämlich zum Ende aller Dinge; und das Ertönen der Posaunen der sieben Engel ist das Vorbereiten und Vollenden seines Werkes zu Anfang des siebenten Jahrtausends – das Vorbereiten des Weges vor der Zeit seines Kommens."},{"verse":13,"text":"Fr.: Wann wird das vollbracht werden, was im 9. Kapitel der Offenbarung geschrieben steht?Antw.: Es wird nach dem Öffnen des siebenten Siegels vollbracht werden, vor dem Kommen Christi."},{"verse":14,"text":"Fr.: Was sollen wir unter dem kleinen Buch verstehen, das Johannes gegessen hat, wie es im 10. Kapitel der Offenbarung erwähnt ist?Antw.: Darunter ist zu verstehen, dass es eine Mission und eine Verordnung für ihn war, die Stämme Israels zu sammeln; siehe, dies ist Elias, der, wie es geschrieben steht, kommen und alles wiederherstellen muss."},{"verse":15,"text":"Fr.: Was ist unter den zwei Zeugen im elften Kapitel der Offenbarung zu verstehen?Antw.: Das sind zwei Propheten, die der jüdischen Nation in den letzten Tagen erweckt werden, zur Zeit der Wiederherstellung; und sie werden den Juden prophezeien, nachdem diese gesammelt worden sind und die Stadt Jerusalem im Land ihrer Väter aufgebaut haben."}]},{"chapter":78,"verses":[{"verse":1,"text":"Der Herr redete zu Joseph Smith Jr., nämlich: Hört auf mich, spricht der Herr, euer Gott, die ihr zum Hohen Priestertum meiner Kirche ordiniert seid, die ihr euch versammelt habt,"},{"verse":2,"text":"und hört auf den Rat dessen, der euch aus der Höhe ordiniert hat, der die Worte der Weisheit in eure Ohren sprechen wird, damit Errettung für euch in dem sei, was ihr mir vorgelegt habt, spricht Gott, der Herr."},{"verse":3,"text":"Denn wahrlich, ich sage euch: Die Zeit ist gekommen und ist jetzt da; und siehe, ja siehe, es muss notwendigerweise sein, dass es eine Organisation meines Volkes gebe, um die Angelegenheiten des Vorratshauses für die Armen meines Volkes zu regeln und festzulegen, sowohl an diesem Ort wie auch im Land Zion –"},{"verse":4,"text":"als eine dauernde und immerwährende Einrichtung und Ordnung für meine Kirche, um die Sache zu fördern, die ihr auf euch genommen habt, für die Errettung des Menschen und für die Herrlichkeit eures Vaters, der im Himmel ist;"},{"verse":5,"text":"damit ihr in den Bündnissen himmlischer Dinge gleich seiet, ja, und auch irdischer Dinge, um himmlische Dinge zu erlangen."},{"verse":6,"text":"Denn wenn ihr in irdischen Dingen nicht gleich seid, könnt ihr beim Erlangen himmlischer Dinge nicht gleich sein;"},{"verse":7,"text":"denn wenn ihr wollt, dass ich euch einen Platz in der celestialen Welt gebe, dann müsst ihr euch darauf vorbereiten, indem ihr das tut, was ich euch geboten und von euch verlangt habe."},{"verse":8,"text":"Und nun, wahrlich, so spricht der Herr: Es ist ratsam, dass alles zu meiner Herrlichkeit getan werde, von euch, die ihr in dieser Ordnung verbunden seid;"},{"verse":9,"text":"oder, mit anderen Worten, mein Diener Newel K. Whitney und mein Diener Joseph Smith Jr. und mein Diener Sidney Rigdon sollen mit den Heiligen, die in Zion sind, zu Rate sitzen;"},{"verse":10,"text":"andernfalls trachtet der Satan danach, ihr Herz von der Wahrheit abzuwenden, sodass sie verblendet werden und das, was für sie bereitet ist, nicht verstehen."},{"verse":11,"text":"Darum gebe ich euch das Gebot, euch bereitzumachen und euch mit einem Bündnis oder immerwährenden Bund, der nicht gebrochen werden kann, zu organisieren."},{"verse":12,"text":"Und wer ihn bricht, wird sein Amt und seinen Stand in der Kirche verlieren und wird bis zum Tag der Erlösung den Schlägen des Satans überantwortet werden."},{"verse":13,"text":"Siehe, dies ist die Vorbereitung, womit ich euch vorbereite, und die Grundlage und das Beispiel, das ich euch gebe, wodurch ihr die Gebote ausführen könnt, die euch gegeben sind;"},{"verse":14,"text":"damit durch meine Vorsehung, ungeachtet der Drangsal, die über euch kommen wird, damit die Kirche unabhängig dastehen kann, über allen anderen Geschöpfen unterhalb der celestialen Welt;"},{"verse":15,"text":"damit ihr zu der Krone heraufkommen könnt, die für euch bereitet ist, und zu Herrschern über viele Reiche gemacht werden könnt, spricht Gott, der Herr, der Heilige Zions, der die Grundlagen von Adam-ondi-Ahman gelegt hat,"},{"verse":16,"text":"der Michael zu eurem Fürsten bestimmt und seine Füße fest hingestellt und ihn hoch oben hingesetzt und ihm die Schlüssel der Errettung unter dem Rat und der Leitung des Heiligen gegeben hat, der ohne Anfang der Tage oder Ende des Lebens ist."},{"verse":17,"text":"Wahrlich, wahrlich, ich sage euch: Ihr seid kleine Kinder, und ihr habt noch nicht verstanden, welch große Segnungen der Vater in seinen eigenen Händen hält und für euch bereitet hat;"},{"verse":18,"text":"und ihr könnt jetzt noch nicht alles ertragen; doch seid guten Mutes, denn ich werde euch weiter führen. Das Reich ist euer, und seine Segnungen sind euer, und die Reichtümer der Ewigkeit sind euer."},{"verse":19,"text":"Und wer alles mit Dankbarkeit empfängt, der wird herrlich gemacht werden; und die Dinge dieser Erde werden ihm hinzugefügt werden, selbst hundertfältig, ja, mehr."},{"verse":20,"text":"Darum tut das, was ich euch geboten habe, spricht euer Erlöser, nämlich der Sohn Ahman, der alles bereitet, ehe er euch hinwegnimmt;"},{"verse":21,"text":"denn ihr seid die Kirche des Erstgeborenen, und er wird euch in einer Wolke emporheben und einem jeden sein Teil bestimmen."},{"verse":22,"text":"Und wer ein treuer und weiser Treuhänder ist, der wird alles ererben. Amen."}]},{"chapter":79,"verses":[{"verse":1,"text":"Wahrlich, ich sage dir: Es ist mein Wille, dass mein Diener Jared Carter abermals in die östlichen Länder gehe, von Ort zu Ort und von Stadt zu Stadt, in der Macht der Ordinierung, womit er ordiniert worden ist, und die frohe Nachricht von großer Freude verkündige, nämlich das immerwährende Evangelium."},{"verse":2,"text":"Und ich werde den Tröster auf ihn herabschicken, der ihn die Wahrheit lehren wird und den Weg, den er gehen soll;"},{"verse":3,"text":"und insoweit er treu ist, werde ich ihn abermals mit Garben krönen."},{"verse":4,"text":"Darum lass dein Herz froh sein, mein Diener Jared Carter, und fürchte dich nicht, spricht dein Herr, ja, Jesus Christus. Amen."}]},{"chapter":80,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr zu dir, mein Diener Stephen Burnett: Geh hin, geh hin in die Welt und predige das Evangelium jedem Geschöpf, das vom Klang deiner Stimme erreicht wird."},{"verse":2,"text":"Und da du dir einen Begleiter wünschst, gebe ich dir meinen Diener Eden Smith."},{"verse":3,"text":"Darum geht hin und predigt mein Evangelium, ob im Norden oder im Süden, im Osten oder im Westen, darauf kommt es nicht an, denn ihr könnt nicht fehlgehen."},{"verse":4,"text":"Darum verkündet, was ihr vernommen habt und wirklich glaubt und wovon ihr wisst, dass es wahr ist."},{"verse":5,"text":"Siehe, dies ist der Wille dessen, der euch berufen hat, euer Erlöser, ja, Jesus Christus. Amen."}]},{"chapter":81,"verses":[{"verse":1,"text":"Wahrlich, wahrlich, ich sage dir, mein Diener Frederick G. Williams: Höre auf die Stimme dessen, der redet, auf das Wort des Herrn, deines Gottes, und höre auf die Berufung, zu der du berufen wirst, nämlich in meiner Kirche ein Hoher Priester und meinem Diener Joseph Smith Jr. ein Ratgeber zu sein,"},{"verse":2,"text":"dem ich die Schlüssel des Reiches gegeben habe, die immer zur Präsidentschaft des Hohen Priestertums gehören:"},{"verse":3,"text":"Darum, wahrlich, erkenne ich ihn an und werde ihn und auch dich segnen, insoweit du treu bist im Rat, in dem Amt, das ich dir bestimmt habe, in ständigem Beten, laut und in deinem Herzen, in der Öffentlichkeit und wenn du allein bist, und auch in deinem geistlichen Dienst, indem du das Evangelium im Land der Lebenden und unter deinen Brüdern verkündigst."},{"verse":4,"text":"Und indem du dies tust, wirst du deinen Mitmenschen das meiste Gute tun und wirst die Herrlichkeit dessen fördern, der dein Herr ist."},{"verse":5,"text":"Darum sei treu; steh in dem Amt, das ich dir bestimmt habe; steh den Schwachen bei, hebe die herabgesunkenen Hände empor, und stärke die müden Knie."},{"verse":6,"text":"Und wenn du bis ans Ende treu bist, wirst du eine Krone der Unsterblichkeit haben und ewiges Leben in den Wohnungen, die ich im Haus meines Vaters bereitet habe."},{"verse":7,"text":"Siehe, ja siehe, dies sind die Worte Alphas und Omegas, ja, Jesu Christi. Amen."}]},{"chapter":82,"verses":[{"verse":1,"text":"Wahrlich, wahrlich, ich sage euch, meine Diener: Insoweit ihr einander eure Verfehlungen vergeben habt, so vergebe ich, der Herr, euch auch."},{"verse":2,"text":"Doch gibt es unter euch welche, die über die Maßen gesündigt haben; ja, selbst ihr alle habt gesündigt; aber wahrlich, ich sage euch: Hütet euch hinfort und lasst ab von Sünde, damit nicht schwerer Richterspruch auf euer Haupt falle."},{"verse":3,"text":"Denn wem viel gegeben ist, von dem wird viel gefordert; und wer gegen das größere Licht sündigt, der wird den größeren Schuldspruch empfangen."},{"verse":4,"text":"Ihr ruft meinen Namen an um Offenbarungen, und ich gebe sie euch; und insoweit ihr meine Worte, die ich euch gebe, nicht haltet, werdet ihr zu Übertretern; und Gerechtigkeit und Richterspruch sind die festgesetzte Strafe, die mit meinem Gesetz einhergeht."},{"verse":5,"text":"Darum, was ich zu einem sage, das sage ich zu allen: Seid wachsam, denn der Widersacher breitet seine Herrschaft aus, und Finsternis regiert;"},{"verse":6,"text":"und der Zorn Gottes entflammt gegen die Bewohner der Erde; und niemand tut Gutes, denn alle sind vom Weg abgewichen."},{"verse":7,"text":"Und nun, wahrlich, ich sage euch: Ich, der Herr, werde euch keine Sünde zur Last legen; geht eurer Wege und sündigt nicht mehr; aber zu der Seele, die sündigt, werden die früheren Sünden zurückkehren, spricht der Herr, euer Gott."},{"verse":8,"text":"Und weiter, ich sage euch: Ich gebe euch ein neues Gebot, damit ihr meinen Willen in Bezug auf euch versteht,"},{"verse":9,"text":"oder, mit anderen Worten, ich gebe euch Weisungen, wie ihr vor mir handeln könnt, damit es sich zu eurer Errettung wende."},{"verse":10,"text":"Ich, der Herr, bin verpflichtet, wenn ihr tut, was ich sage; tut ihr aber nicht, was ich sage, so habt ihr keine Verheißung."},{"verse":11,"text":"Darum wahrlich, ich sage euch: Es ist ratsam, dass meine Diener Edward Partridge und Newel K. Whitney, A. Sidney Gilbert und Sidney Rigdon und mein Diener Joseph Smith und John Whitmer und Oliver Cowdery und W. W. Phelps und Martin Harris sich miteinander durch ein Bündnis und einen Bund, der durch Übertretung nicht gebrochen werden kann, wenn nicht unmittelbar darauf Richterspruch folgen soll, in ihren verschiedenen Treuhandschaften bindend verpflichten –"},{"verse":12,"text":"um die Angelegenheiten der Armen und alles, was die Bischofschaft sowohl im Land Zion als auch im Land Kirtland betrifft, zu verwalten;"},{"verse":13,"text":"denn ich habe das Land Kirtland zu der von mir selbst bestimmten Zeit zum Nutzen der Heiligen des Allerhöchsten und für einen Pfahl für Zion geweiht."},{"verse":14,"text":"Denn Zion muss zunehmen an Schönheit und an Heiligkeit; seine Grenzen müssen erweitert werden; seine Pfähle müssen gestärkt werden; ja, wahrlich, ich sage euch: Zion muss sich erheben und seine schönen Gewänder anlegen."},{"verse":15,"text":"Darum gebe ich euch dies Gebot, euch mit diesem Bund bindend zu verpflichten, und es soll gemäß den Gesetzen des Herrn geschehen."},{"verse":16,"text":"Siehe, dies ist auch nach meiner Weisheit zu eurem Nutzen."},{"verse":17,"text":"Und ihr sollt gleich sein oder, mit anderen Worten, ihr sollt gleiche Ansprüche auf das Eigentum haben, damit ihr die Belange eurer Treuhandschaften nutzbringend verwalten könnt, ein jeder gemäß seinen Bedürfnissen und seinem Bedarf, soweit seine Bedürfnisse gerecht sind –"},{"verse":18,"text":"und dies alles zum Nutzen der Kirche des lebendigen Gottes, damit ein jeder sein Talent nutzbringend anlege, damit ein jeder weitere Talente hinzugewinne, ja, selbst hundertfältig, damit sie in das Vorratshaus des Herrn eingeworfen werden, um das allgemeine Eigentum der ganzen Kirche zu werden –"},{"verse":19,"text":"ein jeder soll auf das Wohl seines Nächsten bedacht sein und bei allem, was er tut, das Auge nur auf die Herrlichkeit Gottes richten."},{"verse":20,"text":"Diese Ordnung habe ich zu einer immerwährenden Ordnung für euch und für eure Nachfolger bestimmt, insoweit ihr nicht sündigt."},{"verse":21,"text":"Und mit der Seele, die gegen diesen Bund sündigt und ihr Herz dagegen verhärtet, soll gemäß den Gesetzen meiner Kirche verfahren werden, und sie soll bis zum Tag der Erlösung den Schlägen des Satans überantwortet werden."},{"verse":22,"text":"Und nun, wahrlich, ich sage euch, und dies ist Weisheit: Macht euch Freunde mit dem Mammon der Ungerechtigkeit, dann werden sie euch nicht vernichten."},{"verse":23,"text":"Überlasst mir allein den Richterspruch, denn er ist mein, und ich werde vergelten. Friede sei mit euch; meine Segnungen begleiten euch."},{"verse":24,"text":"Denn schon jetzt ist das Reich euer und wird es immerdar sein, wenn ihr von eurer Standhaftigkeit nicht fallt. So ist es. Amen."}]},{"chapter":83,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr, zusätzlich zu den Gesetzen der Kirche in Bezug auf Frauen und Kinder, diejenigen, die der Kirche angehören und die ihren Ehemann oder Vater verloren haben:"},{"verse":2,"text":"Frauen haben an ihren Mann Anspruch auf ihren Unterhalt, bis ihr Mann weggenommen wird; und wenn sie nicht als Übertreterinnen befunden werden, sollen sie Gemeinschaft in der Kirche haben."},{"verse":3,"text":"Und wenn sie nicht treu sind, sollen sie keine Gemeinschaft in der Kirche haben; doch dürfen sie gemäß den Gesetzen des Landes auf ihrem Erbteil verbleiben."},{"verse":4,"text":"Alle Kinder haben an ihre Eltern Anspruch auf ihren Unterhalt, bis sie mündig sind."},{"verse":5,"text":"Und danach haben sie Anspruch an die Kirche oder, mit anderen Worten, an das Vorratshaus des Herrn, wenn ihre Eltern nichts haben, um ihnen ein Erbteil zu geben."},{"verse":6,"text":"Und das Vorratshaus soll durch die Weihungen aus der Kirche erhalten bleiben; und Witwen und Waisen sollen versorgt werden, ebenso die Armen. Amen."}]},{"chapter":84,"verses":[{"verse":1,"text":"Eine Offenbarung von Jesus Christus an seinen Diener Joseph Smith Jr. und sechs Älteste, als sie ihr Herz vereinigten und ihre Stimme zum Himmel erhoben."},{"verse":2,"text":"Ja, das Wort des Herrn in Bezug auf seine Kirche, aufgerichtet in den letzten Tagen für die Wiederherstellung seines Volkes, wie er durch den Mund seiner Propheten gesprochen hat, und für die Sammlung seiner Heiligen, damit sie auf dem Berg Zion stehen, der die Stadt des Neuen Jerusalem sein wird."},{"verse":3,"text":"Und diese Stadt soll gebaut werden, angefangen am Tempelgrund, der durch den Finger des Herrn bestimmt worden ist, im westlichen Grenzgebiet des Staates Missouri, und durch die Hand von Joseph Smith Jr. und anderer, an denen der Herr Wohlgefallen gehabt hat, geweiht worden ist."},{"verse":4,"text":"Wahrlich, dies ist das Wort des Herrn: Die Stadt Neues Jerusalem soll durch die Sammlung der Heiligen erbaut werden, angefangen an diesem Ort, nämlich am Platz des Tempels, und dieser Tempel wird in dieser Generation errichtet werden."},{"verse":5,"text":"Denn wahrlich, diese Generation wird nicht gänzlich vergehen, bis dem Herrn ein Haus erbaut sein wird, und eine Wolke wird darauf ruhen, und diese Wolke wird selbst die Herrlichkeit des Herrn sein, die das Haus erfüllen wird."},{"verse":6,"text":"Und die Söhne Moses, gemäß dem Heiligen Priestertum, das er unter der Hand seines Schwiegervaters Jitro empfing,"},{"verse":7,"text":"und Jitro empfing es unter Kalebs Hand,"},{"verse":8,"text":"und Kaleb empfing es unter Elihus Hand,"},{"verse":9,"text":"und Elihu unter Jeremis Hand,"},{"verse":10,"text":"und Jeremi unter Gads Hand,"},{"verse":11,"text":"und Gad unter Esaias’ Hand,"},{"verse":12,"text":"und Esaias empfing es unter Gottes Hand."},{"verse":13,"text":"Esaias lebte auch in den Tagen Abrahams und wurde von ihm gesegnet –"},{"verse":14,"text":"dieser Abraham empfing das Priestertum von Melchisedek, der es durch die Linie seiner Väter, ja, bis Noach, empfangen hatte;"},{"verse":15,"text":"und von Noach bis Henoch, durch die Linie ihrer Väter;"},{"verse":16,"text":"und von Henoch bis Abel, der durch die Verschwörung seines Bruders getötet wurde und der das Priestertum auf die Gebote Gottes hin durch die Hand seines Vaters Adam empfing, der der erste Mensch war –"},{"verse":17,"text":"und dieses Priestertum besteht in der Kirche Gottes in allen Generationen fort und ist ohne Anfang der Tage oder Ende der Jahre."},{"verse":18,"text":"Und der Herr bestätigte auch auf Aaron und seine Nachkommen, durch alle ihre Generationen, ein Priestertum, und dieses Priestertum besteht ebenfalls fort und verbleibt immerdar bei dem Priestertum, das nach der heiligsten Ordnung Gottes ist."},{"verse":19,"text":"Und dieses größere Priestertum vollzieht das Evangelium und hat den Schlüssel der Geheimnisse des Reiches inne, nämlich den Schlüssel der Gotteserkenntnis."},{"verse":20,"text":"Darum wird in seinen Verordnungen die Macht des Göttlichen kundgetan."},{"verse":21,"text":"Und ohne seine Verordnungen und die Vollmacht des Priestertums wird die Macht des Göttlichen den Menschen im Fleische nicht kundgetan;"},{"verse":22,"text":"denn ohne dies kann kein Mensch das Angesicht Gottes, nämlich des Vaters, sehen und leben."},{"verse":23,"text":"Dies nun lehrte Mose die Kinder Israel in der Wildnis in klarer Weise und trachtete eifrig danach, sein Volk zu heiligen, damit es das Angesicht Gottes sehen könnte;"},{"verse":24,"text":"aber es verhärtete sein Herz und konnte seine Gegenwart nicht ertragen; darum schwor der Herr in seinem Grimm, denn sein Zorn war gegen es entflammt, es sollte, solange es in der Wildnis sei, nicht in seine Ruhe eintreten, und diese Ruhe ist die Fülle seiner Herrlichkeit."},{"verse":25,"text":"Darum nahm er Mose aus ihrer Mitte, ebenso auch das Heilige Priestertum;"},{"verse":26,"text":"und das geringere Priestertum bestand fort, und dieses Priestertum hat den Schlüssel des Dienstes von Engeln und des vorbereitenden Evangeliums inne;"},{"verse":27,"text":"und dieses Evangelium ist das Evangelium der Umkehr und der Taufe und der Sündenvergebung und das Gesetz der fleischlichen Gebote, das der Herr in seinem Grimm unter den Kindern Israel im Haus Aaron fortbestehen ließ bis Johannes, den Gott erweckte und der von Mutterleib an vom Heiligen Geist erfüllt war."},{"verse":28,"text":"Denn er wurde getauft, als er noch in seiner Kindheit war, und wurde vom Engel Gottes, zu der Zeit, da er acht Tage alt war, zu dieser Macht ordiniert, um das Reich der Juden zu stürzen und um dem Herrn vor dem Angesicht seines Volkes den Weg geradezumachen, um es auf das Kommen des Herrn vorzubereiten, in dessen Hand alle Macht gegeben ist."},{"verse":29,"text":"Und weiter: Das Amt des Ältesten und das des Bischofs sind notwendige Beigaben, die zum Hohen Priestertum gehören."},{"verse":30,"text":"Und weiter: Das Amt des Lehrers und das des Diakons sind notwendige Beigaben, die zum geringeren Priestertum gehören, und dieses Priestertum wurde auf Aaron und seine Söhne bestätigt."},{"verse":31,"text":"Darum, wie ich in Bezug auf die Söhne Moses gesprochen habe – denn die Söhne Moses und auch die Söhne Aarons sollen ein annehmbares Opfer darbringen und eine Gabe im Haus des Herrn; und das Haus soll dem Herrn in dieser Generation auf dem geweihten Platz erbaut werden, wie ich es bestimmt habe –"},{"verse":32,"text":"und die Söhne Moses und Aarons werden mit der Herrlichkeit des Herrn erfüllt werden auf dem Berg Zion im Haus des Herrn, und deren Söhne seid ihr; und auch viele, die ich berufen und ausgesandt habe, meine Kirche aufzubauen."},{"verse":33,"text":"Denn diejenigen, die treu sind, sodass sie diese zwei Priestertümer erlangen, von denen ich gesprochen habe, und ihre Berufung groß machen, werden vom Geist geheiligt, sodass sich ihr Körper erneuern wird."},{"verse":34,"text":"Sie werden Söhne Moses und Aarons und Nachkommen Abrahams und die Kirche und das Reich und die Auserwählten Gottes."},{"verse":35,"text":"Und alle, die dieses Priestertum empfangen, die empfangen auch mich, spricht der Herr;"},{"verse":36,"text":"denn wer meine Diener empfängt, der empfängt mich;"},{"verse":37,"text":"und wer mich empfängt, der empfängt meinen Vater;"},{"verse":38,"text":"und wer meinen Vater empfängt, der empfängt meines Vaters Reich; darum wird ihm alles gegeben werden, was mein Vater hat."},{"verse":39,"text":"Und dies ist gemäß dem Eid und Bund, der zum Priestertum gehört."},{"verse":40,"text":"Darum: Alle diejenigen, die das Priestertum empfangen, die empfangen diesen Eid und Bund meines Vaters, den er nicht brechen kann und der unverrückbar ist."},{"verse":41,"text":"Wer aber diesen Bund bricht, nachdem er ihn empfangen hat, und sich gänzlich davon abwendet, der wird weder in dieser Welt noch in der künftigen Welt Vergebung der Sünden erlangen."},{"verse":42,"text":"Und weh all denen, die nicht zu diesem Priestertum kommen, das ihr empfangen habt, das ich jetzt auf euch, die ihr heute anwesend seid, durch meine eigene Stimme aus den Himmeln bestätige; und ich selbst habe den himmlischen Scharen und meinen Engeln in Bezug auf euch Verantwortung übertragen."},{"verse":43,"text":"Und nun gebe ich euch das Gebot, achtzuhaben in Bezug auf euch selbst und den Worten des ewigen Lebens eifrig Beachtung zu schenken."},{"verse":44,"text":"Denn ihr sollt von jedem Wort leben, das aus dem Mund Gottes hervorkommt."},{"verse":45,"text":"Denn das Wort des Herrn ist Wahrheit, und was auch immer Wahrheit ist, das ist Licht, und was auch immer Licht ist, das ist Geist, ja, der Geist Jesu Christi."},{"verse":46,"text":"Und der Geist gibt jedem Menschen, der in die Welt kommt, Licht; und der Geist erleuchtet jeden Menschen auf der Welt, der auf die Stimme des Geistes hört."},{"verse":47,"text":"Und jeder, der auf die Stimme des Geistes hört, kommt hin zu Gott, nämlich dem Vater."},{"verse":48,"text":"Und der Vater belehrt ihn über den Bund, den er erneuert und auf euch bestätigt hat, der um euretwillen auf euch bestätigt ist, und nicht allein um euretwillen, sondern um der ganzen Welt willen."},{"verse":49,"text":"Und die ganze Welt liegt in Sünde und stöhnt unter Finsternis und unter der Knechtschaft der Sünde."},{"verse":50,"text":"Und dass sie unter der Knechtschaft der Sünde sind, könnt ihr daran erkennen, dass sie nicht zu mir kommen."},{"verse":51,"text":"Denn wer nicht zu mir kommt, der ist unter der Knechtschaft der Sünde."},{"verse":52,"text":"Und wer meine Stimme nicht empfängt, der kennt meine Stimme nicht und ist nicht von mir."},{"verse":53,"text":"Und daran könnt ihr die Rechtschaffenen von den Schlechten unterscheiden und wissen, dass die ganze Welt eben jetzt unter Sünde und Finsternis stöhnt."},{"verse":54,"text":"Und euer Verstand ist in der Vergangenheit verfinstert gewesen wegen Unglaubens und weil ihr mit dem, was ihr empfangen habt, leichtfertig umgegangen seid –"},{"verse":55,"text":"und diese Eitelkeit und Ungläubigkeit haben die ganze Kirche unter Schuldspruch gebracht."},{"verse":56,"text":"Und dieser Schuldspruch liegt auf den Kindern Zion, ja, auf allen."},{"verse":57,"text":"Und sie werden unter diesem Schuldspruch verbleiben, bis sie umkehren und sich an den neuen Bund erinnern, nämlich das Buch Mormon und die bisherigen Gebote, die ich ihnen gegeben habe, und nicht nur reden, sondern gemäß dem, was ich geschrieben habe, handeln –"},{"verse":58,"text":"damit sie Frucht hervorbringen, die dem Reich ihres Vaters angemessen ist; andernfalls verbleibt eine Geißel und ein Strafgericht, das über die Kinder Zion ausgegossen werden soll."},{"verse":59,"text":"Denn sollen die Kinder des Reiches mein heiliges Land verunreinigen? Wahrlich, ich sage euch: Nein."},{"verse":60,"text":"Wahrlich, wahrlich, ich sage euch, die ihr jetzt meine Worte vernehmt, und das ist meine Stimme: Gesegnet seid ihr, insoweit ihr dies empfangt;"},{"verse":61,"text":"denn ich will euch eure Sünden mit diesem Gebot vergeben: dass ihr standhaft bleibt in eurem Sinn, voll ernster Besinnung und im Geist des Betens, und indem ihr aller Welt Zeugnis gebt für all jenes, was euch mitgeteilt wird."},{"verse":62,"text":"Darum geht hin in alle Welt; und zu jedwedem Ort, wo ihr nicht hingehen könnt, da sendet hin, damit das Zeugnis von euch ausgehe in alle Welt, zu jedem Geschöpf."},{"verse":63,"text":"Und wie ich zu meinen Aposteln gesprochen habe, so spreche ich auch zu euch, denn ihr seid meine Apostel, ja, Gottes Hohe Priester; ihr seid es, die mein Vater mir gegeben hat; ihr seid meine Freunde;"},{"verse":64,"text":"darum, wie ich zu meinen Aposteln gesprochen habe, so spreche ich abermals zu euch: Jede Seele, die an eure Worte glaubt und sich zur Sündenvergebung im Wasser taufen lässt, wird den Heiligen Geist empfangen."},{"verse":65,"text":"Und diese Zeichen werden denen folgen, die da glauben:"},{"verse":66,"text":"In meinem Namen werden sie viele wunderbare Werke tun;"},{"verse":67,"text":"in meinem Namen werden sie Teufel austreiben;"},{"verse":68,"text":"in meinem Namen werden sie die Kranken heilen;"},{"verse":69,"text":"in meinem Namen werden sie den Blinden die Augen öffnen und den Tauben die Ohren freimachen;"},{"verse":70,"text":"und die Zunge der Stummen wird reden;"},{"verse":71,"text":"und wenn ihnen jemand Gift verabreicht, so wird es ihnen nicht schaden;"},{"verse":72,"text":"und Schlangengift wird keine Macht haben, ihnen Leid anzutun."},{"verse":73,"text":"Aber ein Gebot gebe ich ihnen, dass sie damit nicht über sich prahlen, auch nicht vor der Welt darüber reden sollen; denn dies alles ist euch zu eurem Nutzen und zur Errettung gegeben."},{"verse":74,"text":"Wahrlich, wahrlich, ich sage euch: Diejenigen, die nicht an eure Worte glauben und sich nicht zur Vergebung ihrer Sünden in meinem Namen im Wasser taufen lassen, um den Heiligen Geist empfangen zu können, werden verdammt werden und werden nicht in meines Vaters Reich kommen, wo mein Vater und ich sind."},{"verse":75,"text":"Und diese Offenbarung an euch und dieses Gebot sind von genau dieser Stunde an auf der ganzen Welt in Kraft, und das Evangelium ergeht an alle, die es nicht empfangen haben."},{"verse":76,"text":"Aber wahrlich, ich sage allen, denen das Reich gegeben worden ist: Von euch muss es ihnen gepredigt werden, damit sie von ihren bisherigen bösen Werken umkehren; denn sie müssen wegen ihres bösen, ungläubigen Herzens zurechtgewiesen werden, ebenso eure Brüder in Zion wegen ihrer Auflehnung gegen euch, als ich euch hingesandt hatte."},{"verse":77,"text":"Und weiter sage ich euch, meinen Freunden, denn fortan werde ich euch Freunde nennen: Es ist ratsam, dass ich euch dies Gebot gebe, dass ihr so werdet wie meine Freunde in den Tagen, da ich bei ihnen war und reiste, um das Evangelium mit meiner Macht zu predigen;"},{"verse":78,"text":"denn ich ließ ihnen nicht zu, Beutel oder Tasche zu haben, auch keine zwei Röcke."},{"verse":79,"text":"Siehe, ich sende euch aus, die Welt zu prüfen, und der Arbeiter ist seines Lohnes wert."},{"verse":80,"text":"Und jeder, der hingeht und dieses Evangelium vom Reich predigt und nicht ablässt, weiterhin in allem treu zu sein, wird im Sinn nicht müde werden, auch nicht verfinstert, auch nicht im Leib, Glied und Gelenk; und kein Haar von seinem Haupt wird unbemerkt zu Boden fallen. Und sie werden weder hungrig sein noch durstig."},{"verse":81,"text":"Darum sorgt euch nicht für den morgigen Tag, was ihr essen werdet oder was ihr trinken werdet oder womit ihr euch kleiden werdet."},{"verse":82,"text":"Betrachtet doch die Lilien auf dem Feld, wie sie wachsen: Sie arbeiten nicht, auch spinnen sie nicht; und doch sind die Reiche der Welt in all ihrer Herrlichkeit nicht gekleidet wie eine von ihnen."},{"verse":83,"text":"Denn euer Vater, der im Himmel ist, weiß, dass ihr all dessen bedürft."},{"verse":84,"text":"Darum lasst den morgigen Tag für sich selbst sorgen."},{"verse":85,"text":"Sorgt euch auch nicht im Voraus, was ihr sagen sollt; sondern häuft in eurem Sinn beständig die Worte des Lebens auf wie einen Schatz, dann wird euch zur selben Stunde das Maß eingegeben werden, das einem jeden zugemessen werden soll."},{"verse":86,"text":"Darum lasst keinen unter euch – denn dieses Gebot ist für alle Getreuen, die von Gott in der Kirche zum geistlichen Dienst berufen sind –, der ausgeht, um dieses Evangelium vom Reich zu verkündigen, von dieser Stunde an Beutel oder Tasche mitnehmen."},{"verse":87,"text":"Siehe, ich sende euch aus, um die Welt für alle ihre unrechten Taten zurechtzuweisen und sie über ein Strafgericht zu belehren, das kommen wird."},{"verse":88,"text":"Und wo euch jemand empfängt, da werde ich auch sein, denn ich werde vor eurem Angesicht hergehen. Ich werde zu eurer rechten Hand sein und zu eurer linken, und mein Geist wird in eurem Herzen sein und meine Engel werden rings um euch sein, um euch zu stützen."},{"verse":89,"text":"Wer euch empfängt, der empfängt mich; und er wird euch speisen und euch kleiden und euch Geld geben."},{"verse":90,"text":"Und wer euch speist oder euch kleidet oder euch Geld gibt, wird keineswegs seines Lohnes verlustig gehen."},{"verse":91,"text":"Und wer das nicht tut, der ist nicht mein Jünger; daran könnt ihr meine Jünger erkennen."},{"verse":92,"text":"Wenn euch jemand nicht empfängt, so geht von ihm weg, für euch allein, und säubert eure Füße, ja, mit Wasser, reinem Wasser, es sei in Hitze oder in Kälte, und gebt eurem Vater, der im Himmel ist, dafür Zeugnis und kehrt nicht mehr zu jenem Menschen zurück."},{"verse":93,"text":"Und wo auch immer ihr in ein Dorf oder eine Stadt kommt, so tut desgleichen."},{"verse":94,"text":"Doch sucht eifrig und haltet nicht zurück; und weh jenem Haus oder jenem Dorf oder jener Stadt, wo man euch oder eure Worte oder euer Zeugnis in Bezug auf mich verwirft."},{"verse":95,"text":"Weh, sage ich abermals, jenem Haus oder jenem Dorf oder jener Stadt, wo man euch oder eure Worte oder euer Zeugnis für mich verwirft;"},{"verse":96,"text":"denn ich, der Allmächtige, habe meine Hände auf die Nationen gelegt, um sie für ihre Schlechtigkeit zu geißeln."},{"verse":97,"text":"Und Plagen werden ausgehen, und sie werden nicht von der Erde weggenommen werden, bis ich mein Werk vollendet habe, das in Rechtschaffenheit abgekürzt werden wird –"},{"verse":98,"text":"bis alle mich kennen werden, die verbleiben, selbst vom Geringsten bis zum Größten, und von der Erkenntnis des Herrn erfüllt sein werden und Aug in Auge sehen werden und ihre Stimme erheben werden und mit vereinter Stimme dieses neue Lied singen, nämlich:"},{"verse":99,"text":"Der Herr hat Zion wiedergebracht;der Herr hat sein Volk, Israel, erlöstgemäß der Auserwählung durch Gnade,die zustande gebracht wurde durch den Glaubenund den Bund ihrer Väter."},{"verse":100,"text":"Der Herr hat sein Volk erlöst,und der Satan ist gebunden, und Zeit ist nicht mehr.Der Herr hat alles in eins zusammengeführt.Der Herr hat Zion von oben herniedergebracht.Der Herr hat Zion von unten heraufgebracht."},{"verse":101,"text":"Die Erde hat gekreißt und ihre Kraft hervorgebracht;und Wahrheit ist in ihrem Inneren vorhanden;und die Himmel haben ihr zugelächelt,und sie ist bekleidet mit der Herrlichkeit ihres Gottes;denn er steht inmitten seines Volkes."},{"verse":102,"text":"Herrlichkeit und Ehre und Macht und Kraftseien unserem Gotte zugeschrieben; denn er ist voll Barmherzigkeit,Gerechtigkeit, Gnade und Wahrheit und Friedefür immer und immer. Amen."},{"verse":103,"text":"Und weiter, wahrlich, wahrlich, ich sage euch: Es ist ratsam, dass jeder Mann, der ausgeht, um mein immerwährendes Evangelium zu verkündigen, sofern er Familie hat und Geld geschenkt erhält, ihr dieses schickt oder zu ihrem Nutzen verwendet, wie der Herr ihn anweist; denn so scheint es mir gut."},{"verse":104,"text":"Und alle diejenigen, die keine Familie haben und die Geld empfangen, sollen es an den Bischof in Zion oder an den Bischof in Ohio senden, damit es für das Herausbringen der Offenbarungen und deren Druck sowie für die Errichtung Zions geweiht werde."},{"verse":105,"text":"Und wenn jemand einem von euch einen Rock oder einen Anzug schenkt, so nehmt euren alten und gebt ihn den Armen, und geht voll Freude eures Weges."},{"verse":106,"text":"Und wenn einer unter euch stark im Geist ist, so soll er den mit sich nehmen, der schwach ist, damit dieser in aller Sanftmut erbaut werde, damit auch er stark werde."},{"verse":107,"text":"Darum nehmt diejenigen mit euch, die zum geringeren Priestertum ordiniert sind, und sendet sie vor euch her, dass sie Vereinbarungen treffen und den Weg bereiten und Vereinbarungen erfüllen, die ihr selbst nicht erfüllen könnt."},{"verse":108,"text":"Siehe, auf diese Weise haben mir meine Apostel in alten Tagen meine Kirche aufgerichtet."},{"verse":109,"text":"Darum lasst einen jeden in seinem eigenen Amt stehen und in seiner eigenen Berufung arbeiten; und lasst das Haupt nicht zu den Füßen sagen, es habe die Füße nicht nötig; denn wie soll der Leib ohne die Füße imstande sein zu stehen?"},{"verse":110,"text":"Auch hat der Leib jedes Glied nötig, damit alle miteinander erbaut werden, damit das geordnete Gefüge vollkommen erhalten bleibe."},{"verse":111,"text":"Und siehe, die Hohen Priester sollen reisen, ebenso die Ältesten, ebenso die geringeren Priester; aber die Diakone und Lehrer sollen bestimmt werden, über die Mitglieder der Kirche zu wachen und ortsständige geistliche Diener für die Kirche zu sein."},{"verse":112,"text":"Und Newel K. Whitney, der Bischof, soll ebenfalls ringsum und zu allen Gemeinden reisen; er soll nach den Armen forschen und sich ihrer Bedürfnisse annehmen, indem er die Reichen und die Stolzen demütig macht."},{"verse":113,"text":"Er soll auch einen Beauftragten anstellen, der die Leitung übernimmt und ihm nach seiner Weisung die weltlichen Geschäfte besorgt."},{"verse":114,"text":"Doch soll der Bischof in die Stadt New York gehen, ebenso in die Stadt Albany und auch in die Stadt Boston, und die Menschen in jenen Städten mit dem Schall des Evangeliums, mit lauter Stimme, vor der Verwüstung und gänzlichen Vernichtung warnen, die sie erwartet, wenn sie dies alles verwerfen."},{"verse":115,"text":"Denn wenn sie dies alles verwerfen, so ist die Stunde ihres Gerichts nahe, und ihr Haus wird ihnen wüst gelassen werden."},{"verse":116,"text":"Er soll auf mich vertrauen, dann wird er nicht zuschanden werden, und kein Haar von seinem Haupt wird unbemerkt zu Boden fallen."},{"verse":117,"text":"Und wahrlich, ich sage euch, meinen übrigen Dienern: Geht aus, wie es euch die Umstände erlauben, in euren verschiedenen Berufungen, in die großen und ansehnlichen Städte und Dörfer, und weist mit Rechtschaffenheit die Welt wegen all ihrer unrechten und gottlosen Taten zurecht, und erläutert ihr deutlich und verständlich die Verwüstung durch den Gräuel in den letzten Tagen."},{"verse":118,"text":"Denn mit euch, so spricht der Herr, der Allmächtige, werde ich ihre Reiche niederreißen; ich werde nicht nur die Erde erschüttern, sondern auch die Sternenhimmel werden erzittern."},{"verse":119,"text":"Denn ich, der Herr, habe meine Hand ausgestreckt, um die Mächte des Himmels zu gebrauchen; noch könnt ihr es nicht sehen, aber noch eine kleine Weile, dann werdet ihr es sehen und werdet wissen, dass ich bin und dass ich kommen und mit meinem Volk regieren werde."},{"verse":120,"text":"Ich bin Alpha und Omega, der Anfang und das Ende. Amen."}]},{"chapter":85,"verses":[{"verse":1,"text":"Es ist die Pflicht des Schriftführers, den der Herr bestimmt hat, einen Geschichtsbericht und allgemeine Aufzeichnungen der Kirche über alles, was in Zion vorgeht, zu führen und über alle diejenigen, die Eigentum weihen und vom Bischof rechtsgültig Erbteile empfangen;"},{"verse":2,"text":"und auch ihren Lebenswandel, ihren Glauben und ihre Werke; und auch über die Abtrünnigen, die abtrünnig werden, nachdem sie ihr Erbteil empfangen haben."},{"verse":3,"text":"Es ist gegen den Willen und das Gebot Gottes, dass diejenigen, die ihr Erbteil nicht durch Weihung empfangen, in Übereinstimmung mit seinem Gesetz, das er gegeben hat, um sein Volk zu zehnten und es auf den Tag der Vergeltung und des Brennens vorzubereiten, beim Volk Gottes namentlich verzeichnet sind."},{"verse":4,"text":"Auch soll ihre Stammtafel nicht geführt werden, und sie soll nirgendwo in den Berichten oder der Geschichte der Kirche zu finden sein."},{"verse":5,"text":"Weder ihr Name noch der Name der Väter noch der Name der Kinder soll im Buch des Gesetzes Gottes geschrieben gefunden werden, spricht der Herr der Heerscharen."},{"verse":6,"text":"Ja, so spricht die leise, sanfte Stimme, die durch alles flüstert und alles durchdringt und die mich oftmals bis ins Gebein erbeben lässt, wenn sie etwas kundtut, nämlich:"},{"verse":7,"text":"Und es wird sich begeben: Ich, Gott, der Herr, werde einen senden, mächtig und stark, der das Zepter der Macht in seiner Hand hält, mit Licht bekleidet wie mit einem Mantel, dessen Mund Worte reden wird, ewige Worte; sein Inneres aber wird eine Quelle der Wahrheit sein, dass er das Haus Gottes in Ordnung bringe und die Grundstücke als Erbteil den Heiligen zuweise, deren Name im Buch des Gesetzes Gottes ebenso verzeichnet gefunden wird wie der Name ihrer Väter und der ihrer Kinder;"},{"verse":8,"text":"jener Mann hingegen, der von Gott berufen und bestimmt war, der seine Hand ausstreckt, um die Lade Gottes festzuhalten, wird durch den Pfeil des Todes fallen, so wie ein Baum, der von einem scharfen Blitzstrahl gefällt wird."},{"verse":9,"text":"Und alle diejenigen, die nicht im Buch der Erinnerung verzeichnet gefunden werden, werden an jenem Tag kein Erbteil finden, sondern sie werden in Stücke gehauen werden, und ihr Teil wird ihnen unter den Ungläubigen bestimmt werden, wo Wehklagen und Zähneknirschen sein wird."},{"verse":10,"text":"Dies spreche ich nicht aus mir selbst; was der Herr also spricht, das wird er auch erfüllen."},{"verse":11,"text":"Und diejenigen, die vom Hohen Priestertum sind, deren Name nicht im Buch des Gesetzes verzeichnet gefunden wird oder von denen man findet, dass sie abgefallen sind oder aus der Kirche ausgeschlossen worden sind, ebenso diejenigen vom geringeren Priestertum oder von den Mitgliedern, werden an jenem Tag kein Erbteil unter den Heiligen des Allerhöchsten finden;"},{"verse":12,"text":"darum soll ihnen geschehen wie den Kindern der Priester, wie man es im zweiten Kapitel Esra in Vers ein- und zweiundsechzig aufgezeichnet findet."}]},{"chapter":86,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr zu euch, meine Diener, über das Gleichnis vom Weizen und vom Unkraut:"},{"verse":2,"text":"Siehe, wahrlich, ich sage: Der Acker, das war die Welt, und die den Samen gesät haben, das waren die Apostel;"},{"verse":3,"text":"und nachdem sie entschlafen sind, ist der große Verfolger der Kirche, die Abtrünnige, die Hure, nämlich Babylon, die alle Nationen dazu gebracht hat, aus ihrem Becher zu trinken, in deren Herzen der Feind, nämlich der Satan, sitzt und regiert – siehe, er sät das Unkraut; darum erstickt das Unkraut den Weizen und treibt die Kirche in die Wildnis."},{"verse":4,"text":"Aber siehe, in den letzten Tagen, nämlich jetzt, da der Herr anfängt, das Wort hervorzubringen, und da der Halm hervorsprießt und noch zart ist –"},{"verse":5,"text":"siehe, wahrlich, ich sage euch: Tag und Nacht schreien die Engel zum Herrn; sie sind bereit und warten darauf, dass sie ausgesandt werden, um die Felder abzuernten;"},{"verse":6,"text":"aber der Herr spricht zu ihnen: Reißt das Unkraut nicht aus, solange der Halm noch zart ist (denn wahrlich, euer Glaube ist schwach), damit ihr nicht auch den Weizen vernichtet."},{"verse":7,"text":"Darum lasst den Weizen und das Unkraut miteinander wachsen, bis die Ernte ganz reif ist; dann sammelt zuerst den Weizen aus dem Unkraut, und wenn ihr den Weizen gesammelt habt, siehe, ja siehe, wird das Unkraut in Bündel gebunden, und dann bleibt noch übrig, das Feld abzubrennen."},{"verse":8,"text":"Darum, so spricht der Herr zu euch, bei denen das Priestertum durch die Linie eurer Väter fortbestanden hat –"},{"verse":9,"text":"denn ihr seid rechtmäßige Erben gemäß dem Fleische und seid mit Christus in Gott vor der Welt verborgen gewesen –"},{"verse":10,"text":"darum sind euer Leben und das Priestertum erhalten geblieben, und es muss notwendigerweise durch euch und eure Linie erhalten bleiben bis zur Wiederherstellung all dessen, was durch den Mund aller heiligen Propheten vom Anbeginn der Welt an gesprochen worden ist."},{"verse":11,"text":"Darum, gesegnet seid ihr, wenn ihr in meiner Güte verbleibt, ein Licht für die Anderen, und durch dieses Priestertum ein Erretter meinem Volk Israel. Der Herr hat es gesagt. Amen."}]},{"chapter":87,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr in Bezug auf die Kriege, die in Kürze eintreten werden, die mit der Auflehnung von South Carolina anfangen und schließlich mit dem Tod und Elend vieler Seelen enden werden;"},{"verse":2,"text":"und die Zeit wird kommen, dass Krieg über alle Nationen ausgegossen werden wird, und es wird an diesem Ort anfangen."},{"verse":3,"text":"Denn siehe, die Südstaaten werden sich gegen die Nordstaaten abspalten, und die Südstaaten werden andere Nationen anrufen, ja, die Nation Großbritannien, wie sie genannt wird, und sie werden auch andere Nationen anrufen, um sich gegen andere Nationen zu verteidigen; und dann wird Krieg über alle Nationen ausgegossen werden."},{"verse":4,"text":"Und es wird sich begeben: Nach vielen Tagen werden sich Sklaven gegen ihre Herren erheben, die für den Krieg geordnet und ausgebildet sein werden."},{"verse":5,"text":"Und es wird sich auch begeben: Die Überreste, die im Land übriggeblieben sind, werden sich ordnen und werden überaus zornig werden und werden die Anderen mit einer schweren Plage plagen."},{"verse":6,"text":"Und so, durch das Schwert und durch Blutvergießen, werden die Bewohner der Erde trauern; und durch Hungersnot und Plage und Erdbeben und den Donner des Himmels und auch das heftige und scharfe Blitzen werden die Bewohner der Erde den Grimm und den Unwillen und die züchtigende Hand eines allmächtigen Gottes zu spüren bekommen, bis die beschlossene Vernichtung allen Nationen ein völliges Ende bereitet hat;"},{"verse":7,"text":"damit der Schrei der Heiligen und des Blutes der Heiligen von der Erde her dem Herrn Zebaot nicht mehr in die Ohren heraufkomme, dass sie an ihren Feinden gerächt werden mögen."},{"verse":8,"text":"Darum steht an heiligen Stätten und wankt nicht, bis der Tag des Herrn kommt; denn siehe, er kommt schnell, spricht der Herr. Amen."}]},{"chapter":88,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr zu euch, die ihr euch versammelt habt, um seinen Willen in Bezug auf euch zu empfangen:"},{"verse":2,"text":"Siehe, dies gefällt eurem Herrn wohl, und die Engel freuen sich über euch; die Almosen eurer Gebete sind dem Herrn Zebaot in die Ohren heraufgekommen und werden ins Buch der Namen der Geheiligten eingetragen, nämlich derer von der celestialen Welt."},{"verse":3,"text":"Darum sende ich euch nun einen anderen Tröster, nämlich euch, meinen Freunden, dass er in eurem Herzen verbleibe, nämlich den Heiligen Geist der Verheißung; und dieser andere Tröster ist derselbe, den ich meinen Jüngern verheißen habe, wie es im Zeugnis des Johannes aufgezeichnet ist."},{"verse":4,"text":"Dieser Tröster ist die Verheißung, die ich euch vom ewigen Leben gebe, ja, von der Herrlichkeit des celestialen Reiches;"},{"verse":5,"text":"und diese Herrlichkeit ist die der Kirche des Erstgeborenen, ja, Gottes, des Heiligsten von allen, durch Jesus Christus, seinen Sohn –"},{"verse":6,"text":"er, der in die Höhe aufgefahren ist, wie er auch hinabgefahren ist unter alles, sodass er alles erfasst hat, auf dass er in allem sei und alles durchdringe, das Licht der Wahrheit;"},{"verse":7,"text":"und diese Wahrheit leuchtet. Dies ist das Licht Christi. So ist er auch in der Sonne und das Licht der Sonne und die Macht davon, wodurch sie gemacht worden ist."},{"verse":8,"text":"So ist er auch im Mond und ist das Licht des Mondes und die Macht davon, wodurch dieser gemacht worden ist,"},{"verse":9,"text":"so auch das Licht der Sterne und die Macht davon, wodurch sie gemacht worden sind,"},{"verse":10,"text":"und auch der Erde und die Macht davon, nämlich der Erde, worauf ihr steht."},{"verse":11,"text":"Und das Licht, das leuchtet und euch Licht gibt, ist durch ihn, der euch die Augen erleuchtet, und das ist dasselbe Licht, das euch das Verständnis belebt;"},{"verse":12,"text":"dieses Licht geht von der Gegenwart Gottes aus und erfüllt die Unermesslichkeit des Raumes –"},{"verse":13,"text":"das Licht, das in allem ist, das allem Leben gibt, das das Gesetz ist, wodurch alles regiert wird, ja, die Macht Gottes, der auf seinem Thron sitzt, der im Schoß der Ewigkeit ist, der inmitten von allem ist."},{"verse":14,"text":"Nun, wahrlich, ich sage euch: Durch die Erlösung, die für euch bewirkt worden ist, wird die Auferstehung von den Toten zustande gebracht."},{"verse":15,"text":"Und der Geist und der Körper sind die Seele des Menschen."},{"verse":16,"text":"Und die Auferstehung von den Toten ist die Erlösung der Seele."},{"verse":17,"text":"Und die Erlösung der Seele kommt durch ihn, der alles belebt, in dessen Herzen es beschlossen ist, dass die Armen und die Sanftmütigen der Erde sie ererben sollen."},{"verse":18,"text":"Darum muss sie notwendigerweise von allem Unrecht geheiligt werden, damit sie für die celestiale Herrlichkeit vorbereitet werde;"},{"verse":19,"text":"denn nachdem sie das Maß ihrer Erschaffung erfüllt hat, wird sie mit Herrlichkeit gekrönt werden, selbst mit der Gegenwart Gottes des Vaters,"},{"verse":20,"text":"damit Körper, die vom celestialen Reich sind, sie für immer und immer besitzen können; denn zu diesem Zweck ist sie gemacht und erschaffen worden, und zu diesem Zweck werden sie geheiligt."},{"verse":21,"text":"Und diejenigen, die nicht durch das Gesetz geheiligt sind, das ich euch gegeben habe, nämlich das Gesetz Christi, müssen ein anderes Reich ererben, nämlich das eines terrestrialen Reiches oder das eines telestialen Reiches."},{"verse":22,"text":"Denn wer nicht imstande ist, sich an das Gesetz eines celestialen Reiches zu halten, kann nicht in einer celestialen Herrlichkeit leben."},{"verse":23,"text":"Und wer sich nicht an das Gesetz eines terrestrialen Reiches halten kann, kann nicht in einer terrestrialen Herrlichkeit leben."},{"verse":24,"text":"Und wer sich nicht an das Gesetz eines telestialen Reiches halten kann, kann nicht in einer telestialen Herrlichkeit leben; darum ist er für ein Reich der Herrlichkeit nicht tauglich. Darum muss er in einem Reich leben, das kein Reich der Herrlichkeit ist."},{"verse":25,"text":"Und weiter, wahrlich, ich sage euch: Die Erde hält sich an das Gesetz eines celestialen Reiches, denn sie erfüllt das Maß ihrer Erschaffung und übertritt das Gesetz nicht –"},{"verse":26,"text":"darum wird sie geheiligt werden; ja, wenn sie auch sterben wird, so wird sie doch wieder belebt werden und wird in der Macht leben, womit sie belebt wird, und die Rechtschaffenen werden sie ererben."},{"verse":27,"text":"Denn wenn sie auch sterben, so werden sie doch wiederauferstehen, ein geistiger Körper."},{"verse":28,"text":"Diejenigen, die von einem celestialen Geist sind, werden denselben Körper empfangen, der ein natürlicher Körper war; ja, ihr werdet euren Körper empfangen, und eure Herrlichkeit wird diejenige Herrlichkeit sein, womit euer Körper belebt ist."},{"verse":29,"text":"Ihr, die ihr durch einen Teil der celestialen Herrlichkeit belebt seid, werdet dann davon empfangen, und zwar eine Fülle."},{"verse":30,"text":"Und diejenigen, die durch einen Teil der terrestrialen Herrlichkeit belebt sind, werden dann davon empfangen, und zwar eine Fülle."},{"verse":31,"text":"Und auch diejenigen, die durch einen Teil der telestialen Herrlichkeit belebt sind, werden dann davon empfangen, und zwar eine Fülle."},{"verse":32,"text":"Und diejenigen, die übrigbleiben, werden ebenfalls belebt werden; doch werden sie wieder an ihren eigenen Platz zurückkehren, um sich dessen zu erfreuen, was sie bereit sind zu empfangen, weil sie nicht bereit waren, sich dessen zu erfreuen, was sie hätten empfangen können."},{"verse":33,"text":"Denn was nützt es dem Menschen, wenn ihm eine Gabe gewährt wird, und er empfängt die Gabe nicht? Siehe, er freut sich nicht über das, was ihm gegeben wird, noch freut er sich über den, der die Gabe gibt."},{"verse":34,"text":"Und weiter, wahrlich, ich sage euch: Was durch Gesetz regiert wird, das wird auch durch Gesetz bewahrt und durch dasselbe vollkommen gemacht und geheiligt."},{"verse":35,"text":"Was aber ein Gesetz bricht und sich nicht an das Gesetz hält, sondern danach trachtet, für sich selbst ein Gesetz zu werden, und in Sünde leben will und ganz und gar in Sünde lebt, das kann weder durch Gesetz noch durch Barmherzigkeit, Gerechtigkeit noch Richterspruch geheiligt werden. Darum müssen sie weiterhin schmutzig bleiben."},{"verse":36,"text":"Allen Reichen ist ein Gesetz gegeben;"},{"verse":37,"text":"und es gibt viele Reiche; denn es gibt keinen Raum, worin es nicht ein Reich gäbe; und es gibt kein Reich, worin es keinen Raum gäbe, sei es ein größeres oder ein geringeres Reich."},{"verse":38,"text":"Und jedem Reich ist ein Gesetz gegeben; und zu jedem Gesetz gibt es auch gewisse Grenzen und Bedingungen."},{"verse":39,"text":"Alle Wesen, die sich nicht an jene Bedingungen halten, werden nicht gerechtfertigt."},{"verse":40,"text":"Denn Intelligenz hält fest an Intelligenz; Weisheit empfängt Weisheit; Wahrheit nimmt Wahrheit an; Tugend liebt Tugend; Licht hält fest an Licht; Barmherzigkeit hat Mitleid mit Barmherzigkeit und beansprucht die Ihren; Gerechtigkeit nimmt weiter ihren Lauf und beansprucht die Ihren; Richterspruch geht vor dem Angesicht dessen her, der auf dem Thron sitzt und alles regiert und vollbringt."},{"verse":41,"text":"Er erfasst alles, und alles ist vor ihm, und alles ist rings um ihn; und er ist über allem und in allem und ist durch alles und ist rings um alles; und alles ist durch ihn und von ihm, nämlich Gott, für immer und immer."},{"verse":42,"text":"Und weiter, wahrlich, ich sage euch: Er hat allen Dingen ein Gesetz gegeben, durch das sie sich in ihren Zeiten und ihren Jahreszeiten bewegen;"},{"verse":43,"text":"und ihre Bahnen sind festgelegt, nämlich die Bahnen der Himmel und der Erde, wodurch die Erde und alle Planeten erfasst sind."},{"verse":44,"text":"Und sie geben einander Licht in ihren Zeiten und in ihren Jahreszeiten, in ihren Minuten, in ihren Stunden, in ihren Tagen, in ihren Wochen, in ihren Monaten, in ihren Jahren – und sie alle sind ein Jahr für Gott, nicht aber für den Menschen."},{"verse":45,"text":"Die Erde rollt auf ihren Flügeln, und die Sonne gibt ihr Licht bei Tag, und der Mond gibt sein Licht bei Nacht, und die Sterne geben ebenfalls ihr Licht, wenn sie in ihrer Herrlichkeit inmitten der Macht Gottes auf ihren Flügeln rollen."},{"verse":46,"text":"Womit soll ich diese Reiche vergleichen, damit ihr es versteht?"},{"verse":47,"text":"Siehe, diese alle sind Reiche, und ein Mensch, der eines oder das Geringste davon gesehen hat, hat Gott gesehen, wie er sich in seiner Majestät und Macht bewegt."},{"verse":48,"text":"Ich sage euch: Er hat ihn gesehen; doch er, der zu den Seinen kam, wurde nicht erfasst."},{"verse":49,"text":"Das Licht leuchtet in der Finsternis, und die Finsternis erfasst es nicht; doch der Tag wird kommen, da ihr selbst Gott erfassen werdet, denn ihr werdet in ihm und durch ihn belebt sein."},{"verse":50,"text":"Dann werdet ihr wissen, dass ihr mich gesehen habt, dass ich bin und dass ich das wahre Licht bin, das in euch ist, und dass ihr in mir seid; sonst könntet ihr nicht gedeihen."},{"verse":51,"text":"Siehe, ich will diese Reiche mit einem Mann vergleichen, der einen Acker hatte; und er sandte seine Diener auf den Acker, den Acker umzugraben."},{"verse":52,"text":"Und er sprach zum ersten: Gehe hin und arbeite auf dem Acker, und zur ersten Stunde werde ich zu dir kommen, und du wirst die Freude meines Angesichts schauen."},{"verse":53,"text":"Und er sprach zum zweiten: Gehe auch hin auf den Acker, und zur zweiten Stunde werde ich dich mit der Freude meines Angesichts besuchen."},{"verse":54,"text":"Und auch zum dritten, nämlich: Ich werde dich besuchen;"},{"verse":55,"text":"und zum vierten, und so weiter bis zum zwölften."},{"verse":56,"text":"Und der Herr des Ackers ging in der ersten Stunde zum ersten und blieb die ganze Stunde bei ihm, und er wurde durch das Licht des Angesichts seines Herrn erfreut."},{"verse":57,"text":"Und dann zog er sich vom ersten zurück, um auch den zweiten zu besuchen und den dritten und den vierten und so weiter bis zum zwölften."},{"verse":58,"text":"Und so empfingen sie alle das Licht des Angesichts ihres Herrn, ein jeder zu seiner Stunde und zu seiner Zeit und zu seiner Zeitspanne –"},{"verse":59,"text":"angefangen beim ersten und so weiter bis zum letzten, und vom letzten bis zum ersten, und vom ersten bis zum letzten –,"},{"verse":60,"text":"ein jeder in seiner Ordnung, bis seine Stunde zu Ende war, ja, so wie es ihm sein Herr geboten hatte, damit sein Herr in ihm verherrlicht werde und er in seinem Herrn, damit sie alle verherrlicht würden."},{"verse":61,"text":"Darum will ich alle diese Reiche und ihre Bewohner mit diesem Gleichnis vergleichen – ein jedes Reich zu seiner Stunde und zu seiner Zeit und zu seiner Zeitspanne, ja, gemäß dem Beschluss, den Gott gefasst hat."},{"verse":62,"text":"Und weiter, wahrlich, ich sage euch, meine Freunde: Diese Worte lasse ich bei euch, damit ihr im Herzen darüber nachdenkt, mit diesem Gebot, das ich euch gebe, dass ihr mich anruft, solange ich nahe bin –"},{"verse":63,"text":"naht euch mir, und ich werde mich euch nahen; sucht mich eifrig, dann werdet ihr mich finden; bittet, und ihr werdet empfangen; klopfet an, und es wird euch aufgetan werden."},{"verse":64,"text":"Was auch immer ihr den Vater in meinem Namen bittet, das wird euch gegeben werden, was für euch ratsam ist;"},{"verse":65,"text":"und wenn ihr um etwas bittet, was für euch nicht ratsam ist, so wird sich das zu eurer Schuldigsprechung wenden."},{"verse":66,"text":"Siehe, das, was ihr vernehmt, ist wie die Stimme eines Rufers in der Wildnis – in der Wildnis, weil ihr ihn nicht sehen könnt –, meine Stimme, weil meine Stimme Geist ist; mein Geist ist Wahrheit; die Wahrheit verbleibt und hat kein Ende, und wenn sie in euch ist, so wird sie reichlich vorhanden sein."},{"verse":67,"text":"Und wenn euer Auge nur auf meine Herrlichkeit gerichtet ist, so wird euer ganzer Leib mit Licht erfüllt werden, und es wird in euch keine Finsternis sein; und jener Leib, der mit Licht erfüllt ist, erfasst alles."},{"verse":68,"text":"Darum heiligt euch, damit euer Sinn nur auf Gott gerichtet sei, dann werden die Tage kommen, da ihr ihn sehen werdet; denn er wird für euch den Schleier von seinem Angesicht nehmen, und es wird zu seiner eigenen Zeit sein und auf seine eigene Weise und gemäß seinem eigenen Willen."},{"verse":69,"text":"Denkt an die große und letzte Verheißung, die ich euch gegeben habe; werft eure müßigen Gedanken und euer übermäßiges Gelächter weit weg von euch."},{"verse":70,"text":"Verweilt, verweilt an diesem Ort, und beruft eine feierliche Versammlung ein, nämlich derjenigen, die die ersten Arbeiter in diesem letzten Reich sind."},{"verse":71,"text":"Und lasst diejenigen, die von ihnen während ihrer Reisen gewarnt worden sind, den Herrn anrufen und eine kurze Zeit lang in ihrem Herzen über die Warnung nachdenken, die sie empfangen haben."},{"verse":72,"text":"Siehe, ja siehe, ich werde mich eurer Herden annehmen und werde Älteste erwecken und zu ihnen senden."},{"verse":73,"text":"Siehe, ich werde mein Werk in seiner Zeit beschleunigen."},{"verse":74,"text":"Und ich gebe euch, die ihr die ersten Arbeiter in diesem letzten Reich seid, ein Gebot: Versammelt euch und organisiert euch und macht euch bereit und heiligt euch; ja, macht euer Herz rein, und säubert eure Hände und eure Füße vor mir, damit ich euch reinigen kann;"},{"verse":75,"text":"damit ich eurem Vater und eurem Gott und meinem Gott bezeugen kann, dass ihr rein seid vom Blut dieser schlechten Generation; damit ich diese Verheißung erfüllen kann, diese große und letzte Verheißung, die ich euch gegeben habe, wann ich will."},{"verse":76,"text":"Auch gebe ich euch das Gebot, von dieser Zeit an mit Beten und Fasten fortzufahren."},{"verse":77,"text":"Und ich gebe euch das Gebot, einander die Lehre des Reiches zu lehren."},{"verse":78,"text":"Lehrt eifrig, und meine Gnade wird mit euch sein, damit ihr noch vollkommener unterwiesen seiet in Theorie, in Grundsätzlichem, in der Lehre, im Gesetz des Evangeliums, in allem, was das Reich Gottes betrifft und was ratsam ist, dass ihr es versteht;"},{"verse":79,"text":"in dem, was sowohl im Himmel als auch auf der Erde und unter der Erde ist; dem, was gewesen ist, dem, was ist, dem, was sich in Kürze begeben muss; dem, was daheim ist, dem, was in der Fremde ist; den Kriegen und den Verwirrungen der Nationen und den Strafgerichten, die auf dem Lande lasten; und auch einer Kenntnis von Ländern und von Reichen –"},{"verse":80,"text":"damit ihr in allem bereit seiet, wenn ich euch abermals aussende, um die Berufung, zu der ich euch berufen habe, und die Mission, mit der ich euch beauftragt habe, groß zu machen."},{"verse":81,"text":"Siehe, ich habe euch ausgesandt, Zeugnis zu geben und die Menschen zu warnen; und einem jeden, der gewarnt worden ist, kommt es zu, seinen Nächsten zu warnen."},{"verse":82,"text":"Darum haben sie keine Entschuldigung mehr, und ihre Sünden sind auf ihrem eigenen Haupt."},{"verse":83,"text":"Wer mich frühe sucht, der wird mich finden und wird nicht verlassen sein."},{"verse":84,"text":"Darum verweilt und arbeitet eifrig, damit ihr vollkommener werdet in eurem geistlichen Dienst, um zum letzten Mal zu den Anderen hinzugehen, alle, die der Mund des Herrn benennen wird, um das Gesetz zuzubinden und das Zeugnis zu versiegeln und um die Heiligen für die kommende Stunde des Gerichts bereitzumachen,"},{"verse":85,"text":"damit ihre Seele dem Grimm Gottes entrinnen möge, der Verwüstung durch den Gräuel, die die Schlechten erwartet, in dieser Welt ebenso wie in der künftigen Welt. Wahrlich, ich sage euch: Lasst diejenigen, die nicht die ersten Ältesten sind, im Weingarten weiterarbeiten, bis der Mund des Herrn sie rufen wird, denn ihre Zeit ist noch nicht gekommen; ihr Gewand ist nicht rein vom Blut dieser Generation."},{"verse":86,"text":"Verbleibt in der Freiheit, womit ihr frei gemacht seid, verstrickt euch nicht in Sünde, sondern lasst eure Hände rein sein, bis der Herr kommt."},{"verse":87,"text":"Denn nicht mehr viele Tage, und die Erde wird zittern und hin und her wanken wie ein Betrunkener; und die Sonne wird ihr Angesicht verbergen und wird sich weigern, Licht zu geben; und der Mond wird in Blut gebadet sein; und die Sterne werden überaus zornig werden und werden sich herabstürzen wie eine Feige, die von einem Feigenbaum herabfällt."},{"verse":88,"text":"Und nach eurem Zeugnis kommen Grimm und Unwille über das Volk."},{"verse":89,"text":"Denn nach eurem Zeugnis kommt das Zeugnis von Erdbeben, das Stöhnen in ihrem Innern verursachen wird, und die Menschen werden zu Boden fallen und werden nicht imstande sein zu stehen."},{"verse":90,"text":"Und es kommt auch das Zeugnis durch die Stimme von Donnern und die Stimme von Blitzen und die Stimme von Unwettern und die Stimme von Meereswogen, die sich über ihre Grenzen hinaus erheben werden."},{"verse":91,"text":"Und alles wird in Aufruhr sein; und gewiss wird den Menschen das Herz aussetzen, denn Furcht wird über alles Volk kommen."},{"verse":92,"text":"Und Engel werden mitten durch den Himmel fliegen und, indem sie die Posaune Gottes ertönen lassen, mit lauter Stimme rufen, nämlich: Macht euch bereit, macht euch bereit, o ihr Bewohner der Erde; denn das Gericht unseres Gottes ist gekommen. Siehe, ja siehe, der Bräutigam kommt; geht aus, ihm entgegen."},{"verse":93,"text":"Und sogleich wird ein großes Zeichen am Himmel erscheinen, und alles Volk wird es miteinander sehen."},{"verse":94,"text":"Und noch ein Engel wird seine Posaune ertönen lassen, nämlich: Jene große Kirche, die Mutter der Gräuel, die alle Nationen dazu gebracht hat, vom Wein des Zornes ihrer Unzucht zu trinken, die die Heiligen Gottes verfolgt, die deren Blut vergoss – sie, die an vielen Wassern sitzt und auf den Inseln des Meeres –, siehe, sie ist das Unkraut der Erde; sie wird in Bündel gebunden, ihre Bande werden stark gemacht, kein Mensch kann sie lösen; darum ist sie zum Verbrennen bereit. Und er wird seine Posaune lang und auch laut ertönen lassen, und alle Nationen werden es hören."},{"verse":95,"text":"Und es wird über den Zeitraum einer halben Stunde hinweg Stille sein im Himmel; und sogleich danach wird der Vorhang des Himmels entfaltet werden, wie eine Schriftrolle entfaltet wird, nachdem sie zusammengerollt war, und vom Angesicht des Herrn wird der Schleier weggenommen werden;"},{"verse":96,"text":"und die Heiligen, die auf Erden sind, die am Leben sind, werden belebt und entrückt werden, ihm zu begegnen."},{"verse":97,"text":"Und die in ihren Gräbern geschlafen haben, werden hervorkommen, denn ihre Gräber werden sich öffnen; und auch sie werden entrückt werden, um ihm in der Mitte der Himmelssäule zu begegnen –"},{"verse":98,"text":"sie gehören Christus: die Erstlingsgabe, diejenigen, die als Erste mit ihm herniedersteigen werden, und diejenigen, die auf Erden und in ihren Gräbern sind, die zuerst entrückt werden, um ihm zu begegnen; und das alles, wenn der Engel Gottes die Stimme der Posaune ertönen lassen wird."},{"verse":99,"text":"Und danach wird noch ein Engel ertönen lassen, nämlich die zweite Posaune; und dann kommt die Erlösung derer, die Christus bei seinem Kommen gehören, die ihr Teil in jenem Gefängnis empfangen haben, das für sie bereitet ist, damit sie das Evangelium empfangen und den Menschen gemäß nach dem Fleisch gerichtet werden können."},{"verse":100,"text":"Und weiter, noch eine Posaune wird ertönen, und das ist die dritte Posaune; und dann kommen die Geister der Menschen, die gerichtet werden sollen und unter Schuldigsprechung befunden werden;"},{"verse":101,"text":"und dies sind die übrigen Toten, und sie werden nicht wieder lebendig, bis die tausend Jahre zu Ende sind, auch weiter nicht bis zum Ende der Erde."},{"verse":102,"text":"Und noch eine Posaune wird ertönen, und das ist die vierte Posaune, nämlich: Es befinden sich unter denen, die bis zu jenem großen und letzten Tag, ja, bis zum Ende bleiben müssen, jene, die weiterhin schmutzig bleiben werden."},{"verse":103,"text":"Und noch eine Posaune wird ertönen, und das ist die fünfte Posaune, und das ist der fünfte Engel, der das immerwährende Evangelium überbringt – während er mitten durch den Himmel fliegt, zu allen Nationen, Geschlechtern, Sprachen und Völkern,"},{"verse":104,"text":"und dies wird der Ton seiner Posaune sein, nämlich für alles Volk, sowohl im Himmel als auch auf Erden und die unter der Erde sind –, denn jedes Ohr wird vernehmen, und jedes Knie wird sich beugen, und jede Zunge wird bekennen, wenn sie den Ton der Posaune hören, nämlich: Fürchtet Gott, und gebt ihm die Ehre, der auf dem Thron sitzt, für immer und immer; denn die Stunde seines Gerichts ist gekommen."},{"verse":105,"text":"Und weiter, noch ein Engel wird seine Posaune ertönen lassen, und das ist der sechste Engel, nämlich: Sie ist gefallen, die alle Nationen dazu gebracht hat, vom Wein des Zornes ihrer Unzucht zu trinken, sie ist gefallen, ist gefallen!"},{"verse":106,"text":"Und weiter, noch ein Engel wird seine Posaune ertönen lassen, und das ist der siebente Engel, nämlich: Es ist vollbracht, es ist vollbracht! Das Lamm Gottes hat überwunden und die Weinkelter allein getreten, ja, die Weinkelter des heftigen Grimms des allmächtigen Gottes."},{"verse":107,"text":"Und dann werden die Engel mit der Herrlichkeit seiner Macht gekrönt werden, und die Heiligen werden von seiner Herrlichkeit erfüllt werden und ihr Erbteil empfangen und ihm gleichgemacht werden."},{"verse":108,"text":"Und dann wird der erste Engel abermals seine Posaune allen Lebenden in die Ohren tönen lassen und die geheimen Taten der Menschen sowie die mächtigen Werke Gottes in den ersten tausend Jahren offenbaren."},{"verse":109,"text":"Und dann wird der zweite Engel seine Posaune ertönen lassen und die geheimen Taten der Menschen und die Gedanken und Absichten ihres Herzens sowie die mächtigen Werke Gottes in den zweiten tausend Jahren offenbaren –"},{"verse":110,"text":"und so fort, bis der siebente Engel seine Posaune ertönen lassen wird; und er wird vortreten auf das Land und auf das Meer und im Namen dessen, der auf dem Thron sitzt, schwören, dass es Zeit nicht länger geben wird; und der Satan wird gebunden werden, jene alte Schlange, die der Teufel genannt wird, und wird über den Zeitraum von eintausend Jahren hinweg nicht losgebunden werden."},{"verse":111,"text":"Und dann wird er für eine kurze Zeit lang losgebunden, damit er seine Heere sammeln kann."},{"verse":112,"text":"Und Michael, der siebente Engel, ja, der Erzengel, wird seine Heere sammeln, nämlich die Scharen des Himmels."},{"verse":113,"text":"Und der Teufel wird seine Heere sammeln, nämlich die Scharen der Hölle, und wird zum Kampf gegen Michael und seine Heere heranrücken."},{"verse":114,"text":"Und dann kommt die Schlacht des großen Gottes; und der Teufel und seine Heere werden an ihren eigenen Ort geworfen werden, sodass sie über die Heiligen nimmermehr irgendwelche Macht haben werden."},{"verse":115,"text":"Denn Michael wird ihre Schlachten schlagen und wird den überwinden, der nach dem Thron dessen trachtet, der auf dem Thron sitzt, nämlich des Lammes."},{"verse":116,"text":"Dies ist die Herrlichkeit Gottes und der Geheiligten; und sie werden den Tod nimmermehr schauen."},{"verse":117,"text":"Darum, wahrlich, ich sage euch, meine Freunde: Beruft eure feierliche Versammlung ein, wie ich es euch geboten habe."},{"verse":118,"text":"Und da nicht alle Glauben haben, so sucht eifrig und lehrt einander Worte der Weisheit; ja, sucht Worte der Weisheit aus den besten Büchern; trachtet nach Wissen, ja, durch Studium und auch durch Glauben."},{"verse":119,"text":"Organisiert euch; bereitet alles vor, was nötig ist; und errichtet ein Haus, nämlich ein Haus des Betens, ein Haus des Fastens, ein Haus des Glaubens, ein Haus des Lernens, ein Haus der Herrlichkeit, ein Haus der Ordnung, ein Haus Gottes;"},{"verse":120,"text":"damit euer Eintreten im Namen des Herrn geschehe; damit euer Weggehen im Namen des Herrn geschehe; damit alle eure Begrüßungen im Namen des Herrn geschehen, die Hände zum Allerhöchsten erhoben."},{"verse":121,"text":"Darum lasst ab von all euren leichten Reden, von allem Gelächter, von all euren lüsternen Wünschen, von all eurem Stolz und all eurer Leichtfertigkeit und von all eurem schlechten Tun."},{"verse":122,"text":"Bestimmt unter euch einen zum Lehrer, und lasst nicht alle auf einmal Wortführer sein; sondern lasst immer nur einen reden, und lasst alle seinen Worten zuhören, damit, wenn alle geredet haben, alle durch alle erbaut worden sein mögen und ein jeder das gleiche Recht habe."},{"verse":123,"text":"Seht zu, dass ihr einander liebhabt; hört auf, habgierig zu sein; lernt, miteinander zu teilen, wie es das Evangelium verlangt."},{"verse":124,"text":"Hört auf, müßig zu sein; hört auf, unrein zu sein; hört auf, Fehler aneinander zu finden; hört auf, länger als nötig zu schlafen; geht früh zu Bett, damit ihr nicht müde seiet; steht früh auf, damit ihr an Körper und Verstand gestärkt seiet."},{"verse":125,"text":"Und vor allem: Bekleidet euch mit dem Band der Nächstenliebe wie mit einem Mantel, denn es ist dies das Band der Vollkommenheit und des Friedens."},{"verse":126,"text":"Betet immer, damit ihr nicht ermattet, bis ich komme. Siehe, ja siehe, ich werde schnell kommen und euch zu mir nehmen. Amen."},{"verse":127,"text":"Und weiter: Die Ordnung des Hauses, das für die Präsidentschaft der Schule der Propheten bereitet ist; eingerichtet, damit sie in allem, was für sie ratsam ist, unterwiesen werden können, nämlich alle Beamten der Kirche oder, mit anderen Worten, diejenigen, die zum geistlichen Dienst in der Kirche berufen sind, angefangen bei den Hohen Priestern bis herab zu den Diakonen –"},{"verse":128,"text":"und dies soll die Ordnung des Hauses der Präsidentschaft der Schule sein: Wer bestimmt ist, der Präsident oder Lehrer zu sein, soll in dem Haus, das für ihn bereitet werden soll, an seinem Platz stehend vorgefunden werden."},{"verse":129,"text":"Darum soll er als Erster im Haus Gottes sein, an einer Stelle, wo die im Haus Versammelten seine Worte klar und deutlich vernehmen können, ohne dass laut gesprochen werden muss."},{"verse":130,"text":"Und wenn er in das Haus Gottes kommt, denn er soll als Erster im Haus sein – siehe, das ist schön, auf dass er ein Vorbild sei –,"},{"verse":131,"text":"soll er sich auf seinen Knien vor Gott im Gebet darbringen, zum Zeichen des immerwährenden Bundes oder zur Erinnerung daran."},{"verse":132,"text":"Und wenn jemand nach ihm hereinkommt, soll der Lehrer aufstehen und, die Hände zum Himmel erhoben, ja, nämlich geradewegs, seinen Bruder oder seine Brüder mit diesen Worten begrüßen:"},{"verse":133,"text":"Bist du ein Bruder, seid ihr Brüder? Ich begrüße euch im Namen des Herrn Jesus Christus, zum Zeichen des immerwährenden Bundes oder zur Erinnerung daran, und in diesem Bund empfange ich euch in der Gemeinschaft mit dem festen, unverrückbaren und unabänderlichen Entschluss, durch die Gnade Gottes in den Banden der Liebe euer Freund und Bruder zu sein und in allen Geboten Gottes untadelig und dankbar für immer und immer zu wandeln. Amen."},{"verse":134,"text":"Und wenn einer dieser Begrüßung nicht würdig befunden wird, soll er keinen Platz unter euch haben; denn ihr sollt nicht dulden, dass mein Haus durch ihn verunreinigt werde."},{"verse":135,"text":"Und wer hereinkommt und treu vor mir ist und ein Bruder ist, oder wenn es Brüder sind, so sollen sie den Präsidenten oder Lehrer begrüßen, die Hände zum Himmel erhoben, mit ebendemselben Gebet und Bündnis oder indem sie zum Zeichen dessen Amen sagen."},{"verse":136,"text":"Siehe, wahrlich, ich sage euch: Dies ist für euch das Beispiel für die gegenseitige Begrüßung im Haus Gottes, in der Schule der Propheten."},{"verse":137,"text":"Und ihr seid aufgerufen, dies mit Gebet und Danksagung zu tun, wie der Geist euch bei allem, was ihr im Haus des Herrn, in der Schule der Propheten, tut, zu reden eingeben wird, damit es ein Heiligtum werde, eine Wohnstätte des Heiligen Geistes zu eurer Erbauung."},{"verse":138,"text":"Und ihr sollt keinen bei euch in diese Schule aufnehmen, der nicht rein ist vom Blut dieser Generation;"},{"verse":139,"text":"und er soll durch die heilige Handlung der Fußwaschung aufgenommen werden, denn zu diesem Zweck ist die Verordnung der Fußwaschung eingesetzt worden."},{"verse":140,"text":"Und weiter, die heilige Handlung der Fußwaschung soll vom Präsidenten oder präsidierenden Ältesten der Kirche vollzogen werden."},{"verse":141,"text":"Sie soll mit Gebet beginnen, und nach dem Nehmen von Brot und Wein soll er sich gürten, dem Muster gemäß, das im dreizehnten Kapitel im Zeugnis des Johannes über mich angegeben ist. Amen."}]},{"chapter":89,"verses":[{"verse":1,"text":"Ein Wort der Weisheit zum Nutzen des Rates der Hohen Priester, die in Kirtland versammelt sind, und der Kirche und auch der Heiligen in Zion –"},{"verse":2,"text":"auszusenden als Gruß, nicht als Gebot oder Nötigung, sondern als Offenbarung und als Wort der Weisheit, zeigt es doch die Ordnung und den Willen Gottes in Bezug auf die zeitliche Errettung aller Heiligen in den letzten Tagen –,"},{"verse":3,"text":"gegeben als Grundsatz mit einer Verheißung, angepasst der Fähigkeit der Schwachen und der Schwächsten unter allen Heiligen, die Heilige sind oder so genannt werden können."},{"verse":4,"text":"Siehe, wahrlich, so spricht der Herr zu euch: Infolge der Schlechtigkeit und der bösen Absichten, die im Herzen von verschwörerischen Menschen in den letzten Tagen vorhanden sind und sein werden, habe ich euch gewarnt und warne euch im Voraus, indem ich euch durch Offenbarung dieses Wort der Weisheit gebe:"},{"verse":5,"text":"Falls irgendjemand unter euch Wein oder starkes Getränk trinkt, siehe, so ist das nicht gut und in den Augen eures Vaters auch nicht recht, außer wenn ihr euch zusammenfindet, um vor ihm eure heiligen Handlungen darzubringen."},{"verse":6,"text":"Und siehe, das soll Wein sein, ja, reiner Wein aus den Trauben des Weinstocks, von euch selbst erzeugt."},{"verse":7,"text":"Und weiter: Starkes Getränk ist nicht für den Bauch, sondern dass ihr euch damit den Körper wascht."},{"verse":8,"text":"Und weiter: Tabak ist nicht für den Körper, auch nicht für den Bauch, und ist nicht gut für den Menschen, sondern ist ein Kraut für Quetschungen und für alles kranke Vieh und soll mit Verstand und Geschick gebraucht werden."},{"verse":9,"text":"Und weiter: Heißes Getränk ist weder für den Körper noch für den Bauch."},{"verse":10,"text":"Und weiter, wahrlich, ich sage euch: Alle bekömmlichen Kräuter hat Gott für die leibliche Verfassung und Beschaffenheit des Menschen und ihm zum Gebrauch verordnet –"},{"verse":11,"text":"ein jedes Kraut zu seiner Jahreszeit und eine jede Frucht zu ihrer Jahreszeit; und sie alle sind mit Vernunft und Danksagung zu gebrauchen."},{"verse":12,"text":"Ja, auch Fleisch von Tieren und von den Vögeln der Luft habe ich, der Herr, verordnet, dass der Mensch es mit Danksagung gebrauche; doch soll es sparsam gebraucht werden;"},{"verse":13,"text":"und es ist mir angenehm, dass es nicht gebraucht werde, außer in Zeiten des Winters oder der Kälte oder der Hungersnot."},{"verse":14,"text":"Alle Körnerfrucht ist den Menschen und den Tieren zum Gebrauch verordnet, dass sie die Stütze des Lebens sei, nicht nur für den Menschen, sondern auch für die Tiere des Feldes und die Vögel des Himmels und alle wilden Tiere, die auf Erden laufen oder kriechen;"},{"verse":15,"text":"und diese hat Gott gemacht, damit der Mensch sie gebrauche, doch nur in Zeiten der Not und des übermäßigen Hungers."},{"verse":16,"text":"Alle Körnerfrucht ist gut als Nahrung für den Menschen, wie auch die Frucht des Weinstocks und das, was Frucht bringt, sei es im Boden oder über dem Boden –"},{"verse":17,"text":"doch Weizen für den Menschen und Mais für das Rind und Hafer für das Pferd und Roggen für das Geflügel und die Schweine und für alle Tiere des Feldes und Gerste für alle nützlichen Tiere und für leichtes Getränk, wie auch andere Körnerfrucht."},{"verse":18,"text":"Und alle Heiligen, die sich dieser Worte erinnern und sie befolgen und tun und die in ihrem Wandel die Gebote beachten, werden Gesundheit empfangen in ihrem Nabel und Mark für ihre Knochen"},{"verse":19,"text":"und werden Weisheit und große Schätze der Erkenntnis finden, selbst verborgene Schätze,"},{"verse":20,"text":"und werden laufen und nicht ermüden und werden gehen und nicht ermatten."},{"verse":21,"text":"Und ich, der Herr, gebe ihnen die Verheißung, dass der zerstörende Engel an ihnen vorübergehen wird wie an den Kindern Israel und sie nicht töten wird. Amen."}]},{"chapter":90,"verses":[{"verse":1,"text":"So spricht der Herr: Wahrlich, wahrlich, ich sage dir, mein Sohn: Deine Sünden sind dir vergeben gemäß deiner Bitte, denn deine Gebete und die Gebete deiner Brüder sind mir in die Ohren heraufgekommen."},{"verse":2,"text":"Darum bist du hinfort gesegnet, der du die Schlüssel des Reiches trägst, die dir gegeben worden sind; und dieses Reich kommt zum letzten Mal hervor."},{"verse":3,"text":"Wahrlich, ich sage dir: Die Schlüssel dieses Reiches werden dir nie genommen werden, solange du auf der Welt bist, auch nicht in der künftigen Welt;"},{"verse":4,"text":"doch sollen durch dich die Aussprüche Gottes an andere gegeben werden, ja, nämlich an die Kirche."},{"verse":5,"text":"Und alle, die die Aussprüche Gottes empfangen – sie sollen sich in Acht nehmen, wie sie mit ihnen umgehen, damit sie nicht als unbedeutend angesehen werden und sie dadurch unter Schuldigsprechung geraten und stolpern und fallen, wenn die Stürme herabfahren und die Winde wehen und die Regengüsse niedergehen und an ihr Haus schlagen."},{"verse":6,"text":"Und abermals, wahrlich, ich sage deinen Brüdern Sidney Rigdon und Frederick G. Williams: Ihre Sünden sind ihnen auch vergeben, und sie werden als dir gleichwertig erachtet, die Schlüssel dieses letzten Reiches innezuhaben"},{"verse":7,"text":"und ebenso, durch dein Wirken, die Schlüssel der Schule der Propheten, die einzurichten ich geboten habe;"},{"verse":8,"text":"damit sie dadurch vervollkommnet werden in ihrem geistlichen Dienst für die Errettung Zions und der Nationen Israels und der Anderen, aller, die glauben werden;"},{"verse":9,"text":"damit sie durch dein Wirken das Wort empfangen und durch ihr Wirken das Wort hinausgehe an die Enden der Erde, zu den Anderen zuerst, und dann, siehe, ja siehe, werden sie sich den Juden zuwenden."},{"verse":10,"text":"Und dann kommt der Tag, da sich der Arm des Herrn in seiner Macht offenbaren wird, um die Nationen, die heidnischen Nationen, das Haus Josef, vom Evangelium ihrer Errettung zu überzeugen."},{"verse":11,"text":"Denn an jenem Tag wird es sich begeben: Jedermann wird die Fülle des Evangeliums in seiner eigenen Zunge und in seiner eigenen Sprache vernehmen, durch diejenigen, die zu dieser Macht ordiniert sind, durch das Wirken des Trösters, der über sie ausgegossen wird, um Jesus Christus zu offenbaren."},{"verse":12,"text":"Und nun, wahrlich, ich sage euch: Ich gebe euch das Gebot, dass ihr weiter im geistlichen Dienst und in der Präsidentschaft verbleibt."},{"verse":13,"text":"Und wenn ihr die Übersetzung der Propheten beendet habt, sollt ihr hinfort über die Angelegenheiten der Kirche und der Schule präsidieren"},{"verse":14,"text":"und von Zeit zu Zeit, wie es durch den Tröster kundgetan werden wird, Offenbarungen empfangen, um die Geheimnisse des Reiches zu entfalten,"},{"verse":15,"text":"und die Gemeinden in Ordnung bringen und studieren und lernen und mit allen guten Büchern und mit Sprachen, Zungen und Völkern bekannt werden."},{"verse":16,"text":"Und dies soll euer ganzes Leben lang eure Arbeit und eure Sendung sein: im Rat zu präsidieren und alle Angelegenheiten dieser Kirche und dieses Reiches in Ordnung zu bringen."},{"verse":17,"text":"Schämt euch nicht, lasst euch nicht beschämen; lasst euch aber wegen eures Hochmuts und Stolzes ermahnen, denn dieser legt euch eine Schlinge für eure Seele."},{"verse":18,"text":"Bringt eure Häuser in Ordnung; haltet Trägheit und Unreinheit weit von euch fern."},{"verse":19,"text":"Nun, wahrlich, ich sage dir: Lass, sobald wie es möglich ist, für die Familie deines Ratgebers und Schreibers, nämlich Frederick G. Williams, einen Platz besorgen."},{"verse":20,"text":"Und lass meinen bejahrten Diener Joseph Smith Sr. mit seiner Familie an dem Platz verbleiben, wo er jetzt lebt; und lass einen Verkauf nicht zu, bis der Mund des Herrn es verfügt."},{"verse":21,"text":"Und lass meinen Ratgeber, nämlich Sidney Rigdon, dort bleiben, wo er jetzt wohnt, bis der Mund des Herrn es verfügt."},{"verse":22,"text":"Und lass den Bischof eifrig suchen, um einen Beauftragten zu finden; und das soll ein Mann sein, der über Reichtümer verfügt – ein Mann Gottes und von starkem Glauben –,"},{"verse":23,"text":"damit er hierdurch imstande ist, alle Schulden zu begleichen; damit das Vorratshaus des Herrn vor den Augen des Volkes nicht in Verruf gerate."},{"verse":24,"text":"Forscht eifrig, betet immer und seid gläubig, dann wird alles zu eurem Guten zusammenwirken, wenn ihr untadelig wandelt und des Bundes eingedenk seid, mit dem ihr euch miteinander verbunden habt."},{"verse":25,"text":"Lasst eure Familien klein sein, vor allem die meines bejahrten Dieners Joseph Smith Sr., was nämlich diejenigen betrifft, die nicht zu euren Familien gehören,"},{"verse":26,"text":"damit das, womit ihr versehen worden seid, um mein Werk auszuführen, nicht von euch genommen und denen gegeben werde, die nicht würdig sind –"},{"verse":27,"text":"und ihr dadurch gehindert seid, das zu vollbringen, was ich euch geboten habe."},{"verse":28,"text":"Und abermals, wahrlich, ich sage euch: Es ist mein Wille, dass meine Magd Vienna Jaques Geld empfange, um ihre Auslagen zu begleichen, und sich ins Land Zion hinaufbegebe;"},{"verse":29,"text":"und der Rest des Geldes möge mir geweiht werden und sie zu der von mir selbst bestimmten Zeit belohnt werden."},{"verse":30,"text":"Wahrlich, ich sage euch: Es ist recht in meinen Augen, dass sie sich hinauf ins Land Zion begebe und von der Hand des Bischofs ein Erbteil empfange;"},{"verse":31,"text":"damit sie sich in Frieden niederlassen kann, insoweit sie treu ist, und in ihren Tagen hinfort nicht müßig sei."},{"verse":32,"text":"Und siehe, wahrlich, ich sage euch: Ihr sollt dieses Gebot niederschreiben und euren Brüdern in Zion sagen, sie in Liebe grüßend, dass ich euch berufen habe, zu der von mir selbst bestimmten Zeit auch über Zion zu präsidieren."},{"verse":33,"text":"Darum sollen sie aufhören, mich wegen dieser Sache zu ermüden."},{"verse":34,"text":"Siehe, ich sage euch: Eure Brüder in Zion fangen an umzukehren, und die Engel freuen sich über sie."},{"verse":35,"text":"Doch habe ich an vielem kein Wohlgefallen; und ich habe kein Wohlgefallen an meinem Diener William E. McLellin, auch nicht an meinem Diener Sidney Gilbert; und auch der Bischof und andere haben vieles, wovon sie umkehren müssen."},{"verse":36,"text":"Aber wahrlich, ich sage euch: Ich, der Herr, werde mit Zion streiten und mit seinen Starken rechten und es züchtigen, bis es überwindet und vor mir rein ist."},{"verse":37,"text":"Denn es wird nicht von seinem Platz entfernt werden. Ich, der Herr, habe es gesagt. Amen."}]},{"chapter":91,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr zu euch in Bezug auf die Apokryphen: Vieles ist darin enthalten, was wahr ist; und sie sind im Wesentlichen richtig übersetzt;"},{"verse":2,"text":"vieles ist darin enthalten, was nicht wahr ist, und das sind Hinzufügungen von Menschenhand."},{"verse":3,"text":"Wahrlich, ich sage euch: Es ist nicht nötig, die Apokryphen zu übersetzen."},{"verse":4,"text":"Darum, wer sie liest, der möge verstehen, denn der Geist tut Wahrheit kund;"},{"verse":5,"text":"und wer durch den Geist erleuchtet ist, der wird Nutzen daraus erlangen;"},{"verse":6,"text":"und wer nicht durch den Geist empfängt, dem können sie nicht nützen. Darum ist es nicht nötig, sie zu übersetzen. Amen."}]},{"chapter":92,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr: Ich gebe der vereinigten Ordnung, die in Übereinstimmung mit dem früher erteilten Gebot organisiert worden ist, eine Offenbarung und ein Gebot in Bezug auf meinen Diener Frederick G. Williams, dass ihr ihn in die Ordnung aufnehmen sollt. Was ich einem sage, das sage ich allen."},{"verse":2,"text":"Und weiter sage ich dir, mein Diener Frederick G. Williams: Du sollst in dieser Ordnung ein rühriges Mitglied sein; und insoweit du im Halten aller früheren Gebote treu bist, wirst du gesegnet sein für immer. Amen."}]},{"chapter":93,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr: Es wird sich begeben: Jede Seele, die von ihren Sünden lässt und zu mir kommt und meinen Namen anruft und meiner Stimme gehorcht und meine Gebote hält, wird mein Angesicht sehen und wissen, dass ich bin"},{"verse":2,"text":"und dass ich das wahre Licht bin, das jedem Menschen leuchtet, der in die Welt kommt,"},{"verse":3,"text":"und dass ich im Vater bin und der Vater in mir und der Vater und ich eins sind –"},{"verse":4,"text":"der Vater, weil er mir von seiner Fülle gegeben hat, und der Sohn, weil ich in der Welt gewesen bin und Fleisch zu meiner Wohnstätte gemacht und unter den Söhnen der Menschen gewohnt habe."},{"verse":5,"text":"Ich war in der Welt und empfing von meinem Vater, und seine Werke waren deutlich kundgetan."},{"verse":6,"text":"Und Johannes sah die Fülle meiner Herrlichkeit und gab dafür Zeugnis, und die Fülle des Berichtes des Johannes wird später noch offenbart werden."},{"verse":7,"text":"Und er gab Zeugnis, nämlich: Ich sah seine Herrlichkeit, dass er im Anfang war, ehe die Welt war;"},{"verse":8,"text":"darum war im Anfang das Wort, denn er war das Wort, nämlich der Bote der Errettung –"},{"verse":9,"text":"das Licht und der Erlöser der Welt; der Geist der Wahrheit, der in die Welt kam, weil die Welt von ihm gemacht wurde, und in ihm war das Leben der Menschen und das Licht der Menschen."},{"verse":10,"text":"Die Welten wurden von ihm gemacht; die Menschen wurden von ihm gemacht; alles wurde von ihm gemacht und durch ihn und aus ihm."},{"verse":11,"text":"Und ich, Johannes, gebe Zeugnis, dass ich seine Herrlichkeit schaute, nämlich die Herrlichkeit des Einziggezeugten des Vaters, voller Gnade und Wahrheit, ja, der Geist der Wahrheit, der kam und im Fleische wohnte und unter uns wohnte."},{"verse":12,"text":"Und ich, Johannes, sah, dass er zuerst nicht von der Fülle empfing, sondern Gnade um Gnade empfing;"},{"verse":13,"text":"und er empfing zuerst nicht von der Fülle, sondern ging von Gnade zu Gnade, bis er eine Fülle empfing;"},{"verse":14,"text":"und so wurde er der Sohn Gottes genannt, weil er zuerst nicht von der Fülle empfing."},{"verse":15,"text":"Und ich, Johannes, gebe Zeugnis: Und siehe, die Himmel öffneten sich, und der Heilige Geist kam auf ihn herab in Gestalt einer Taube und ließ sich auf ihm nieder, und aus dem Himmel kam eine Stimme, nämlich: Dies ist mein geliebter Sohn."},{"verse":16,"text":"Und ich, Johannes, gebe Zeugnis, dass er eine Fülle der Herrlichkeit vom Vater empfing,"},{"verse":17,"text":"und er empfing alle Macht, im Himmel wie auch auf Erden, und die Herrlichkeit des Vaters war mit ihm, denn er wohnte in ihm."},{"verse":18,"text":"Und es wird sich begeben: Wenn ihr treu seid, werdet ihr die Fülle des Berichtes des Johannes empfangen."},{"verse":19,"text":"Ich gebe euch diese Worte, damit ihr versteht und wisst, wie ihr anbeten sollt, und wisst, was ihr anbetet, damit ihr in meinem Namen zum Vater kommen und zu gegebener Zeit von seiner Fülle empfangen könnt."},{"verse":20,"text":"Denn wenn ihr meine Gebote haltet, werdet ihr von seiner Fülle empfangen und in mir verherrlicht werden wie ich im Vater; darum sage ich euch: Ihr werdet Gnade um Gnade empfangen."},{"verse":21,"text":"Und nun, wahrlich, ich sage euch: Ich war im Anfang beim Vater und bin der Erstgeborene;"},{"verse":22,"text":"und alle, die durch mich gezeugt sind, sind Teilhaber der Herrlichkeit desselben und sind die Kirche des Erstgeborenen."},{"verse":23,"text":"Ihr wart auch am Anfang beim Vater; das, was Geist ist, nämlich der Geist der Wahrheit;"},{"verse":24,"text":"und Wahrheit ist Kenntnis von etwas, wie es ist und wie es war und wie es kommen wird;"},{"verse":25,"text":"und was auch immer mehr oder weniger ist als dies, ist der Geist jenes Schlechten, der ein Lügner war von Anfang an."},{"verse":26,"text":"Der Geist der Wahrheit ist von Gott. Ich bin der Geist der Wahrheit, und Johannes hat für mich Zeugnis gegeben, nämlich: Er empfing eine Fülle der Wahrheit, ja, nämlich von aller Wahrheit;"},{"verse":27,"text":"und kein Mensch empfängt eine Fülle, wenn er nicht seine Gebote hält."},{"verse":28,"text":"Wer seine Gebote hält, empfängt Wahrheit und Licht, bis er in der Wahrheit verherrlicht ist und alles weiß."},{"verse":29,"text":"Der Mensch war auch im Anfang bei Gott. Intelligenz oder das Licht der Wahrheit wurde nicht erschaffen oder gemacht und kann es auch gar nicht."},{"verse":30,"text":"Alle Wahrheit ist unabhängig in dem Bereich, worein Gott sie gestellt hat, und kann für sich selbst handeln, wie auch alle Intelligenz; anders gibt es kein Dasein."},{"verse":31,"text":"Siehe, hierin liegt die Entscheidungsfreiheit des Menschen, und hierin liegt die Schuldigsprechung des Menschen; weil das, was von Anfang an war, ihnen deutlich kundgetan ist und sie das Licht nicht annehmen."},{"verse":32,"text":"Und jeder Mensch, dessen Geist das Licht nicht annimmt, steht unter Schuldspruch."},{"verse":33,"text":"Denn der Mensch ist Geist. Die Elemente sind ewig, und Geist und Element, untrennbar verbunden, empfangen eine Fülle der Freude;"},{"verse":34,"text":"sind sie aber getrennt, so kann der Mensch eine Fülle der Freude nicht empfangen."},{"verse":35,"text":"Die Elemente sind die Wohnstätte Gottes; ja, der Mensch ist die Wohnstätte Gottes, nämlich ein Tempel; und welcher Tempel auch immer entweiht wird, jenen Tempel wird Gott zerstören."},{"verse":36,"text":"Die Herrlichkeit Gottes ist Intelligenz oder, mit anderen Worten, Licht und Wahrheit."},{"verse":37,"text":"Licht und Wahrheit verlassen jenen Bösen."},{"verse":38,"text":"Der Geist jedes Menschen war im Anfang unschuldig; und nachdem Gott den Menschen vom Fall erlöst hatte, wurden die Menschen in ihrem Kindeszustand wiederum unschuldig vor Gott."},{"verse":39,"text":"Und jener Schlechte kommt und nimmt von den Menschenkindern infolge von Ungehorsam und wegen der Überlieferung ihrer Väter Licht und Wahrheit weg."},{"verse":40,"text":"Ich aber habe euch geboten, eure Kinder in Licht und Wahrheit aufzuziehen."},{"verse":41,"text":"Aber wahrlich, ich sage dir, mein Diener Frederick G. Williams: Du bist unter diesem Schuldspruch verblieben;"},{"verse":42,"text":"du hast deine Kinder nicht Licht und Wahrheit gemäß den Geboten gelehrt; und jener Schlechte hat noch immer Macht über dich, und das ist die Ursache deiner Bedrängnis."},{"verse":43,"text":"Und nun, ein Gebot gebe ich dir: Wenn du befreit sein willst, musst du dein eigenes Haus in Ordnung bringen; denn es gibt vieles, was in deinem Haus nicht recht ist."},{"verse":44,"text":"Wahrlich, ich sage meinem Diener Sidney Rigdon, dass er in einigem die Gebote in Bezug auf seine Kinder nicht gehalten hat; darum bringe zuerst dein Haus in Ordnung."},{"verse":45,"text":"Wahrlich, ich sage meinem Diener Joseph Smith Jr. oder, mit anderen Worten, ich werde euch Freunde nennen, denn ihr seid meine Freunde, und ihr werdet ein Erbteil mit mir haben –"},{"verse":46,"text":"ich habe euch um der Welt willen Diener genannt, und um meinetwillen seid ihr ihre Diener –,"},{"verse":47,"text":"und nun, wahrlich, ich sage zu Joseph Smith Jr.: Du hast die Gebote nicht gehalten und musst notwendigerweise zurechtgewiesen vor dem Herrn dastehen;"},{"verse":48,"text":"deine Familie muss notwendigerweise umkehren und von einigem lassen und deinen Worten ernstere Beachtung schenken oder von ihrem Platz entfernt werden."},{"verse":49,"text":"Was ich zu einem sage, das sage ich zu allen; betet immer, damit jener Schlechte nicht Macht in euch habe und euch von eurem Platz entferne."},{"verse":50,"text":"Auch mein Diener Newel K. Whitney, ein Bischof meiner Kirche, hat es nötig, gezüchtigt zu werden und seine Familie in Ordnung zu bringen und zu sehen, dass sie zu Hause eifriger und besorgter sind und immer beten, sonst werden sie von ihrem Platz entfernt werden."},{"verse":51,"text":"Nun sage ich euch, meine Freunde: Lasst meinen Diener Sidney Rigdon sich auf die Reise machen und sich beeilen und auch das angenehme Jahr des Herrn und das Evangelium der Errettung verkündigen, wie ich ihm eingeben werde zu reden; und durch euer einmütiges Gebet des Glaubens werde ich ihn aufrechterhalten."},{"verse":52,"text":"Und lasst auch meine Diener Joseph Smith Jr. und Frederick G. Williams sich beeilen, und es wird ihnen eingegeben werden, selbst gemäß dem Gebet des Glaubens; und insoweit ihr meine Worte haltet, werdet ihr weder in dieser Welt noch in der künftigen Welt zuschanden werden."},{"verse":53,"text":"Und wahrlich, ich sage euch: Es ist mein Wille, dass ihr euch beeilt, meine Schriften zu übersetzen und Kenntnis von der Geschichte und von Ländern und von Reichen, von den Gesetzen Gottes und der Menschen zu erlangen, und das alles für die Errettung Zions. Amen."}]},{"chapter":94,"verses":[{"verse":1,"text":"Und weiter, wahrlich, ich sage euch, meine Freunde: Das Gebot gebe ich euch, mit dem Werk der Planung und Vorbereitung für den Anfang und die Grundlegung der Stadt des Zionspfahles hier im Land Kirtland zu beginnen, mit meinem Haus beginnend."},{"verse":2,"text":"Und siehe, es muss gemäß dem Muster geschehen, das ich euch gegeben habe."},{"verse":3,"text":"Und das erste Grundstück gegen Süden soll mir geweiht werden für die Errichtung eines Hauses für die Präsidentschaft, für die Arbeit der Präsidentschaft, um Offenbarungen zu erlangen, und für das Werk des geistlichen Dienstes der Präsidentschaft in allem, was die Kirche und das Reich betrifft."},{"verse":4,"text":"Wahrlich, ich sage euch: Es soll im Innenraum fünfundfünfzig Fuß breit und fünfundsechzig Fuß lang gebaut werden."},{"verse":5,"text":"Und es soll einen unteren und einen oberen Raum geben, gemäß dem Muster, das euch später noch gegeben werden wird."},{"verse":6,"text":"Und es soll von der Grundlegung an dem Herrn geweiht sein, gemäß der Ordnung des Priestertums, gemäß dem Muster, das euch später noch gegeben werden wird."},{"verse":7,"text":"Und es soll gänzlich dem Herrn für die Arbeit der Präsidentschaft geweiht werden."},{"verse":8,"text":"Und ihr sollt nicht zulassen, dass etwas Unreines hineingelangt; und meine Herrlichkeit wird da sein, und meine Gegenwart wird da sein."},{"verse":9,"text":"Aber wenn etwas Unreines hineingelangt, so wird meine Herrlichkeit nicht da sein, und meine Gegenwart wird nicht hineingelangen."},{"verse":10,"text":"Und weiter, wahrlich, ich sage euch: Das zweite Grundstück gegen Süden soll mir geweiht werden für die Errichtung eines Hauses für mich, für die Arbeit des Druckens der Übersetzung meiner Schriften und all dessen, was auch immer ich euch gebieten werde."},{"verse":11,"text":"Und es soll im Innenraum fünfundfünfzig Fuß breit und fünfundsechzig Fuß lang sein, und es soll einen unteren und einen oberen Raum geben."},{"verse":12,"text":"Und dieses Haus soll von der Grundlegung an gänzlich dem Herrn geweiht sein für die Arbeit des Druckens all dessen, was auch immer ich euch gebieten werde, dass es heilig und makellos sei gemäß dem Muster, wie es euch in allem gegeben werden wird."},{"verse":13,"text":"Und auf dem dritten Grundstück soll mein Diener Hyrum Smith sein Erbteil empfangen."},{"verse":14,"text":"Und auf dem ersten und zweiten Grundstück gegen Norden sollen meine Diener Reynolds Cahoon und Jared Carter ihr Erbteil empfangen –"},{"verse":15,"text":"damit sie die Arbeit verrichten können, die ich für sie bestimmt habe: für den Bau meiner Häuser ein Komitee zu bilden, gemäß dem Gebot, das ich, Gott, der Herr, euch gegeben habe."},{"verse":16,"text":"Diese zwei Häuser sollen aber nicht gebaut werden, ehe ich euch in Bezug auf sie ein Gebot gebe."},{"verse":17,"text":"Und nun gebe ich euch zu dieser Zeit nichts mehr. Amen."}]},{"chapter":95,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr zu euch, die ich liebe; und die ich liebe, die züchtige ich auch, damit ihre Sünden vergeben seien, denn mit der Züchtigung bereite ich einen Weg, damit sie in allem aus der Versuchung befreit werden; und ich habe euch geliebt –"},{"verse":2,"text":"darum müsst ihr notwendigerweise gezüchtigt werden und zurechtgewiesen vor meinem Angesicht dastehen;"},{"verse":3,"text":"denn ihr habt mit einer sehr schweren Sünde gegen mich gesündigt, indem ihr nicht in allem das große Gebot beachtet habt, das ich euch in Bezug auf den Bau meines Hauses gegeben habe,"},{"verse":4,"text":"zur Vorbereitung, mit der ich beabsichtige, meine Apostel vorzubereiten, meinen Weingarten zum letzten Mal zu beschneiden, damit ich meine seltsame Tat vollbringen kann, damit ich meinen Geist über alles Fleisch ausgießen kann –"},{"verse":5,"text":"aber siehe, wahrlich, ich sage euch: Es gibt viele unter euch, die ordiniert worden sind, die ich berufen habe, aber wenige von ihnen werden erwählt."},{"verse":6,"text":"Diejenigen, die nicht erwählt sind, haben eine sehr schwere Sünde gesündigt, indem sie am Mittag in Finsternis wandeln."},{"verse":7,"text":"Und aus diesem Grund habe ich euch das Gebot gegeben, eure feierliche Versammlung einzuberufen, damit euer Fasten und euer Trauern heraufkommen mögen in die Ohren des Herrn Zebaot, das ist übersetzt: der Schöpfer des ersten Tages, der Anfang und das Ende."},{"verse":8,"text":"Ja, wahrlich, ich sage euch: Ich habe euch das Gebot gegeben, ein Haus zu bauen, und in dem Haus beabsichtige ich, diejenigen, die ich erwählt habe, mit Macht aus der Höhe auszurüsten;"},{"verse":9,"text":"denn das ist die Verheißung des Vaters an euch; darum gebiete ich euch zu verweilen, ja, wie meine Apostel zu Jerusalem."},{"verse":10,"text":"Doch haben meine Diener eine sehr schwere Sünde gesündigt; und Streitigkeiten sind in der Schule der Propheten aufgekommen, und das war sehr schmerzlich für mich, spricht euer Herr; darum habe ich sie ausgesandt, damit sie gezüchtigt würden."},{"verse":11,"text":"Wahrlich, ich sage euch: Es ist mein Wille, dass ihr ein Haus baut. Wenn ihr meine Gebote haltet, werdet ihr die Macht haben, es zu bauen."},{"verse":12,"text":"Wenn ihr meine Gebote nicht haltet, wird die Liebe des Vaters nicht bei euch verbleiben, darum werdet ihr in Finsternis wandeln."},{"verse":13,"text":"Aber hier ist Weisheit und die Absicht des Herrn – das Haus soll gebaut werden, aber nicht nach der Weise der Welt, denn ich gewähre euch nicht, nach der Weise der Welt zu leben;"},{"verse":14,"text":"darum soll es nach der Weise gebaut werden, die ich dreien von euch zeigen werde, die ihr bestimmen und zu dieser Macht ordinieren sollt."},{"verse":15,"text":"Und seine Größe soll in seinem Innenraum fünfundfünfzig Fuß nach der Breite sein, und lasst es fünfundsechzig Fuß nach der Länge sein."},{"verse":16,"text":"Und der untere Teil des Innenraums soll mir für das Darbringen eurer Abendmahlshandlung geweiht werden und für euer Predigen und euer Fasten und euer Beten und dass ihr mir eure höchst heiligen Wünsche darbringt, spricht euer Herr."},{"verse":17,"text":"Und der obere Teil des Innenraums soll mir für die Schule meiner Apostel geweiht werden, spricht Sohn Ahman oder, mit anderen Worten, Alphus oder, mit anderen Worten, Omegus, nämlich Jesus Christus, euer Herr. Amen."}]},{"chapter":96,"verses":[{"verse":1,"text":"Siehe, ich sage euch: Hier ist Weisheit, wodurch ihr wissen könnt, wie ihr in dieser Sache handeln sollt, denn es ist mir ratsam, dass dieser Pfahl, den ich zur Stärkung Zions gesetzt habe, stark gemacht werde."},{"verse":2,"text":"Darum soll mein Diener Newel K. Whitney den Platz übernehmen, der von euch erwähnt wird und auf dem ich mein heiliges Haus zu bauen beabsichtige."},{"verse":3,"text":"Und weiter: Lasst ihn in Grundstücke eingeteilt werden, wie es zum Nutzen derer, die nach Erbteilen trachten, weise ist und wie ihr es im Rat unter euch beschließen werdet."},{"verse":4,"text":"Darum seht zu, dass ihr euch um diese Sache kümmert, ebenso um denjenigen Teil, der notwendig ist, um meiner Ordnung zu nützen, damit mein Wort zu den Menschenkindern gebracht werden kann."},{"verse":5,"text":"Denn siehe, wahrlich, ich sage euch: Dies ist mir am ratsamsten, nämlich dass mein Wort zu den Menschenkindern hinausgehe, damit den Menschenkindern zu eurem Nutzen das Herz erweicht werde. So ist es. Amen."},{"verse":6,"text":"Und weiter, wahrlich, ich sage euch: Es ist nach meiner Weisheit und mir ratsam, dass mein Diener John Johnson, dessen Opfer ich angenommen habe und dessen Gebete ich vernommen habe und dem ich die Verheißung ewigen Lebens gebe, insoweit er hinfort meine Gebote hält –"},{"verse":7,"text":"denn er ist ein Abkömmling Josefs und hat teil an den Segnungen der Verheißung, die seinen Vätern gegeben worden ist –,"},{"verse":8,"text":"wahrlich, ich sage euch, es ist mir ratsam, dass er ein Mitglied der Ordnung werde, um mithelfen zu können, dass mein Wort zu den Menschenkindern gebracht werde."},{"verse":9,"text":"Darum sollt ihr ihn zu dieser Segnung ordinieren, und er soll eifrig danach trachten, die Belastungen zu beseitigen, die auf dem von euch erwähnten Haus liegen, damit er darin wohnen kann. So ist es. Amen."}]},{"chapter":97,"verses":[{"verse":1,"text":"Wahrlich, ich sage euch, meine Freunde: Ich spreche zu euch mit meiner Stimme, nämlich der Stimme meines Geistes, um euch meinen Willen in Bezug auf eure Brüder im Land Zion zu zeigen, von denen viele wahrhaft demütig sind und eifrig danach trachten, Weisheit zu lernen und Wahrheit zu finden."},{"verse":2,"text":"Wahrlich, wahrlich, ich sage euch: Gesegnet sind solche, denn sie werden erlangen; denn ich, der Herr, erzeige Barmherzigkeit allen Sanftmütigen und gegenüber allen, wem auch immer ich will, damit ich gerechtfertigt bin, wenn ich sie vor Gericht bringe."},{"verse":3,"text":"Siehe, ich sage euch in Bezug auf die Schule in Zion: Ich, der Herr, habe Wohlgefallen daran, dass es eine Schule in Zion gibt, und auch an meinem Diener Parley P. Pratt, denn er verbleibt in mir."},{"verse":4,"text":"Und insoweit er weiterhin in mir verbleibt, soll er auch weiterhin über die Schule im Land Zion präsidieren, bis ich ihm andere Gebote gebe."},{"verse":5,"text":"Und ich werde ihn mit einer Vielfalt von Segnungen segnen, dass er alle Schriften und Geheimnisse zur Erbauung der Schule und der Kirche in Zion auslege."},{"verse":6,"text":"Und den Übrigen in der Schule bin ich, der Herr, willens, Barmherzigkeit zu erzeigen; doch gibt es welche, die notwendigerweise gezüchtigt werden müssen, und ihre Werke werden kundgetan werden."},{"verse":7,"text":"Die Axt ist an die Wurzel der Bäume gelegt; und jeder Baum, der keine gute Frucht hervorbringt, wird umgehauen und ins Feuer geworfen werden. Ich, der Herr, habe es gesagt."},{"verse":8,"text":"Wahrlich, ich sage euch: Alle unter ihnen, die wissen, dass ihr Herz ehrlich und reuig ist und ihr Geist zerknirscht, und die willens sind, ihre Bündnisse durch Opfer zu beachten – ja, jedes Opfer, das ich, der Herr, gebieten werde –, die werden von mir angenommen."},{"verse":9,"text":"Denn ich, der Herr, werde sie hervorbringen lassen wie ein sehr fruchtbarer Baum, der in gutes Land an einem reinen Strom gepflanzt ist und viel köstliche Frucht bringt."},{"verse":10,"text":"Wahrlich, ich sage euch: Es ist mein Wille, dass mir im Land Zion ein Haus gebaut werde, dem Muster entsprechend, das ich euch gegeben habe."},{"verse":11,"text":"Ja, es soll schnell gebaut werden, vom Zehnten meines Volkes."},{"verse":12,"text":"Siehe, dies ist der Zehnte und das Opfer, das ich, der Herr, von ihrer Hand fordere, damit mir ein Haus gebaut werde für die Errettung Zions –"},{"verse":13,"text":"als ein Ort der Danksagung für alle Heiligen und als ein Ort der Unterweisung für alle diejenigen, die in all ihren verschiedenen Berufungen und Ämtern zum Werk des geistlichen Dienstes berufen sind,"},{"verse":14,"text":"damit sie vervollkommnet werden im Verständnis ihres geistlichen Dienstes, in der Theorie, in Grundsätzlichem und in der Lehre, in allem, was das Reich Gottes auf Erden betrifft; und die Schlüssel dieses Reiches sind euch übertragen worden."},{"verse":15,"text":"Und insofern mir mein Volk im Namen des Herrn ein Haus baut und nicht zulässt, dass etwas Unreines hineingelangt, damit es nicht entweiht werde, wird meine Herrlichkeit darauf ruhen;"},{"verse":16,"text":"ja, und meine Gegenwart wird da sein, denn ich werde dorthin kommen; und alle, die im Herzen rein sind, die dorthin kommen, werden Gott sehen."},{"verse":17,"text":"Aber wenn es entweiht wird, werde ich nicht dorthin kommen, und meine Herrlichkeit wird nicht da sein; denn ich komme nicht in unheilige Tempel."},{"verse":18,"text":"Und nun, siehe, wenn Zion dies tut, so wird es gedeihen und sich ausbreiten und sehr herrlich werden, sehr groß und sehr schrecklich."},{"verse":19,"text":"Und die Nationen der Erde werden es ehren und werden sagen: Gewisslich ist Zion die Stadt unseres Gottes, und gewisslich kann Zion nicht stürzen noch von seinem Platz entfernt werden, denn Gott ist da, und die Hand des Herrn ist da;"},{"verse":20,"text":"und er hat bei der Gewalt seiner Macht geschworen, er werde Zions Errettung und hoher Turm sein."},{"verse":21,"text":"Darum wahrlich, so spricht der Herr: Lasst Zion sich freuen, denn dies ist Zion – die im Herzen Reinen; darum lasst Zion sich freuen, während alle Schlechten trauern."},{"verse":22,"text":"Denn siehe, ja siehe, Vergeltung kommt schnell über die Gottlosen wie der Wirbelsturm; und wer wird ihr entrinnen?"},{"verse":23,"text":"Die Geißel des Herrn wird bei Nacht und bei Tag darüber hinstreichen, und die Nachricht davon wird alles Volk plagen; ja, ihr wird nicht Einhalt geboten, bis der Herr kommt;"},{"verse":24,"text":"denn der Unwille des Herrn ist gegen ihre Gräuel und all ihre schlechten Werke entflammt."},{"verse":25,"text":"Doch Zion wird entrinnen, wenn es darauf bedacht ist, alles zu tun, was auch immer ich ihm geboten habe."},{"verse":26,"text":"Wenn es aber nicht darauf bedacht ist zu tun, was auch immer ich ihm geboten habe, werde ich es gemäß all seinen Werken heimsuchen: mit schwerer Bedrängnis, mit Seuche, mit Plage, mit dem Schwert, mit Vergeltung, mit verzehrendem Feuer."},{"verse":27,"text":"Doch lasst es dieses eine Mal vor seinen Ohren verlesen, dass ich, der Herr, sein Opfer angenommen habe; und wenn Zion nicht mehr sündigt, wird nichts davon über es kommen,"},{"verse":28,"text":"und ich werde es mit Segnungen segnen und ihm eine Vielfalt von Segnungen vervielfachen, ihm und seinen Generationen für immer und immer, spricht der Herr, euer Gott. Amen."}]},{"chapter":98,"verses":[{"verse":1,"text":"Wahrlich, ich sage euch, meine Freunde: Fürchtet euch nicht, euer Herz sei getrost; ja, freut euch immerdar, und gebt in allem Dank;"},{"verse":2,"text":"harrt geduldig auf den Herrn, denn eure Gebete sind dem Herrn Zebaot in die Ohren gedrungen und sind mit diesem Siegel und Zeugnis aufgezeichnet: Der Herr hat geschworen und beschlossen, dass sie gewährt werden sollen."},{"verse":3,"text":"Darum gibt er euch diese Verheißung mit dem unwandelbaren Bündnis, dass sie erfüllt werden sollen; und alles, womit ihr bedrängt worden seid, wird zu eurem Guten zusammenwirken und zur Verherrlichung meines Namens, spricht der Herr."},{"verse":4,"text":"Und nun, wahrlich, ich sage euch in Bezug auf die Gesetze des Landes: Es ist mein Wille, dass mein Volk darauf bedacht sei, alles zu tun, was auch immer ich ihm gebiete."},{"verse":5,"text":"Und ein Landesgesetz, das verfassungsmäßig ist und bei der Aufrechterhaltung von Rechten und Freiheiten den Grundsatz der Freiheit stützt, gehört der ganzen Menschheit und lässt sich vor mir rechtfertigen."},{"verse":6,"text":"Darum rechtfertige ich, der Herr, euch und eure Brüder in meiner Kirche, wenn ihr jenes Gesetz unterstützt, das das verfassungsmäßige Gesetz des Landes ist;"},{"verse":7,"text":"und, was menschliches Gesetz betrifft, was auch immer mehr oder weniger ist als dies, kommt vom Bösen."},{"verse":8,"text":"Ich, Gott, der Herr, mache euch frei, darum seid ihr wirklich frei; und das Gesetz macht euch auch frei."},{"verse":9,"text":"Doch wenn die Schlechten herrschen, trauert das Volk."},{"verse":10,"text":"Nach ehrlichen Menschen und weisen Menschen soll man darum eifrig suchen, und gute Menschen und weise Menschen sollt ihr bedacht sein zu unterstützen; andernfalls, was auch immer weniger ist als diese, kommt vom Bösen."},{"verse":11,"text":"Und ich gebe euch das Gebot, dass ihr von allem Bösen lasst und an allem Guten festhaltet, dass ihr von jedem Wort lebt, das aus dem Mund Gottes hervorkommt."},{"verse":12,"text":"Denn er gibt den Getreuen Zeile um Zeile, Weisung um Weisung; und ich will euch hiermit prüfen und erproben."},{"verse":13,"text":"Und wer auch immer sein Leben in meiner Sache niederlegt, um meines Namens willen, wird es wiederfinden, selbst ewiges Leben."},{"verse":14,"text":"Darum fürchtet euch nicht vor euren Feinden; denn ich habe in meinem Herzen beschlossen, spricht der Herr, euch in allem zu erproben, ob ihr in meinem Bund verbleiben werdet, selbst bis zum Tod, damit ihr für würdig befunden werden könnt."},{"verse":15,"text":"Denn wenn ihr nicht in meinem Bund verbleibt, seid ihr meiner nicht würdig."},{"verse":16,"text":"Darum entsagt dem Krieg und verkündigt Frieden, und trachtet eifrig danach, das Herz der Kinder ihren Vätern zuzuwenden und das Herz der Väter den Kindern,"},{"verse":17,"text":"und weiter, das Herz der Juden den Propheten und der Propheten den Juden, damit ich nicht komme und die ganze Erde mit einem Fluch schlage und alles Fleisch verzehrt werde vor mir."},{"verse":18,"text":"Euer Herz beunruhige sich nicht; denn in meines Vaters Haus sind viele Wohnungen, und ich habe einen Platz für euch bereitet; und wo mein Vater und ich sind, da werdet auch ihr sein."},{"verse":19,"text":"Siehe, ich, der Herr, habe kein Wohlgefallen an vielen, die in der Gemeinde in Kirtland sind;"},{"verse":20,"text":"denn sie lassen nicht von ihren Sünden und ihren schlechten Wegen, dem Stolz ihres Herzens und ihrer Habgier und all ihrem Abscheulichen und beachten nicht die Worte der Weisheit und des ewigen Lebens, die ich ihnen gegeben habe."},{"verse":21,"text":"Wahrlich, ich sage euch: Ich, der Herr, werde sie züchtigen und werde tun, was auch immer mir beliebt, wenn sie nicht umkehren und alles beachten, was auch immer ich ihnen gesagt habe."},{"verse":22,"text":"Und weiter sage ich zu euch: Wenn ihr darauf bedacht seid zu tun, was auch immer ich euch gebiete, so werde ich, der Herr, allen Grimm und Unwillen von euch abwenden, und die Pforten der Hölle werden euch nicht überwältigen."},{"verse":23,"text":"Nun spreche ich zu euch in Bezug auf eure Familien: Wenn die Menschen euch oder eure Familie einmal schlagen und ihr es geduldig tragt und sie nicht schmäht, auch nicht nach Rache trachtet, so werdet ihr belohnt werden;"},{"verse":24,"text":"tragt ihr es aber nicht geduldig, dann wird es euch so angerechnet werden, als sei es euch mit einem rechten Maß zugemessen worden."},{"verse":25,"text":"Und weiter: Wenn euer Feind euch zum zweiten Mal schlägt und ihr euren Feind nicht schmäht und es geduldig tragt, so wird euer Lohn hundertfach sein."},{"verse":26,"text":"Und weiter: Wenn er euch zum dritten Mal schlägt und ihr es geduldig tragt, so wird euer Lohn euch vierfach verdoppelt werden;"},{"verse":27,"text":"und diese drei Zeugnisse werden gegen euren Feind stehen, wenn er nicht umkehrt, und werden nicht ausgelöscht werden."},{"verse":28,"text":"Und nun, wahrlich, ich sage euch: Wenn jener Feind meiner Vergeltung entrinnen soll, sodass er nicht vor mich zum Gericht gebracht wird, so müsst ihr zusehen, dass ihr ihn in meinem Namen davor warnt, noch jemals über euch zu kommen, auch nicht über eure Familie, selbst eure Kindeskinder bis zur dritten und vierten Generation."},{"verse":29,"text":"Und wenn er dann über euch oder eure Kinder oder eure Kindeskinder bis zur dritten und vierten Generation kommt, habe ich deinen Feind in deine Hände gegeben;"},{"verse":30,"text":"und wenn du ihn dann noch verschonst, wirst du für deine Rechtschaffenheit belohnt werden, ebenso deine Kinder und deine Kindeskinder bis zur dritten und vierten Generation."},{"verse":31,"text":"Doch ist dein Feind in deinen Händen, und wenn du ihm gemäß seinen Werken vergiltst, bist du gerechtfertigt; wenn er dir nach dem Leben getrachtet hat und dein Leben durch ihn gefährdet ist, so ist dein Feind in deinen Händen, und du bist gerechtfertigt."},{"verse":32,"text":"Siehe, dies ist das Gesetz, das ich meinem Diener Nephi und deinen Vätern Josef und Jakob und Isaak und Abraham sowie all meinen Propheten und Aposteln in alter Zeit gegeben habe."},{"verse":33,"text":"Und weiter: Dies ist das Gesetz, das ich den Meinen in alter Zeit gegeben habe, dass sie gegen keine Nation, kein Geschlecht, keine Sprache oder kein Volk zum Kampf ziehen sollten, außer ich, der Herr, geböte es ihnen."},{"verse":34,"text":"Und wenn irgendeine Nation oder Sprache oder irgendein Volk ihnen den Krieg erklären würde, sollten sie jenem Volk, jener Nation oder Sprache zunächst ein Friedensbanner emporheben;"},{"verse":35,"text":"und wenn jenes Volk das Friedensangebot nicht annehmen würde, auch nicht beim zweiten oder dritten Mal, dann sollten sie diese Zeugnisse vor den Herrn bringen;"},{"verse":36,"text":"dann würde ich, der Herr, ihnen ein Gebot geben und sie rechtfertigen, wenn sie dann zum Kampf gegen jene Nation oder Sprache oder jenes Volk ziehen würden."},{"verse":37,"text":"Und ich, der Herr, würde ihre Schlachten schlagen und die Schlachten ihrer Kinder und ihrer Kindeskinder, bis sie sich an all ihren Feinden gerächt hätten bis zur dritten und vierten Generation."},{"verse":38,"text":"Siehe, dies ist ein Beispiel für alle Völker, spricht der Herr, euer Gott, zur Rechtfertigung vor mir."},{"verse":39,"text":"Und weiter, wahrlich, ich sage euch: Wenn dein Feind, nachdem er zum ersten Mal über dich gekommen ist, umkehrt und zu dir kommt und um deine Vergebung bittet, sollst du ihm vergeben und sollst es nicht weiter als Zeugnis gegen deinen Feind beibehalten –"},{"verse":40,"text":"und so fort bis zum zweiten und dritten Mal; und sooft dein Feind von der Verfehlung, womit er gegen dich gefehlt hat, umkehrt, sollst du ihm vergeben, bis zu siebzigmal siebenmal."},{"verse":41,"text":"Und wenn er gegen dich fehlt und beim ersten Mal nicht umkehrt, sollst du ihm dennoch vergeben."},{"verse":42,"text":"Und wenn er zum zweiten Mal gegen dich fehlt und nicht umkehrt, sollst du ihm dennoch vergeben."},{"verse":43,"text":"Und wenn er zum dritten Mal gegen dich fehlt und nicht umkehrt, sollst du ihm auch vergeben."},{"verse":44,"text":"Aber wenn er zum vierten Mal gegen dich fehlt, sollst du ihm nicht vergeben, sondern sollst diese Zeugnisse vor den Herrn bringen; und sie werden nicht ausgelöscht werden, bis er umkehrt und dich für alles, womit er gegen dich gefehlt hat, vierfach entschädigt."},{"verse":45,"text":"Und wenn er das tut, sollst du ihm von ganzem Herzen vergeben; und wenn er das nicht tut, werde ich, der Herr, dich an deinem Feind hundertfach rächen,"},{"verse":46,"text":"auch an seinen Kindern und an seinen Kindeskindern, an ihnen allen, die mich hassen, bis zur dritten und vierten Generation."},{"verse":47,"text":"Aber wenn die Kinder oder die Kindeskinder umkehren und sich mit ihrem ganzen Herzen und mit all ihrer Macht, ganzem Sinn und aller Kraft zum Herrn, ihrem Gott, wenden und alle ihre Verfehlungen, womit sie gefehlt haben oder womit ihre Väter oder ihre Vatersväter gefehlt haben, vierfach gutmachen, dann soll sich dein Unwille abwenden,"},{"verse":48,"text":"und Vergeltung soll nicht mehr über sie kommen, spricht der Herr, dein Gott, und ihre Verfehlungen sollen nie mehr als Zeugnis gegen sie vor den Herrn gebracht werden. Amen."}]},{"chapter":99,"verses":[{"verse":1,"text":"Siehe, so spricht der Herr zu meinem Diener John Murdock: Du wirst berufen, in die östlichen Länder zu gehen, von Haus zu Haus, von Dorf zu Dorf und von Stadt zu Stadt, um deren Einwohnern mein immerwährendes Evangelium zu verkündigen, inmitten von Verfolgung und Schlechtigkeit."},{"verse":2,"text":"Und wer dich empfängt, der empfängt mich; und du wirst die Macht haben, in der Kundgebung meines Heiligen Geistes mein Wort zu verkünden."},{"verse":3,"text":"Und wer dich empfängt wie ein kleines Kind, der empfängt mein Reich; und gesegnet ist er, denn er wird Barmherzigkeit erlangen."},{"verse":4,"text":"Und wer auch immer dich verwirft, der wird von meinem Vater und seinem Haus verworfen werden; und du sollst dir an verborgener Stelle am Weg zum Zeugnis gegen ihn die Füße säubern."},{"verse":5,"text":"Und siehe, ja siehe, ich komme schnell zum Gericht, um alle von ihren gottlosen Taten zu überzeugen, die sie gegen mich verübt haben, wie es in der Rolle des Buches über mich geschrieben steht."},{"verse":6,"text":"Und nun, wahrlich, ich sage dir: Es ist nicht ratsam, dass du gehst, ehe für deine Kinder gesorgt ist und sie wohlwollend an den Bischof in Zion gesandt worden sind."},{"verse":7,"text":"Und nach ein paar Jahren, wenn du das von mir wünschst, magst du auch in das gute Land hinaufgehen und dein Erbteil in Besitz nehmen;"},{"verse":8,"text":"andernfalls sollst du weiterhin mein Evangelium verkündigen, bis du hinweggenommen wirst. Amen."}]},{"chapter":100,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr zu euch, meine Freunde Sidney und Joseph: Euren Familien geht es gut; sie sind in meiner Hand, und ich werde mit ihnen tun, wie es mir gut scheint; denn in mir ist alle Macht."},{"verse":2,"text":"Darum folgt mir nach, und hört auf den Rat, den ich euch geben werde."},{"verse":3,"text":"Siehe, ja siehe, ich habe viel Volk an diesem Ort, in den Gebieten ringsum; und eine wirksame Tür wird sich öffnen in den Gebieten ringsum in diesem Land im Osten."},{"verse":4,"text":"Darum habe ich, der Herr, euch an diesen Ort kommen lassen; denn so war es mir zur Errettung von Seelen ratsam."},{"verse":5,"text":"Darum, wahrlich, ich sage euch: Erhebt eure Stimme gegenüber diesem Volk; sprecht die Gedanken aus, die ich euch ins Herz geben werde, dann werdet ihr vor den Menschen nicht zuschanden werden;"},{"verse":6,"text":"denn es wird euch zur selben Stunde, ja, im selben Augenblick eingegeben werden, was ihr sagen sollt."},{"verse":7,"text":"Aber ein Gebot gebe ich euch, dass ihr, was auch immer ihr in meinem Namen verkündigt, es in allem mit Herzensfeierlichkeit, im Geist der Sanftmut verkündigt."},{"verse":8,"text":"Und ich gebe euch diese Verheißung: Insoweit ihr das tut, wird der Heilige Geist ausgegossen werden, damit er für alles, was auch immer ihr sagen werdet, Zeugnis gebe."},{"verse":9,"text":"Und es ist mir ratsam, dass du, mein Diener Sidney, diesem Volk ein Sprecher seist; ja, wahrlich, ich werde dich zu dieser Berufung ordinieren, nämlich der Sprecher meines Dieners Joseph zu sein."},{"verse":10,"text":"Und ich werde ihm die Macht geben, mächtig zu sein im Zeugnis."},{"verse":11,"text":"Und ich werde dir die Macht geben, mächtig zu sein im Erläutern aller Schriften, damit du für ihn ein Sprecher sein kannst, und er wird für dich ein Offenbarer sein, damit du alles mit Gewissheit erkennen kannst, was die Belange meines Reiches auf Erden betrifft."},{"verse":12,"text":"Darum setzt eure Reise fort, und euer Herz möge sich freuen; denn siehe, ja siehe, ich bin bei euch, ja, bis ans Ende."},{"verse":13,"text":"Und nun gebe ich euch ein Wort in Bezug auf Zion. Zion wird erlöst werden, wenn es auch eine kurze Zeit lang gezüchtigt werden wird."},{"verse":14,"text":"Eure Brüder, meine Diener Orson Hyde und John Gould, sind in meiner Hand; und insoweit sie meine Gebote halten, werden sie errettet werden."},{"verse":15,"text":"Darum sei euer Herz getrost; denn alles wird für diejenigen, die untadelig wandeln, zu ihrem Guten zusammenwirken und zur Heiligung der Kirche."},{"verse":16,"text":"Denn ich werde mir ein reines Volk erwecken, das mir in Rechtschaffenheit dient;"},{"verse":17,"text":"und alle, die den Namen des Herrn anrufen und seine Gebote halten, werden errettet werden. So ist es. Amen."}]},{"chapter":101,"verses":[{"verse":1,"text":"Wahrlich, ich sage euch in Bezug auf eure Brüder, die bedrängt und verfolgt und aus dem Land ihres Erbteils ausgestoßen worden sind:"},{"verse":2,"text":"Ich, der Herr, habe zugelassen, dass die Bedrängnis, womit sie bedrängt worden sind, infolge ihrer Übertretungen über sie gekommen ist;"},{"verse":3,"text":"und doch werde ich sie als mein Eigen anerkennen, und sie werden mein sein an jenem Tag, da ich komme, meine Juwelen herzurichten."},{"verse":4,"text":"Darum müssen sie notwendigerweise gezüchtigt und geprüft werden so wie Abraham, dem geboten war, seinen einzigen Sohn darzubringen."},{"verse":5,"text":"Denn alle diejenigen, die Züchtigung nicht ertragen wollen, sondern mich leugnen, können nicht geheiligt werden."},{"verse":6,"text":"Siehe, ich sage euch: Es hat Misstöne und Streitigkeiten und Neid und Streit und lüsterne und habgierige Wünsche unter ihnen gegeben; und damit haben sie ihre Erbteile verunreinigt."},{"verse":7,"text":"Sie waren langsam, auf die Stimme des Herrn, ihres Gottes, zu hören; darum ist der Herr, ihr Gott, langsam, auf ihr Beten zu hören und ihnen am Tag ihrer Beunruhigung darauf Antwort zu geben."},{"verse":8,"text":"Am Tag ihres Friedens haben sie meinen Rat geringgeschätzt; aber am Tag ihrer Beunruhigung, da fühlen sie notgedrungen nach mir."},{"verse":9,"text":"Wahrlich, ich sage euch: Ungeachtet ihrer Sünden ist mein Inneres von Mitleid für sie erfüllt. Ich werde sie nicht völlig verstoßen; und am Tag des Grimms werde ich der Barmherzigkeit gedenken."},{"verse":10,"text":"Ich habe geschworen, und der Beschluss ist durch ein Gebot, das ich euch früher gegeben habe, hinausgegangen, dass ich das Schwert meines Unwillens um meines Volkes willen niederfallen lassen werde; und so, wie ich es gesagt habe, wird es sich begeben."},{"verse":11,"text":"Mein Unwille wird sich bald ohne Maß über alle Nationen ergießen; und das werde ich tun, wenn der Becher ihres Übeltuns voll ist."},{"verse":12,"text":"Und an jenem Tag werden alle, die sich auf dem Wachtturm befinden, oder, mit anderen Worten, mein ganzes Israel, errettet werden."},{"verse":13,"text":"Und diejenigen, die zerstreut worden sind, werden gesammelt werden."},{"verse":14,"text":"Und alle diejenigen, die getrauert haben, werden getröstet werden."},{"verse":15,"text":"Und alle diejenigen, die ihr Leben für meinen Namen hingegeben haben, werden gekrönt werden."},{"verse":16,"text":"Darum sei euer Herz in Bezug auf Zion getrost, denn alles Fleisch ist in meiner Hand; seid ruhig und wisst, dass ich Gott bin."},{"verse":17,"text":"Zion wird nicht von seinem Platz entfernt werden, auch wenn seine Kinder zerstreut worden sind."},{"verse":18,"text":"Die übrigbleiben und im Herzen rein sind, werden zurückkehren und zu ihren Erbteilen hinkommen, sie und ihre Kinder, mit Gesängen immerwährender Freude, um die verwüsteten Stätten Zions aufzubauen –"},{"verse":19,"text":"und dies alles, damit die Propheten sich erfüllen."},{"verse":20,"text":"Und siehe, es ist kein anderer Platz bestimmt als der, den ich bestimmt habe; und es wird auch kein anderer Platz bestimmt werden als der, den ich für das Werk der Sammlung meiner Heiligen bestimmt habe,"},{"verse":21,"text":"bis der Tag kommt, da sich für sie kein Raum mehr findet; und dann habe ich andere Plätze, die ich ihnen bestimmen werde, und sie werden Pfähle genannt werden, für die Zeltbehänge oder die Stärke Zions."},{"verse":22,"text":"Siehe, es ist mein Wille, dass alle, die meinen Namen anrufen und mich gemäß meinem immerwährenden Evangelium anbeten, sich sammeln und an heiligen Stätten stehen"},{"verse":23,"text":"und sich für die Offenbarung bereitmachen, die kommen wird, wenn der Schleier der Bedeckung meines Tempels, in meiner Wohnstätte, der die Erde verhüllt, weggenommen werden wird und alles Fleisch miteinander mich sehen wird."},{"verse":24,"text":"Und alles Verwesliche, sei es am Menschen oder an den Tieren des Feldes oder den Vögeln des Himmels oder den Fischen des Meeres, das auf der ganzen Erde wohnt, wird verzehrt werden;"},{"verse":25,"text":"und auch was aus Elementen ist, wird vor glühender Hitze schmelzen; und alles wird neu werden, damit meine Erkenntnis und Herrlichkeit auf der ganzen Erde wohnen kann."},{"verse":26,"text":"Und an jenem Tag wird die Feindschaft der Menschen und die Feindschaft der Tiere, ja, die Feindschaft allen Fleisches aufhören vor meinem Angesicht."},{"verse":27,"text":"Und an jenem Tag wird, was auch immer jemand erbittet, ihm gegeben werden."},{"verse":28,"text":"Und an jenem Tag wird der Satan nicht die Macht haben, jemanden zu versuchen."},{"verse":29,"text":"Und es wird kein Leid geben, weil es keinen Tod gibt."},{"verse":30,"text":"An jenem Tag wird ein kleines Kind nicht sterben, ehe es alt ist; und sein Leben wird wie das Alter eines Baumes sein;"},{"verse":31,"text":"und wenn es stirbt, wird es nicht schlafen, das heißt in der Erde, sondern wird in einem Augenblick verwandelt werden und wird entrückt werden, und seine Ruhe wird herrlich sein."},{"verse":32,"text":"Ja, wahrlich, ich sage euch: An jenem Tag, da der Herr kommt, wird er alles offenbaren –"},{"verse":33,"text":"das, was vergangen ist, und Verborgenes, was niemand gewusst hat, das, was die Erde betrifft, wodurch sie gemacht worden ist, und ihren Zweck und ihr Ende –"},{"verse":34,"text":"höchst Kostbares, das, was oben ist, und das, was unten ist, das, was in der Erde und auf der Erde und im Himmel ist."},{"verse":35,"text":"Und alle, die um meines Namens willen Verfolgung leiden und im Glauben ausharren, werden, auch wenn sie aufgerufen sind, um meinetwillen ihr Leben niederzulegen, dennoch an all dieser Herrlichkeit teilhaben."},{"verse":36,"text":"Darum fürchtet euch nicht, auch nicht vor dem Tod; denn in dieser Welt ist eure Freude nicht voll, aber in mir ist eure Freude voll."},{"verse":37,"text":"Darum sorgt euch nicht um den Leib, auch nicht um das Leben des Leibes, sondern sorgt euch um die Seele und um das Leben der Seele."},{"verse":38,"text":"Und trachtet immer nach dem Angesicht des Herrn, damit ihr euch mit Ausdauer eure Seele zu eigen macht; dann werdet ihr ewiges Leben haben."},{"verse":39,"text":"Wenn Menschen zu meinem immerwährenden Evangelium berufen werden und sich durch einen immerwährenden Bund binden, so sind sie als das Salz der Erde zu betrachten und die Würzkraft der Menschen;"},{"verse":40,"text":"sie sind berufen, den Menschen Würzkraft zu sein; darum, wenn jenes Salz der Erde seine Würzkraft verliert, siehe, ist es hinfort zu nichts mehr nütze, als hinausgeworfen und von den Menschen zertreten zu werden."},{"verse":41,"text":"Siehe, hier ist Weisheit in Bezug auf die Kinder Zion, ja, viele, aber nicht alle; sie sind als Übertreter befunden worden, darum müssen sie notwendigerweise gezüchtigt werden –"},{"verse":42,"text":"wer sich selbst erhöht, der wird erniedrigt werden, und wer sich selbst erniedrigt, der wird erhöht werden."},{"verse":43,"text":"Und nun will ich euch ein Gleichnis zeigen, damit ihr meinen Willen in Bezug auf die Erlösung Zions kennt."},{"verse":44,"text":"Ein gewisser Edelmann hatte ein auserlesenes Stück Land, und er sprach zu seinen Dienern: Geht in meinen Weingarten, ja, zu genau diesem auserlesenen Stück Land, und pflanzt zwölf Ölbäume;"},{"verse":45,"text":"und stellt rings um sie Wächter auf, und baut einen Turm, damit einer, der der Wächter auf dem Turm sein soll, das Land ringsum überblicke, damit nicht meine Ölbäume niedergebrochen werden, wenn der Feind kommt, um zu plündern und die Frucht meines Weingartens an sich zu nehmen."},{"verse":46,"text":"Nun gingen die Diener des Edelmanns hin und taten, wie ihr Herr ihnen geboten hatte, und pflanzten die Ölbäume und setzten ringsum eine Hecke und stellten Wächter auf und fingen an, einen Turm zu bauen."},{"verse":47,"text":"Und während sie noch dabei waren, dessen Grundlage zu legen, fingen sie an, bei sich zu sprechen: Und wozu braucht mein Herr diesen Turm?"},{"verse":48,"text":"Und berieten eine lange Zeit und sprachen bei sich: Wozu braucht mein Herr diesen Turm, wo dies doch eine Zeit des Friedens ist?"},{"verse":49,"text":"Könnte man dieses Geld nicht zu den Wechslern geben? Denn dies hier ist nicht nötig."},{"verse":50,"text":"Und während sie so untereinander uneins waren, wurden sie sehr träge, und sie hörten nicht auf die Gebote ihres Herrn."},{"verse":51,"text":"Und der Feind kam bei Nacht und brach die Hecke nieder; und die Diener des Edelmanns erhoben sich und waren erschrocken und flohen; und der Feind zerstörte ihre Arbeit und brach die Ölbäume nieder."},{"verse":52,"text":"Nun siehe, der Edelmann, der Herr des Weingartens, rief seine Diener zusammen und sprach zu ihnen: Nun? Was ist der Grund für dieses große Übel?"},{"verse":53,"text":"Hättet ihr nicht tun sollen, wie ich euch geboten habe, und – nachdem ihr den Weingarten bepflanzt und die Hecke ringsum gesetzt und Wächter auf die Wälle gestellt hattet – auch den Turm bauen und auf den Turm einen Wächter setzen und meinen Weingarten bewachen und nicht einschlafen sollen, damit nicht der Feind über euch komme?"},{"verse":54,"text":"Und siehe, der Wächter auf dem Turm hätte den Feind gesehen, solange er noch weit weg war; und dann hättet ihr euch bereitmachen und den Feind daran hindern können, die Hecke niederzubrechen, und hättet meinen Weingarten vor den Händen des Zerstörers gerettet."},{"verse":55,"text":"Und der Herr des Weingartens sprach zu einem seiner Diener: Gehe hin und hole meine übrigen Diener zusammen, und nimm die ganze Stärke meines Hauses, nämlich meine Krieger, meine Jünglinge und auch die von mittlerem Alter unter all meinen Dienern, die die Stärke meines Hauses sind, ausgenommen nur diejenigen, die ich bestimmt habe dazubleiben;"},{"verse":56,"text":"und geht geradewegs zum Land meines Weingartens, und befreit meinen Weingarten; denn er ist mein, ich habe ihn mit Geld gekauft."},{"verse":57,"text":"Darum geht geradewegs zu meinem Land; brecht die Wälle meiner Feinde nieder, stürzt ihren Turm um, und zerstreut ihre Wächter."},{"verse":58,"text":"Und insoweit sie sich gegen euch sammeln, verschafft mir Recht gegen meine Feinde, damit ich bald mit meinem übrigen Haus kommen und das Land besitzen kann."},{"verse":59,"text":"Und der Diener sprach zu seinem Herrn: Wann wird das sein?"},{"verse":60,"text":"Und er sprach zu seinem Diener: Wann ich will; gehe du geradewegs und tu alles, was auch immer ich dir geboten habe;"},{"verse":61,"text":"und dies wird mein Siegel und Segen auf dir sein – ein getreuer und weiser Treuhänder inmitten meines Hauses, ein Herrscher in meinem Reich."},{"verse":62,"text":"Und sein Diener ging geradewegs und tat alles, was auch immer sein Herr ihm geboten hatte; und nach vielen Tagen erfüllte sich alles."},{"verse":63,"text":"Weiter, wahrlich, ich sage euch: Ich werde euch in Bezug auf alle die Gemeinden zeigen, was nach meiner Weisheit ist, insoweit sie willens sind, sich auf die rechte und angemessene Weise zu ihrer Errettung führen zu lassen –"},{"verse":64,"text":"damit das Werk der Sammlung meiner Heiligen weitergehe, damit ich sie an heiligen Stätten zu meinem Namen erbaue; denn die Zeit der Ernte ist da, und mein Wort muss sich notwendigerweise erfüllen."},{"verse":65,"text":"Darum muss ich mein Volk sammeln gemäß dem Gleichnis vom Weizen und dem Unkraut, damit der Weizen in den Speichern gesichert werde, um ewiges Leben zu besitzen und mit celestialer Herrlichkeit gekrönt zu werden, wenn ich im Reich meines Vaters kommen werde, um einem jeden gemäß dem zu vergelten, wie seine Werke sein werden;"},{"verse":66,"text":"während das Unkraut in Bündel gebunden werden wird, und seine Bande werden stark sein, damit es in unauslöschlichem Feuer verbrannt werde."},{"verse":67,"text":"Darum gebe ich allen Gemeinden das Gebot, sich weiterhin an den Orten zu sammeln, die ich bestimmt habe."},{"verse":68,"text":"Doch soll, wie ich euch in einem früheren Gebot gesagt habe, eure Sammlung nicht in Hast vor sich gehen, auch nicht als Flucht; sondern lasst alles vor euch bereitmachen."},{"verse":69,"text":"Und damit alles vor euch bereitgemacht sei, sollt ihr das Gebot beachten, das ich diesbezüglich gegeben habe –"},{"verse":70,"text":"welches besagt oder lehrt, alle Ländereien im Gebiet rings um das Land, das ich bestimmt habe, das Land Zion zu sein, soweit sie mit Geld zu kaufen sind, mit Geld zu kaufen, für den Beginn der Sammlung meiner Heiligen,"},{"verse":71,"text":"alles Land, was im Landkreis Jackson und in den Landkreisen ringsum gekauft werden kann; und lasst das Übrige in meiner Hand."},{"verse":72,"text":"Nun wahrlich, ich sage euch: Alle Gemeinden sollen alle ihre Gelder zusammentragen; das soll aber zu seiner Zeit geschehen, und nicht in Hast; und achtet darauf, dass alles vor euch bereitgemacht sei."},{"verse":73,"text":"Und ehrenhafte Männer sollen bestimmt werden, ja, weise Männer, und sendet sie hin, diese Ländereien zu kaufen."},{"verse":74,"text":"Und die Gemeinden in den östlichen Ländern können, sobald sie aufgebaut sind und wenn sie auf diesen Rat hören wollen, Ländereien kaufen und sich auf ihnen sammeln; und auf diese Weise können sie Zion errichten."},{"verse":75,"text":"Schon jetzt ist bereits genügend vorhanden, ja, sogar reichlich, um Zion zu erlösen und seine verwüsteten Stätten aufzubauen, um nie mehr niedergeworfen zu werden, wenn nur die Gemeinden, die sich nach meinem Namen nennen, auf meine Stimme hören wollten."},{"verse":76,"text":"Und weiter sage ich euch, nämlich was diejenigen betrifft, die von ihren Feinden zerstreut worden sind: Es ist mein Wille, dass sie weiterhin Wiedergutmachung und Entschädigung durch die Hand derer fordern, die als Herrscher gesetzt sind und Vollmacht über euch haben –"},{"verse":77,"text":"gemäß den Gesetzen und der Verfassung des Volkes, die ich habe einrichten lassen und die für die Rechte und zum Schutz allen Fleisches aufgrund von gerechten und heiligen Grundsätzen aufrechterhalten werden sollen,"},{"verse":78,"text":"damit jedermann in der Lehre und dem Grundsätzlichen, was die Zukunft betrifft, gemäß der sittlichen Entscheidungsfreiheit handeln kann, die ich ihm gegeben habe, damit jedermann am Tag des Gerichts für seine Sünden selbst verantwortlich sei."},{"verse":79,"text":"Darum ist es nicht recht, dass irgendjemand in der Knechtschaft eines anderen sei."},{"verse":80,"text":"Und zu diesem Zweck habe ich die Verfassung dieses Landes durch die Hand weiser Männer eingerichtet, die ich zu genau diesem Zweck erweckt habe, und habe das Land durch Blutvergießen befreit."},{"verse":81,"text":"Nun, womit soll ich die Kinder Zion vergleichen? Ich will auf sie das Gleichnis von der Frau und dem ungerechten Richter anwenden, denn die Menschen sollen allezeit beten und nicht ermatten; und dort heißt es:"},{"verse":82,"text":"Es war ein Richter in einer Stadt, der fürchtete sich nicht vor Gott und scheute sich vor keinem Menschen."},{"verse":83,"text":"Und es war eine Witwe in jener Stadt, und sie kam zu ihm und sprach: Verschaffe mir Recht gegen meinen Widersacher."},{"verse":84,"text":"Und er wollte eine Zeit lang nicht; danach aber dachte er bei sich selbst: Obschon ich mich vor Gott nicht fürchte und vor keinem Menschen scheue, so will ich doch dieser Witwe, weil sie mich so behelligt, ihr Recht verschaffen, damit sie nicht unaufhörlich kommt und mich ermüdet."},{"verse":85,"text":"Hiermit will ich die Kinder Zion vergleichen."},{"verse":86,"text":"Sie sollen zu Füßen des Richters fordern;"},{"verse":87,"text":"und wenn er sie nicht beachtet, sollen sie zu Füßen des Gouverneurs fordern;"},{"verse":88,"text":"und wenn der Gouverneur sie nicht beachtet, sollen sie zu Füßen des Präsidenten fordern;"},{"verse":89,"text":"und wenn der Präsident sie nicht beachtet, dann wird der Herr sich erheben und aus seinem Versteck hervortreten und in seinem Ungestüm die Nation plagen;"},{"verse":90,"text":"und in seinem glühenden Unmut und in seinem grimmigen Zorn wird er zu seiner Zeit jene schlechten, ungetreuen und ungerechten Treuhänder ausstoßen und ihnen ihr Teil bei den Heuchlern und Ungläubigen bestimmen,"},{"verse":91,"text":"ja, in der äußeren Finsternis, wo es Weinen und Wehklagen und Zähneknirschen gibt."},{"verse":92,"text":"Darum betet, dass ihre Ohren für euer Schreien offen sein mögen, damit ich zu ihnen barmherzig sein kann, damit dies nicht über sie komme."},{"verse":93,"text":"Was ich euch gesagt habe, muss notwendigerweise geschehen, damit alle Menschen ohne Entschuldigung seien;"},{"verse":94,"text":"damit weise Männer und Herrscher das hören und erkennen mögen, was sie nie wahrgenommen haben;"},{"verse":95,"text":"damit ich darangehen kann, meine Tat, meine seltsame Tat, zu vollbringen und mein Werk, mein seltsames Werk, zu tun, damit die Menschen den Unterschied sehen mögen zwischen den Rechtschaffenen und den Schlechten, spricht euer Gott."},{"verse":96,"text":"Und weiter, ich sage euch: Es ist gegen mein Gebot und meinen Willen, dass mein Diener Sidney Gilbert mein Vorratshaus, das ich für mein Volk bestimmt habe, in die Hände meiner Feinde verkaufe."},{"verse":97,"text":"Lasst das, was ich bestimmt habe, nicht mit Zustimmung derjenigen, die sich nach meinem Namen nennen, durch meine Feinde verunreinigt werden;"},{"verse":98,"text":"denn das ist eine sehr schmerzliche und schwere Sünde gegen mich und gegen mein Volk, infolge all dessen, was ich beschlossen habe und was bald die Nationen befallen wird."},{"verse":99,"text":"Darum ist es mein Wille, dass mein Volk das, was ich ihm bestimmt habe, beansprucht und den Anspruch aufrechterhält, auch wenn es ihm nicht erlaubt sein sollte, darauf zu wohnen."},{"verse":100,"text":"Doch sage ich nicht, dass es nicht darauf wohnen werde; denn insoweit es Frucht und Werke hervorbringt, die meinem Reich angemessen sind, wird es darauf wohnen."},{"verse":101,"text":"Es wird bauen, und kein anderer wird es ererben; es wird Weingärten pflanzen, und es wird die Frucht davon essen. So ist es. Amen."}]},{"chapter":102,"verses":[{"verse":1,"text":"Am heutigen Tag versammelte sich auf Offenbarung hin ein allgemeiner Rat von vierundzwanzig Hohen Priestern im Haus von Joseph Smith Jr. und ging daran, den Hoherat der Kirche Christi zu organisieren; dieser soll aus zwölf Hohen Priestern bestehen und einem oder drei Präsidenten, wie der Fall es erfordern mag."},{"verse":2,"text":"Der Hoherat wurde durch Offenbarung zu dem Zweck bestellt, größere Schwierigkeiten zu bereinigen, zu denen es in der Kirche kommen kann, die aber weder von der Gemeinde noch vom Bischofsrat zur Zufriedenheit der Beteiligten bereinigt werden können."},{"verse":3,"text":"Joseph Smith Jr., Sidney Rigdon und Frederick G. Williams wurden mit den Stimmen des Rates als Präsidenten anerkannt; und Joseph Smith Sr., John Smith, Joseph Coe, John Johnson, Martin Harris, John S. Carter, Jared Carter, Oliver Cowdery, Samuel H. Smith, Orson Hyde, Sylvester Smith und Luke Johnson, alles Hohe Priester, wurden von dem Rat einstimmig als ständiger Rat der Kirche ausgewählt."},{"verse":4,"text":"Die vorstehend genannten Ratsmitglieder wurden dann gefragt, ob sie ihre Berufung annehmen und ob sie in diesem Amt gemäß dem Gesetz des Himmels handeln wollten, worauf alle antworteten, sie nähmen ihre Berufung an und würden ihr Amt gemäß der ihnen von Gott zuteilgewordenen Gnade ausüben."},{"verse":5,"text":"Die Anzahl derer, die den Rat bildeten, der bei der Berufung der vorstehend genannten Ratsmitglieder im Namen und für die Kirche abstimmte, war dreiundvierzig wie folgt: neun Hohe Priester, siebzehn Älteste, vier Priester und dreizehn Mitglieder."},{"verse":6,"text":"Beschluss: Der Hoherat ist nur dann ermächtigt zu handeln, wenn sieben von den vorstehend genannten Ratsmitgliedern oder deren ordnungsgemäß bestellten Nachfolgern anwesend sind."},{"verse":7,"text":"Diese sieben sollen ermächtigt sein, andere Hohe Priester zu bestimmen, die sie für würdig und fähig halten, anstelle abwesender Ratsmitglieder zu handeln."},{"verse":8,"text":"Beschluss: Jedes Mal, wenn ein Platz dadurch frei wird, dass eines der vorstehend genannten Ratsmitglieder stirbt, infolge von Übertretung des Amtes enthoben wird oder aus diesem Verwaltungsbereich der Kirche wegzieht, soll er auf Nominierung vonseiten des Präsidenten oder der Präsidenten hin wieder besetzt werden und durch die Stimme eines allgemeinen Rates von Hohen Priestern bestätigt werden, der zu diesem Zweck zusammentritt und im Namen der Kirche handelt."},{"verse":9,"text":"Der Präsident der Kirche, der auch der Präsident des Rates ist, wird durch Offenbarung bestimmt und durch die Stimme der Kirche in seinem Amt bestätigt."},{"verse":10,"text":"Und gemäß der Würde seines Amtes präsidiert er über den Rat der Kirche; und er hat das Recht, sich von zwei weiteren Präsidenten unterstützen zu lassen, die auf die gleiche Weise bestimmt werden, wie er selbst bestimmt wurde."},{"verse":11,"text":"Und falls einer oder beide von denen, die bestimmt wurden, ihm zu helfen, abwesend sind, ist er ermächtigt, ohne Helfer über den Rat zu präsidieren; und falls er selbst abwesend ist, sind die anderen Präsidenten ermächtigt, an seiner Stelle zu präsidieren, entweder gemeinsam oder einer von beiden."},{"verse":12,"text":"Wo immer ein Hoherat der Kirche Christi gemäß dem vorstehenden Muster ordnungsgemäß organisiert ist, soll es die Pflicht der zwölf Ratsmitglieder sein, nummerierte Lose zu ziehen und so festzulegen, wer von den zwölf zuerst sprechen soll, beginnend mit Nummer eins und so der Reihe nach bis Nummer zwölf."},{"verse":13,"text":"Wann immer dieser Rat zusammentritt, um einen Fall zu behandeln, sollen die zwölf Ratsmitglieder abwägen, ob es ein schwieriger Fall ist oder nicht; wenn nicht, so sollen nur zwei Ratsmitglieder, gemäß der Ordnung, die oben beschrieben ist, dazu sprechen."},{"verse":14,"text":"Wird er aber als schwierig betrachtet, so sollen vier bestimmt werden; falls besonders schwierig, sechs; in keinem Fall aber sollen mehr als sechs bestimmt werden zu sprechen."},{"verse":15,"text":"In allen Fällen hat der Angeklagte das Recht auf eine Hälfte des Rates, um Beleidigung und Ungerechtigkeit zu verhindern."},{"verse":16,"text":"Und die Ratsmitglieder, die bestimmt worden sind, vor dem Rat zu sprechen, sollen, nachdem das Beweismaterial geprüft worden ist, den Fall in seinem wahren Licht vor dem Rat vortragen; und ein jeder soll unparteiisch und gerecht sprechen."},{"verse":17,"text":"Die Ratsmitglieder, die die geraden Nummern gezogen haben, nämlich 2, 4, 6, 8, 10 und 12, sind diejenigen, die für den Angeklagten eintreten und Beleidigung und Ungerechtigkeit verhindern."},{"verse":18,"text":"In allen Fällen sollen der Ankläger und der Angeklagte das Recht haben, vor dem Rat für sich selbst zu sprechen, nachdem die Beweise gehört worden sind und die Ratsmitglieder, die bestimmt waren, zu dem Fall zu sprechen, ihre Ausführungen abgeschlossen haben."},{"verse":19,"text":"Nachdem die Beweise gehört worden sind, Ratsmitglieder, Ankläger und Angeklagte gesprochen haben, soll der Präsident gemäß dem Verständnis, das er von dem Fall hat, eine Entscheidung treffen und die zwölf Ratsmitglieder aufrufen, dieselbe durch ihre Stimme zu bestätigen."},{"verse":20,"text":"Sollten aber die übrigen Ratsmitglieder, die nicht gesprochen haben, oder irgendeiner von ihnen, nachdem sie die Beweise und Plädoyers unvoreingenommen angehört haben, in der Entscheidung des Präsidenten einen Irrtum entdecken, so können sie das kundtun, und der Fall soll neu verhandelt werden."},{"verse":21,"text":"Und wenn nach einer sorgfältigen neuen Verhandlung irgendwelches zusätzliches Licht in den Fall gebracht worden ist, soll die Entscheidung demgemäß geändert werden."},{"verse":22,"text":"Falls sich aber kein zusätzliches Licht ergeben hat, soll die erste Entscheidung bestehen bleiben, da die Mehrheit des Rates ermächtigt ist, sie festzulegen."},{"verse":23,"text":"Falls es sich um eine Schwierigkeit hinsichtlich der Lehre oder der Grundsätze handelt und nicht genügend Schriftliches vorliegt, dass dem Rat klarwird, wie der Fall zu beurteilen ist, kann der Präsident den Willen des Herrn durch Offenbarung erfragen und erlangen."},{"verse":24,"text":"Sind die Hohen Priester auswärts, so sind sie ermächtigt, auf die vorgenannte Weise einen Rat zu berufen und zu organisieren, um Schwierigkeiten zu bereinigen, sofern eine oder beide beteiligten Seiten darum ersuchen."},{"verse":25,"text":"Und der besagte Rat von Hohen Priestern ist ermächtigt, einen aus seiner eigenen Reihe zu bestimmen, der für die betreffende Zeit über solch einen Rat präsidiert."},{"verse":26,"text":"Es ist die Pflicht des besagten Rates, unverzüglich eine Abschrift der Verhandlung samt einer vollständigen Darlegung der Beweisgründe, die zu der gefällten Entscheidung geführt haben, an den Hoherat am Sitz der Ersten Präsidentschaft der Kirche zu senden."},{"verse":27,"text":"Sollten die Beteiligten oder einer von ihnen mit der Entscheidung des besagten Rates nicht zufrieden sein, können sie beim Hoherat am Sitz der Ersten Präsidentschaft der Kirche Berufung einlegen und eine neue Verhandlung haben; der Fall soll dann dort verhandelt werden, gemäß dem früher beschriebenen Muster, als ob noch keine solche Entscheidung getroffen worden sei."},{"verse":28,"text":"Dieser Rat von auswärtigen Hohen Priestern ist nur in den schwierigsten Fällen von Angelegenheiten der Kirche einzuberufen; und kein gewöhnlicher oder alltäglicher Fall rechtfertigt die Einberufung eines solchen Rates."},{"verse":29,"text":"Die reisenden oder ansässigen auswärtigen Hohen Priester sind ermächtigt festzustellen, ob es notwendig ist, einen solchen Rat einzuberufen oder nicht."},{"verse":30,"text":"Hinsichtlich ihrer Entscheidungen besteht ein Unterschied zwischen dem auswärtigen Hoherat, oder den auswärtigen reisenden Hohen Priestern, und dem reisenden Hoherat, der aus den zwölf Aposteln besteht."},{"verse":31,"text":"Gegen die Entscheidung des ersteren kann Berufung eingelegt werden, aber gegen die Entscheidung des letzteren nicht."},{"verse":32,"text":"Letztere kann nur von den Generalautoritäten der Kirche in Frage gestellt werden, falls es sich um Übertretung handelt."},{"verse":33,"text":"Entscheid: Der Präsident oder die Präsidenten am Sitz der Ersten Präsidentschaft der Kirche sind ermächtigt, nach Prüfung des Berufungsantrags und des einschlägigen Beweismaterials und der Aussagen zu entscheiden, ob in einem solchen Fall, wo Berufung eingelegt wird, ein Anspruch auf eine neue Verhandlung gerechtfertigt ist."},{"verse":34,"text":"Die zwölf Ratsmitglieder gingen dann daran, durch Lose oder Wahlzettel festzustellen, wer als Erster sprechen sollte, und das Ergebnis war wie folgt, nämlich: 1. Oliver Cowdery, 2. Joseph Coe, 3. Samuel H. Smith, 4. Luke Johnson, 5. John S. Carter, 6. Sylvester Smith, 7. John Johnson, 8. Orson Hyde, 9. Jared Carter, 10. Joseph Smith Sr., 11. John Smith, 12. Martin Harris.Nach dem Gebet wurde die Sitzung geschlossen."},{"verse":35,"text":"Oliver Cowdery,"},{"verse":36,"text":"Orson Hyde,"},{"verse":37,"text":"Schriftführer"}]},{"chapter":103,"verses":[{"verse":1,"text":"Wahrlich, ich sage euch, meine Freunde: Siehe, ich will euch eine Offenbarung und ein Gebot geben, damit ihr wisst, wie ihr in Erfüllung eurer Pflichten in Bezug auf die Errettung und Erlösung eurer Brüder handeln sollt, die im Land Zion zerstreut worden sind,"},{"verse":2,"text":"gejagt und geschlagen durch die Hand meiner Feinde, über die ich zu der von mir bestimmten Zeit meinen Grimm ohne Maß ausgießen werde."},{"verse":3,"text":"Denn ich habe sie bisher gewähren lassen, damit sie das Maß ihrer Übeltaten füllen, damit ihr Becher voll sei"},{"verse":4,"text":"und damit diejenigen, die sich nach meinem Namen nennen, eine kurze Zeit lang gezüchtigt werden, mit einer schweren und schmerzlichen Züchtigung, weil sie nicht gänzlich auf die Weisungen und Gebote gehört haben, die ich ihnen gegeben habe."},{"verse":5,"text":"Aber wahrlich, ich sage euch: Ich habe einen Beschluss beschlossen, den mein Volk verwirklichen wird, insoweit es von genau dieser Stunde an auf den Rat hört, den ich, der Herr, sein Gott, ihm geben werde."},{"verse":6,"text":"Siehe, es wird, denn ich habe es beschlossen, von genau dieser Stunde an anfangen, meine Feinde zu überwältigen."},{"verse":7,"text":"Und wenn es darauf bedacht ist, auf alle Worte zu hören, die ich, der Herr, sein Gott, zu ihm sagen werde, wird es niemals aufhören zu überwältigen, bis mir die Reiche der Welt unter die Füße getan sind und die Erde den Heiligen gegeben wird, dass sie sie für immer und immer besitzen."},{"verse":8,"text":"Insoweit es aber meine Gebote nicht hält und nicht darauf bedacht ist, auf alle meine Worte zu hören, werden die Reiche der Welt es überwältigen."},{"verse":9,"text":"Denn es ist hingestellt worden, der Welt ein Licht zu sein und den Menschen Erretter zu sein;"},{"verse":10,"text":"und insoweit es den Menschen kein Erretter ist, ist es wie Salz, das seine Würzkraft verloren hat und hinfort zu nichts mehr nütze ist, als hinausgeworfen und von den Menschen zertreten zu werden."},{"verse":11,"text":"Aber wahrlich, ich sage euch: Ich habe beschlossen, dass eure Brüder, die zerstreut worden sind, in die Länder ihrer Erbteile zurückkehren werden und die verwüsteten Stätten Zions aufbauen werden."},{"verse":12,"text":"Denn nach viel Drangsal, wie ich euch in einem früheren Gebot gesagt habe, kommt der Segen."},{"verse":13,"text":"Siehe, dies ist der Segen, den ich nach euren Drangsalen und den Drangsalen eurer Brüder verheißen habe: eure Erlösung und die Erlösung eurer Brüder, ja, ihre Wiederherstellung im Land Zion, um aufgerichtet und nie mehr niedergeworfen zu werden."},{"verse":14,"text":"Doch wenn sie ihre Erbteile verunreinigen, werden sie niedergeworfen werden; denn ich werde sie nicht verschonen, wenn sie ihre Erbteile verunreinigen."},{"verse":15,"text":"Siehe, ich sage euch: Die Erlösung Zions muss notwendigerweise durch Macht kommen;"},{"verse":16,"text":"darum werde ich meinem Volk einen Mann erwecken, der es führen wird, wie Mose die Kinder Israel geführt hat."},{"verse":17,"text":"Denn ihr seid die Kinder Israel und von den Nachkommen Abrahams, und ihr müsst notwendigerweise durch Macht und mit ausgestrecktem Arm aus der Knechtschaft geführt werden."},{"verse":18,"text":"Und wie am Anfang eure Väter geführt worden sind, so wird die Erlösung Zions sein."},{"verse":19,"text":"Darum lasst euer Herz nicht zagen, denn zu euch sage ich nicht, wie ich zu euren Vätern gesagt habe: Mein Engel wird vor euch hergehen, nicht aber meine Gegenwart."},{"verse":20,"text":"Sondern zu euch sage ich: Meine Engel werden vor euch hergehen, und auch meine Gegenwart, und mit der Zeit werdet ihr das gute Land besitzen."},{"verse":21,"text":"Wahrlich, wahrlich, ich sage euch: Mein Diener Joseph Smith Jr. ist der Mann, mit dem ich den Diener verglichen habe, zu dem der Herr des Weingartens in dem Gleichnis, das ich euch gegeben habe, gesprochen hat."},{"verse":22,"text":"Darum soll mein Diener Joseph Smith Jr. zu der Stärke meines Hauses, meinen Jünglingen und denen von mittlerem Alter, sprechen: Sammelt euch im Land Zion, auf dem Land, das ich mit Geld gekauft habe, das mir geweiht worden ist."},{"verse":23,"text":"Und lasst alle Gemeinden weise Männer mit ihren Geldern hinaufsenden und Land kaufen, ja, wie ich es ihnen geboten habe."},{"verse":24,"text":"Und insoweit meine Feinde gegen euch ziehen, um euch von meinem guten Land zu verjagen, das ich als das Land Zion geweiht habe, nämlich von euren eigenen Ländereien, nachdem ihr diese Zeugnisse gegen sie vor mich gebracht habt, sollt ihr sie verfluchen;"},{"verse":25,"text":"und wen auch immer ihr verflucht, den werde ich verfluchen, und ihr sollt mich an meinen Feinden rächen."},{"verse":26,"text":"Und meine Gegenwart wird mit euch sein, ja, wenn ihr mich an meinen Feinden rächt bis zur dritten und vierten Generation derer, die mich hassen."},{"verse":27,"text":"Keiner soll Angst davor haben, um meinetwillen sein Leben niederzulegen; denn wer auch immer sein Leben um meinetwillen niederlegt, der wird es wiederfinden."},{"verse":28,"text":"Und wer auch immer nicht willens ist, um meinetwillen sein Leben niederzulegen, der ist nicht mein Jünger."},{"verse":29,"text":"Es ist mein Wille, dass mein Diener Sidney Rigdon in den Zusammenkünften in den östlichen Ländern seine Stimme erhebe, um die Gemeinden vorzubereiten, dass sie die Gebote halten, die ich ihnen in Bezug auf die Wiederherstellung und Erlösung Zions gegeben habe."},{"verse":30,"text":"Es ist mein Wille, dass mein Diener Parley P. Pratt und mein Diener Lyman Wight nicht eher in das Land ihrer Brüder zurückkehren, als bis sie Abteilungen zusammengebracht haben, die in das Land Zion hinaufgehen, zu zehn oder zu zwanzig oder zu fünfzig oder zu hundert, bis sie an Zahl fünfhundert von der Stärke meines Hauses zusammengebracht haben."},{"verse":31,"text":"Siehe, das ist mein Wille; bittet, und ihr werdet empfangen; aber die Menschen tun nicht immer meinen Willen."},{"verse":32,"text":"Darum, wenn ihr keine fünfhundert zusammenbringt, trachtet eifrig danach, vielleicht dreihundert zusammenzubringen."},{"verse":33,"text":"Und wenn ihr keine dreihundert zusammenbringt, trachtet eifrig danach, vielleicht einhundert zusammenzubringen."},{"verse":34,"text":"Aber wahrlich, ich sage euch: Das Gebot gebe ich euch, nicht eher in das Land Zion hinaufzugehen, als bis ihr einhundert von der Stärke meines Hauses zusammengebracht habt, dass sie mit euch in das Land Zion hinaufgehen."},{"verse":35,"text":"Darum, wie ich euch gesagt habe: Bittet, und ihr werdet empfangen; betet ernsthaft darum, dass vielleicht mein Diener Joseph Smith Jr. mit euch gehe und inmitten meines Volkes präsidiere und mein Reich in dem geweihten Land organisiere und die Kinder Zion auf den Gesetzen und Geboten aufrichte, die euch gegeben worden sind und noch gegeben werden sollen."},{"verse":36,"text":"Aller Sieg und alle Herrlichkeit kommt für euch durch euren Eifer, eure Treue und eure Gebete des Glaubens zustande."},{"verse":37,"text":"Lasst meinen Diener Parley P. Pratt mit meinem Diener Joseph Smith Jr. reisen."},{"verse":38,"text":"Lasst meinen Diener Lyman Wight mit meinem Diener Sidney Rigdon reisen."},{"verse":39,"text":"Lasst meinen Diener Hyrum Smith mit meinem Diener Frederick G. Williams reisen."},{"verse":40,"text":"Lasst meinen Diener Orson Hyde mit meinem Diener Orson Pratt reisen, wohin auch immer mein Diener Joseph Smith Jr. ihnen allen raten wird, damit diese Gebote erfüllt werden, die ich euch gegeben habe; und lasst das Übrige in meinen Händen. So ist es. Amen."}]},{"chapter":104,"verses":[{"verse":1,"text":"Wahrlich, ich sage euch, meine Freunde: Ich gebe euch Rat und ein Gebot in Bezug auf alles Eigentum, was der Ordnung gehört, die zu organisieren und zu gründen ich gebot, als eine vereinigte Ordnung und eine immerwährende Ordnung zum Nutzen meiner Kirche und zur Errettung der Menschen, bis ich komme –"},{"verse":2,"text":"mit unwandelbarer und unabänderlicher Verheißung, nämlich: Insoweit diejenigen, denen ich das Gebot gegeben habe, treu seien, würden sie mit einer Vielfalt von Segnungen gesegnet werden,"},{"verse":3,"text":"aber insoweit sie nicht treu seien, würden sie einem Fluch nahe sein."},{"verse":4,"text":"Darum, insoweit einige meiner Diener das Gebot nicht gehalten haben, sondern den Bund durch Habgier und mit geheuchelten Worten gebrochen haben, habe ich sie mit einem sehr schweren und schmerzlichen Fluch verflucht."},{"verse":5,"text":"Denn ich, der Herr, habe in meinem Herzen beschlossen: Insoweit jemand, der der Ordnung angehört, als Übertreter befunden wird oder, mit anderen Worten, den Bund bricht, womit ihr verpflichtet seid, so wird er in seinem Leben verflucht sein und wird niedergetreten werden, von wem ich will,"},{"verse":6,"text":"denn ich, der Herr, werde mich in all diesem nicht verspotten lassen –"},{"verse":7,"text":"und dies alles, damit nicht die Unschuldigen unter euch mit den Ungerechten schuldig gesprochen werden und damit nicht die Schuldigen unter euch entrinnen; denn ich, der Herr, habe euch eine Krone der Herrlichkeit zu meiner rechten Hand verheißen."},{"verse":8,"text":"Darum, insoweit ihr als Übertreter befunden werdet, könnt ihr meinem Grimm in eurem Leben nicht entrinnen."},{"verse":9,"text":"Insoweit ihr wegen Übertretung ausgeschlossen werdet, könnt ihr den Schlägen des Satans bis zum Tag der Erlösung nicht entrinnen."},{"verse":10,"text":"Und nun gebe ich euch von genau dieser Stunde an Macht, dass ein jeder von euch, von der Ordnung, der als Übertreter befunden wird und von dem Bösen nicht umkehrt, dass ihr ihn den Schlägen des Satans überantwortet; und er wird keine Macht haben, Böses über euch zu bringen."},{"verse":11,"text":"Es ist nach meiner Weisheit; darum gebe ich euch das Gebot, euch zu organisieren und einem jeden seine Treuhandschaft zu bestimmen,"},{"verse":12,"text":"damit mir ein jeder über die Treuhandschaft, die ihm bestimmt worden ist, Rechenschaft geben kann."},{"verse":13,"text":"Denn es ist ratsam, dass ich, der Herr, einen jeden rechenschaftspflichtig mache, als Treuhänder über irdische Segnungen, die ich für meine Geschöpfe gemacht und bereitet habe."},{"verse":14,"text":"Ich, der Herr, habe die Himmel ausgespannt und die Erde gebaut, ja, meiner Hände Werk; und alles darin ist mein."},{"verse":15,"text":"Und es ist meine Absicht, für meine Heiligen zu sorgen, denn alles ist mein."},{"verse":16,"text":"Aber es muss notwendigerweise auf meine eigene Weise geschehen; und siehe, dies ist die Weise, die ich, der Herr, beschlossen habe, um für meine Heiligen zu sorgen: Die Armen sollen erhöht werden, indem die Reichen erniedrigt werden."},{"verse":17,"text":"Denn die Erde ist voll, und es ist genug vorhanden, ja, dass noch übrigbleibt; ja, ich habe alles bereitet und den Menschenkindern gewährt, für sich selbst zu handeln."},{"verse":18,"text":"Darum, wenn jemand von dem Überfluss nimmt, den ich gemacht habe, und von seinem Teil nicht, gemäß dem Gesetz meines Evangeliums, den Armen und den Bedürftigen abgibt, so wird er zusammen mit den Schlechten in der Hölle seine Augen emporheben in seiner Qual."},{"verse":19,"text":"Und nun, wahrlich, ich sage euch in Bezug auf das Eigentum der Ordnung:"},{"verse":20,"text":"Meinem Diener Sidney Rigdon sollen die Stätte, wo er gegenwärtig wohnt, sowie das Grundstück der Gerberei als seine Treuhandschaft bestimmt werden, zu seinem Unterhalt, solange er, so wie ich es will, in meinem Weingarten arbeitet, wenn ich es ihm gebiete."},{"verse":21,"text":"Und alles soll gemäß dem Rat der Ordnung geschehen und der vereinigten Zustimmung oder Stimme der Ordnung derer, die im Land Kirtland wohnen."},{"verse":22,"text":"Und diese Treuhandschaft und Segnung übertrage ich, der Herr, meinem Diener Sidney Rigdon als Segnung auf ihn und seine Nachkommen nach ihm,"},{"verse":23,"text":"und ich werde Segnungen auf ihm vervielfachen, insoweit er vor mir demütig ist."},{"verse":24,"text":"Und weiter: Meinem Diener Martin Harris soll als seine Treuhandschaft das Stück Land bestimmt werden, das mein Diener John Johnson im Austausch für sein früheres Erbteil erhalten hat, für ihn und seine Nachkommen nach ihm;"},{"verse":25,"text":"und insoweit er treu ist, werde ich Segnungen auf ihm und seinen Nachkommen nach ihm vervielfachen."},{"verse":26,"text":"Und mein Diener Martin Harris soll sein Geld für die Verkündigung meiner Worte hingeben, wie mein Diener Joseph Smith Jr. es anordnen wird."},{"verse":27,"text":"Und weiter: Mein Diener Frederick G. Williams soll seine gegenwärtige Wohnstätte haben."},{"verse":28,"text":"Und mein Diener Oliver Cowdery soll das Grundstück haben, das abgetrennt ist und an das Haus grenzt, das als Druckerei dienen soll, also das Grundstück Nummer eins, und ebenfalls das Grundstück, worauf sein Vater wohnt."},{"verse":29,"text":"Und meine Diener Frederick G. Williams und Oliver Cowdery sollen die Druckerei haben samt allem, was dazugehört."},{"verse":30,"text":"Und das soll ihre Treuhandschaft sein, die ihnen bestimmt werden soll."},{"verse":31,"text":"Und insoweit sie treu sind, siehe, werde ich sie segnen und Segnungen auf ihnen vervielfachen."},{"verse":32,"text":"Und dies ist der Anfang der Treuhandschaft, die ich ihnen bestimmt habe, für sie und ihre Nachkommen nach ihnen."},{"verse":33,"text":"Und insoweit sie treu sind, werde ich Segnungen auf ihnen und ihren Nachkommen nach ihnen vervielfachen, ja, eine Vielfalt von Segnungen."},{"verse":34,"text":"Und weiter: Mein Diener John Johnson soll das Haus, worin er wohnt, und das Erbteil haben, alles außer dem Grund, der dem Bau meiner Häuser vorbehalten ist und der zu jenem Erbteil gehört, und jenen Grundstücken, die für meinen Diener Oliver Cowdery genannt worden sind."},{"verse":35,"text":"Und insoweit er treu ist, werde ich Segnungen auf ihm vervielfachen."},{"verse":36,"text":"Und es ist mein Wille, dass er die Grundstücke verkaufe, die für den Aufbau der Stadt meiner Heiligen abgesteckt sind, insoweit es ihm durch die Stimme des Geistes kundgetan werden wird und gemäß dem Rat der Ordnung und durch die Stimme der Ordnung."},{"verse":37,"text":"Und dies ist der Anfang der Treuhandschaft, die ich ihm bestimmt habe, als Segnung für ihn und seine Nachkommen nach ihm."},{"verse":38,"text":"Und insoweit er treu ist, werde ich eine Vielfalt von Segnungen auf ihm vervielfachen."},{"verse":39,"text":"Und weiter: Meinem Diener Newel K. Whitney sollen die Häuser und das Grundstück bestimmt werden, wo er gegenwärtig wohnt, dazu das Grundstück und Gebäude, wo sich das Warenhaus befindet, und ebenfalls das Grundstück, das an der Ecke südlich des Warenhauses liegt, und auch das Grundstück, worauf sich das Aschenhaus befindet."},{"verse":40,"text":"Und dies alles habe ich für meinen Diener Newel K. Whitney als seine Treuhandschaft bestimmt, als Segnung auf ihn und seine Nachkommen nach ihm, zum Nutzen des Warenhauses meiner Ordnung, die ich für meinen Pfahl im Land Kirtland eingerichtet habe."},{"verse":41,"text":"Ja, wahrlich, das ist die Treuhandschaft, die ich für meinen Diener N. K. Whitney bestimmt habe, nämlich dieses gesamte Warenhaus, für ihn und seinen Bevollmächtigten und seine Nachkommen nach ihm."},{"verse":42,"text":"Und insoweit er im Halten meiner Gebote, die ich ihm gegeben habe, treu ist, werde ich Segnungen auf ihm und seinen Nachkommen nach ihm vervielfachen, ja, eine Vielfalt von Segnungen."},{"verse":43,"text":"Und weiter: Meinem Diener Joseph Smith Jr. soll das Grundstück bestimmt werden, das für den Bau meines Hauses abgesteckt ist, das vierzig Ruten lang und zwölf breit ist, dazu auch das Erbteil, worauf gegenwärtig sein Vater wohnt;"},{"verse":44,"text":"und dies ist der Anfang der Treuhandschaft, die ich ihm bestimmt habe, als Segnung auf ihn und auf seinen Vater."},{"verse":45,"text":"Denn siehe, ich habe für seinen Vater ein Erbteil zu seinem Unterhalt zurückbehalten; darum soll er dem Haus meines Dieners Joseph Smith Jr. zugerechnet werden."},{"verse":46,"text":"Und ich werde Segnungen auf dem Haus meines Dieners Joseph Smith Jr. vervielfachen, insoweit er treu ist, ja, eine Vielfalt von Segnungen."},{"verse":47,"text":"Und nun gebe ich euch ein Gebot in Bezug auf Zion, dass ihr nicht länger als vereinigte Ordnung an eure Brüder aus Zion gebunden sein sollt, außer nur auf die folgende Weise:"},{"verse":48,"text":"Nachdem ihr euch organisiert habt, sollt ihr die Vereinigte Ordnung des Pfahles Zion der Stadt Kirtland genannt werden. Und eure Brüder, nachdem sie sich organisiert haben, sollen die Vereinigte Ordnung der Stadt Zion genannt werden."},{"verse":49,"text":"Und sie sollen sich unter ihren eigenen Namen und in ihrem eigenen Namen organisieren; und sie sollen ihre Geschäfte in ihrem eigenen Namen und unter ihren eigenen Namen betreiben;"},{"verse":50,"text":"und ihr sollt eure Geschäfte in eurem eigenen Namen und unter euren eigenen Namen betreiben."},{"verse":51,"text":"Und das habe ich geboten, dass es zu eurer Errettung und auch zu ihrer Errettung getan werde, als Folge dessen, dass sie verjagt worden sind, und dessen, was kommen wird."},{"verse":52,"text":"Da die Bündnisse durch Übertretung gebrochen worden sind, durch Habgier und geheuchelte Worte –"},{"verse":53,"text":"darum seid ihr als vereinigte Ordnung mit euren Brüdern aufgelöst, sodass ihr nur bis zu dieser Stunde mit ihnen verbunden seid und nur auf die Weise, wie ich gesagt habe, nämlich durch Darlehen, wie sich diese Ordnung im Rat einigt, wie es eure Umstände erlauben und die Stimme des Rates es anordnet."},{"verse":54,"text":"Und weiter gebe ich euch ein Gebot in Bezug auf eure Treuhandschaft, die ich euch bestimmt habe."},{"verse":55,"text":"Siehe, all dieses Eigentum ist mein, denn sonst ist euer Glaube unnütz, und ihr seid als Heuchler befunden, und die Bündnisse, die ihr mir gemacht habt, sind gebrochen;"},{"verse":56,"text":"und wenn nun das Eigentum mein ist, so seid ihr Treuhänder; andernfalls seid ihr keine Treuhänder."},{"verse":57,"text":"Aber wahrlich, ich sage euch: Ich habe euch zu Treuhändern über mein Haus bestimmt, ja, tatsächlich zu Treuhändern."},{"verse":58,"text":"Und zu diesem Zweck habe ich euch geboten, euch zu organisieren, nämlich meine Worte zu drucken, die Fülle meiner Schriften, die Offenbarungen, die ich euch gegeben habe und die ich euch später noch von Zeit zu Zeit geben werde –"},{"verse":59,"text":"zu dem Zweck, dass meine Kirche und mein Reich auf Erden aufgebaut und mein Volk für die Zeit bereitgemacht werde, da ich bei ihm wohnen werde; denn das steht nahe bevor."},{"verse":60,"text":"Und ihr sollt euch eine Stätte als Schatzkammer bereitmachen und sie meinem Namen weihen."},{"verse":61,"text":"Und ihr sollt einen unter euch bestimmen, dass er die Schatzkammer verwalte, und er soll zu dieser Segnung ordiniert werden."},{"verse":62,"text":"Und auf der Schatzkammer soll ein Siegel sein, und alles Heilige soll an die Schatzkammer abgeführt werden; und niemand unter euch soll sie oder irgendeinen Teil davon sein Eigen nennen, denn sie soll euch allen gemeinsam gehören."},{"verse":63,"text":"Und ich übergebe sie euch von genau dieser Stunde an; und nun seht zu, dass ihr darangeht, die Treuhandschaft zu nutzen, die ich euch bestimmt habe, ausgenommen das Heilige, zu dem Zweck, das Heilige zu drucken, wie ich es gesagt habe."},{"verse":64,"text":"Und die Gewinne aus dem Heiligen sollen in die Schatzkammer getan werden, und ein Siegel soll darauf sein; und sie sollen von niemandem verwendet oder aus der Schatzkammer entnommen werden, und auch das Siegel, das darauf gesetzt werden soll, soll nicht gelöst werden, außer durch die Stimme der Ordnung oder durch Gebot."},{"verse":65,"text":"Und so sollt ihr die Gewinne aus dem Heiligen in der Schatzkammer zu heiligen und geheiligten Zwecken bewahren."},{"verse":66,"text":"Und dies soll die heilige Schatzkammer des Herrn genannt werden; und ein Siegel soll darauf angebracht bleiben, damit sie heilig und dem Herrn geweiht sei."},{"verse":67,"text":"Und weiter: Es soll eine weitere Schatzkammer bereitgemacht und ein Schatzmeister bestimmt werden, dass er die Schatzkammer verwalte, und ein Siegel soll darauf gesetzt werden;"},{"verse":68,"text":"und alle Gelder, die ihr in eurer Treuhandschaft empfangt, indem ihr das Eigentum, das ich euch bestimmt habe, verbessert, durch Häuser oder durch Ländereien oder durch Viehbestand oder durch alles andere, ausgenommen die heiligen und geheiligten Schriften, die ich mir zu heiligen und geheiligten Zwecken vorbehalte, sollen in die Schatzkammer eingebracht werden, sobald ihr Gelder empfangt, zu hundert oder zu fünfzig oder zu zwanzig oder zu zehn oder zu fünf."},{"verse":69,"text":"Oder, mit anderen Worten, wenn einer unter euch fünf Dollar erhält, soll er sie in die Schatzkammer einbringen; oder wenn er zehn oder zwanzig oder fünfzig oder hundert erhält, soll er das Gleiche tun;"},{"verse":70,"text":"und keiner von euch soll sagen, es sei sein Eigen; denn es soll nicht sein Eigen heißen, auch kein Teil davon."},{"verse":71,"text":"Und es soll kein Teil davon verwendet oder aus der Schatzkammer entnommen werden, außer durch die Stimme und allgemeine Zustimmung der Ordnung."},{"verse":72,"text":"Und dies soll die Stimme und allgemeine Zustimmung der Ordnung sein: Jeder von euch mag zum Schatzmeister sagen: Ich habe dies nötig, damit mir in meiner Treuhandschaft geholfen sei –"},{"verse":73,"text":"ob es fünf Dollar sind oder ob es zehn Dollar sind oder zwanzig oder fünfzig oder hundert, der Schatzmeister soll ihm die Summe geben, die er verlangt, damit ihm in seiner Treuhandschaft geholfen sei –"},{"verse":74,"text":"solange er nicht als Übertreter befunden wird und es sich vor dem Rat der Ordnung klar kundtut, dass er ein ungetreuer und ein unweiser Treuhänder ist."},{"verse":75,"text":"Solange er aber volle Gemeinschaft genießt und in seiner Treuhandschaft treu und weise ist, soll dies dem Schatzmeister ein Zeichen sein, dass der Schatzmeister ihm nichts verweigern soll."},{"verse":76,"text":"Aber im Fall von Übertretung soll der Schatzmeister dem Rat und der Stimme der Ordnung unterworfen sein."},{"verse":77,"text":"Und falls der Schatzmeister als ungetreuer und als unweiser Treuhänder befunden wird, soll er dem Rat und der Stimme der Ordnung unterworfen sein und soll von seinem Platz entfernt werden, und an seiner Stelle soll ein anderer bestimmt werden."},{"verse":78,"text":"Und weiter, wahrlich, ich sage euch in Bezug auf eure Schulden: Siehe, es ist mein Wille, dass ihr all eure Schulden bezahlt."},{"verse":79,"text":"Und es ist mein Wille, dass ihr euch vor mir demütigt und diese Segnung durch euren Eifer und eure Demut und das Gebet des Glaubens erlangt."},{"verse":80,"text":"Und insoweit ihr eifrig und demütig seid und das Gebet des Glaubens ausübt, siehe, werde ich denjenigen das Herz erweichen, bei denen ihr Schulden habt, bis ich euch die Mittel sende, wodurch ihr befreit werdet."},{"verse":81,"text":"Darum schreibt schnell nach New York, und schreibt gemäß dem, was durch meinen Geist angesagt wird; und ich werde denjenigen das Herz erweichen, bei denen ihr Schulden habt, sodass es ihnen aus dem Sinn genommen wird, euch in Bedrängnis zu bringen."},{"verse":82,"text":"Und insoweit ihr demütig und glaubenstreu seid und meinen Namen anruft, siehe, werde ich euch den Sieg schenken."},{"verse":83,"text":"Ich gebe euch die Verheißung, dass ihr dieses eine Mal aus eurer Knechtschaft befreit werden sollt."},{"verse":84,"text":"Insoweit ihr eine Gelegenheit erhaltet, Geld zu hundert oder tausend zu leihen, ja, so viel zu leihen, dass ihr euch aus der Knechtschaft befreien könnt, so habt ihr das Recht dazu."},{"verse":85,"text":"Und verpfändet das Eigentum, das ich euch in die Hand gegeben habe, dieses eine Mal, indem ihr eure Namen dazu hergebt, mit allgemeiner Zustimmung oder auf andere Weise, wie es euch gut scheint."},{"verse":86,"text":"Ich gebe euch dieses Recht dieses eine Mal; und siehe, wenn ihr darangeht, das, was ich euch vorgelegt habe, gemäß meinen Geboten zu tun, so ist dies alles mein, und ihr seid meine Treuhänder, und der Meister wird nicht zulassen, dass in sein Haus eingebrochen wird. So ist es. Amen."}]},{"chapter":105,"verses":[{"verse":1,"text":"Wahrlich, ich sage euch, die ihr euch versammelt habt, um meinen Willen in Bezug auf die Erlösung meines bedrängten Volkes zu erfahren:"},{"verse":2,"text":"Siehe, ich sage euch: Ohne die Übertretungen meines Volkes, und ich spreche von der Kirche und nicht von Einzelnen, könnte es schon jetzt erlöst sein."},{"verse":3,"text":"Aber siehe, es hat nicht gelernt, dem zu gehorchen, was ich von seiner Hand gefordert habe, sondern ist voll von allerart Bösem und teilt nicht von seiner Habe, wie es Heiligen geziemt, mit den Armen und Bedrängten unter ihm"},{"verse":4,"text":"und ist nicht einig, gemäß jener Einigkeit, die das Gesetz des celestialen Reiches erfordert,"},{"verse":5,"text":"und Zion kann nicht anders aufgebaut werden als nur nach den Grundsätzen des Gesetzes des celestialen Reiches; andernfalls kann ich es nicht zu mir nehmen."},{"verse":6,"text":"Und mein Volk muss notwendigerweise gezüchtigt werden, bis es Gehorsam lernt, wenn es sein muss, durch das, was es leidet."},{"verse":7,"text":"Ich rede nicht von denen, die bestimmt sind, mein Volk zu führen, die die ersten Ältesten meiner Kirche sind, denn sie stehen nicht alle unter diesem Schuldspruch;"},{"verse":8,"text":"sondern ich rede von meinen auswärtigen Gemeinden – es gibt viele, die sagen: Wo ist ihr Gott? Siehe, er wird sie in der Zeit der Beunruhigung befreien, sonst gehen wir nicht nach Zion hinauf und behalten unser Geld."},{"verse":9,"text":"Darum ist es mir im Hinblick auf die Übertretungen meines Volkes ratsam, dass meine Ältesten eine kurze Zeit lang auf die Erlösung Zions warten –"},{"verse":10,"text":"damit sie selbst sich bereitmachen können und damit mein Volk vollkommener belehrt werde und Erfahrung sammle und seine Pflichten sowie das, was ich von seiner Hand fordere, vollkommener erkenne."},{"verse":11,"text":"Und dies kann erst zustande gebracht werden, wenn meine Ältesten mit Macht aus der Höhe ausgerüstet sind."},{"verse":12,"text":"Denn siehe, ich habe ein großes Endowment und einen großen Segen bereitet, der über sie ausgegossen werden soll, insoweit sie treu sind und weiterhin vor mir demütig bleiben."},{"verse":13,"text":"Darum ist es mir ratsam, dass meine Ältesten eine kurze Zeit lang auf die Erlösung Zions warten."},{"verse":14,"text":"Denn siehe, ich fordere nicht von ihrer Hand, dass sie die Schlachten Zions schlagen; denn, wie ich es in einem früheren Gebot gesagt habe, so will ich es auch erfüllen: Ich werde eure Schlachten schlagen."},{"verse":15,"text":"Siehe, den Zerstörer habe ich ausgesandt, meine Feinde zu zerstören und zu verwüsten; und in nicht vielen Jahren von nun an werden keine mehr übrig sein, mein Erbe zu verunreinigen und meinen Namen in dem Land zu lästern, das ich für die Sammlung meiner Heiligen geweiht habe."},{"verse":16,"text":"Siehe, ich habe meinem Diener Joseph Smith Jr. geboten, der Stärke meines Hauses, nämlich meinen Kriegern, meinen Jünglingen und denen von mittlerem Alter, zu sagen, dass sie sich zur Erlösung meines Volkes versammeln und die Türme meiner Feinde umstürzen und ihre Wächter zerstreuen sollen;"},{"verse":17,"text":"aber die Stärke meines Hauses hat nicht auf meine Worte gehört."},{"verse":18,"text":"Aber insoweit es welche gibt, die auf meine Worte gehört haben, habe ich einen Segen und ein Endowment für sie bereit, wenn sie weiterhin treu bleiben."},{"verse":19,"text":"Ich habe ihre Gebete vernommen und werde ihr Opfer annehmen, und es ist mir ratsam, dass sie bis hierher gebracht werden, damit ihr Glaube geprüft werden kann."},{"verse":20,"text":"Und nun, wahrlich, ich sage euch: Das Gebot gebe ich euch, dass alle, die hier heraufgekommen sind und im Gebiet ringsum bleiben können, hier bleiben sollen;"},{"verse":21,"text":"und diejenigen, die nicht bleiben können, die ihre Familie im Osten haben, sollen eine kurze Zeit lang verweilen, wie es mein Diener Joseph für sie bestimmen wird;"},{"verse":22,"text":"denn ich werde ihn diesbezüglich beraten, und alles, was auch immer er für sie bestimmt, wird sich erfüllen."},{"verse":23,"text":"Und all mein Volk, was in den Gebieten ringsum wohnt, soll sehr treu und gebetsvoll und demütig vor mir sein und nichts von dem offenbaren, was ich ihm offenbart habe, bis es nach meiner Weisheit offenbart werden soll."},{"verse":24,"text":"Redet nicht von Strafgerichten, und prahlt auch nicht mit Glauben und mächtigen Werken, sondern sammelt euch vorsichtig, so viele in einem Gebiet wie möglich und wie es mit den Gefühlen der Menschen vereinbar ist;"},{"verse":25,"text":"und siehe, ich werde es geben, dass ihr in ihren Augen Gunst und Gnade findet, damit ihr in Frieden und Sicherheit ruht, während ihr zu den Menschen sagt: Übt Rechtsprechung und Gerechtigkeit für uns gemäß dem Gesetz, und macht das uns angetane Unrecht wieder gut."},{"verse":26,"text":"Nun siehe, ich sage euch, meine Freunde: Auf diese Weise könnt ihr in den Augen der Menschen Gunst erlangen, bis das Heer Israels sehr groß sein wird."},{"verse":27,"text":"Und ich werde den Menschen von Zeit zu Zeit das Herz erweichen, wie ich es beim Herz des Pharaos getan habe, bis mein Diener Joseph Smith Jr. und meine Ältesten, die ich bestimmt habe, Zeit haben werden, die Stärke meines Hauses zu sammeln"},{"verse":28,"text":"und weise Männer aussenden zu lassen, die erfüllen sollen, was ich geboten habe, in Bezug auf den Ankauf allen Landes, was im Kreis Jackson und in den angrenzenden Kreisen ringsum gekauft werden kann."},{"verse":29,"text":"Denn es ist mein Wille, dass dieses Land gekauft werde; und nachdem es gekauft ist, sollen meine Heiligen es gemäß den von mir gegebenen Gesetzen der Weihung besitzen."},{"verse":30,"text":"Und nachdem dieses Land gekauft ist, werde ich die Heere Israels als schuldlos ansehen, wenn sie ihr eigenes Land in Besitz nehmen, das sie zuvor mit ihrem Geld gekauft haben, und die Türme meiner Feinde umstürzen, die darauf stehen mögen, und ihre Wächter zerstreuen und mich an meinen Feinden rächen bis zur dritten und vierten Generation derer, die mich hassen."},{"verse":31,"text":"Lasst aber zuerst mein Heer sehr groß werden, und lasst es sich vor mir heiligen, damit es schön werde wie die Sonne und klar wie der Mond und damit seine Banner allen Nationen ein Schrecken seien,"},{"verse":32,"text":"damit die Reiche dieser Welt dazu gedrängt werden anzuerkennen, dass das Reich Zion tatsächlich das Reich unseres Gottes und seines Christus ist; darum wollen wir uns den Gesetzen Zions unterwerfen."},{"verse":33,"text":"Wahrlich, ich sage euch: Es ist mir ratsam, dass die ersten Ältesten meiner Kirche ihr Endowment aus der Höhe in meinem Haus empfangen, das meinem Namen im Land Kirtland gebaut werden soll, wie ich es geboten habe."},{"verse":34,"text":"Und die Gebote, die ich in Bezug auf Zion und sein Gesetz gegeben habe, sollen nach seiner Erlösung ausgeführt und erfüllt werden."},{"verse":35,"text":"Es hat einen Tag des Berufens gegeben, aber die Zeit für einen Tag des Erwählens ist gekommen; und es sollen diejenigen erwählt werden, die würdig sind."},{"verse":36,"text":"Und es werden meinem Diener durch die Stimme des Geistes diejenigen kundgetan werden, die erwählt worden sind; und sie werden geheiligt werden;"},{"verse":37,"text":"und insoweit sie den Rat befolgen, den sie empfangen, werden sie nach vielen Tagen die Macht haben, alles zu vollbringen, was Zion betrifft."},{"verse":38,"text":"Und abermals sage ich euch: Erbittet Frieden nicht nur bei denen, die euch geschlagen haben, sondern bei allen Menschen,"},{"verse":39,"text":"und hebt ein Friedenspanier empor, und lasst eine Friedenskundmachung an die Enden der Erde ergehen;"},{"verse":40,"text":"und macht denen, die euch geschlagen haben, Friedensvorschläge gemäß der Stimme des Geistes, die in euch ist, dann wird alles zu eurem Guten zusammenwirken."},{"verse":41,"text":"Darum seid treu; und siehe, ja siehe, ich bin bei euch, ja, bis ans Ende. So ist es. Amen."}]},{"chapter":106,"verses":[{"verse":1,"text":"Es ist mein Wille, dass mein Diener Warren A. Cowdery zum präsidierenden Hohen Priester in meiner Kirche im Land Freedom und den Gebieten ringsum bestimmt und als solcher ordiniert werde;"},{"verse":2,"text":"er soll mein immerwährendes Evangelium predigen und seine Stimme erheben und das Volk warnen, nicht nur in seinem eigenen Ort, sondern in den angrenzenden Landkreisen,"},{"verse":3,"text":"und soll dieser hohen und heiligen Berufung, die ich ihm hiermit gebe, seine ganze Zeit widmen und eifrig nach dem Himmelreich und dessen Rechtschaffenheit trachten, und alles Notwendige wird dem hinzugefügt werden; denn der Arbeiter ist seines Lohnes wert."},{"verse":4,"text":"Und weiter, wahrlich, ich sage euch: Das Kommen des Herrn naht heran, und es kommt über die Welt wie ein Dieb in der Nacht –"},{"verse":5,"text":"darum gürtet euch die Lenden, damit ihr die Kinder des Lichts seiet und jener Tag nicht über euch komme wie ein Dieb."},{"verse":6,"text":"Und weiter, wahrlich, ich sage euch: Freude war im Himmel, als mein Diener Warren sich meinem Zepter gebeugt und sich von den Machenschaften der Menschen getrennt hat;"},{"verse":7,"text":"darum ist mein Diener Warren gesegnet, denn ich werde barmherzig zu ihm sein; und ungeachtet der Eingebildetheit seines Herzens werde ich ihn emporheben, insoweit er sich vor mir demütigt."},{"verse":8,"text":"Und ich werde ihm Gnade und Zuversicht geben, womit er bestehen kann; und wenn er weiterhin für die Kirche ein treuer Zeuge und ein Licht ist, habe ich in den Wohnungen meines Vaters eine Krone für ihn bereitet. So ist es. Amen."}]},{"chapter":107,"verses":[{"verse":1,"text":"In der Kirche gibt es zwei Priestertümer, nämlich das Melchisedekische und das Aaronische, welches das Levitische Priestertum einschließt."},{"verse":2,"text":"Das erste wird deshalb das Melchisedekische Priestertum genannt, weil Melchisedek ein so großer Hoher Priester war."},{"verse":3,"text":"Vor seinen Tagen hieß es das Heilige Priestertum nach der Ordnung des Sohnes Gottes."},{"verse":4,"text":"Aber aus Achtung oder Ehrfurcht vor dem Namen des allerhöchsten Wesens und um die allzu häufige Wiederholung seines Namens zu vermeiden, nannten sie, die Kirche, in alten Tagen dieses Priestertum nach Melchisedek oder das Melchisedekische Priestertum."},{"verse":5,"text":"Alle anderen Vollmachten oder Ämter in der Kirche sind Beigaben zu diesem Priestertum."},{"verse":6,"text":"Aber es gibt zwei Abteilungen oder Hauptteile – einmal das Melchisedekische Priestertum, zum anderen das Aaronische oder Levitische Priestertum."},{"verse":7,"text":"Das Amt des Ältesten fällt unter das Priestertum Melchisedeks."},{"verse":8,"text":"Das Melchisedekische Priestertum hat das Recht auf die Präsidentschaft inne und hat Macht und Vollmacht über alle Ämter in der Kirche in allen Zeitaltern der Welt, um in geistigen Belangen zu amtieren."},{"verse":9,"text":"Die Präsidentschaft des Hohen Priestertums nach der Ordnung Melchisedeks hat das Recht, in allen Ämtern in der Kirche zu amtieren."},{"verse":10,"text":"Hohe Priester nach der Ordnung des Melchisedekischen Priestertums haben das Recht, unter der Leitung der Präsidentschaft in ihrem eigenen Bereich in geistigen Belangen zu amtieren und auch im Amt eines Ältesten, Priesters (der Levitischen Ordnung), Lehrers, Diakons und Mitglieds."},{"verse":11,"text":"Ein Ältester hat das Recht, an seiner Stelle zu amtieren, wenn der Hohe Priester nicht anwesend ist."},{"verse":12,"text":"Hohe Priester und Älteste sollen in geistigen Belangen amtieren, im Einklang mit den Bündnissen und Geboten der Kirche; und sie haben das Recht, in all diesen Ämtern der Kirche zu amtieren, wenn keine höheren Autoritäten anwesend sind."},{"verse":13,"text":"Das zweite Priestertum wird das Priestertum Aarons genannt, weil es Aaron und seinen Nachkommen in all ihren Generationen übertragen wurde."},{"verse":14,"text":"Es wird deshalb das geringere Priestertum genannt, weil es eine Beigabe zum größeren oder Melchisedekischen Priestertum ist und die Macht hat, äußerliche Verordnungen zu vollziehen."},{"verse":15,"text":"Die Bischofschaft ist die Präsidentschaft dieses Priestertums und hat die Schlüssel oder Vollmacht desselben inne."},{"verse":16,"text":"Niemand hat ein gesetzliches Recht auf dieses Amt, die Schlüssel dieses Priestertums innezuhaben, außer er sei ein buchstäblicher Abkömmling Aarons."},{"verse":17,"text":"Aber da ein Hoher Priester des Melchisedekischen Priestertums die Vollmacht hat, in allen geringeren Ämtern zu amtieren, darf er im Amt des Bischofs amtieren, wenn kein buchstäblicher Abkömmling Aarons gefunden werden kann; Voraussetzung ist, dass er berufen und unter den Händen der Präsidentschaft des Melchisedekischen Priestertums zu dieser Macht eingesetzt und ordiniert wird."},{"verse":18,"text":"Die Macht und Vollmacht des höheren oder Melchisedekischen Priestertums ist es, die Schlüssel aller geistigen Segnungen der Kirche innezuhaben –"},{"verse":19,"text":"den Vorzug zu genießen, die Geheimnisse des Himmelreichs zu empfangen, dass sich einem der Himmel auftut, dass man mit der allgemeinen Versammlung und Kirche des Erstgeborenen in Verbindung steht und sich der Gemeinschaft mit Gott dem Vater und mit Jesus, dem Mittler des Neuen Bundes, und deren Gegenwart erfreut."},{"verse":20,"text":"Die Macht und Vollmacht des geringeren oder Aaronischen Priestertums ist es, die Schlüssel des Dienstes von Engeln innezuhaben und die äußerlichen Verordnungen zu vollziehen, den Buchstaben des Evangeliums, die Taufe der Umkehr zur Sündenvergebung, im Einklang mit den Bündnissen und Geboten."},{"verse":21,"text":"Notwendigerweise gibt es Präsidenten oder präsidierende Beamte, die aus denen erwachsen, oder von oder aus denen bestimmt werden, die zu den verschiedenen Ämtern in diesen zwei Priestertümern ordiniert sind."},{"verse":22,"text":"Aus dem Melchisedekischen Priestertum bilden drei präsidierende Hohe Priester, von der Körperschaft erwählt, zu diesem Amt bestimmt und ordiniert und vom Vertrauen, Glauben und Gebet der Kirche getragen, das Kollegium der Präsidentschaft der Kirche."},{"verse":23,"text":"Die zwölf reisenden Räte sind berufen, die Zwölf Apostel oder besonderen Zeugen des Namens Christi in aller Welt zu sein – so unterscheiden sie sich von anderen Beamten in der Kirche durch die Pflichten ihrer Berufung."},{"verse":24,"text":"Und sie bilden ein Kollegium, das den drei vorerwähnten Präsidenten an Vollmacht und Macht gleich ist."},{"verse":25,"text":"Die Siebziger sind ebenfalls berufen, das Evangelium zu predigen und den Anderen sowie in aller Welt besondere Zeugen zu sein – so unterscheiden sie sich von anderen Beamten in der Kirche durch die Pflichten ihrer Berufung."},{"verse":26,"text":"Und sie bilden ein Kollegium, das dem der soeben genannten zwölf besonderen Zeugen oder Apostel an Vollmacht gleich ist."},{"verse":27,"text":"Und jede Entscheidung, die von einem dieser Kollegien getroffen wird, muss bei demselben einstimmig sein, das heißt, jedes Mitglied des betreffenden Kollegiums muss mit dessen Entscheidungen einverstanden sein, damit ihre Entscheidungen dieselbe Macht oder Gültigkeit haben wie die der anderen –"},{"verse":28,"text":"eine Mehrheit kann ein Kollegium bilden, wenn die Umstände es nicht anders erlauben –,"},{"verse":29,"text":"ist dies aber nicht der Fall, so haben ihre Entscheidungen keinen Anspruch auf dieselben Segnungen wie die Entscheidungen eines Kollegiums von drei Präsidenten in alter Zeit, die nach der Ordnung Melchisedeks ordiniert wurden und rechtschaffene und heilige Männer waren."},{"verse":30,"text":"Die Entscheidungen dieser Kollegien, oder von einem davon, sollen in aller Rechtschaffenheit getroffen werden, in Heiligkeit und Herzensdemut, mit Sanftmut und Langmut und Glauben und Tugend und Erkenntnis, Mäßigung, Geduld, Gottesfurcht, brüderlichem Wohlwollen und Nächstenliebe;"},{"verse":31,"text":"denn dies ist die Verheißung: Wenn dieses alles reichlich in ihnen vorhanden ist, werden sie in der Erkenntnis des Herrn nicht unfruchtbar sein."},{"verse":32,"text":"Und falls irgendeine Entscheidung dieser Kollegien auf unrechte Weise getroffen wird, kann sie einer allgemeinen Versammlung der verschiedenen Kollegien vorgelegt werden, welche die geistigen Autoritäten der Kirche bilden; sonst aber gibt es gegen ihre Entscheidung keine Berufung."},{"verse":33,"text":"Die Zwölf sind ein reisender präsidierender Hoherat, der im Namen des Herrn unter der Leitung der Präsidentschaft der Kirche und im Einklang mit der Satzung des Himmels amtieren soll und der die Kirche aufbauen und alle Angelegenheiten derselben in allen Nationen ordnen soll, zuerst bei den Anderen und danach bei den Juden."},{"verse":34,"text":"Die Siebziger sollen im Namen des Herrn unter der Leitung der Zwölf, oder des reisenden Hoherates, handeln, um die Kirche aufzubauen und alle Angelegenheiten derselben in allen Nationen zu ordnen, zuerst bei den Anderen und dann bei den Juden –"},{"verse":35,"text":"die Zwölf, die die Schlüssel innehaben, sind ausgesandt, um durch die Kundmachung des Evangeliums Jesu Christi die Tür zu öffnen, und zwar zuerst den Anderen und dann den Juden."},{"verse":36,"text":"Die ortsständigen Hoheräte in den Zionspfählen bilden ein Kollegium, das in den Angelegenheiten der Kirche in all seinen Entscheidungen dem Kollegium der Präsidentschaft oder dem reisenden Hoherat an Vollmacht gleich ist."},{"verse":37,"text":"Der Hoherat in Zion bildet ein Kollegium, das in den Angelegenheiten der Kirche in all seinen Entscheidungen den Zwölferräten in den Zionspfählen an Vollmacht gleich ist."},{"verse":38,"text":"Es ist die Pflicht des reisenden Hoherates, sich an die Siebziger zu wenden, wenn sie Hilfe benötigen, um die verschiedenen Aufgaben zu erfüllen, wie das Predigen und Vollziehen des Evangeliums, und nicht an irgendjemand anderen."},{"verse":39,"text":"Es ist die Pflicht der Zwölf, in allen großen Zweigen der Kirche Evangelisten zum geistlichen Dienst zu ordinieren, wie sie ihnen durch Offenbarung bezeichnet werden –"},{"verse":40,"text":"die Ordnung dieses Priestertums war dazu bestimmt, vom Vater an den Sohn weitergegeben zu werden, und gehört zu Recht den buchstäblichen Abkömmlingen der erwählten Nachkommenschaft, der diese Verheißungen gegeben worden sind."},{"verse":41,"text":"Diese Ordnung wurde in den Tagen Adams eingerichtet und durch Abstammungslinie auf die folgende Weise weitergegeben:"},{"verse":42,"text":"von Adam an Set, der im Alter von neunundsechzig Jahren von Adam ordiniert wurde und drei Jahre vor seinem (Adams) Tod von ihm gesegnet wurde und durch seinen Vater von Gott die Verheißung empfing, seine Nachkommenschaft werde die vom Herrn erwählte sein und sie werde bis zum Ende der Erde bewahrt bleiben;"},{"verse":43,"text":"denn er (Set) war ein vollkommener Mann, und er war das genaue Ebenbild seines Vaters, so sehr, dass er seinem Vater in allem zu gleichen schien und von diesem nur durch sein Alter unterschieden werden konnte."},{"verse":44,"text":"Enosch wurde im Alter von einhundertvierunddreißig Jahren und vier Monaten durch die Hand Adams ordiniert."},{"verse":45,"text":"Gott rief Kenan in dessen vierzigstem Lebensjahr in der Wildnis zu; und er begegnete Adam, als er nach dem Ort Schedolamach unterwegs war. Er war siebenundachtzig Jahre alt, als er seine Ordinierung empfing."},{"verse":46,"text":"Mahalalel war vierhundertsechsundneunzig Jahre und sieben Tage alt, als er durch die Hand Adams ordiniert wurde, der ihn auch segnete."},{"verse":47,"text":"Jered war zweihundert Jahre alt, als er unter der Hand Adams ordiniert wurde, der ihn auch segnete."},{"verse":48,"text":"Henoch war fünfundzwanzig Jahre alt, als er unter der Hand Adams ordiniert wurde; und er war fünfundsechzig, da segnete ihn Adam."},{"verse":49,"text":"Und er sah den Herrn, und er wandelte mit ihm und war ständig vor seinem Angesicht; und er wandelte dreihundertfünfundsechzig Jahre lang mit Gott, sodass er vierhundertdreißig Jahre alt war, als er entrückt wurde."},{"verse":50,"text":"Metuschelach war einhundert Jahre alt, als er unter der Hand Adams ordiniert wurde."},{"verse":51,"text":"Lamech war zweiunddreißig Jahre alt, als er unter der Hand Sets ordiniert wurde."},{"verse":52,"text":"Noach war zehn Jahre alt, als er unter der Hand Metuschelachs ordiniert wurde."},{"verse":53,"text":"Drei Jahre vor seinem Tod rief Adam Set, Enosch, Kenan, Mahalalel, Jered, Henoch und Metuschelach, die alle Hohe Priester waren, samt seiner übrigen rechtschaffenen Nachkommenschaft in das Tal Adam-ondi-Ahman und ließ ihnen dort seinen letzten Segen zuteilwerden."},{"verse":54,"text":"Und der Herr erschien ihnen, und sie erhoben sich und segneten Adam und nannten ihn Michael, den Fürsten, den Erzengel."},{"verse":55,"text":"Und der Herr ließ Adam Erquickung zuteilwerden und sprach zu ihm: Ich habe dich hingestellt, das Haupt zu sein; eine Menge Nationen werden aus dir kommen, und du bist ein Fürst über sie immerdar."},{"verse":56,"text":"Und Adam stand inmitten der Zusammenkunft auf; und obgleich er vom Alter niedergebeugt war, weissagte er, voll des Heiligen Geistes, alles, was seiner Nachkommenschaft bis zur letzten Generation widerfahren werde."},{"verse":57,"text":"Dies ist alles im Buch Henoch niedergeschrieben und wird zu gegebener Zeit bezeugt werden."},{"verse":58,"text":"Es ist auch die Pflicht der Zwölf, alle anderen Beamten der Kirche zu ordinieren und zu ordnen, im Einklang mit der Offenbarung, die besagt:"},{"verse":59,"text":"An die Kirche Christi im Land Zion, zusätzlich zu den Gesetzen der Kirche hinsichtlich der Angelegenheiten der Kirche –"},{"verse":60,"text":"wahrlich, ich sage euch, spricht der Herr der Heerscharen, es muss notwendigerweise präsidierende Älteste geben, um über diejenigen zu präsidieren, die das Amt eines Ältesten haben;"},{"verse":61,"text":"und auch Priester, um über diejenigen zu präsidieren, die das Amt eines Priesters haben;"},{"verse":62,"text":"und auch Lehrer, um über diejenigen zu präsidieren, die das Amt eines Lehrers haben, in der gleichen Weise, und auch die Diakone –"},{"verse":63,"text":"darum vom Diakon zum Lehrer und vom Lehrer zum Priester und vom Priester zum Ältesten, ein jeder gesondert, wie sie gemäß den Bündnissen und Geboten der Kirche bestimmt werden."},{"verse":64,"text":"Dann kommt das Hohe Priestertum, das größte von allen."},{"verse":65,"text":"Darum muss es notwendigerweise so sein, dass einer aus dem Hohen Priestertum bestimmt wird, über das Priestertum zu präsidieren, und er soll Präsident des Hohen Priestertums der Kirche genannt werden"},{"verse":66,"text":"oder, mit anderen Worten, Präsidierender Hoher Priester über das Hohe Priestertum der Kirche."},{"verse":67,"text":"Von demselben kommt das Vollziehen von heiligen Handlungen und Segnungen in der Kirche, durch das Auflegen der Hände."},{"verse":68,"text":"Darum ist das Amt des Bischofs diesem nicht gleich; denn das Amt des Bischofs besteht darin, in allen zeitlichen Belangen zu amtieren;"},{"verse":69,"text":"doch muss der Bischof aus dem Hohen Priestertum ausgewählt werden, wenn er kein buchstäblicher Abkömmling Aarons ist;"},{"verse":70,"text":"denn wenn er kein buchstäblicher Abkömmling Aarons ist, kann er die Schlüssel jenes Priestertums nicht innehaben."},{"verse":71,"text":"Doch kann ein Hoher Priester, nämlich nach der Ordnung Melchisedeks, eingesetzt werden, um die zeitlichen Belange zu verwalten, denn er wird durch den Geist der Wahrheit Kenntnis davon haben,"},{"verse":72,"text":"und auch, um Richter in Israel zu sein, um die Angelegenheiten der Kirche zu führen, um über Übertreter zu Gericht zu sitzen, aufgrund von Zeugnis, wie es ihm gemäß den Gesetzen vorgelegt wird, mit dem Beistand seiner Ratgeber, die er sich aus den Ältesten der Kirche erwählt hat oder erwählen wird."},{"verse":73,"text":"Dies ist die Pflicht eines Bischofs, der kein buchstäblicher Abkömmling Aarons ist, aber zum Hohen Priestertum nach der Ordnung Melchisedeks ordiniert worden ist."},{"verse":74,"text":"So soll er Richter sein, nämlich allgemeiner Richter bei den Einwohnern Zions oder in einem Zionspfahl oder in irgendeinem Zweig der Kirche, wo er zu diesem geistlichen Dienst eingesetzt wird, bis die Grenzen Zions erweitert werden und es notwendig wird, in Zion oder anderswo weitere Bischöfe oder Richter zu haben."},{"verse":75,"text":"Und insoweit weitere Bischöfe bestimmt werden, sollen sie das gleiche Amt ausüben."},{"verse":76,"text":"Aber ein buchstäblicher Abkömmling Aarons hat ein gesetzliches Recht auf die Präsidentschaft dieses Priestertums, auf die Schlüssel dieses geistlichen Dienstes, darauf, das Amt des Bischofs selbständig auszuüben, ohne Ratgeber, außer in einem Fall, wo gegen einen Präsidenten des Hohen Priestertums nach der Ordnung Melchisedeks vorgegangen wird, darauf, als Richter in Israel zu sitzen."},{"verse":77,"text":"Und wenn einer dieser Räte eine Entscheidung trifft, so im Einklang mit dem Gebot, das besagt:"},{"verse":78,"text":"Weiter, wahrlich, ich sage euch: Die wichtigsten Angelegenheiten der Kirche und die schwierigsten Fälle der Kirche sollen, insoweit es über die Entscheidung des Bischofs oder der Richter Unzufriedenheit gibt, dem Rat der Kirche übergeben und vorgetragen werden, vor der Präsidentschaft des Hohen Priestertums."},{"verse":79,"text":"Und die Präsidentschaft des Rates des Hohen Priestertums hat die Macht, weitere Hohe Priester, nämlich zwölf, zu berufen, dass sie als Ratgeber behilflich sind; und so hat die Präsidentschaft des Hohen Priestertums mit ihren Ratgebern die Macht, gemäß den Gesetzen der Kirche aufgrund von Zeugnis zu entscheiden."},{"verse":80,"text":"Und nach dieser Entscheidung soll der Fall nicht mehr vor dem Herrn in Erinnerung gebracht werden; denn dies ist der höchste Rat der Kirche Gottes und die endgültige Entscheidung in Streitfällen geistiger Natur."},{"verse":81,"text":"Es gibt niemanden, der der Kirche angehört, der von diesem Rat der Kirche ausgenommen ist."},{"verse":82,"text":"Und falls ein Präsident des Hohen Priestertums übertritt, soll er vor dem allgemeinen Rat der Kirche in Erinnerung gebracht werden, der von zwölf Ratgebern aus dem Hohen Priestertum unterstützt werden soll;"},{"verse":83,"text":"und ihre Entscheidung auf seinem Haupt soll die Streitigkeit in Bezug auf ihn beenden."},{"verse":84,"text":"Auf diese Weise wird niemand von der Gerechtigkeit und den Gesetzen Gottes ausgenommen sein, damit alles in Ordnung und mit Ernsthaftigkeit vor ihm geschehe, gemäß Wahrheit und Rechtschaffenheit."},{"verse":85,"text":"Und weiter, wahrlich, ich sage euch: Die Pflicht des Präsidenten über das Amt des Diakons ist es, über zwölf Diakone zu präsidieren, mit ihnen zu Rate zu sitzen und sie ihre Pflicht zu lehren und alle einander erbauen zu lassen, wie es gemäß den Bündnissen angegeben ist."},{"verse":86,"text":"Und auch die Pflicht des Präsidenten über das Amt der Lehrer ist es, über vierundzwanzig Lehrer zu präsidieren und mit ihnen zu Rate zu sitzen und sie die Pflichten ihres Amtes zu lehren, wie in den Bündnissen angegeben."},{"verse":87,"text":"Auch die Pflicht des Präsidenten über das Priestertum Aarons ist es, über achtundvierzig Priester zu präsidieren und mit ihnen zu Rate zu sitzen, sie die Pflichten ihres Amtes zu lehren, wie es in den Bündnissen angegeben ist –"},{"verse":88,"text":"dieser Präsident muss Bischof sein; denn dies ist eine der Pflichten dieses Priestertums."},{"verse":89,"text":"Weiter, die Pflicht des Präsidenten über das Amt der Ältesten ist es, über sechsundneunzig Älteste zu präsidieren und mit ihnen zu Rate zu sitzen und sie gemäß den Bündnissen zu belehren."},{"verse":90,"text":"Diese Präsidentschaft unterscheidet sich von der der Siebziger und ist für diejenigen vorgesehen, die nicht in alle Welt hinaus reisen."},{"verse":91,"text":"Und weiter, die Pflicht des Präsidenten des Amtes des Hohen Priestertums ist es, über die ganze Kirche zu präsidieren und so wie Mose zu sein –"},{"verse":92,"text":"siehe, hier ist Weisheit; ja, ein Seher, ein Offenbarer, ein Übersetzer und ein Prophet zu sein, der alle die Gaben Gottes besitzt, die dieser dem Haupt der Kirche zuteilwerden lässt."},{"verse":93,"text":"Und es ist gemäß der Vision, die die Ordnung der Siebziger zeigt, dass sie sieben Präsidenten haben sollen, die über sie präsidieren, erwählt aus der Zahl der Siebziger;"},{"verse":94,"text":"und der siebente Präsident dieser Präsidenten soll über die sechs präsidieren;"},{"verse":95,"text":"und diese sieben Präsidenten sollen außer den ersten siebzig, denen sie selbst angehören, weitere siebzig erwählen und sollen über sie präsidieren;"},{"verse":96,"text":"und noch weitere siebzig, bis siebenmal siebzig, wenn die Arbeit im Weingarten es notwendigerweise erfordert."},{"verse":97,"text":"Und diese Siebziger sollen reisende geistliche Diener sein, zuerst für die Anderen und auch für die Juden."},{"verse":98,"text":"Dagegen sind andere Beamte der Kirche, die nicht den Zwölf und auch nicht den Siebzigern angehören, nicht verpflichtet, zu allen Nationen zu reisen, sondern sie sollen reisen, wie es ihre Umstände zulassen, ungeachtet dessen, dass sie ebenso hohe und verantwortungsvolle Ämter in der Kirche innehaben mögen."},{"verse":99,"text":"Darum lasst nun einen jeden seine Pflicht lernen und mit allem Eifer das Amt ausüben lernen, zu dem er bestimmt worden ist."},{"verse":100,"text":"Wer träge ist, wird nicht für würdig erachtet werden zu stehen; und wer seine Pflicht nicht lernt und sich nicht als annehmbar erweist, wird nicht für würdig erachtet werden zu stehen. So ist es. Amen."}]},{"chapter":108,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr zu dir, mein Diener Lyman: Deine Sünden sind dir vergeben, weil du meiner Stimme gehorcht hast und heute Morgen hierhergekommen bist, um von demjenigen Rat zu empfangen, den ich bestimmt habe."},{"verse":2,"text":"Darum lass deine Seele ruhig sein, was deinen Stand in geistigen Belangen betrifft, und widerstehe meiner Stimme nicht länger."},{"verse":3,"text":"Und erhebe dich, und beachte von nun an sorgfältiger deine Gelübde, die du abgelegt hast und noch ablegst, dann wirst du mit überaus großen Segnungen gesegnet werden."},{"verse":4,"text":"Warte geduldig, bis die feierliche Versammlung meiner Diener einberufen wird, dann wird deiner mit den ersten meiner Ältesten gedacht werden, und du wirst mit den übrigen meiner Ältesten, die ich ausgewählt habe, das Recht durch Ordinierung empfangen."},{"verse":5,"text":"Siehe, das ist die Verheißung des Vaters für dich, wenn du weiterhin treu bist."},{"verse":6,"text":"Und an dem Tag wird es sich für dich erfüllen, dass du das Recht haben wirst, mein Evangelium zu predigen, von nun an, wohin auch immer ich dich von der Zeit an senden werde."},{"verse":7,"text":"Darum stärke deine Brüder in all deinem Umgang, in all deinen Gebeten, in all deinen Ermahnungen und in all deinem Tun."},{"verse":8,"text":"Und siehe, ja siehe, ich bin bei dir, um dich zu segnen und dich für immer zu befreien. Amen."}]},{"chapter":109,"verses":[{"verse":1,"text":"Dank sei deinem Namen, o Herr, Gott Israels, der du den Bund hältst und deinen Dienern Barmherzigkeit erzeigst, die mit ganzem Herzen untadelig vor dir wandeln –"},{"verse":2,"text":"der du deinen Dienern geboten hast, deinem Namen an diesem Ort [Kirtland] ein Haus zu bauen."},{"verse":3,"text":"Und nun siehst du, o Herr, dass deine Diener gemäß deinem Gebot gehandelt haben."},{"verse":4,"text":"Und nun bitten wir dich, heiliger Vater, im Namen Jesu Christi, der der Sohn deines Herzens ist und in dessen Namen allein den Menschenkindern Errettung zuteilwerden kann, wir bitten dich, o Herr, nimm dieses Haus an, das Werk unserer, deiner Diener, Hände, das zu bauen du uns geboten hast."},{"verse":5,"text":"Denn du weißt, dass wir dieses Werk inmitten großer Drangsal vollbracht haben; und in unserer Armut haben wir von unserer Habe gegeben, um deinem Namen ein Haus zu bauen, damit des Menschen Sohn eine Stätte habe, wo er sich seinem Volk kundtun kann."},{"verse":6,"text":"Und wie du in einer Offenbarung gesagt hast, die du uns gegeben hast und worin du uns deine Freunde genannt und gesagt hast: Beruft eure feierliche Versammlung ein, wie ich es euch geboten habe;"},{"verse":7,"text":"und da nicht alle Glauben haben, so sucht eifrig und lehrt einander Worte der Weisheit; ja, sucht Worte der Weisheit aus den besten Büchern; trachtet nach Wissen, ja, durch Studium und auch durch Glauben;"},{"verse":8,"text":"organisiert euch; bereitet alles vor, was nötig ist; und errichtet ein Haus, nämlich ein Haus des Betens, ein Haus des Fastens, ein Haus des Glaubens, ein Haus des Lernens, ein Haus der Herrlichkeit, ein Haus der Ordnung, ein Haus Gottes;"},{"verse":9,"text":"damit euer Eintreten im Namen des Herrn geschehe; damit euer Weggehen im Namen des Herrn geschehe; damit alle eure Begrüßungen im Namen des Herrn geschehen, die Hände zum Allerhöchsten erhoben –"},{"verse":10,"text":"und so bitten wir dich nun, heiliger Vater, stehe uns, deinem Volk, mit deiner Gnade bei, wenn wir unsere feierliche Versammlung einberufen, damit es zu deiner Ehre geschehe und deiner göttlichen Annahme wert sei,"},{"verse":11,"text":"und auf eine Weise, dass wir in deinen Augen für würdig befunden werden, uns die Erfüllung der Verheißungen zu sichern, die du uns, deinem Volk, in den uns erteilten Offenbarungen gegeben hast,"},{"verse":12,"text":"damit deine Herrlichkeit sich niederlasse auf dein Volk und auf dieses dein Haus, das wir dir nun weihen, damit es geheiligt werde und als Heiligtum geweiht sei und damit deine heilige Gegenwart sich beständig in diesem Haus befinde;"},{"verse":13,"text":"und damit alle Menschen, die über die Schwelle des Hauses des Herrn treten, deine Macht verspüren und sich gedrängt fühlen anzuerkennen, dass du es geheiligt hast und dass es dein Haus ist, eine Stätte deiner Heiligkeit."},{"verse":14,"text":"Und gewähre, heiliger Vater, dass all jene, die in diesem Haus anbeten werden, Worte der Weisheit aus den besten Büchern gelehrt werden und dass sie nach Wissen trachten, ja, durch Studium und auch durch Glauben, wie du gesagt hast,"},{"verse":15,"text":"und dass sie in dir aufwachsen und eine Fülle des Heiligen Geistes empfangen und sich gemäß deinen Gesetzen organisieren und bereit sind, alles zu erlangen, was nötig ist,"},{"verse":16,"text":"und dass dieses Haus ein Haus des Betens, ein Haus des Fastens, ein Haus des Glaubens, ein Haus der Herrlichkeit und Gottes sei, ja, dein Haus,"},{"verse":17,"text":"dass alles Eintreten deines Volkes in dieses Haus im Namen des Herrn geschehe,"},{"verse":18,"text":"dass all sein Weggehen aus diesem Haus im Namen des Herrn geschehe"},{"verse":19,"text":"und dass alle seine Begrüßungen im Namen des Herrn geschehen, mit heiligen Händen, zum Allerhöchsten erhoben,"},{"verse":20,"text":"und dass nichts Unreines in dein Haus eingelassen werde, es zu verunreinigen;"},{"verse":21,"text":"und wenn irgendwelche von deinem Volk übertreten, dass sie rasch umkehren und zu dir zurückkehren und in deinen Augen Gunst finden und ihnen die Segnungen wiedergegeben werden mögen, die nach deiner Verordnung über diejenigen ausgegossen werden sollen, die dich in deinem Haus verehren."},{"verse":22,"text":"Und wir bitten dich, heiliger Vater: Mögen deine Diener, wenn sie aus diesem Haus hinausgehen, mit deiner Macht ausgerüstet sein, und mögen dein Name auf ihnen sein und deine Herrlichkeit rings um sie sein und deine Engel Verantwortung über sie haben;"},{"verse":23,"text":"und mögen sie von dieser Stätte überaus große und herrliche Nachricht in Wahrheit hinaustragen bis an die Enden der Erde, damit sie wissen, dass dies dein Werk ist und dass du deine Hand ausgestreckt hast, um das zu erfüllen, was du durch den Mund der Propheten in Bezug auf die letzten Tage gesprochen hast."},{"verse":24,"text":"Wir bitten dich, heiliger Vater, gib dem Volk, das anbeten und sich einen achtbaren Namen und Stand in diesem deinem Haus bewahren wird, für alle Generationen und für die Ewigkeit festen Bestand,"},{"verse":25,"text":"dass keiner Waffe, die gegen es geformt wird, etwas gelinge; dass derjenige, der ihm eine Grube gräbt, selbst hineinfalle;"},{"verse":26,"text":"dass keine Verbindung der Schlechtigkeit die Macht habe, sich zu erheben und dein Volk zu überwältigen, auf das in diesem Haus dein Name gelegt werden wird;"},{"verse":27,"text":"und wenn sich irgendein Volk gegen dieses Volk erheben wird, dass dein Zorn gegen es entflamme;"},{"verse":28,"text":"und wenn es dieses Volk schlagen wird, dass du es schlägst; dass du für dein Volk kämpfest, wie du es am Tag der Schlacht getan hast, damit es aus den Händen all seiner Feinde befreit werde."},{"verse":29,"text":"Wir bitten dich, heiliger Vater, alle diejenigen, die Lügenberichte über deinen Diener oder deine Diener in die Welt hinaus verbreitet haben, zu beschämen und zu erschrecken und in Scham und Verwirrung zu versetzen, wenn sie nicht umkehren, sobald ihnen das immerwährende Evangelium zu Gehör gebracht wird,"},{"verse":30,"text":"und dass alle ihre Werke zunichtegemacht werden mögen und vom Hagel und von den Richtersprüchen, die du in deinem Zorn über sie senden wirst, hinweggefegt werden, damit das Lügen und Verleumden gegen dein Volk ein Ende habe."},{"verse":31,"text":"Denn du weißt, o Herr, dass deine Diener vor dir schuldlos gewesen sind, wenn sie für deinen Namen Zeugnis gegeben haben, wofür sie das alles haben erdulden müssen."},{"verse":32,"text":"Darum flehen wir dich um gänzliche und vollständige Befreiung von diesem Joch an;"},{"verse":33,"text":"brich es weg, o Herr; brich es mit deiner Macht weg vom Hals deiner Diener, damit wir uns inmitten dieser Generation erheben und dein Werk tun können."},{"verse":34,"text":"O Jehova, sei barmherzig zu diesem Volk, und da alle Menschen sündigen, so vergib deinem Volk seine Übertretungen und lass sie für immer ausgelöscht sein."},{"verse":35,"text":"Lass die Salbung deiner Diener mit Macht aus der Höhe auf sie gesiegelt sein."},{"verse":36,"text":"Lass es an ihnen erfüllt werden wie an denen am Pfingsttag; lass die Gabe der Zungenrede über dein Volk ausgegossen sein, ja, Zungen, zerteilt, wie von Feuer, und auch deren Auslegung."},{"verse":37,"text":"Und lass dein Haus von deiner Herrlichkeit erfüllt sein wie vom Brausen eines mächtigen Windes."},{"verse":38,"text":"Lege auf deine Diener das Zeugnis des Bundes, damit sie, wenn sie hinausgehen und dein Wort verkündigen, das Gesetz versiegeln und deinen Heiligen das Herz für alle jene Richtersprüche bereitmachen können, die du in deinem Grimm im Begriff bist, wegen ihrer Übertretungen auf die Bewohner der Erde zu senden, damit dein Volk am Tag der Beunruhigung nicht verzage."},{"verse":39,"text":"Und welche Stadt auch immer deine Diener betreten, und die Bewohner jener Stadt nehmen ihr Zeugnis an, da lass deinen Frieden und deine Errettung auf jener Stadt sein, damit sie aus jener Stadt die Rechtschaffenen sammeln können, damit sie nach Zion oder seinen Pfählen, den Stätten deiner Bestimmung, ziehen mögen mit Liedern immerwährender Freude;"},{"verse":40,"text":"und ehe dies vollbracht ist, lass deine Strafgerichte nicht auf jene Stadt fallen."},{"verse":41,"text":"Und welche Stadt auch immer deine Diener betreten, und die Bewohner jener Stadt nehmen das Zeugnis deiner Diener nicht an, und deine Diener warnen sie, sich aus dieser verkehrten Generation zu erretten, da lass über jene Stadt kommen, was du durch den Mund deiner Propheten gesprochen hast."},{"verse":42,"text":"Aber befreie du, o Jehova, wir bitten dich inständig, deine Diener aus ihren Händen, und säubere sie von deren Blut."},{"verse":43,"text":"O Herr, wir freuen uns nicht am Untergang unserer Mitmenschen, ihre Seele ist kostbar vor dir;"},{"verse":44,"text":"aber dein Wort muss sich erfüllen. Hilf deinen Dienern zu sagen, wobei deine Gnade ihnen beistehe: Dein Wille geschehe, o Herr, und nicht der unsere."},{"verse":45,"text":"Wir wissen, dass du durch den Mund deiner Propheten Schreckliches in Bezug auf die Schlechten in den letzten Tagen gesprochen hast – dass du deine Strafgerichte ohne Maß ausgießen wirst;"},{"verse":46,"text":"darum, o Herr, befreie dein Volk aus dem Unheil der Schlechten; befähige deine Diener, das Gesetz zu versiegeln und das Zeugnis zuzubinden, damit sie auf den Tag des Brennens vorbereitet seien."},{"verse":47,"text":"Wir bitten dich, heiliger Vater, gedenke derer, die von den Einwohnern des Kreises Jackson, Missouri, vom Land ihres Erbteils verjagt worden sind, und brich, o Herr, dieses Joch der Bedrängnis weg, das ihnen auferlegt worden ist."},{"verse":48,"text":"Du weißt, o Herr, dass sie von schlechten Menschen schwer bedrückt und bedrängt worden sind; und das Herz zerfließt uns vor Besorgnis über ihre schmerzlichen Lasten."},{"verse":49,"text":"O Herr, wie lange wirst du dulden, dass dieses Volk diese Bedrängnis ertragen muss und die Schreie seiner Unschuldigen dir in die Ohren emporsteigen und ihr Blut zum Zeugnis vor dich hinaufkomme und du nicht dein Zeugnis zu ihren Gunsten erkennen lässt?"},{"verse":50,"text":"Habe Erbarmen, o Herr, mit dem üblen Pöbel, der dein Volk verjagt hat, damit sie aufhören zu plündern, damit sie von ihren Sünden umkehren, sofern Umkehr zu finden ist;"},{"verse":51,"text":"wenn sie aber nicht wollen, so entblöße deinen Arm, o Herr, und erlöse, was du deinem Volk als Zion bestimmt hast."},{"verse":52,"text":"Und wenn es nicht anders sein kann, damit die Sache deines Volkes vor dir nicht fehlschlage, dann lass deinen Zorn entflammen und deinen Unwillen auf sie fallen, damit sie dahinschwinden unter dem Himmel, sowohl Wurzel als auch Zweig;"},{"verse":53,"text":"aber insoweit sie umkehren, bist du gnädig und barmherzig und wirst deinen Grimm abwenden, wenn du auf das Angesicht deines Gesalbten schaust."},{"verse":54,"text":"Habe Erbarmen, o Herr, mit allen Nationen auf Erden; habe Erbarmen mit den in unserem Land Herrschenden; mögen jene Grundsätze, die von unseren Vätern so ehrenhaft und vortrefflich verteidigt worden sind, nämlich die Verfassung unseres Landes, aufrechterhalten bleiben immerdar."},{"verse":55,"text":"Gedenke der Könige, der Fürsten, der Edlen und der Großen auf Erden und allen Volkes und der Kirchen, aller Armen, der Bedürftigen und Bedrängten auf der Erde,"},{"verse":56,"text":"damit ihr Herz erweicht werde, wenn deine Diener, o Jehova, aus deinem Haus hingehen und für deinen Namen Zeugnis geben, damit ihre Vorurteile vor der Wahrheit zurückweichen und dein Volk Gunst finde in den Augen aller;"},{"verse":57,"text":"damit alle Enden der Erde wissen mögen, dass wir, deine Diener, deine Stimme vernommen haben und dass du uns gesandt hast;"},{"verse":58,"text":"damit aus all diesen deine Diener, die Söhne Jakobs, die Rechtschaffenen sammeln können, dass sie deinem Namen eine heilige Stadt bauen, wie du ihnen geboten hast."},{"verse":59,"text":"Wir bitten dich, für Zion noch weitere Pfähle zu bestimmen, außer diesem einen, den du schon bestimmt hast, damit die Sammlung deines Volkes mit großer Macht und Erhabenheit voranschreite und damit dein Werk in Rechtschaffenheit abgekürzt werde."},{"verse":60,"text":"Diese Worte nun haben wir vor dir, o Herr, gesprochen, in Bezug auf die Offenbarungen und Gebote, die du uns gegeben hast, die wir den Anderen gleichgesetzt sind."},{"verse":61,"text":"Aber du weißt, dass du große Liebe für die Kinder Jakob hast, die seit langer Zeit auf den Bergen zerstreut sind, an einem wolkigen und finsteren Tag."},{"verse":62,"text":"Darum bitten wir dich, habe Erbarmen mit den Kindern Jakob, damit die Erlösung Jerusalems von dieser Stunde an ihren Anfang nehme"},{"verse":63,"text":"und das Joch der Knechtschaft von nun an vom Haus David weggebrochen werde"},{"verse":64,"text":"und die Kinder Juda anfangen können, in die Länder zurückzukehren, die du ihrem Vater Abraham gegeben hast."},{"verse":65,"text":"Und lass die Übriggebliebenen von Jakob, die wegen ihrer Übertretung verflucht und geschlagen worden sind, sich von ihrem wilden und rohen Zustand zur Fülle des immerwährenden Evangeliums bekehren,"},{"verse":66,"text":"damit sie ihre Waffen des Blutvergießens niederlegen und ihre Auflehnung beenden."},{"verse":67,"text":"Und mögen alle die zerstreuten Überreste Israels, die bis an die Enden der Erde gejagt worden sind, zur Erkenntnis der Wahrheit kommen, an den Messias glauben und aus der Unterdrückung erlöst werden und sich vor dir freuen."},{"verse":68,"text":"O Herr, gedenke deines Dieners Joseph Smith Jr. und all seiner Bedrängnisse und Verfolgungen – wie er mit Jehova einen Bund geschlossen und dir, o mächtiger Gott Jakobs, sein Gelübde dargebracht hat – und der Gebote, die du ihm gegeben hast, und dass er sich aufrichtig bemüht hat, deinen Willen zu tun."},{"verse":69,"text":"Habe Erbarmen, o Herr, mit seiner Frau und seinen Kindern, damit sie in deiner Gegenwart erhöht und von deiner hegenden Hand erhalten werden mögen."},{"verse":70,"text":"Habe Erbarmen mit all ihren unmittelbaren Verwandten, damit deren Vorurteile gebrochen und wie von einer Flut hinweggespült werden, damit sie bekehrt und mit Israel erlöst werden und wissen mögen, dass du Gott bist."},{"verse":71,"text":"Gedenke, o Herr, der Präsidenten, ja, aller Präsidenten deiner Kirche, dass deine rechte Hand sie samt all ihren Familien und ihren unmittelbaren Verwandten erhöhe, dass ihr Name bestehen bleibe und von Generation zu Generation in immerwährendem Andenken gehalten werde."},{"verse":72,"text":"Gedenke, o Herr, deiner gesamten Kirche, mit all ihren Familien und all ihren unmittelbaren Verwandten, mit all ihren Kranken und Bedrängten, mit allen Armen und Sanftmütigen der Erde, damit das Reich, das du ohne das Zutun von Händen errichtet hast, ein großer Berg werde und die ganze Erde erfülle,"},{"verse":73,"text":"damit deine Kirche aus der Wildnis der Finsternis hervorkomme und leuchte, schön wie der Mond, klar wie die Sonne und schrecklich wie ein Heer mit Bannern,"},{"verse":74,"text":"und wie eine Braut geschmückt sei für jenen Tag, da du von den Himmeln den Schleier wegnehmen und machen wirst, dass die Berge vor deiner Gegenwart zerfließen und die Täler erhöht werden, die zerklüfteten Orte geebnet, damit deine Herrlichkeit die Erde erfülle,"},{"verse":75,"text":"damit wir, wenn die Posaune für die Toten ertönt, in der Wolke entrückt werden, dir entgegen, damit wir für immer beim Herrn seien,"},{"verse":76,"text":"damit unsere Kleider rein seien, damit wir mit dem Gewand der Rechtschaffenheit, mit Palmen in unseren Händen und der Krone der Herrlichkeit auf unserem Haupt angetan seien und für alle unsere Leiden ewige Freude ernten."},{"verse":77,"text":"O Herr, allmächtiger Gott, erhöre uns bei diesem unserem Flehen, und gib uns Antwort vom Himmel, deiner heiligen Wohnung, wo du auf dem Thron sitzest – mit Herrlichkeit, Ehre, Macht, Majestät, Kraft, Herrschaft, Wahrheit, Gerechtigkeit, Rechtsprechung, Barmherzigkeit und einer unbegrenzten Fülle, vom Immerwährenden zum Immerwährenden."},{"verse":78,"text":"O erhöre, o erhöre, o erhöre uns, o Herr! Und gib Antwort auf dieses Flehen, und nimm es an, dass wir dir dieses Haus weihen, das Werk unserer Hände, das wir deinem Namen gebaut haben,"},{"verse":79,"text":"und ebenso diese Kirche, dass du deinen Namen auf sie legest. Und hilf uns durch die Macht deines Geistes, damit wir unsere Stimme verschmelzen lassen mit jenen strahlenden, leuchtenden Serafim rings um deinen Thron, mit jauchzender Lobpreisung und dem Gesang: Hosanna Gott und dem Lamm!"},{"verse":80,"text":"Und lass diese deine Gesalbten mit Errettung bekleidet sein und deine Heiligen vor Freude laut rufen. Amen und Amen."}]},{"chapter":110,"verses":[{"verse":1,"text":"Der Schleier wurde von unserem Sinn weggenommen, und uns gingen die Augen unseres Verständnisses auf."},{"verse":2,"text":"Wir sahen den Herrn auf der Brüstung der Kanzel vor uns stehen, und unter seinen Füßen war eine Pflasterarbeit aus reinem Gold, in der Farbe wie Bernstein."},{"verse":3,"text":"Seine Augen waren wie eine Feuerflamme, sein Haupthaar war weiß wie reiner Schnee, sein Antlitz leuchtete heller als das Licht der Sonne, und seine Stimme tönte wie das Rauschen großer Gewässer, ja, die Stimme Jehovas, die sprach:"},{"verse":4,"text":"Ich bin der Erste und der Letzte; ich bin der, der lebt, ich bin der, der getötet worden ist; ich bin euer Fürsprecher beim Vater."},{"verse":5,"text":"Siehe, eure Sünden sind euch vergeben; ihr seid rein vor mir; darum hebt euer Haupt empor und freut euch."},{"verse":6,"text":"Lasst das Herz eurer Brüder sich freuen, und lasst das Herz all meines Volkes sich freuen, das mit all seiner Macht meinem Namen dieses Haus gebaut hat."},{"verse":7,"text":"Denn siehe, ich habe dieses Haus angenommen, und mein Name wird hier sein, und ich werde mich meinem Volk mit Barmherzigkeit in diesem Haus kundtun."},{"verse":8,"text":"Ja, ich werde meinen Dienern erscheinen und mit meiner eigenen Stimme zu ihnen sprechen, wenn mein Volk meine Gebote hält und dieses heilige Haus nicht verunreinigt."},{"verse":9,"text":"Ja, das Herz Tausender und Zehntausender wird sich sehr freuen infolge der Segnungen, die ausgegossen werden sollen, und des Endowments, mit dem meine Diener in diesem Haus ausgerüstet worden sind."},{"verse":10,"text":"Und der Ruhm dieses Hauses wird sich in fremde Länder ausbreiten, und das ist der Anfang der Segnung, die meinem Volk auf das Haupt ausgegossen werden wird. So ist es. Amen."},{"verse":11,"text":"Nachdem diese Vision zu Ende war, öffneten sich uns die Himmel abermals, und Mose erschien vor uns und übertrug uns die Schlüssel zur Sammlung Israels von den vier Teilen der Erde und zur Rückführung der zehn Stämme aus dem Land des Nordens."},{"verse":12,"text":"Danach erschien Elias und übertrug die Evangeliumszeit Abrahams und sagte, in uns und unseren Nachkommen würden alle Generationen nach uns gesegnet sein."},{"verse":13,"text":"Nachdem diese Vision zu Ende war, wurde uns plötzlich eine weitere große und herrliche Vision eröffnet, denn der Prophet Elija, der in den Himmel aufgenommen wurde, ohne den Tod zu schmecken, stand vor uns und sprach:"},{"verse":14,"text":"Siehe, die Zeit ist völlig da, von der Maleachis Mund gesprochen hat – der bezeugte, dass er [Elija] gesandt werden würde, ehe der große und schreckliche Tag des Herrn käme –"},{"verse":15,"text":"um das Herz der Väter den Kindern und das der Kinder den Vätern zuzuwenden, damit nicht die ganze Erde mit einem Fluch geschlagen werde –,"},{"verse":16,"text":"darum sind die Schlüssel dieser Evangeliumszeit in eure Hände übergeben, und dadurch könnt ihr wissen, dass der große und schreckliche Tag des Herrn nahe ist, ja, vor der Tür."}]},{"chapter":111,"verses":[{"verse":1,"text":"Ich, der Herr, euer Gott, bin trotz eurer Torheiten nicht ungehalten darüber, dass ihr diese Reise unternommen habt."},{"verse":2,"text":"Ich habe viele Schätze für euch in dieser Stadt zum Nutzen Zions und viele Menschen in dieser Stadt, die ich zu gegebener Zeit durch euer Mitwirken zum Nutzen Zions aus ihr sammeln werde."},{"verse":3,"text":"Darum ist es ratsam, dass ihr mit den Menschen in dieser Stadt Bekanntschaft knüpft, wie ihr geführt werdet und wie es euch eingegeben werden wird."},{"verse":4,"text":"Und zu gegebener Zeit wird es sich begeben: Ich werde diese Stadt euch in die Hände geben, sodass ihr Macht über sie habt, sodass sie eure geheimen Absichten nicht entdecken; und ihr Reichtum an Gold und Silber wird euer sein."},{"verse":5,"text":"Macht euch keine Sorgen wegen eurer Schulden, denn ich werde euch die Macht geben, sie zu bezahlen."},{"verse":6,"text":"Macht euch keine Sorgen wegen Zion, denn ich werde barmherzig mit ihm umgehen."},{"verse":7,"text":"Verweilt an diesem Ort und in den Gebieten ringsum,"},{"verse":8,"text":"und die Stätte, wo ihr nach meinem Willen hauptsächlich verweilen sollt, wird euch durch den Frieden und die Macht meines Geistes, die euch zufließen werden, bezeichnet werden."},{"verse":9,"text":"Diese Stätte könnt ihr für euch mieten. Und erkundigt euch eifrig nach den ehemaligen Einwohnern und Gründern dieser Stadt,"},{"verse":10,"text":"denn in dieser Stadt gibt es mehr Schätze für euch als nur einen."},{"verse":11,"text":"Darum seid klug wie die Schlangen und doch ohne Sünde, dann werde ich alles für euch zum Guten ordnen, so schnell, wie ihr imstande seid, es zu empfangen. Amen."}]},{"chapter":112,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr zu dir, mein Diener Thomas: Ich habe deine Gebete vernommen; und deine Almosen sind zu mir heraufgekommen, zum Gedächtnis für diejenigen, deine Brüder, die erwählt worden sind, für meinen Namen Zeugnis zu geben und dieses hinauszusenden an alle Nationen, Geschlechter, Sprachen und Völker, und die durch die Mithilfe meiner Diener ordiniert worden sind."},{"verse":2,"text":"Wahrlich, ich sage dir: Es hat in deinem Herzen und bei dir einiges wenige gegeben, woran ich, der Herr, kein Wohlgefallen hatte."},{"verse":3,"text":"Doch weil du dich erniedrigt hast, sollst du erhöht werden; darum sind dir alle deine Sünden vergeben."},{"verse":4,"text":"Lass dein Herz guten Mutes sein vor meinem Angesicht; und du sollst für meinen Namen Zeugnis geben, nicht nur den Anderen, sondern auch den Juden; und du sollst mein Wort hinaussenden bis an die Enden der Erde."},{"verse":5,"text":"Kämpfe darum Morgen für Morgen; und Tag für Tag lass deine warnende Stimme ergehen; und wenn die Nacht kommt, lass die Bewohner der Erde deiner Rede wegen nicht schlummern."},{"verse":6,"text":"Lass deine Wohnung in Zion bekannt sein, und ziehe mit deinem Haus nicht weg; denn ich, der Herr, habe ein großes Werk für dich zu tun, nämlich meinen Namen unter den Menschenkindern zu verkünden."},{"verse":7,"text":"Darum gürte dir die Lenden für das Werk. Lass auch deine Füße beschuht sein, denn du bist erwählt, und dein Pfad liegt in den Bergen und bei vielen Nationen."},{"verse":8,"text":"Und durch dein Wort werden viele Hohe erniedrigt werden, und durch dein Wort werden viele Niedrige erhöht werden."},{"verse":9,"text":"Deine Stimme soll eine Zurechtweisung für den Übertreter sein; und auf deine Zurechtweisung hin soll die Zunge des Verleumders mit ihrer Frevelhaftigkeit aufhören."},{"verse":10,"text":"Sei demütig, dann wird der Herr, dein Gott, dich an der Hand führen und dir auf deine Gebete Antwort geben."},{"verse":11,"text":"Ich kenne dein Herz und habe deine Gebete in Bezug auf deine Brüder vernommen. Sei nicht parteiisch gegen sie, indem du sie mehr liebst als viele andere, aber lass deine Liebe zu ihnen so sein wie zu dir selbst; und lass deine Liebe für alle Menschen und für alle, die meinen Namen lieben, reichlich vorhanden sein."},{"verse":12,"text":"Und bete für deine Brüder von den Zwölf. Ermahne sie mit Deutlichkeit um meines Namens willen, und lass sie wegen all ihrer Sünden ermahnt werden, und sei meinem Namen treu vor mir."},{"verse":13,"text":"Und nach ihren Versuchungen und vieler Drangsal, siehe, werde ich, der Herr, nach ihnen fühlen, und wenn sie ihr Herz nicht verhärten und ihren Hals nicht starr gegen mich machen, werden sie sich bekehren, und ich werde sie heilen."},{"verse":14,"text":"Nun sage ich dir, und was ich zu dir sage, das sage ich zu allen Zwölf: Erhebt euch und gürtet euch die Lenden, nehmt euer Kreuz auf euch, folgt mir nach und weidet meine Schafe."},{"verse":15,"text":"Erhöht euch nicht selbst; lehnt euch nicht gegen meinen Diener Joseph auf; denn wahrlich, ich sage euch: Ich bin mit ihm, und meine Hand wird über ihm sein; und die Schlüssel, die ich ihm gegeben habe, und auch an euch, werden nicht von ihm genommen werden, bis ich komme."},{"verse":16,"text":"Wahrlich, ich sage dir, mein Diener Thomas: Du bist der Mann, den ich erwählt habe, die Schlüssel meines Reiches innezuhaben, was die Zwölf betrifft, draußen unter allen Nationen –"},{"verse":17,"text":"damit du mein Diener seiest, um die Tür des Reiches überall dort aufzuschließen, wohin mein Diener Joseph und mein Diener Sidney und mein Diener Hyrum nicht kommen können;"},{"verse":18,"text":"denn auf sie habe ich für eine kurze Zeit die Bürde aller Gemeinden gelegt."},{"verse":19,"text":"Darum, wohin auch immer sie dich senden werden, da gehe hin, und ich werde mit dir sein; und an welchem Ort auch immer du meinen Namen verkündigen wirst, da wird sich dir eine wirksame Tür öffnen, damit sie mein Wort empfangen können."},{"verse":20,"text":"Wer auch immer mein Wort empfängt, der empfängt mich, und wer auch immer mich empfängt, der empfängt jene, die Erste Präsidentschaft, die ich gesandt habe und die ich um meines Namens willen zu Ratgebern für euch gemacht habe."},{"verse":21,"text":"Und weiter, ich sage dir: Wer auch immer in meinem Namen von euch ausgesandt werden wird, durch die Stimme deiner Brüder, der Zwölf, von euch ordnungsgemäß empfohlen und ermächtigt, wird die Macht haben, die Tür meines Reiches einer jeden Nation zu öffnen, wohin auch immer ihr sie senden werdet –"},{"verse":22,"text":"insoweit sie sich vor mir demütigen und in meinem Wort verbleiben und auf die Stimme meines Geistes hören."},{"verse":23,"text":"Wahrlich, wahrlich, ich sage euch: Finsternis bedeckt die Erde und tiefe Finsternis den Sinn der Völker, und alles Fleisch ist vor meinem Angesicht verdorben geworden."},{"verse":24,"text":"Siehe, Vergeltung kommt schnell über die Bewohner der Erde, ein Tag des Grimms, ein Tag des Brennens, ein Tag der Verwüstung, des Weinens, des Trauerns und des Klagens; und wie ein Wirbelsturm wird er über die ganze Erde kommen, spricht der Herr."},{"verse":25,"text":"Und an meinem Haus wird es anfangen, und von meinem Haus wird es ausgehen, spricht der Herr;"},{"verse":26,"text":"zuerst bei denen von euch, spricht der Herr, die bekannt haben, meinen Namen zu kennen, aber mich nicht gekannt haben und mitten in meinem Haus gegen mich gelästert haben, spricht der Herr."},{"verse":27,"text":"Darum seht zu, dass ihr euch wegen der Angelegenheiten meiner Kirche an diesem Ort nicht beunruhigt, spricht der Herr."},{"verse":28,"text":"Sondern macht euer Herz vor mir rein; und dann geht hin in alle Welt, und predigt mein Evangelium jedem Geschöpf, das es noch nicht empfangen hat;"},{"verse":29,"text":"und wer da glaubt und sich taufen lässt, der wird errettet werden, und wer da nicht glaubt und sich nicht taufen lässt, der wird verdammt werden."},{"verse":30,"text":"Denn euch, den Zwölf, und jenen, der Ersten Präsidentschaft, die mit euch bestimmt worden sind, dass sie eure Ratgeber und eure Führer seien, ist die Macht dieses Priestertums gegeben, für die letzten Tage und für die letzte Zeit, worin die Evangeliumszeit der Fülle der Zeiten ist."},{"verse":31,"text":"Und diese Macht habt ihr zusammen mit all denen inne, die irgendwann, vom Anfang der Schöpfung an, eine Evangeliumszeit empfangen haben."},{"verse":32,"text":"Denn wahrlich, ich sage euch: Die Schlüssel der Evangeliumszeit, die ihr empfangen habt, sind von den Vätern herabgekommen und zuletzt vom Himmel auf euch herabgesandt worden."},{"verse":33,"text":"Wahrlich, ich sage euch: Siehe, wie groß ist eure Berufung. Säubert euer Herz und euer Gewand, damit nicht das Blut dieser Generation von euren Händen gefordert wird."},{"verse":34,"text":"Seid treu, bis ich komme, denn ich komme schnell; und mein Lohn kommt mit mir, um jedem Menschen gemäß dem zu vergelten, wie seine Werke sein werden. Ich bin Alpha und Omega. Amen."}]},{"chapter":113,"verses":[{"verse":1,"text":"Wer ist der Stamm Isais, wovon im 11. Kapitel des Jesaja, Vers 1, 2, 3, 4 und 5 die Rede ist?"},{"verse":2,"text":"Wahrlich, so spricht der Herr: Es ist Christus."},{"verse":3,"text":"Was ist das Reis, wovon im 11. Kapitel des Jesaja, Vers 1, die Rede ist und das aus dem Stamm Isais hervorgehen soll?"},{"verse":4,"text":"Siehe, so spricht der Herr: Das ist ein Diener in den Händen Christi, der sowohl ein Abkömmling Isais als auch Efraims ist, oder aus dem Haus Josef, und auf den viel Macht gelegt worden ist."},{"verse":5,"text":"Was ist die Wurzel Isais, von der im Vers 10 des 11. Kapitels die Rede ist?"},{"verse":6,"text":"Siehe, so spricht der Herr: Das ist ein Abkömmling sowohl Isais als auch Josefs, dem das Priestertum und die Schlüssel des Reiches zu Recht gehören, als ein Panier und zur Sammlung meines Volkes in den letzten Tagen."},{"verse":7,"text":"Fragen von Elias Higbee: Was bedeutet der Befehl im 52. Kapitel von Jesaja, Vers 1, wo es heißt: O Zion, zieh an deine Stärke – und auf welches Volk nahm Jesaja Bezug?"},{"verse":8,"text":"Er nahm Bezug auf diejenigen, die Gott in den letzten Tagen berufen würde und die die Macht des Priestertums innehaben würden, um Zion wiederzubringen und zur Erlösung Israels; und seine Stärke anziehen heißt, die Vollmacht des Priestertums anzulegen, worauf es, Zion, kraft Abstammungslinie ein Recht hat, und auch, wieder zu der Macht zu gelangen, die ihm verlorengegangen war."},{"verse":9,"text":"Was sollen wir darunter verstehen, dass Zion sich von den Fesseln seines Halses losmachen soll (Vers 2)?"},{"verse":10,"text":"Wir sollen darunter verstehen, dass die zerstreuten Überreste ermahnt werden, zum Herrn zurückzukehren, von dem sie abgefallen sind; wenn sie das tun, so verheißt ihnen der Herr, dass er zu ihnen sprechen oder ihnen Offenbarung geben wird. Siehe Vers 6, 7 und 8. Die Fesseln seines Halses sind die Flüche Gottes auf ihm oder die Überreste Israels in ihrem zerstreuten Zustand unter den Anderen."}]},{"chapter":114,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr: Es ist weise, wenn mein Diener David W. Patten seine gesamten Geschäfte so bald wie möglich abschließt und seinen Warenbestand veräußert, damit er im nächsten Frühjahr zusammen mit anderen, ja, zwölf, er selbst mit eingeschlossen, für mich eine Mission erfüllen kann, um meinen Namen zu bezeugen und aller Welt frohe Nachricht zu bringen."},{"verse":2,"text":"Denn wahrlich, so spricht der Herr: Falls es unter euch welche gibt, die meinen Namen verleugnen, sollen andere an deren Stelle gesetzt werden und deren Bischofsamt empfangen. Amen."}]},{"chapter":115,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr zu euch, mein Diener Joseph Smith Jr. und auch mein Diener Sidney Rigdon und auch mein Diener Hyrum Smith, und zu deinen Ratgebern, die schon bestimmt sind und später noch bestimmt werden sollen,"},{"verse":2,"text":"und auch zu dir, mein Diener Edward Partridge, und zu seinen Ratgebern"},{"verse":3,"text":"und auch zu meinen treuen Dienern, die den Hoherat meiner Kirche in Zion bilden, denn so soll er genannt werden, und zu allen Ältesten und allem Volk meiner Kirche Jesu Christi der Heiligen der Letzten Tage, die über die ganze Welt zerstreut sind,"},{"verse":4,"text":"denn so soll meine Kirche in den letzten Tagen genannt werden, nämlich: Kirche Jesu Christi der Heiligen der Letzten Tage."},{"verse":5,"text":"Wahrlich, ich sage euch allen: Erhebt euch und lasst euer Licht leuchten, damit es den Nationen ein Banner sei"},{"verse":6,"text":"und damit die Sammlung im Land Zion und in seinen Pfählen Schutz bewirke und eine Zuflucht sei vor dem Sturm und vor dem Grimm, wenn diese unvermischt über die ganze Erde ausgegossen werden."},{"verse":7,"text":"Lasst die Stadt Far West mir ein heiliges und geweihtes Land sein; und sie soll höchst heilig genannt werden, denn der Boden, darauf du stehst, ist heilig."},{"verse":8,"text":"Darum gebiete ich euch, mir ein Haus zu bauen, zur Sammlung meiner Heiligen, damit sie mich anbeten können."},{"verse":9,"text":"Und es soll in diesem kommenden Sommer einen Anfang dieser Arbeit geben und die Grundlegung und die vorbereitenden Arbeiten,"},{"verse":10,"text":"und der Anfang soll am vierten Tag des nächsten Julis gemacht werden; und von der Zeit an soll mein Volk eifrig arbeiten, um meinem Namen ein Haus zu bauen;"},{"verse":11,"text":"und von diesem Tag an in einem Jahr soll es abermals beginnen und das Fundament meines Hauses errichten."},{"verse":12,"text":"So lasst es also von der Zeit an eifrig arbeiten, bis es fertig ist, vom Eckstein bis zur Spitze, bis nichts mehr da ist, was unfertig ist."},{"verse":13,"text":"Wahrlich, ich sage euch: Lasst weder meinen Diener Joseph noch meinen Diener Sidney noch meinen Diener Hyrum weiterhin deshalb in Schulden geraten, weil meinem Namen ein Haus gebaut werden soll;"},{"verse":14,"text":"sondern lasst meinem Namen ein Haus bauen gemäß dem Muster, das ich ihnen zeigen werde."},{"verse":15,"text":"Und wenn mein Volk es nicht gemäß dem Muster baut, das ich seiner Präsidentschaft zeigen werde, so werde ich es nicht aus seinen Händen annehmen."},{"verse":16,"text":"Wenn mein Volk es aber gemäß dem Muster baut, das ich seiner Präsidentschaft zeigen werde, nämlich meinem Diener Joseph und seinen Ratgebern, so werde ich es aus den Händen meines Volkes annehmen."},{"verse":17,"text":"Und weiter, wahrlich, ich sage euch: Es ist mein Wille, dass die Stadt Far West durch die Sammlung meiner Heiligen schnell aufgebaut werde,"},{"verse":18,"text":"und auch, dass andere Orte in den Gebieten ringsum als Pfähle bestimmt werden, wie sie meinem Diener Joseph von Zeit zu Zeit kundgetan werden."},{"verse":19,"text":"Denn siehe, ich werde mit ihm sein, und ich werde ihn vor dem Volk heiligen; denn ihm habe ich die Schlüssel dieses Reiches und geistlichen Dienstes gegeben. So ist es. Amen."}]},{"chapter":116,"verses":[{"verse":1,"text":"Der Herr aber bezeichnete Spring Hill als Adam-ondi-Ahman, weil, wie er sagte, das der Ort ist, wohin Adam kommen wird, um sein Volk aufzusuchen, oder wo der Alte der Tage sitzen wird, wie davon beim Propheten Daniel die Rede ist."}]},{"chapter":117,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr zu meinem Diener William Marks und auch zu meinem Diener Newel K. Whitney: Sie sollen ihre Geschäfte schnell abschließen und aus dem Land Kirtland abreisen, ehe ich, der Herr, wiederum den Schnee auf die Erde sende."},{"verse":2,"text":"Sie sollen erwachen und sich erheben und hervorkommen und sich nicht verweilen, denn ich, der Herr, gebiete es."},{"verse":3,"text":"Darum, wenn sie sich verweilen, wird es ihnen nicht wohl ergehen."},{"verse":4,"text":"Sie sollen von all ihren Sünden und von all ihren habgierigen Wünschen vor mir umkehren, spricht der Herr; denn was bedeutet mir Besitztum?, spricht der Herr."},{"verse":5,"text":"Lasst die Besitztümer in Kirtland für die Schulden herausgegeben werden, spricht der Herr. Lasst sie fahren, spricht der Herr, und was auch immer übrigbleibt, das soll in euren Händen bleiben, spricht der Herr."},{"verse":6,"text":"Denn gehören mir nicht die Vögel des Himmels und auch die Fische des Meeres und die Tiere der Berge? Habe ich nicht die Erde gemacht? Halte ich nicht das Geschick aller Heere der Nationen der Erde?"},{"verse":7,"text":"Darum: Werde ich nicht dürres Land zum Knospen und zum Blühen bringen und es im Überfluss hervorbringen lassen?, spricht der Herr."},{"verse":8,"text":"Gibt es denn nicht Raum genug auf den Bergen von Adam-ondi-Ahman und auf der Ebene von Olaha Schineha, oder dem Land, wo Adam wohnte, dass ihr das begehren müsstet, was nur ein Tropfen ist, und dabei das Wichtigere vernachlässigt?"},{"verse":9,"text":"Darum kommt hier herauf in das Land meines Volkes, nämlich Zion."},{"verse":10,"text":"Mein Diener William Marks soll über wenigem treu sein, dann wird er Herrscher sein über vieles. Lasst ihn inmitten meines Volkes in der Stadt Far West präsidieren, und lasst ihn mit den Segnungen meines Volkes gesegnet sein."},{"verse":11,"text":"Mein Diener Newel K. Whitney soll sich der Bande der Nikolaiten und all ihrer geheimen Gräuel und all seiner Kleinlichkeit der Seele vor mir schämen, spricht der Herr, und er soll in das Land Adam-ondi-Ahman heraufkommen und ein Bischof für mein Volk sein, spricht der Herr, nicht dem Namen nach, sondern in der Tat, spricht der Herr."},{"verse":12,"text":"Und weiter, ich sage euch: Ich gedenke meines Dieners Oliver Granger; siehe, wahrlich, ich sage ihm: Sein Name wird von Generation zu Generation in heiligem Andenken gehalten werden für immer und immer, spricht der Herr."},{"verse":13,"text":"Darum soll er ernstlich für die Erlösung der Ersten Präsidentschaft meiner Kirche kämpfen, spricht der Herr; und wenn er fällt, so wird er sich wieder erheben, denn sein Opfer wird mir heiliger sein als sein Zuwachs, spricht der Herr."},{"verse":14,"text":"Darum soll er schnell hier heraufkommen in das Land Zion; und zu gegebener Zeit wird er zu einem Kaufmann für meinen Namen gemacht werden, spricht der Herr, zum Nutzen meines Volkes."},{"verse":15,"text":"Darum lasst niemanden meinen Diener Oliver Granger verachten, sondern lasst die Segnungen meines Volkes auf ihm sein für immer und immer."},{"verse":16,"text":"Und weiter, wahrlich, ich sage euch: Alle meine Diener im Land Kirtland sollen des Herrn, ihres Gottes, und auch meines Hauses gedenken, dass sie es heilighalten und bewahren und zu der von mir selbst bestimmten Zeit die Geldwechsler umstoßen, spricht der Herr. So ist es. Amen."}]},{"chapter":118,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr: Lasst unverzüglich eine Konferenz abhalten; lasst die Zwölf sich organisieren, und lasst Männer bestimmt werden, den Platz derer einzunehmen, die gefallen sind."},{"verse":2,"text":"Lasst meinen Diener Thomas eine Zeit lang im Land Zion bleiben, um mein Wort zu veröffentlichen."},{"verse":3,"text":"Lasst die Übrigen von jener Stunde an weiter predigen, und wenn sie dies mit aller Bescheidenheit des Herzens, mit Sanftmut und Demut und Langmut tun, so gebe ich, der Herr, ihnen die Verheißung, dass ich für ihre Familien sorgen werde; und eine wirksame Tür wird sich ihnen hinfort öffnen."},{"verse":4,"text":"Und lasst sie im nächsten Frühjahr abreisen und sich über die großen Wasser begeben und dort mein Evangelium verbreiten, ja, seine Fülle, und für meinen Namen Zeugnis geben."},{"verse":5,"text":"Lasst sie sich am sechsundzwanzigsten Tag des nächsten Aprils von meinen Heiligen in der Stadt Far West verabschieden, und zwar auf dem Bauplatz meines Hauses, spricht der Herr."},{"verse":6,"text":"Lasst meinen Diener John Taylor und auch meinen Diener John E. Page und auch meinen Diener Wilford Woodruff und auch meinen Diener Willard Richards bestimmt werden, die Stelle derer zu besetzen, die gefallen sind, und von ihrer Berufung offiziell verständigt werden."}]},{"chapter":119,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr: Ich verlange, dass all ihr überschüssiges Eigentum dem Bischof meiner Kirche in Zion in die Hände gelegt werde –"},{"verse":2,"text":"für den Bau meines Hauses und um die Grundlage zu legen für Zion und für das Priestertum und für die Schulden der Präsidentschaft meiner Kirche."},{"verse":3,"text":"Und das soll der Anfang des Zehntens meines Volkes sein."},{"verse":4,"text":"Und danach sollen diejenigen, die so gezehntet worden sind, jährlich ein Zehntel all ihres Ertrags bezahlen; und das soll für sie, für mein heiliges Priestertum, ein feststehendes Gesetz sein immerdar, spricht der Herr."},{"verse":5,"text":"Wahrlich, ich sage euch: Es wird sich begeben: Alle, die sich im Land Zion sammeln, sollen sich um ihr überschüssiges Eigentum zehnten lassen und sollen dieses Gesetz befolgen, sonst werden sie nicht für würdig befunden werden, bei euch zu bleiben."},{"verse":6,"text":"Und ich sage euch: Wenn mein Volk dieses Gesetz nicht befolgt, dass es es heilighält, und mir nicht das Land Zion durch dieses Gesetz heiligt, auf dass dort meine Satzungen und meine Richtersprüche gehalten werden, damit es höchst heilig sei, siehe, wahrlich, ich sage euch: Dann wird es für euch kein Land Zion sein."},{"verse":7,"text":"Und dies soll für alle Zionspfähle ein Beispiel sein. So ist es. Amen."}]},{"chapter":120,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr: Die Zeit ist nun gekommen, dass darüber durch einen Rat verfügt werden soll, der sich aus der Ersten Präsidentschaft meiner Kirche und aus dem Bischof und seinem Rat und aus meinem Hoherat zusammensetzt; und durch meine eigene Stimme an sie, spricht der Herr. So ist es. Amen."}]},{"chapter":121,"verses":[{"verse":1,"text":"O Gott, wo bist du? Und wo ist das Gezelt, das dein Versteck bedeckt?"},{"verse":2,"text":"Wie lange noch wird deine Hand sich zurückhalten und dein Auge, ja, dein reines Auge, von den ewigen Himmeln her das Unrecht ansehen, das deinem Volk und deinen Dienern widerfährt, und dein Ohr von ihrem Schreien durchdrungen werden?"},{"verse":3,"text":"Ja, o Herr, wie lange noch sollen sie dieses Unrecht und diese gesetzwidrige Unterdrückung erleiden, ehe dein Herz sich für sie erweichen lässt und dein Inneres von Mitleid mit ihnen bewegt sein wird?"},{"verse":4,"text":"O Herr, allmächtiger Gott, der du den Himmel, die Erde und die Meere und alles, was darinnen ist, gemacht hast, der du den Teufel beherrschst und unterwirfst, ihn und die finstere, in Nacht gehüllte Herrschaft von Scheol – strecke deine Hand aus, lass dein Auge durchdringen, lass dein Gezelt sich heben, lass dein Versteck nicht länger bedeckt sein, lass dein Ohr sich neigen, lass dein Herz sich erweichen und dein Inneres von Mitleid mit uns bewegt sein!"},{"verse":5,"text":"Lass deinen Zorn sich gegen unsere Feinde entzünden, und im Ungestüm deines Herzens räche das uns angetane Unrecht mit deinem Schwert!"},{"verse":6,"text":"Gedenke deiner Heiligen, die leiden, o unser Gott; dann werden deine Diener immerdar an deinem Namen Freude haben!"},{"verse":7,"text":"Mein Sohn, Friede sei deiner Seele; dein Ungemach und deine Bedrängnisse werden nur einen kleinen Augenblick dauern,"},{"verse":8,"text":"und dann, wenn du gut darin ausharrst, wird Gott dich in der Höhe erhöhen; du wirst über alle deine Feinde triumphieren."},{"verse":9,"text":"Deine Freunde stehen doch zu dir, und sie werden dich wieder willkommen heißen, mit warmem Herzen und freundlicher Hand."},{"verse":10,"text":"Noch bist du nicht wie Ijob, deine Freunde streiten nicht gegen dich und beschuldigen dich nicht der Übertretung, wie sie es mit Ijob getan haben."},{"verse":11,"text":"Und die dich der Übertretung beschuldigen, deren Hoffnung wird versengt werden, und ihre Erwartungen werden dahinschmelzen, wie der Raureif vor den sengenden Strahlen der aufgehenden Sonne schmilzt;"},{"verse":12,"text":"und auch, dass Gott seine Hand und sein Siegel gesetzt hat, die Zeiten und Jahreszeiten zu ändern und ihnen den Sinn zu verblenden, damit sie sein wunderbares Wirken nicht verstehen, damit er sie auch prüfen und in ihrer eigenen Hinterlist fassen kann;"},{"verse":13,"text":"auch weil ihr Herz verdorben ist, und all das, was sie über andere bringen und andere gern erleiden lassen wollen, bis zum Allerletzten über sie selbst kommen mag;"},{"verse":14,"text":"damit sie auch enttäuscht werden mögen und ihre Hoffnungen ausgelöscht werden mögen"},{"verse":15,"text":"und dass sie und ihre Nachkommen in nicht vielen Jahren von nun an von unter dem Himmel hinweggefegt werden, spricht Gott, sodass auch nicht einer übrigbleibt, an der Mauer zu stehen."},{"verse":16,"text":"Verflucht sind alle, die die Ferse gegen meine Gesalbten heben, spricht der Herr, und schreien, sie hätten gesündigt, wenn sie vor mir nicht gesündigt haben, spricht der Herr, sondern das getan haben, was in meinen Augen recht war und was ich ihnen geboten hatte."},{"verse":17,"text":"Aber diejenigen, die Übertretung schreien, tun es, weil sie selbst Diener der Sünde und Kinder des Ungehorsams sind."},{"verse":18,"text":"Und diejenigen, die fälschlich gegen meine Diener schwören, um sie in Gefangenschaft und zum Tode zu bringen –"},{"verse":19,"text":"weh ihnen; weil sie meinen Kleinen Unrecht getan haben, werden sie von den Verordnungen meines Hauses ausgeschlossen werden."},{"verse":20,"text":"Ihr Korb wird nicht voll sein, ihre Häuser und ihre Scheunen werden verfallen, und sie selbst werden von denen verachtet werden, die ihnen geschmeichelt haben."},{"verse":21,"text":"Sie werden kein Anrecht auf das Priestertum haben, auch nicht ihre Nachkommenschaft nach ihnen, von Generation zu Generation."},{"verse":22,"text":"Es wäre besser für sie gewesen, man hätte ihnen einen Mühlstein um den Hals gehängt und sie wären in der Tiefe des Meeres ertrunken."},{"verse":23,"text":"Weh all denen, die mein Volk quälen und es verjagen und ermorden und gegen es aussagen, spricht der Herr der Heerscharen; die Schlangenbrut wird der Verdammnis der Hölle nicht entrinnen."},{"verse":24,"text":"Siehe, meine Augen sehen und kennen alle ihre Werke, und ich habe für sie alle ein rasches Strafgericht bereit, wenn es an der Zeit ist;"},{"verse":25,"text":"denn für einen jeden Menschen ist eine Zeit bestimmt, je nachdem, wie seine Werke sein werden."},{"verse":26,"text":"Gott wird euch durch seinen Heiligen Geist, ja, durch die unaussprechliche Gabe des Heiligen Geistes, Erkenntnis geben, die vom Anfang der Welt an bis heute nicht offenbart worden ist,"},{"verse":27,"text":"wovon unsere Vorväter voll Erwartung gehofft haben, sie werde in den letzten Zeiten offenbart werden, worauf ihnen die Engel den Sinn gelenkt haben, da sie für die Fülle ihrer Herrlichkeit zurückbehalten worden war;"},{"verse":28,"text":"eine kommende Zeit, da nichts vorenthalten werden wird, sei es, dass es einen Gott gebe oder viele Götter – sie werden kundgetan werden."},{"verse":29,"text":"Alle Throne und Königreiche, Fürstentümer und Mächte werden offenbart und all denen anheimgegeben werden, die um des Evangeliums Jesu Christi willen tapfer ausgeharrt haben."},{"verse":30,"text":"Und auch, welcherlei Grenzen den Himmeln oder den Meeren oder dem trockenen Land oder der Sonne, dem Mond oder den Sternen gesetzt sind –"},{"verse":31,"text":"alle ihre Umlaufzeiten, alle bestimmten Tage, Monate und Jahre und alle Tage ihrer Tage, Monate und Jahre sowie alle ihre Herrlichkeiten, Gesetze und festgesetzten Zeiten, werden in den Tagen der Evangeliumszeit der Fülle der Zeiten offenbart werden –"},{"verse":32,"text":"gemäß dem, was inmitten des Rates des ewigen Gottes aller anderen Götter verordnet wurde, ehe diese Welt war, dass es bis zu ihrer Vollendung und zu ihrem Ende zurückbehalten werde, wenn dann jeder Mensch in seine ewige Gegenwart und in seine unsterbliche Ruhe eingehen wird."},{"verse":33,"text":"Wie lange kann ein fließendes Wasser unrein bleiben? Was für eine Macht soll den Himmeln Einhalt gebieten? Ebenso gut könnte der Mensch seinen schwachen Arm ausstrecken, um den Missouri in seinem vorgezeichneten Lauf anzuhalten oder ihn stromauf zu wenden, wie den Allmächtigen daran hindern, vom Himmel herab Erkenntnis auf das Haupt der Heiligen der Letzten Tage auszugießen."},{"verse":34,"text":"Siehe, viele gibt es, die berufen sind, aber wenige werden erwählt. Und warum werden sie nicht erwählt?"},{"verse":35,"text":"Weil sie ihr Herz so sehr auf die Dinge dieser Welt gesetzt haben und nach den Ehren der Menschen streben, dass sie diese eine Lehre nicht lernen:"},{"verse":36,"text":"dass die Rechte des Priestertums untrennbar mit den Mächten des Himmels verbunden sind und dass die Mächte des Himmels nur nach den Grundsätzen der Rechtschaffenheit beherrscht und gebraucht werden können."},{"verse":37,"text":"Dass sie uns übertragen werden können, das ist wahr; aber wenn wir versuchen, unsere Sünden zu verdecken oder unseren Stolz und eitlen Ehrgeiz zu befriedigen, oder wenn wir auch nur mit dem geringsten Maß von Unrecht irgendwelche Gewalt oder Herrschaft oder Nötigung auf die Seele der Menschenkinder ausüben wollen – siehe, dann ziehen sich die Himmel zurück, der Geist des Herrn ist betrübt, und wenn er sich zurückgezogen hat, dann Amen zum Priestertum oder der Vollmacht jenes Mannes."},{"verse":38,"text":"Siehe, ehe er es gewahr wird, ist er sich selbst überlassen, gegen den Stachel auszuschlagen, die Heiligen zu verfolgen und gegen Gott zu streiten."},{"verse":39,"text":"Traurige Erfahrung hat uns gelehrt: Fast jedermann neigt von Natur aus dazu, sogleich mit dem Ausüben ungerechter Herrschaft anzufangen, sobald er meint, ein wenig Vollmacht erhalten zu haben."},{"verse":40,"text":"Daher sind zwar viele berufen, werden aber wenige erwählt."},{"verse":41,"text":"Kraft des Priestertums kann und soll keine Macht und kein Einfluss anders geltend gemacht werden als nur mit überzeugender Rede, mit Langmut, mit Milde und Sanftmut und mit ungeheuchelter Liebe,"},{"verse":42,"text":"mit Wohlwollen und mit reiner Erkenntnis, wodurch sich die Seele sehr erweitert, ohne Heuchelei und ohne Falschheit –"},{"verse":43,"text":"zur rechten Zeit mit aller Deutlichkeit zurechtweisend, wenn vom Heiligen Geist dazu bewogen; und danach demjenigen, den du zurechtgewiesen hast, vermehrte Liebe erweisend, damit er nicht meint, du seiest sein Feind,"},{"verse":44,"text":"damit er weiß, dass deine Treue stärker ist als die Fesseln des Todes."},{"verse":45,"text":"Lass dein Inneres auch erfüllt sein von Nächstenliebe zu allen Menschen und zum Haushalt des Glaubens, und lass Tugend immerfort deine Gedanken zieren; dann wird dein Vertrauen in der Gegenwart Gottes stark werden, und die Lehre des Priestertums wird dir auf die Seele niederträufeln wie der Tau vom Himmel."},{"verse":46,"text":"Der Heilige Geist wird dein ständiger Begleiter sein und dein Zepter ein unwandelbares Zepter der Rechtschaffenheit und Wahrheit, und deine Herrschaft wird eine immerwährende Herrschaft sein, und ohne Nötigung wird sie dir zufließen für immer und immer."}]},{"chapter":122,"verses":[{"verse":1,"text":"Die Enden der Erde werden sich nach deinem Namen erkundigen, und Narren werden dich verspotten, und die Hölle wird gegen dich wüten,"},{"verse":2,"text":"während die im Herzen Reinen und die Weisen und die Edlen und die Tugendhaften beständig nach Rat und Vollmacht und Segnungen unter deinen Händen trachten werden."},{"verse":3,"text":"Und dein Volk wird sich niemals auf das Zeugnis von Verrätern hin gegen dich wenden."},{"verse":4,"text":"Und wenn auch ihr Einfluss dich in Ungelegenheiten und hinter Gitter und Mauern bringen wird, wirst du doch in Ehren gehalten werden, und nur noch einen kleinen Augenblick, dann wird deine Stimme inmitten deiner Feinde schrecklicher sein als ein wilder Löwe, wegen deiner Rechtschaffenheit; und dein Gott wird zu dir stehen für immer und immer."},{"verse":5,"text":"Wenn von dir gefordert wird, Drangsal durchzumachen, wenn du unter falschen Brüdern in Gefahr bist, wenn du unter Räubern in Gefahr bist, wenn du auf dem Land oder Meer in Gefahr bist,"},{"verse":6,"text":"wenn du mit falschen Beschuldigungen aller Art beschuldigt wirst, wenn deine Feinde über dich herfallen, wenn sie dich aus der Gesellschaft deines Vaters und deiner Mutter und deiner Brüder und Schwestern wegreißen und wenn deine Feinde dich mit gezücktem Schwert vom Herzen deiner Frau und deiner Kinder wegreißen und dein ältester Sohn, obwohl erst sechs Jahre alt, sich an deine Kleider klammert und sagt: Mein Vater, mein Vater, warum kannst du nicht bei uns bleiben? O mein Vater, was werden die Männer mit dir tun?, und wenn er dann mit dem Schwert von dir weggestoßen wird und du ins Gefängnis geschleppt wirst und deine Feinde dich umschleichen wie Wölfe, die auf das Blut des Lammes aus sind,"},{"verse":7,"text":"und wenn du in die Grube geworfen werden oder Mördern in die Hände fallen solltest und das Todesurteil über dich gesprochen werden sollte, wenn du in die Tiefe gestürzt wirst, wenn die brausende See sich gegen dich verschwört, wenn wütende Winde deine Feinde werden, wenn sich am Himmel Finsternis zusammenzieht und alle Elemente sich verbünden, um den Weg zu versperren, und, vor allem, wenn die Hölle selbst ihren Rachen weit aufreißt nach dir, dann wisse, mein Sohn, dass dies alles dir Erfahrung bringen und dir zum Guten dienen wird."},{"verse":8,"text":"Des Menschen Sohn ist unter das alles hinabgefahren. Bist du größer als er?"},{"verse":9,"text":"Darum halte an deinem Weg fest, und das Priestertum wird bei dir verbleiben; denn ihre Grenzen sind festgesetzt, sie können nicht darüber hinaus. Deine Tage sind bekannt, und deinen Jahren wird nichts abgerechnet werden; darum fürchte nicht, was Menschen tun können, denn Gott wird mit dir sein für immer und immer."}]},{"chapter":123,"verses":[{"verse":1,"text":"Und weiter möchten wir euch zu bedenken geben, dass es angebracht wäre, wenn alle Heiligen die Berichte über alle Tatsachen sowie die Leiden und Misshandlungen sammelten, die vom Volk dieses Staates über sie gebracht worden sind,"},{"verse":2,"text":"ebenso von allem Eigentum und dem Umfang des Schadens, den sie erlitten haben, sowohl in ihrem Leumund als auch an persönlicher Unbill und auch an unbeweglichem Eigentum,"},{"verse":3,"text":"und auch die Namen aller Personen, die bei ihrer Unterdrückung Hand angelegt hatten, soweit sie sie feststellen und herausfinden können."},{"verse":4,"text":"Und vielleicht kann ein Komitee bestimmt werden, das dies alles herausfinden kann und das Aussagen und eidesstattliche Erklärungen aufnimmt und auch die verleumderischen Veröffentlichungen sammelt, die im Umlauf sind,"},{"verse":5,"text":"dazu alles, was davon in Zeitschriften und in Nachschlagewerken zu finden ist, sowie alle verleumderischen Geschichten, die veröffentlicht sind oder eben geschrieben werden, und von wem, und das die ganze Verkettung von teuflischer Schurkerei und ruchlosen und mörderischen Gewalttaten, die an diesem Volk verübt worden sind, darlegt –"},{"verse":6,"text":"damit wir sie nicht nur aller Welt bekanntmachen, sondern sie in all ihrer finsteren und höllischen Schattierung den Spitzen der Regierung vorlegen können, als die letzte Anstrengung, die uns von unserem himmlischen Vater auferlegt wird, ehe wir die Verheißung voll und ganz in Anspruch nehmen können, die ihn aus seinem Versteck herausruft, und auch damit die ganze Nation ohne Entschuldigung sei, ehe er die Macht seines mächtigen Armes aussenden kann."},{"verse":7,"text":"Es ist dies eine zwingende Pflicht, die wir Gott, den Engeln, bei denen wir einst stehen werden, und auch uns selbst, unseren Frauen und Kindern schulden, denn diese mussten sich voll Kummer, Trauer und Sorge unter die verdammenswürdigste Hand von Mord, Tyrannei und Unterdrückung beugen, die ihrerseits vom Einfluss des gleichen Geistes gestützt, angespornt und aufrechterhalten wird, der die Glaubensbekenntnisse der Väter, die Lügen ererbt haben, so stark im Herzen der Kinder hat einwurzeln lassen und der die Welt mit Verwirrung erfüllt hat und stärker und stärker geworden ist und jetzt die wahrhaftige Haupttriebfeder aller Verdorbenheit ist, und die ganze Erde stöhnt unter der Last seines Übeltuns."},{"verse":8,"text":"Es ist ein eisernes Joch, es ist ein starkes Band, es sind wahrhaftig die Handschellen und Ketten und Fußeisen und Fesseln der Hölle."},{"verse":9,"text":"Darum ist dies eine zwingende Pflicht, die wir nicht nur unseren eigenen Frauen und Kindern schulden, sondern auch den Witwen und Vaterlosen, deren Männer und Väter unter seiner eisernen Hand ermordet worden sind,"},{"verse":10,"text":"und diese finsteren und schwarzen Taten reichen hin, selbst die Hölle schaudern zu lassen, sodass sie entsetzt und bleich dasteht und die Hände selbst des Teufels zittern und erlahmen."},{"verse":11,"text":"Ebenso ist dies eine zwingende Pflicht, die wir der gesamten heranwachsenden Generation und allen im Herzen Reinen schulden –"},{"verse":12,"text":"denn es gibt unter allen Glaubensgemeinschaften, Parteien und Konfessionen noch immer viele auf Erden, die von der verschlagenen Hinterlist der Menschen, die auf der Lauer liegen, um zu täuschen, verblendet sind und denen die Wahrheit nur deshalb vorenthalten ist, weil sie nicht wissen, wo sie zu finden ist –,"},{"verse":13,"text":"darum müssen wir unser Leben damit aufbrauchen und abnutzen, dass wir alles Verborgene der Finsternis ans Licht bringen, wo wir solches erkennen, und es ist uns wahrhaftig vom Himmel her kundgetan –"},{"verse":14,"text":"dem also müssen wir uns mit großer Ernsthaftigkeit widmen."},{"verse":15,"text":"Niemand soll das für eine Kleinigkeit halten; denn es gibt vieles, was in der Zukunft liegt, was die Heiligen betrifft und was von dem allen abhängt."},{"verse":16,"text":"Ihr wisst, Brüder, dass ein ganz kleines Steuer einem sehr großen Schiff in Zeiten des Sturms sehr viel zu nutzen vermag, wenn es dem Wind und den Wellen zum Trotz auf Kurs gehalten wird."},{"verse":17,"text":"Darum, vielgeliebte Brüder, lasst uns frohgemut alles tun, was in unserer Macht liegt, und dann mögen wir mit größter Zuversicht ruhig stehen, um die Errettung Gottes zu sehen und dass sein Arm offenbar werde."}]},{"chapter":124,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr zu dir, mein Diener Joseph Smith: Ich habe Wohlgefallen an deinem Opfer und Bekenntnis, das du dargebracht hast, denn zu diesem Zweck habe ich dich erweckt, damit ich durch das Schwache der Erde meine Weisheit zeigen kann."},{"verse":2,"text":"Deine Gebete sind vor mir annehmbar, und als Antwort darauf sage ich dir: Du bist jetzt dazu berufen, unverzüglich eine feierliche Kundmachung von meinem Evangelium zu erlassen, ebenso von diesem Pfahl, den ich als Eckstein für Zion gesetzt habe und der zu einer Feinheit geglättet werden wird, die der eines Palastes gleichkommt."},{"verse":3,"text":"Diese Kundmachung soll an alle Könige auf der Welt ergehen, an die vier Ecken davon, an den ehrenwerten neugewählten Präsidenten sowie die hochgesinnten Gouverneure der Nation, in der du lebst, und an alle Nationen, die über die Erde zerstreut sind."},{"verse":4,"text":"Sie soll im Geist der Sanftmut und durch die Macht des Heiligen Geistes geschrieben werden, der zu der Zeit in dir sein wird, wenn du sie schreibst;"},{"verse":5,"text":"denn es wird dir vom Heiligen Geist gegeben werden, meinen Willen in Bezug auf diese Könige und Autoritäten zu erkennen, ja, was ihnen in künftiger Zeit widerfahren wird."},{"verse":6,"text":"Denn siehe, ich bin im Begriff, sie aufzurufen, dass sie dem Licht und der Herrlichkeit Zions Beachtung schenken, denn die festgesetzte Zeit ist gekommen, da Zion begünstigt werden soll."},{"verse":7,"text":"Rufe ihnen darum mit lauter Kundmachung zu und mit deinem Zeugnis, und fürchte sie nicht, denn sie sind wie Gras und all ihre Herrlichkeit wie dessen Blume, die bald abfällt, damit sie auch ohne Entschuldigung seien –"},{"verse":8,"text":"und damit ich sie am Tag der Heimsuchung heimsuchen kann, wenn ich mein verborgenes Angesicht entschleiern werde, um dem Bedrücker sein Teil bei den Heuchlern zu bestimmen, wo Zähneknirschen ist –, wenn sie meine Diener und mein Zeugnis verwerfen, das ich ihnen offenbart habe."},{"verse":9,"text":"Und weiter, ich werde sie besuchen und ihnen das Herz erweichen, vielen von ihnen, euch zum Nutzen, damit ihr in ihren Augen Gnade findet, damit sie zum Licht der Wahrheit kommen können und die Anderen zur Erhöhung Zions, ja, wenn es emporgehoben wird."},{"verse":10,"text":"Denn der Tag meiner Heimsuchung kommt schnell, zu einer Stunde, da ihr es nicht denkt; und wo wird mein Volk Sicherheit haben und Zuflucht für diejenigen, die davon noch übrig sind?"},{"verse":11,"text":"Erwacht, o ihr Könige der Erde! Kommt, o kommt mit eurem Gold und eurem Silber meinem Volk zu Hilfe, hin zum Haus der Töchter Zions."},{"verse":12,"text":"Und weiter, wahrlich, ich sage dir: Lass meinen Diener Robert B. Thompson dir helfen, diese Kundmachung zu schreiben, denn ich habe Wohlgefallen an ihm und daran, dass er bei dir sei."},{"verse":13,"text":"Darum soll er auf deinen Rat hören, und ich werde ihn mit einer Vielfalt von Segnungen segnen; er soll hinfort in allem treu und wahr sein, dann wird er in meinen Augen groß sein;"},{"verse":14,"text":"aber er soll daran denken, dass ich seine Treuhandschaft aus seinen Händen fordern werde."},{"verse":15,"text":"Und weiter, wahrlich, ich sage dir: Gesegnet ist mein Diener Hyrum Smith; denn ich, der Herr, liebe ihn wegen der Lauterkeit seines Herzens und weil er das liebt, was vor mir recht ist, spricht der Herr."},{"verse":16,"text":"Weiter, lass meinen Diener John C. Bennett dir bei deiner Arbeit helfen, mein Wort zu den Königen und Völkern der Erde zu senden; er soll dir, nämlich dir, meinem Diener Joseph Smith, in der Stunde der Bedrängnis beistehen; und sein Lohn wird nicht ausbleiben, wenn er Rat annimmt."},{"verse":17,"text":"Und wegen seiner Liebe wird er groß sein, denn er wird mein sein, wenn er dies tut, spricht der Herr. Ich habe die Arbeit gesehen, die er getan hat, und ich nehme sie an, wenn er darin fortfährt, und werde ihn mit Segnungen und großer Herrlichkeit krönen."},{"verse":18,"text":"Und weiter, ich sage dir: Es ist mein Wille, dass mein Diener Lyman Wight im Geist der Sanftmut weiterhin für Zion predigt und mich vor der Welt bekennt; und ich werde ihn wie auf Adlerflügeln emportragen, und er wird sich und meinem Namen Herrlichkeit und Ehre erzeugen."},{"verse":19,"text":"Dann kann ich ihn, wenn er seine Arbeit beendet, zu mir nehmen, so wie ich es mit meinem Diener David Patten getan habe, der jetzt bei mir ist, ebenso mein Diener Edward Partridge und auch mein bejahrter Diener Joseph Smith Sr., der bei Abraham zu dessen rechter Hand sitzt; und gesegnet und heilig ist er, denn er ist mein."},{"verse":20,"text":"Und weiter, wahrlich, ich sage dir: Mein Diener George Miller ist ohne Falschheit; ihm kann man wegen der Lauterkeit seines Herzens vertrauen; und um der Liebe willen, die er für mein Zeugnis hat, liebe ich, der Herr, ihn."},{"verse":21,"text":"Darum sage ich dir: Auf sein Haupt siegle ich das Bischofsamt, gleich wie meinem Diener Edward Partridge, damit er die Weihungen meines Hauses in Empfang nehme, damit er den Armen meines Volkes Segnungen auf das Haupt zuteilwerden lasse, spricht der Herr. Niemand soll meinen Diener George verachten, denn er wird mir Ehre machen."},{"verse":22,"text":"Mein Diener George und mein Diener Lyman und mein Diener John Snider und andere sollen meinem Namen ein Haus bauen, und zwar eines, wie mein Diener Joseph es ihnen zeigen wird, auf dem Platz, den er ihnen ebenfalls zeigen wird."},{"verse":23,"text":"Und es soll eine Herberge sein, ein Haus, worin Fremde aus der Ferne unterkommen können; darum soll es ein gutes Haus sein, aller Annahme wert, damit der müde Wanderer sich in Gesundheit und Sicherheit befinde, während er über das Wort des Herrn und den Eckstein nachsinnt, den ich für Zion bestimmt habe."},{"verse":24,"text":"Dieses Haus wird eine gesunde Wohnstätte sein, wenn es meinem Namen erbaut wird und wenn der Verwalter, der dafür bestimmt werden wird, nicht zulässt, dass es verunreinigt wird. Es soll heilig sein, sonst wird der Herr, euer Gott, nicht darin wohnen."},{"verse":25,"text":"Und weiter, wahrlich, ich sage dir: Lass alle meine Heiligen von ferne hierherkommen."},{"verse":26,"text":"Und sendet Eilboten aus, ja, ausgewählte Boten, und sagt ihnen: Kommt mit all eurem Gold und eurem Silber und euren Edelsteinen und mit all euren alten Kostbarkeiten und mit all jenen, die von alten Kostbarkeiten Kenntnis haben – und die kommen wollen, mögen kommen – und bringt Buchsbaum und Tanne und Kiefer und alle kostbaren Bäume der Erde mit;"},{"verse":27,"text":"kommt mit Eisen, mit Kupfer und mit Messing und mit Zink und mit all euren Kostbarkeiten der Erde, und baut meinem Namen ein Haus, dass der Allerhöchste darin wohnen kann."},{"verse":28,"text":"Denn es findet sich kein Ort auf der Erde, wohin er kommen könnte, um euch das wiederherzustellen, was verlorengegangen war oder was er weggenommen hat, nämlich die Fülle des Priestertums."},{"verse":29,"text":"Denn kein Taufbecken gibt es auf der Erde, wo sie, meine Heiligen, für diejenigen getauft werden können, die tot sind –"},{"verse":30,"text":"denn diese Verordnung gehört in mein Haus und kann für mich sonst nicht annehmbar sein, außer in den Tagen eurer Armut, solange ihr nicht imstande seid, mir ein Haus zu bauen."},{"verse":31,"text":"Aber ich gebiete euch, allen meinen Heiligen, mir ein Haus zu bauen; und ich gewähre euch genügend Zeit, mir ein Haus zu bauen; und während dieser Zeit werden eure Taufen für mich annehmbar sein."},{"verse":32,"text":"Aber siehe, wenn diese bestimmte Zeit zu Ende ist, werden eure Taufen für eure Toten für mich nicht mehr annehmbar sein; und wenn ihr dies nicht tut, werdet ihr nach Ablauf der bestimmten Zeit als Kirche samt euren Toten verworfen werden, spricht der Herr, euer Gott."},{"verse":33,"text":"Denn wahrlich, ich sage euch: Nachdem ihr genügend Zeit gehabt habt, mir ein Haus zu bauen, wohin die Verordnung der Taufe für die Toten gehört, und wofür diese schon vor Grundlegung der Welt eingerichtet wurde, können eure Taufen für eure Toten für mich nicht mehr annehmbar sein;"},{"verse":34,"text":"denn darin werden die Schlüssel des heiligen Priestertums ordiniert, damit ihr Ehre und Herrlichkeit empfangen könnt."},{"verse":35,"text":"Und nach dieser Zeit werden eure Taufen für die Toten durch diejenigen, die auswärts zerstreut sind, für mich nicht mehr annehmbar sein, spricht der Herr."},{"verse":36,"text":"Denn es ist verordnet, dass in Zion und in seinen Pfählen und in Jerusalem, jenen Orten, die ich als Zuflucht bestimmt habe, die Stätten für eure Taufen für eure Toten sein sollen."},{"verse":37,"text":"Und weiter, wahrlich, ich sage euch: Wie sollen eure Waschungen für mich annehmbar sein, wenn ihr sie nicht in einem Haus vollzieht, das ihr meinem Namen gebaut habt?"},{"verse":38,"text":"Denn aus diesem Grund habe ich Mose geboten, dass er ein Offenbarungszelt bauen solle, dass sie dieses in der Wildnis mit sich führen sollten und im Land der Verheißung ein Haus bauen, damit jene Verordnungen offenbart werden konnten, die schon verborgen worden waren, ehe die Welt war."},{"verse":39,"text":"Darum, wahrlich, ich sage euch: Eure Salbungen und eure Waschungen und eure Taufen für die Toten und eure feierlichen Versammlungen und eure Gedenkfeiern für eure Opfer durch die Söhne Levi und für eure Aussprüche Gottes an euren höchst heiligen Stätten, worin ihr Mitteilungen empfangt, und eure Satzungen und Richtersprüche für den Anfang der Offenbarungen und die Grundlage Zions und für die Herrlichkeit, Ehre und das Endowment all seiner Bürger sind durch die Verordnung meines heiligen Hauses verordnet, und mein Volk hat allzeit das Gebot, meinem heiligen Namen ein solches Haus zu bauen."},{"verse":40,"text":"Und wahrlich, ich sage euch: Lasst dieses Haus meinem Namen gebaut werden, damit ich darin meinem Volk meine Verordnungen offenbaren kann;"},{"verse":41,"text":"denn es beliebt mir, meiner Kirche zu offenbaren, was von vor der Grundlegung der Welt an verborgen gehalten wurde und was die Evangeliumszeit der Fülle der Zeiten betrifft."},{"verse":42,"text":"Und ich werde meinem Diener Joseph alles zeigen, was dieses Haus betrifft, auch das dazugehörige Priestertum sowie die Stelle, wo es erbaut werden soll."},{"verse":43,"text":"Und ihr sollt es an der Stelle bauen, die ihr für den Bau in Betracht gezogen habt, denn das ist der Platz, den ich ausgewählt habe und wo ihr bauen sollt."},{"verse":44,"text":"Wenn ihr mit all eurer Macht arbeitet, will ich jenen Platz weihen, sodass er geheiligt wird."},{"verse":45,"text":"Und wenn mein Volk auf meine Stimme hören wird, auch auf die Stimme meiner Diener, die ich bestimmt habe, mein Volk zu führen, siehe, wahrlich, so sage ich euch: Es wird nicht von seinem Platz entfernt werden."},{"verse":46,"text":"Wenn es aber nicht auf meine Stimme hören wird, auch nicht auf die Stimme dieser Männer, die ich bestimmt habe, so wird es ohne Segen sein, weil es meinen heiligen Boden und meine heiligen Verordnungen und Satzungen und meine heiligen Worte, die ich ihm gebe, verunreinigt."},{"verse":47,"text":"Und es wird sich begeben: Wenn ihr meinem Namen ein Haus baut, aber das, was ich sage, nicht tut, so werde ich den Eid, den ich euch leiste, nicht vollziehen und auch die Verheißungen, die ihr aus meinen Händen erwartet, nicht erfüllen, spricht der Herr."},{"verse":48,"text":"Denn statt Segnungen bringt ihr dann durch eure eigenen Werke Fluch, Grimm, Unwillen und Richterspruch auf euer eigenes Haupt – durch eure Torheit und durch alle eure Gräuel, die ihr vor mir verübt, spricht der Herr."},{"verse":49,"text":"Wahrlich, wahrlich, ich sage euch: Wenn ich irgendwelchen Söhnen der Menschen das Gebot gebe, meinem Namen ein Werk zu vollbringen, und jene Söhne der Menschen gehen mit all ihrer Macht und mit allem, was sie haben, daran, jenes Werk auszuführen und lassen in ihrem Eifer nicht nach, und ihre Feinde kommen über sie und hindern sie daran, jenes Werk auszuführen, siehe, dann erscheint es mir angebracht, jenes Werk nicht mehr von den Händen jener Söhne der Menschen zu fordern, sondern ihre Opfer anzunehmen."},{"verse":50,"text":"Und das Übeltun und die Übertretung meiner heiligen Gesetze und Gebote werde ich auf dem Haupt derjenigen heimsuchen, die mein Werk behindert haben, bis zur dritten und vierten Generation, solange sie nicht umkehren und mich hassen, spricht Gott, der Herr."},{"verse":51,"text":"Aus diesem Grund also habe ich die Opfer derjenigen angenommen, denen ich geboten habe, meinem Namen im Kreis Jackson, Missouri, eine Stadt und ein Haus zu erbauen, und die von ihren Feinden daran gehindert wurden, spricht der Herr, euer Gott."},{"verse":52,"text":"Und ich werde Richterspruch, Grimm und Unwillen, Wehklagen und Pein und Zähneknirschen auf ihr Haupt vergelten bis zur dritten und vierten Generation, solange sie nicht umkehren und mich hassen, spricht der Herr, euer Gott."},{"verse":53,"text":"Und dies mache ich euch zu einem Beispiel, euch zum Trost in Bezug auf alle diejenigen, denen geboten worden ist, ein Werk zu tun, und die von der Hand ihrer Feinde und durch Unterdrückung daran gehindert worden sind, spricht der Herr, euer Gott."},{"verse":54,"text":"Denn ich bin der Herr, euer Gott, und werde alle diejenigen eurer Brüder erretten, die im Herzen rein waren und im Land Missouri getötet wurden, spricht der Herr."},{"verse":55,"text":"Und weiter, wahrlich, ich sage euch: Ich gebiete euch abermals, meinem Namen ein Haus zu bauen, ja, an diesem Ort, damit ihr euch mir in allem als treu erweisen könnt, was auch immer ich euch gebiete, damit ich euch segnen und euch mit Ehre, Unsterblichkeit und ewigem Leben krönen kann."},{"verse":56,"text":"Und nun sage ich euch, was meine Herberge betrifft, die zu bauen ich euch geboten habe, um Fremdlinge zu beherbergen: Sie soll meinem Namen gebaut werden, und mein Name soll darauf genannt werden, und mein Diener Joseph und sein Haus sollen darin Platz haben, von Generation zu Generation."},{"verse":57,"text":"Denn diese Salbung habe ich auf sein Haupt kommen lassen, dass seine Segnung auch auf das Haupt seiner Nachkommen nach ihm kommen soll."},{"verse":58,"text":"Und wie ich zu Abraham in Bezug auf die Geschlechter der Erde gesagt habe, so sage ich auch zu meinem Diener Joseph: In dir und in deinen Nachkommen werden die Geschlechter der Erde gesegnet sein."},{"verse":59,"text":"Darum lasst meinen Diener Joseph und seine Nachkommen nach ihm Platz in diesem Haus haben, von Generation zu Generation, für immer und immer, spricht der Herr."},{"verse":60,"text":"Und der Name des Hauses soll Nauvoo-Haus sein; und es soll eine angenehme Wohnung für die Menschen sein und eine Ruhestätte für den müden Wanderer, damit er über die Herrlichkeit Zions und die Herrlichkeit dieses seines Ecksteins nachsinnen kann,"},{"verse":61,"text":"damit er auch Rat von denen empfangen kann, die ich als Pflanzung des Ruhmes gesetzt habe und als Wächter auf den Mauern Zions."},{"verse":62,"text":"Siehe, wahrlich, ich sage euch: Mein Diener George Miller und mein Diener Lyman Wight und mein Diener John Snider und mein Diener Peter Haws sollen sich organisieren und einen aus ihrer Mitte zum Vorsitzenden ihres Komitees bestimmen, zu dem Zweck, dieses Haus zu bauen."},{"verse":63,"text":"Und sie sollen eine Satzung gestalten, sodass sie Anteile zum Bau des Hauses in Empfang nehmen können."},{"verse":64,"text":"Und sie sollen nicht weniger als fünfzig Dollar pro Anteilschein an diesem Haus in Empfang nehmen, und es soll ihnen gestattet sein, von einem Einzelnen bis zu fünfzehntausend Dollar als Anteile an diesem Haus anzunehmen."},{"verse":65,"text":"Aber es soll ihnen nicht gestattet sein, mehr als fünfzehntausend Dollar als Anteile eines Einzelnen in Empfang zu nehmen."},{"verse":66,"text":"Und es soll ihnen nicht gestattet sein, weniger als fünfzig Dollar pro Anteilschein an dem Haus von einem Einzelnen entgegenzunehmen."},{"verse":67,"text":"Und es soll ihnen nicht gestattet sein, jemanden als Anteilseigner an dem Haus anzunehmen, außer der Betreffende bezahlt ihnen seine Anteile bei Übernahme der Anteile auf die Hand;"},{"verse":68,"text":"und im Verhältnis zu dem Anteilsbetrag, den er ihnen auf die Hand bezahlt, soll er Anteile an dem Haus empfangen; wenn er ihnen aber nichts auf die Hand bezahlt, soll er keine Anteile an dem Haus empfangen."},{"verse":69,"text":"Und wenn jemand ihnen Anteile auf die Hand bezahlt, so soll das für Anteile an dem Haus sein – für ihn selbst und für seine Generation nach ihm, von Generation zu Generation, solange er und seine Erben die Anteile im Besitz haben und die Anteile weder verkaufen noch aus freiem Willen und Handeln aus den Händen lassen, wenn ihr meinen Willen tun wollt, spricht der Herr, euer Gott."},{"verse":70,"text":"Und weiter, wahrlich, ich sage euch: Wenn mein Diener George Miller und mein Diener Lyman Wight und mein Diener John Snider und mein Diener Peter Haws irgendwelche Anteile in die Hand bekommen, sei es in Geld oder in Eigentum, wodurch sie Geldeswert in Empfang nehmen, so sollen sie keinen Teil von diesen Anteilen für irgendeinen anderen Zweck verwenden als nur für dieses Haus."},{"verse":71,"text":"Und wenn sie einen Teil von jenen Anteilen ohne die Zustimmung des Anteilseigners anders verwenden als nur für dieses Haus und solche Anteile, die sie anderswo als nur für dieses Haus verwenden, nicht vierfach zurückzahlen, dann werden sie verflucht sein und werden von ihrem Platz entfernt werden, spricht Gott, der Herr; denn ich, der Herr, bin Gott, und lasse mich in all diesem nicht verspotten."},{"verse":72,"text":"Wahrlich, ich sage euch: Mein Diener Joseph soll ihnen Anteile für den Bau dieses Hauses auf die Hand zahlen, wie es ihm gut scheint; aber mein Diener Joseph darf nicht mehr als fünfzehntausend Dollar für Anteile an diesem Haus zahlen, auch nicht weniger als fünfzig Dollar; und das darf auch niemand sonst, spricht der Herr."},{"verse":73,"text":"Und es gibt noch andere, die meinen Willen in Bezug auf sie wissen wollen, denn sie haben das von meiner Hand erbeten."},{"verse":74,"text":"Darum sage ich euch in Bezug auf meinen Diener Vinson Knight: Wenn er meinen Willen tun will, so erwerbe er Anteile an diesem Haus für sich und für seine Generation nach ihm, von Generation zu Generation."},{"verse":75,"text":"Und er soll inmitten des Volkes seine Stimme erheben, lang und laut, um für die Sache der Armen und der Bedürftigen einzutreten; und er soll nicht fehlgehen und sein Herz nicht ermatten lassen; dann werde ich seine Opfer annehmen, und sie werden mir nicht sein wie die Opfer Kains, denn er wird mein sein, spricht der Herr."},{"verse":76,"text":"Seine Familie soll sich freuen und das Herz von ihrer Bedrängnis wegwenden; denn ich habe ihn erwählt und ihn gesalbt, und er wird inmitten seines Hauses Ehre erlangen, denn ich werde ihm alle seine Sünden vergeben, spricht der Herr. Amen."},{"verse":77,"text":"Wahrlich, ich sage euch: Mein Diener Hyrum soll Anteile an diesem Haus erwerben, wie es ihm gut scheint – für sich und seine Generation nach ihm, von Generation zu Generation."},{"verse":78,"text":"Mein Diener Isaac Galland soll Anteile an diesem Haus erwerben, denn ich, der Herr, liebe ihn um der Arbeit willen, die er getan hat, und werde ihm alle seine Sünden vergeben; darum soll er mit einer Beteiligung an diesem Haus bedacht werden, von Generation zu Generation."},{"verse":79,"text":"Mein Diener Isaac Galland soll unter euch bestimmt und von meinem Diener William Marks ordiniert werden und von ihm gesegnet werden, dass er mit meinem Diener Hyrum gehe und die Arbeit verrichte, die mein Diener Joseph ihnen zuweisen wird, dann werden sie sehr gesegnet sein."},{"verse":80,"text":"Mein Diener William Marks soll Anteile an diesem Haus bezahlen, wie es ihm gut scheint – für sich und seine Generation, von Generation zu Generation."},{"verse":81,"text":"Mein Diener Henry G. Sherwood soll Anteile an diesem Haus bezahlen, wie es ihm gut scheint – für sich und seine Nachkommen nach ihm, von Generation zu Generation."},{"verse":82,"text":"Mein Diener William Law soll Anteile an diesem Haus bezahlen – für sich und seine Nachkommen nach ihm, von Generation zu Generation."},{"verse":83,"text":"Wenn er meinen Willen tun will, so soll er seine Familie nicht in die östlichen Länder bringen, nämlich nach Kirtland; doch werde ich, der Herr, Kirtland aufbauen, aber ich, der Herr, habe für die dortigen Einwohner eine Geißel bereitet."},{"verse":84,"text":"Und bei meinem Diener Almon Babbitt gibt es vieles, was mir nicht gefällt; siehe, er strebt danach, seinen eigenen Rat durchzusetzen und nicht den Rat, den ich verordnet habe, nämlich den der Präsidentschaft meiner Kirche; und er richtet ein goldenes Kalb auf, dass mein Volk es anbete."},{"verse":85,"text":"Lasst niemand von diesem Ort weggehen, der mit dem Bestreben, meine Gebote zu halten, hierhergekommen ist."},{"verse":86,"text":"Wenn sie hier leben, so sollen sie in mir leben; und wenn sie sterben, so sollen sie in mir sterben; denn sie werden von all ihrer Arbeit hier ausruhen und werden ihr Werk fortsetzen."},{"verse":87,"text":"Darum soll mein Diener William sein Vertrauen in mich setzen und aufhören, wegen der Krankheit im Land für seine Familie zu fürchten. Wenn ihr mich liebt, so haltet meine Gebote; dann wird die Krankheit im Land sich zu eurer Herrlichkeit auswirken."},{"verse":88,"text":"Mein Diener William soll hingehen und mit lauter Stimme und mit großer Freude mein immerwährendes Evangelium verkündigen, wie er von meinem Geist dazu bewogen wird, zu den Einwohnern von Warsaw und auch zu den Einwohnern von Carthage und auch zu den Einwohnern von Burlington und auch zu den Einwohnern von Madison, und mit Geduld und Eifer auf weitere Anweisungen bei meiner Generalkonferenz warten, spricht der Herr."},{"verse":89,"text":"Wenn er meinen Willen tun will, so soll er hinfort auf den Rat meines Dieners Joseph hören und mit seinem Ertrag die Sache der Armen unterstützen und die neue Übersetzung meines heiligen Wortes an die Bewohner der Erde veröffentlichen."},{"verse":90,"text":"Und wenn er dies tut, so werde ich ihn mit einer Vielfalt von Segnungen segnen, sodass er nicht verlassen sein wird, noch seine Nachkommen um Brot betteln müssen."},{"verse":91,"text":"Und weiter, wahrlich, ich sage euch: Mein Diener William soll anstelle meines Dieners Hyrum zum Ratgeber meines Dieners Joseph bestimmt, ordiniert und gesalbt werden, damit mein Diener Hyrum das Amt im Priestertum und als Patriarch übernehmen kann, das ihm von seinem Vater durch Segnung und auch als Recht bestimmt worden ist;"},{"verse":92,"text":"damit er hinfort die Schlüssel für die patriarchalischen Segen auf das Haupt meines ganzen Volkes innehabe;"},{"verse":93,"text":"damit jeder, den er segnet, gesegnet sein wird und jeder, den er verflucht, verflucht sein wird; damit, was auch immer er auf Erden binden wird, im Himmel gebunden sein wird, und was auch immer er auf Erden lösen wird, im Himmel gelöst sein wird."},{"verse":94,"text":"Und von dieser Zeit an bestimme ich ihn, für meine Kirche ein Prophet und ein Seher und ein Offenbarer zu sein gleichwie mein Diener Joseph,"},{"verse":95,"text":"damit er auch im Einvernehmen mit meinem Diener Joseph handle und damit er von meinem Diener Joseph Rat empfange, denn dieser wird ihm die Schlüssel kundtun, wodurch er erbitten und empfangen kann und mit der gleichen Segnung und Herrlichkeit und Ehre und dem gleichen Priestertum und den gleichen Gaben des Priestertums gekrönt werden kann, die vormals auf den gelegt worden waren, der mein Diener Oliver Cowdery war;"},{"verse":96,"text":"damit mein Diener Hyrum Zeugnis geben möge für all das, was ich ihm zeigen werde, damit sein Name von Generation zu Generation in ehrenvoller Erinnerung gehalten werde für immer und immer."},{"verse":97,"text":"Lass auch meinen Diener William Law die Schlüssel empfangen, wodurch er Segnungen erbitten und empfangen kann; er soll demütig vor mir sein und ohne Falschheit sein, dann wird er von meinem Geist empfangen, ja, dem Tröster, der ihm von allem kundtun wird, ob es wahr ist, und ihm zur selben Stunde eingeben wird, was er sagen soll."},{"verse":98,"text":"Und diese Zeichen werden ihm folgen: Er wird die Kranken heilen, er wird Teufel austreiben und wird befreit werden von denen, die ihm tödliches Gift verabreichen möchten;"},{"verse":99,"text":"und er wird auf Pfaden geführt werden, wo die Giftschlange seine Ferse nicht zu fassen bekommt, und er wird sich emporschwingen in der Vorstellung seiner Gedanken wie auf Adlersflügeln."},{"verse":100,"text":"Und wenn ich will, dass er Tote auferweckt, soll er seine Stimme nicht zurückhalten."},{"verse":101,"text":"Darum soll mein Diener William sich nicht zurückhalten, sondern vor Freude und Jubel laut rufen, mit Hosanna für den, der für immer und immer auf dem Thron sitzt, spricht der Herr, euer Gott."},{"verse":102,"text":"Siehe, ich sage euch: Ich habe für meinen Diener William und meinen Diener Hyrum, und nur für sie, eine Mission bereit; und mein Diener Joseph soll daheim bleiben, denn er wird gebraucht. Das Übrige werde ich euch später noch zeigen. So ist es. Amen."},{"verse":103,"text":"Und weiter, wahrlich, ich sage euch: Wenn mein Diener Sidney mir dienen und meinem Diener Joseph ein Ratgeber sein will, so soll er sich erheben und herzukommen und im Amt seiner Berufung stehen und sich vor mir demütigen."},{"verse":104,"text":"Und wenn er mir ein annehmbares Opfer und Bekenntnis darbringt und bei meinem Volk bleibt, siehe, so werde ich, der Herr, euer Gott, ihn heilen, sodass er geheilt ist; und er wird wieder auf den Bergen seine Stimme erheben und ein Sprecher vor meinem Angesicht sein."},{"verse":105,"text":"Er soll kommen und seine Familie in der Nachbarschaft unterbringen, wo mein Diener Joseph wohnt."},{"verse":106,"text":"Und auf all seinen Reisen soll er seine Stimme erheben wie mit dem Ton einer Posaune und die Bewohner der Erde warnen, dem kommenden Grimm zu entfliehen."},{"verse":107,"text":"Er soll meinem Diener Joseph behilflich sein, und auch mein Diener William Law soll meinem Diener Joseph behilflich sein, eine feierliche Kundmachung an die Könige der Erde zu verfassen, so wie ich es euch zuvor gesagt habe."},{"verse":108,"text":"Wenn mein Diener Sidney meinen Willen tun will, so soll er seine Familie nicht in die östlichen Länder wegbringen, sondern ihren Wohnsitz verlegen, so wie ich es gesagt habe."},{"verse":109,"text":"Siehe, es ist nicht mein Wille, dass er danach trachten soll, Sicherheit und Zuflucht außerhalb der Stadt zu finden, die ich für euch bestimmt habe, nämlich die Stadt Nauvoo."},{"verse":110,"text":"Wahrlich, ich sage euch: Selbst jetzt, wenn er auf meine Stimme hört, wird es ihm wohl ergehen. So ist es. Amen."},{"verse":111,"text":"Und weiter, wahrlich, ich sage euch: Mein Diener Amos Davies soll denen, die ich dazu bestimmt habe, dass sie eine Herberge bauen, nämlich das Nauvoo-Haus, Anteile auf die Hand bezahlen."},{"verse":112,"text":"Das soll er tun, wenn er eine Beteiligung haben will; und er soll auf den Rat meines Dieners Joseph hören und mit seinen eigenen Händen arbeiten, damit er das Vertrauen der Menschen erlange."},{"verse":113,"text":"Und wenn er sich in allem, was seiner Obhut anvertraut wird, als treu erweist, ja, selbst wenigem, so wird er zum Herrscher über vieles gemacht werden;"},{"verse":114,"text":"darum soll er sich selbst erniedrigen, damit er erhöht werden kann. So ist es. Amen."},{"verse":115,"text":"Und weiter, wahrlich, ich sage euch: Wenn mein Diener Robert D. Foster meiner Stimme gehorchen will, so soll er für meinen Diener Joseph ein Haus bauen, gemäß dem Vertrag, den er mit ihm geschlossen hat, so wie sich ihm von Zeit zu Zeit die Tür dazu öffnen wird."},{"verse":116,"text":"Und er soll von all seiner Torheit umkehren und sich mit Nächstenliebe bekleiden und aufhören, Böses zu tun, und all sein hartes Reden ablegen"},{"verse":117,"text":"und dem Nauvoo-Haus-Komitee Anteile auf die Hand bezahlen – für sich und für seine Generation nach ihm, von Generation zu Generation,"},{"verse":118,"text":"und auf den Rat meiner Diener Joseph und Hyrum und William Law und auf die Autoritäten hören, die ich berufen habe, die Grundlage von Zion zu legen, dann wird es ihm für immer und immer wohl ergehen. So ist es. Amen."},{"verse":119,"text":"Und weiter, wahrlich, ich sage euch: Lasst niemanden dem Nauvoo-Haus-Komitee Anteile bezahlen, der nicht an das Buch Mormon und die Offenbarungen glaubt, die ich euch gegeben habe, spricht der Herr, euer Gott;"},{"verse":120,"text":"denn was mehr oder weniger ist als dies, kommt vom Bösen und wird von Flüchen begleitet sein und nicht von Segnungen, spricht der Herr, euer Gott. So ist es. Amen."},{"verse":121,"text":"Und weiter, wahrlich, ich sage euch: Das Nauvoo-Haus-Komitee soll für alle seine Arbeiten, die es für den Bau des Nauvoo-Hauses verrichtet, eine gerechte Lohnvergütung erhalten; und ihr Lohn soll so sein, wie sie es unter sich vereinbaren, nämlich was dessen Höhe betrifft."},{"verse":122,"text":"Und lasst einen jeden, der Anteile bezahlt, seinen Teil an ihrer Entlohnung tragen, wenn es zu ihrem Lebensunterhalt notwendig ist, spricht der Herr; andernfalls soll ihnen ihre Arbeit als Anteile an diesem Haus angerechnet werden. So ist es. Amen."},{"verse":123,"text":"Wahrlich, ich sage euch: Nun gebe ich euch die Beamten bekannt, die zu meinem Priestertum gehören, damit ihr dessen Schlüssel innehaben könnt, nämlich das Priestertum nach der Ordnung Melchisedeks, welches nach der Ordnung meines einziggezeugten Sohnes ist."},{"verse":124,"text":"Zuerst gebe ich euch Hyrum Smith als Patriarchen für euch, dass er die siegelnden Segnungen meiner Kirche innehabe, ja, den Heiligen Geist der Verheißung, wodurch ihr für den Tag der Erlösung versiegelt werdet, damit ihr trotz der Stunde der Versuchung, die über euch kommen mag, nicht fallt."},{"verse":125,"text":"Ich gebe euch meinen Diener Joseph, dass er der präsidierende Älteste über meine ganze Kirche sei, dass er ein Übersetzer, ein Offenbarer, ein Seher und Prophet sei."},{"verse":126,"text":"Ich gebe ihm als Ratgeber meinen Diener Sidney Rigdon und meinen Diener William Law, dass diese ein Kollegium und die Erste Präsidentschaft bilden, um die Aussprüche Gottes für die ganze Kirche zu empfangen."},{"verse":127,"text":"Ich gebe euch meinen Diener Brigham Young, dass er der Präsident des reisenden Rates, der Zwölf, sei;"},{"verse":128,"text":"und diese Zwölf haben die Schlüssel inne, um die Vollmacht meines Reiches für die vier Ecken der Erde zu erschließen und danach jedem Geschöpf mein Wort zu senden."},{"verse":129,"text":"Es sind dies Heber C. Kimball, Parley P. Pratt, Orson Pratt, Orson Hyde, William Smith, John Taylor, John E. Page, Wilford Woodruff, Willard Richards, George A. Smith;"},{"verse":130,"text":"David Patten habe ich zu mir genommen; siehe, sein Priestertum nimmt niemand von ihm; aber wahrlich, ich sage euch: Ein anderer möge für dieselbe Berufung bestimmt werden."},{"verse":131,"text":"Und weiter, ich sage euch: Ich gebe euch einen Hoherat für den Eckstein von Zion,"},{"verse":132,"text":"nämlich Samuel Bent, Henry G. Sherwood, George W. Harris, Charles C. Rich, Thomas Grover, Newel Knight, David Dort, Dunbar Wilson – Seymour Brunson habe ich zu mir genommen; niemand nimmt ihm sein Priestertum, aber ein anderer möge an seiner Stelle zu demselben Priestertum bestimmt werden; und wahrlich, ich sage euch: Mein Diener Aaron Johnson soll an seiner Stelle zu dieser Berufung ordiniert werden –, David Fullmer, Alpheus Cutler, William Huntington."},{"verse":133,"text":"Und weiter, ich gebe euch Don C. Smith als Präsidenten eines Kollegiums von Hohen Priestern,"},{"verse":134,"text":"und diese Verordnung ist zu dem Zweck eingerichtet, diejenigen vorzubereiten, die als ortsständige Präsidenten oder Diener über verschiedene auswärtige zerstreute Pfähle bestimmt werden sollen;"},{"verse":135,"text":"und sie können auch reisen, wenn sie wollen, doch sind sie vielmehr zu ortsständigen Präsidenten ordiniert, denn das ist das Amt ihrer Berufung, spricht der Herr, euer Gott."},{"verse":136,"text":"Ich gebe ihm Amasa Lyman und Noah Packard als Ratgeber, dass sie über das Kollegium der Hohen Priester meiner Kirche präsidieren mögen, spricht der Herr."},{"verse":137,"text":"Und weiter, ich sage euch: Ich gebe euch John A. Hicks, Samuel Williams und Jesse Baker, und dieses Priestertum soll über das Kollegium der Ältesten präsidieren, und dieses Kollegium ist für die ortsständigen geistlichen Diener eingerichtet; doch können sie reisen, aber sie sind ordiniert, um ortsständige geistliche Diener für meine Kirche zu sein, spricht der Herr."},{"verse":138,"text":"Und weiter, ich gebe euch Joseph Young, Josiah Butterfield, Daniel Miles, Henry Herriman, Zera Pulsipher, Levi Hancock, James Foster, dass sie über das Kollegium der Siebziger präsidieren,"},{"verse":139,"text":"und dieses Kollegium ist für reisende Älteste eingerichtet, die in aller Welt für meinen Namen Zeugnis geben, wohin auch immer der reisende Hoherat, meine Apostel, sie senden wird, um vor meinem Angesicht einen Weg zu bereiten."},{"verse":140,"text":"Der Unterschied zwischen diesem Kollegium und dem Kollegium der Ältesten besteht darin, dass die einen beständig reisen sollen, und die anderen sollen von Zeit zu Zeit über die Gemeinden präsidieren; diese also haben die Verantwortung, von Zeit zu Zeit zu präsidieren, und die anderen haben nicht die Verantwortung zu präsidieren, spricht der Herr, euer Gott."},{"verse":141,"text":"Und weiter, ich sage euch: Ich gebe euch Vinson Knight, Samuel H. Smith und Shadrach Roundy, wenn er es annehmen will, dass sie über die Bischofschaft präsidieren; Kenntnis über die besagte Bischofschaft ist euch im Buch Lehre und Bündnisse gegeben."},{"verse":142,"text":"Und weiter, ich sage euch: Samuel Rolfe und seine Ratgeber für die Priester, und den Präsidenten der Lehrer und seine Ratgeber und auch den Präsidenten der Diakone und seine Ratgeber und auch den Präsidenten des Pfahles und seine Ratgeber."},{"verse":143,"text":"Die obigen Ämter habe ich euch gegeben, auch deren Schlüssel, als Hilfsmittel und zur Regierung, für das Werk des geistlichen Dienstes und die Vervollkommnung meiner Heiligen."},{"verse":144,"text":"Und das Gebot gebe ich euch, alle diese Ämter zu besetzen und die Namen, die ich erwähnt habe, entweder zu billigen oder aber zu missbilligen, und zwar auf meiner Generalkonferenz;"},{"verse":145,"text":"und für alle diese Ämter Räume in meinem Haus vorzubereiten, wenn ihr es meinem Namen baut, spricht der Herr, euer Gott. So ist es. Amen."}]},{"chapter":125,"verses":[{"verse":1,"text":"Was ist der Wille des Herrn in Bezug auf die Heiligen im Territorium Iowa?"},{"verse":2,"text":"Wahrlich, so spricht der Herr: Ich sage euch: Wenn diejenigen, die sich nach meinem Namen nennen und sich bestreben, meine Heiligen zu sein – wenn sie meinen Willen tun und meine in Bezug auf sie gegebenen Gebote halten wollen, dann sollen sie sich an den Orten sammeln, die ich ihnen durch meinen Diener Joseph bestimmen werde, und meinem Namen Städte bauen, damit sie bereit seien für das, was die Zukunft bringen wird."},{"verse":3,"text":"Sie sollen auf dem Land gegenüber der Stadt Nauvoo meinem Namen eine Stadt bauen, und sie soll mit dem Namen Zarahemla benannt werden."},{"verse":4,"text":"Und alle, die von Osten und Westen und Norden und Süden kommen und den Wunsch haben, darin zu wohnen, sollen dort ihr Erbteil übernehmen, und ebenso in der Stadt Nashville oder in der Stadt Nauvoo und in allen Pfählen, die ich bestimmt habe, spricht der Herr."}]},{"chapter":126,"verses":[{"verse":1,"text":"Teurer und vielgeliebter Bruder Brigham Young, wahrlich, so spricht der Herr zu dir: Mein Diener Brigham, es wird von deiner Hand nicht mehr gefordert, dass du, wie in der Vergangenheit, deine Familie verlässt, denn dein Opfer ist für mich annehmbar."},{"verse":2,"text":"Ich habe deine Arbeit und Mühe gesehen, als du um meines Namens willen gereist bist."},{"verse":3,"text":"Darum gebiete ich dir, sende mein Wort hinaus, und sorge von dieser Zeit an, fortan und für immer, besonders für deine Familie. Amen."}]},{"chapter":127,"verses":[{"verse":1,"text":"Da der Herr mir offenbart hat, dass meine Feinde sowohl in Missouri als auch in diesem Staat mir wieder nachstellen, und da sie mir ohne Grund nachstellen und auch nicht den geringsten Schatten oder Anstrich von Gerechtigkeit und Recht auf ihrer Seite haben, wenn sie ihre Strafverfolgung gegen mich in Gang setzen, und da ihre Behauptungen alle auf Unwahrheit der schwärzesten Art beruhen, habe ich es für ratsam und weise gehalten, den Ort für eine kurze Zeit zu verlassen, um meiner eigenen Sicherheit und der Sicherheit dieses Volkes willen. All denen, die mit mir in Geschäftsverbindung stehen, möchte ich sagen, dass ich meine Angelegenheiten an Agenten und Gehilfen übergeben habe, die alles Geschäftliche prompt und ordnungsgemäß erledigen und darauf sehen werden, dass alle meine Schulden zu gegebener Zeit beglichen werden, sei es, indem Vermögenswerte herausgegeben werden, oder auf andere Weise, wie der einzelne Fall es erfordert oder wie die Umstände es zulassen. Wenn ich höre, dass der Sturm sich völlig gelegt hat, werde ich dann wieder zu euch zurückkehren."},{"verse":2,"text":"Und was nun die Gefahren betrifft, die durchzumachen ich berufen bin, so scheinen sie mir nur gering, denn menschlicher Neid und Grimm sind alle Tage meines Lebens mein übliches Los gewesen; und aus welchem Grund, scheint rätselhaft, außer ich wurde schon vor der Grundlegung der Welt zu irgendeinem guten Zweck ordiniert, oder bösen, wie zu nennen es euch beliebt. Urteilt für euch selbst. Gott weiß das alles, ob es gut ist oder böse. Wie auch immer, ich bin gewohnt, in tiefem Wasser zu schwimmen. Das ist mir alles zur zweiten Natur geworden, und es geht mir so wie Paulus, dass ich mich der Drangsal rühme, denn bis zum heutigen Tag hat der Gott meiner Väter mich aus allem befreit und wird mich auch hinfort befreien; denn siehe, ja siehe, ich werde über alle meine Feinde triumphieren, denn Gott, der Herr, hat es gesagt."},{"verse":3,"text":"Alle Heiligen sollen sich darum freuen und überaus froh sein; denn Israels Gott ist ihr Gott, und er wird all ihren Bedrückern eine gerechte Vergeltung als Lohn auf das Haupt zumessen."},{"verse":4,"text":"Und weiter, wahrlich, so spricht der Herr: Lasst die Arbeit an meinem Tempel und an jedem Werk, das ich euch bestimmt habe, weitergehen und nicht aufhören; und euer Eifer und eure Ausdauer und Geduld und eure Anstrengungen sollen sich verdoppeln, und ihr werdet keineswegs eures Lohnes verlustig gehen, spricht der Herr der Heerscharen. Und wenn sie euch verfolgen, so haben sie auch die Propheten und rechtschaffenen Männer verfolgt, die vor euch gewesen sind. Für das alles gibt es einen Lohn im Himmel."},{"verse":5,"text":"Und weiter, ich gebe euch ein Wort in Bezug auf die Taufe für eure Toten."},{"verse":6,"text":"Wahrlich, so spricht der Herr zu euch in Bezug auf eure Toten: Wenn jemand von euch für eure Toten getauft wird, so soll es einen Berichtführer geben, und er soll Augenzeuge eurer Taufen sein; er soll mit eigenen Ohren hören, damit er der Wahrheit gemäß bezeugen kann, spricht der Herr,"},{"verse":7,"text":"damit alles, was ihr aufzeichnet, im Himmel aufgezeichnet werde, was auch immer ihr auf Erden bindet, im Himmel gebunden sei, was auch immer ihr auf Erden löst, im Himmel gelöst sei;"},{"verse":8,"text":"denn ich bin im Begriff, auf Erden vieles wiederherzustellen, was das Priestertum betrifft, spricht der Herr der Heerscharen."},{"verse":9,"text":"Und weiter: Alle Aufzeichnungen sollen in Ordnung sein, damit sie in die Archive meines heiligen Tempels gelegt und von Generation zu Generation in Erinnerung behalten werden können, spricht der Herr der Heerscharen."},{"verse":10,"text":"Ich möchte allen Heiligen sagen, dass ich mir mit überaus großem Wunsch gewünscht hätte, am folgenden Sabbat vom Rednerpult aus zu ihnen über das Thema der Taufe für die Toten zu sprechen. Da es aber nicht in meiner Macht steht, dies zu tun, werde ich das Wort des Herrn über dieses Thema von Zeit zu Zeit niederschreiben und es euch zusammen mit vielem anderen mit der Post zusenden."},{"verse":11,"text":"Ich schließe nun für heute meinen Brief aus Mangel an mehr Zeit; denn der Feind ist wachsam, und wie der Erretter gesagt hat, der Fürst dieser Welt kommt, aber er hat keine Macht über mich."},{"verse":12,"text":"Siehe, ich bete zu Gott, dass ihr alle errettet werden mögt. Und ich unterzeichne als euer Diener im Herrn, als Prophet und Seher der Kirche Jesu Christi der Heiligen der Letzten Tage."},{"verse":13,"text":"Joseph Smith."}]},{"chapter":128,"verses":[{"verse":1,"text":"Wie ich in meinem Brief, den ich euch vor meinem Weggang schrieb, erwähnte, dass ich euch von Zeit zu Zeit schreiben und euch Mitteilung über viele Themen machen würde, so nehme ich nun das Thema der Taufe für die Toten wieder auf, denn dieses Thema scheint meine Gedanken zu beanspruchen und meine Gefühle am stärksten zu beeindrucken, seit ich von meinen Feinden verfolgt werde."},{"verse":2,"text":"Ich habe euch einige Worte der Offenbarung in Bezug auf einen Berichtführer geschrieben. Hinsichtlich dieser Sache habe ich noch einige weitere Einblicke gehabt, die ich nun bestätige. Das heißt, ich hatte in meinem vorigen Brief gesagt, es müsse ein Berichtführer da sein, der Augenzeuge sein und auch mit eigenen Ohren hören solle, damit er vor dem Herrn der Wahrheit gemäß einen Bericht geben könne."},{"verse":3,"text":"Nun wäre es hinsichtlich dieser Sache für einen einzelnen Berichtführer wohl sehr schwierig, zu allen Zeiten anwesend zu sein und alle Arbeiten selbst zu erledigen. Um diese Schwierigkeit zu vermeiden, kann in jeder Gemeinde der Stadt ein eigener Berichtführer bestimmt werden, der gut geeignet ist, eine genaue Niederschrift anzufertigen; und er soll beim Festhalten des gesamten Vorgangs sehr ausführlich und genau verfahren und in seinem Bericht bestätigen, dass er mit eigenen Augen gesehen und mit eigenen Ohren gehört hat; er soll das Datum, die Namen und so weiter sowie den Verlauf der gesamten Handlung wiedergeben; auch soll er drei der Anwesenden, sofern es welche gegeben hat, namentlich nennen, die das alles auf Verlangen jederzeit bestätigen können, damit durch den Mund zweier oder dreier Zeugen jegliches Wort bestätigt werden kann."},{"verse":4,"text":"Dann soll es auch einen allgemeinen Berichtführer geben, dem diese anderen Berichte eingehändigt werden können, begleitet von einer eigenhändig unterzeichneten Bescheinigung, die bescheinigt, dass der angefertigte Bericht richtig ist. Dann kann der allgemeine Berichtführer der Kirche den Bericht ins Generalbuch der Kirche eintragen, dazu auch die Bescheinigungen sowie sämtliche anwesenden Zeugen, dazu seine eigene Erklärung, dass er wirklich glaubt, dass die obige Erklärung und die Berichte, aufgrund seiner Kenntnis vom Charakter der betreffenden Männer und von ihrer Berufung in der Kirche, der Wahrheit entsprechen. Und sobald dies im Generalbuch der Kirche eingetragen ist, wird der Bericht genauso heilig sein und der Verordnung geradeso entsprechen, als habe er mit eigenen Augen gesehen und mit eigenen Ohren gehört und davon einen Bericht im Generalbuch der Kirche gemacht."},{"verse":5,"text":"Ihr denkt vielleicht, diese Anordnung sei sehr ausführlich; ich will euch aber sagen, dass sie nur dem Willen Gottes entspricht, indem sie der Verordnung und Vorbereitung gerecht wird, die der Herr vor der Grundlegung der Welt für die Errettung der Toten, die sterben würden, ohne das Evangelium zu kennen, verordnet und bereitet hat."},{"verse":6,"text":"Und ferner möchte ich euch daran erinnern, dass Johannes der Offenbarer über genau dieses Thema hinsichtlich der Toten nachsann, als er sagte, und ihr findet es in Offenbarung 20:12: Und ich sah die Toten, klein und groß, vor Gott stehen, und die Bücher wurden aufgeschlagen; und noch ein Buch wurde aufgeschlagen, das ist das Buch des Lebens; und die Toten wurden nach dem gerichtet, was in den Büchern geschrieben steht, gemäß ihren Werken."},{"verse":7,"text":"Aus diesem Zitat erseht ihr, dass die Bücher aufgeschlagen wurden und dass noch ein Buch aufgeschlagen wurde, das war das Buch des Lebens; aber die Toten wurden nach dem gerichtet, was in den Büchern geschrieben steht, gemäß ihren Werken; folglich müssen die genannten Bücher jene Bücher sein, welche die Aufzeichnung über ihre Werke enthalten und sich dabei auf die Aufzeichnungen beziehen, die auf Erden geführt werden. Und das Buch, welches das Buch des Lebens war, ist die Aufzeichnung, die im Himmel geführt wird; dieser Grundsatz stimmt genau mit der Lehre überein, die euch in der Offenbarung geboten worden ist, die in dem Brief enthalten war, den ich euch vor meinem Weggang geschrieben habe – damit alles, was ihr aufzeichnet, im Himmel aufgezeichnet werde."},{"verse":8,"text":"Nun besteht das Wesen dieser Verordnung in der Macht des Priestertums, durch die Offenbarung von Jesus Christus, wodurch euch zugestanden ist, dass, was auch immer ihr auf Erden bindet, im Himmel gebunden sein wird, und was auch immer ihr auf Erden löst, im Himmel gelöst sein wird. Oder mit anderen Worten, wenn man die Übersetzung von einer anderen Seite betrachtet: Was auch immer ihr auf Erden aufzeichnet, wird im Himmel aufgezeichnet sein, und was auch immer ihr auf Erden nicht aufzeichnet, wird im Himmel nicht aufgezeichnet sein; denn aus den Büchern werden eure Toten gerichtet werden, gemäß ihren eigenen Werken, sei es, dass sie die Verordnungen selbst, in propria persona, vollzogen haben oder mit Hilfe ihrer eigenen Beauftragten – gemäß der Verordnung, die Gott schon von vor der Grundlegung der Welt an zu ihrer Errettung bereitet hat, gemäß den Aufzeichnungen, die sie in Bezug auf ihre Toten geführt haben."},{"verse":9,"text":"Einigen mag es als eine sehr kühne Lehre vorkommen, wenn wir von einer Macht sprechen, die auf Erden aufzeichnet oder bindet und im Himmel bindet. Doch ist diese Macht in allen Zeitaltern der Welt gegeben worden, immer wenn der Herr einem Mann oder einer Gruppe von Männern durch tatsächliche Offenbarung eine Evangeliumszeit des Priestertums gegeben hat. Was auch immer jene Männer mit Vollmacht und im Namen des Herrn getan haben, und es voll Wahrhaftigkeit und Treue getan haben, und worüber sie einen ordnungsgemäßen und getreuen Bericht geführt haben, das ist demnach auf Erden und im Himmel zu einem Gesetz geworden und kann gemäß dem Ratschluss des großen Jehova nicht für ungültig erklärt werden. Das ist ein wahrheitsgetreues Wort. Wer kann es anhören?"},{"verse":10,"text":"Und als weiteres Beispiel Matthäus 16:18,19: Und ich sage dir auch: Du bist Petrus, und auf diesen Felsen werde ich meine Kirche bauen; und die Pforten der Hölle werden sie nicht überwältigen. Und ich werde dir die Schlüssel des Himmelreichs geben, und was auch immer du auf Erden binden wirst, das wird im Himmel gebunden sein, und was auch immer du auf Erden lösen wirst, das wird im Himmel gelöst sein."},{"verse":11,"text":"Nun besteht das große und erhabene Geheimnis der ganzen Sache und das summum bonum des ganzen uns vorliegenden Themas darin, dass man die Mächte des Heiligen Priestertums erlangt. Wem diese Schlüssel gegeben sind, für den ist es nicht schwierig, eine Kenntnis von den Tatsachen hinsichtlich der Errettung der Menschenkinder zu erlangen, und zwar sowohl für die Toten als auch für die Lebenden."},{"verse":12,"text":"Hierin liegen Herrlichkeit und Ehre und Unsterblichkeit und ewiges Leben: Die Verordnung der Taufe mit Wasser, dass man darin untergetaucht wird, um dem Gleichnis der Toten zu entsprechen, damit ein Grundsatz mit dem anderen im Einklang sei; wenn man im Wasser untergetaucht wird und aus dem Wasser hervorkommt, so ist das ein Gleichnis der Auferstehung der Toten, die aus ihrem Grab hervorkommen; darum wurde diese Verordnung eingeführt, um eine Beziehung zur Verordnung der Taufe für die Toten herzustellen, denn sie ist ein Gleichnis der Toten."},{"verse":13,"text":"Infolgedessen wurde das Taufbecken als Sinnbild des Grabes eingerichtet, und es muss, dem Gebot gemäß, unterhalb des Ortes sein, wo sich die Lebenden gewöhnlich versammeln, um so die Lebenden und die Toten darzustellen, und damit alles sein Gleichnis habe und damit es miteinander im Einklang sei – das Irdische soll mit dem übereinstimmen, was himmlisch ist, wie Paulus es im 1. Korintherbrief 15:46,47 und 48 gesagt hat:"},{"verse":14,"text":"Aber nicht das Geistige war zuerst, sondern das Natürliche, und danach das Geistige. Der erste Mensch ist von der Erde, irdisch; der zweite Mensch ist der Herr vom Himmel. Wie der irdische ist, so sind auch die Irdischen; und wie der himmlische ist, so sind auch die Himmlischen. Und wie die Aufzeichnungen hinsichtlich eurer Toten auf Erden sind, die wahrheitsgetreu abgefasst sind, so sind auch die Aufzeichnungen im Himmel. Darum ist dies die siegelnde und bindende Macht und sind dies, in einem bestimmten Sinn des Wortes, die Schlüssel des Reiches, die im Schlüssel der Erkenntnis bestehen."},{"verse":15,"text":"Und nun, meine vielgeliebten Brüder und Schwestern, lasst mich euch versichern, dass es sich hier um Grundsätze hinsichtlich der Toten und der Lebenden handelt, die man im Hinblick auf unsere eigene Errettung nicht leichthin übergehen kann. Denn ihre Errettung ist für unsere eigene Errettung notwendig und wesentlich, wie Paulus in Bezug auf die Väter gesagt hat – dass sie nicht ohne uns vollkommen gemacht werden können – und auch wir können ohne unsere Toten nicht vollkommen gemacht werden."},{"verse":16,"text":"Und nun will ich euch hinsichtlich der Taufe für die Toten noch ein weiteres Zitat von Paulus anführen, 1. Korintherbrief 15:29: Was machen sonst, die sich taufen lassen für die Toten, wenn die Toten überhaupt nicht auferstehen? Warum lassen sie sich dann taufen für die Toten?"},{"verse":17,"text":"Und weiter will ich euch im Zusammenhang mit diesem Zitat etwas von einem der Propheten zitieren, der das Auge auf die Wiederherstellung des Priestertums gerichtet hatte, auf die Herrlichkeiten, die in den letzten Tagen soffenbart werden sollten, und insbesondere auf dieses herrlichste aller Themen, die zum immerwährenden Evangelium gehören, nämlich die Taufe für die Toten; denn Maleachi sagt im letzten Kapitel, die letzten beiden Verse: Siehe, ich werde euch den Propheten Elija senden, ehe der große und schreckliche Tag des Herrn kommt. Und er wird das Herz der Väter den Kindern zuwenden und das Herz der Kinder ihren Vätern, damit ich nicht komme und die Erde mit einem Fluch schlage."},{"verse":18,"text":"Ich hätte dafür eine klarere Übersetzung geben können, doch ist sie in der jetzigen Form für meinen Zweck klar genug. In diesem Fall genügt es zu wissen, dass die Erde mit einem Fluch geschlagen werden wird, wenn es nicht irgendeine Art von Bindeglied zwischen den Vätern und den Kindern gibt, nämlich im Rahmen irgendeines Sachgebiets – und siehe, was ist dieses Sachgebiet? Es ist die Taufe für die Toten. Denn ohne sie können wir nicht vollkommen gemacht werden, und auch sie können nicht ohne uns vollkommen gemacht werden. Und ebenso können weder sie noch wir ohne diejenigen vollkommen gemacht werden, die im Evangelium gestorben sind; denn mit der Einleitung der Evangeliumszeit der Fülle der Zeiten – und diese Evangeliumszeit wird gerade erst eingeleitet – ist es notwendig, dass eine gänzliche und vollständige und vollkommene Vereinigung und Verbindung der Evangeliumszeiten und Schlüssel und Mächte und Herrlichkeiten stattfindet und von den Tagen Adams, ja, bis in die gegenwärtige Zeit offenbart wird. Und nicht nur dieses, sondern auch das, was von der Grundlegung der Welt an niemals offenbart worden ist, sondern vor den Weisen und Klugen verborgen gehalten worden ist, wird in dieser, der Evangeliumszeit der Fülle der Zeiten, den Unmündigen und Säuglingen offenbart werden."},{"verse":19,"text":"Und nun, was vernehmen wir in dem Evangelium, das wir empfangen haben? Eine Stimme der Freude! Eine Stimme der Barmherzigkeit vom Himmel und eine Stimme der Wahrheit aus der Erde; frohe Nachricht für die Toten; eine Stimme der Freude für die Lebenden und die Toten; frohe Nachricht von großer Freude. Wie anmutig sind auf den Bergen die Füße derer, die frohe Nachricht von Gutem bringen und die zu Zion sprechen: Siehe, dein Gott regiert! Wie der Tau des Karmel, so wird Gotteserkenntnis auf sie herniederfallen!"},{"verse":20,"text":"Und weiter, was vernehmen wir? Frohe Nachricht von Cumorah! Moroni, ein Engel aus dem Himmel, der die Erfüllung der Propheten verkündet – das Buch, das offenbart werden sollte. Eine Stimme des Herrn in der Wildnis bei Fayette im Kreis Seneca, die den drei Zeugen sagt, sie sollten für das Buch Zeugnis geben! Die Stimme Michaels am Ufer des Susquehanna, den Teufel entlarvend, der als ein Engel des Lichts erschienen war! Die Stimme von Petrus, Jakobus und Johannes in der Wildnis zwischen Harmony, Kreis Susquehanna, und Colesville, Kreis Broome, am Ufer des Susquehanna, die verkünden, dass sie die Schlüssel des Reiches sowie der Evangeliumszeit der Fülle der Zeiten besitzen!"},{"verse":21,"text":"Und weiter die Stimme Gottes in der Kammer des alten Vaters Whitmer in Fayette, Kreis Seneca, und zu verschiedenen Zeiten und an mehreren Orten während aller Wanderungen und Drangsale dieser Kirche Jesu Christi der Heiligen der Letzten Tage! Und die Stimme Michaels, des Erzengels; die Stimme Gabriels und Rafaels und mehrerer Engel, von Michael oder Adam herab bis zur gegenwärtigen Zeit, die alle ihre Evangeliumszeit verkünden, ihre Rechte, ihre Schlüssel, ihre Ehren, ihre Majestät und Herrlichkeit und die Macht ihres Priestertums; sie geben Zeile um Zeile, Weisung um Weisung, hier ein wenig und dort ein wenig; sie spenden uns Trost, indem sie uns das darlegen, was kommen wird, und unsere Hoffnung festigen!"},{"verse":22,"text":"Brüder, sollen wir in einer so großen Sache nicht vorwärtsgehen? Geht vorwärts und nicht rückwärts! Mut, Brüder, und auf, auf zum Sieg! Lasst euer Herz sich freuen und überaus froh sein. Lasst die Erde in Gesang ausbrechen. Lasst die Toten ewige Lobeshymnen auf den König Immanuel anstimmen, der, noch ehe die Welt war, das verordnet hat, was uns befähigen würde, sie aus ihrem Gefängnis zu erlösen; denn die Gefangenen werden freigelassen werden."},{"verse":23,"text":"Lasst die Berge vor Freude jauchzen, und all ihr Täler, ruft laut, und all ihr Meere und trockenen Länder, verkündigt die Wunder eures ewigen Königs! Und ihr Flüsse und Bäche und Rinnsale, fließt voll Freude dahin. Lasst die Wälder und alle Bäume des Feldes den Herrn preisen, und ihr festen Gesteine, weint vor Freude! Und die Sonne, der Mond und die Morgensterne sollen miteinander jubeln, und alle Söhne Gottes sollen vor Freude jauchzen! Und die ewigen Schöpfungen sollen seinen Namen für immer und immer verkünden! Und weiter sage ich: Wie herrlich ist die Stimme, die wir aus dem Himmel vernehmen und die unseren Ohren Herrlichkeit und Errettung und Ehre und Unsterblichkeit und ewiges Leben verkündigt – Reiche, Fürstentümer und Mächte!"},{"verse":24,"text":"Siehe, der große Tag des Herrn steht bevor, und wer kann den Tag seines Kommens aushalten, und wer kann bestehen, wenn er erscheint? Denn er ist wie das Feuer eines Schmelzers und wie die Lauge der Wäscher; und er wird sitzen wie einer, der Silber schmilzt und reinigt, und er wird die Söhne Levi rein machen und sie wie Gold und Silber läutern, damit sie dem Herrn in Rechtschaffenheit ein Opfer darbringen können. Darum lasst uns, als Kirche und als Volk und als Heilige der Letzten Tage, dem Herrn in Rechtschaffenheit ein Opfer darbringen, und lasst uns in seinem heiligen Tempel, sobald er fertiggestellt ist, ein Buch mit den Aufzeichnungen über unsere Toten darbringen, das aller Annahme wert ist."},{"verse":25,"text":"Brüder, ich habe euch zu diesem Thema noch vieles zu sagen; aber für heute will ich schließen und das Thema ein andermal wieder aufnehmen. Ich bin, wie immer, euer demütiger Diener und unentwegter Freund,"},{"verse":26,"text":"Joseph Smith."}]},{"chapter":129,"verses":[{"verse":1,"text":"Es gibt zwei Arten von Wesen im Himmel, und zwar: Engel, bei denen es sich um Auferstandene handelt und die einen Körper aus Fleisch und Gebein haben –"},{"verse":2,"text":"Jesus beispielsweise hat gesagt: Fasst mich an und seht; denn ein Geist hat nicht Fleisch und Gebein, wie ihr seht, dass ich habe."},{"verse":3,"text":"Zweitens: die Geister gerechter Menschen, die vollkommen gemacht sind – solche, die noch nicht auferstanden sind, aber die gleiche Herrlichkeit ererben."},{"verse":4,"text":"Wenn ein Bote kommt und sagt, er habe eine Botschaft von Gott, so reiche ihm die Hand und fordere ihn auf, dir die Hand zu geben."},{"verse":5,"text":"Wenn es ein Engel ist, so wird er es tun, und du wirst seine Hand fühlen."},{"verse":6,"text":"Wenn es der Geist eines gerechten Menschen ist, der vollkommen gemacht worden ist, so wird er in seiner Herrlichkeit kommen, denn das ist die einzige Weise, wie er erscheinen kann –"},{"verse":7,"text":"fordere ihn auf, dir die Hand zu geben, und er wird sich nicht rühren, denn es widerspricht der Ordnung des Himmels, dass ein gerechter Mensch täuscht; aber er wird dennoch seine Botschaft ausrichten."},{"verse":8,"text":"Wenn es der Teufel als ein Engel des Lichts ist und du ihn aufforderst, dir die Hand zu geben, so wird er dir die Hand reichen, und du wirst nichts fühlen, deshalb kannst du ihn entlarven."},{"verse":9,"text":"Dies sind drei wichtige Schlüssel, womit man erkennen kann, ob eine Kundgebung von Gott ist."}]},{"chapter":130,"verses":[{"verse":1,"text":"Wenn der Erretter erscheinen wird, werden wir ihn so sehen, wie er ist. Wir werden sehen, dass er ein Mensch ist gleichwie wir."},{"verse":2,"text":"Und derselbe gesellige Umgang, der unter uns hier vorhanden ist, wird auch dort unter uns vorhanden sein, nur wird er mit ewiger Herrlichkeit verbunden sein, welcher Herrlichkeit wir uns jetzt noch nicht erfreuen."},{"verse":3,"text":"Johannes 14:23 – Das Erscheinen des Vaters und des Sohnes, in diesem Vers, ist ein persönliches Erscheinen; und die Vorstellung, dass der Vater und der Sohn im Herzen eines Menschen wohnen, ist ein alter sektiererischer Gedanke, der falsch ist."},{"verse":4,"text":"Als Antwort auf die Frage: Ist nicht die Zeitrechnung Gottes, die der Engel, die der Propheten und die der Menschen jeweils von dem Planeten abhängig, auf dem sie wohnen?"},{"verse":5,"text":"antworte ich: Ja. Aber es gibt keine Engel, die dieser Erde dienen, die nicht auch zu ihr gehören oder gehört haben."},{"verse":6,"text":"Die Engel wohnen nicht auf einem Planeten wie diese Erde,"},{"verse":7,"text":"sondern sie wohnen in der Gegenwart Gottes, auf einem Himmelskörper wie ein Meer von Glas und Feuer, wo alles für ihre Herrlichkeit offenbar ist – Vergangenes, Gegenwärtiges und Zukünftiges – und sich beständig vor dem Herrn befindet."},{"verse":8,"text":"Der Ort, wo Gott wohnt, ist ein großer Urim und Tummim."},{"verse":9,"text":"Diese Erde wird in ihrem geheiligten und unsterblichen Zustand kristallgleich gemacht werden und wird für die Bewohner, die darauf wohnen, ein Urim und Tummim sein, wodurch alles, was ein tieferstehendes Reich betrifft, oder alle Reiche einer niedrigeren Ordnung, denen, die darauf wohnen, offenbar sein wird; und diese Erde wird Christus gehören."},{"verse":10,"text":"Dann wird der weiße Stein, der in Offenbarung 2:17 erwähnt ist, für jeden, der einen empfängt, zu einem Urim und Tummim werden, wodurch das, was eine höhere Ordnung der Reiche betrifft, kundgetan werden wird;"},{"verse":11,"text":"und einem jeden von denen, die in das celestiale Reich gelangen, wird ein weißer Stein gegeben, worauf ein neuer Name geschrieben ist, den kein Mensch kennt als nur der, der ihn empfängt. Der neue Name ist das Schlüsselwort."},{"verse":12,"text":"Ich prophezeie im Namen Gottes, des Herrn, dass die Schwierigkeiten, die vor dem Kommen des Menschensohnes viel Blutvergießen verursachen werden, ihren Anfang in South Carolina nehmen werden."},{"verse":13,"text":"Es wird wahrscheinlich infolge der Sklavenfrage dazu kommen. Dies hat mir eine Stimme verkündet, während ich am 25. Dezember 1832 ernstlich darüber betete."},{"verse":14,"text":"Ich betete einmal sehr ernstlich, um die Zeit zu erfahren, wann des Menschen Sohn kommen werde; da hörte ich eine Stimme Folgendes sagen:"},{"verse":15,"text":"Joseph, mein Sohn, wenn du lebst, bis du fünfundachtzig Jahre alt bist, wirst du das Antlitz des Menschensohnes sehen; darum lass dir dies genügen, und behellige mich in dieser Sache nicht mehr."},{"verse":16,"text":"So verblieb ich, ohne imstande zu sein zu erkennen, ob dieses Kommen sich auf den Anfang des Millenniums oder auf ein vorhergehendes Erscheinen bezieht oder ob ich sterben und so sein Antlitz sehen würde."},{"verse":17,"text":"Ich glaube aber, des Menschen Sohn wird nicht früher kommen als zur genannten Zeit."},{"verse":18,"text":"Jeglicher Grundzug der Intelligenz, den wir uns in diesem Leben zu eigen machen, wird mit uns in der Auferstehung hervorkommen."},{"verse":19,"text":"Und wenn jemand in diesem Leben durch seinen Eifer und Gehorsam mehr Wissen und Intelligenz erlangt als ein anderer, so wird er in der künftigen Welt um so viel im Vorteil sein."},{"verse":20,"text":"Es gibt ein Gesetz, das im Himmel vor den Grundlegungen dieser Welt unwiderruflich angeordnet wurde und auf dem alle Segnungen beruhen –"},{"verse":21,"text":"und wenn wir irgendeine Segnung von Gott erlangen, dann nur, indem wir das Gesetz beachten, auf dem sie beruht."},{"verse":22,"text":"Der Vater hat einen Körper aus Fleisch und Gebein, so fühlbar wie der eines Menschen, ebenso der Sohn; aber der Heilige Geist hat keinen Körper aus Fleisch und Gebein, sondern ist eine Person aus Geist. Wäre es nicht so, könnte der Heilige Geist nicht in uns wohnen."},{"verse":23,"text":"Ein Mensch kann den Heiligen Geist empfangen, und dieser kann auf ihn herabkommen, muss aber nicht bei ihm verweilen."}]},{"chapter":131,"verses":[{"verse":1,"text":"In der celestialen Herrlichkeit gibt es drei Himmel oder Grade,"},{"verse":2,"text":"und um den höchsten zu erlangen, muss man in diese Ordnung des Priestertums [nämlich den neuen und immerwährenden Bund der Ehe] eintreten;"},{"verse":3,"text":"und wenn jemand das nicht tut, so kann er ihn nicht erlangen."},{"verse":4,"text":"Er kann in einen anderen eingehen, aber das ist das Ende seines Reiches; er kann keine Vermehrung haben."},{"verse":5,"text":"(17. Mai 1843) Das sicherere Prophezeiungswort bedeutet: Man weiß, dass man für das ewige Leben versiegelt ist – durch Offenbarung und den Geist der Prophezeiung, mittels der Macht des Heiligen Priestertums."},{"verse":6,"text":"Es ist unmöglich, dass man in Unwissenheit errettet wird."},{"verse":7,"text":"So etwas wie unstoffliche Materie gibt es nicht. Aller Geist ist Materie, aber er ist feiner oder reiner und kann nur von reineren Augen erkannt werden;"},{"verse":8,"text":"wir können ihn nicht sehen, aber wenn unser Körper einmal rein gemacht sein wird, werden wir sehen, dass Geist nichts anderes ist als Materie."}]},{"chapter":132,"verses":[{"verse":1,"text":"Wahrlich, so spricht der Herr zu dir, mein Diener Joseph: Da du von meiner Hand erfragt hast und wissen und verstehen willst, inwiefern ich, der Herr, meine Diener Abraham, Isaak und Jakob gerechtfertigt habe, und auch Mose, David und Salomo, meine Diener, was den Grundsatz und die Lehre betrifft, dass sie viele Frauen und Nebenfrauen gehabt haben –"},{"verse":2,"text":"siehe, ja, siehe, ich bin der Herr, dein Gott, und werde dir, was diese Sache betrifft, Antwort geben."},{"verse":3,"text":"Darum bereite dein Herz vor, die Weisungen zu empfangen und zu beachten, die ich im Begriff bin, dir zu geben; denn alle, denen dieses Gesetz offenbart wird, müssen es befolgen."},{"verse":4,"text":"Denn siehe, ich offenbare euch einen neuen und einen immerwährenden Bund; und wenn ihr euch an diesen Bund nicht haltet, so seid ihr verdammt; denn niemand kann diesen Bund verwerfen und dennoch in meine Herrlichkeit eingelassen werden."},{"verse":5,"text":"Denn alle, die aus meinen Händen eine Segnung haben wollen, müssen sich an das für diese Segnung bestimmte Gesetz und seine Bedingungen halten, wie sie von vor der Grundlegung der Welt an festgelegt sind."},{"verse":6,"text":"Und was den neuen und immerwährenden Bund betrifft, so wurde er für die Fülle meiner Herrlichkeit festgelegt; und wer eine Fülle davon empfängt, muss und wird sich an das Gesetz halten, sonst wird er verdammt sein, spricht Gott, der Herr."},{"verse":7,"text":"Und wahrlich, ich sage euch: Die Bedingungen dieses Gesetzes sind: Alle Bündnisse, Verträge, Verbindlichkeiten, Verpflichtungen, Eide, Gelöbnisse, Handlungen, Bindungen, Vereinbarungen und Erwartungen, die nicht sowohl für die Zeit als auch für alle Ewigkeit geschlossen und eingegangen und vom Heiligen Geist der Verheißung gesiegelt werden – durch den, der gesalbt ist –, und das auch auf höchst heilige Weise durch Offenbarung und Gebot mittels meines Gesalbten, den ich dazu bestimmt habe, auf Erden diese Macht innezuhaben (und ich habe meinen Diener Joseph bestimmt, dass er diese Macht in den letzten Tagen innehaben soll, und es gibt auf Erden zu einer Zeit immer nur einen, dem diese Macht und die Schlüssel dieses Priestertums übertragen sind), haben bei der Auferstehung von den Toten und danach keinerlei Wirksamkeit, Kraft und Gültigkeit; denn alle Verträge, die nicht zu diesem Zweck geschlossen werden, haben ein Ende, wenn die Menschen tot sind."},{"verse":8,"text":"Siehe, mein Haus ist ein Haus der Ordnung, spricht Gott, der Herr, und nicht ein Haus der Verwirrung."},{"verse":9,"text":"Werde ich ein Opfer annehmen, spricht der Herr, das nicht in meinem Namen dargebracht wird?"},{"verse":10,"text":"Oder werde ich aus euren Händen etwas annehmen, was ich nicht bestimmt habe?"},{"verse":11,"text":"Und werde ich euch etwas bestimmen, spricht der Herr, außer durch ein Gesetz, so wie ich und mein Vater es für euch verordnet haben, ehe die Welt war?"},{"verse":12,"text":"Ich bin der Herr, dein Gott, und ich gebe euch dies Gebot: Niemand wird zum Vater kommen außer durch mich oder durch mein Wort, nämlich mein Gesetz, spricht der Herr."},{"verse":13,"text":"Und alles, was in der Welt ist, sei es von Menschen verordnet, von Thronen oder Fürstentümern oder Mächten, oder sei es etwas Namhaftes, was immer es auch sei, und was nicht durch mich oder durch mein Wort ist, spricht der Herr, wird umgestoßen werden und wird nicht bestehen bleiben, sobald die Menschen tot sind, weder bei der Auferstehung noch danach, spricht der Herr, dein Gott."},{"verse":14,"text":"Denn was auch immer bestehen bleibt, ist von mir; und was auch immer nicht von mir ist, wird erschüttert und vernichtet werden."},{"verse":15,"text":"Wenn darum in der Welt ein Mann eine Frau heiratet, und er heiratet sie nicht durch mich oder durch mein Wort, und er macht mit ihr einen Bund, solange er in der Welt ist und sie mit ihm, so sind ihr Bund und ihre Ehe nicht mehr in Kraft, wenn sie tot sind und wenn sie außerhalb der Welt sind; darum sind sie durch keinerlei Gesetz verbunden, wenn sie außerhalb der Welt sind."},{"verse":16,"text":"Darum werden sie, wenn sie außerhalb der Welt sind, weder heiraten noch verheiratet werden, sondern werden zu Engeln im Himmel bestimmt; und diese Engel sind geistliche Diener, um denen zu dienen, die eines vermehrten und eines überaus größeren und eines ewigen Maßes an Herrlichkeit würdig sind."},{"verse":17,"text":"Denn diese Engel haben sich nicht an mein Gesetz gehalten; darum können sie nicht größer gemacht werden, sondern bleiben gesondert und ledig, ohne Erhöhung, in ihrem erretteten Zustand bis in alle Ewigkeit und sind hinfort keine Götter, sondern sind Engel Gottes für immer und immer."},{"verse":18,"text":"Und weiter, wahrlich, ich sage euch: Wenn ein Mann eine Frau heiratet und mit ihr einen Bund für die Zeit und für alle Ewigkeit schließt, und dieser Bund ist nicht durch mich oder durch mein Wort, nämlich mein Gesetz, und ist nicht durch den Heiligen Geist der Verheißung gesiegelt, durch den, den ich zu dieser Macht gesalbt und bestimmt habe, dann ist er weder gültig noch in Kraft, wenn sie außerhalb der Welt sind, weil sie nicht durch mich verbunden worden sind, spricht der Herr, noch durch mein Wort; wenn sie außerhalb der Welt sind, kann dieser dort nicht empfangen werden, weil dort die Engel und die Götter bestimmt sind, an denen sie nicht vorüber können; darum können sie meine Herrlichkeit nicht ererben; denn mein Haus ist ein Haus der Ordnung, spricht Gott, der Herr."},{"verse":19,"text":"Und weiter, wahrlich, ich sage euch: Wenn ein Mann eine Frau heiratet, durch mein Wort, nämlich mein Gesetz, und durch den neuen und immerwährenden Bund, und dieser wird vom Heiligen Geist der Verheißung auf sie gesiegelt, durch den, der gesalbt ist und den ich zu dieser Macht und zu den Schlüsseln dieses Priestertums bestimmt habe, und es wird ihnen gesagt: Ihr werdet in der ersten Auferstehung hervorkommen, und wenn es nach der ersten Auferstehung ist, dann in der nächsten Auferstehung, und werdet Throne, Reiche, Fürstentümer und Mächte, Königreiche und alle Höhen und Tiefen ererben – dann wird es in des Lammes Buch des Lebens geschrieben werden, dass er keinen Mord begehen soll, wodurch unschuldiges Blut vergossen würde, und wenn sie in meinem Bund verbleiben und keinen Mord begehen, wodurch unschuldiges Blut vergossen würde, dann wird ihnen alles geschehen, was auch immer mein Diener ihnen zugebilligt hat – in der Zeit und durch alle Ewigkeit, und wird in voller Kraft sein, wenn sie außerhalb der Welt sind, und sie werden an den Engeln und den Göttern, die dort hingestellt sind, vorbeigehen zu ihrer Erhöhung und Herrlichkeit in allem, wie es auf ihr Haupt gesiegelt worden ist, und diese Herrlichkeit wird eine Fülle und ein ewiger Fortbestand der Nachkommenschaft sein, für immer und immer."},{"verse":20,"text":"Dann werden sie Götter sein, weil sie kein Ende haben; darum werden sie vom Immerwährenden zum Immerwährenden sein, weil sie weiterbestehen; dann werden sie über allem sein, weil alles ihnen untertan ist. Dann werden sie Götter sein, weil sie alle Macht haben und die Engel ihnen untertan sind."},{"verse":21,"text":"Wahrlich, wahrlich, ich sage euch: Wenn ihr nicht nach meinem Gesetz lebt, könnt ihr diese Herrlichkeit nicht erlangen."},{"verse":22,"text":"Denn eng ist die Pforte und schmal der Weg, der zur Erhöhung und zur Fortsetzung der Leben führt, und wenige sind es, die ihn finden, weil ihr mich in der Welt nicht empfangt und mich auch nicht kennt."},{"verse":23,"text":"Aber wenn ihr mich in der Welt empfangt, dann werdet ihr mich erkennen und werdet eure Erhöhung empfangen, damit, wo ich bin, auch ihr sein werdet."},{"verse":24,"text":"Das sind die ewigen Leben: den allein weisen und wahren Gott zu erkennen, und Jesus Christus, den er gesandt hat. Ich bin es. Empfangt darum mein Gesetz."},{"verse":25,"text":"Weit ist die Pforte und breit der Weg, der zu den Toden führt, und viele sind es, die da hineingehen, weil sie mich nicht empfangen und sich auch nicht an mein Gesetz halten."},{"verse":26,"text":"Wahrlich, wahrlich, ich sage euch: Wenn ein Mann eine Frau gemäß meinem Wort heiratet und sie durch den Heiligen Geist der Verheißung gesiegelt werden, wie ich es bestimmt habe, und er oder sie irgendeine Sünde oder irgendwelche Übertretung des neuen und immerwährenden Bundes begeht und Lästerungen jeglicher Art und wenn sie keinen Mord begehen, wodurch sie unschuldiges Blut vergießen, so werden sie dennoch in der ersten Auferstehung hervorkommen und in ihre Erhöhung eingehen; aber sie werden im Fleisch zerschlagen werden und werden bis zum Tag der Erlösung den Schlägen des Satans ausgeliefert sein, spricht Gott, der Herr."},{"verse":27,"text":"Die Lästerung gegen den Heiligen Geist, die weder in der Welt noch außerhalb der Welt vergeben werden wird, besteht darin, dass ihr einen Mord begeht, wodurch ihr unschuldiges Blut vergießt und meinem Tod zustimmt, nachdem ihr meinen neuen und immerwährenden Bund empfangen habt, spricht Gott, der Herr; und wer sich nicht an dieses Gesetz hält, kann keinesfalls in meine Herrlichkeit eingehen, sondern wird verdammt sein, spricht der Herr."},{"verse":28,"text":"Ich bin der Herr, dein Gott, und werde dir das Gesetz meines Heiligen Priestertums geben, wie es von mir und meinem Vater verordnet wurde, ehe die Welt war."},{"verse":29,"text":"Abraham empfing alles, was auch immer er empfing, durch Offenbarung und Gebot, durch mein Wort, spricht der Herr, und ist in seine Erhöhung eingegangen und sitzt auf seinem Thron."},{"verse":30,"text":"Abraham empfing Verheißungen in Bezug auf seine Nachkommen und die Frucht seiner Lenden – aus dessen Lenden du, nämlich mein Diener Joseph, bist –, die weiterbestehen sollten, solange sie in der Welt wären; und was nun Abraham und seine Nachkommen betrifft, auch außerhalb der Welt sollten sie weiterbestehen; sowohl in der Welt als auch außerhalb der Welt sollten sie weiterbestehen, so unzählbar wie die Sterne – ja, selbst wenn ihr den Sand am Ufer des Meeres zählen könntet, so könntet ihr sie doch nicht zählen."},{"verse":31,"text":"Diese Verheißung gilt auch für euch, weil ihr von Abraham seid und die Verheißung an Abraham gegeben wurde; und durch dieses Gesetz wird die Fortsetzung der Werke meines Vaters bewirkt, worin er sich selbst verherrlicht."},{"verse":32,"text":"Geht darum hin und tut die Werke Abrahams; tretet in mein Gesetz ein, dann werdet ihr errettet werden."},{"verse":33,"text":"Wenn ihr aber nicht in mein Gesetz eintretet, so könnt ihr die Verheißung meines Vaters, die er Abraham gemacht hat, nicht empfangen."},{"verse":34,"text":"Gott gebot Abraham, und Sara gab Abraham die Hagar zur Frau. Und warum tat sie das? Weil es das Gesetz war; und aus Hagar entsprangen viele Völker. Darum war dies, unter anderem, die Erfüllung der Verheißungen."},{"verse":35,"text":"Befand sich Abraham deshalb unter Schuldspruch? Wahrlich, ich sage euch: Nein; denn ich, der Herr, hatte es geboten."},{"verse":36,"text":"Abraham erhielt das Gebot, seinen Sohn Isaak darzubringen; und doch stand geschrieben: Du sollst nicht töten. Abraham jedoch weigerte sich nicht, und es wurde ihm als Rechtschaffenheit angerechnet."},{"verse":37,"text":"Abraham empfing Nebenfrauen, und diese gebaren ihm Kinder; und das wurde ihm als Rechtschaffenheit angerechnet, weil sie ihm gegeben worden waren, und er verblieb in meinem Gesetz; wie auch Isaak und Jakob nichts anderes taten, als was ihnen geboten worden war; und weil sie nichts anderes taten, als was ihnen geboten worden war, sind sie gemäß den Verheißungen in ihre Erhöhung eingegangen und sitzen auf Thronen und sind nicht Engel, sondern sind Götter."},{"verse":38,"text":"David empfing ebenfalls viele Frauen und Nebenfrauen, und auch Salomo und Mose, meine Diener, ebenso viele andere meiner Diener vom Anfang der Schöpfung an bis zu dieser Zeit; und in nichts sündigten sie als nur in dem, was sie nicht von mir empfangen hatten."},{"verse":39,"text":"Davids Frauen und Nebenfrauen wurden ihm von mir durch die Hand Natans, meines Dieners, gegeben sowie anderer Propheten, die die Schlüssel dieser Macht innehatten; und in nichts von diesem hat er gegen mich gesündigt als nur im Fall des Urija und dessen Frau; und darum ist er von seiner Erhöhung gefallen und hat sein Teil empfangen; und außerhalb der Welt wird er seine Frauen nicht ererben, denn ich habe sie einem anderen gegeben, spricht der Herr."},{"verse":40,"text":"Ich bin der Herr, dein Gott, und ich habe dir, mein Diener Joseph, eine Aufgabe bestimmt und stelle alles wieder her. Bitte, um was du willst, und es wird dir gegeben werden, gemäß meinem Wort."},{"verse":41,"text":"Und da du mich in Bezug auf Ehebruch gefragt hast – wahrlich, wahrlich, ich sage euch: Wenn ein Mann im neuen und immerwährenden Bund eine Frau empfängt und wenn sie mit einem anderen Mann ist, den ich ihr nicht durch die heilige Salbung bestimmt habe, so hat sie Ehebruch begangen und wird vernichtet werden."},{"verse":42,"text":"Wenn sie nicht im neuen und immerwährenden Bund ist, und sie ist mit einem anderen Mann, so hat sie Ehebruch begangen."},{"verse":43,"text":"Und wenn ihr Mann mit einer anderen Frau ist, und er war unter einem Gelöbnis, so hat er sein Gelöbnis gebrochen und hat Ehebruch begangen."},{"verse":44,"text":"Und wenn sie keinen Ehebruch begangen hat, sondern unschuldig ist und ihr Gelöbnis nicht gebrochen hat und sie das weiß und ich es dir, mein Diener Joseph, offenbare, so wirst du durch die Macht meines Heiligen Priestertums die Macht haben, sie zu nehmen und sie dem zu geben, der keinen Ehebruch begangen hat, sondern treu gewesen ist; denn er wird zum Herrscher über vieles gemacht werden."},{"verse":45,"text":"Denn ich habe dir die Schlüssel sowie die Macht des Priestertums übertragen, wodurch ich alles wiederherstelle und dir alles zu gegebener Zeit kundtue."},{"verse":46,"text":"Und wahrlich, wahrlich, ich sage dir: Was auch immer du auf Erden siegelst, wird im Himmel gesiegelt sein, und was auch immer du in meinem Namen und durch mein Wort auf Erden bindest, spricht der Herr, das wird ewiglich in den Himmeln gebunden sein; und wessen Sünden auch immer du auf Erden erlässt, dem werden sie ewiglich in den Himmeln erlassen sein; und wessen Sünden auch immer du auf Erden behältst, dem werden sie im Himmel behalten sein."},{"verse":47,"text":"Und weiter, wahrlich, ich sage: Wen auch immer du segnest, den werde ich segnen, und wen auch immer du verfluchst, den werde ich verfluchen, spricht der Herr; denn ich, der Herr, bin dein Gott."},{"verse":48,"text":"Und weiter, wahrlich, ich sage dir, mein Diener Joseph: Was auch immer du auf Erden gibst, und wem auch immer du auf Erden jemanden durch mein Wort und gemäß meinem Gesetz gibst – mit Segnungen und nicht mit Flüchen wird es einhergehen und mit meiner Macht, spricht der Herr, und wird auf Erden und im Himmel ohne Schuldigsprechung sein."},{"verse":49,"text":"Denn ich bin der Herr, dein Gott, und werde mit dir sein, ja, bis ans Ende der Welt und durch alle Ewigkeit; denn wahrlich, ich siegle auf dich deine Erhöhung und bereite dir im Reich meines Vaters einen Thron, bei Abraham, deinem Vater."},{"verse":50,"text":"Siehe, ich habe deine Opfer gesehen und werde alle deine Sünden vergeben; ich habe deine Opfer gesehen, als du dem, was ich dir gesagt habe, gehorsam gewesen bist. Darum gehe hin, und ich werde dir einen Ausweg schaffen, so wie ich Abrahams Opfer angenommen habe, seinen Sohn Isaak darzubringen."},{"verse":51,"text":"Wahrlich, ich sage dir: Ein Gebot gebe ich meiner Magd Emma Smith, deiner Frau, die ich dir gegeben habe, dass sie sich zurückhalte und nicht von dem nehme, was ich dir gebot, ihr anzutragen; denn ich habe es getan, spricht der Herr, um euch alle zu prüfen, wie ich es mit Abraham getan habe, und damit ich aus eurer Hand ein Opfer fordern kann, durch Bündnis und Opfer."},{"verse":52,"text":"Und meine Magd Emma Smith soll alle diejenigen empfangen, die meinem Diener Joseph gegeben worden sind und die vor mir tugendhaft und rein sind; und diejenigen, die nicht rein sind, aber gesagt haben, dass sie rein seien, werden vernichtet werden, spricht Gott, der Herr."},{"verse":53,"text":"Denn ich bin der Herr, dein Gott, und ihr sollt meiner Stimme gehorchen; und ich gebe es meinem Diener Joseph, dass er zum Herrscher über vieles gemacht werden wird; denn er ist über wenigem getreu gewesen, und hinfort werde ich ihn stärken."},{"verse":54,"text":"Und ich gebiete meiner Magd Emma Smith, bei meinem Diener Joseph zu bleiben und an ihm festzuhalten und an niemandem und nichts sonst. Doch wenn sie sich nicht an dieses Gebot hält, wird sie vernichtet werden, spricht der Herr; denn ich bin der Herr, dein Gott, und werde sie vernichten, wenn sie nicht nach meinem Gesetz lebt."},{"verse":55,"text":"Aber wenn sie sich nicht an dieses Gebot hält, dann soll mein Diener Joseph doch alles für sie tun, ja, wie er es gesagt hat; und ich werde ihn segnen und ihn mehren und ihm in dieser Welt hundertfach Väter und Mütter, Brüder und Schwestern, Häuser und Ländereien, Frauen und Kinder geben, und Kronen ewiger Leben in den ewigen Welten."},{"verse":56,"text":"Und weiter, wahrlich, ich sage: Meine Magd soll meinem Diener Joseph seine Verfehlungen vergeben; dann werden auch ihr ihre Verfehlungen vergeben werden, worin sie gegen mich gefehlt hat; und ich, der Herr, dein Gott, werde sie segnen und sie mehren und werde machen, dass ihr Herz sich freut."},{"verse":57,"text":"Und weiter, ich sage: Mein Diener Joseph soll sein Eigentum nicht aus den Händen geben, damit nicht ein Feind komme und ihn vernichte, denn der Satan trachtet danach, zu vernichten; denn ich bin der Herr, dein Gott, und er ist mein Diener; und siehe, ja siehe, ich bin mit ihm, wie ich mit Abraham, deinem Vater, gewesen bin, ja, zu seiner Erhöhung und Herrlichkeit."},{"verse":58,"text":"Was nun das Gesetz des Priestertums betrifft, so gibt es vieles, was dazugehört."},{"verse":59,"text":"Wahrlich, wenn ein Mann von meinem Vater berufen wird wie Aaron, durch meine eigene Stimme und durch die Stimme dessen, der mich gesandt hat, und ich ihn mit den Schlüsseln der Macht dieses Priestertums ausgerüstet habe – wenn er etwas in meinem Namen tut und gemäß meinem Gesetz und durch mein Wort, so begeht er keine Sünde, und ich werde ihn rechtfertigen."},{"verse":60,"text":"Darum soll niemand meinen Diener Joseph bedrängen; denn ich werde ihn rechtfertigen, denn er wird das Opfer bringen, das ich für seine Übertretungen aus seinen Händen fordere, spricht der Herr, euer Gott."},{"verse":61,"text":"Und weiter, was das Gesetz des Priestertums betrifft: Wenn ein Mann eine Jungfrau ehelicht und den Wunsch hat, noch eine andere zu ehelichen, und die erste gibt ihre Zustimmung, und wenn er dann die zweite ehelicht, und sie sind Jungfrauen und haben sich keinem anderen Mann versprochen, dann ist er gerechtfertigt; er kann keinen Ehebruch begehen, denn sie sind ihm gegeben, und mit dem, was ihm gehört und keinem anderen, kann er keinen Ehebruch begehen."},{"verse":62,"text":"Und wenn ihm durch dieses Gesetz zehn Jungfrauen gegeben werden, so kann er doch keinen Ehebruch begehen, denn sie gehören ihm, und sie sind ihm gegeben; darum ist er gerechtfertigt."},{"verse":63,"text":"Wenn aber eine oder irgendeine der zehn Jungfrauen nach ihrer Verehelichung bei einem anderen Mann ist, so hat sie Ehebruch begangen und wird vernichtet werden; denn sie sind ihm gegeben, um sich zu mehren und die Erde zu füllen, gemäß meinem Gebot, und um die Verheißung zu erfüllen, die mein Vater vor der Grundlegung der Welt gegeben hat, und zu ihrer Erhöhung in den ewigen Welten, damit sie Menschenseelen gebären können; denn hierin wird das Werk meines Vaters fortgesetzt, damit er verherrlicht werde."},{"verse":64,"text":"Und weiter, wahrlich, wahrlich, ich sage euch: Wenn ein Mann, der die Schlüssel dieser Macht innehat, eine Frau hat und er sie das Gesetz meines Priestertums lehrt, was nämlich dies alles betrifft, so soll sie glauben und ihm dienen, sonst wird sie vernichtet werden, spricht der Herr, euer Gott; denn ich werde sie vernichten; denn ich werde meinen Namen groß machen über all denen, die mein Gesetz empfangen und danach leben."},{"verse":65,"text":"Darum wird es, wenn sie dieses Gesetz nicht annimmt, vor mir doch recht sein, dass er alles empfängt, was auch immer ich, der Herr, sein Gott, ihm geben werde; denn sie hat nicht geglaubt und ihm nicht gedient, wie es meinem Wort entsprochen hätte; und dann wird sie diejenige sein, die übertritt; und er ist vom Gesetz der Sara ausgenommen, die Abraham gemäß dem Gesetz diente, als ich Abraham gebot, sich die Hagar zur Frau zu nehmen."},{"verse":66,"text":"Und nun, was dieses Gesetz betrifft, wahrlich, wahrlich, ich sage dir: Ich werde dir später noch mehr offenbaren; darum lass dies für jetzt genügen. Siehe, ich bin Alpha und Omega. Amen."}]},{"chapter":133,"verses":[{"verse":1,"text":"Horcht auf, o ihr Volk meiner Kirche, spricht der Herr, euer Gott, und vernehmt das Wort des Herrn in Bezug auf euch –"},{"verse":2,"text":"des Herrn, der plötzlich zu seinem Tempel kommen wird; des Herrn, der mit einem Fluch zum Gericht über die Welt herniederkommen wird, ja, über alle Nationen, die Gott vergessen, und über alle Gottlosen unter euch."},{"verse":3,"text":"Denn er wird seinen heiligen Arm vor den Augen aller Nationen entblößen, und alle Enden der Erde werden die Errettung ihres Gottes sehen."},{"verse":4,"text":"Darum macht euch bereit, macht euch bereit, o mein Volk; heiligt euch, sammelt euch, o ihr Volk meiner Kirche, im Land Zion, ihr alle, denen nicht geboten worden ist zu verweilen."},{"verse":5,"text":"Zieht aus Babylon aus. Seid rein, die ihr die Gefäße des Herrn tragt."},{"verse":6,"text":"Beruft eure feierlichen Versammlungen ein, und sprecht oft miteinander. Und ein jeder soll den Namen des Herrn anrufen."},{"verse":7,"text":"Ja, wahrlich, ich sage euch abermals: Die Zeit ist gekommen, da die Stimme des Herrn an euch ergeht: Zieht aus Babylon aus; sammelt euch aus den Nationen, von den vier Winden her, von einem Ende des Himmels zum anderen."},{"verse":8,"text":"Sendet die Ältesten meiner Kirche hinaus zu den Nationen, die ferne sind, zu den Inseln des Meeres; sendet hin zu fremden Ländern; ruft allen Nationen zu, zuerst den Anderen und dann den Juden."},{"verse":9,"text":"Und siehe, ja siehe, dies soll ihr Ruf sein und die Stimme des Herrn an alle Völker: Geht hin zum Land Zion, damit die Grenzen meines Volkes sich erweitern und damit seine Pfähle gestärkt werden und damit Zion sich in die Gebiete ringsum ausbreite."},{"verse":10,"text":"Ja, lasst den Ruf unter allem Volk erschallen: Wacht auf, und erhebt euch und geht hin, dem Bräutigam entgegen; siehe, ja siehe, der Bräutigam kommt; geht aus, ihm entgegen. Macht euch bereit für den großen Tag des Herrn."},{"verse":11,"text":"Darum wacht, denn ihr wisst weder den Tag noch die Stunde."},{"verse":12,"text":"Darum lasst die, die sich bei den Anderen befinden, nach Zion fliehen."},{"verse":13,"text":"Und lasst die, die von Juda sind, nach Jerusalem fliehen, zu den Bergen, da des Herrn Haus ist."},{"verse":14,"text":"Zieht aus von den Nationen, ja, aus Babylon, mitten aus der Schlechtigkeit, die das geistige Babylon ist."},{"verse":15,"text":"Aber wahrlich, so spricht der Herr: Eure Flucht geschehe nicht in Hast, sondern lasst alles vor euch bereitmachen; und wer geht, der soll nicht zurücksehen, damit nicht plötzliche Vernichtung über ihn komme."},{"verse":16,"text":"Horcht auf und vernehmt, o ihr Bewohner der Erde. Hört allesamt zu, ihr Ältesten meiner Kirche, und vernehmt die Stimme des Herrn; denn er ruft allen Menschen zu, und er gebietet allen Menschen überall, umzukehren."},{"verse":17,"text":"Denn siehe, Gott, der Herr, hat den Engel ausgesandt, der mitten durch den Himmel ruft, nämlich: Bereitet den Weg des Herrn, und macht seine Pfade gerade, denn die Stunde seines Kommens ist nah –"},{"verse":18,"text":"da das Lamm auf dem Berg Zion stehen wird, und mit ihm einhundertvierundvierzigtausend, die den Namen seines Vaters auf der Stirn geschrieben tragen."},{"verse":19,"text":"Darum macht euch bereit für das Kommen des Bräutigams; geht aus, geht aus, ihm entgegen."},{"verse":20,"text":"Denn siehe, er wird auf dem Ölberg stehen und auf dem mächtigen Ozean, ja, der großen Tiefe, und auf den Inseln des Meeres und auf dem Land Zion."},{"verse":21,"text":"Und er wird seine Stimme aus Zion erschallen lassen, und er wird von Jerusalem aus sprechen, und seine Stimme wird unter allen Völkern gehört werden;"},{"verse":22,"text":"und es wird eine Stimme sein wie die Stimme vieler Wasser und wie die Stimme großen Donners, der die Berge zerbrechen wird, und die Täler werden nicht mehr zu finden sein."},{"verse":23,"text":"Er wird der großen Tiefe gebieten, und sie wird in die Länder im Norden zurückgetrieben werden, und die Inseln werden zu einem einzigen Land werden;"},{"verse":24,"text":"und das Land Jerusalem und das Land Zion werden an ihren eigenen Platz zurückgesetzt werden, und die Erde wird wieder so sein, wie sie in den Tagen war, ehe sie geteilt wurde."},{"verse":25,"text":"Und der Herr, ja, der Erretter, wird inmitten seines Volkes stehen und wird über alles Fleisch regieren."},{"verse":26,"text":"Und derer, die in den Ländern im Norden sind, wird vor dem Herrn gedacht werden; und ihre Propheten werden seine Stimme hören und werden sich nicht länger zurückhalten; und sie werden die Felsen schlagen, und das Eis wird in ihrer Gegenwart zerfließen."},{"verse":27,"text":"Und in der Mitte der großen Tiefe wird eine Straße aufgeworfen werden."},{"verse":28,"text":"Ihre Feinde werden ihnen zur Beute werden;"},{"verse":29,"text":"und in den unfruchtbaren Wüsten werden sich Teiche lebenden Wassers bilden, und der ausgedörrte Boden wird nicht länger ein durstiges Land sein."},{"verse":30,"text":"Und sie werden ihre reichen Schätze den Kindern Efraim, meinen Dienern, bringen."},{"verse":31,"text":"Und die Grenzen der immerwährenden Hügel werden vor ihrer Gegenwart erzittern."},{"verse":32,"text":"Und dort werden sie niederfallen und mit Herrlichkeit gekrönt werden, nämlich in Zion, von den Händen der Diener des Herrn, nämlich den Kindern Efraim."},{"verse":33,"text":"Und sie werden von Liedern immerwährender Freude erfüllt sein."},{"verse":34,"text":"Siehe, dies ist der Segen des immerwährenden Gottes auf die Stämme Israel und der reichere Segen auf das Haupt Efraims und seiner Zugehörigen."},{"verse":35,"text":"Und auch die vom Stamm Juda werden nach ihren Leiden vor dem Herrn in Heiligkeit geheiligt werden, dass sie Tag und Nacht in seiner Gegenwart wohnen, für immer und immer."},{"verse":36,"text":"Und nun, wahrlich, der Herr spricht: Damit dies unter euch bekannt sei, o ihr Bewohner der Erde, habe ich meinen Engel gesandt, der mitten durch den Himmel fliegt und das immerwährende Evangelium hat, und er ist einigen erschienen und hat es den Menschen überbracht, und er wird vielen erscheinen, die auf Erden wohnen."},{"verse":37,"text":"Und dieses Evangelium wird jeder Nation, jedem Geschlecht, jeder Sprache und jedem Volk gepredigt werden."},{"verse":38,"text":"Und die Diener Gottes werden hinausgehen und mit lauter Stimme rufen: Fürchtet Gott und gebt ihm die Ehre, denn die Stunde seines Gerichts ist da;"},{"verse":39,"text":"und betet ihn an, der Himmel und Erde gemacht hat und das Meer und die Wasserquellen –"},{"verse":40,"text":"und werden den Namen des Herrn anrufen bei Tag und bei Nacht, nämlich: O dass du doch die Himmel zerrissest, dass du doch herabkämest, dass die Berge vor deiner Gegenwart zerflössen."},{"verse":41,"text":"Und es wird ihnen auf ihr Haupt beantwortet werden, denn die Gegenwart des Herrn wird wie das schmelzende Feuer sein, das brennt, und wie das Feuer, das das Wasser zum Sieden bringt."},{"verse":42,"text":"O Herr, du wirst herabkommen und deinen Widersachern deinen Namen kundtun, und alle Nationen werden vor deiner Gegenwart zittern,"},{"verse":43,"text":"wenn du Furchtbares tust, das, was sie nicht erwartet haben,"},{"verse":44,"text":"ja, wenn du herabkommst und die Berge vor deiner Gegenwart zerfließen, wirst du dem begegnen, der sich freut und Rechtschaffenheit bewirkt, der sich deiner auf deinen Wegen erinnert."},{"verse":45,"text":"Denn seit Anbeginn der Welt haben die Menschen nicht vernommen, weder mit dem Ohr gehört noch hat ein Auge gesehen – außer dir, o Gott –, was du Großes bereitet hast dem, der auf dich wartet."},{"verse":46,"text":"Und man wird sagen: Wer ist das, der von Gott im Himmel herabkommt mit gefärbtem Gewand, ja, aus unbekannten Regionen, angetan mit seinen herrlichen Kleidern, der da schreitet in seiner ganzen großen Stärke?"},{"verse":47,"text":"Und er wird sagen: Ich bin der, der in Rechtschaffenheit gesprochen hat und die Macht hat zu erretten."},{"verse":48,"text":"Und der Herr wird rotfarbene Kleider tragen, und seine Gewänder werden sein wie dessen, der im Weinbottich tritt."},{"verse":49,"text":"Und so groß wird die Herrlichkeit seiner Gegenwart sein, dass die Sonne vor Scham ihr Angesicht verbergen wird, und der Mond wird sein Licht nicht geben, und die Sterne werden aus ihren Plätzen geschleudert werden."},{"verse":50,"text":"Und man wird seine Stimme vernehmen: Ich habe die Weinkelter allein getreten und habe Gericht über alles Volk gebracht; und niemand war bei mir;"},{"verse":51,"text":"und ich habe sie voll Ungestüm zertreten, und ich habe in meinem Zorn auf sie getreten, und mit ihrem Blut habe ich mir die Gewänder besprengt und meine Kleidung ganz befleckt; denn dies war der Tag der Vergeltung, die in meinem Herzen war."},{"verse":52,"text":"Und nun ist das Jahr meiner Erlösten gekommen; und sie werden das liebevolle Wohlwollen ihres Herrn und alles, was er ihnen gemäß seiner Güte und gemäß seinem liebevollen Wohlwollen hat zuteilwerden lassen, rühmen für immer und immer."},{"verse":53,"text":"In all ihren Bedrängnissen war er bedrängt. Und der Engel seiner Gegenwart hat sie errettet; und in seiner Liebe und in seinem Erbarmen hat er sie erlöst und sie getragen und sie gestützt alle Tage vor alters;"},{"verse":54,"text":"ja, und auch Henoch und die mit ihm waren; die Propheten, die vor ihm waren; und auch Noach und die vor ihm waren; und auch Mose und die vor ihm waren;"},{"verse":55,"text":"und von Mose bis Elija, und von Elija bis Johannes, die bei der Auferstehung Christi mit ihm waren, und die heiligen Apostel samt Abraham, Isaak und Jakob werden in der Gegenwart des Lammes sein."},{"verse":56,"text":"Und die Gräber der Heiligen werden sich öffnen, und sie werden hervorkommen und zur rechten Hand des Lammes stehen, wenn dieses auf dem Berg Zion stehen wird und in der heiligen Stadt, dem Neuen Jerusalem; und sie werden das Lied des Lammes singen, bei Tag und bei Nacht, für immer und immer."},{"verse":57,"text":"Und aus dem Grund, damit die Menschen zu Teilhabern der Herrlichkeiten werden können, die offenbart werden sollten, hat der Herr die Fülle seines Evangeliums, seinen immerwährenden Bund, ausgesandt und klar und einfach die Gründe dargelegt,"},{"verse":58,"text":"um die Schwachen vorzubereiten auf das, was auf der Erde kommen wird, und auf den Auftrag des Herrn an dem Tag, da die Schwachen die Weisen beschämen werden und da der Kleinste eine mächtige Nation werden wird und ihrer zwei sogar Zehntausende in die Flucht schlagen werden."},{"verse":59,"text":"Und durch das Schwache der Erde wird der Herr die Nationen mit der Macht seines Geistes dreschen."},{"verse":60,"text":"Und aus dem Grund sind diese Gebote gegeben worden; am Tag, als sie gegeben wurden, da wurde geboten, sie der Welt vorzuenthalten, aber jetzt sollen sie an alles Fleisch ergehen –"},{"verse":61,"text":"und dies gemäß dem Sinn und Willen des Herrn, der über alles Fleisch herrscht."},{"verse":62,"text":"Und dem, der umkehrt und sich vor dem Herrn heiligt, wird ewiges Leben gegeben."},{"verse":63,"text":"Und an denen, die nicht auf die Stimme des Herrn hören, wird sich erfüllen, was der Prophet Mose geschrieben hat, dass sie aus dem Volk ausgeschlossen werden sollen,"},{"verse":64,"text":"und auch das, was der Prophet Maleachi geschrieben hat: Denn siehe, der Tag kommt, der brennen wird wie ein Ofen; und alle Stolzen, ja, und alle, die Schlechtes tun, werden Stoppeln sein; und der Tag, der kommt, wird sie verbrennen, spricht der Herr der Heerscharen, sodass er ihnen nicht Wurzel noch Zweig lassen wird."},{"verse":65,"text":"Darum wird dies die Antwort des Herrn an sie sein:"},{"verse":66,"text":"An dem Tag, da ich zu den Meinen kam, hat niemand unter euch mich empfangen, und ihr wurdet verjagt."},{"verse":67,"text":"Als ich abermals rief, war niemand von euch da, zu antworten; doch war mein Arm keineswegs verkürzt, dass ich nicht hätte erlösen können, ebenso wenig meine Macht, zu befreien."},{"verse":68,"text":"Siehe, mit meiner Zurechtweisung trockne ich das Meer aus. Ich mache die Flüsse zur Wildnis; ihre Fische stinken und sterben vor Durst."},{"verse":69,"text":"Ich kleide die Himmel in Schwärze und mache Sackleinen zu ihrer Hülle."},{"verse":70,"text":"Und dies werdet ihr von meiner Hand erhalten – ihr werdet euch in Kummer niederlegen."},{"verse":71,"text":"Siehe, ja siehe, es gibt niemand, der euch befreit; denn ihr habt meiner Stimme nicht gehorcht, als ich euch aus den Himmeln zurief; ihr habt meinen Dienern nicht geglaubt, und als sie zu euch gesandt wurden, habt ihr sie nicht empfangen."},{"verse":72,"text":"Darum haben sie das Zeugnis versiegelt und das Gesetz zugebunden, und ihr seid der Finsternis ausgeliefert worden."},{"verse":73,"text":"Diese werden hinweggehen in die äußere Finsternis, wo es Weinen und Wehklagen und Zähneknirschen gibt."},{"verse":74,"text":"Siehe, der Herr, euer Gott, hat es gesprochen. Amen."}]},{"chapter":134,"verses":[{"verse":1,"text":"Wir glauben, dass Regierungen von Gott zum Nutzen des Menschen eingerichtet worden sind und dass er die Menschen für ihr Verhalten in Bezug auf sie zur Rechenschaft zieht, sei es im Geben von Gesetzen oder in deren Anwendung zum Wohl und zur Sicherheit der Gesellschaft."},{"verse":2,"text":"Wir glauben, dass keine Regierung friedlich bestehen kann, ohne dass solche Gesetze erlassen werden und unangetastet bleiben, die jedem Einzelnen die Wahrnehmung seiner Gewissensfreiheit, das Recht auf Eigentum und freie Verfügung darüber und den Schutz des Lebens gewährleisten."},{"verse":3,"text":"Wir glauben, dass alle Regierungen notwendigerweise staatliche Beamte und Behörden brauchen, um ihre Gesetze durchzusetzen; und dass solche, die das Gesetz unparteiisch und gerecht anwenden, gesucht und gestützt werden sollen – durch die Stimme des Volkes, wenn in einer Republik, oder durch den Willen des Landesherrn."},{"verse":4,"text":"Wir glauben, dass die Religion von Gott eingerichtet worden ist und dass die Menschen ihm, und nur ihm, für die Ausübung derselben verantwortlich sind, sofern ihre religiösen Ansichten sie nicht dazu veranlassen, die Rechte und Freiheiten anderer zu verletzen; aber wir glauben nicht, dass menschliches Gesetz das Recht hat, sich einzumischen und Regeln für die Gottesverehrung vorzuschreiben, um Gewissenszwang auszuüben oder Formen öffentlicher oder privater Gottesverehrung zu diktieren; dass staatliche Behörden das Verbrechen unterbinden sollen, aber niemals das Gewissen überwachen; Missetat bestrafen sollen, aber niemals die Freiheit der Seele unterdrücken."},{"verse":5,"text":"Wir glauben, dass alle Menschen verpflichtet sind, die jeweilige Regierung, unter der sie leben, zu stützen und zu tragen, solange sie durch die Gesetze dieser Regierung in ihren angeborenen und unveräußerlichen Rechten geschützt werden; und dass allen so beschützten Bürgern Aufstand und Auflehnung nicht zustehen und entsprechend bestraft werden sollen; und dass jede Regierung das Recht hat, solche Gesetze anzuwenden, die nach ihrem Urteil am besten geeignet sind, das öffentliche Wohl zu sichern; zugleich aber sollen sie die Gewissensfreiheit heilighalten."},{"verse":6,"text":"Wir glauben, dass jedermann in seiner Stellung geachtet werden soll, Herrschende und Vertreter der Staatsmacht als solche, denn sie sind eingesetzt, um die Unschuldigen zu schützen und die Schuldigen zu bestrafen, und dass alle Menschen den Gesetzen Achtung und Unterordnung schulden, da ohne sie Friede und Eintracht durch Anarchie und Terror verdrängt würden; menschliche Gesetze sind ausdrücklich zu dem Zweck geschaffen, unsere Interessen als Einzelne und als Nationen zu regeln, zwischen einem Menschen und dem anderen; und göttliche Gesetze sind vom Himmel gegeben und schreiben Regeln für geistige Belange vor, für Glauben und Gottesverehrung; für beides ist der Mensch seinem Schöpfer verantwortlich."},{"verse":7,"text":"Wir glauben, dass Herrscher, Staaten und Regierungen das Recht haben und verpflichtet sind, Gesetze anzuwenden, die alle Bürger bei der freien Ausübung ihres religiösen Glaubens schützen; aber wir glauben nicht, dass sie das Recht haben, Bürger dieser Freiheit rechtens zu berauben oder sie in ihren Ansichten zu beschneiden, solange die Gesetze geachtet und in Ehren gehalten werden und diese religiösen Ansichten nicht Aufstand und Verschwörung gutheißen."},{"verse":8,"text":"Wir glauben, dass das Begehen eines Verbrechens gemäß der Art des Verstoßes bestraft werden soll, dass Mord, Hochverrat, Raub, Diebstahl und Landfriedensbruch in jeder Hinsicht gemäß ihrer Strafbarkeit und der Absicht, unter den Menschen Böses zu stiften, bestraft werden sollen, und zwar nach den Gesetzen jener Regierung, wo der Verstoß begangen worden ist; und für den öffentlichen Frieden und die öffentliche Ruhe sollen alle Menschen eintreten und nach Kräften dazu beitragen, dass diejenigen, die gegen gute Gesetze verstoßen, der Bestrafung zugeführt werden."},{"verse":9,"text":"Wir glauben nicht, dass es recht ist, religiöse Einflussnahme und staatliche Regierung zu vermischen, wodurch die eine Religionsgesellschaft begünstigt, die andere aber in ihren geistigen Freiheiten beschnitten würde und ihren Mitgliedern die persönlichen Rechte als Bürger verweigert würden."},{"verse":10,"text":"Wir glauben, dass alle Religionsgesellschaften das Recht haben, mit ihren Mitgliedern wegen ordnungswidrigen Verhaltens gemäß den Regeln und Statuten der betreffenden Gesellschaft zu verfahren, vorausgesetzt, dass solche Verfahren sich auf die Zugehörigkeit zur Gemeinschaft und den Stand in derselben beziehen; wir glauben aber nicht, dass irgendeine Religionsgesellschaft die Vollmacht hat, über jemandes Recht auf Eigentum oder Leben zu verhandeln, ihnen die Güter dieser Welt abzunehmen oder ihren Leib oder ihr Leben in Gefahr zu bringen oder irgendeine körperliche Strafe über sie zu verhängen. Sie können sie nur aus ihrer Gesellschaft ausschließen und ihnen die Gemeinschaft entziehen."},{"verse":11,"text":"Wir glauben, dass man sich zur Wiedergutmachung allen Unrechts und alles Erlittenen auf das bürgerliche Recht berufen soll, wenn es sich um persönliche Übergriffe handelt oder das Recht auf Eigentum und Persönlichkeit verletzt ist, sofern Gesetze vorhanden sind, die diesen Schutz bieten; wir glauben aber auch, dass alle Menschen berechtigt sind, sich selbst, ihre Freunde, ihr Eigentum und die Regierung in einer Notlage gegen ungesetzliche Anschläge und Übergriffe von jedweder Seite zu verteidigen, wo man sich nicht unverzüglich auf die Gesetze berufen und Abhilfe nicht geschaffen werden kann."},{"verse":12,"text":"Wir glauben, dass es recht ist, den Nationen der Erde das Evangelium zu predigen und die Rechtschaffenen zu warnen, sich aus der Verdorbenheit der Welt zu erretten; aber wir glauben nicht, dass es recht ist, sich bei Leibeigenen einzumischen, ihnen das Evangelium zu predigen oder sie zu taufen, wenn dies dem Willen und Wunsch ihrer Herren widerspricht, noch uns mit ihnen einzulassen oder sie auch nur im Geringsten dahingehend zu beeinflussen, dass sie mit ihren Umständen in diesem Leben unzufrieden sind, und dadurch das Leben von Menschen zu gefährden; eine solche Einmischung halten wir für ungesetzlich und ungerecht und betrachten sie als Gefahr für den Frieden einer jeden Regierung, die zulässt, dass menschliche Wesen in Knechtschaft gehalten werden."}]},{"chapter":135,"verses":[{"verse":1,"text":"Um das Zeugnis dieses Buches und des Buches Mormon zu besiegeln, geben wir den Märtyrertod des Propheten Joseph Smith und des Patriarchen Hyrum Smith bekannt. Sie wurden am 27. Juni 1844 um ungefähr fünf Uhr nachmittags im Gefängnis von Carthage erschossen – von einem bewaffneten, geschwärzten Pöbel von etwa 150 bis 200 Personen. Hyrum wurde zuerst getroffen und fiel mit dem Ausruf: Ich bin des Todes! ruhig nieder. Joseph sprang aus dem Fenster und wurde dabei zu Tode getroffen; er rief aus: O Herr, mein Gott! Auf beide wurde in brutaler Weise noch geschossen, als sie schon tot waren; und beide wurden von je vier Kugeln getroffen."},{"verse":2,"text":"John Taylor und Willard Richards, zwei von den Zwölf, waren zu der Zeit die Einzigen im gleichen Raum; ersterer wurde auf grausame Weise durch vier Kugeln verwundet, ist aber seither genesen; letzterer kam dank der Vorsehung Gottes davon, ohne auch nur ein Loch in seinem Gewand."},{"verse":3,"text":"Joseph Smith, der Prophet und Seher des Herrn, hat mehr für die Errettung der Menschen in dieser Welt getan als irgendein anderer Mensch, der je auf ihr gelebt hat – Jesus allein ausgenommen. In der kurzen Spanne von zwanzig Jahren hat er das Buch Mormon hervorgebracht, das er durch die Gabe und Macht Gottes übersetzte, und ist das Werkzeug zu dessen Veröffentlichung in zwei Erdteilen gewesen; hat er die Fülle des immerwährenden Evangeliums, die darin enthalten ist, an die vier Enden der Erde gesandt; hat er die Offenbarungen und Gebote, die dieses Buch Lehre und Bündnisse bilden, hervorgebracht, dazu noch viele andere weise Dokumente und Belehrungen zum Nutzen der Menschenkinder; hat er viele tausend Heilige der Letzten Tage gesammelt, eine große Stadt gegründet und einen Namen und Ruf hinterlassen, der nicht getötet werden kann. Er war groß im Leben und war groß im Sterben in den Augen Gottes und seines Volkes; und wie die meisten Gesalbten des Herrn in alter Zeit, so hat auch er seine Mission und sein Werk mit seinem eigenen Blut besiegelt; gleichermaßen sein Bruder Hyrum. Im Leben waren sie vereint, und der Tod hat sie nicht getrennt!"},{"verse":4,"text":"Als Joseph sich nach Carthage begab, um sich den angeblichen Forderungen des Gesetzes zu stellen, da sagte er, zwei oder drei Tage vor seiner Ermordung: „Ich gehe wie ein Lamm zum Schlachten, aber ich bin so ruhig wie ein Sommermorgen; mein Gewissen ist frei von Schuld gegenüber Gott und gegenüber allen Menschen. Ich werde unschuldig sterben, und man wird von mir noch sagen: Er wurde kaltblütig ermordet.“ – Am gleichen Morgen las Hyrum, nachdem er sich bereitgemacht hatte zu gehen – soll man sagen: zum Schlachten? Ja!, denn so war es –, den folgenden Absatz kurz vor Ende des zwölften Kapitels von Ether im Buch Mormon und faltete die betreffende Seite ein:"},{"verse":5,"text":"Und es begab sich: Ich betete zum Herrn, er möge den Anderen Gnade erweisen, damit sie Nächstenliebe haben können. Und es begab sich: Der Herr sprach zu mir: Wenn sie keine Nächstenliebe haben, so macht es für dich nichts aus; du bist treu gewesen; darum werden deine Kleider rein gemacht werden. Und weil du deine Schwäche erkannt hast, wirst du stark gemacht werden, ja, sodass du dich an der Stätte niedersetzen kannst, die ich in den Wohnungen meines Vaters bereitet habe. Und nun sage ich … den Anderen Lebewohl, ja, und auch meinen Brüdern, die ich liebe, bis wir uns vor dem Richterstuhl Christi begegnen, wo alle Menschen wissen werden, dass meine Kleider nicht mit eurem Blut befleckt sind. Die das Testament gemacht haben, sind nun tot, und ihr Testament ist in Kraft."},{"verse":6,"text":"Hyrum Smith war im Februar 1844 vierundvierzig Jahre alt geworden, und Joseph Smith war im Dezember 1843 achtunddreißig; und hinfort werden ihre Namen unter die der religiösen Märtyrer eingereiht werden, und der Leser in jeder Nation wird daran erinnert werden, dass das Buch Mormon und dieses Buch, Lehre und Bündnisse der Kirche, das beste Blut des neunzehnten Jahrhunderts gekostet haben, damit diese zur Errettung einer zerrütteten Welt hervorgebracht werden konnten; und wenn das Feuer um der Herrlichkeit Gottes willen schon einen grünen Baum zu versengen vermag, um wie viel leichter wird es die dürren Bäume verbrennen können, um den Weingarten von Verdorbenem zu reinigen. Sie lebten um der Herrlichkeit willen, sie starben um der Herrlichkeit willen, und Herrlichkeit ist ihr ewiger Lohn. Von Zeitalter zu Zeitalter werden ihre Namen der Nachwelt überliefert werden wie Juwelen für die Geheiligten."},{"verse":7,"text":"Sie waren keines Verbrechens schuldig, was schon oft vorher bewiesen worden war, und wurden nur aufgrund der Verschwörung von Verrätern und schlechten Menschen im Gefängnis eingesperrt; und ihr unschuldiges Blut auf dem Fußboden des Gefängnisses zu Carthage ist ein großes Siegel, das dem „Mormonismus“ beigefügt wurde und das von keinem Gerichtshof auf Erden verworfen werden kann; und ihr unschuldiges Blut auf dem Wappen des Staates Illinois ist zusammen mit dem vom Gouverneur verbürgten, aber gebrochenen Wort des Staates für die Wahrheit des immerwährenden Evangeliums ein Zeugnis, das die ganze Welt nicht anfechten kann; und ihr unschuldiges Blut auf dem Banner der Freiheit und auf der Magna Charta der Vereinigten Staaten ist ein Botschafter für die Religion Jesu Christi, der den ehrlichen Menschen in allen Nationen das Herz anrühren wird; und ihr unschuldiges Blut wird zusammen mit dem unschuldigen Blut aller Märtyrer, die Johannes unterhalb des Altares sah, zum Herrn der Heerscharen schreien, bis er dieses Blut an der Erde rächt. Amen."}]},{"chapter":136,"verses":[{"verse":1,"text":"Das Wort und der Wille des Herrn in Bezug auf das Lager Israel auf seiner Reise nach dem Westen:"},{"verse":2,"text":"Alles Volk der Kirche Jesu Christi der Heiligen der Letzten Tage und diejenigen, die mit ihnen reisen, sollen sich in Abteilungen organisieren, mit dem Bündnis und Gelübde, alle Gebote und Satzungen des Herrn, unseres Gottes, zu befolgen."},{"verse":3,"text":"Die Abteilungen sollen mit Hauptleuten über hundert, Hauptleuten über fünfzig und Hauptleuten über zehn organisiert werden, mit einem Präsidenten und seinen zwei Ratgebern an ihrer Spitze, unter der Leitung der Zwölf Apostel."},{"verse":4,"text":"Und dies soll unser Bund sein: Wir wollen nach allen Verordnungen des Herrn wandeln."},{"verse":5,"text":"Jede Abteilung soll sich, so gut sie kann, mit allen Gespannen, Wagen, Vorräten, Kleidung und was sonst für die Reise notwendig ist, versehen."},{"verse":6,"text":"Sobald die Abteilungen organisiert sind, sollen sie mit aller Macht darangehen, um für diejenigen, die verweilen, Vorbereitungen zu treffen."},{"verse":7,"text":"Jede Abteilung mit ihren Hauptleuten und Präsidenten soll entscheiden, wie viele im nächsten Frühjahr aufbrechen können; dann sollen sie eine genügende Anzahl rüstiger und erfahrener Männer auswählen, die unter Mitnahme von Gespannen, Saatgut und landwirtschaftlichen Geräten als Pioniere vorausgehen und den Anbau früher Feldfrucht vorbereiten."},{"verse":8,"text":"Jede Abteilung soll gemäß der verteilbaren Menge ihres Eigentums einen im Verhältnis gleichen Anteil aufbringen, um die Armen, die Witwen, die Vaterlosen und die Familien derer, die im Heeresdienst stehen, mitzunehmen, damit nicht die Schreie der Witwen und der Vaterlosen dem Herrn gegen dieses Volk in die Ohren heraufkommen."},{"verse":9,"text":"Jede Abteilung soll für diejenigen, die dieses Jahr zurückbleiben müssen, Häuser sowie Felder für den Anbau von Getreide herrichten; und das ist der Wille des Herrn in Bezug auf sein Volk."},{"verse":10,"text":"Jeder Einzelne soll seinen ganzen Einfluss und sein ganzes Vermögen aufbieten, um dieses Volk an den Ort zu verlegen, wo der Herr einen Zionspfahl errichten wird."},{"verse":11,"text":"Und wenn ihr dies mit reinem Herzen tut, in voller Glaubenstreue, dann werdet ihr gesegnet werden; ihr werdet an eurem Kleinvieh und an euren Herden gesegnet sein und auf euren Feldern und in euren Häusern und in euren Familien."},{"verse":12,"text":"Lasst meine Diener Ezra T. Benson und Erastus Snow eine Abteilung organisieren."},{"verse":13,"text":"Und lasst meine Diener Orson Pratt und Wilford Woodruff eine Abteilung organisieren."},{"verse":14,"text":"Lasst auch meine Diener Amasa Lyman und George A. Smith eine Abteilung organisieren."},{"verse":15,"text":"Und bestimmt Präsidenten, auch Hauptleute über hundert und über fünfzig und über zehn."},{"verse":16,"text":"Und lasst meine Diener, die bestimmt worden sind, hingehen und die Heiligen diesen meinen Willen lehren, damit sie bereit seien, in ein Land des Friedens zu ziehen."},{"verse":17,"text":"Geht eures Weges und tut, was ich euch gesagt habe, und fürchtet eure Feinde nicht; denn sie werden nicht die Macht haben, mein Werk aufzuhalten."},{"verse":18,"text":"Zion wird zu der von mir selbst bestimmten Zeit erlöst werden."},{"verse":19,"text":"Und wenn jemand danach trachtet, sich wichtig zu machen, aber nicht nach meinem Rat trachtet, so wird er keine Macht haben, und seine Torheit wird kundgetan werden."},{"verse":20,"text":"Trachtet also danach; und ein jeder halte seine Verpflichtungen gegenüber dem anderen ein; und begehre nichts, was deinem Bruder gehört."},{"verse":21,"text":"Haltet euch von dem Übel fern, den Namen des Herrn zu missbrauchen, denn ich bin der Herr, euer Gott, ja, der Gott eurer Väter, der Gott Abrahams und Isaaks und Jakobs."},{"verse":22,"text":"Ich bin es, der die Kinder Israel aus dem Land Ägypten geführt hat, und mein Arm ist in den letzten Tagen ausgestreckt, um mein Volk Israel zu erretten."},{"verse":23,"text":"Hört auf, miteinander zu streiten; hört auf, voneinander Böses zu reden."},{"verse":24,"text":"Hört auf mit der Trunkenheit; und lasst eure Worte darauf gerichtet sein, einander zu erbauen."},{"verse":25,"text":"Wenn du von deinem Nächsten borgst, sollst du das Geborgte zurückgeben; und wenn du nicht zurückzahlen kannst, so gehe gleich zu deinem Nächsten und sage es ihm, damit er dich nicht schuldig spreche."},{"verse":26,"text":"Wenn du etwas findest, was dein Nächster verloren hat, so sollst du eifrig nachforschen, bis du es ihm wieder übergeben kannst."},{"verse":27,"text":"Du sollst eifrig bestrebt sein, das zu bewahren, was du hast, auf dass du ein weiser Treuhänder seist; denn es ist die freie Gabe des Herrn, deines Gottes, und du bist sein Treuhänder."},{"verse":28,"text":"Wenn du fröhlich bist, so preise den Herrn mit Gesang, mit Musik, mit Tanz und mit einem Gebet des Lobes und der Danksagung."},{"verse":29,"text":"Wenn du bekümmert bist, so rufe den Herrn, deinen Gott, in flehentlichem Gebet an, damit eure Seele sich freue."},{"verse":30,"text":"Fürchte deine Feinde nicht, denn sie sind in meiner Hand, und ich werde mit ihnen tun, wie es mir gefällt."},{"verse":31,"text":"Mein Volk muss in allem geprüft werden, damit es vorbereitet sei, die Herrlichkeit zu empfangen, die ich für es habe, nämlich die Herrlichkeit Zions; und wer Züchtigung nicht ertragen will, der ist meines Reiches nicht wert."},{"verse":32,"text":"Wer unwissend ist, soll Weisheit lernen, indem er sich demütigt und den Herrn, seinen Gott, anruft, damit ihm die Augen aufgehen und er sehen kann und ihm die Ohren aufgehen und er hören kann;"},{"verse":33,"text":"denn mein Geist ist in die Welt gesandt, um die Demütigen und Zerknirschten zu erleuchten und die Gottlosen schuldig zu sprechen."},{"verse":34,"text":"Eure Brüder haben euch und euer Zeugnis verworfen, ja, die Nation, die euch verjagt hat,"},{"verse":35,"text":"und nun kommt der Tag ihres Unheils, ja, die Tage des Leidens, gleich einer Frau, die von den Wehen ereilt wird; und ihr Leiden wird groß sein, wenn sie nicht rasch umkehren, ja, sehr rasch."},{"verse":36,"text":"Denn sie haben die Propheten getötet, ebenso diejenigen, die zu ihnen gesandt worden sind; und sie haben unschuldiges Blut vergossen, das vom Erdboden her gegen sie schreit."},{"verse":37,"text":"Darum wundert euch nicht darüber, denn ihr seid noch nicht rein, ihr könnt meine Herrlichkeit noch nicht ertragen; aber ihr werdet sie schauen, wenn ihr im Halten all meiner Worte treu seid, die ich euch gegeben habe, von den Tagen Adams bis Abraham, von Abraham bis Mose, von Mose bis Jesus und seinen Aposteln und von Jesus und seinen Aposteln bis Joseph Smith, den ich durch meine Engel, meine geistlichen Diener, und mit meiner eigenen Stimme aus den Himmeln aufgerufen habe, dass er mein Werk hervorbringe;"},{"verse":38,"text":"und diese Grundlage hat er gelegt und war treu; und ich habe ihn zu mir genommen."},{"verse":39,"text":"Viele haben sich über seinen Tod gewundert; aber es war nötig, dass er sein Zeugnis mit seinem Blut besiegeln musste, damit er geehrt werden konnte und die Schlechten schuldig gesprochen werden konnten."},{"verse":40,"text":"Habe ich euch nicht von euren Feinden befreit, allein dadurch, dass ich ein Zeugnis meines Namens hinterlassen habe?"},{"verse":41,"text":"Darum horcht nun auf, o ihr Volk meiner Kirche; ihr Ältesten, hört allesamt zu; ihr habt mein Reich empfangen."},{"verse":42,"text":"Seid eifrig im Halten all meiner Gebote, damit nicht Strafgerichte über euch kommen und euer Glaube euch versage und eure Feinde über euch triumphieren. So, für diesmal nichts mehr. Amen und Amen."}]},{"chapter":137,"verses":[{"verse":1,"text":"Die Himmel öffneten sich uns, und ich schaute das celestiale Reich Gottes und dessen Herrlichkeit, ob im Leibe oder außerhalb, das kann ich nicht sagen."},{"verse":2,"text":"Ich sah die alles übersteigende Schönheit des Tores, durch das die Erben jenes Reiches eintreten werden und das wie kreisende Feuerflammen war,"},{"verse":3,"text":"und auch den strahlenden Thron Gottes, auf dem der Vater und der Sohn saßen."},{"verse":4,"text":"Ich sah die schönen Straßen jenes Reiches, die aussahen, als seien sie mit Gold gepflastert."},{"verse":5,"text":"Ich sah Vater Adam und Abraham und meinen Vater und meine Mutter, meinen Bruder Alvin, der schon seit langem entschlafen ist,"},{"verse":6,"text":"und verwunderte mich, wie es war, dass er in dem Reich ein Erbteil erlangt hatte, in Anbetracht dessen, dass er aus diesem Leben geschieden war, ehe der Herr seine Hand erhoben hatte, Israel zum zweiten Mal zu sammeln, und nicht zur Vergebung der Sünden getauft worden war."},{"verse":7,"text":"So erging die Stimme des Herrn an mich, nämlich: Alle, die gestorben sind, ohne von diesem Evangelium zu wissen, die es aber angenommen hätten, wenn sie hätten verweilen dürfen, werden Erben des celestialen Reiches Gottes sein;"},{"verse":8,"text":"auch alle, die von nun an sterben, ohne davon zu wissen, die es aber von ganzem Herzen angenommen hätten, werden Erben dieses Reiches sein;"},{"verse":9,"text":"denn ich, der Herr, werde alle Menschen gemäß ihren Werken richten, gemäß den Wünschen ihres Herzens."},{"verse":10,"text":"Und ich sah auch, dass alle Kinder, die sterben, ehe sie die Jahre der Verantwortlichkeit erreicht haben, im celestialen Reich des Himmels errettet sind."}]},{"chapter":138,"verses":[{"verse":1,"text":"Am dritten Oktober des Jahres neunzehnhundertachtzehn saß ich in meinem Zimmer und sann über die Schriften nach"},{"verse":2,"text":"und überdachte das große, sühnende Opfer, das der Sohn Gottes für die Erlösung der Welt vollbracht hatte,"},{"verse":3,"text":"und die große und wunderbare Liebe, die der Vater und der Sohn dadurch bekundet hatten, dass der Erlöser in die Welt gekommen war,"},{"verse":4,"text":"damit durch sein Sühnopfer und durch Gehorsam gegenüber den Grundsätzen des Evangeliums die Menschen errettet werden könnten."},{"verse":5,"text":"Während mich das beschäftigte, kam ich in Gedanken auf die Schreiben des Apostels Petrus an die ursprünglichen Heiligen zurück, die in Pontus, Galatien, Kappadozien und anderen Gebieten Kleinasiens verstreut lebten, wo nach der Kreuzigung des Herrn das Evangelium gepredigt worden war."},{"verse":6,"text":"Ich schlug die Bibel auf und las im Ersten Brief des Petrus das dritte und vierte Kapitel, und tiefer als je zuvor berührten mich beim Lesen die folgenden Stellen:"},{"verse":7,"text":"„Denn auch Christus hat das eine Mal für Sünden gelitten, der Gerechte für die Ungerechten, damit er uns zu Gott führe, und ist getötet worden nach dem Fleisch, aber lebendig gemacht nach dem Geist."},{"verse":8,"text":"In demselben ist er auch hingegangen und hat den Geistern im Gefängnis gepredigt,"},{"verse":9,"text":"die vorzeiten ungehorsam waren, als Gottes Langmut sich geduldete in den Tagen Noachs, da man die Arche zurüstete, in der wenige, nämlich acht Seelen, gerettet wurden durchs Wasser.“ (1 Petrus 3:18-20.)"},{"verse":10,"text":"„Denn dazu ist auch den Toten das Evangelium gepredigt worden, damit sie den Menschen gemäß nach dem Fleisch gerichtet werden, aber Gott gemäß nach dem Geist leben könnten.“ (1 Petrus 4:6.)"},{"verse":11,"text":"Als ich über dies Geschriebene nachsann, gingen meinem Verständnis die Augen auf, und der Geist des Herrn ruhte auf mir, und ich sah die Scharen der Toten, klein und auch groß."},{"verse":12,"text":"Und an dem einen Ort war eine unzählbare Schar der Geister der Gerechten versammelt, die dem Zeugnis von Jesus treu gewesen waren, solange sie auf Erden gelebt hatten,"},{"verse":13,"text":"und die als Sinnbild für das große Opfer des Sohnes Gottes Opfer dargebracht hatten und im Namen ihres Erlösers Drangsal erlitten hatten."},{"verse":14,"text":"Sie alle waren aus dem irdischen Leben geschieden in der festen Hoffnung auf eine herrliche Auferstehung durch die Gnade Gottes des Vaters und seines einziggezeugten Sohnes, Jesus Christus."},{"verse":15,"text":"Ich sah, dass sie von Freude und Frohsinn erfüllt waren und sich miteinander freuten, weil der Tag ihrer Befreiung nahe war."},{"verse":16,"text":"Sie waren versammelt und warteten darauf, dass der Sohn Gottes in die Geisterwelt komme, um ihre Erlösung aus den Banden des Todes zu verkünden."},{"verse":17,"text":"Ihr schlummernder Staub würde zu seiner vollkommenen Gestalt wiederhergestellt werden, Knochen zu seinem Knochen und darauf die Sehnen und das Fleisch, der Geist und der Leib würden wiedervereinigt werden, um nie mehr getrennt zu werden, damit sie eine Fülle der Freude empfangen könnten."},{"verse":18,"text":"Während diese riesige Menge wartete und sie alle miteinander redeten und sich auf die Stunde ihrer Befreiung von den Ketten des Todes freuten, erschien der Sohn Gottes und verkündete den Gefangenen, die treu gewesen waren, die Freiheit;"},{"verse":19,"text":"und dort predigte er ihnen das immerwährende Evangelium, die Lehre von der Auferstehung und der Erlösung der Menschen vom Fall und, unter der Bedingung, dass sie umkehrten, von ihren eigenen Sünden."},{"verse":20,"text":"Aber zu den Schlechten ging er nicht, und bei den Gottlosen und den Umkehrunwilligen, die sich, als sie im Fleische weilten, verunreinigt hatten, erhob sich seine Stimme nicht;"},{"verse":21,"text":"und auch die Widersetzlichen, die die Zeugnisse und die Warnungen der Propheten aus alter Zeit verworfen hatten, schauten seine Gegenwart nicht und sahen sein Angesicht nicht."},{"verse":22,"text":"Wo sie waren, herrschte Finsternis, aber unter den Rechtschaffenen, da war Friede;"},{"verse":23,"text":"und die Heiligen freuten sich über ihre Erlösung, beugten das Knie und bekannten sich zum Sohn Gottes als ihrem Erlöser und Befreier vom Tod und von den Ketten der Hölle."},{"verse":24,"text":"Ihr Antlitz leuchtete, und der Glanz der Gegenwart des Herrn ruhte auf ihnen, und sie lobsangen seinem heiligen Namen."},{"verse":25,"text":"Ich verwunderte mich, denn mir war bewusst, dass der Erretter an die drei Jahre lang unter den Juden und denen vom Haus Israel gewirkt hatte und bestrebt gewesen war, sie das immerwährende Evangelium zu lehren und sie zur Umkehr zu rufen;"},{"verse":26,"text":"und doch gab es, ungeachtet seiner mächtigen Werke und Wundertaten und seiner mit großer Macht und Vollmacht vorgetragenen Verkündigung der Wahrheit, nur wenige, die auf seine Stimme hörten und sich über seine Gegenwart freuten und aus seinen Händen Errettung annahmen."},{"verse":27,"text":"Sein Wirken unter den Toten aber war auf die kurze Zeitspanne beschränkt, die zwischen der Kreuzigung und seiner Auferstehung lag,"},{"verse":28,"text":"und ich verwunderte mich über die Worte des Petrus – nämlich dass er sagt, Gottes Sohn habe den Geistern im Gefängnis gepredigt, die vorzeiten ungehorsam waren, als Gottes Langmut sich geduldete in den Tagen Noachs – und wie es ihm möglich war, in einer so kurzen Zeit diesen Geistern zu predigen und unter ihnen die notwendige Arbeit zu vollbringen."},{"verse":29,"text":"Und während ich mich verwunderte, gingen mir die Augen auf und mein Verständnis wurde belebt, und ich nahm wahr, dass der Herr nicht in eigener Person zu den Schlechten und den Ungehorsamen, die die Wahrheit verworfen hatten, hinging, um sie zu belehren,"},{"verse":30,"text":"sondern siehe, aus den Rechtschaffenen stellte er seine Kräfte zusammen und bestimmte Boten, angetan mit Macht und Vollmacht, und gab ihnen den Auftrag, hinzugehen und das Licht des Evangeliums denen zu bringen, die in Finsternis waren, ja, zu allen Menschengeistern; und so wurde den Toten das Evangelium gepredigt."},{"verse":31,"text":"Und die ausgewählten Boten gingen hin, um den angenehmen Tag des Herrn zu verkünden und den Gefangenen, die gebunden waren, die Freiheit zu verkündigen, ja, allen, die von ihren Sünden umkehren und das Evangelium empfangen würden."},{"verse":32,"text":"So wurde das Evangelium denen gepredigt, die in ihren Sünden gestorben waren, ohne die Wahrheit gekannt zu haben, oder in Übertretung, da sie die Propheten verworfen hatten."},{"verse":33,"text":"Man belehrte sie über Glauben an Gott, die Umkehr von der Sünde, die stellvertretende Taufe zur Sündenvergebung, die Gabe des Heiligen Geistes durch Händeauflegen"},{"verse":34,"text":"sowie alle sonstigen Evangeliumsgrundsätze, die sie kennenlernen mussten, damit sie sich bereitmachen konnten, dass sie den Menschen gemäß nach dem Fleisch gerichtet werden, aber Gott gemäß nach dem Geist leben könnten."},{"verse":35,"text":"Und so wurde es unter den Toten, klein und auch groß, den Ungerechten und den Getreuen, kundgetan, dass durch das Opfer des Sohnes Gottes am Kreuz die Erlösung zustande gebracht worden war."},{"verse":36,"text":"So wurde es kundgetan, dass unser Erlöser, während er in der Welt der Geister weilte, seine Zeit damit zubrachte, die getreuen Geister der Propheten, die im Fleische für ihn Zeugnis gegeben hatten, zu unterweisen und vorzubereiten,"},{"verse":37,"text":"damit sie die Erlösungsbotschaft zu all jenen Toten tragen könnten, zu denen er wegen ihrer Widersetzlichkeit und Übertretung nicht in eigener Person hingehen konnte, damit auch sie durch das Wirken seiner Diener seine Worte hören könnten."},{"verse":38,"text":"Unter den Großen und Mächtigen, die in dieser riesigen Versammlung der Rechtschaffenen versammelt waren, befanden sich Vater Adam, der Alte der Tage und Vater aller,"},{"verse":39,"text":"und unsere herrliche Mutter Eva mit vielen ihrer getreuen Töchter, die in den verschiedenen Zeitaltern gelebt und den wahren und lebendigen Gott angebetet hatten."},{"verse":40,"text":"Abel, der erste Märtyrer, war da, auch sein Bruder Set, einer der Mächtigen, der das genaue Abbild seines Vaters Adam war."},{"verse":41,"text":"Noach, der vor der Flut gewarnt hatte, Sem, der große Hohe Priester, Abraham, der Vater der Getreuen, Isaak, Jakob und Mose, der große Gesetzgeber Israels,"},{"verse":42,"text":"und Jesaja, der durch Prophezeiung verkündet hatte, der Erlöser sei gesalbt worden, um die, die zerbrochenen Herzens sind, zu verbinden, um den Gefangenen die Freiheit und den Gebundenen die Öffnung des Gefängnisses zu verkündigen – auch sie waren da."},{"verse":43,"text":"Außerdem Ezechiel, dem in einer Vision das weite Tal der verdorrten Gebeine gezeigt worden war, die mit Fleisch umgeben werden würden, um in der Auferstehung der Toten wieder als lebendige Seelen hervorzukommen,"},{"verse":44,"text":"Daniel, der die Aufrichtung des Gottesreiches in den Letzten Tagen vorhersah und vorhersagte, das nimmermehr zerstört und auch keinem anderen Volk gegeben werden würde,"},{"verse":45,"text":"Elias, der mit Mose auf dem Berg der Verklärung war,"},{"verse":46,"text":"und Maleachi, der Prophet, der das Kommen Elijas bezeugt hatte – von dem auch Moroni zu dem Propheten Joseph Smith sprach und verkündete, er werde kommen, ehe der große und schreckliche Tag des Herrn eingeleitet würde –, auch sie waren da."},{"verse":47,"text":"Der Prophet Elija sollte den Kindern die ihren Vätern gemachten Verheißungen ins Herz pflanzen,"},{"verse":48,"text":"die große Arbeit andeutend, die in der Evangeliumszeit der Fülle der Zeiten in den Tempeln des Herrn zu tun ist, für die Erlösung der Toten und die Siegelung der Kinder an ihre Eltern, damit nicht bei seinem Kommen die ganze Erde mit einem Fluch geschlagen und völlig verwüstet werde."},{"verse":49,"text":"Alle diese und viele andere, auch die Propheten, die unter den Nephiten gelebt und das Kommen des Sohnes Gottes bezeugt hatten, waren in der riesigen Versammlung anwesend und warteten auf ihre Befreiung,"},{"verse":50,"text":"denn die Toten hatten die lange Abwesenheit ihres Geistes von ihrem Leib als Gefangenschaft betrachtet."},{"verse":51,"text":"Diese unterwies der Herr und gab ihnen Macht hervorzukommen, nach seiner Auferstehung von den Toten, um in das Reich seines Vaters einzugehen und dort mit Unsterblichkeit und ewigem Leben gekrönt zu werden,"},{"verse":52,"text":"und dann mit ihrer Arbeit fortzufahren, wie der Herr es verheißen hatte, und Teilhaber aller Segnungen zu sein, die für jene zurückbehalten worden waren, die ihn lieben."},{"verse":53,"text":"Der Prophet Joseph Smith und mein Vater Hyrum Smith, Brigham Young, John Taylor, Wilford Woodruff und andere auserkorene Geister – die zurückbehalten worden waren, um in der Fülle der Zeiten hervorzukommen und sich an der Grundlegung des großen Werks der Letzten Tage zu beteiligen,"},{"verse":54,"text":"wozu auch die Errichtung von Tempeln und darin der Vollzug heiliger Handlungen zur Erlösung der Toten gehört – waren ebenfalls in der Geisterwelt."},{"verse":55,"text":"Ich nahm wahr, dass sie sich auch unter den Edlen und Großen befunden hatten, die am Anfang ausgewählt worden waren, Herrscher in der Kirche Gottes zu sein."},{"verse":56,"text":"Schon ehe sie geboren wurden, erhielten sie mit vielen anderen in der Welt der Geister ihre ersten Unterweisungen und wurden darauf vorbereitet, zu der vom Herrn bestimmten Zeit hervorzukommen und in seinem Weingarten für die Errettung der Menschenseelen zu arbeiten."},{"verse":57,"text":"Ich sah, dass die getreuen Ältesten dieser Evangeliumszeit nach ihrem Hinscheiden aus dem irdischen Leben mit ihrer Arbeit fortfahren, indem sie das Evangelium der Umkehr und der Erlösung durch das Opfer des einziggezeugten Sohnes Gottes unter denen verkündigen, die in der großen Welt der Geister der Toten in Finsternis und unter der Knechtschaft der Sünde sind."},{"verse":58,"text":"Die Toten, die umkehren, werden erlöst werden, indem sie die Verordnungen des Hauses Gottes beachten,"},{"verse":59,"text":"und werden, sobald sie die Strafe für ihre Übertretungen bezahlt haben und reingewaschen sind, gemäß ihren Werken einen Lohn empfangen; denn sie sind Erben der Errettung."},{"verse":60,"text":"So wurde mir die Vision von der Erlösung der Toten offenbart, und ich gebe Zeugnis, und ich weiß, dass dieser Bericht wahr ist – durch den Segen unseres Herrn und Erretters, Jesus Christus. So ist es. Amen."}]}]},{"id":"official-declarations","title":"Amtliche Erklärung","englishTitle":"Official Declarations","volume":"Doctrine and Covenants","volumeId":"dc-testament","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"An alle, die es betrifft:"},{"verse":2,"text":"Da Pressemeldungen zu politischen Zwecken von Salt Lake City ausgesandt wurden und weite Verbreitung erfahren haben, die berichten, die Utah-Kommission behaupte in ihrem neuesten Bericht an den Minister des Inneren, es würden noch immer Trauungen zur Mehrehe vollzogen und seit letztem Juni oder im vergangenen Jahr seien in Utah vierzig oder mehr solche Ehen geschlossen worden; auch hätten die Führer der Kirche in öffentlichen Ansprachen die Polygamie gelehrt und zur weiteren Ausübung derselben ermuntert und gedrängt –"},{"verse":3,"text":"darum erkläre ich als Präsident der Kirche Jesu Christi der Heiligen der Letzten Tage hiermit auf das Feierlichste, dass diese Beschuldigungen falsch sind. Wir lehren keine Polygamie oder Mehrehe und gestatten auch niemandem, ihre Ausübung einzugehen; und ich stelle in Abrede, dass vierzig oder irgendeine andere Zahl von Trauungen zur Mehrehe in der betreffenden Zeit in unseren Tempeln oder sonst wo im Territorium Utah vollzogen worden sind."},{"verse":4,"text":"Ein Fall wurde gemeldet, wo die Beteiligten behaupten, die Eheschließung sei im Frühjahr 1889 im Endowment House in Salt Lake City erfolgt, aber ich war nicht imstande zu erfahren, wer die Trauung vollzogen hat; was auch immer in dieser Sache geschehen sein mag, ist ohne mein Wissen geschehen. Auf dieses angebliche Vorkommnis hin wurde das Endowment House auf meine Weisung unverzüglich abgerissen."},{"verse":5,"text":"Da nun der Kongress Gesetze erlassen hat, die die Mehrehe verbieten, und da das höchste Appellationsgericht diese Gesetze als verfassungsgemäß bezeichnet hat, erkläre ich hiermit meine Absicht, mich diesen Gesetzen zu fügen und bei den Mitgliedern der Kirche, deren Präsident ich bin, meinen Einfluss geltend zu machen, dass sie es auch tun."},{"verse":6,"text":"In den von mir und meinen Amtsbrüdern in der genannten Zeit der Kirche erteilten Belehrungen gibt es nichts, was vernünftigerweise als Aufforderung oder Ermutigung zur Polygamie ausgelegt werden kann; und wenn irgendein Ältester der Kirche eine Sprache führte, die eine solche Unterweisung zu enthalten schien, wurde er sofort zurechtgewiesen. Und nun erkläre ich öffentlich, dass ich den Heiligen der Letzten Tage den Rat erteile, von jeder Eheschließung, die durch das Gesetz des Landes verboten ist, Abstand zu nehmen."},{"verse":7,"text":"Wilford Woodruff"},{"verse":8,"text":"Präsident der Kirche Jesu Christi der Heiligen der Letzten Tage."},{"verse":9,"text":"Präsident Lorenzo Snow stellte folgenden Antrag:"},{"verse":10,"text":"„Ich schlage Folgendes vor: Da wir Wilford Woodruff als den Präsidenten der Kirche Jesu Christi der Heiligen der Letzten Tage anerkennen und als den einzigen Menschen auf Erden, der gegenwärtig die Schlüssel der Siegelungsverordnungen innehat, halten wir ihn kraft seiner Stellung für voll befugt, das Manifest, das uns vorgelesen worden ist und das vom 24. September 1890 datiert ist, zu erlassen; und da wir als Kirche in einer Generalkonferenz versammelt sind, nehmen wir seine Erklärung in Bezug auf die Mehrehe als maßgebend und bindend an.“"},{"verse":11,"text":"Salt Lake City, Utah, den 6. Oktober 1890."},{"verse":12,"text":"Der Herr wird niemals zulassen, dass ich oder irgendein anderer Mann, der Präsident dieser Kirche ist, Sie in die Irre führt. Das ist nicht Teil des Plans. Das hat Gott nicht im Sinn. Wenn ich das versuchte, würde der Herr mich von meinem Platz entfernen, und das wird er auch mit jedem anderen tun, der versucht, die Menschenkinder von den Aussprüchen Gottes und von ihrer Pflicht weg in die Irre zu führen. (Einundsechzigste Herbst-Generalkonferenz der Kirche, Montag, den 6. Oktober 1890, Salt Lake City, Utah. Veröffentlicht in der Deseret Evening News vom 11. Oktober 1890, Seite 2.)"},{"verse":13,"text":"Es kommt nicht darauf an, wer lebt oder wer stirbt oder wer berufen ist, diese Kirche zu führen; sie müssen sie durch die Inspiration des allmächtigen Gottes führen. Wenn sie es nicht auf diese Weise tun, können sie es überhaupt nicht tun. …"},{"verse":14,"text":"Ich habe in letzter Zeit einige Offenbarungen gehabt, die mir sehr wichtig sind, und ich werde Ihnen mitteilen, was der Herr mir gesagt hat. Lassen Sie mich Ihren Sinn auf das lenken, was wir das Manifest nennen. …"},{"verse":15,"text":"Der Herr hat mir gesagt, ich solle den Heiligen der Letzten Tage eine Frage stellen; und er hat mir auch gesagt, wenn sie dem zuhörten, was ich ihnen sagen würde, und die ihnen gestellte Frage durch den Geist und die Macht Gottes beantworten würden, dann würden sie in Bezug auf diese Sache alle gleichermaßen antworten, und sie würden alle gleichermaßen glauben."},{"verse":16,"text":"Dies ist die Frage: Was ist der klügste Weg, den die Heiligen der Letzten Tage verfolgen sollen – weiterhin zu versuchen, die Mehrehe auszuüben, wobei die Gesetze der Nation dem entgegenstehen und sechzig Millionen Menschen dagegen sind, und um den Preis der Beschlagnahmung und des Verlustes aller Tempel und der Beendigung der dortigen heiligen Handlungen für die Lebenden und auch für die Toten und der Gefangennahme der Ersten Präsidentschaft und der Zwölf und der Familienoberhäupter in der Kirche und der Beschlagnahmung des persönlichen Eigentums des Volkes (und jede dieser Maßnahmen würde für sich allein ausreichen, die Ausübung zu beenden); oder, nachdem wir getan und erlitten haben, was wir durch unser Festhalten an diesem Prinzip erlebt haben, mit der Ausübung aufzuhören und uns dem Gesetz zu unterwerfen und, indem wir das tun, die Propheten, Apostel und Väter zu Hause zu lassen, sodass sie die Menschen belehren können und den Pflichten der Kirche nachkommen können, und auch die Tempel in den Händen der Heiligen zu belassen, sodass sie für die heiligen Handlungen des Evangeliums für die Lebenden wie auch die Toten Sorge tragen können?"},{"verse":17,"text":"Der Herr hat mir durch Vision und Offenbarung genau gezeigt, was geschehen würde, wenn wir mit der Ausübung nicht aufhörten. Wenn wir nicht damit aufgehört hätten, hätten Sie keine Verwendung gehabt für … irgendeinen der Männer in diesem Tempel in Logan, denn alle heiligen Handlungen hätten im ganzen Land Zion aufgehört. Verwirrung hätte in ganz Israel geherrscht, und viele Männer wären zu Gefangenen geworden. Diese Schwierigkeit wäre über die ganze Kirche gekommen, und dann wären wir gezwungen worden, mit der Ausübung aufzuhören. Nun ist die Frage, sollte sie auf diese Weise beendet werden oder auf die Weise, die der Herr uns gezeigt hat und die unsere Propheten und Apostel und Väter als freie Männer belässt und die Tempel in den Händen des Volkes, sodass die Toten erlöst werden können. Eine große Anzahl ist schon durch dieses Volk aus dem Gefängnis in der Geisterwelt befreit worden, und soll die Arbeit weitergehen oder aufhören? Das ist die Frage, die ich den Heiligen der Letzten Tage vorlege. Sie müssen für sich selbst urteilen. Ich möchte, dass Sie sie für sich selbst beantworten. Ich werde sie nicht beantworten, aber ich sage Ihnen, das ist genau die Lage, in die wir als Volk geraten wären, wenn wir nicht den Weg so gegangen wären, wie wir es getan haben. …"},{"verse":18,"text":"Ich sah genau, was sich begeben würde, wenn nicht etwas getan würde. Ich habe diesen Geist lange Zeit auf mir gefühlt. Aber ich möchte dieses sagen: Ich hätte alle Tempel aus unseren Händen gehen lassen müssen; ich selbst hätte ins Gefängnis gehen müssen und hätte jeden anderen Mann dahin gehen lassen müssen, wenn nicht der Gott des Himmels mir geboten hätte zu tun, was ich getan habe; und als die Stunde kam, da mir geboten wurde, das zu tun, da war mir alles klar. Ich ging vor den Herrn und ich schrieb nieder, was der Herr mich schreiben hieß. …"},{"verse":19,"text":"Ich lasse dies bei Ihnen, damit Sie darüber nachsinnen und nachdenken. Der Herr ist mit uns am Werk. (Konferenz des Cache-Pfahles in Logan, Utah, am Sonntag, den 1. November 1891. Veröffentlicht in der Deseret Weekly vom 14. November 1891.)"},{"verse":20,"text":"Nun will ich Ihnen sagen, was mir kundgetan wurde und was der Sohn Gottes in dieser Sache getan hat. … All dies hätte sich begeben, so wahr Gott, der Allmächtige, lebt, wäre nicht das Manifest gegeben worden. Deshalb hat der Sohn Gottes es für richtig befunden, diese Sache zu seinem eigenen Zweck der Kirche und der Welt vorlegen zu lassen. Der Herr hatte die Errichtung Zions beschlossen. Er hatte die Fertigstellung dieses Tempels beschlossen. Er hatte beschlossen, dass die Errettung der Lebenden und der Toten in diesen Tälern der Berge gegeben werden sollte. Und der allmächtige Gott hatte beschlossen, dass der Teufel das nicht vereiteln sollte. Wenn Sie das verstehen können, das ist ein Schlüssel dazu. (Aus einer Ansprache bei der sechsten Weihungsversammlung des Salt-Lake-Tempels im April 1893. Niederschrift der Weihungsgottesdienste, Archiv der Geschichtsabteilung der Kirche, Salt Lake City, Utah.)"}]},{"chapter":2,"verses":[{"verse":1,"text":"An alle, die es betrifft:"},{"verse":2,"text":"Auf der 148. Herbst-Generalkonferenz der Kirche Jesu Christi der Heiligen der Letzten Tage trug Präsident N. Eldon Tanner, Erster Ratgeber in der Ersten Präsidentschaft der Kirche, am 30. September 1978 Folgendes vor:"},{"verse":3,"text":"Anfang Juni dieses Jahres hat die Erste Präsidentschaft bekanntgegeben, Präsident Spencer W. Kimball habe eine Offenbarung empfangen, dass die Segnungen des Priestertums und des Tempels allen würdigen männlichen Mitgliedern der Kirche zugänglich gemacht werden. Präsident Kimball hat mich gebeten, der Konferenz zur Kenntnis zu bringen, dass er nach dem Empfang dieser Offenbarung, die ihm nach langem Nachsinnen und Beten in den heiligen Räumen des heiligen Tempels zuteilwurde, sie seinen Ratgebern vorgelegt hat, die sie angenommen und gutgeheißen haben. Danach wurde sie dem Kollegium der Zwölf Apostel vorgelegt, das sie einstimmig gutgeheißen hat, und anschließend wurde sie allen übrigen Generalautoritäten vorgelegt, und diese haben sie gleichermaßen einstimmig gutgeheißen."},{"verse":4,"text":"Präsident Kimball hat mich gebeten, nun diesen Brief zu verlesen:"},{"verse":5,"text":"8. Juni 1978"},{"verse":6,"text":"An alle allgemeinen und örtlichen Priestertumsbeamten der Kirche Jesu Christi der Heiligen der Letzten Tage auf der ganzen Welt"},{"verse":7,"text":"Liebe Brüder!"},{"verse":8,"text":"Wir erleben mit, wie sich das Werk des Herrn über die Erde ausbreitet, und sind sehr dankbar dafür, dass Menschen in vielen Ländern für die Botschaft des wiederhergestellten Evangeliums empfänglich gewesen sind und sich in ständig wachsender Zahl der Kirche angeschlossen haben. Dies wiederum hat in uns den Wunsch geweckt, alle Rechte und Segnungen, die das Evangelium bietet, jedem würdigen Mitglied der Kirche zugänglich zu machen."},{"verse":9,"text":"In Anbetracht der Verheißungen, die von den uns vorausgegangenen Propheten und Präsidenten der Kirche gemacht worden sind, dass zu einer bestimmten Zeit in Gottes ewigem Plan alle unsere Brüder, die dazu würdig sind, das Priestertum empfangen können, und angesichts der Glaubenstreue derjenigen, denen das Priestertum vorenthalten war, haben wir uns lange und ernsthaft für diese unsere getreuen Brüder eingesetzt und viele Stunden im Oberen Raum des Tempels verbracht, wo wir den Herrn um göttliche Führung angefleht haben."},{"verse":10,"text":"Er hat unsere Gebete vernommen und hat durch Offenbarung bestätigt, dass der langverheißene Tag gekommen ist, da jeder glaubenstreue, würdige Mann in der Kirche das heilige Priestertum, samt der Macht, dessen göttliche Vollmacht auszuüben, empfangen und sich mit seiner Familie sämtlicher Segnungen erfreuen darf, die sich daraus ergeben, einschließlich der Segnungen des Tempels. Demnach können alle würdigen männlichen Mitglieder der Kirche ohne Rücksicht auf Rasse oder Hautfarbe zum Priestertum ordiniert werden. Die Priestertumsführer sind angewiesen, sich an die Bestimmungen zu halten, wonach mit allen Anwärtern auf die Ordinierung zum Aaronischen oder zum Melchisedekischen Priestertum eine eingehende Unterredung zu führen ist, um zu gewährleisten, dass sie den festgesetzten Anforderungen der Würdigkeit entsprechen."},{"verse":11,"text":"Wir verkünden feierlich, dass der Herr nunmehr seinen Willen kundgetan hat, zum Segen all seiner Kinder überall auf der Erde, die auf die Stimme seiner bevollmächtigten Diener hören und sich bereitmachen, jede Segnung des Evangeliums zu empfangen."},{"verse":12,"text":"Spencer W. Kimball"},{"verse":13,"text":"N. Eldon Tanner"},{"verse":14,"text":"Marion G. Romney"},{"verse":15,"text":"Erste Präsidentschaft"},{"verse":16,"text":"Wir erkennen Spencer W. Kimball als den Propheten, Seher und Offenbarer sowie Präsidenten der Kirche Jesu Christi der Heiligen der Letzten Tage an; darum wird vorgeschlagen, dass wir als konstituierende Versammlung diese Offenbarung als das Wort und den Willen des Herrn annehmen. Wer dem zustimmt, zeige es bitte durch das Heben der rechten Hand. Falls jemand dagegen ist, zeige er es auf die gleiche Weise."},{"verse":17,"text":"Der vorstehende Antrag wurde einstimmig bejaht und angenommen."},{"verse":18,"text":"Salt Lake City, Utah, den 30. September 1978."}]}]},{"id":"moses","title":"Mose","englishTitle":"Moses","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Die Worte Gottes, die er zu Mose sprach zu einer Zeit, als Mose auf einen überaus hohen Berg entrückt wurde"},{"verse":2,"text":"und er Gott von Angesicht zu Angesicht sah und er mit ihm redete und die Herrlichkeit Gottes auf Mose war; darum konnte Mose seine Gegenwart ertragen."},{"verse":3,"text":"Und Gott sprach zu Mose, nämlich: Siehe, ich bin Gott, der Herr, der Allmächtige, und Endlos ist mein Name; denn ich bin ohne Anfang der Tage und ohne Ende der Jahre, und ist das nicht endlos?"},{"verse":4,"text":"Und siehe, du bist mein Sohn; darum schaue, und ich werde dir das Werk meiner Hände zeigen; aber nicht alles, denn meine Werke sind ohne Ende wie auch meine Worte, denn sie hören nie auf."},{"verse":5,"text":"Darum kann kein Mensch alle meine Werke sehen, außer er sähe alle meine Herrlichkeit; und kein Mensch kann alle meine Herrlichkeit sehen und danach im Fleische auf Erden verbleiben."},{"verse":6,"text":"Und ich habe eine Arbeit für dich, Mose, mein Sohn; und du bist im Ebenbild meines Einziggezeugten; und mein Einziggezeugter ist der Erretter und wird es sein, denn er ist voller Gnade und Wahrheit; doch es gibt keinen Gott neben mir, und alles ist gegenwärtig bei mir, denn ich kenne es alles."},{"verse":7,"text":"Und nun siehe, dieses eine zeige ich dir, Mose, mein Sohn, denn du bist in der Welt, und nun zeige ich es dir."},{"verse":8,"text":"Und es begab sich: Mose schaute und sah die Welt, auf der er geschaffen worden war; und Mose sah die Welt und ihre Enden sowie alle Menschenkinder, die es gibt und die erschaffen worden sind; und darüber staunte er und wunderte sich sehr."},{"verse":9,"text":"Und die Gegenwart Gottes zog sich von Mose zurück, sodass seine Herrlichkeit nicht mehr auf Mose war; und Mose war sich selbst überlassen. Und als er sich selbst überlassen war, fiel er zur Erde."},{"verse":10,"text":"Und es begab sich: Es dauerte den Zeitraum vieler Stunden, ehe Mose wieder seine natürliche Kraft als Mensch erlangte; und er sprach bei sich: Nun weiß ich aus diesem Grunde, dass der Mensch nichts ist, und das hätte ich nie gedacht."},{"verse":11,"text":"Aber nun haben meine eigenen Augen Gott gesehen, aber nicht meine natürlichen, sondern meine geistigen Augen, denn meine natürlichen Augen hätten nicht sehen können; denn ich wäre in seiner Gegenwart vergangen und hätte sterben müssen, aber seine Herrlichkeit war auf mir, und ich habe sein Angesicht gesehen, denn ich bin vor ihm verklärt worden."},{"verse":12,"text":"Und es begab sich: Als Mose diese Worte gesprochen hatte, siehe, da kam der Satan, ihn zu versuchen, nämlich: Mose, Menschensohn, bete mich an!"},{"verse":13,"text":"Und es begab sich: Mose blickte den Satan an und sprach: Wer bist du? Denn siehe, ich bin ein Sohn Gottes, im Ebenbild seines Einziggezeugten; und wo ist deine Herrlichkeit, dass ich dich anbeten sollte?"},{"verse":14,"text":"Denn siehe, ich hätte Gott nicht anblicken können, wenn nicht seine Herrlichkeit auf mich gekommen und ich vor ihm verklärt worden wäre. Dich aber kann ich anblicken als natürlicher Mensch. Gewiss, ist es nicht so?"},{"verse":15,"text":"Gesegnet sei der Name meines Gottes, denn sein Geist hat sich nicht gänzlich von mir zurückgezogen; oder wo ist denn deine Herrlichkeit, denn für mich ist sie Finsternis? Und ich kann zwischen dir und Gott unterscheiden, denn Gott hat zu mir gesagt: Bete Gott an, denn ihm allein sollst du dienen."},{"verse":16,"text":"Geh hinweg, Satan; täusche mich nicht! Denn Gott hat zu mir gesagt: Du bist nach dem Ebenbild meines Einziggezeugten."},{"verse":17,"text":"Und er hat mir auch Gebote gegeben, als er mir aus dem brennenden Busch zurief, nämlich: Rufe Gott an im Namen meines Einziggezeugten, und bete mich an!"},{"verse":18,"text":"Und weiter sprach Mose: Ich werde nicht aufhören, Gott anzurufen, habe ich doch noch anderes, was ich ihn fragen will: Denn seine Herrlichkeit ist auf mir gewesen, darum kann ich zwischen ihm und dir unterscheiden. Weiche von hier, Satan!"},{"verse":19,"text":"Und nun, als Mose diese Worte gesprochen hatte, schrie der Satan mit lauter Stimme und tobte auf der Erde und gebot, nämlich: Ich bin der Einziggezeugte, bete mich an!"},{"verse":20,"text":"Und es begab sich: Mose fing an, sich über die Maßen zu fürchten, und als er sich zu fürchten anfing, sah er die Bitternis der Hölle. Doch als er Gott anrief, empfing er Kraft, und er gebot, nämlich: Weiche von mir, Satan; denn allein diesen einen Gott werde ich anbeten, nämlich den Gott der Herrlichkeit."},{"verse":21,"text":"Und nun fing der Satan zu zittern an, und die Erde bebte, und Mose empfing Kraft und rief Gott an, nämlich: Im Namen des Einziggezeugten, weiche von hier, Satan!"},{"verse":22,"text":"Und es begab sich: Der Satan schrie mit lauter Stimme, mit Weinen und Wehklagen und Zähneknirschen; und er wich hinweg, ja, aus der Gegenwart des Mose, sodass er ihn nicht mehr sah."},{"verse":23,"text":"Und nun, dafür gab Mose Zeugnis, aber infolge von Schlechtigkeit ist es unter den Menschenkindern nicht vorhanden."},{"verse":24,"text":"Und es begab sich: Als der Satan aus der Gegenwart des Mose gewichen war, hob Mose seine Augen zum Himmel auf, denn er war vom Heiligen Geist erfüllt, der Zeugnis gibt für den Vater und den Sohn;"},{"verse":25,"text":"und als er den Namen Gottes anrief, sah er abermals seine Herrlichkeit, denn sie war auf ihm; und er vernahm eine Stimme, nämlich: Gesegnet bist du, Mose, denn ich, der Allmächtige, habe dich erwählt, und du wirst stärker gemacht werden als viele Wasser, denn sie werden dein Gebot beachten, als seiest du Gott."},{"verse":26,"text":"Und sieh, ich bin mit dir, ja, bis ans Ende deiner Tage; denn du wirst mein Volk aus der Knechtschaft befreien, ja, Israel, meine Erwählten."},{"verse":27,"text":"Und es begab sich: Als die Stimme noch redete, ließ Mose seine Augen schweifen und sah die Erde, ja, selbst alles davon; und es gab da auch nicht den kleinsten Teil davon, den er nicht sah; denn durch den Geist Gottes nahm er es wahr."},{"verse":28,"text":"Und er sah auch deren Bewohner, und es gab da auch nicht eine Seele, die er nicht sah; und durch den Geist Gottes nahm er sie wahr; und ihre Anzahl war groß, ja, so zahllos wie der Sand am Meeresstrand."},{"verse":29,"text":"Und er sah viele Länder; und jedes Land wurde Erde genannt, und es waren Bewohner darauf."},{"verse":30,"text":"Und es begab sich: Mose rief Gott an, nämlich: Ich bitte dich, erzähle mir, warum dies alles so ist und wodurch du diese gemacht hast."},{"verse":31,"text":"Und siehe, die Herrlichkeit des Herrn war auf Mose, sodass Mose in der Gegenwart Gottes stand und mit ihm von Angesicht zu Angesicht redete. Und Gott, der Herr, sprach zu Mose: Für meinen eigenen Zweck habe ich dies alles gemacht. Hier ist Weisheit, und sie verbleibt in mir."},{"verse":32,"text":"Und durch das Wort meiner Macht habe ich sie erschaffen, nämlich durch meinen einziggezeugten Sohn, der voller Gnade und Wahrheit ist."},{"verse":33,"text":"Und Welten ohne Zahl habe ich erschaffen; auch habe ich sie für meinen eigenen Zweck erschaffen; und durch den Sohn habe ich sie erschaffen, nämlich meinen Einziggezeugten."},{"verse":34,"text":"Und den ersten Menschen aller Menschen habe ich Adam genannt, was viele bedeutet."},{"verse":35,"text":"Aber nur von dieser Erde und ihren Bewohnern gebe ich dir Bericht. Denn siehe, es gibt viele Welten, die durch das Wort meiner Macht vergangen sind. Und es gibt viele, die jetzt bestehen, und unzählbar sind sie für den Menschen; aber mir ist alles gezählt, denn es ist mein, und ich kenne es."},{"verse":36,"text":"Und es begab sich: Mose sprach zum Herrn, nämlich: Sei barmherzig zu deinem Diener, o Gott, und erzähle mir in Bezug auf diese Erde und ihre Bewohner und auch die Himmel, und dann wird dein Diener zufrieden sein."},{"verse":37,"text":"Und Gott, der Herr, sprach zu Mose, nämlich: Der Himmel sind viele, und sie können für den Menschen nicht gezählt werden; aber mir sind sie gezählt, denn sie sind mein."},{"verse":38,"text":"Und wie eine Erde vergehen wird, samt ihren Himmeln, so wird eine andere kommen; und es gibt kein Ende für meine Werke, auch nicht für meine Worte."},{"verse":39,"text":"Denn siehe, dies ist mein Werk und meine Herrlichkeit: die Unsterblichkeit und das ewige Leben des Menschen zustande zu bringen."},{"verse":40,"text":"Und nun, Mose, mein Sohn, werde ich zu dir über diese Erde sprechen, auf der du stehst; und du sollst das, was ich sprechen werde, niederschreiben."},{"verse":41,"text":"Und an einem Tag, da die Menschenkinder meine Worte für nichts achten und deren viele aus dem Buch, das du schreiben wirst, herausnehmen werden, siehe, da werde ich einen anderen, dir gleich, erwecken; und dann werden sie wieder unter den Menschenkindern vorhanden sein – unter all denen, die glauben."},{"verse":42,"text":"(Diese Worte wurden zu Mose gesprochen, und zwar auf dem Berg, dessen Name unter den Menschenkindern nicht bekannt sein wird. Und nun werden sie zu dir gesprochen. Zeige sie niemandem außer denen, die glauben. So ist es. Amen.)"}]},{"chapter":2,"verses":[{"verse":1,"text":"Und es begab sich: Der Herr sprach zu Mose, nämlich: Siehe, ich gebe dir Offenbarung in Bezug auf diesen Himmel und diese Erde; schreibe die Worte nieder, die ich spreche. Ich bin der Anfang und das Ende, der allmächtige Gott; durch meinen Einziggezeugten habe ich dies alles erschaffen; ja, am Anfang erschuf ich den Himmel und die Erde, auf der du stehst."},{"verse":2,"text":"Und die Erde war ohne Gestalt und wüst; und ich ließ Finsternis aufkommen über der Tiefe; und mein Geist schwebte über dem Wasser, denn ich bin Gott."},{"verse":3,"text":"Und ich, Gott, sprach: Lasst Licht sein; und es ward Licht."},{"verse":4,"text":"Und ich, Gott, sah das Licht, und das Licht war gut. Und ich, Gott, schied das Licht von der Finsternis."},{"verse":5,"text":"Und ich, Gott, nannte das Licht Tag, und die Finsternis nannte ich Nacht; und das tat ich durch das Wort meiner Macht, und es geschah, wie ich sprach; und der Abend und der Morgen waren der erste Tag."},{"verse":6,"text":"Und weiter sprach ich, Gott: Lasst ein Gewölbe sein inmitten des Wassers; und es geschah so, ja, wie ich sprach; und ich sprach: Lasst es die Wasser von den Wassern scheiden; und es geschah;"},{"verse":7,"text":"und ich, Gott, schuf das Gewölbe und schied die Wasser, ja, die großen Wasser unter dem Gewölbe von den Wassern, die über dem Gewölbe waren; und es war so, ja, wie ich sprach."},{"verse":8,"text":"Und ich, Gott, nannte das Gewölbe Himmel; und der Abend und der Morgen waren der zweite Tag."},{"verse":9,"text":"Und ich, Gott, sprach: Lasst die Wasser unter dem Himmel sich an einen Ort sammeln; und es war so; und ich, Gott, sprach: Lasst trockenes Land sein; und es war so."},{"verse":10,"text":"Und ich, Gott, nannte das trockene Land Erde, und die Sammlung der Wasser nannte ich das Meer; und ich, Gott, sah, dass alles, was ich gemacht hatte, gut war."},{"verse":11,"text":"Und ich, Gott, sprach: Lasst die Erde Gras hervorbringen, das Kraut, das Samen trägt, den Fruchtbaum, der Frucht trägt nach seiner Art, und den Baum, der Frucht trägt, worin sein eigener Same sei auf der Erde; und es war so, ja, wie ich sprach."},{"verse":12,"text":"Und die Erde brachte Gras hervor, jedes Kraut, das Samen trägt nach seiner Art, und den Baum, der Frucht trägt, worin sein eigener Same sei nach seiner Art; und ich, Gott, sah, dass alles, was ich gemacht hatte, gut war;"},{"verse":13,"text":"und der Abend und der Morgen waren der dritte Tag."},{"verse":14,"text":"Und ich, Gott, sprach: Lasst Lichter sein am Gewölbe des Himmels, dass sie den Tag von der Nacht scheiden, und für Zeichen sollen sie sein und für Jahreszeiten und für Tage und für Jahre,"},{"verse":15,"text":"und lasst sie Lichter sein am Gewölbe des Himmels, dass sie der Erde Licht geben; und es war so."},{"verse":16,"text":"Und ich, Gott, machte zwei große Lichter, das größere Licht, dass es den Tag beherrsche, und das kleinere Licht, dass es die Nacht beherrsche; und das größere Licht war die Sonne, und das kleinere Licht war der Mond; und auch die Sterne wurden gemacht, ja, gemäß meinem Wort."},{"verse":17,"text":"Und ich, Gott, setzte sie an das Gewölbe des Himmels, um der Erde Licht zu geben,"},{"verse":18,"text":"und die Sonne, dass sie über den Tag herrsche, und den Mond, dass er über die Nacht herrsche, und um das Licht von der Finsternis zu scheiden; und ich, Gott, sah, dass alles, was ich gemacht hatte, gut war;"},{"verse":19,"text":"und der Abend und der Morgen waren der vierte Tag."},{"verse":20,"text":"Und ich, Gott, sprach: Lasst die Wasser reichlich hervorbringen das sich regende Geschöpf, das Leben hat, und Vögel fliegen über der Erde am offenen Gewölbe des Himmels."},{"verse":21,"text":"Und ich, Gott, erschuf große Walfische und jedes lebendige Geschöpf, das sich regt, das die Wasser reichlich hervorbrachten, nach ihrer Art, und jeden geflügelten Vogel nach seiner Art; und ich, Gott, sah, dass alles, was ich erschaffen hatte, gut war."},{"verse":22,"text":"Und ich, Gott, segnete sie, nämlich: Seid fruchtbar und mehret euch, und füllet die Wasser im Meer; und lasst die Vögel sich mehren auf Erden;"},{"verse":23,"text":"und der Abend und der Morgen waren der fünfte Tag."},{"verse":24,"text":"Und ich, Gott, sprach: Lasst die Erde das lebendige Geschöpf hervorbringen nach seiner Art, Vieh und kriechendes Getier und die Wildtiere der Erde nach ihrer Art; und es war so;"},{"verse":25,"text":"und ich, Gott, schuf die Wildtiere der Erde nach ihrer Art und Vieh nach seiner Art und alles, was auf der Erde kriecht, nach seiner Art; und ich, Gott, sah, dass dieses alles gut war."},{"verse":26,"text":"Und ich, Gott, sagte zu meinem Einziggezeugten, der vom Anfang an bei mir war: Lass uns den Menschen machen als unser Abbild, uns selbst ähnlich; und es war so. Und ich, Gott, sprach: Lasst sie herrschen über die Fische des Meeres und über die Vögel der Luft und über das Vieh und über die ganze Erde und über alles kriechende Getier, was auf der Erde kriecht."},{"verse":27,"text":"Und ich, Gott, erschuf den Menschen als mein eigenes Abbild, als Abbild meines Einziggezeugten erschuf ich ihn; männlich und weiblich erschuf ich sie."},{"verse":28,"text":"Und ich, Gott, segnete sie und sprach zu ihnen: Seid fruchtbar und mehret euch, und füllet die Erde und machet sie euch untertan, und herrschet über die Fische des Meeres und über die Vögel der Luft und über alles Lebendige, was sich auf der Erde regt."},{"verse":29,"text":"Und ich, Gott, sprach zum Menschen: Siehe, ich habe euch jegliches samenbringende Kraut gegeben, das auf der ganzen Erde ist, und jeglichen Baum, an dem Frucht sein wird, die den Samen in sich hat, einen Baum hervorzubringen; euch wird dies zur Nahrung sein."},{"verse":30,"text":"Und jedem Wildtier der Erde und jedem Vogel der Luft und allem, was auf der Erde kriecht, dem ich Leben gewähre, soll alles reine Kraut gegeben sein zur Nahrung; und es war so, ja, wie ich sprach."},{"verse":31,"text":"Und ich, Gott, sah alles, was ich gemacht hatte; und siehe, alles, was ich gemacht hatte, war sehr gut; und der Abend und der Morgen waren der sechste Tag."}]},{"chapter":3,"verses":[{"verse":1,"text":"So wurden vollendet der Himmel und die Erde und all ihre Schar."},{"verse":2,"text":"Und am siebenten Tag beendete ich, Gott, mein Werk und alles, was ich gemacht hatte; und ich ruhte am siebenten Tag von all meinem Werk; und alles, was ich gemacht hatte, war vollendet worden, und ich, Gott, sah, dass es gut war;"},{"verse":3,"text":"und ich, Gott, segnete den siebenten Tag und heiligte ihn; denn an ihm ruhte ich von all meinem Werk, das ich, Gott, erschaffen und gemacht hatte."},{"verse":4,"text":"Und nun siehe, ich sage dir: Dies sind die Generationen des Himmels und der Erde, als sie erschaffen wurden an dem Tag, da ich, Gott, der Herr, den Himmel und die Erde machte,"},{"verse":5,"text":"und jede Pflanze des Feldes, bevor sie auf Erden war, und jedes Kraut des Feldes, bevor es wuchs. Denn ich, Gott, der Herr, erschuf alles, wovon ich gesprochen habe, geistig, ehe es natürlich auf der Erde war. Denn ich, Gott, der Herr, hatte es noch nicht regnen lassen auf den Erdboden. Und ich, Gott, der Herr, hatte alle Menschenkinder erschaffen und doch noch keinen Menschen, der die Erde bebaute, denn im Himmel erschuf ich sie, und noch war kein Fleisch auf der Erde, auch nicht im Wasser, auch nicht in der Luft;"},{"verse":6,"text":"aber ich, Gott, der Herr, sprach, und da stieg von der Erde ein Dunst auf und wässerte den ganzen Erdboden."},{"verse":7,"text":"Und ich, Gott, der Herr, gestaltete den Menschen aus dem Staub des Erdbodens und hauchte in seine Nasenlöcher den Lebenshauch; und der Mensch wurde eine lebende Seele, das erste Fleisch auf Erden, auch der erste Mensch; doch wurde alles zuvor erschaffen, aber geistig wurde es erschaffen und gemacht, gemäß meinem Wort."},{"verse":8,"text":"Und ich, Gott, der Herr, pflanzte einen Garten im Osten, in Eden, und darein setzte ich den Menschen, den ich gestaltet hatte."},{"verse":9,"text":"Und aus dem Erdboden ließ ich, Gott, der Herr, alle Bäume natürlich aufwachsen, die angenehm anzusehen sind für den Menschen; und der Mensch konnte sie sehen. Und sie wurden auch lebende Seelen. Denn sie waren geistig an dem Tag, da ich sie erschuf; denn sie verblieben in der Sphäre, in der ich, Gott, sie erschuf, ja, nämlich alles, was ich dem Menschen zum Gebrauch bereitet hatte; und der Mensch sah, dass es gut war zur Nahrung. Und ich, Gott, der Herr, pflanzte auch den Baum des Lebens in der Mitte des Gartens und auch den Baum der Erkenntnis von Gut und Böse."},{"verse":10,"text":"Und ich, Gott, der Herr, ließ von Eden einen Fluss ausgehen, den Garten zu bewässern; und von dort an teilte er sich und wurde zu vier Hauptflüssen."},{"verse":11,"text":"Und ich, Gott, der Herr, gab dem ersten den Namen Pischon, und er umfließt das ganze Land Hawila, wo ich, Gott, der Herr, viel Gold erschaffen habe;"},{"verse":12,"text":"und das Gold jenes Landes ist gut, und dort gibt es Bdelliumharz und den Stein Onyx."},{"verse":13,"text":"Und der Name des zweiten Flusses lautet Gihon; er ist es, der das ganze Land Äthiopien umfließt."},{"verse":14,"text":"Und der Name des dritten Flusses ist Hiddekel; er ist es, der im Osten von Assyrien hingeht. Und der vierte Fluss ist der Eufrat."},{"verse":15,"text":"Und ich, Gott, der Herr, nahm den Menschen und setzte ihn in den Garten von Eden, ihn zu bebauen und ihn zu hüten."},{"verse":16,"text":"Und ich, Gott, der Herr, gebot dem Menschen, nämlich: Von jedem Baum des Gartens magst du nach Belieben essen,"},{"verse":17,"text":"aber vom Baum der Erkenntnis von Gut und Böse, davon sollst du nicht essen; doch du magst dich selbst entscheiden, denn das ist dir gewährt; aber bedenke, dass ich es verbiete, denn an dem Tag, da du davon isst, wirst du sicherlich sterben."},{"verse":18,"text":"Und ich, Gott, der Herr, sagte zu meinem Einziggezeugten, es sei nicht gut, dass der Mensch allein sei; darum will ich ihm eine Hilfe machen, ihm ebenbürtig."},{"verse":19,"text":"Und aus dem Erdboden gestaltete ich, Gott, der Herr, jedes Tier des Feldes und jeden Vogel der Luft und gebot ihnen, zu Adam zu kommen, um zu sehen, wie er sie benennen würde; und sie waren auch lebende Seelen; denn ich, Gott, hauchte in sie den Lebenshauch und gebot, wie auch immer Adam jedes lebendige Geschöpf benannte, so solle dessen Name sein."},{"verse":20,"text":"Und Adam gab allem Vieh und den Vögeln der Luft und jedem Tier des Feldes Namen; aber für Adam, da fand sich keine Hilfe, ihm ebenbürtig."},{"verse":21,"text":"Und ich, Gott, der Herr, ließ einen tiefen Schlaf auf Adam fallen; und er schlief, und ich nahm eine von seinen Rippen und verschloss ihre Stelle stattdessen mit Fleisch;"},{"verse":22,"text":"und aus der Rippe, die ich, Gott, der Herr, von dem Menschen genommen hatte, schuf ich eine Frau und brachte sie zu dem Menschen."},{"verse":23,"text":"Und Adam sprach: Dies, das weiß ich, ist nun Bein von meinem Gebein und Fleisch von meinem Fleisch; sie wird Frau heißen, denn vom Mann wurde sie genommen."},{"verse":24,"text":"Darum wird ein Mann seinen Vater und seine Mutter verlassen und wird an seiner Frau festhalten; und sie werden ein Fleisch sein."},{"verse":25,"text":"Und sie waren beide nackt, der Mensch und seine Frau, und schämten sich nicht."}]},{"chapter":4,"verses":[{"verse":1,"text":"Und ich, Gott, der Herr, sprach zu Mose, nämlich: Jener Satan, dem du im Namen meines Einziggezeugten geboten hast, ist derselbe, der von Anfang an gewesen ist; und er trat vor mich und sprach: Siehe, hier bin ich, sende mich; ich will dein Sohn sein, und ich will die ganze Menschheit erlösen, dass auch nicht eine Seele verlorengeht, und gewiss werde ich es tun; darum gib mir deine Ehre."},{"verse":2,"text":"Aber siehe: Mein geliebter Sohn, der mein Geliebter und Erwählter von Anfang an war, sprach zu mir: Vater, dein Wille geschehe, und die Herrlichkeit sei dein immerdar."},{"verse":3,"text":"Darum, weil jener Satan sich gegen mich auflehnte und danach trachtete, die Entscheidungsfreiheit des Menschen zu vernichten, die ich, Gott, der Herr, ihm gegeben hatte, und weil ich ihm auch meine eigene Macht geben sollte, ließ ich ihn durch die Macht meines Einziggezeugten hinabwerfen;"},{"verse":4,"text":"und er wurde der Satan, ja, nämlich der Teufel, der Vater aller Lügen, die Menschen zu täuschen und zu verblenden und sie nach seinem Willen in Gefangenschaft zu führen, ja, alle, die nicht auf meine Stimme hören wollen."},{"verse":5,"text":"Und nun war die Schlange listiger als alle Tiere des Feldes, die ich, Gott, der Herr, geschaffen hatte."},{"verse":6,"text":"Und der Satan legte es der Schlange ins Herz (denn er hatte viele nach sich weggezogen), und er trachtete auch danach, Eva zu verleiten, denn er erkannte die Absicht Gottes nicht, und darum trachtete er danach, die Welt zu vernichten."},{"verse":7,"text":"Und er sprach zu der Frau: Ja, hat Gott gesagt: Ihr sollt nicht von allen Bäumen des Gartens essen? (Und er sprach durch den Mund der Schlange.)"},{"verse":8,"text":"Und die Frau sprach zu der Schlange: Wir dürfen von der Frucht der Bäume des Gartens essen;"},{"verse":9,"text":"aber von der Frucht des Baumes, den du mitten im Garten siehst, hat Gott gesagt: Ihr sollt nicht davon essen, und ihr sollt nicht daran rühren, sonst werdet ihr sterben."},{"verse":10,"text":"Und die Schlange sprach zu der Frau: Ihr werdet nicht sicherlich sterben;"},{"verse":11,"text":"denn Gott weiß: An dem Tag, da ihr davon esst, werden euch die Augen aufgehen, und ihr werdet wie Götter sein, Gut und Böse erkennend."},{"verse":12,"text":"Und als die Frau sah, dass der Baum gut war zur Nahrung und dass er eine Lust für die Augen war und ein begehrenswerter Baum, sie weise zu machen, da nahm sie von seiner Frucht und aß und gab auch ihrem Mann bei ihr, und er aß."},{"verse":13,"text":"Und ihnen beiden gingen die Augen auf, und sie erkannten, dass sie nackt gewesen waren. Und sie hefteten Feigenblätter zusammen und machten sich Schürzen."},{"verse":14,"text":"Und sie hörten die Stimme Gottes, des Herrn, als sie sich in der Kühle des Tages im Garten ergingen; und Adam und seine Frau gingen daran, sich vor der Gegenwart Gottes, des Herrn, unter den Bäumen im Garten zu verstecken."},{"verse":15,"text":"Und ich, Gott, der Herr, rief Adam und sprach zu ihm: Wohin gehst du?"},{"verse":16,"text":"Und er sprach: Ich hörte deine Stimme im Garten, und ich fürchtete mich, denn ich sah, dass ich nackt war, und ich versteckte mich."},{"verse":17,"text":"Und ich, Gott, der Herr, sprach zu Adam: Wer hat dir gesagt, dass du nackt bist? Hast du von dem Baum gegessen, von dem ich dir geboten habe, nicht zu essen, da du sonst sicherlich sterben würdest?"},{"verse":18,"text":"Und der Mensch sprach: Die Frau, die du mir gegeben hast und die nach deinem Gebot bei mir bleiben soll, sie hat mir von der Frucht des Baumes gegeben, und ich habe gegessen."},{"verse":19,"text":"Und ich, Gott, der Herr, sprach zu der Frau: Was hast du da getan? Und die Frau sprach: Die Schlange hat mich verleitet, und ich habe gegessen."},{"verse":20,"text":"Und ich, Gott, der Herr, sprach zu der Schlange: Weil du das getan hast, sollst du verflucht sein vor allem Vieh und vor allen Tieren des Feldes; auf deinem Bauch sollst du gehen, und Staub sollst du fressen alle Tage deines Lebens;"},{"verse":21,"text":"und ich werde Feindschaft setzen zwischen dich und die Frau, zwischen deinen Nachkommen und ihren Nachkommen; und er wird dir den Kopf zerschlagen, und du wirst ihm die Ferse zerschlagen."},{"verse":22,"text":"Zu der Frau sprach ich, Gott, der Herr: Ich werde deine Mühsal und deine Schwangerschaft sehr mehren. Unter Mühen wirst du Kinder hervorbringen, und dein Verlangen wird nach deinem Mann sein, und er wird über dich herrschen."},{"verse":23,"text":"Und zu Adam sprach ich, Gott, der Herr: Weil du auf die Stimme deiner Frau gehört und von der Frucht des Baumes gegessen hast, von dem ich dir gebot, nämlich: Du sollst davon nicht essen!, so sei verflucht der Erdboden um deinetwillen; unter Mühsal wirst du von ihm essen alle Tage deines Lebens."},{"verse":24,"text":"Auch Dornen und Disteln wird er dir hervorbringen, und du wirst das Kraut des Feldes essen."},{"verse":25,"text":"Im Schweiße deines Angesichts wirst du Brot essen, bis du zum Erdboden zurückkehrst – denn du wirst sicherlich sterben –, denn von ihm bist du genommen: Denn Staub warst du, und zum Staub musst du zurück."},{"verse":26,"text":"Und Adam nannte seine Frau Eva, weil sie die Mutter aller Lebenden ist; denn so habe ich, Gott, der Herr, die erste von allen Frauen genannt, und es sind ihrer viele."},{"verse":27,"text":"Für Adam und auch für seine Frau machte ich, Gott, der Herr, Röcke aus Tierhaut und bekleidete sie."},{"verse":28,"text":"Und ich, Gott, der Herr, sprach zu meinem Einziggezeugten: Siehe, der Mensch ist geworden wie unsereiner im Erkennen von Gut und Böse; und nun, damit er nicht seine Hand ausstrecke und auch vom Baum des Lebens nehme und esse und lebe immerdar,"},{"verse":29,"text":"darum werde ich, Gott, der Herr, ihn aus dem Garten von Eden weisen, dass er den Erdboden bebaue, von dem er genommen ward;"},{"verse":30,"text":"denn so wahr ich, Gott, der Herr, lebe, können meine Worte nicht unwirksam zurückkehren; denn so, wie sie aus meinem Mund hervorgehen, müssen sie sich erfüllen."},{"verse":31,"text":"So trieb ich den Menschen hinaus, und ich stellte im Osten des Gartens von Eden Kerubim auf und ein loderndes Schwert, das ringsum kreiste, um den Weg zum Baum des Lebens zu bewachen."},{"verse":32,"text":"(Und dies sind die Worte, die ich zu meinem Diener Mose sprach; und sie sind wahr, ja, wie ich es will; und ich habe sie zu dir gesprochen. Sieh zu, dass du sie keinem Menschen zeigst, bis ich es dir gebiete, außer denen, die glauben. Amen.)"}]},{"chapter":5,"verses":[{"verse":1,"text":"Und es begab sich: Nachdem ich, Gott, der Herr, sie hinausgetrieben hatte, fing Adam an, die Erde zu bebauen und über alle Tiere des Feldes zu herrschen und sein Brot im Schweiße seiner Stirn zu essen, wie ich, der Herr, es ihm geboten hatte. Und auch Eva, seine Frau, arbeitete mit ihm."},{"verse":2,"text":"Und Adam erkannte seine Frau, und sie gebar ihm Söhne und Töchter, und allmählich mehrten sie sich und füllten die Erde."},{"verse":3,"text":"Und seit dieser Zeit fingen die Söhne und Töchter Adams an, sich paarweise im Land zu verteilen und das Land zu bebauen und Herden zu hüten; und auch sie zeugten Söhne und Töchter."},{"verse":4,"text":"Und Adam und Eva, seine Frau, riefen den Namen des Herrn an, und sie vernahmen die Stimme des Herrn aus der Richtung vom Garten von Eden her, wie er zu ihnen sprach; und sie sahen ihn nicht, denn sie waren aus seiner Gegenwart ausgeschlossen."},{"verse":5,"text":"Und er gab ihnen Gebote, dass sie den Herrn, ihren Gott, anbeten sollten und die Erstlinge ihrer Herden dem Herrn als Opfer darbringen sollten. Und Adam beachtete die Gebote des Herrn."},{"verse":6,"text":"Und nach vielen Tagen erschien Adam ein Engel des Herrn und sprach: Warum bringst du dem Herrn Opfer dar? Und Adam sprach zu ihm: Ich weiß nicht, außer dass der Herr es mir geboten hat."},{"verse":7,"text":"Und dann sprach der Engel, nämlich: Dies ist ein Sinnbild für das Opfer des Einziggezeugten des Vaters, der voller Gnade und Wahrheit ist."},{"verse":8,"text":"Darum sollst du alles, was du tust, im Namen des Sohnes tun, und du sollst umkehren und Gott im Namen des Sohnes anrufen immerdar."},{"verse":9,"text":"Und an jenem Tag fiel der Heilige Geist auf Adam, der Zeugnis gibt für den Vater und den Sohn, nämlich: Ich bin der Einziggezeugte des Vaters vom Anfang an, fortan und für immer, auf dass, da du gefallen bist, du wieder erlöst werden kannst, und auch die ganze Menschheit, ja, alle, die es wollen."},{"verse":10,"text":"Und an jenem Tag pries Adam Gott und wurde erfüllt und fing an, in Bezug auf alle Familien der Erde zu prophezeien, nämlich: Gepriesen sei der Name Gottes, denn wegen meiner Übertretung sind mir die Augen aufgegangen, und in diesem Leben werde ich Freude haben, und wiederum im Fleische werde ich Gott schauen."},{"verse":11,"text":"Und Eva, seine Frau, hörte das alles und war froh und sagte: Wenn wir nicht übertreten hätten, so hätten wir nie Nachkommen gehabt und hätten nie Gut und Böse erkannt, auch nicht die Freude unserer Erlösung und das ewige Leben, das Gott allen gibt, die gehorsam sind."},{"verse":12,"text":"Und Adam und Eva priesen den Namen Gottes, und sie taten alles ihren Söhnen und ihren Töchtern kund."},{"verse":13,"text":"Und der Satan kam unter sie und sprach: Ich bin auch ein Sohn Gottes; und er gebot ihnen, nämlich: Glaubt es nicht! Und sie glaubten es nicht, und sie liebten den Satan mehr als Gott. Und die Menschen fingen an, von der Zeit an fleischlich, sinnlich und teuflisch zu sein."},{"verse":14,"text":"Und Gott, der Herr, rief durch den Heiligen Geist die Menschen überall auf und gebot ihnen umzukehren;"},{"verse":15,"text":"und alle, die an den Sohn glaubten und von ihren Sünden umkehrten, würden errettet werden, und alle, die nicht glaubten und nicht umkehrten, würden verdammt werden; und die Worte gingen aus dem Mund Gottes als ein fester Beschluss hervor; darum müssen sie sich erfüllen."},{"verse":16,"text":"Und Adam und Eva, seine Frau, hörten nicht auf, Gott anzurufen. Und Adam erkannte Eva, seine Frau, und sie wurde schwanger und gebar Kain und sprach: Ich habe einen Mann vom Herrn bekommen; möge er darum seine Worte nicht verwerfen. Aber siehe, Kain hörte nicht und sprach: Wer ist der Herr, dass ich ihn kennen sollte?"},{"verse":17,"text":"Und sie wurde abermals schwanger und gebar seinen Bruder Abel. Und Abel hörte auf die Stimme des Herrn. Und Abel wurde ein Schafhirte, aber Kain wurde ein Ackersmann."},{"verse":18,"text":"Und Kain liebte den Satan mehr als Gott. Und der Satan gebot ihm, nämlich: Bereite ein Opfer für den Herrn!"},{"verse":19,"text":"Und im Laufe der Zeit begab es sich: Kain brachte dem Herrn von der Frucht des Erdbodens ein Opfer dar."},{"verse":20,"text":"Und Abel, er brachte auch von den Erstlingen seiner Herde und von ihrem Fett dar. Und der Herr achtete auf Abel und auf sein Opfer;"},{"verse":21,"text":"aber auf Kain und auf sein Opfer achtete er nicht. Nun wusste der Satan das, und es gefiel ihm wohl. Und Kain ergrimmte sehr, und sein Antlitz senkte sich."},{"verse":22,"text":"Und der Herr sprach zu Kain: Warum bist du ergrimmt? Warum hat sich dein Antlitz gesenkt?"},{"verse":23,"text":"Wenn du wohl tust, wirst du angenommen werden. Aber wenn du nicht wohl tust, so liegt die Sünde vor der Tür, und der Satan möchte dich haben; und wenn du nicht auf meine Gebote hörst, werde ich dich überantworten, und es wird mit dir geschehen, wie er es möchte. Und du wirst über ihn herrschen;"},{"verse":24,"text":"denn von dieser Zeit an wirst du der Vater seiner Lügen sein; du wirst Verderben heißen, denn auch du warst, ehe die Welt war."},{"verse":25,"text":"Und man wird in künftiger Zeit sagen: Diese Gräuel kommen von Kain her; denn er hat den besseren Rat verworfen, der von Gott her gekommen ist; und dies ist ein Fluch, den ich auf dich legen werde, wenn du nicht umkehrst."},{"verse":26,"text":"Und Kain ergrimmte und hörte nicht mehr auf die Stimme des Herrn und auch nicht auf Abel, seinen Bruder, der in Heiligkeit vor dem Herrn wandelte."},{"verse":27,"text":"Und Adam und seine Frau trauerten vor dem Herrn wegen Kain und seiner Brüder."},{"verse":28,"text":"Und es begab sich: Kain nahm eine der Töchter seiner Brüder zur Frau, und sie liebten den Satan mehr als Gott."},{"verse":29,"text":"Und der Satan sprach zu Kain: Schwöre mir bei deiner Kehle, und wenn du es verrätst, wirst du sterben; und lass auch deine Brüder bei ihrem Haupt und beim lebendigen Gott schwören, dass sie es nicht verraten werden; denn wenn sie es verraten, werden sie sicherlich sterben; und dies, damit dein Vater nichts davon weiß; und heute will ich deinen Bruder Abel in deine Hände geben."},{"verse":30,"text":"Und der Satan schwor dem Kain, er werde gemäß seinem Befehl handeln. Und dies alles geschah im Geheimen."},{"verse":31,"text":"Und Kain sprach: Ich bin wahrhaftig Mahan, der Meister dieses großen Geheimnisses, dass ich morden und Gewinn erlangen kann. Darum wurde Kain Meister Mahan genannt, und er rühmte sich seiner Schlechtigkeit."},{"verse":32,"text":"Und Kain ging auf das Feld, und Kain sprach mit Abel, seinem Bruder. Und es begab sich: Als sie auf dem Feld waren, erhob sich Kain gegen Abel, seinen Bruder, und erschlug ihn."},{"verse":33,"text":"Und Kain rühmte sich dessen, was er getan hatte, nämlich: Ich bin frei; sicherlich fallen die Herden meines Bruders in meine Hände."},{"verse":34,"text":"Und der Herr sprach zu Kain: Wo ist Abel, dein Bruder? Und er sprach: Ich weiß nicht. Bin ich meines Bruders Hüter?"},{"verse":35,"text":"Und der Herr sprach: Was hast du getan? Die Stimme des Blutes deines Bruders schreit vom Erdboden her zu mir!"},{"verse":36,"text":"Und nun, verflucht seist du von der Erde, die ihren Mund aufgetan hat, das Blut deines Bruders von deiner Hand zu empfangen."},{"verse":37,"text":"Wenn du den Erdboden bebaust, wird er dir hinfort seine Kraft nicht geben. Ein Flüchtling und ein unsteter Wanderer wirst du sein auf Erden."},{"verse":38,"text":"Und Kain sprach zum Herrn: Der Satan hat mich wegen der Herden meines Bruders versucht. Und ich war auch ergrimmt, denn sein Opfer hast du angenommen und meines nicht; meine Strafe ist zu groß, als dass ich sie tragen kann."},{"verse":39,"text":"Siehe, du hast mich heute vom Angesicht des Herrn vertrieben, und vor deinem Angesicht werde ich verborgen sein; und ich werde ein Flüchtling und ein unsteter Wanderer sein auf Erden. Und es wird sich begeben: Wer mich findet, wird mich meiner Übeltaten wegen erschlagen, denn diese sind vor dem Herrn nicht verborgen."},{"verse":40,"text":"Und ich, der Herr, sprach zu ihm: Wer auch immer dich erschlägt, siebenfach soll Vergeltung geübt werden an ihm! Und ich, der Herr, machte an Kain ein Zeichen, damit niemand ihn umbrächte, der ihn fände."},{"verse":41,"text":"Und Kain wurde aus der Gegenwart des Herrn ausgeschlossen und wohnte mit seiner Frau und vielen seiner Brüder im Lande Nod, östlich von Eden."},{"verse":42,"text":"Und Kain erkannte seine Frau, und sie wurde schwanger und gebar Henoch, und er zeugte auch viele Söhne und Töchter. Und er baute eine Stadt, und er gab der Stadt den Namen nach dem Namen seines Sohnes Henoch."},{"verse":43,"text":"Und dem Henoch wurde Irad geboren und weitere Söhne und Töchter. Und Irad zeugte Mahujaël und weitere Söhne und Töchter. Und Mahujaël zeugte Metuschaël und weitere Söhne und Töchter. Und Metuschaël zeugte Lamech."},{"verse":44,"text":"Und Lamech nahm sich zwei Frauen; der Name der einen war Ada und der Name der anderen Zilla."},{"verse":45,"text":"Und Ada gebar Jabal; er wurde der Vater derer, die in Zelten wohnen, und sie waren Viehhüter. Und sein Bruder hieß Jubal, er wurde der Vater all derer, die mit der Harfe und der Flöte umgehen."},{"verse":46,"text":"Und Zilla, auch sie gebar, nämlich Tubal-Kain, der alle diejenigen unterwies, die Messing und Eisen bearbeiteten. Und die Schwester Tubal-Kains hieß Naama."},{"verse":47,"text":"Und Lamech sprach zu seinen Frauen Ada und Zilla: Vernehmt meine Stimme, ihr Frauen Lamechs, und hört auf meine Rede; denn ich habe einen Mann erschlagen für meine Wunde und einen Jüngling für meine Strieme."},{"verse":48,"text":"Wenn Kain siebenfach gerächt werden soll, wahrhaftig, dann Lamech siebenundsiebzigfach!"},{"verse":49,"text":"Denn Lamech war mit dem Satan ein Bündnis eingegangen nach der Weise Kains, wodurch er Meister Mahan wurde, ein Meister jenes großen Geheimnisses, das dem Kain vom Satan zuteilwurde; und Irad, Henochs Sohn, der ihr Geheimnis kannte, fing an, es den Söhnen Adams zu offenbaren;"},{"verse":50,"text":"darum erschlug Lamech ihn im Zorn, nicht wie Kain seinen Bruder Abel, um Gewinn zu erlangen, sondern er erschlug ihn um des Eides willen."},{"verse":51,"text":"Denn seit den Tagen Kains gab es eine geheime Verbindung, und ihre Werke geschahen in Finsternis, und ein jeder erkannte seinen Bruder."},{"verse":52,"text":"Der Herr verfluchte darum Lamech und sein Haus und alle diejenigen, die mit dem Satan einen Bund gemacht hatten; denn sie hielten die Gebote Gottes nicht, und das missfiel Gott, und er teilte sich ihnen nicht mit, und ihre Werke waren Gräuel und fingen an, sich unter allen Söhnen der Menschen zu verbreiten. Und dies war unter den Söhnen der Menschen."},{"verse":53,"text":"Und unter den Töchtern der Menschen wurde darüber nicht gesprochen, weil Lamech das Geheimnis seinen Frauen gesagt hatte, und sie lehnten sich gegen ihn auf und verkündeten diese Sache allerorten und hatten kein Mitleid;"},{"verse":54,"text":"darum wurde Lamech verachtet und ausgestoßen und begab sich nicht unter die Söhne der Menschen, damit er nicht sterbe."},{"verse":55,"text":"Und so nahmen die Werke der Finsternis unter allen Söhnen der Menschen allmählich überhand."},{"verse":56,"text":"Und Gott verfluchte die Erde mit einem schweren Fluch und war zornig auf die Schlechten, auf alle Söhne der Menschen, die er gemacht hatte,"},{"verse":57,"text":"denn sie wollten nicht auf seine Stimme hören und auch nicht an seinen einziggezeugten Sohn glauben, nämlich den, der, wie er verkündet hatte, in der Mitte der Zeit kommen würde und der von vor der Grundlegung der Welt an bereitet worden war."},{"verse":58,"text":"Und so fing das Evangelium an, von Anbeginn gepredigt zu werden, und es wurde von heiligen Engeln verkündet, die aus der Gegenwart Gottes ausgesandt wurden, und von seiner eigenen Stimme und durch die Gabe des Heiligen Geistes."},{"verse":59,"text":"Und so wurde Adam alles durch eine heilige Verordnung bestätigt und das Evangelium gepredigt und der Beschluss ausgesandt, dass es in der Welt sein solle bis an ihr Ende; und so geschah es. Amen."}]},{"chapter":6,"verses":[{"verse":1,"text":"Und Adam hörte auf die Stimme Gottes und rief seine Söhne zur Umkehr."},{"verse":2,"text":"Und Adam erkannte seine Frau abermals, und sie gebar einen Sohn, und er gab ihm den Namen Set. Und Adam verherrlichte den Namen Gottes; denn er sprach: Gott hat mir einen anderen Nachkommen bestimmt anstelle Abels, den Kain erschlagen hat."},{"verse":3,"text":"Und Gott offenbarte sich dem Set, und er lehnte sich nicht auf, sondern brachte ein annehmbares Opfer dar wie sein Bruder Abel. Und auch ihm wurde ein Sohn geboren, und er gab ihm den Namen Enosch."},{"verse":4,"text":"Und dann fingen diese Männer an, den Namen des Herrn anzurufen, und der Herr segnete sie;"},{"verse":5,"text":"und ein Buch der Erinnerung wurde geführt, worin in der Sprache Adams Aufzeichnungen gemacht wurden; denn allen, die Gott anriefen, wurde es gegeben, durch den Geist der Inspiration zu schreiben;"},{"verse":6,"text":"und sie lehrten ihre Kinder lesen und schreiben, und sie hatten eine Sprache, die rein und unverdorben war."},{"verse":7,"text":"Nun wird ebendasselbe Priestertum, das am Anfang war, auch am Ende der Welt sein."},{"verse":8,"text":"Diese Prophezeiung nun sprach Adam aus, als er vom Heiligen Geist dazu bewogen wurde, und von den Kindern Gottes wurde eine Stammtafel geführt. Und das Buch der Generationen Adams ist dies, nämlich: An dem Tag, da Gott den Menschen erschuf, da machte er ihn Gott selbst ähnlich;"},{"verse":9,"text":"als Abbild seines eigenen Leibes, männlich und weiblich, erschuf er sie und segnete sie und gab ihnen den Namen Adam an dem Tag, da sie erschaffen wurden und im Land auf dem Fußschemel Gottes zu lebenden Seelen wurden."},{"verse":10,"text":"Und Adam lebte einhundertdreißig Jahre und zeugte einen Sohn, der ihm selbst ähnlich war wie sein eigenes Abbild, und gab ihm den Namen Set."},{"verse":11,"text":"Und die Tage Adams, nachdem er Set gezeugt hatte, waren achthundert Jahre, und er zeugte viele Söhne und Töchter;"},{"verse":12,"text":"und alle Tage Adams, die er lebte, waren neunhundertdreißig Jahre, und er starb."},{"verse":13,"text":"Set lebte einhundertfünf Jahre und zeugte Enosch und prophezeite alle seine Tage und belehrte seinen Sohn Enosch in den Wegen Gottes; darum prophezeite auch Enosch."},{"verse":14,"text":"Und Set lebte, nachdem er Enosch gezeugt hatte, achthundertsieben Jahre und zeugte viele Söhne und Töchter."},{"verse":15,"text":"Und die Menschenkinder wurden zahlreich im ganzen Land. Und in jenen Tagen hatte der Satan große Herrschaft unter den Menschen und wütete in ihrem Herzen; und von da an kam es zu Kriegen und Blutvergießen; und die Hand eines Mannes war gegen seinen eigenen Bruder, ihm den Tod zu bringen, wegen der geheimen Werke und des Strebens nach Macht."},{"verse":16,"text":"Alle Tage Sets waren neunhundertzwölf Jahre, und er starb."},{"verse":17,"text":"Und Enosch lebte neunzig Jahre und zeugte Kenan. Und Enosch und das übrige Volk Gottes zogen aus dem Land weg, das Schulon genannt wurde, und wohnten in einem Land der Verheißung, das er nach seinem eigenen Sohn benannte, den er Kenan genannt hatte."},{"verse":18,"text":"Und Enosch lebte, nachdem er Kenan gezeugt hatte, achthundertfünfzehn Jahre und zeugte viele Söhne und Töchter. Und alle Tage Enoschs waren neunhundertfünf Jahre, und er starb."},{"verse":19,"text":"Und Kenan lebte siebzig Jahre und zeugte Mahalalel; und Kenan lebte, nachdem er Mahalalel gezeugt hatte, achthundertvierzig Jahre und zeugte Söhne und Töchter. Und alle Tage Kenans waren neunhundertzehn Jahre, und er starb."},{"verse":20,"text":"Und Mahalalel lebte fünfundsechzig Jahre und zeugte Jered; und Mahalalel lebte, nachdem er Jered gezeugt hatte, achthundertdreißig Jahre und zeugte Söhne und Töchter. Und alle Tage Mahalalels waren achthundertfünfundneunzig Jahre, und er starb."},{"verse":21,"text":"Und Jered lebte einhundertzweiundsechzig Jahre und zeugte Henoch; und Jered lebte, nachdem er Henoch gezeugt hatte, achthundert Jahre und zeugte Söhne und Töchter. Und Jered belehrte Henoch in allen Wegen Gottes."},{"verse":22,"text":"Und dies ist die Stammtafel der Söhne Adams, der der Sohn Gottes war, mit dem Gott selbst redete."},{"verse":23,"text":"Und sie waren Prediger der Rechtschaffenheit und sprachen und prophezeiten und riefen überall alle Menschen zur Umkehr; und Glaube wurden die Menschenkinder gelehrt."},{"verse":24,"text":"Und es begab sich: Alle Tage Jereds waren neunhundertzweiundsechzig Jahre, und er starb."},{"verse":25,"text":"Und Henoch lebte fünfundsechzig Jahre und zeugte Metuschelach."},{"verse":26,"text":"Und es begab sich: Henoch zog im Land umher, unter dem Volk; und als er umherzog, kam der Geist Gottes aus dem Himmel herab und ruhte auf ihm."},{"verse":27,"text":"Und er vernahm eine Stimme vom Himmel, nämlich: Henoch, mein Sohn, prophezeie diesem Volk und sprich zu ihm: Kehrt um, denn so spricht der Herr: Ich bin zornig auf dieses Volk, und mein grimmiger Zorn ist gegen es entflammt; denn sein Herz ist hart geworden, und seine Ohren sind schwerhörig, und seine Augen können nicht weit sehen;"},{"verse":28,"text":"und diese vielen Generationen lang, ja, seit dem Tag, da ich die Menschen erschaffen habe, gehen sie irre und leugnen mich und suchen in der Finsternis ihren eigenen Rat; und in ihren eigenen Gräueln ersinnen sie Mord und halten nicht die Gebote, die ich ihrem Vater Adam gegeben habe."},{"verse":29,"text":"Darum haben sie falsch geschworen, und durch ihre Eide haben sie den Tod über sich gebracht; und eine Hölle habe ich für sie bereitet, wenn sie nicht umkehren;"},{"verse":30,"text":"und dies ist ein Beschluss, den ich am Anfang der Welt, von ihrer Grundlegung an, aus meinem eigenen Mund ausgesandt habe, und durch den Mund meiner Diener, deiner Väter, habe ich ihn verkündet, ja, wie er in die Welt hinausgesandt werden wird bis an ihre Enden."},{"verse":31,"text":"Und als Henoch diese Worte vernommen hatte, neigte er sich vor dem Herrn zur Erde und sprach vor dem Herrn, nämlich: Wieso habe ich Gunst gefunden in deinen Augen und bin doch nur ein Knabe und alles Volk hasst mich; denn meine Sprache ist unbeholfen; warum also bin ich dein Diener?"},{"verse":32,"text":"Und der Herr sprach zu Henoch: Gehe hin und tue, wie ich dir geboten habe, und niemand wird dich durchbohren. Tue deinen Mund auf, und er wird erfüllt werden, und ich werde dir zu reden eingeben; denn alles Fleisch ist in meiner Hand, und ich werde tun, wie es mir gut scheint."},{"verse":33,"text":"Sprich zu diesem Volk: Wählt euch heute, Gott, dem Herrn, zu dienen, der euch gemacht hat."},{"verse":34,"text":"Siehe, mein Geist ruht auf dir, darum werde ich alle deine Worte rechtfertigen; und die Berge werden vor dir weichen, und die Flüsse werden sich aus ihrem Lauf wenden, und du wirst in mir verbleiben und ich in dir; darum wandle mit mir!"},{"verse":35,"text":"Und der Herr sprach zu Henoch und sagte zu ihm: Salbe dir die Augen mit Lehm, und wasche sie, dann wirst du sehen. Und er tat es."},{"verse":36,"text":"Und er sah die Geister, die Gott erschaffen hatte, und er sah auch Dinge, die für das natürliche Auge nicht sichtbar sind; und von da an ging die Rede durch das ganze Land: Einen Seher hat der Herr für sein Volk erweckt."},{"verse":37,"text":"Und es begab sich: Henoch ging hin in das Land, unter das Volk, stellte sich auf die Hügel und die hohen Plätze und rief mit lauter Stimme und zeugte gegen seine Werke; und alle Menschen nahmen Anstoß an ihm."},{"verse":38,"text":"Und sie gingen hin zu den hohen Plätzen, um ihn zu hören, und sie sprachen zu den Hütern der Zelte: Bleibt ihr hier und hütet die Zelte, während wir hinüber gehen, um den Seher zu betrachten; denn er prophezeit, und Seltsames geht vor im Land; ein wilder Mann ist zu uns gekommen."},{"verse":39,"text":"Und es begab sich: Als sie ihn hörten, legte niemand Hand an ihn; denn Furcht überkam alle, die ihn hörten; denn er wandelte mit Gott."},{"verse":40,"text":"Und es kam zu ihm ein Mann, der Machija hieß, und sprach zu ihm: Sage uns klar, wer du bist und von woher du kommst."},{"verse":41,"text":"Und er sprach zu ihnen: Ich bin aus dem Land Kenan gekommen, dem Land meiner Väter, einem Land der Rechtschaffenheit bis zum heutigen Tag. Und mein Vater hat mich in allen Wegen Gottes belehrt."},{"verse":42,"text":"Und es begab sich: Als ich aus dem Land Kenan zog, am Meer im Osten, da sah ich eine Vision; und siehe, die Himmel erblickte ich, und der Herr sprach mit mir und gab mir ein Gebot; aus diesem Grund also, um das Gebot zu halten, spreche ich diese Worte aus."},{"verse":43,"text":"Und Henoch fuhr in seiner Rede fort, nämlich: Der Herr, der mit mir gesprochen hat, derselbe ist der Gott des Himmels, und er ist mein Gott und euer Gott, und ihr seid meine Brüder, und warum sucht ihr Rat bei euch selbst und leugnet den Gott des Himmels?"},{"verse":44,"text":"Die Himmel hat er gemacht, die Erde ist sein Fußschemel, und ihre Grundlage ist sein. Siehe, er hat sie gelegt, und eine Schar von Menschen hat er auf sie gebracht."},{"verse":45,"text":"Und Tod ist über unsere Väter gekommen; und doch kennen wir sie und können nicht leugnen, ja, und alle, selbst den ersten von allen, kennen wir, nämlich Adam."},{"verse":46,"text":"Denn ein Buch der Erinnerung haben wir bei uns geschrieben gemäß dem Muster, das durch den Finger Gottes gegeben worden ist; und es ist in unserer eigenen Sprache gegeben."},{"verse":47,"text":"Und als Henoch die Worte Gottes aussprach, zitterte das Volk und konnte in seiner Gegenwart nicht bestehen."},{"verse":48,"text":"Und er sprach zu ihm: Weil Adam gefallen ist, sind wir; und durch seinen Fall ist der Tod gekommen; und wir haben an Elend und Weh teil."},{"verse":49,"text":"Siehe, der Satan ist unter die Menschenkinder gekommen und verleitet sie dazu, ihn anzubeten; und die Menschen sind fleischlich, sinnlich und teuflisch geworden und sind aus der Gegenwart Gottes ausgeschlossen."},{"verse":50,"text":"Aber Gott hat unseren Vätern kundgetan, dass alle Menschen umkehren müssen."},{"verse":51,"text":"Und er rief unseren Vater Adam mit seiner eigenen Stimme an, nämlich: Ich bin Gott; ich habe die Welt gemacht und die Menschen, ehe sie im Fleische waren."},{"verse":52,"text":"Und er sprach zu ihm auch: Wenn du dich mir zuwenden und auf meine Stimme hören willst und glauben und von all deinen Übertretungen umkehren und dich taufen lassen willst, nämlich im Wasser, im Namen meines einziggezeugten Sohnes, der voller Gnade und Wahrheit ist, nämlich Jesus Christus, der einzige Name, der unter dem Himmel gegeben wird, wodurch den Menschenkindern Errettung zuteilwird, dann wirst du die Gabe des Heiligen Geistes empfangen und sollst alles in seinem Namen erbitten, und was auch immer du erbitten wirst, das wird dir gegeben werden."},{"verse":53,"text":"Und unser Vater Adam sprach zum Herrn und sagte: Wieso müssen die Menschen umkehren und sich im Wasser taufen lassen? Und der Herr sprach zu Adam: Siehe, deine Übertretung im Garten von Eden habe ich dir vergeben."},{"verse":54,"text":"Daher kam unter dem Volk überall die Rede auf, der Sohn Gottes habe die ursprüngliche Schuld gesühnt, wodurch die Sünden der Eltern nicht auf dem Haupt der Kinder zu verantworten sind, denn diese sind von der Grundlegung der Welt an heil."},{"verse":55,"text":"Und der Herr sprach zu Adam, nämlich: Weil deine Kinder in Sünde empfangen sind, ja, so wird die Sünde in ihrem Herzen empfangen, wenn sie anfangen aufzuwachsen; und sie schmecken das Bittere, damit sie das Gute zu würdigen wissen."},{"verse":56,"text":"Und es ist ihnen gegeben, Gut von Böse zu unterscheiden; darum können sie für sich selbst handeln, und ich habe euch noch weiteres Gesetz und Gebot gegeben."},{"verse":57,"text":"Darum lehre dies deine Kinder, dass alle Menschen, wo auch immer, umkehren müssen, sonst können sie keinesfalls das Reich Gottes ererben, denn nichts Unreines kann dort wohnen oder in seiner Gegenwart wohnen; denn in der Sprache Adams ist sein Name Mensch der Heiligkeit, und der Name seines Einziggezeugten ist des Menschen Sohn, ja, Jesus Christus, ein rechtschaffener Richter, der in der Mitte der Zeit kommen wird."},{"verse":58,"text":"Darum gebe ich dir das Gebot, dies alles deine Kinder frei und offen zu lehren, nämlich:"},{"verse":59,"text":"Infolge von Übertretung kommt der Fall, und der Fall bringt den Tod; und da ihr durch Wasser und Blut und den Geist in die Welt geboren wurdet, die ich gemacht habe, und so aus Staub zu einer lebenden Seele geworden seid, so müsst ihr von neuem in das Himmelreich geboren werden, nämlich aus Wasser und aus dem Geist, und müsst durch Blut gesäubert werden, nämlich das Blut meines Einziggezeugten, damit ihr von aller Sünde geheiligt werdet und euch erfreuen könnt an den Worten des ewigen Lebens in dieser Welt und an ewigem Leben in der künftigen Welt, ja, an unsterblicher Herrlichkeit;"},{"verse":60,"text":"denn durch das Wasser haltet ihr das Gebot, durch den Geist werdet ihr gerechtfertigt, und durch das Blut werdet ihr geheiligt;"},{"verse":61,"text":"darum ist es gegeben, dass es in euch verbleibe: das Zeugnis des Himmels, der Tröster, das Friedfertige der unsterblichen Herrlichkeit, die Wahrheit aller Dinge, das, was alles belebt, was alles lebendig macht, das, was alles weiß und alle Macht hat gemäß der Weisheit, Barmherzigkeit, Wahrheit, Gerechtigkeit und Rechtsprechung."},{"verse":62,"text":"Und nun siehe, ich sage dir: Das ist der Plan der Errettung für alle Menschen, durch das Blut meines Einziggezeugten, der in der Mitte der Zeit kommen wird."},{"verse":63,"text":"Und siehe, alles hat sein Gleichnis, und alles ist erschaffen und gemacht worden, dass es von mir Zeugnis gebe, sowohl das, was zeitlich ist, als auch das, was geistig ist; das, was oben in den Himmeln ist, und das, was auf der Erde ist, und das, was in der Erde ist, und das, was unter der Erde ist – oben wie unten: Alles gibt Zeugnis von mir."},{"verse":64,"text":"Und es begab sich: Als der Herr mit Adam, unserem Vater, gesprochen hatte, da rief Adam zum Herrn, und er wurde vom Geist des Herrn hinweggeführt und wurde ins Wasser hinabgetragen und wurde unter Wasser gelegt und wurde aus dem Wasser hervorgebracht."},{"verse":65,"text":"Und so wurde er getauft, und der Geist Gottes kam auf ihn herab, und so wurde er aus dem Geist geboren und wurde im inneren Menschen belebt."},{"verse":66,"text":"Und er vernahm eine Stimme aus dem Himmel, nämlich: Du bist mit Feuer und mit dem Heiligen Geist getauft. Dies ist das Zeugnis des Vaters und des Sohnes, fortan und für immer;"},{"verse":67,"text":"und du bist nach der Ordnung dessen, der ohne Anfang der Tage oder Ende der Jahre ist, von aller Ewigkeit bis in alle Ewigkeit."},{"verse":68,"text":"Siehe, du bist eins in mir, ein Sohn Gottes; und so können alle meine Söhne werden. Amen."}]},{"chapter":7,"verses":[{"verse":1,"text":"Und es begab sich: Henoch setzte seine Rede fort, nämlich: Siehe, unser Vater Adam lehrte dies alles, und viele haben geglaubt und sind Söhne Gottes geworden, und viele haben nicht geglaubt und sind in ihren Sünden zugrunde gegangen, und in Qualen erwarten sie voll Furcht, dass der Grimm Gottes sich in feurigem Unwillen über sie ergießt."},{"verse":2,"text":"Und von der Zeit an fing Henoch zu prophezeien an, indem er zum Volk sprach, nämlich: Als ich umherzog und an dem Ort Machuja stand und zum Herrn rief, da kam aus dem Himmel eine Stimme, nämlich: Wende dich und begib dich auf den Berg Simeon."},{"verse":3,"text":"Und es begab sich: Ich wandte mich und stieg auf den Berg; und als ich auf dem Berg stand, sah ich die Himmel offen, und ich wurde von Herrlichkeit umhüllt;"},{"verse":4,"text":"und ich sah den Herrn, und er stand vor meinem Angesicht, und er redete mit mir, so wie ein Mensch mit dem anderen redet, von Angesicht zu Angesicht; und er sprach zu mir: Schaue, und ich werde dir die Welt über den Zeitraum vieler Generationen hinweg zeigen."},{"verse":5,"text":"Und es begab sich: Ich sah in das Tal Schum, und sieh da, ein großes Volk, das in Zelten wohnte, ja, das Volk Schum."},{"verse":6,"text":"Und der Herr sprach weiter zu mir: Schaue! Und ich schaute nach Norden, und ich sah das Volk Kanaan, das in Zelten wohnte."},{"verse":7,"text":"Und der Herr sprach zu mir: Prophezeie! Und ich prophezeite, nämlich: Siehe, das Volk Kanaan, das zahlreich ist, wird sich in Schlachtordnung gegen das Volk Schum aufmachen und wird es totschlagen, sodass es völlig vernichtet sein wird; und das Volk Kanaan wird sich im Land verteilen, und das Land wird dürr und unfruchtbar werden, und kein anderes Volk wird dort wohnen als nur das Volk Kanaan;"},{"verse":8,"text":"denn siehe, der Herr wird das Land mit großer Hitze verfluchen, und dessen Unfruchtbarkeit wird immerdar sein; und es kam Schwärze über all die Kinder Kanaan, sodass sie unter allem Volk verachtet wurden."},{"verse":9,"text":"Und es begab sich: Der Herr sprach zu mir: Schaue! Und ich schaute, und ich sah das Land Scharon und das Land Henoch und das Land Omner und das Land Heni und das Land Schem und das Land Haner und das Land Hananniha samt all ihren Bewohnern;"},{"verse":10,"text":"und der Herr sprach zu mir: Gehe hin zu diesem Volk und sprich zu ihm: Kehrt um!, dass ich nicht hinkomme und sie mit einem Fluch schlage und sie sterben."},{"verse":11,"text":"Und er gab mir das Gebot, ich solle im Namen des Vaters und des Sohnes, der voller Gnade und Wahrheit ist, und des Heiligen Geistes, der Zeugnis gibt für den Vater und den Sohn, taufen."},{"verse":12,"text":"Und es begab sich: Henoch rief weiterhin alles Volk zur Umkehr, außer das Volk Kanaan;"},{"verse":13,"text":"und so groß war der Glaube Henochs, dass er das Volk Gottes führte, und ihre Feinde zogen gegen sie zum Kampf heran; und er redete das Wort des Herrn, und die Erde erzitterte, und die Berge wichen hinweg, ja, gemäß seinem Gebot, und die Flüsse mit Wasser wandten sich aus ihrer Bahn, und das Brüllen der Löwen war aus der Wildnis zu hören; und alle Nationen fürchteten sich sehr, so mächtig war das Wort Henochs, und so groß war die Macht der Sprache, die Gott ihm gegeben hatte."},{"verse":14,"text":"Es kam auch ein Land aus der Tiefe des Meeres empor, und so groß war die Furcht der Feinde des Volkes Gottes, dass sie flohen und sich ferne hinstellten und auf das Land gingen, das aus der Tiefe des Meeres gekommen war."},{"verse":15,"text":"Und auch die Riesen des Landes stellten sich ferne hin; und es kam ein Fluch über alles Volk, was gegen Gott kämpfte;"},{"verse":16,"text":"und von der Zeit an gab es Kriege und Blutvergießen unter ihnen; aber der Herr kam und wohnte bei seinem Volk, und es lebte in Rechtschaffenheit."},{"verse":17,"text":"Die Furcht des Herrn lag auf allen Nationen, so groß war die Herrlichkeit des Herrn, die auf seinem Volk war. Und der Herr segnete das Land, und auf den Bergen war sein Volk gesegnet und auf den hohen Plätzen, und es erging ihm wohl."},{"verse":18,"text":"Und der Herr nannte sein Volk Zion, weil es eines Herzens und eines Sinnes war und in Rechtschaffenheit lebte; und es gab keine Armen unter ihm."},{"verse":19,"text":"Und Henoch fuhr fort, dem Volk Gottes in Rechtschaffenheit zu predigen. Und es begab sich: In seinen Tagen baute er eine Stadt, die man die Stadt der Heiligkeit nannte, nämlich Zion."},{"verse":20,"text":"Und es begab sich: Henoch redete mit dem Herrn, und er sprach zum Herrn: Gewiss wird Zion immerdar in Sicherheit wohnen. Aber der Herr sprach zu Henoch: Zion habe ich gesegnet, aber das übrige Volk habe ich verflucht."},{"verse":21,"text":"Und es begab sich: Der Herr zeigte Henoch alle Bewohner der Erde; und er sah, und sieh da, Zion wurde im Laufe der Zeit in den Himmel aufgenommen. Und der Herr sprach zu Henoch: Sieh meine Wohnstätte immerdar!"},{"verse":22,"text":"Und Henoch sah auch das übrige Volk der Söhne Adams; und es war ein Gemisch aus allen Nachkommen Adams außer den Nachkommen Kains, denn die Nachkommen Kains waren schwarz und hatten unter ihnen keinen Platz."},{"verse":23,"text":"Und nachdem Zion in den Himmel aufgenommen worden war, schaute Henoch, und sieh da, alle Nationen der Erde waren vor ihm;"},{"verse":24,"text":"und es kam Generation auf Generation; und Henoch war hoch und emporgehoben, selbst im Schoß des Vaters und des Menschensohnes; und siehe, die Macht des Satans war über der ganzen Erde."},{"verse":25,"text":"Und er sah Engel aus dem Himmel niedersteigen, und er hörte eine laute Stimme, nämlich: Wehe, weh sei den Bewohnern der Erde!"},{"verse":26,"text":"Und er sah den Satan, und er hatte eine große Kette in der Hand, und sie verschleierte die ganze Erde mit Finsternis; und er schaute auf und lachte, und seine Engel freuten sich."},{"verse":27,"text":"Und Henoch sah Engel aus dem Himmel niedersteigen, die Zeugnis ablegten vom Vater und Sohn; und der Heilige Geist fiel auf viele, und sie wurden durch die Mächte des Himmels ins Zion entrückt."},{"verse":28,"text":"Und es begab sich: Der Gott des Himmels blickte auf das übrige Volk, und er weinte; und Henoch gab dafür Zeugnis, nämlich: Wieso weinen die Himmel und vergießen Tränen wie Regen, der auf die Berge fällt?"},{"verse":29,"text":"Und Henoch sprach zum Herrn: Wieso kannst du weinen, wo du doch heilig bist und von aller Ewigkeit bis in alle Ewigkeit?"},{"verse":30,"text":"Und wäre es möglich, dass der Mensch die Teilchen der Erde zählen könnte, ja, Millionen Erden gleich dieser, so wäre das noch nicht einmal der Anfang der Zahl deiner Schöpfungen; und deine Vorhänge sind noch immer ausgespannt; und doch bist du da, und dein Schoß ist da; und du bist auch gerecht; du bist barmherzig und wohlwollend immerdar;"},{"verse":31,"text":"und du hast Zion in deinen eigenen Schoß aufgenommen, aus all deinen Schöpfungen, von aller Ewigkeit bis in alle Ewigkeit; und nichts als Frieden, Gerechtigkeit und Wahrheit ist die Stätte deines Thrones; und Barmherzigkeit wird vor deinem Angesicht einhergehen und kein Ende haben; wieso kannst du weinen?"},{"verse":32,"text":"Der Herr sprach zu Henoch: Sieh diese deine Brüder; sie sind das Werk meiner eigenen Hände, und ich gab ihnen ihre Erkenntnis an dem Tag, da ich sie erschuf; und im Garten von Eden gab ich dem Menschen seine Entscheidungsfreiheit;"},{"verse":33,"text":"und deinen Brüdern habe ich gesagt und auch das Gebot gegeben, dass sie einander lieben sollen und dass sie mich, ihren Vater, erwählen sollen; aber siehe, sie sind lieblos, und sie hassen ihr eigenes Blut;"},{"verse":34,"text":"und das Feuer meines Unwillens ist gegen sie entflammt, und in meinem glühenden Unmut werde ich die Fluten über sie herabsenden, denn mein grimmiger Zorn ist gegen sie entflammt."},{"verse":35,"text":"Siehe, ich bin Gott; Mensch der Heiligkeit ist mein Name; Mensch des Rates ist mein Name; und auch Endlos und Ewig ist mein Name."},{"verse":36,"text":"Darum kann ich meine Hände ausstrecken und alle Schöpfungen fassen, die ich gemacht habe; und auch mein Auge kann sie durchdringen, und unter allen Werken meiner Hände hat es keine so große Schlechtigkeit gegeben wie unter deinen Brüdern."},{"verse":37,"text":"Aber siehe, ihre Sünden werden ihren Vätern auf dem Haupt liegen; der Satan wird ihr Vater sein, und Elend wird ihr Los sein; und alle Himmel werden über sie weinen, ja, das ganze Werk meiner Hände; warum also sollen die Himmel nicht weinen, in Anbetracht dessen, dass diese leiden werden?"},{"verse":38,"text":"Aber siehe, diese, auf denen deine Augen ruhen, werden in den Fluten zugrunde gehen; und siehe, ich werde sie einschließen, ein Gefängnis habe ich für sie bereitet."},{"verse":39,"text":"Und das, was ich erwählt habe, hat sich vor meinem Angesicht eingesetzt. Darum leidet er für ihre Sünden, insoweit sie umkehren an dem Tag, da mein Erwählter zu mir zurückkehren wird, und bis zu dem Tag werden sie Qualen leiden;"},{"verse":40,"text":"darum werden darüber die Himmel weinen, ja, und das ganze Werk meiner Hände."},{"verse":41,"text":"Und es begab sich: Der Herr sprach zu Henoch und berichtete Henoch alles Tun der Menschenkinder; darum wusste Henoch und blickte auf ihre Schlechtigkeit und ihr Elend und weinte und streckte seine Arme aus, und sein Herz schwoll so weit wie die Ewigkeit, und sein Inneres war sehr bewegt; und die ganze Ewigkeit bebte."},{"verse":42,"text":"Und Henoch sah auch Noach und seine Familie, dass die Nachkommenschaft aller Söhne Noachs mit einer zeitlichen Errettung errettet werden würde;"},{"verse":43,"text":"darum sah Henoch, dass Noach eine Arche baute und dass der Herr auf sie herablächelte und sie in seiner eigenen Hand hielt; aber über die Übrigen, die Schlechten, brachen die Fluten herein und verschlangen sie."},{"verse":44,"text":"Und als Henoch dies sah, wurde seine Seele bitter, und er weinte über seine Brüder und sprach zu den Himmeln: Ich will nicht getröstet sein! Aber der Herr sprach zu Henoch: Hebe dein Herz empor und sei froh und schaue!"},{"verse":45,"text":"Und es begab sich: Henoch schaute, und von Noach an erblickte er alle Familien der Erde; und er rief zum Herrn, nämlich: Wann wird der Tag des Herrn kommen? Wann wird das Blut des Rechtschaffenen vergossen werden, damit alle, die trauern, geheiligt werden und ewiges Leben haben können?"},{"verse":46,"text":"Und der Herr sprach: Es wird in der Mitte der Zeit sein, in den Tagen der Schlechtigkeit und Vergeltung."},{"verse":47,"text":"Und siehe, Henoch schaute den Tag, da des Menschen Sohn kam, ja, im Fleisch; und seine Seele freute sich und sprach: Der Rechtschaffene wird emporgehoben, und das Lamm von Grundlegung der Welt an wird getötet; und durch den Glauben bin ich im Schoß des Vaters, und siehe, Zion ist bei mir."},{"verse":48,"text":"Und es begab sich: Henoch schaute auf die Erde, und er hörte eine Stimme aus deren Innerem, nämlich: Weh, weh ist mir, der Mutter der Menschen; ich bin gepeinigt, ich bin müde wegen der Schlechtigkeit meiner Kinder. Wann werde ich ruhen und von dem Schmutz gesäubert werden, der aus mir hervorgegangen ist? Wann wird mein Schöpfer mich heiligen, damit ich ruhen mag und Rechtschaffenheit eine Zeit lang auf mir wohne?"},{"verse":49,"text":"Und als Henoch die Erde trauern hörte, weinte er und rief zum Herrn, nämlich: O Herr, wirst du kein Mitleid mit der Erde haben? Wirst du die Kinder Noach nicht segnen?"},{"verse":50,"text":"Und es begab sich: Henoch fuhr fort, zum Herrn zu rufen, nämlich: Ich bitte dich, o Herr, im Namen deines Einziggezeugten, nämlich Jesus Christus, habe Erbarmen mit Noach und seinen Nachkommen, dass die Erde nie wieder von den Fluten bedeckt werde."},{"verse":51,"text":"Und der Herr konnte es nicht versagen; und er machte mit Henoch einen Bund und schwor ihm mit einem Eid, er würde die Fluten zurückhalten, er würde die Kinder Noach anrufen;"},{"verse":52,"text":"und er sandte den unabänderlichen Beschluss aus, dass ein Rest seiner Nachkommen zu allen Zeiten unter allen Nationen zu finden sein werde, solange die Erde bestehe;"},{"verse":53,"text":"und der Herr sprach: Gesegnet ist der, aus dessen Nachkommen Messias kommen wird, denn er spricht: Ich bin Messias, der König Zions, der Fels des Himmels, der weit ist wie die Ewigkeit; wer durch das Tor hereinkommt und durch mich emporsteigt, wird niemals fallen; gesegnet sind darum diejenigen, von denen ich gesprochen habe, denn sie werden mit Liedern immerwährender Freude hervorkommen."},{"verse":54,"text":"Und es begab sich: Henoch rief zum Herrn, nämlich: Wenn des Menschen Sohn im Fleische kommt, wird dann die Erde ruhen? Ich bitte dich, zeige mir das alles!"},{"verse":55,"text":"Und der Herr sprach zu Henoch: Schaue! Und er schaute und sah des Menschen Sohn nach der Weise der Menschen auf das Kreuz emporgehoben;"},{"verse":56,"text":"und er hörte eine laute Stimme, und die Himmel waren verschleiert, und alle Schöpfungen Gottes trauerten, und die Erde stöhnte, und die Felsen spalteten sich, und die Heiligen standen auf und wurden zur rechten Hand des Menschensohnes mit Kronen der Herrlichkeit gekrönt;"},{"verse":57,"text":"und alle Geister, die im Gefängnis waren, kamen hervor und standen zur rechten Hand Gottes, und die Übrigen wurden bis zum Gericht des großen Tages in Ketten der Finsternis behalten."},{"verse":58,"text":"Und wiederum weinte Henoch und rief zum Herrn, nämlich: Wann wird die Erde ruhen?"},{"verse":59,"text":"Und Henoch sah des Menschen Sohn auffahren zum Vater; und er rief den Herrn an, nämlich: Wirst du nicht wieder auf die Erde kommen? Denn du bist Gott, und ich kenne dich, und du hast mir geschworen und mir geboten, im Namen deines Einziggezeugten zu bitten; du hast mich gemacht und mir ein Recht auf deinen Thron gegeben, und nicht aus mir selbst, sondern durch deine eigene Gnade; darum frage ich dich, ob du nicht wieder auf die Erde kommen wirst."},{"verse":60,"text":"Und der Herr sprach zu Henoch: So wahr ich lebe, so werde ich in den letzten Tagen kommen, in den Tagen der Schlechtigkeit und Vergeltung, um den Eid zu erfüllen, den ich dir in Bezug auf die Kinder Noach geschworen habe;"},{"verse":61,"text":"und der Tag wird kommen, da die Erde ruhen wird, aber vor jenem Tag werden sich die Himmel verfinstern, und ein Schleier der Finsternis wird die Erde bedecken; und die Himmel werden erzittern und ebenso die Erde; und große Drangsale werden über die Menschenkinder kommen, aber mein Volk werde ich bewahren;"},{"verse":62,"text":"und Rechtschaffenheit werde ich aus dem Himmel herabsenden, und Wahrheit werde ich aus der Erde hervorgehen lassen, um Zeugnis zu geben für meinen Einziggezeugten, seine Auferstehung von den Toten, ja, und auch die Auferstehung aller Menschen; und Rechtschaffenheit und Wahrheit werde ich über die Erde fegen lassen wie eine Flut, um meine Auserwählten von den vier Enden der Erde an eine Stätte zu sammeln, die ich bereiten werde, eine Heilige Stadt, damit mein Volk sich die Lenden gürte und ausschaue nach der Zeit meines Kommens; denn dort wird meine Wohnstätte sein, und sie wird Zion heißen, ein Neues Jerusalem."},{"verse":63,"text":"Und der Herr sprach zu Henoch: Dann wirst du mit deiner ganzen Stadt ihnen dort begegnen, und wir werden sie in unseren Schoß aufnehmen, und sie werden uns sehen; und wir werden ihnen um den Hals fallen, und sie werden uns um den Hals fallen, und wir werden einander küssen;"},{"verse":64,"text":"und dort wird meine Wohnstätte sein, und es wird Zion sein, das aus allen Schöpfungen hervorgehen wird, die ich gemacht habe; und über den Zeitraum von tausend Jahren hinweg wird die Erde ruhen."},{"verse":65,"text":"Und es begab sich: Henoch sah den Tag, da des Menschen Sohn in den letzten Tagen kommen würde, um über den Zeitraum von tausend Jahren hinweg in Rechtschaffenheit auf der Erde zu wohnen;"},{"verse":66,"text":"aber vor jenem Tag sah er große Drangsale unter den Schlechten; und er sah auch das Meer, dass es unruhig war und dass den Menschen das Herz aussetzte, denn voll Furcht blickten sie den Richtersprüchen des allmächtigen Gottes entgegen, die über die Schlechten kommen würden."},{"verse":67,"text":"Und der Herr zeigte Henoch alles, selbst bis zum Ende der Welt; und er schaute den Tag der Rechtschaffenen, die Stunde ihrer Erlösung, und empfing eine Fülle der Freude;"},{"verse":68,"text":"und alle die Tage Zions in den Tagen Henochs waren dreihundertfünfundsechzig Jahre."},{"verse":69,"text":"Und Henoch und all sein Volk wandelten mit Gott, und er wohnte mitten in Zion; und es begab sich: Zion war nicht mehr, denn Gott nahm es in seinen eigenen Schoß auf; und von daher kam die Rede auf: Zion ist geflohen."}]},{"chapter":8,"verses":[{"verse":1,"text":"Und alle Tage Henochs waren vierhundertdreißig Jahre."},{"verse":2,"text":"Und es begab sich: Metuschelach, der Sohn Henochs, wurde nicht hinweggenommen, damit sich die Bündnisse des Herrn erfüllen konnten, die er für Henoch gemacht hatte; denn er hatte wahrhaftig mit Henoch den Bund gemacht, dass Noach von der Frucht seiner Lenden sein werde."},{"verse":3,"text":"Und es begab sich: Metuschelach prophezeite, dass aus seinen Lenden alle Reiche der Erde hervorgehen würden (durch Noach), und er verherrlichte sich selbst."},{"verse":4,"text":"Und es kam eine große Hungersnot in das Land, und der Herr verfluchte die Erde mit einem schweren Fluch, und viele ihrer Bewohner starben."},{"verse":5,"text":"Und es begab sich: Metuschelach lebte einhundertsiebenundachtzig Jahre und zeugte Lamech;"},{"verse":6,"text":"und Metuschelach lebte, nachdem er Lamech gezeugt hatte, siebenhundertzweiundachtzig Jahre und zeugte Söhne und Töchter;"},{"verse":7,"text":"und alle Tage Metuschelachs waren neunhundertneunundsechzig Jahre, und er starb."},{"verse":8,"text":"Und Lamech lebte einhundertzweiundachtzig Jahre und zeugte einen Sohn,"},{"verse":9,"text":"und er gab ihm den Namen Noach und sprach: Dieser Sohn wird uns trösten in unserer Arbeit und in der Mühe unserer Hände an dem Erdboden, den der Herr verflucht hat."},{"verse":10,"text":"Und Lamech lebte, nachdem er Noach gezeugt hatte, fünfhundertfünfundneunzig Jahre und zeugte Söhne und Töchter;"},{"verse":11,"text":"und alle Tage Lamechs waren siebenhundertsiebenundsiebzig Jahre, und er starb."},{"verse":12,"text":"Und Noach war vierhundertfünfzig Jahre alt und zeugte Jafet; und zweiundvierzig Jahre danach zeugte er Sem mit ihr, die die Mutter Jafets war, und als er fünfhundert Jahre alt war, zeugte er Ham."},{"verse":13,"text":"Und Noach und seine Söhne hörten auf den Herrn und schenkten ihm Beachtung; und sie wurden die Söhne Gottes genannt."},{"verse":14,"text":"Und als diese Menschen sich allmählich auf dem Erdboden mehrten und ihnen Töchter geboren wurden, da sahen die Söhne der Menschen, dass diese Töchter anmutig waren, und sie nahmen sie sich zu Frauen, so wie sie wollten."},{"verse":15,"text":"Und der Herr sprach zu Noach: Die Töchter deiner Söhne haben sich verkauft; denn siehe, mein Zorn ist gegen die Söhne der Menschen entflammt, denn sie wollen nicht auf meine Stimme hören."},{"verse":16,"text":"Und es begab sich: Noach prophezeite und lehrte das, was von Gott ist, so wie es am Anfang war."},{"verse":17,"text":"Und der Herr sprach zu Noach: Mein Geist wird sich nicht immer mit dem Menschen abmühen, denn er soll wissen, dass alles Fleisch sterben wird; doch sollen seine Tage einhundertzwanzig Jahre sein; und wenn die Menschen nicht umkehren, werde ich die Fluten über sie senden."},{"verse":18,"text":"Und in jenen Tagen gab es Riesen auf der Erde, und sie stellten Noach nach, um ihm das Leben zu nehmen; aber der Herr war mit Noach, und die Macht des Herrn war auf ihm."},{"verse":19,"text":"Und der Herr ordinierte Noach nach seiner eigenen Ordnung und gebot ihm, er solle hingehen und den Menschenkindern sein Evangelium verkünden, ja, wie es Henoch gegeben worden war."},{"verse":20,"text":"Und es begab sich: Noach rief die Menschenkinder auf, dass sie umkehren sollten; aber sie hörten nicht auf seine Worte;"},{"verse":21,"text":"und auch traten sie, nachdem sie ihm zugehört hatten, vor ihn und sprachen: Siehe, wir sind die Söhne Gottes; haben wir uns nicht die Töchter der Menschen genommen? Und ist es nicht so, dass wir essen und trinken und heiraten und verheiratet werden? Und unsere Frauen gebären uns Kinder, und diese sind mächtige Männer, den Männern gleich, die in alter Zeit waren, Männer großen Ruhms. Und sie hörten nicht auf die Worte Noachs."},{"verse":22,"text":"Und Gott sah, dass die Schlechtigkeit der Menschen groß geworden war auf Erden; und jeder Mensch war im Trachten der Gedanken seines Herzens überheblich, denn diese waren beständig nur böse."},{"verse":23,"text":"Und es begab sich: Noach fuhr fort, dem Volk zu predigen, nämlich: Hört her, und schenkt meinen Worten Beachtung;"},{"verse":24,"text":"seid gläubig, und kehrt um von euren Sünden, und lasst euch taufen im Namen Jesu Christi, des Sohnes Gottes, ja, wie unsere Väter, dann werdet ihr den Heiligen Geist empfangen, damit euch alles kundgetan werden kann; und wenn ihr dies nicht tut, werden die Fluten über euch kommen; doch sie hörten nicht darauf."},{"verse":25,"text":"Und es reute Noach, und das Herz tat ihm weh, dass der Herr den Menschen auf Erden gemacht hatte, und es schmerzte ihn im Herzen."},{"verse":26,"text":"Und der Herr sprach: Ich werde den Menschen, den ich erschaffen habe, vom Erdboden vertilgen, sowohl den Menschen als auch das Tier und das kriechende Getier und die Vögel der Luft; denn es reut Noach, dass ich sie erschaffen habe und dass ich sie gemacht habe; und er hat mich angerufen, denn sie haben ihm nach dem Leben getrachtet."},{"verse":27,"text":"Und so fand Noach Gnade in den Augen des Herrn, denn Noach war ein gerechter Mann und in seiner Generation vollkommen; und er wandelte mit Gott, wie es auch seine drei Söhne taten, Sem, Ham und Jafet."},{"verse":28,"text":"Die Erde war verdorben vor Gott, und sie war von Gewalttätigkeit erfüllt."},{"verse":29,"text":"Und Gott schaute auf die Erde, und siehe, sie war verdorben, denn alles Fleisch hatte seinen Weg auf Erden verdorben."},{"verse":30,"text":"Und Gott sprach zu Noach: Das Ende allen Fleisches ist vor mich gekommen, denn die Erde ist von Gewalttätigkeit erfüllt, und siehe, ich werde alles Fleisch von der Erde hinweg vertilgen."}]}]},{"id":"abraham","title":"Abraham","englishTitle":"Abraham","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Im Land der Chaldäer, am Wohnsitz meiner Väter, sah ich, Abraham, dass es für mich nötig war, einen anderen Ort als Wohnsitz zu erlangen;"},{"verse":2,"text":"und da ich gewahr wurde, dass mir mehr Glück und Frieden und Ruhe beschieden sein würden, trachtete ich nach den Segnungen der Väter und dem Recht, wozu ich ordiniert sein musste, um sie anderen zu spenden; da ich selbst ein Nachfolger der Rechtschaffenheit war und auch wünschte, jemand zu sein, der viel Erkenntnis besaß, und ein besserer Nachfolger der Rechtschaffenheit zu sein und mehr Erkenntnis zu besitzen und ein Vater vieler Nationen zu sein, ein Fürst des Friedens, und wünschte, Belehrungen zu empfangen und die Gebote Gottes zu halten, wurde ich ein rechtmäßiger Erbe, ein Hoher Priester, der das Recht innehatte, das den Vätern zugehörte."},{"verse":3,"text":"Es wurde mir von den Vätern übertragen; es kam von den Vätern herab, vom Anfang der Zeit her, ja, selbst vom Anfang, oder vor der Grundlegung der Erde, bis in die gegenwärtige Zeit herab, nämlich das Recht des Erstgeborenen oder des ersten Menschen, welcher Adam ist oder der erste Vater, durch die Väter bis zu mir."},{"verse":4,"text":"Ich trachtete nach meiner Berufung zum Priestertum gemäß der Berufung von Gott an die Väter in Bezug auf die Nachkommen."},{"verse":5,"text":"Meine Väter, die sich abgewandt hatten von ihrer Rechtschaffenheit und von den heiligen Geboten, die der Herr, ihr Gott, ihnen gegeben hatte, hin zur Anbetung der Götter der Heiden, weigerten sich entschieden, auf meine Stimme zu hören;"},{"verse":6,"text":"denn ihr Herz war darauf gerichtet, Böses zu tun, und hatte sich gänzlich dem Gott von Elkena und dem Gott von Libna und dem Gott von Mamakra und dem Gott von Korasch und dem Gott des Pharaos, des Königs von Ägypten, zugewandt;"},{"verse":7,"text":"darum wandten sie ihr Herz dem heidnischen Opferbrauch zu, indem sie ihre Kinder diesen stummen Götzen opferten und nicht auf meine Stimme hörten, sondern darangingen, mir durch die Hand des Priesters von Elkena das Leben nehmen zu lassen. Der Priester von Elkena war auch der Priester des Pharaos."},{"verse":8,"text":"Nun war es zu dieser Zeit der Brauch des Priesters des Pharaos, des Königs von Ägypten, auf dem Altar, der im Land Chaldäa errichtet war, diesen fremden Göttern als Opfer Männer, Frauen und Kinder darzubringen."},{"verse":9,"text":"Und es begab sich: Der Priester brachte dem Gott des Pharaos und auch dem Gott von Schagriel ein Opfer dar, nämlich nach der Weise der Ägypter. Nun war der Gott von Schagriel die Sonne."},{"verse":10,"text":"Sogar ein Kind brachte der Priester des Pharaos als Dankopfer auf dem Altar dar, der bei dem Hügel stand, der Potifars Hügel genannt wurde, am oberen Ende der Ebene von Olischem."},{"verse":11,"text":"Nun hatte dieser Priester auf diesem Altar drei Jungfrauen auf einmal geopfert, und das waren die Töchter des Onita, eines königlichen Abkömmlings direkt aus den Lenden Hams. Diese Jungfrauen wurden wegen ihrer Tugend geopfert; sie wollten sich nicht beugen, um Götter aus Holz oder aus Stein anzubeten, darum wurden sie auf diesem Altar umgebracht, und es geschah nach der Weise der Ägypter."},{"verse":12,"text":"Und es begab sich: Die Priester taten mir Gewalt an, um auch mich zu töten, wie sie es mit jenen Jungfrauen auf diesem Altar getan hatten; und damit ihr Kenntnis habt von diesem Altar, will ich euch auf die Darstellung zu Beginn dieses Berichts verweisen."},{"verse":13,"text":"Er war in Gestalt einer Bettstatt gemacht, wie sie bei den Chaldäern benutzt wurde, und er stand vor den Göttern von Elkena, Libna, Mamakra, Korasch und auch einem Gott gleich dem des Pharaos, des Königs von Ägypten."},{"verse":14,"text":"Damit ihr eine Vorstellung von diesen Göttern habt, habe ich euch in den Abbildungen am Anfang ihr Aussehen angegeben, und diese Art von Abbildungen wird von den Chaldäern „Ralinos“ genannt, was Hieroglyphen bedeutet."},{"verse":15,"text":"Und als sie die Hände gegen mich erhoben, um mich zu opfern und mir das Leben zu nehmen, siehe, da erhob ich meine Stimme zum Herrn, zu meinem Gott, und der Herr hörte und vernahm, und er erfüllte mich mit der Vision des Allmächtigen, und der Engel seiner Gegenwart stand mir bei und löste sogleich meine Bande;"},{"verse":16,"text":"und seine Stimme erging an mich: Abraham, Abraham, siehe, mein Name ist Jehova, und ich habe dich erhört und bin herniedergekommen, um dich zu befreien und um dich aus deines Vaters Haus und von deiner ganzen Verwandtschaft wegzuführen in ein fremdes Land, von dem du nicht weißt;"},{"verse":17,"text":"und dies, weil sie ihr Herz von mir abgewandt haben, um den Gott von Elkena und den Gott von Libna und den Gott von Mamakra und den Gott von Korasch und den Gott des Pharaos, des Königs von Ägypten, anzubeten; darum bin ich herniedergekommen, um sie heimzusuchen und denjenigen zu vernichten, der seine Hand gegen dich, mein Sohn Abraham, erhoben hat, um dir das Leben zu nehmen."},{"verse":18,"text":"Siehe, ich werde dich mit meiner Hand führen, und ich werde dich nehmen und dir meinen Namen auferlegen, ja, das Priestertum deines Vaters, und meine Macht wird über dir sein."},{"verse":19,"text":"Wie es mit Noach war, so wird es mit dir sein; aber durch deinen geistlichen Dienst wird mein Name auf Erden bekannt sein immerdar, denn ich bin dein Gott."},{"verse":20,"text":"Siehe, Potifars Hügel war im Land Ur in Chaldäa. Und der Herr zerbrach den Altar von Elkena und von den Göttern des Landes und zerstörte sie gänzlich und schlug den Priester, sodass er starb; und es war große Trauer in Chaldäa und auch am Hof des Pharaos; und Pharao bedeutet König aus königlichem Geblüt."},{"verse":21,"text":"Nun war dieser König von Ägypten ein Abkömmling aus den Lenden Hams und hatte durch seine Geburt Anteil am Blut der Kanaaniter."},{"verse":22,"text":"Von dieser Abkunft stammen alle Ägypter, und so wurde das Blut der Kanaaniter im Land bewahrt."},{"verse":23,"text":"Das Land Ägypten wurde erstmals von einer Frau entdeckt; sie war die Tochter Hams und die Tochter der Ägyptus, was auf Chaldäisch Ägypten bedeutet, was bedeutet: das, was verboten ist;"},{"verse":24,"text":"als diese Frau das Land entdeckte, war es unter Wasser; und nachher siedelte sie ihre Söhne darin an; und so stammt die Rasse, die den Fluch in dem Land bewahrte, von Ham."},{"verse":25,"text":"Nun wurde die erste Regierung in Ägypten von Pharao, dem ältesten Sohn der Ägyptus, der Tochter Hams, gebildet, und zwar nach der Art der Regierung Hams, die patriarchalisch war."},{"verse":26,"text":"Pharao, der ein rechtschaffener Mann war, begründete sein Königreich und richtete sein Volk weise und gerecht alle seine Tage und trachtete ernsthaft danach, jene Ordnung nachzuahmen, die von den Vätern in den ersten Generationen aufgestellt worden war, in den Tagen der ersten patriarchalischen Regierung, ja, in der Regierung Adams und auch Noachs, seines Vaters, der ihn mit den Segnungen der Erde gesegnet hatte und mit den Segnungen der Weisheit, ihn aber, was das Priestertum betrifft, verflucht hatte."},{"verse":27,"text":"Nun war Pharao von jener Abstammung, durch die er das Recht des Priestertums nicht haben konnte, obwohl die Pharaonen von Noach her, durch Ham, gern darauf Anspruch erhoben, darum wurde mein Vater durch ihren Götzendienst verleitet;"},{"verse":28,"text":"aber ich werde später noch darangehen, die Zeittafel von mir selbst bis an den Anfang der Schöpfung zurückreichend darzustellen, denn die Aufzeichnungen sind in meine Hände gelangt, und ich besitze sie bis zur gegenwärtigen Zeit."},{"verse":29,"text":"Nun ging, nachdem der Priester von Elkena geschlagen wurde, sodass er starb, all das, was mir in Bezug auf das Land Chaldäa gesagt worden war, in Erfüllung, dass es eine Hungersnot in dem Land geben werde."},{"verse":30,"text":"Demgemäß herrschte im ganzen Land Chaldäa eine Hungersnot, und mein Vater war durch die Hungersnot schwer geplagt, und er kehrte von dem Bösen um, das er gegen mich beschlossen hatte, nämlich mir das Leben zu nehmen."},{"verse":31,"text":"Aber die Aufzeichnungen der Väter, ja, der Patriarchen, über das Recht auf das Priestertum, hatte der Herr, mein Gott, in meinen eigenen Händen bewahrt; diese Kenntnis vom Anfang der Schöpfung und auch von den Planeten und von den Sternen, wie sie den Vätern kundgetan wurde, habe ich darum bis zu diesem Tag bewahrt, und ich werde darangehen, einiges davon zum Nutzen meiner Nachkommenschaft, die nach mir kommen wird, in diesem Bericht niederzuschreiben."}]},{"chapter":2,"verses":[{"verse":1,"text":"Nun ließ Gott, der Herr, die Hungersnot im Land Ur so schwer werden, dass Haran, mein Bruder, starb; aber Terach, mein Vater, lebte noch im Land Ur der Chaldäer."},{"verse":2,"text":"Und es begab sich: Ich, Abraham, nahm Sarai zur Frau, und Nahor, mein Bruder, nahm Milka zur Frau, die die Tochter Harans war."},{"verse":3,"text":"Nun hatte der Herr zu mir gesprochen: Abraham, geh fort aus deinem Land und von deiner Verwandtschaft und aus deines Vaters Haus in ein Land, das ich dir zeigen werde."},{"verse":4,"text":"Darum verließ ich das Land Ur der Chaldäer, um ins Land Kanaan zu reisen, und ich nahm Lot, meines Bruders Sohn, und seine Frau und Sarai, meine Frau, mit; und auch mein Vater folgte mir nach in das Land, das wir als Haran bezeichneten."},{"verse":5,"text":"Und die Hungersnot ließ nach; und mein Vater blieb in Haran und wohnte dort, da es in Haran viele Herden gab; und mein Vater wandte sich wieder seinem Götzendienst zu, darum verblieb er in Haran."},{"verse":6,"text":"Aber ich, Abraham, und Lot, meines Bruders Sohn, beteten zum Herrn, und der Herr erschien mir und sprach zu mir: Steh auf und nimm Lot mit dir; denn ich habe vor, dich aus dem Land Haran fortzunehmen und aus dir einen geistlichen Diener zu machen, der meinen Namen in einem fremden Land trägt, das ich deinen Nachkommen nach dir als immerwährenden Besitz geben werde, wenn sie auf meine Stimme hören."},{"verse":7,"text":"Denn ich bin der Herr, dein Gott; ich wohne im Himmel; die Erde ist mein Fußschemel; ich strecke meine Hand aus über das Meer, und es gehorcht meiner Stimme; ich mache den Wind und das Feuer zu meinem Wagen; ich spreche zu den Bergen: Weicht von hier!, und siehe, sie werden von einem Wirbelsturm hinweggenommen, plötzlich, in einem Augenblick."},{"verse":8,"text":"Mein Name ist Jehova, und ich weiß das Ende von Anfang an; darum wird meine Hand über dir sein."},{"verse":9,"text":"Und ich werde aus dir eine große Nation machen, und ich werde dich über die Maßen segnen und deinen Namen unter allen Nationen groß machen; und du wirst deinen Nachkommen nach dir ein Segen sein, dass sie in ihren Händen diesen geistlichen Dienst und dieses Priestertum zu allen Nationen tragen;"},{"verse":10,"text":"und ich werde sie durch deinen Namen segnen; denn alle, die dieses Evangelium empfangen, werden nach deinem Namen genannt werden und werden deinen Nachkommen zugezählt werden und werden aufstehen und dich als ihren Vater preisen;"},{"verse":11,"text":"und ich werde die segnen, die dich segnen, und die verfluchen, die dich verfluchen; und in dir (das heißt in deinem Priestertum) und in deinen Nachkommen (das heißt deinem Priestertum) – denn ich gebe dir die Verheißung, dass dieses Recht in dir und in deinen Nachkommen nach dir verbleiben wird (das heißt den buchstäblichen Nachkommen oder den leiblichen Nachkommen) – werden alle Familien der Erde gesegnet sein, ja, mit den Segnungen des Evangeliums, und das sind die Segnungen der Errettung, ja, des ewigen Lebens."},{"verse":12,"text":"Nachdem nun der Herr sich davon zurückgezogen hatte, zu mir zu sprechen, und mir sein Angesicht entzogen hatte, sprach ich in meinem Herzen: Dein Diener hat dich ernstlich gesucht; nun habe ich dich gefunden;"},{"verse":13,"text":"du hast deinen Engel gesandt, um mich von den Göttern von Elkena zu befreien, und ich werde wohl daran tun, auf deine Stimme zu hören, darum lass deinen Diener sich erheben und in Frieden ziehen."},{"verse":14,"text":"So zog ich, Abraham, weg, wie der Herr es mir gesagt hatte, und Lot mit mir; und ich, Abraham, war zweiundsechzig Jahre alt, als ich aus Haran wegzog."},{"verse":15,"text":"Und ich nahm Sarai, die ich zur Frau genommen hatte, als ich in Ur in Chaldäa war, und Lot, meines Bruders Sohn, und all unsere Habe mit, die wir gesammelt hatten, und die Seelen, die wir in Haran gewonnen hatten, und wir machten uns auf den Weg in das Land Kanaan und wohnten, als wir auf dem Weg waren, in Zelten;"},{"verse":16,"text":"darum war die Ewigkeit unsere Zudecke und unser Fels und unsere Errettung, als wir von Haran auf dem Weg über Jerschon reisten, um in das Land Kanaan zu kommen."},{"verse":17,"text":"Nun baute ich, Abraham, im Land Jerschon einen Altar und brachte dem Herrn ein Opfer dar und betete, die Hungersnot möge von meines Vaters Haus abgewendet werden, damit sie nicht zugrunde gingen."},{"verse":18,"text":"Und dann zogen wir von Jerschon durch das Land nach dem Ort Sichem; er lag in der Ebene von More, und wir waren schon in das Grenzgebiet des Landes der Kanaaniter gekommen, und ich brachte dort in der Ebene von More Opfer dar und rief den Herrn inbrünstig an, denn wir waren schon in das Land dieser götzendienerischen Nation gekommen."},{"verse":19,"text":"Und der Herr erschien mir als Antwort auf meine Gebete und sprach zu mir: Deinen Nachkommen werde ich dieses Land geben."},{"verse":20,"text":"Und ich, Abraham, erhob mich vom Ort des Altars, den ich dem Herrn gebaut hatte, und zog von dort an einen Berg östlich von Bet-El und schlug dort mein Zelt auf, Bet-El im Westen und Ai im Osten; und dort baute ich dem Herrn noch einen Altar und rief wiederum den Namen des Herrn an."},{"verse":21,"text":"Und ich, Abraham, reiste weiter, immer noch gegen Süden; und es gab eine fortdauernde Hungersnot im Land; und ich, Abraham, beschloss, nach Ägypten hinabzuziehen und dort zu verweilen, denn die Hungersnot wurde sehr drückend."},{"verse":22,"text":"Und es begab sich: Als ich nahe daran war, Ägypten zu betreten, sprach der Herr zu mir: Siehe, Sarai, deine Frau, ist als Frau sehr schön anzusehen;"},{"verse":23,"text":"darum wird es sich begeben: Wenn die Ägypter sie sehen, werden sie sagen, sie ist seine Frau; und sie werden dich töten, sie aber werden sie leben lassen; darum sieh zu, dass ihr es auf diese Weise macht:"},{"verse":24,"text":"Lass sie zu den Ägyptern sagen, sie sei deine Schwester; dann wird deine Seele leben."},{"verse":25,"text":"Und es begab sich: Ich, Abraham, erzählte Sarai, meiner Frau, alles, was der Herr zu mir gesprochen hatte: Darum bitte ich dich, sage zu ihnen, du seist meine Schwester, auf dass es mir um deinetwillen wohl ergehe und meine Seele deinetwegen lebe."}]},{"chapter":3,"verses":[{"verse":1,"text":"Und ich, Abraham, hatte den Urim und Tummim, den der Herr, mein Gott, mir im Ur der Chaldäer gegeben hatte;"},{"verse":2,"text":"und ich sah die Sterne, dass sie sehr groß waren und dass einer von ihnen dem Thron Gottes am nächsten war; und es gab viele große, die nahe bei ihm waren."},{"verse":3,"text":"Und der Herr sprach zu mir: Diese sind es, die regieren; und der Name des großen ist Kolob, weil er mir nahe ist, denn ich bin der Herr, dein Gott: Ich habe diesen so gesetzt, dass er alle jene regiere, die derselben Ordnung angehören wie der, auf dem du stehst."},{"verse":4,"text":"Und der Herr sagte mir durch den Urim und Tummim, dass der Kolob der Weise des Herrn entspreche gemäß seinen Zeiten und Jahreszeiten in seinen Umdrehungen; eine Umdrehung sei für den Herrn nach seiner Zeitrechnung ein Tag, und das seien eintausend Jahre gemäß der Zeit, die dem bestimmt ist, auf dem du stehst. Das ist die Zeitrechnung des Herrn, nämlich gemäß der Zeitrechnung des Kolob."},{"verse":5,"text":"Und der Herr sprach zu mir: Der Planet, der das kleinere Licht ist, kleiner als das, was den Tag beherrschen soll, nämlich die Nacht, steht hinsichtlich der Zeitrechnung über dem oder ist größer als der, auf dem du stehst, denn er bewegt sich in einer langsameren Ordnung; das entspricht der Ordnung, weil er über der Erde steht, auf der du stehst, und darum hat seine Zeitrechnung an Anzahl nicht so viele Tage und Monate und Jahre."},{"verse":6,"text":"Und der Herr sprach zu mir: Nun, Abraham, diese zwei Tatsachen bestehen, siehe, deine Augen sehen das; es ist dir gegeben, die Zeitrechnungen und die festgesetzte Zeit zu kennen, ja, die festgesetzte Zeit der Erde, auf der du stehst, und die festgesetzte Zeit des größeren Lichts, das gesetzt ist, den Tag zu beherrschen, und die festgesetzte Zeit des kleineren Lichts, das gesetzt ist, die Nacht zu beherrschen."},{"verse":7,"text":"Nun ist die festgesetzte Zeit des kleineren Lichts gemäß seiner Zeitrechnung länger als die Zeitrechnung der Erde, auf der du stehst."},{"verse":8,"text":"Und wo diese zwei Tatsachen bestehen, da gibt es noch eine weitere Tatsache darüber hinaus, das heißt, da gibt es noch einen weiteren Planeten, dessen Zeitrechnung noch länger ist;"},{"verse":9,"text":"und so gibt es die Zeitrechnung des einen Planeten über die des anderen hinaus, bis du nahe zum Kolob kommst, und dieser Kolob folgt der Zeitrechnung des Herrn; und dieser Kolob ist nahe an den Thron Gottes gesetzt, dass er alle die Planeten regiere, die derselben Ordnung angehören wie der, auf dem du stehst."},{"verse":10,"text":"Und es ist dir gegeben, die festgesetzte Zeit aller Sterne zu kennen, die gesetzt sind, Licht zu geben, bis du nahe an den Thron Gottes kommst."},{"verse":11,"text":"So redete ich, Abraham, mit dem Herrn von Angesicht zu Angesicht, wie ein Mensch mit dem anderen redet; und er erzählte mir von den Werken, die seine Hände gemacht hatten;"},{"verse":12,"text":"und er sprach zu mir: Mein Sohn, mein Sohn (und seine Hand war ausgestreckt), siehe, ich werde dir alle diese zeigen. Und er legte seine Hand auf meine Augen, und ich schaute das, was seine Hände gemacht hatten, und dessen war viel; und es vervielfachte sich vor meinen Augen, und ich konnte das Ende davon nicht sehen."},{"verse":13,"text":"Und er sprach zu mir: Dies ist Schineha, das ist die Sonne. Und er sprach zu mir: Kokab, das ist Stern. Und er sprach zu mir: Olea, das ist der Mond. Und er sprach zu mir: Kokabim, was Sterne bedeutet oder alle großen Lichter, die am Gewölbe des Himmels sind."},{"verse":14,"text":"Und es war des Nachts, als der Herr diese Worte zu mir sprach: Ich will dich mehren und deine Nachkommen nach dir, gleichwie diese; und wenn du die Zahl der Sandkörner zählen kannst, so wird die Zahl deiner Nachkommen sein."},{"verse":15,"text":"Und der Herr sprach zu mir: Abraham, ich zeige dir dies, ehe ihr nach Ägypten geht, damit ihr alle diese Worte verkünden möget."},{"verse":16,"text":"Wenn es zwei Dinge gibt, und das eine steht über dem anderen, so gibt es Größeres über ihnen; darum ist Kolob der größte aller Kokabim, die du gesehen hast, denn er ist mir am nächsten."},{"verse":17,"text":"Nun, wenn es zwei Dinge gibt, das eine über dem anderen, und der Mond über der Erde ist, so mag es sein, dass es auch über ihm einen Planeten oder einen Stern gibt; und es gibt nichts, was der Herr, dein Gott, sich im Herzen zu tun vornimmt, was er dann nicht auch tut."},{"verse":18,"text":"Nichtsdestoweniger hat er den größeren Stern gemacht; gleichermaßen auch, wenn es zwei Geister gibt, und der eine ist intelligenter als der andere, so haben diese zwei Geister doch, obwohl der eine intelligenter ist als der andere, keinen Anfang; sie haben zuvor existiert, sie werden kein Ende haben, sie werden hernach existieren, denn sie sind n-olam oder ewig."},{"verse":19,"text":"Und der Herr sprach zu mir: Diese zwei Tatsachen bestehen, dass es zwei Geister gibt, und der eine ist intelligenter als der andere; es gibt noch einen weiteren, der intelligenter ist als sie; ich bin der Herr, dein Gott, ich bin intelligenter als sie alle."},{"verse":20,"text":"Der Herr, dein Gott, hat seinen Engel gesandt, dich aus den Händen des Priesters von Elkena zu befreien."},{"verse":21,"text":"Ich wohne inmitten von ihnen allen; darum bin ich nun zu dir herniedergekommen, um dir die Werke zu verkünden, die meine Hände gemacht haben, worin meine Weisheit sie alle übertrifft, denn ich herrsche oben in den Himmeln und unten auf der Erde mit aller Weisheit und Umsicht über alle Intelligenzen, die deine Augen gesehen haben, von Anfang an; ich bin am Anfang mitten unter alle die Intelligenzen herniedergekommen, die du gesehen hast."},{"verse":22,"text":"Nun hatte der Herr mir, Abraham, die Intelligenzen gezeigt, die geformt wurden, ehe die Welt war; und unter allen diesen waren viele von den Edlen und Großen;"},{"verse":23,"text":"und Gott sah diese Seelen, dass sie gut waren, und er stand mitten unter ihnen, und er sprach: Diese werde ich zu meinen Herrschern machen; denn er stand unter denen, die Geister waren, und er sah, dass sie gut waren; und er sprach zu mir: Abraham, du bist einer von ihnen; du wurdest erwählt, ehe du geboren wurdest."},{"verse":24,"text":"Und da stand einer unter ihnen, der war wie Gott, und er sprach zu denen, die bei ihm waren: Wir wollen hinabgehen, denn dort gibt es Raum, und wir wollen von diesen Stoffen nehmen, und wir wollen eine Erde machen, worauf diese wohnen können;"},{"verse":25,"text":"und wir wollen sie hierdurch prüfen und sehen, ob sie alles tun werden, was auch immer der Herr, ihr Gott, ihnen gebietet;"},{"verse":26,"text":"und diejenigen, die sich ihren ersten Stand bewahren, werden hinzugefügt bekommen; und diejenigen, die sich ihren ersten Stand nicht bewahren, werden keine Herrlichkeit im selben Reich mit denen haben, die sich ihren ersten Stand bewahren; und diejenigen, die sich ihren zweiten Stand bewahren, werden Herrlichkeit auf ihr Haupt hinzugefügt bekommen für immer und immer."},{"verse":27,"text":"Und der Herr sprach: Wen soll ich senden? Und einer wie des Menschen Sohn antwortete: Hier bin ich, sende mich! Und ein anderer antwortete und sprach: Hier bin ich, sende mich! Und der Herr sprach: Ich werde den ersten senden."},{"verse":28,"text":"Und der zweite wurde zornig und bewahrte sich seinen ersten Stand nicht, und an jenem Tag folgten ihm viele nach."}]},{"chapter":4,"verses":[{"verse":1,"text":"Und dann sprach der Herr: Lasst uns hinabgehen. Und sie gingen am Anfang hinab, und sie, das heißt die Götter, formten und gestalteten die Himmel und die Erde."},{"verse":2,"text":"Und die Erde, nachdem sie gestaltet war, war leer und öde, denn sie hatten noch nichts gestaltet als nur die Erde; und Finsternis herrschte über der Tiefe, und der Geist der Götter brütete über den Wassern."},{"verse":3,"text":"Und sie (die Götter) sprachen: Lasst Licht sein; und es ward Licht."},{"verse":4,"text":"Und sie (die Götter) erfassten das Licht, denn es war hell; und sie schieden das Licht oder ließen es sich von der Finsternis scheiden."},{"verse":5,"text":"Und die Götter nannten das Licht Tag, und die Finsternis nannten sie Nacht. Und es begab sich: Vom Abend bis zum Morgen nannten sie Nacht, und vom Morgen bis zum Abend nannten sie Tag; und dies war der erste oder der Anfang dessen, was sie Tag und Nacht nannten."},{"verse":6,"text":"Und die Götter sprachen auch: Lasst da einen weiten Raum sein inmitten der Wasser, und er soll die Wasser von den Wassern scheiden."},{"verse":7,"text":"Und die Götter befahlen dem weiten Raum, sodass er die Wasser, die unter dem weiten Raum waren, von den Wassern, die über dem weiten Raum waren, schied; und es war so, ja, wie sie es befahlen."},{"verse":8,"text":"Und die Götter nannten den weiten Raum Himmel. Und es begab sich: Vom Abend bis zum Morgen nannten sie Nacht; und es begab sich: Vom Morgen bis zum Abend nannten sie Tag; und dies war die zweite Zeit, die sie Nacht und Tag nannten."},{"verse":9,"text":"Und die Götter befahlen, nämlich: Lasst die Wasser unter dem Himmel sich an einen Ort sammeln, und lasst die Erde trocken emporsteigen; und es war so, wie sie es befahlen;"},{"verse":10,"text":"und die Götter bezeichneten das trockene Land als Erde, und die Sammlung der Wasser bezeichneten sie als große Wasser; und die Götter sahen, dass ihnen gehorcht wurde."},{"verse":11,"text":"Und die Götter sprachen: Lasst uns die Erde bereitmachen, dass sie Gras hervorbringe, das Kraut, das Samen trägt, den Fruchtbaum, der Frucht trägt nach seiner Art, dessen Same in sich seinesgleichen trägt auf der Erde; und es war so, ja, wie sie es befahlen."},{"verse":12,"text":"Und die Götter formten die Erde so, dass sie Gras aus dessen eigenem Samen hervorbrachte, und das Kraut so, dass es Kraut aus seinem eigenen Samen hervorbrachte, nach seiner eigenen Art Samen tragend, und die Erde so, dass sie den Baum aus seinem eigenen Samen hervorbrachte, der Frucht trägt, dessen Same in sich nur seinesgleichen hervorbringen kann, nach seiner Art; und die Götter sahen, dass ihnen gehorcht wurde."},{"verse":13,"text":"Und es begab sich: Sie zählten die Tage; vom Abend bis zum Morgen nannten sie Nacht; und es begab sich: Vom Morgen bis zum Abend nannten sie Tag; und es war die dritte Zeit."},{"verse":14,"text":"Und die Götter formten die Lichter im weiten Raum des Himmels und ließen sie den Tag von der Nacht scheiden und formten sie so, dass sie für Zeichen dienten und für Jahreszeiten und für Tage und für Jahre,"},{"verse":15,"text":"und formten sie so, dass Lichter seien im weiten Raum des Himmels, um der Erde Licht zu geben; und es war so."},{"verse":16,"text":"Und die Götter formten die zwei großen Lichter, das größere Licht, dass es den Tag beherrsche, und das kleinere Licht, dass es die Nacht beherrsche; mit dem kleineren Licht setzten sie auch die Sterne;"},{"verse":17,"text":"und die Götter setzten sie in den weiten Raum des Himmels, um der Erde Licht zu geben und um über den Tag und über die Nacht zu herrschen und das Licht von der Finsternis scheiden zu lassen."},{"verse":18,"text":"Und die Götter hatten acht auf die Dinge, denen sie befohlen hatten, bis sie gehorchten."},{"verse":19,"text":"Und es begab sich: Vom Abend bis zum Morgen war es Nacht; und es begab sich: Vom Morgen bis zum Abend war es Tag; und es war die vierte Zeit."},{"verse":20,"text":"Und die Götter sprachen: Lasst uns die Wasser bereitmachen, dass sie die sich regenden Geschöpfe, die Leben haben, reichlich hervorbringen, und die Vögel, dass sie über der Erde im offenen weiten Raum des Himmels fliegen."},{"verse":21,"text":"Und die Götter machten die Wasser bereit, dass sie große Walfische und jedes lebendige Geschöpf, das sich regt, hervorbrächten, welche die Wasser reichlich hervorbringen sollten, nach ihrer Art; und jeden geflügelten Vogel nach seiner Art. Und die Götter sahen, dass ihnen gehorcht werden würde und dass ihr Plan gut war."},{"verse":22,"text":"Und die Götter sprachen: Wir werden sie segnen und sie fruchtbar sein und sich mehren und die Wasser in den Meeren oder großen Wassern füllen lassen und die Vögel sich mehren lassen auf Erden."},{"verse":23,"text":"Und es begab sich: Vom Abend bis zum Morgen nannten sie Nacht, und es begab sich: Vom Morgen bis zum Abend nannten sie Tag; und es war die fünfte Zeit."},{"verse":24,"text":"Und die Götter machten die Erde bereit, dass sie das lebendige Geschöpf hervorbrächte nach seiner Art, Vieh und kriechendes Getier und die Wildtiere der Erde nach ihrer Art; und es war so, wie sie gesprochen hatten."},{"verse":25,"text":"Und die Götter formten die Erde, dass sie die Wildtiere hervorbringe nach ihrer Art und Vieh nach seiner Art und alles, was auf der Erde kriecht, nach seiner Art; und die Götter sahen, dass sie gehorchen würden."},{"verse":26,"text":"Und die Götter hielten miteinander Rat und sprachen: Lasst uns hinabgehen und den Menschen gestalten als unser Abbild, uns selbst ähnlich; und wir werden ihnen Herrschaft geben über die Fische des Meeres und über die Vögel der Luft und über das Vieh und über die ganze Erde und über alles kriechende Getier, was auf der Erde kriecht."},{"verse":27,"text":"So gingen die Götter hinab, um den Menschen als ihr eigenes Abbild zu formen, als Abbild der Götter ihn zu gestalten, männlich und weiblich sie zu gestalten."},{"verse":28,"text":"Und die Götter sprachen: Wir werden sie segnen. Und die Götter sprachen: Wir werden bewirken, dass sie fruchtbar seien und sich mehren und die Erde füllen und sie sich untertan machen und herrschen über die Fische des Meeres und über die Vögel der Luft und über alles Lebendige, was sich auf der Erde regt."},{"verse":29,"text":"Und die Götter sprachen: Siehe, wir werden ihnen jegliches samentragende Kraut geben, das auf der ganzen Erde wachsen wird, und jeglichen Baum, an dem Frucht sein wird; ja, die Frucht des Baumes, die Samen trägt, werden wir ihnen geben; es wird ihnen zur Nahrung sein."},{"verse":30,"text":"Und jedem Wildtier der Erde und jedem Vogel der Luft und allem, was auf der Erde kriecht, siehe, wir werden ihnen Leben geben, und wir werden ihnen auch alles grüne Kraut zur Nahrung geben, und alles dieses wird so geformt werden."},{"verse":31,"text":"Und die Götter sprachen: Wir werden alles tun, was wir gesprochen haben, und sie formen; und siehe, sie werden sehr gehorsam sein. Und es begab sich: Vom Abend bis zum Morgen nannten sie Nacht; und es begab sich: Vom Morgen bis zum Abend nannten sie Tag; und sie zählten die sechste Zeit."}]},{"chapter":5,"verses":[{"verse":1,"text":"Und so werden wir vollenden die Himmel und die Erde und alle ihre Scharen."},{"verse":2,"text":"Und die Götter sprachen bei sich: Zur siebenten Zeit werden wir unser Werk beenden, das wir beratschlagt haben; und wir werden zur siebenten Zeit von all unserem Werk ruhen, was wir beratschlagt haben."},{"verse":3,"text":"Und die Götter vollendeten zur siebenten Zeit, denn zur siebenten Zeit wollten sie von all ihren Werken ruhen, die zu gestalten sie (die Götter) miteinander beratschlagt hatten, und heiligten die Zeit. Und so waren ihre Beschlüsse zu der Zeit, da sie miteinander beratschlagten, die Himmel und die Erde zu gestalten."},{"verse":4,"text":"Und die Götter kamen herab und gestalteten diese, die Generationen der Himmel und der Erde, als sie gestaltet wurden an dem Tag, da die Götter die Erde und die Himmel gestalteten"},{"verse":5,"text":"gemäß all dem, was sie gesprochen hatten in Bezug auf jede Pflanze des Feldes, bevor sie auf Erden war, und jedes Kraut des Feldes, bevor es wuchs; denn die Götter hatten noch nicht regnen lassen auf Erden, als sie beratschlagten, all dies zu machen, und hatten noch keinen Menschen gestaltet, der die Erde bebaute."},{"verse":6,"text":"Aber da stieg von der Erde ein Dunst auf und wässerte den ganzen Erdboden."},{"verse":7,"text":"Und die Götter gestalteten den Menschen aus dem Staub des Erdbodens und nahmen seinen Geist (nämlich den Geist des Menschen) und taten ihn in ihn und hauchten in seine Nasenlöcher den Lebenshauch, und der Mensch wurde eine lebende Seele."},{"verse":8,"text":"Und die Götter pflanzten einen Garten im Osten, in Eden, und darein setzten sie den Menschen, dessen Geist sie in den Leib getan hatten, den sie gestaltet hatten."},{"verse":9,"text":"Und aus dem Erdboden ließen die Götter einen jeden Baum aufwachsen, der angenehm anzusehen und gut zur Nahrung ist; auch den Baum des Lebens in der Mitte des Gartens und den Baum der Erkenntnis von Gut und Böse."},{"verse":10,"text":"Da war ein Fluss, der ausging von Eden, den Garten zu bewässern, und von dort an teilte er sich und wurde zu vier Hauptflüssen."},{"verse":11,"text":"Und die Götter nahmen den Menschen und setzten ihn in den Garten von Eden, ihn zu bebauen und ihn zu hüten."},{"verse":12,"text":"Und die Götter geboten dem Menschen, nämlich: Von jedem Baum des Gartens magst du nach Belieben essen,"},{"verse":13,"text":"aber vom Baum der Erkenntnis von Gut und Böse, davon sollst du nicht essen; denn zu der Zeit, da du davon isst, wirst du sicherlich sterben. Nun sah ich, Abraham, dass dies nach der Zeit des Herrn war, die nach der Zeit des Kolob ist; denn noch hatten die Götter Adam seine Zeitrechnung nicht bestimmt."},{"verse":14,"text":"Und die Götter sprachen: Lasst uns für den Menschen eine Hilfe machen, ihm ebenbürtig; denn es ist nicht gut, dass der Mensch allein sei, darum wollen wir für ihn eine Hilfe gestalten, ihm ebenbürtig."},{"verse":15,"text":"Und die Götter ließen einen tiefen Schlaf auf Adam fallen; und er schlief, und sie nahmen eine von seinen Rippen und verschlossen ihre Stelle stattdessen mit Fleisch;"},{"verse":16,"text":"und aus der Rippe, die die Götter von dem Menschen genommen hatten, gestalteten sie eine Frau und brachten sie zu dem Menschen."},{"verse":17,"text":"Und Adam sprach: Dies war Bein von meinem Gebein und Fleisch von meinem Fleisch; nun wird sie Frau heißen, denn vom Mann wurde sie genommen;"},{"verse":18,"text":"darum wird ein Mann seinen Vater und seine Mutter verlassen und wird an seiner Frau festhalten; und sie werden ein Fleisch sein."},{"verse":19,"text":"Und sie waren beide nackt, der Mensch und seine Frau, und schämten sich nicht."},{"verse":20,"text":"Und aus dem Erdboden gestalteten die Götter jedes Tier des Feldes und jeden Vogel der Luft und brachten sie zu Adam, um zu sehen, wie er sie benennen würde; und wie auch immer Adam jedes lebendige Geschöpf benannte, so solle dessen Name sein."},{"verse":21,"text":"Und Adam gab allem Vieh und den Vögeln der Luft und jedem Tier des Feldes Namen; und für Adam, da wurde eine Hilfe gefunden, ihm ebenbürtig."}]}]},{"id":"joseph-smith-matthew","title":"Joseph Smith – Matthäus","englishTitle":"Joseph Smith-Matthew","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Denn ich sage euch, dass ihr mich von jetzt an nicht sehen und nicht wissen werdet, dass ich es bin, über den von den Propheten geschrieben worden ist, bis ihr sprecht: Gesegnet ist er, der kommt im Namen des Herrn in den Wolken des Himmels, und alle heiligen Engel mit ihm! Da verstanden seine Jünger, dass er wieder auf die Erde kommen würde, nachdem er zur rechten Hand Gottes verherrlicht und gekrönt worden sei."},{"verse":2,"text":"Und Jesus ging hinaus und verließ den Tempel; und seine Jünger kamen zu ihm, um ihn zu hören, und sprachen: Meister, zeige uns, was es mit den Gebäuden des Tempels auf sich hat, denn du hast gesagt: Sie werden niedergerissen und euch verwüstet gelassen werden."},{"verse":3,"text":"Und Jesus sprach zu ihnen: Seht ihr nicht das alles, und versteht ihr es nicht? Wahrlich, ich sage euch: Es wird hier, an diesem Tempel, nicht ein Stein auf dem anderen bleiben, der nicht niedergerissen werden wird."},{"verse":4,"text":"Und Jesus verließ sie und ging auf den Ölberg. Und als er auf dem Ölberg saß, traten die Jünger für sich allein vor ihn und sprachen: Sage uns, wann wird das alles geschehen, was du in Bezug auf die Zerstörung des Tempels und der Juden gesagt hast; und was ist das Zeichen für dein Kommen und für das Ende der Welt oder die Vernichtung der Schlechten, was das Ende der Welt ist?"},{"verse":5,"text":"Und Jesus antwortete und sprach zu ihnen: Gebt acht, dass euch niemand täusche;"},{"verse":6,"text":"denn viele werden unter meinem Namen kommen und sagen: Ich bin Christus – und werden viele täuschen;"},{"verse":7,"text":"dann werden sie euch der Bedrängnis ausliefern und werden euch töten, und ihr werdet von allen Nationen um meines Namens willen gehasst werden,"},{"verse":8,"text":"und dann werden viele Anstoß nehmen und werden einander verraten und werden einander hassen;"},{"verse":9,"text":"und viele falsche Propheten werden sich erheben und werden viele täuschen;"},{"verse":10,"text":"und weil das Übeltun überhandnimmt, wird die Liebe bei vielen erkalten;"},{"verse":11,"text":"wer aber standhaft bleibt und sich nicht überwinden lässt, der wird errettet werden."},{"verse":12,"text":"Darum, wenn ihr den Gräuel der Verwüstung erblicken werdet, von dem der Prophet Daniel in Bezug auf die Zerstörung Jerusalems gesprochen hat, dann sollt ihr an heiliger Stätte stehen; wer da liest, der möge verstehen."},{"verse":13,"text":"Dann soll in die Berge fliehen, wer in Judäa ist;"},{"verse":14,"text":"und wer auf dem Dach ist, soll fliehen und nicht zurückkehren, um etwas aus seinem Haus zu holen;"},{"verse":15,"text":"auch wer auf dem Feld ist, soll nicht zurückkehren, um seinen Mantel zu holen;"},{"verse":16,"text":"weh aber denen, die schwanger sind, und denen, die in jenen Tagen stillen;"},{"verse":17,"text":"darum bittet den Herrn, eure Flucht möge nicht im Winter geschehen und auch nicht am Sabbattag;"},{"verse":18,"text":"denn dann, in jenen Tagen, wird große Drangsal sein über den Juden und auf den Einwohnern Jerusalems, wie sie zuvor noch nicht von Gott über Israel gesandt wurde, vom Anfang ihres Reiches bis zu dieser Zeit, nein, und auch nie wieder über Israel gesandt werden wird."},{"verse":19,"text":"Alles, was über sie gekommen ist, ist erst der Anfang der Kümmernisse, die über sie kommen werden."},{"verse":20,"text":"Und wenn jene Tage nicht verkürzt würden, dann würde nichts von ihrem Fleisch errettet werden; aber um der Auserwählten willen, gemäß dem Bund, werden jene Tage verkürzt werden."},{"verse":21,"text":"Siehe, dies alles habe ich euch in Bezug auf die Juden gesagt; und weiter, wenn jemand nach der Drangsal jener Tage, die über Jerusalem kommen wird, zu euch sagen wird: Siehe, hier ist Christus, oder da, so glaubt ihm nicht;"},{"verse":22,"text":"denn in jenen Tagen werden sich auch manch falscher Christus und falscher Prophet erheben und werden große Zeichen und Wunder zeigen, sodass sie, wenn möglich, sogar die Auserwählten täuschen, die die Auserwählten gemäß dem Bund sind."},{"verse":23,"text":"Siehe, ich sage euch dies alles um der Auserwählten willen; und ihr werdet auch von Kriegen und Kriegsgerüchten hören; seht zu, dass ihr euch nicht beunruhigt; denn alles, was ich euch gesagt habe, muss sich begeben; aber es ist noch nicht das Ende."},{"verse":24,"text":"Siehe, ich habe es euch vorausgesagt;"},{"verse":25,"text":"darum, wenn sie zu euch sagen werden: Siehe, er ist in der Wüste, so geht nicht hin; Siehe, er ist in den geheimen Gemächern, so glaubt es nicht;"},{"verse":26,"text":"denn wie das Licht des Morgens aus dem Osten kommt und bis zum Westen leuchtet und die ganze Erde bedeckt, so wird es auch sein, wenn des Menschen Sohn kommt."},{"verse":27,"text":"Und nun zeige ich euch ein Gleichnis. Siehe, wo auch immer das Aas ist, da werden sich die Adler sammeln; in gleicher Weise werden sich auch meine Auserwählten von den vier Enden der Erde sammeln."},{"verse":28,"text":"Und sie werden von Kriegen und Kriegsgerüchten hören."},{"verse":29,"text":"Siehe, ich spreche um meiner Auserwählten willen, denn es wird sich Nation gegen Nation erheben und Reich gegen Reich; es werden Hungersnöte und Seuchen und Erdbeben an verschiedenen Orten sein."},{"verse":30,"text":"Und abermals: Weil das Übeltun überhandnimmt, wird die Liebe der Menschen erkalten; aber wer sich nicht überwinden lässt, der wird errettet werden."},{"verse":31,"text":"Und abermals: Dieses Evangelium vom Reich wird in der ganzen Welt gepredigt werden zum Zeugnis für alle Nationen, und dann wird das Ende kommen oder die Vernichtung der Schlechten;"},{"verse":32,"text":"und abermals wird der Gräuel der Verwüstung, wovon der Prophet Daniel gesprochen hat, sich erfüllen."},{"verse":33,"text":"Und sogleich nach der Drangsal jener Tage wird sich die Sonne verfinstern, und der Mond wird sein Licht nicht geben, und die Sterne werden vom Himmel fallen, und die Mächte des Himmels werden erschüttert werden."},{"verse":34,"text":"Wahrlich, ich sage euch: Die Generation, in der sich dies alles zeigen wird, wird nicht vergehen, bis alles, was ich euch gesagt habe, sich erfüllen wird."},{"verse":35,"text":"Obschon die Tage kommen werden, da Himmel und Erde vergehen, werden doch meine Worte nicht vergehen, sondern alle werden sich erfüllen."},{"verse":36,"text":"Und, wie ich zuvor gesagt habe, nach der Drangsal jener Tage und nachdem die Mächte der Himmel erschüttert worden sind, dann wird das Zeichen des Menschensohnes am Himmel erscheinen, und dann werden alle Stämme der Erde wehklagen; und sie werden des Menschen Sohn kommen sehen in den Wolken des Himmels, mit Macht und großer Herrlichkeit;"},{"verse":37,"text":"und wer mein Wort wie einen Schatz hütet, wird sich nicht täuschen lassen, denn des Menschen Sohn wird kommen, und er wird seine Engel vor sich hersenden mit lautem Posaunenschall, und sie werden die übrigen seiner Auserwählten sammeln von den vier Winden her, von einem Ende des Himmels zum anderen."},{"verse":38,"text":"Nun lernt ein Gleichnis vom Feigenbaum: Wenn seine Zweige noch zart sind und er anfängt, Blätter sprießen zu lassen, so wisst ihr, dass der Sommer nahe bevorsteht;"},{"verse":39,"text":"so auch meine Auserwählten, wenn sie dies alles sehen, werden sie wissen, dass er nahe ist, ja, vor der Tür;"},{"verse":40,"text":"aber den Tag und die Stunde weiß keiner; nein, auch nicht die Engel Gottes im Himmel, sondern allein mein Vater."},{"verse":41,"text":"Doch wie es in den Tagen Noachs war, so wird es auch sein, wenn des Menschen Sohn kommt;"},{"verse":42,"text":"denn mit ihnen wird es sein, wie es in den Tagen vor der Flut war; denn bis zu dem Tag, da Noach in die Arche ging, aßen und tranken sie, heirateten und wurden verheiratet"},{"verse":43,"text":"und wussten nicht, bis die Flut kam und sie alle hinwegraffte; so wird es auch sein, wenn des Menschen Sohn kommt."},{"verse":44,"text":"Dann wird sich erfüllen, was geschrieben steht, dass in den letzten Tagen zwei auf dem Felde sein werden, der eine wird genommen und der andere gelassen,"},{"verse":45,"text":"zwei werden auf der Mühle mahlen, der eine wird genommen und der andere gelassen;"},{"verse":46,"text":"und was ich zu einem spreche, das spreche ich zu allen Menschen: Darum seid wachsam, denn ihr wisst nicht, zu welcher Stunde euer Herr kommt."},{"verse":47,"text":"Das aber wisset: Wenn der Hausvater gewusst hätte, zu welcher Stunde der Dieb kommt, so hätte er gewacht und hätte nicht zugelassen, dass in sein Haus eingebrochen wird, sondern wäre bereit gewesen."},{"verse":48,"text":"Darum seid auch ihr bereit, denn zu solcher Stunde, da ihr es nicht denkt, kommt des Menschen Sohn."},{"verse":49,"text":"Wer ist nun ein treuer und weiser Diener, den sein Herr über seinen Haushalt hat walten lassen, damit er ihm zur bestimmten Zeit Essen gebe?"},{"verse":50,"text":"Gesegnet ist derjenige Diener, den sein Herr, wenn er kommt, bei solchem Tun finden wird; und wahrlich, ich sage euch: Er wird ihn über alle seine Güter walten lassen."},{"verse":51,"text":"Aber wenn der böse Diener in seinem Herzen sagt: Mein Herr verzögert sein Kommen,"},{"verse":52,"text":"und anfängt, seine Mitbrüder im Dienst zu schlagen und mit den Betrunkenen zu essen und zu trinken,"},{"verse":53,"text":"dann wird der Herr jenes Dieners an einem Tag kommen, da er ihn nicht erwartet, und zu einer Stunde, die er nicht kennt,"},{"verse":54,"text":"und wird ihn in Stücke hauen und wird ihm sein Teil bei den Heuchlern bestimmen; da wird es Weinen und Zähneknirschen geben."},{"verse":55,"text":"Und so kommt das Ende der Schlechten gemäß der Prophezeiung des Mose, nämlich: Sie werden ausgeschlossen werden aus dem Volk; doch das Ende der Erde ist noch nicht, aber bald."}]}]},{"id":"joseph-smith-history","title":"Joseph Smith – Lebensgeschichte","englishTitle":"Joseph Smith-History","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Infolge der vielen Gerüchte, die von übelgesinnten und hinterhältigen Leuten über Entstehung und Fortschritt der Kirche Jesu Christi der Heiligen der Letzten Tage in Umlauf gesetzt worden sind und die alle von ihren Urhebern ersonnen worden sind, um der Kirche als solcher und ihrem Fortschritt in der Welt entgegenzuwirken, habe ich mich veranlasst gesehen, diese Darstellung zu schreiben, um die Öffentlichkeit eines Besseren zu belehren und allen Wahrheitssuchern die Tatsachen über mich und die Kirche so zu vermitteln, wie sie sich zugetragen haben, soweit mir diese Tatsachen zur Verfügung stehen."},{"verse":2,"text":"In dieser Schilderung werde ich die verschiedenen Ereignisse, die auf diese Kirche Bezug haben, in Wahrheit und Rechtschaffenheit darstellen, wie sie sich zugetragen haben oder wie sie gegenwärtig [1838], also im achten Jahr seit der Gründung der genannten Kirche, bestehen."},{"verse":3,"text":"Ich wurde im Jahre unseres Herrn eintausendachthundertfünf geboren, am dreiundzwanzigsten Tag im Dezember, in der Ortschaft Sharon, Kreis Windsor, Staat Vermont. … Mein Vater, Joseph Smith Sr., zog aus dem Staate Vermont weg und übersiedelte nach Palmyra, Kreis Ontario (jetzt Wayne) im Staate New York, als ich etwa in meinem zehnten Lebensjahr stand. Rund vier Jahre nachdem mein Vater nach Palmyra gekommen war, übersiedelte er mit seiner Familie nach Manchester im selben Kreis Ontario –"},{"verse":4,"text":"seine Familie bestand aus elf Seelen, nämlich meinem Vater Joseph Smith, meiner Mutter Lucy Smith (vor ihrer Heirat hieß sie Mack, Tochter des Solomon Mack), meinen Brüdern Alvin (der am 19. November 1823 in seinem sechsundzwanzigsten Lebensjahr starb), Hyrum, mir selbst, Samuel Harrison, William und Don Carlos sowie meinen Schwestern Sophronia, Catherine und Lucy."},{"verse":5,"text":"Im Laufe des zweiten Jahres nach unserer Übersiedlung nach Manchester kam es an unserem Wohnort zu einer ungewöhnlichen Erregung über das Thema Religion. Sie begann bei den Methodisten, breitete sich aber bald unter allen Glaubensgemeinschaften in jener Gegend des Landes aus. Es hatte tatsächlich den Anschein, als sei der ganze Landesteil davon ergriffen, und ganze Scharen schlossen sich den verschiedenen religiösen Parteien an, was nicht wenig Aufregung und Uneinigkeit unter den Leuten verursachte, denn einige schrien: „Siehe hier!“, und andere: „Siehe dort!“ Einige stritten für den Methodistenglauben, andere für den der Presbyterianer, wieder andere für den der Baptisten."},{"verse":6,"text":"Denn wohl bekundeten diejenigen, die sich zu den verschiedenen Glaubensrichtungen bekehrt hatten, zur Zeit ihrer Bekehrung große Liebe, und die betreffenden Geistlichen, die dieses außergewöhnliche Schauspiel religiöser Aufwallung in Szene gesetzt hatten und förderten, zeigten großen Eifer, um jedermann sich bekehren zu lassen, wie sie das zu nennen beliebten, und jeder möge sich der Gemeinschaft anschließen, die ihm zusagte; wenn dann aber die Bekehrten einer nach dem anderen weggingen, die einen zu der einen Partei, die anderen zu einer anderen, da konnte man sehen, dass die scheinbar so guten Gefühle der Priester und auch der Bekehrten mehr vorgetäuscht als wirklich waren; denn es kam zu einer großen Verwirrung und zu bösen Gefühlen – Priester eiferte gegen Priester, Bekehrter gegen Bekehrten, sodass all ihr Wohlwollen füreinander, sofern sie je welches gehabt hatten, in dem Wortkrieg und Meinungsstreit gänzlich unterging."},{"verse":7,"text":"Ich stand damals in meinem fünfzehnten Lebensjahr. Meines Vaters Familie ließ sich für den Glauben der Presbyterianer gewinnen, und ihrer vier schlossen sich dieser Kirche an, nämlich meine Mutter Lucy, meine Brüder Hyrum und Samuel Harrison sowie meine Schwester Sophronia."},{"verse":8,"text":"In dieser Zeit großer Erregung wurde mein Sinn von ernstem Nachdenken und innerer Unruhe bewegt; zwar nahm ich lebhaften Anteil und hatte sehr ausgeprägte Gefühle, aber ich hielt mich doch von allen diesen Parteien fern, wenn ich auch ihre verschiedenen Versammlungen besuchte, sooft sich mir die Gelegenheit bot. Im Laufe der Zeit neigte ich in Gedanken der Gemeinschaft der Methodisten zu, und ich hatte wohl auch den Wunsch, mich ihnen anzuschließen; aber so groß waren die Verwirrung und der Streit zwischen den verschiedenen Konfessionen, dass es für einen jungen Menschen wie mich, der mit Menschen und Dingen wenig Erfahrung hatte, gar nicht möglich war, mit Sicherheit zu entscheiden, wer nun Recht und wer Unrecht hatte."},{"verse":9,"text":"Bisweilen befand sich mein Sinn in heftiger Erregung, so groß war das Geschrei, so unaufhörlich der Tumult. Die Presbyterianer wandten sich aufs heftigste gegen die Baptisten und Methodisten und benutzten alle Verstandeskräfte und Spitzfindigkeiten, um ihnen Irrtümer nachzuweisen oder wenigstens die Leute glauben zu machen, sie seien im Irrtum. Anderseits wiederum waren die Baptisten und Methodisten ebenso eifrig bestrebt, ihre eigenen Lehren durchzusetzen und alle anderen zu widerlegen."},{"verse":10,"text":"Inmitten dieses Wortkriegs und Tumults der Meinungen sagte ich mir oft: Was ist da zu tun? Welche von allen diesen Parteien hat Recht, oder haben sie allesamt Unrecht? Falls eine von ihnen Recht hat, welche ist es, und wie soll ich sie erkennen?"},{"verse":11,"text":"Während ich also mit diesen äußersten Schwierigkeiten zu kämpfen hatte, die durch den Glaubensstreit dieser Religionsparteien ausgelöst worden waren, las ich eines Tages im Jakobusbrief den fünften Vers im ersten Kapitel, der lautet: Fehlt es aber einem von euch an Weisheit, so erbitte er sie von Gott, der allen gern gibt und keine Vorwürfe macht; dann wird sie ihm gegeben werden."},{"verse":12,"text":"Nie ist einem Menschen eine Schriftstelle mit mehr Macht ins Herz gedrungen als diese damals mir. Es war so, als ergieße sie sich mit großer Stärke in jede Regung meines Herzens. Wieder und wieder dachte ich darüber nach, denn ich wusste, wenn überhaupt jemand Weisheit von Gott brauchte, so war ich es; denn wie ich mich verhalten sollte, wusste ich nicht, und solange ich nicht mehr Weisheit erlangte, als ich damals besaß, würde ich es auch nie wissen; denn die Religionslehrer der verschiedenen Glaubensgemeinschaften verstanden ein und dieselbe Schriftstelle so unterschiedlich, dass dadurch alles Vertrauen darauf zerstört wurde, die Frage durch Berufung auf die Bibel zu entscheiden."},{"verse":13,"text":"Endlich kam ich zu dem Schluss, dass ich entweder in Finsternis und Verwirrung bleiben müsse oder dass ich das tun müsse, was Jakobus sagt, nämlich Gott bitten. Ich fasste also endlich den Entschluss, Gott zu bitten, denn ich sagte mir: Wenn er denen Weisheit gibt, denen es an Weisheit fehlt, und wenn er gern gibt und keine Vorwürfe macht, dann durfte ich es wohl wagen."},{"verse":14,"text":"Also zog ich mich gemäß diesem meinem Entschluss, Gott zu bitten, in den Wald zurück, um den Versuch zu machen. Es war an einem strahlend schönen Morgen in den ersten Frühlingstagen achtzehnhundertzwanzig. Zum ersten Mal in meinem Leben unternahm ich so einen Versuch, denn bei all meiner Unruhe hatte ich doch noch nie versucht, laut zu beten."},{"verse":15,"text":"Nachdem ich mich an den Ort zurückgezogen hatte, den ich vorher dazu ausersehen hatte, und mich umblickte und sah, dass ich allein war, kniete ich nieder und fing an, Gott die Wünsche meines Herzens vorzutragen. Kaum hatte ich das getan, wurde ich sogleich von einer Macht gepackt, die mich gänzlich überwältigte und eine so erstaunliche Wirkung auf mich hatte, dass sie mir die Zunge lähmte und ich nicht sprechen konnte. Dichte Finsternis zog sich um mich zusammen, und ich hatte eine Zeit lang das Gefühl, als sei ich plötzlicher Vernichtung anheimgegeben."},{"verse":16,"text":"Ich nahm aber alle Kraft zusammen und rief Gott an, er möge mich aus der Macht dieses Feindes befreien, der mich gepackt hatte; und gerade in dem Augenblick, als ich in Verzweiflung versinken und mich der Vernichtung preisgeben wollte – und nicht etwa einem eingebildeten Verderben, sondern der Macht eines wirklichen Wesens aus der Welt des Unsichtbaren, das eine so unglaubliche Macht hatte, wie ich sie nie zuvor bei irgendeinem Wesen verspürt hatte –, eben in diesem Augenblick höchster Angst sah ich gerade über meinem Haupt, heller als das Licht der Sonne, eine Säule aus Licht, die allmählich herabkam, bis sie auf mich fiel."},{"verse":17,"text":"Kaum war sie erschienen, da fand ich mich auch schon von dem Feind befreit, der mich gebunden gehalten hatte. Als das Licht auf mir ruhte, sah ich zwei Personen von unbeschreiblicher Helle und Herrlichkeit über mir in der Luft stehen. Eine von ihnen redete mich an, nannte mich beim Namen und sagte, dabei auf die andere deutend: Dies ist mein geliebter Sohn. Ihn höre!"},{"verse":18,"text":"Der Grund, warum ich den Herrn befragen wollte, war der, dass ich wissen wollte, welche von allen Glaubensgemeinschaften Recht hätte, damit ich wisse, welcher ich mich anschließen sollte. Sobald ich mich so weit gefasst hatte, dass ich imstande war zu sprechen, fragte ich daher die über mir im Licht stehenden Personen, welche von allen Glaubensgemeinschaften die richtige sei (denn bisher war es noch nie in mein Herz gedrungen, dass alle Unrecht hätten) – und welcher ich mich anschließen solle."},{"verse":19,"text":"Ich bekam die Antwort, ich dürfe mich keiner von ihnen anschließen, denn sie seien alle im Unrecht; und die Person, die zu mir sprach, sagte, ihre sämtlichen Glaubensbekenntnisse seien in seinen Augen ein Gräuel; jene Glaubensbekenner seien alle verdorben, denn „sie nahen sich mir mit den Lippen, aber ihr Herz ist ferne von mir; sie verkünden Menschengebote als Lehre, sie haben zwar eine Form der Gottesfurcht, aber sie leugnen deren Macht“."},{"verse":20,"text":"Nochmals verbot er mir, mich einer von ihnen anzuschließen; und noch vieles andere sagte er mir, was ich zu dieser Zeit nicht niederschreiben kann. Als ich wieder zu mir kam, fand ich mich auf dem Rücken liegen, den Blick zum Himmel gerichtet. Als das Licht verschwunden war, hatte ich keine Kraft; ich erholte mich aber bald so weit, dass ich nach Hause gehen konnte. Und als ich mich gegen den offenen Kamin lehnte, fragte mich die Mutter, was los sei. Ich antwortete: „Schon gut, alles ist in Ordnung, mir ist ganz wohl zumute.“ Dann sagte ich zu meiner Mutter: „Ich habe für mich selbst herausgefunden, dass der Presbyterianerglaube nicht richtig ist.“ Der Widersacher muss wohl schon seit meinen frühen Lebensjahren gewusst haben, dass ich dazu bestimmt war, sein Reich zu stören und zu beunruhigen; warum hätten sich sonst die Mächte der Finsternis gegen mich verbinden sollen? Warum sonst die Gegnerschaft und Verfolgung, die sich gegen mich erhoben, fast noch in meiner Kindheit?"},{"verse":21,"text":"Einige wenige Tage nachdem ich diese Vision gehabt hatte, war ich zufällig mit einem Methodistenprediger beisammen, der während der vorerwähnten religiösen Erregung sehr rührig war; und als ich mich mit ihm über das Thema Religion unterhielt, nahm ich die Gelegenheit wahr und gab ihm einen Bericht von der Vision, die ich gehabt hatte. Ich war von seinem Benehmen sehr überrascht, denn er nahm meine Mitteilung nicht nur geringschätzig auf, sondern sogar mit großer Verachtung: Er sagte, das sei alles vom Teufel, so etwas wie Visionen oder Offenbarungen gebe es in diesen Tagen nicht mehr, das hätte alles mit den Aposteln aufgehört, und es würde so etwas nie wieder geben."},{"verse":22,"text":"Ich musste jedoch bald feststellen, dass ich durch das Erzählen meiner Geschichte bei den Glaubensbekennern sehr viel Vorurteil gegen mich weckte und viel Verfolgung verursachte, die ständig zunahm; und obwohl ich nur ein unbekannter Junge von vierzehn, fünfzehn Jahren war und meine Lebensumstände dergestalt, dass sie so einem Knaben keinerlei Bedeutung in der Welt verschafften, nahmen doch hochstehende Männer von mir so viel Notiz, dass sie die öffentliche Meinung gegen mich aufstachelten und eine erbitterte Verfolgung anzettelten; und das hatten alle Glaubensgemeinschaften gemeinsam – alle vereinigten sich, um mich zu verfolgen."},{"verse":23,"text":"Oft habe ich damals und auch seither ernstlich darüber nachdenken müssen, wie seltsam es doch war: Man hielt einen unbekannten, wenig mehr als vierzehn Jahre alten Jungen, der auch noch dazu verurteilt war, seinen kärglichen Lebensunterhalt von Tag zu Tag durch seine schwere Arbeit zu verdienen, für eine so wichtige Persönlichkeit, dass ihm die Großen der damals am weitesten verbreiteten Glaubensgemeinschaften Aufmerksamkeit schenkten, und zwar auf eine Weise, dass sich in ihnen eine Gesinnung bitterster Verfolgung und Schmähung entwickelte. Aber seltsam oder nicht, so war es, und das hat mir oft großen Kummer verursacht."},{"verse":24,"text":"Aber nichtsdestoweniger war es eine Tatsache, dass ich eine Vision gesehen hatte. Ich habe mir seither oft gedacht, dass mir damals ähnlich zumute war wie Paulus, als er sich vor König Agrippa verteidigte und von der Vision berichtete, die er gehabt hatte, als er ein Licht gesehen und eine Stimme gehört hatte; und doch waren da nur wenige, die ihm glaubten; einige sagten, er sei unehrlich, andere sagten, er sei verrückt; und er wurde verspottet und geschmäht. Aber das alles tat der Wirklichkeit seiner Vision keinen Abbruch. Er hatte eine Vision gesehen; er wusste es, und alle Verfolgung unter dem Himmel konnte nichts daran ändern; und wenn sie ihn bis zum Tod verfolgen sollten, so wusste er doch und würde es bis zum letzten Atemzug wissen, dass er ein Licht gesehen und auch eine Stimme gehört hatte, die zu ihm sprach, und die ganze Welt konnte ihn nicht dazu bringen, etwas anderes zu denken oder zu glauben."},{"verse":25,"text":"So war es auch mit mir. Ich hatte tatsächlich ein Licht gesehen, und mitten in dem Licht hatte ich zwei Personen gesehen, und sie hatten wirklich zu mir gesprochen; und wenn man mich auch hasste und verfolgte, weil ich sagte, ich hätte eine Vision gesehen, so war es doch wahr; und während man mich verfolgte und mich schmähte und mich auf alle mögliche Weise böse verleumdete, weil ich das sagte, musste ich mich im Herzen fragen: Wieso verfolgt man mich, weil ich die Wahrheit sage? Ich habe tatsächlich eine Vision gesehen; und wer bin ich, dass ich Gott widerstehen könnte? Oder warum meint die Welt, sie könne mich dazu bringen, dass ich verleugne, was ich tatsächlich gesehen habe? Denn ich hatte eine Vision gesehen, das wusste ich; und ich wusste, dass Gott es wusste; und ich konnte es nicht leugnen, und ich wagte es auch gar nicht, denn zumindest wusste ich, dass ich damit Gott beleidigen und unter Schuldspruch kommen würde."},{"verse":26,"text":"In meinen Gedanken war ich nun, was die Welt der Glaubensgemeinschaften betraf, zufriedengestellt – ich war nicht verpflichtet, mich irgendeiner von ihnen anzuschließen, sondern sollte so verbleiben, wie ich war, bis mir weitere Weisung zuteilwerden würde. Ich hatte herausgefunden, dass das Zeugnis des Jakobus stimmt – dass jemand, dem es an Weisheit fehlt, Gott darum bitten und erlangen kann, ohne dass ihm Vorwürfe gemacht werden."},{"verse":27,"text":"Ich fuhr fort, meinen täglichen Aufgaben im Leben nachzugehen, und zwar bis zum einundzwanzigsten September eintausendachthundertdreiundzwanzig; während der ganzen Zeit hatte ich von der Hand der Leute aller Klassen, religiösen ebenso wie nichtreligiösen, schwere Verfolgung zu leiden, weil ich auch weiterhin darauf bestand, eine Vision gesehen zu haben."},{"verse":28,"text":"In dem Zeitraum, der zwischen dem Tag lag, da ich die Vision hatte, und dem Jahr achtzehnhundertdreiundzwanzig – weil mir geboten wurde, ich solle mich keiner der Glaubensgemeinschaften jener Tage anschließen, und weil ich noch sehr jung war und von denjenigen verfolgt wurde, die eigentlich hätten meine Freunde sein und mich wohlwollend behandeln sollen, und wenn sie der Meinung waren, ich sei einer Täuschung unterlegen, so hätten sie sich bemühen sollen, mich in passender und liebevoller Weise zurückzugewinnen –, war ich allen möglichen Versuchungen ausgesetzt, und da ich in allen möglichen Kreisen verkehrte, verfiel ich häufig in mancherlei törichte Irrtümer und ließ die Schwachheit der Jugend und menschliche Schwächen erkennen, die, ich muss es leider sagen, mich in mancherlei Versuchungen führten, ungehörig in den Augen Gottes. Wenn ich dieses Geständnis ablege, so darf niemand glauben, ich hätte mich irgendwelcher großen oder bösartigen Sünden schuldig gemacht. Eine Neigung, solche zu begehen, lag nie in meiner Natur. Aber ich war der Leichtfertigkeit schuldig und hielt mich bisweilen in übermütiger Gesellschaft auf usw., was nicht zu der Wesensart passte, die jemand bewahren soll, der wie ich von Gott berufen war. Aber das wird keinen in Erstaunen setzen, der an meine Jugend denkt und mein von Natur aus fröhliches Gemüt kennt."},{"verse":29,"text":"Als Folge all dessen hatte ich oft das Gefühl, ich sei meiner Schwachheit und Unzulänglichkeiten wegen schuldig; dann, am Abend des vorerwähnten einundzwanzigsten Septembers, nachdem ich mich für die Nacht zu meinem Bett begeben hatte, wandte ich mich mit Gebet und Flehen an den allmächtigen Gott, er möge mir alle meine Sünden und Torheiten vergeben, er möge mir aber auch eine Kundgebung zuteilwerden lassen, damit ich wisse, wie mein Stand und meine Stellung vor ihm sei; denn ich vertraute fest darauf, eine göttliche Kundgebung zu erhalten, da ich schon früher eine gehabt hatte."},{"verse":30,"text":"Während ich so dabei war, Gott anzurufen, bemerkte ich, wie in meinem Zimmer ein Licht erschien, das immer stärker wurde, bis es im Zimmer schließlich heller war als am Mittag; gleich darauf wurde an meinem Bett eine Gestalt sichtbar, und der Betreffende stand in der Luft, denn seine Füße berührten den Boden nicht."},{"verse":31,"text":"Er hatte ein loses Gewand von außergewöhnlicher Weiße an. Es war weißer als alles, was ich auf Erden je gesehen hatte; auch glaube ich nicht, dass irgendetwas Irdisches derart gemacht werden kann, dass es so überaus weiß und hell leuchtend erscheint. Seine Hände waren unbedeckt, auch seine Arme bis knapp über dem Handgelenk; ebenso waren seine Füße nackt und auch die Beine bis knapp über den Knöcheln. Sein Haupt und sein Hals waren auch nicht bedeckt. Ich konnte erkennen, dass er außer diesem Gewand keine andere Kleidung trug, denn es war offen, sodass ich seine Brust sehen konnte."},{"verse":32,"text":"Nicht nur sein Gewand war überaus weiß, sondern seine ganze Gestalt war unbeschreiblich herrlich und sein Antlitz leuchtend wie ein Blitz. Im Zimmer war es überaus hell, aber doch nicht so hell wie in seiner unmittelbaren Nähe. Als ich ihn erblickte, fürchtete ich mich zuerst; aber bald verließ mich die Furcht."},{"verse":33,"text":"Er nannte mich beim Namen und sagte zu mir, er sei ein Bote, aus der Gegenwart Gottes zu mir gesandt, und heiße Moroni; Gott habe eine Arbeit für mich zu tun; und mein Name werde bei allen Nationen, Geschlechtern und Sprachen für gut und böse gelten, ja, man werde unter allem Volk sowohl gut als auch böse von ihm sprechen."},{"verse":34,"text":"Er sagte, es sei ein Buch verwahrt, auf Goldplatten geschrieben, darin sei ein Bericht über die früheren Bewohner dieses Erdteils und ihre Herkunft zu finden. Er sagte weiter, darin sei die Fülle des immerwährenden Evangeliums enthalten, wie es der Erretter den Bewohnern vor alters gebracht habe."},{"verse":35,"text":"Bei den Platten seien auch zwei Steine in silbernen Bügeln verwahrt – und diese Steine, an einem Brustschild befestigt, bildeten den sogenannten Urim und Tummim –, und der Besitz und Gebrauch dieser Steine hätten früher, in alter Zeit, jemanden zum „Seher“ gemacht; und Gott habe sie bereitet, damit das Buch übersetzt werden könne."},{"verse":36,"text":"Nachdem er mir dies alles gesagt hatte, begann er, Prophezeiungen aus dem Alten Testament zu zitieren. Zuerst zitierte er aus dem ersten Teil des dritten Kapitels von Maleachi; und er zitierte auch aus dem letzten Teil des Kapitels aus der gleichen Prophezeiung, allerdings mit einer kleinen Abweichung vom Wortlaut unserer Bibeln. Anstatt den neunzehnten Vers so zu zitieren, wie er in unseren Büchern lautet, zitierte er ihn so:"},{"verse":37,"text":"Denn siehe, der Tag kommt, der brennen wird wie ein Ofen; und alle Stolzen, ja, und alle, die Schlechtes tun, werden wie Stoppeln brennen; denn die, die kommen, werden sie verbrennen, spricht der Herr der Heerscharen, sodass ihnen nicht Wurzel noch Zweig gelassen wird."},{"verse":38,"text":"Und weiter zitierte er den vorletzten Vers so: Siehe, ich werde euch das Priestertum durch die Hand des Propheten Elija offenbaren, ehe der große und schreckliche Tag des Herrn kommt."},{"verse":39,"text":"Auch den nächsten Vers zitierte er anders: Und er wird die Verheißungen, die den Vätern gemacht worden sind, den Kindern ins Herz pflanzen, und das Herz der Kinder wird sich ihren Vätern zuwenden. Wenn es nicht so wäre, würde die ganze Erde bei seinem Kommen völlig verwüstet werden."},{"verse":40,"text":"Außer diesen zitierte er das elfte Kapitel von Jesaja und sagte, seine Erfüllung stehe soeben bevor. Er zitierte auch das dritte Kapitel der Apostelgeschichte, den zweiundzwanzigsten und dreiundzwanzigsten Vers, und zwar genauso, wie sie in unserem Neuen Testament stehen. Er sagte, der betreffende Prophet sei Christus, aber der Tag sei noch nicht gekommen, da „diejenigen, die seine Stimme nicht hören wollen, aus dem Volke ausgeschlossen werden sollen“, werde aber bald kommen."},{"verse":41,"text":"Auch das dritte Kapitel von Joël zitierte er, vom ersten Vers bis zum letzten. Er sagte auch, dies sei noch nicht erfüllt, werde es aber bald sein. Und weiter bemerkte er, die Fülle der Anderen werde bald anbrechen. Er zitierte noch viele andere Schriftstellen und gab viele Erklärungen, die hier nicht erwähnt werden können."},{"verse":42,"text":"Weiter sagte er zu mir, wenn ich jene Platten, von denen er gesprochen habe, erhielte – denn die Zeit sei noch nicht gekommen, da sie erlangt werden sollten –, dürfe ich sie keinem Menschen zeigen, auch nicht den Brustschild mit dem Urim und Tummim; nur denen, denen sie zu zeigen mir geboten werde; wenn ich es täte, solle ich vernichtet werden. Während er mit mir über die Platten sprach, wurde meinem Sinn eine Vision eröffnet, in der ich die Stelle sehen konnte, wo die Platten aufbewahrt waren, und zwar so klar und deutlich, dass ich die Stelle wiedererkannte, als ich dorthin kam."},{"verse":43,"text":"Nach dieser Mitteilung sah ich, wie das Licht im Zimmer begann, sich unmittelbar um die Person dessen, der zu mir gesprochen hatte, zusammenzuziehen, und das setzte sich fort, bis es im Zimmer wieder finster war, außer ganz nahe um ihn herum. In diesem Augenblick sah ich gleichsam einen Schacht sich bis in den Himmel öffnen, und der Besucher fuhr in die Höhe auf, bis er ganz verschwunden war; und im Zimmer war es wieder so wie zuvor, ehe das himmlische Licht sich gezeigt hatte."},{"verse":44,"text":"Ich lag da und sann über dieses einzigartige Geschehnis nach und wunderte mich sehr über das, was mir dieser ungewöhnliche Bote gesagt hatte; da, mitten in meinem Nachdenken, bemerkte ich plötzlich, dass es in meinem Zimmer abermals anfing, hell zu werden, und gleichsam im nächsten Augenblick war derselbe Himmelsbote wieder an meinem Bett."},{"verse":45,"text":"Er hob an und sagte mir genau dasselbe, was er mir bei seinem ersten Besuch gesagt hatte, ohne die geringste Abweichung; nachdem er das getan hatte, unterrichtete er mich über große Strafgerichte, die über die Erde kommen würden mit großen Verwüstungen durch Hungersnot, Schwert und Seuche; und diese schmerzlichen Strafgerichte würden in dieser Generation über die Erde kommen. Nachdem er dies mitgeteilt hatte, fuhr er wieder wie zuvor in die Höhe auf."},{"verse":46,"text":"Inzwischen war ich in meinem Sinn so tief beeindruckt, dass mich der Schlaf floh und ich überwältigt dalag, voller Verwunderung über das, was ich gesehen und auch gehört hatte. Wie groß aber war meine Überraschung, als ich denselben Boten wiederum an meinem Bett erblickte und all das wiederholen oder nochmals vortragen hörte, was er mir schon zuvor gesagt hatte, und fügte noch eine Warnung an mich hinzu und sagte, der Satan werde mich (wegen der ärmlichen Verhältnisse in meines Vaters Familie) in Versuchung führen wollen, die Platten zu dem Zweck zu erlangen, reich zu werden. Dies verbot er mir und sagte, wenn ich die Platten erhielte, dürfe ich nichts anderes vor Augen haben, als Gott zu verherrlichen, und dürfe keinen anderen Beweggrund haben als den, sein Reich aufzubauen; sonst würde ich sie nicht bekommen."},{"verse":47,"text":"Nach diesem dritten Besuch fuhr er wieder in den Himmel auf wie zuvor, und mir blieb wieder nichts anderes, als darüber nachzudenken, wie seltsam all das war, was ich soeben erlebt hatte; aber kaum war der Himmelsbote zum dritten Mal von mir aufgefahren, da krähte der Hahn, und ich wurde gewahr, dass es Tag wurde, sodass unsere Unterredungen die ganze Nacht gedauert haben mussten."},{"verse":48,"text":"Kurz darauf erhob ich mich von meinem Bett und ging wie gewöhnlich an die notwendige Tagesarbeit; als ich aber anfangen wollte, wie sonst zu arbeiten, war ich derart erschöpft, dass ich zu nichts fähig war. Mein Vater, der mit mir zusammen arbeitete, bemerkte, dass mit mir etwas nicht in Ordnung war, und schickte mich nach Hause. Ich machte mich auf und wollte zum Haus hingehen; als ich aber den Zaun übersteigen wollte, um das Feld zu verlassen, auf dem wir waren, verließen mich die Kräfte vollends, und ich fiel hilflos zu Boden; und eine Zeit lang war ich gänzlich bewusstlos."},{"verse":49,"text":"Das Erste, woran ich mich erinnern kann, war eine Stimme, die zu mir sprach und mich beim Namen rief. Ich schaute auf und sah den gleichen Boten über meinem Haupt stehen, von Licht umgeben wie zuvor. Noch einmal wiederholte er alles, was er mir in der vergangenen Nacht gesagt hatte, und gebot mir, zu meinem Vater zu gehen und ihm von der Vision und den Geboten, die ich empfangen hatte, zu berichten."},{"verse":50,"text":"Ich gehorchte; ich ging zu meinem Vater auf das Feld zurück und erzählte ihm alles. Er erwiderte mir, es sei von Gott, und sagte mir, ich solle hingehen und tun, was der Bote mir geboten habe. Ich verließ das Feld und ging zu der Stelle, wo nach den Worten des Boten die Platten aufbewahrt waren; und dank der Deutlichkeit der Vision, die ich davon gehabt hatte, erkannte ich die Stelle sofort, als ich dort ankam."},{"verse":51,"text":"Nicht weit von der Ortschaft Manchester, Kreis Ontario, New York, erhebt sich ein Hügel von beträchtlicher Größe und der höchste in der ganzen Umgebung. An der Westseite dieses Hügels, nur wenig unterhalb der Kuppe, lagen die Platten unter einem Stein von beträchtlicher Größe, in einem steinernen Behälter verwahrt. Der Stein war an der Oberseite abgerundet, dick in der Mitte und gegen den Rand hin dünner, sodass der mittlere Teil über dem Erdboden sichtbar war, aber der Rand rundum war in der Erde eingebettet."},{"verse":52,"text":"Nachdem ich die Erde entfernt hatte, suchte ich mir einen Hebel, setzte ihn unter dem Rand des Steines an und hob ihn mit einiger Anstrengung hoch. Ich schaute hinein, und da sah ich tatsächlich die Platten, den Urim und Tummim sowie den Brustschild, wie der Bote es gesagt hatte. Der Behälter, worin sie lagen, war durch Steine gebildet, die mit einer Art Zement aneinandergefügt worden waren. Auf dem Boden des Behälters waren zwei Steine quer zum Behälter gelegt, und auf diesen Steinen lagen die Platten und mit ihnen die anderen Gegenstände."},{"verse":53,"text":"Ich versuchte, sie herauszunehmen, aber der Bote untersagte es; abermals wurde mir gesagt, dass die Zeit, sie hervorzubringen, noch nicht gekommen sei und bis in vier Jahren, von jenem Tag an, auch nicht kommen werde. Er sagte mir aber, ich solle in genau einem Jahr, von jenem Tag an, wieder an jene Stelle kommen und er werde mich dort treffen und ich solle dies so lange fortsetzen, bis die Zeit gekommen sei, da ich die Platten erhalten würde."},{"verse":54,"text":"Ich ging daher, wie mir geboten worden war, immer nach Ablauf eines Jahres dorthin, und jedes Mal fand ich den gleichen Boten dort vor und empfing von ihm bei jeder Unterredung Anweisungen und Auskunft darüber, was der Herr vorhabe und wie und auf welche Weise sein Reich in den letzten Tagen zu leiten sei."},{"verse":55,"text":"Mein Vater lebte in sehr bescheidenen Verhältnissen, und so waren wir genötigt, mit unseren Händen zu arbeiten: Wir verdingten uns im Tagelohn oder auf andere Weise, wie sich uns die Gelegenheit bot. Manchmal waren wir daheim und manchmal auswärts und konnten durch ständige Arbeit einen ausreichenden Lebensunterhalt beschaffen."},{"verse":56,"text":"Im Jahr 1823 wurde meines Vaters Familie durch den Tod Alvins, meines ältesten Bruders, von schwerem Leid betroffen. Im Monat Oktober 1825 verdingte ich mich bei einem alten Herrn namens Josiah Stoal, der im Kreis Chenango, Staat New York, lebte. Er hatte etwas von einer Silbermine gehört, die von den Spaniern in Harmony, Kreis Susquehanna, Staat Pennsylvania, erschlossen worden sei und hatte, ehe ich bei ihm Arbeit annahm, gegraben, um wenn möglich die Mine zu entdecken. Nachdem ich zu ihm gezogen war, ließ er mich mit seinen übrigen Arbeitern nach der Silbermine graben; ich blieb nahezu einen Monat bei dieser Arbeit, ohne dass unser Unternehmen Erfolg hatte, und schließlich konnte ich den alten Herrn dazu bringen, dass er die Grabungen nach ihr einstellte. So entstand die weitverbreitete Fabel, ich sei ein Schatzgräber gewesen."},{"verse":57,"text":"Während der Zeit, da ich auf diese Weise arbeitete, hatte ich einen Kostplatz bei einem Herrn Isaac Hale am gleichen Ort; dort sah ich meine Frau (seine Tochter) Emma Hale zum ersten Mal. Am 18. Januar 1827 wurden wir getraut; ich war zu dieser Zeit noch im Dienst des Herrn Stoal."},{"verse":58,"text":"Weil ich immer wieder darauf bestand, dass ich eine Vision gesehen hatte, eilte mir die Verfolgung immer noch nach, und die Familie des Vaters meiner Frau war sehr dagegen, dass wir heirateten. Ich war darum genötigt, mich mit ihr woanders hinzubegeben; also machten wir uns auf und wurden im Haus des Friedensrichters Tarbill in South Bainbridge, Kreis Chenango, New York, getraut. Sogleich nach der Hochzeit verließ ich Herrn Stoal und zog zu meinem Vater, dem ich während jener Jahreszeit bei der Landarbeit half."},{"verse":59,"text":"Endlich kam der Tag, da ich die Platten, den Urim und Tummim sowie den Brustschild erhalten sollte. Am zweiundzwanzigsten September eintausendachthundertsiebenundzwanzig – wie gewohnt war ich nach Ablauf eines weiteren Jahres an den Ort gegangen, wo sie aufbewahrt waren – übergab derselbe Himmelsbote sie mir mit der folgenden Ermahnung: Ich solle für sie verantwortlich sein; wenn sie mir unbedacht oder durch irgendeine Nachlässigkeit meinerseits abhandenkommen sollten, würde ich von Gott abgeschnitten werden; wenn ich aber alle meine Kräfte dafür einsetzen wolle, sie zu bewahren, bis er, der Bote, sie wieder abhole, würden sie geschützt sein."},{"verse":60,"text":"Bald fand ich heraus, warum ich so strenge Weisung erhalten hatte, sie sicher zu bewahren, und weshalb es so war, dass der Bote gesagt hatte, er werde sie wieder abholen, sobald ich vollbracht hätte, was von meiner Hand gefordert werde. Denn kaum war bekanntgeworden, dass sie sich in meinem Besitz befanden, als auch schon die heftigsten Anstrengungen unternommen wurden, sie mir wegzunehmen. Jede nur erdenkliche List wurde zu diesem Zweck angewandt. Die Verfolgung wurde gehässiger und heftiger als zuvor, und eine Menge Leute waren ständig darauf aus, sie mir wenn möglich wegzunehmen. Aber dank der Weisheit Gottes blieben sie sicher in meiner Hand, bis ich mit ihnen vollbracht hatte, was von meiner Hand gefordert war. Als der Bote, wie vereinbart, sie abholen kam, übergab ich sie ihm, und er hat sie bis zum heutigen Tag, dem zweiten Mai eintausendachthundertachtunddreißig, in seiner Obhut."},{"verse":61,"text":"Die Erregung hielt jedoch weiter an, und das Gerücht mit seinen tausend Zungen war die ganze Zeit emsig dabei, Unwahrheiten über meines Vaters Familie und über mich in Umlauf zu setzen. Wenn ich auch nur den tausendsten Teil davon erzählen wollte, würde es Bücher füllen. Die Verfolgung wurde aber so unerträglich, dass ich genötigt war, aus Manchester wegzugehen und mich mit meiner Frau in den Kreis Susquehanna im Staate Pennsylvania zu begeben. Während der Vorbereitungen zum Aufbruch – wir waren sehr arm, und die Verfolgung machte uns so schwer zu schaffen, dass wenig Aussicht bestand, dass sich unsere Verhältnisse je bessern würden – fanden wir mitten in unseren Bedrängnissen einen Freund in einem Herrn namens Martin Harris, der zu uns kam und mir als Reisehilfe fünfzig Dollar schenkte. Herr Harris wohnte in der Ortschaft Palmyra, Kreis Wayne im Staate New York; er war ein angesehener Landwirt."},{"verse":62,"text":"Dank dieser Hilfe zur rechten Zeit war ich imstande, meinen Bestimmungsort in Pennsylvania zu erreichen; und sofort nach meiner Ankunft dort begann ich, die Schriftzeichen von den Platten abzuschreiben. Ich kopierte eine beträchtliche Anzahl davon, und mit Hilfe des Urim und Tummim übersetzte ich einige; ich tat dies in der Zeit zwischen meiner Ankunft im Haus des Vaters meiner Frau im Monat Dezember und dem darauffolgenden Februar."},{"verse":63,"text":"In diesem Monat Februar kam irgendwann der vorerwähnte Herr Martin Harris zu unserer Wohnstatt, nahm die Schriftzeichen, die ich von den Platten abgezeichnet hatte, an sich und machte sich damit zur Stadt New York auf. Was sich dort in Bezug auf ihn und die Schriftzeichen ereignete, will ich seinem eigenen Bericht über die Umstände entnehmen, wie er ihn mir bei seiner Rückkehr folgendermaßen darlegte:"},{"verse":64,"text":"„Ich ging in die Stadt New York und legte die Schriftzeichen, die übersetzt worden waren, zusammen mit ihrer Übersetzung Professor Charles Anthon vor, einem wegen seiner literarischen Bildung berühmten Mann. Professor Anthon erklärte, die Übersetzung sei richtig, und zwar richtiger als alles, was er bisher an Übersetzungen aus dem Ägyptischen gesehen habe. Dann zeigte ich ihm die noch nicht übersetzten, und er sagte, es seien ägyptische, chaldäische, assyrische und arabische; und er sagte, es seien echte Schriftzeichen. Er gab mir eine Bescheinigung, worin er den Leuten in Palmyra bescheinigte, dass es echte Schriftzeichen seien und dass auch die Übersetzung derer, die bereits übersetzt worden waren, richtig sei. Ich nahm die Bescheinigung und steckte sie in die Tasche und wollte gerade das Haus verlassen, als Herr Anthon mich zurückrief und mich fragte, auf welche Weise denn der junge Mann herausgefunden habe, dass an der Stelle, wo er sie dann gefunden habe, Goldplatten waren. Ich antwortete ihm, dass ein Engel Gottes es ihm offenbart habe."},{"verse":65,"text":"Da sagte er zu mir: ‚Lassen Sie mich die Bescheinigung noch einmal sehen.‘ So nahm ich sie aus der Tasche und gab sie ihm; er nahm sie, zerriss sie und sagte, so etwas wie den Dienst von Engeln gebe es nicht mehr, und wenn ich ihm die Platten brächte, werde er sie übersetzen. Ich teilte ihm mit, dass die Platten teilweise versiegelt seien und dass es mir verboten sei, sie zu bringen. Er entgegnete: ‚Ein versiegeltes Buch kann ich nicht lesen.‘ Ich ging von ihm weg zu Dr. Mitchell, der das bestätigte, was Professor Anthon hinsichtlich der Schriftzeichen und der Übersetzung gesagt hatte.“"},{"verse":66,"text":"Am 5. April 1829 kam Oliver Cowdery in mein Haus; ich hatte ihn nie zuvor gesehen. Er sagte mir, er sei in der Gegend, wo mein Vater wohnte, als Schullehrer tätig gewesen, und da mein Vater zu denen gehörte, die in jene Schule schickten, sei er eine Zeit lang bei ihm im Haus in Kost gewesen; bei dieser Gelegenheit habe ihm die Familie die Umstände erzählt, wie ich die Platten empfangen habe, und so sei er nun gekommen, um sich bei mir darüber zu erkundigen."},{"verse":67,"text":"Zwei Tage nach der Ankunft des Herrn Cowdery (das war am 7. April) begann ich mit der Übersetzung des Buches Mormon, und er fing an, für mich zu schreiben."},{"verse":68,"text":"Wir waren noch immer mit der Übersetzungsarbeit befasst, als wir im darauffolgenden Monat (Mai 1829) eines Tages in den Wald gingen, um zu beten und den Herrn wegen der Taufe zur Sündenvergebung zu befragen, die wir bei der Übersetzung der Platten erwähnt gefunden hatten. Während wir damit beschäftigt waren, zu beten und den Herrn anzurufen, kam ein Bote vom Himmel in einer Lichtwolke herab, legte uns seine Hände auf und ordinierte uns mit den folgenden Worten:"},{"verse":69,"text":"Euch, meinen Mitbrüdern im Dienst, übertrage ich im Namen des Messias das Priestertum Aarons, das die Schlüssel des Dienstes von Engeln und die des Evangeliums der Umkehr und die der Taufe durch Untertauchen zur Sündenvergebung innehat; und es wird nie mehr von der Erde genommen werden, bis die Söhne Levi dem Herrn wieder in Rechtschaffenheit ein Opfer darbringen."},{"verse":70,"text":"Er sagte, dieses Aaronische Priestertum habe nicht die Macht, zur Gabe des Heiligen Geistes die Hände aufzulegen, aber diese werde uns später noch übertragen werden, und er wies uns an, uns gleich taufen zu lassen, und gab uns den Auftrag, ich solle Oliver Cowdery taufen, und danach solle er mich taufen."},{"verse":71,"text":"Demgemäß unterzogen wir uns gleich der Taufe. Zuerst taufte ich ihn, und anschließend taufte er mich – danach legte ich ihm meine Hände auf den Kopf und ordinierte ihn zum Aaronischen Priestertum, und anschließend legte er mir seine Hände auf und ordinierte mich zum selben Priestertum –, denn so war es uns geboten worden.*"},{"verse":72,"text":"Der Bote, der uns aus diesem Anlass besuchte und uns dieses Priestertum übertrug, sagte, er heiße Johannes, der nämliche, der im Neuen Testament Johannes der Täufer genannt werde, und er wirke auf Weisung von Petrus, Jakobus und Johannes; diese hätten die Schlüssel des Priestertums des Melchisedek inne, und dieses Priestertum, so sagte er, werde uns zu gegebener Zeit übertragen werden; und ich solle der Erste Älteste der Kirche genannt werden und er (Oliver Cowdery) der Zweite. Es war am fünfzehnten Mai 1829, dass wir unter der Hand dieses Boten ordiniert wurden und dass wir getauft wurden."},{"verse":73,"text":"Als wir, nachdem wir getauft waren, aus dem Wasser hervorkamen, erlebten wir sogleich große und herrliche Segnungen von unserem himmlischen Vater. Kaum hatte ich Oliver Cowdery getauft, da fiel der Heilige Geist auf ihn und er stand auf und prophezeite vieles, was in Kürze geschehen werde. Und ebenso, sogleich, als ich von ihm getauft worden war, hatte auch ich den Geist der Prophezeiung; ich stand auf und prophezeite über die Entstehung dieser Kirche und vieles andere, was mit der Kirche und dieser Generation der Menschenkinder zusammenhing. Wir waren voll des Heiligen Geistes und freuten uns an dem Gott unserer Errettung."},{"verse":74,"text":"Da unser Verstand nun erleuchtet war, begannen die Schriften für unser Verständnis geöffnet zu werden, und die wahre Bedeutung und Absicht ihrer rätselhafteren Stellen auf eine Weise offenbart zu werden, die wir zuvor nie hatten erreichen können, ja, an die wir bisher überhaupt nicht gedacht hatten. Inzwischen waren wir gezwungen, die Tatsache, dass wir das Priestertum empfangen hatten und getauft worden waren, geheimzuhalten, weil sich in der Nachbarschaft schon ein Geist der Verfolgung bemerkbar gemacht hatte."},{"verse":75,"text":"Es wurde uns von Zeit zu Zeit mit Ausschreitungen des Pöbels gedroht, und dies sogar von Glaubensbekennenden. Und ihre Absichten, gegen uns mit Gewalt vorzugehen, wurden (dank göttlicher Vorsehung) nur durch den Einfluss der Familie des Vaters meiner Frau vereitelt, die zu mir sehr freundlich geworden war und die gegen jeden Pöbel war, die mir auch zugestanden wissen wollte, dass ich die Übersetzungsarbeit ohne Unterbrechung fortsetzen könne, weshalb sie uns anerbot und versprach, uns vor jeder ungesetzlichen Handlung zu schützen, soweit das an ihnen lag."},{"verse":76,"text":"Oliver Cowdery beschreibt diese Ereignisse wie folgt: „Das waren unvergessliche Tage – dazusitzen und einer Stimme lauschen zu dürfen, die unter der Eingebung des Himmels sprach, das erweckte in meinem Herzen tiefste Dankbarkeit! Tag für Tag, ohne Unterbrechung, schrieb ich immerfort nieder, was aus seinem Mund kam, als er mit dem Urim und Tummim oder, wie die Nephiten gesagt hätten, den ‚Übersetzern‘ die Geschichte oder die Aufzeichnungen, nämlich das Buch Mormon, übersetzte."},{"verse":77,"text":"Auf den interessanten Bericht, den Mormon und sein glaubenstreuer Sohn Moroni von einem Volk geben, das einst vom Himmel geliebt und begünstigt wurde, auch nur mit wenigen Worten einzugehen, würde meine gegenwärtigen Absichten übersteigen; daher werde ich das auf eine spätere Zeit verschieben und, wie schon in der Einleitung erwähnt, ohne Umschweife auf einige wenige Ereignisse zu sprechen kommen, die mit der Entstehung dieser Kirche unmittelbar zusammenhängen, was jenen Tausenden zur Freude dienen möge, die unter den finsteren Blicken von Frömmlern und der bösen Nachrede von Heuchlern vorgetreten sind und das Evangelium Christi angenommen haben."},{"verse":78,"text":"Niemand könnte mit nüchternen Sinnen die Weisungen übersetzen und niederschreiben, die der Erretter mit eigenem Mund den Nephiten gegeben hat, die genau darlegen, auf welche Weise die Menschen seine Kirche aufrichten sollen – und besonders zu einer Zeit, da Verdorbenheit über sämtliche von Menschen praktizierten Formen und Systeme Unsicherheit gebracht hat –, ohne zugleich den Wunsch zu haben, die Bereitschaft seines Herzens dadurch zu beweisen, dass er sich ins Wassergrab legen lässt, um ‚ein gutes Gewissen durch die Auferstehung Jesu Christi‘ zu erbitten."},{"verse":79,"text":"Nachdem der Bericht vom Wirken des Erretters unter dem Überrest der Nachkommen Jakobs auf diesem Kontinent niedergeschrieben war, konnte man, wie der Prophet es schon zum Ausdruck gebracht hatte, leicht erkennen, dass Finsternis die Erde bedeckte und tiefe Finsternis den Sinn der Völker. Bei weiterem Nachsinnen konnte man leicht erkennen, dass in dem großen Streit und Lärm um die Religion niemand von Gott bevollmächtigt war, die heiligen Handlungen des Evangeliums zu vollziehen. Denn man darf wohl fragen: Haben Menschen, welche Offenbarungen leugnen, die Vollmacht, im Namen Christi zu handeln, wo doch sein Zeugnis nichts weniger ist als der Geist der Prophezeiung und seine Religion sich zu allen Zeitaltern der Welt, wo es das Gottesvolk auf Erden gegeben hat, auf unmittelbare Offenbarungen gegründet hat und durch diese aufgebaut und genährt wird? Wenn diese Tatsachen vergraben und sorgfältig versteckt waren, und zwar von Männern, deren Machenschaften in Gefahr geraten wären, wenn man die Wahrheit auch nur einmal den Menschen ins Gesicht hätte leuchten lassen, so war das doch für uns nicht mehr der Fall, und wir warteten nur darauf, dass das Gebot ergehe: ‚Steht auf und lasst euch taufen!‘"},{"verse":80,"text":"Dieser Wunsch ging bald in Erfüllung. Der Herr, reich an Gnade und immer willens, das beständige Gebet der Demütigen zu erhören, ließ sich herab, uns seinen Willen kundzutun, nachdem wir ihn, fern von den Wohnstätten der Menschen, inbrünstig angerufen hatten. Ganz plötzlich, wie mitten aus der Ewigkeit, sprach uns die Stimme des Erlösers Frieden zu, während der Schleier geteilt ward und der Engel Gottes herabkam, angetan mit Herrlichkeit, und uns die sehnlich erwartete Botschaft überbrachte sowie die Schlüssel des Evangeliums der Umkehr. Welche Freude! Welches Erstaunen! Welche Verwunderung! Während die Welt sich quälte und in Unruhe war, während Millionen umhertappten wie ein Blinder nach der Mauer und während alle Menschen insgesamt der Unsicherheit ausgeliefert waren, sahen unsere Augen, hörten unsere Ohren wie am hellsten Tag, ja, mehr noch, heller als der Glanz der Maiensonne, die damals ihre Strahlen über das Antlitz der Natur ergoss! Dann drang uns seine Stimme, sanft zwar, bis ins Innerste, und seine Worte ‚Ich bin euer Mitbruder im Dienst‘ zerstreuten alle Furcht. Wir horchten, wir staunten, wir bewunderten! Es war die Stimme eines Engels aus der Herrlichkeit, es war eine Botschaft des Allerhöchsten! Und im Hören frohlockten wir, während seine Liebe in unserer Seele entbrannte und wir von der Vision des Allmächtigen umfangen waren! Wo war da noch Platz für Zweifel? Nirgends; die Unsicherheit war entflohen, der Zweifel war dahingesunken und konnte sich nie mehr erheben, während Trug und Schein für immer geflohen waren!"},{"verse":81,"text":"Aber, lieber Bruder, überlege, überlege noch einen Augenblick lang, welche Freude unser Herz erfüllte und mit welcher Überraschung wir uns wohl niederbeugten (denn wer hätte nicht das Knie gebeugt für solch eine Segnung?), als wir unter seiner Hand das Heilige Priestertum empfingen und er sagte: ‚Euch, meinen Mitbrüdern im Dienst, übertrage ich im Namen des Messias dieses Priestertum und diese Vollmacht, die auf Erden verbleiben sollen, damit die Söhne Levi dem Herrn doch wieder ein Opfer darbringen können in Rechtschaffenheit!‘"},{"verse":82,"text":"Ich will nicht versuchen, dir die Gefühle meines Herzens auszumalen, auch nicht die majestätische Schönheit und Herrlichkeit, wovon wir damals umgeben waren; aber du wirst mir glauben, wenn ich sage, dass weder die Erde noch der Mensch mit der Beredsamkeit aller Zeiten auch nur beginnen kann, etwas so aufschlussreich und erhebend in Worte zu kleiden, wie dieses heilige Wesen. Nein, und die Erde vermag auch nicht, die Freude zu geben und den Frieden zu schenken oder die Weisheit zu erfassen, die in jedem Satz enthalten waren, der mit der Macht des Heiligen Geistes ausgesprochen wurde! Der Mensch mag seine Mitmenschen täuschen, und eine Täuschung mag auf die andere Täuschung folgen, und die Kinder des Bösen mögen die Macht haben, die Törichten und Unbelehrten zu verführen, bis nichts als Schein die Menge speist und die Frucht der Unwahrheit wie ein Strom die Schwankenden ins Grab trägt – aber eine einzige Berührung mit dem Finger seiner Liebe, ja, ein einziger Strahl der Herrlichkeit aus der höheren Welt oder nur ein Wort aus dem Mund des Erretters, aus dem Schoß der Ewigkeit, lässt alles zur Bedeutungslosigkeit schrumpfen und löscht es für immer aus unserem Sinn. Die Gewissheit, dass wir in der Gegenwart eines Engels waren, das sichere Bewusstsein, dass wir die Stimme Jesu gehört hatten und die ungetrübte Wahrheit, wie sie nach Gottes Weisung von einem reinen Wesen strömte – das zu beschreiben, fehlen mir die Worte, und ich werde immer voll Verwunderung und Dankbarkeit auf diese Kundgebung der Güte unseres Erretters blicken, solange es mir vergönnt ist, zu verweilen; und in jenen Wohnungen, wo die Vollkommenheit weilt und die Sünde niemals Einlass findet, hoffe ich an dem nie endenden Tag anbeten zu dürfen.“ – Messenger and Advocate, Band 1 (Oktober 1834), Seite 14ff."}]}]},{"id":"articles-of-faith","title":"Glaubensartikel","englishTitle":"Articles of Faith","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Wir glauben an Gott, den ewigen Vater, und an seinen Sohn, Jesus Christus, und an den Heiligen Geist."},{"verse":2,"text":"Wir glauben, dass der Mensch für seine eigenen Sünden bestraft werden wird und nicht für die Übertretung Adams."},{"verse":3,"text":"Wir glauben, dass durch das Sühnopfer Christi alle Menschen errettet werden können, indem sie die Gesetze und Verordnungen des Evangeliums beachten."},{"verse":4,"text":"Wir glauben, dass die ersten Grundsätze und Verordnungen des Evangeliums sind: erstens der Glaube an den Herrn Jesus Christus; zweitens die Umkehr; drittens die Taufe durch Untertauchen zur Sündenvergebung; viertens das Händeauflegen zur Gabe des Heiligen Geistes."},{"verse":5,"text":"Wir glauben, dass man durch Prophezeiung und das Händeauflegen derer, die Vollmacht dazu haben, von Gott berufen werden muss, um das Evangelium zu predigen und seine heiligen Handlungen zu vollziehen."},{"verse":6,"text":"Wir glauben an die gleiche Organisation, wie sie in der Urkirche bestanden hat, nämlich Apostel, Propheten, Hirten, Lehrer, Evangelisten und so weiter."},{"verse":7,"text":"Wir glauben an die Gabe der Zungenrede, Prophezeiung, Offenbarung, der Visionen, der Heilung, Auslegung der Zungenrede und so weiter."},{"verse":8,"text":"Wir glauben, dass die Bibel, soweit richtig übersetzt, das Wort Gottes ist; wir glauben auch, dass das Buch Mormon das Wort Gottes ist."},{"verse":9,"text":"Wir glauben alles, was Gott offenbart hat, und alles, was er jetzt offenbart; und wir glauben, dass er noch viel Großes und Wichtiges offenbaren wird, was das Reich Gottes betrifft."},{"verse":10,"text":"Wir glauben an die buchstäbliche Sammlung Israels und die Wiederherstellung der Zehn Stämme, dass Zion (das Neue Jerusalem) auf dem amerikanischen Kontinent errichtet werden wird, dass Christus persönlich auf der Erde regieren wird und dass die Erde erneuert werden und ihre paradiesische Herrlichkeit empfangen wird."},{"verse":11,"text":"Wir beanspruchen das Recht, den allmächtigen Gott zu verehren, wie es uns das eigene Gewissen gebietet, und gestehen allen Menschen das gleiche Recht zu, mögen sie verehren, wie oder wo oder was sie wollen."},{"verse":12,"text":"Wir glauben, dass es recht ist, einem König, Präsidenten, Herrscher oder Vertreter der Staatsmacht untertan zu sein und das Gesetz zu beachten, zu ehren und für es einzutreten."},{"verse":13,"text":"Wir glauben, dass es recht ist, ehrlich, treu, keusch, gütig und tugendhaft zu sein und allen Menschen Gutes zu tun; ja, wir können sagen, dass wir der Ermahnung des Paulus folgen – wir glauben alles, wir hoffen alles, wir haben viel ertragen und hoffen, alles ertragen zu können. Wenn es etwas Tugendhaftes oder Liebenswertes gibt, wenn etwas guten Klang hat oder lobenswert ist, so trachten wir danach."},{"verse":14,"text":"Joseph Smith."}]}]}]'),i={language:"deu",sourceLanguage:"deu",sourcePage:e,books:n};export{i as r};
